{
	vector<int> p(s.size());
	int k = 0;
	for (int i = 1; i < s.size(); ++i)
	{
		while (k && s[i] != s[k])
		{
			k = p[k - 1];
		}
		k += (s[i] == s[k]);
		p[i] = k;
	}
	return p;
