                flag = true;
                break;
            }
        }
        if (flag)continue;
        table[pattern.length()] = pattern.length() - 1 - i;
        return;
    }
    table[pattern.length()] = pattern.length() - 2;
}

int Gcd(int a, int b) {
    if (b == 0)return a;
    return Gcd(b, a % b);
}

