        for (ll v : g[u]) {
            if (chmin(dp[v], dp[u]+1)) {
                q.push_back(v);
            }
        }
    }

    ll ans = 0;
    REP(i, ns) {
        if (dp[i] < INF) {
            chmax(ans, dp[i]);
        }
    }
