// Math
inline constexpr ll gcd(const ll a, const ll b) {
    return b ? gcd(b, a % b) : a;
}
inline constexpr ll lcm(const ll a, const ll b) { return a / gcd(a, b) * b; }

inline constexpr ll modulo(const ll n, const ll m = MOD) {
    ll k = n % m;
    return k + m * (k < 0);
}
inline constexpr ll chmod(ll &n, const ll m = MOD) {
    n %= m;
    return n += m * (n < 0);
}
inline constexpr ll mpow(ll a, ll n, const ll m = MOD) {
    ll r = 1;
    rep(i, 64) {
        if (n & (1LL << i)) r *= a;
        chmod(r, m);
        a *= a;
        chmod(a, m);
    }
    return r;
}
inline ll inv(const ll n, const ll m = MOD) {
    ll a = n, b = m, x = 1, y = 0;
    while (b) {
        ll t = a / b;
        a -= t * b;
        swap(a, b);
        x -= t * y;
        swap(x, y);
    }
    return modulo(x, m);
}

struct Z_algorithm {
    string S;
    vector<ll> Z;
    Z_algorithm(string S) : S(S), Z(S.size()) {
        ll mem = 0;
        for (ll i = 1; i < S.size(); i++) {
            if (mem + Z[mem] > i and i - mem + Z[i - mem] < Z[mem]) {
                Z[i] = Z[i - mem];
            } else {
                ll j = max(mem + Z[mem], i);
                while (j < S.size() and S[j - i] == S[j]) j++;
                Z[i] = j - i;
                mem = i;
            }
        }
        if (S.size() >= 1) Z[0] = S.size();
    }
    ll prefix(ll t) { return Z[t]; }
};

