int repcount(string s, string t){
    string t2;
    t2.reserve(s.length());
    int lower = 0;
    int upper = s.length() / t.length() + 1;
    int mid;
    for(int i = 0; i < upper; i++) t2.append(t);
    char t2s[t2.length() + 1];
    strcpy(t2s, t2.c_str());
    do{
        mid = (upper + lower + 1) / 2;
        t2s[mid * t.length()] = '\0';
        int pos = s.find(t2s);
        t2s[mid * t.length()] = t2[0];
        // cout << s << " " << t2 << " " << pos << endl;
        // cout << lower << " " << upper << endl;
        if(pos == -1) upper = mid - 1;
        else lower = mid;
    }while(upper != lower);
    return lower;
}

