        sh2 = (sh2 * b2 + (s[i] - 'a')) % h2;
        sh3 = (sh3 * b3 + (s[i] - 'a')) % h3;
    }
    int num[n-m+1];
    rep(i, n-m+1) num[i] = 0;
    if(sh1 == th1 && sh2 == th2 && sh3 == th3) ++num[0];
    lint p1 = powmod(b1, m, h1);
    lint p2 = powmod(b2, m, h2);
    lint p3 = powmod(b3, m, h3);
    rep(i, n-m+1){
        sh1 = (sh1 * b1 % h1 - p1 * (s[i] - 'a') % h1 + (s[i+m] - 'a') + h1) % h1;
        sh2 = (sh2 * b2 % h2 - p2 * (s[i] - 'a') % h2 + (s[i+m] - 'a') + h2) % h2;
        sh3 = (sh3 * b3 % h3 - p3 * (s[i] - 'a') % h3 + (s[i+m] - 'a') + h3) % h3;
        if(sh1 == th1 && sh2 == th2 && sh3 == th3) ++num[i+1];
    }
    rep(i, u.size()){
        if(num[i]) G[i].push_back((i+m)%u.size());
        d[i] = -1;
    }
    rep(i, u.size()) dfs(i);
    int ans = 0;
    rep(i, u.size()) ans = max(ans, d[i]);
    printf("%d\n", ans);
}

