struct Z_algorithm
{
    vector< int > prefix;

    void build(const string &s)
    {
    prefix.assign(s.size(), 0);
    for(int i = 1, j = 0; i < s.size(); i++) {
        if(i + prefix[i - j] < j + prefix[j]) {
            prefix[i] = prefix[i - j];
        } else {
            int k = max(0, j + prefix[j] - i);
            while(i + k < s.size() && s[k] == s[i + k]) ++k;
            prefix[i] = k;
            j = i;
        }
    }
    prefix[0] = (int) s.size();
    }

    int operator[](const int k) const
    {
    return (prefix[k]);
    }

    size_t size()
    {
    return(prefix.size());
    }
};
struct TopologicalSort{
    int n;
    vector<set<int> > G;
    vector<bool> used;
    vector<int> indeg,p;

    TopologicalSort(){}
    TopologicalSort(int sz):n(sz),G(n),used(n),indeg(n),p(0){}

    void add_edge(int s,int t){
        G[s].insert(t);
    }

    void bfs(int s){
        queue<int> q;
        q.push(s);
        used[s]=1;
        while(!q.empty()){
            int v=q.front();q.pop();
            p.push_back(v);
            for(int u:G[v]){
                indeg[u]--;
                if(indeg[u]==0&&!used[u]){
                    used[u]=1;
                    q.push(u);
                }
            }
        }
    }

    vector<int>  build(){
        fill(used.begin(),used.end(),0);
        fill(indeg.begin(),indeg.end(),0);

        for(int i=0;i<n;i++)
            for(int v:G[i]) indeg[v]++;

        for(int i=0;i<n;i++)
            if(indeg[i]==0&&!used[i]) bfs(i);

        return p;
    }
};
