int Check()
{
	int c1=1,c2=1;
	FOR(i,1,n) if (s[i]!=s[1]) c1=0;
	FOR(i,1,m) if (t[i]!=s[1]) c1=0;
	if (m%n!=0&&n%m!=0) c2=0;
	if (m%n==0)
		FOR(i,1,m) if (t[i]!=s[Get(i,n)]) c2=0;
	if (n%m==0)
		FOR(i,1,n) if (s[i]!=t[Get(i,m)]) c2=0;
	return c1||c2;
}
int ok(int k)
{
	mem(f,0);
	mem(nxt,0);
	int j;
	j=0;
	for (int i=2;i<=k*m;i++)
	{
		while (j>0&&t[j+1]!=t[i]) j=nxt[j];
		if (t[j+1]==t[i]) j++;
		nxt[i]=j;
	}
	j=0;
