// 蟻本でみた、ローリングハッシュを試してみる
vector<bool> check_eq(string s, string t) {
  int s_size = s.size();
  int t_size = t.size();
  vector<bool> result(s_size);
  unsigned long long b = 100000007;
  unsigned long long bn = 1;
  unsigned long long s_hash = 0;
  unsigned long long t_hash = 0;

  for (int i = 0; i < t_size; i++) {
    bn *= b;
  }

  for(const char& c : t) {
    t_hash = t_hash * b + c;
  }

  for(int start = 0; start < s_size + t_size - 1; start++) { // ループして反映するので、終了条件がちょっと違う
    int end = start - t_size + 1;
    s_hash = s_hash * b + s[start%s_size];
    if (start < t_size-1) {
      // hashに使う長さがt_sizeに達するまでは使用できない
      continue;
    }

    if (end > 0) {
      // hashに使う長さがt_sizeを超えたら先頭を削除
      s_hash -= s[end-1] * bn;
    }

    result[end] = s_hash == t_hash;
  }

  return result;
}

int main() {
  string s,t,s_origin;
  cin >> s >> t;
  s_origin = s;

  while(s.size() < t.size()) {
    s += s_origin;
  }

  vector<bool> eqs = check_eq(s,t);

  int max_length = 0;
  int s_size = s.size();
  int t_size = t.size();
  vector<int> length(s_size, -1);

  for (int i = 0; i < s_size; i++) {
    if (length[i] != -1) {
      continue;
    }

    if (!eqs[i]) {
      length[i] = 0;
      continue;
    }

    int current = i;
    int diff = 0;
    queue<int> q;
    while(eqs[current]) {
      if (length[current] != -1) {
        diff = length[current]; // すでに到達済みの場合、計算済みの長さを加えて終了する
        break;
      }
      length[current] = 0; // 一旦到達マーク設定
      q.push(current);
      current = (current + t_size) % s_size;
    }

    max_length = max(max_length, diff + (int)q.size());

    while(!q.empty()) {
      int len = q.size();
      int current = q.front();
      q.pop();
      length[current] = len + diff; // 正確な長さで上書き
    }
  }

  if (max_length > 0 && (max_length * t_size) % s_size == 0) {
    max_length = -1; // 無限に一致する
  }
  cout << max_length << endl;

  return 0;
}

