// https://kopricky.github.io/code/String/kmp.html
// res に文字列 text の中にある検索文字列 pattern のすべての一致箇所の開始位置が入る(0_indexed).
class KMP
{
public:
    string pattern;
    int plen;
    vector<int> table;

    KMP(const string& s) : pattern(s), plen((int)pattern.size()), table(plen+1) {
        table[0] = -1;
        int j = -1;
        for (int i = 0; i < plen; i++) {
            while (j >= 0 && pattern[i] != pattern[j]) j = table[j];
            if (pattern[i+1] == pattern[++j]) table[i+1] = table[j];
            else table[i+1] = j;
        }
    }

    void search(const string& text, vector<int>& res) {
        int head = 0, j = 0, tlen = (int)text.size();
        while (head + j < tlen){
            if (pattern[j] == text[head + j]) {
                if (++j != plen) continue;
                res.push_back(head);
            }
            head += j - table[j], j = max(table[j], 0);
        }
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    string s, t;
    cin >> s >> t;
    string s2 = "";
    while (s2.size() < t.size()) s2 += s;
    string s3 = s2 + s2 + s2 + s2;
    KMP kmp(t);
    vector<int> ids;
    kmp.search(s3, ids);

    if (ids.empty()) {
        cout << 0 << endl;
        return 0;
    }

    vector<int> memo(s3.size(), -1);
    for (int i = 0; i < ids.size(); i++) memo[ids[i]] = i;

    int n = s.size();
    int m = t.size();
    vector<int> used(ids.size(), false);
    int ans = 0;
    for (int i = 0; i < ids.size(); i++) {
        if (used[i]) continue;
        used[i] = true;
        int src = ids[i];
        int dst = src;
        for (int j = src + m; j < s3.size(); j += m) {
            if (memo[j] == -1) break;
            dst = j;
            used[memo[j]] = true;
        }

        int hoge = n - src % n;
        int foo = dst % n + 1;
        int dis = dst - src + m;
        int rest = dis - hoge - foo;
        if (rest >= n) {
            cout << -1 << endl;
            return 0;
        } else {
            ans = max(ans, dis / m);
        }
    }
    cout << ans << endl;
    return 0;
}

