template<class T>class RollingHash {
	int n; T base;
	vector<T> pow, hash;
public:
	RollingHash(const string& s, T b = 10007) :n(s.size()), base(b), pow(n + 1), hash(n + 1) {
		pow[0] = 1; hash[0] = 0;
		for (int i = 0; i < n; ++i) {
			pow[i + 1] = pow[i] * base;
			hash[i + 1] = (T(s[i]) + hash[i] * base);
		}
	}
	// [0, r)
	T operator()(int r)const {
		return hash[r];
	}
	// [l, r)
	T operator()(int l, int r)const {
		return operator()(r) - operator()(l) * pow[r - l];
	}
};
using RH = RollingHash<unsigned long long>;

int main() {
	string s = in, t = in;
	string S = s * Age(sz(t), sz(s)); // sz(S) >= sz(t) 
	S = S * 5;

	RH rh_S(S, 12345);

	auto check = [&](int n) {
		string T = t * n;
		RH rh_T(T, 12345);
		rep(i, sz(S) - sz(T) + 1) {
			if (rh_S(i, i + sz(T)) == rh_T(sz(T))) {
				return true;
			}
		}
		return false;
	};

	if (check(sz(S) / sz(t) - 1)) {
		out.exit(-1);
	} else if (!check(1)) {
		out.exit(0);
	}

	int ok = 0, ng = sz(S) / sz(t) + 1;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		(check(mid) ? ok : ng) = mid;
	}
	out(ok);
}

