int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  string s, t;
  cin >> s >> t;
  vector<bool> match(s.size() * 2);
  int u = 0;
  auto pre = kmp(t);
  rep(i, s.size() * 2) {
    while (u != -1 && t[u] != s[i % s.size()]) u = pre[u];
    u++;
    if (u == t.size()) {
      match[i+1 - t.size()] = true;
    }
  }
  vector<vector<int>> g(s.size());
  vector<int> deg(s.size());
  rep(i, s.size()) {
    if (match[i]) {
      int j = (i + t.size()) % s.size();
      g[i].push_back(j);
      deg[j]++;
    }
  }
  queue<int> q;
  rep(i, s.size()) {
    if (deg[i] == 0) {
      q.push(i);
