        while(i<m){
            while(j>-1 && x[i]!=x[j]) j = kmpnext[j];
            i++; j++;
            if(x[i]==x[j]) kmpnext[i] = kmpnext[j];
            else kmpnext[i] = j;
        }
    };
    auto KMP = [&](string x,int m,string y,int n){
        int i = 0,j = 0;
        prekmp(x,m);
        while(j<n){
            while(i>-1 && x[i]!=y[j]) i = kmpnext[i];
            i++; j++;
            if(i>=m){
//                cerr << j-i << " " << (j-i+x.size())%N << endl;
                v[(j-i)%N].push_back((j-i+x.size())%N);
                i = kmpnext[i];
            }
        }
    };
    KMP(T,M,SS,SS.size());
    vector<int> vis(N+1,0);
    function<bool(int)> dfs = [&](int n){
        vis[n] = -1;
        bool ok = true;
        for(auto x:v[n]){
            if(vis[x]==0) ok &= dfs(x);
            else if(vis[x]==-1) return false;
        }
        vis[n] = 1;
        return ok;
    };
    for(int i=0;i<N;i++){
        if(vis[i]==0){
            if(!dfs(i)){
                cout << -1 << endl;
                return 0;
            }
        }
    }
    vector<int> u;
    for(int i=0;i<N;i++) vis[i] = 0;
    function<void(int)> topso = [&](int n){
        vis[n] = 1;
        for(auto x:v[n]) if(!vis[n]) topso(x);
        u.push_back(n);
    };
    for(int i=0;i<N;i++) if(!vis[i]) topso(i);
    reverse(u.begin(),u.end());
    vector<int> d(N+1,0);
    function<int(int)> dfs2 = [&](int n){
        vis[n] = 1;
        d[n] = 1;
        for(auto x:v[n]){
            if(!vis[x] && !v[x].empty()) d[n] = max(d[n],dfs2(x)+1);
            else if(vis[x]==1) d[n] = max(d[n],d[x]+1);
        }
        return d[n];
    };
    for(int i=0;i<N;i++) vis[i] = 0;
    for(auto x:u){
        if(!vis[x] && !v[x].empty()) dfs2(x);
    }
    int ans = 0;
    for(int i=0;i<N;i++) ans = max(ans,d[i]);
    cout << ans << endl;
}

