                cout << -1 << endl;
                return 0;
            }
            else if(sindex[pre] && !visited[pre]){
                sum++;
                visited[pre] = true;
            }
            else{
                break;
            }
        }

        chmax(ans, sum);
    }

    cout << ans << endl;
