    for (int i = 0; i < s.size(); i++) hash[0][i + 1] = (hash[0][i] * b + s[i]) % h1;
    for (int i = 0; i < s.size(); i++) hash[1][i + 1] = (hash[1][i] * b + s[i]) % h2;
    for (int i = 0; i < s.size(); i++) hash[2][i + 1] = (hash[2][i] * b + s[i]) % h3;
}

bool check_equal(vector<vector<long long>> &hash_s, vector<vector<long long>> &hash_t, int &x, int &x_length){
    int cnt = 0;
    if (hash_s[0].back() == (hash_t[0][x + x_length] - hash_t[0][x] * modpow(b, x_length, h1) % h1 + h1) % h1) cnt++;
    if (hash_s[1].back() == (hash_t[1][x + x_length] - hash_t[1][x] * modpow(b, x_length, h2) % h2 + h2) % h2) cnt++;
    if (hash_s[2].back() == (hash_t[2][x + x_length] - hash_t[2][x] * modpow(b, x_length, h3) % h3 + h3) % h3) cnt++;
    if (cnt == 3) return true;
    return false;
}

vector<int> root;
vector<int> ranks;

int find(int x){
    if (root[x] == x) return x;
    root[x] = find(root[x]);
    return root[x];
}

bool check(int x, int y){
    return find(x) == find(y);
}

bool Union(int x, int y){
    x = find(x);
    y = find(y);
    if (x == y) return false;
    if (ranks[x] >= ranks[y]) root[y] = x;
    else root[x] = y;
    if (ranks[x] == ranks[y]) ranks[x]++;
    return true;
}

