void Z_algo(string &S, vector<int> &v) {
    int N = S.size();
    v = vector<int>(N, 0);
    v[0] = N;
    int i = 1, j = 0;
    while (i < N) {
        while (i+j < N && S[j] == S[i+j]) {
            j++;
        }
        v[i] = j;
        //cout << i << " " << j << endl;
        int k = 1;
        while (i+k < N && k+v[k] < v[i]) {
            v[i+k] = v[k];
            k++;
        }
        i += k;
        j = max(j-k, 0);
    }

    return;
}

int main() {
    string s, t;
    cin >> s >> t;
    int N = s.size(), M = t.size();

    string u = t;
    u += "$";
    for (int i = 0; i < (2*M+N)/N; i++) {
        u += s;
    }
    vector<int> table;
    Z_algo(u, table);

    vector<int> pre(N);
    for (int i = 0; i < N; i++) {
        pre[i] = table[M+1+i];
    }

    vector<bool> use(N, false);
    int ans = 0;
    for (int i = 0; i < N; i++) {
        if (use[i]) continue;
        if (pre[i] == M) {
            continue;
        }
        use[i] = true;
        int j = (i+M)%N;
        while (j != i && pre[j] < M && !use[j]) {
            use[j] = true;
            j += M;
            j %= N;
        }
        if (j == i) continue;
        int cnt = 0;
        while (j != i && pre[j] == M && !use[j]) {
            cnt++;
            use[j] = true;
            j += M;
            j %= N;
        }
        ans = max(ans, cnt);
    }
    if (count(use.begin(), use.end(), true) != N) {
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;

    return 0;
}

