template<class T,uint mod>
struct RollingHash_{
	vector< uint > hashed, power;

	inline uint mul(uint a, uint b){
		return a*(unsigned long long)b%mod;
	}
	RollingHash_(){}
	RollingHash_(T s, uint base = 10007) {
		int sz = (int) s.size();
		hashed.assign(sz + 1, 0);
		power.assign(sz + 1, 0);
		power[0] = 1;
		for(int i = 0; i < sz; i++) {
			power[i + 1] = mul(power[i], base);
			hashed[i + 1] = mul(hashed[i], base) + s[i];
			if(hashed[i + 1] >= mod) hashed[i + 1] -= mod;
		}
	}

	uint get(int l, int r){
		uint ret = hashed[r] + mod - mul(hashed[l], power[r - l]);
		if(ret >= mod) ret -= mod;
		return ret;
	}
};

typedef pair<uint,uint>Hash;

template<class T>
struct RollingHash{
	RollingHash_<T,998244353>RH1;
	RollingHash_<T,1000000007>RH2;

	RollingHash(T s){
		RH1=RollingHash_<T,998244353>(s);
		RH2=RollingHash_<T,1000000007>(s);
	}

	Hash get(int l,int r){
		return make_pair(RH1.get(l,r),RH2.get(l,r));
	}
};

