void getFail() {
    int m = P.length();
    f[0] = 0; f[1] = 0;
    for(int i = 1; i < m; i++){
        int j = f[i];
        while(j && P[i]!=P[j]) j = f[j];
        f[i+1] = P[i] == P[j]? j+1 : 0;
    }
}

void find() {
    int n = T.length(), m = P.length();
    getFail();
    int j = 0;
    for(int i = 0; i < n; i++) {
        while(j && P[j]!=T[i]) j = f[j];
        if(P[j] == T[i]) j++;
        if(j == m) g[(i-m+1)%cs].push_back((i+1)%cs);
    }
}

int c[N], d[N] = {0}, ans = 0;
bool dfs(int u) {
	c[u] = -1;
	for(int i = 0; i < g[u].size(); i++) {
        int v = g[u][i];
		if(c[v] < 0) return false;
		else if(!c[v]&&!dfs(v)) return false;
		d[u] = max(d[u], d[v]);
	}
	d[u]++;
	ans = max(ans, d[u]);
	c[u] = 1;
	return true;
}

bool toposort(){
	memset(c, 0, sizeof(c));
	for(int u = 0; u < N; u++) if(!c[u])
        if(!dfs(u)) return false;
	return true;
}

