void search_hash(string s0,string s1,vector<bool> &v){
    ll l0 = s0.size(),l1 = s1.size();
    ll h0 = 0,h1 = 0,bp = mpow(b,s1.size());

    if(l0<l1) return ;

    for(int i = 0;i < l1;i ++){
        h0 = (h0*b+s0[i])%mod;
        h1 = (h1*b+s1[i])%mod;
    }
    for(int i = 0;i+l1 <= l0;i ++){
        if(h0==h1)          v[i] = true;
        if(i+l1<s0.size())  h0 = (h0*b+s0[i+l1]-s0[i]*bp%mod+mod)%mod;
    }
}

