ll calc_longest(ll i, ll dep = 0) {
    if(dep > n) return -1;
    if(longest[i] != -1) return longest[i];
    if(!ok[i]) return longest[i] = 0;

    longest[i] = calc_longest((i + m) % n, dep+1);
    if(longest[i] == -1) return -1;
    return longest[i] += 1;
}

