  cin >> S >> T;
  {
    string sc = min_cycle(T), st = min_cycle(S);
    sc += sc;
    vector<int> Z = Z_algorithm(sc+"#"+st);
    for(size_t i = 0; i < sc.length(); ++i){
      if(Z[i] == (int)st.length()){
        cout << -1 << endl;
        return 0;
      }
    }
  }
  string S_ = S;
  while(S.length() < T.length()) S += S_;
  S += S;
  string U = T + "#" + S;
  vector<int> Z = Z_algorithm(U);
  int N = Z.size(), M = T.length();
  vector<int> dp(N+1);
  int ans = 0;
  for(int i = 0; i < N; ++i){
    ans = max(ans,dp[i]);
    if(Z[i] == M) dp[i+M] = dp[i]+1;
  }
  cout << ans << endl;
}

