	std::random_device rnd;
	std::mt19937 mt(rnd());
	std::uniform_int_distribution<> rand_base(2, rh_mod-2);
	ll rh_base=rand_base(mt);
	RollingHash rhs(SS,rh_mod,rh_base),rht(T,rh_mod,rh_base);

	vector<ll> indegree(S.size());
	vector<vector<ll>> g(S.size());
	rep(i,S.size()){
		if(rhs.get(i,i+T.size()) == rht.get(0,T.size())){
			ll to=(i+T.size()) % S.size();
			g[i].push_back(to);
			indegree[to]++;
		}
	}

	queue<ll> q;
	rep(i,S.size()) if(indegree[i]==0)q.push(i);

	vector<ll> dp(S.size(),0);
	ll sortcount=0;
	while(!q.empty()){
		ll v=q.front();
		q.pop();
		sortcount++;
		for(ll nextv : g[v]){
			dp[nextv]=dp[v]+1;
			indegree[nextv]--;
			if(indegree[nextv]==0)q.push(nextv);
		}
	}

	if(sortcount==S.size()){
		ll maxval=0;
