ll modpow(ll a, ll t) {
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= MOD;
        }
        a *= a;
        a %= MOD;
        t >>= 1;
    }
    return ret;
}

// b は a の substring である
ll is_subseq(string a, string b) {
    int n = a.length(), m = b.length();
    if(n < m) return false;

    vector<ll> hash(n, 0);
    ll ba = 1;
    for(int j=0;j<m;++j) {
        hash[0] += (ll(a[j]-'a') * ba) % MOD;
        hash[0] %= MOD;
        ba *= BASE;
        ba %= MOD;
    }
    ba *= modpow(BASE, MOD-2);
    ba %= MOD;

    for(int i=1;i<n;++i) {
        hash[i] = (((hash[i-1]+MOD-ll(a[i-1]-'a'))%MOD) * modpow(BASE, MOD-2)) % MOD;
        hash[i] %= MOD;
        hash[i] += (ll(a[(i+m-1)%n]-'a') * ba) % MOD;
        hash[i] %= MOD;
    }

    ll h = 0;
    ba = 1;
    for(int j=0;j<m;++j) {
        h += (ll(b[j]-'a') * ba) % MOD;
        h %= MOD;
        ba *= BASE;
        ba %= MOD;
    }

    vector<bool> is_same(n, false);
    int ret = 0;
    for(int i=0;i<n;++i) {
        if(hash[i] == h) {
            bool flag = true;
            for(int d=0;d<m;++d) {
                if(a[(i+d)%n] != b[d]) {
                    flag = false;
                    break;
                }
            }
            if(flag) {
                ret = 1;
                is_same[i] = true;
            }
        }
    }

    int tmp = 0;
    for(int i=0;i<2*n;++i) {
        if(is_same[i%n]) {
            ++tmp;
            i += m-1;
            ret = max(tmp, ret);
        } else {
            tmp = 0;
        }
    }

    return ret;
}

int main() {
    std::ios::sync_with_stdio(0); cin.tie(0);
