struct RollingHash {
	static const ll mul0 = 10009, mul1 = 10007;
	static const ll add0 = 10010007, add1 = 13333331;
	static const ll mod=1e9+7;
	size_t len;
	//vector<ll> hash_, hash2_;
	vector<ha>hash_;
	//static vector<ll> pmo_, pmo2_;
	static vector<ha>pmo_;
	void init(const vector<ll>& s) {
		len = s.size();
		hash_.resize(len + 1);
		hash_[0] = make_pair(0, 0);

		if (pmo_.empty()) {
			pmo_.push_back(make_pair(1, 1));
		}
		while (pmo_.size() <= len) {
			pmo_.push_back(make_pair(
				pmo_.back().first*mul0%mod, 
				pmo_.back().second*mul1%mod)
			);
		}
		for (unsigned int i = 0; i < len; ++i) {
			hash_[i + 1] = make_pair(
				(hash_[i].first * mul0 + s[i])%mod,
				(hash_[i].second*mul1 + s[i])%mod
			);
		}
		return;
	}
	void init(const string& s) {
		vector<ll>v;
		for (char c : s) {
			v.push_back(c);
		}
		init(v);
	}
	ha hash(const int l, const int r)const { // s[l..r]
		return make_pair(
			(hash_[r + 1].first - hash_[l].first * pmo_[r + 1 - l].first+mod*mod)%mod,
			(hash_[r + 1].second - hash_[l].second * pmo_[r + 1 - l].second+mod*mod)%mod
		);
	}
	ha  hash()const { // s[all]
		return hash(0, len - 1);
	}

	//hash�̌����@
	static ha concat(const ha L, const ha R, const int RLength) { // hash(L+R) 
		return make_pair(
			(R.first + L.first*pmo_[RLength].first)%mod,
			(R.second + L.second*pmo_[RLength].second)%mod
		);
	}

	//index�̈ʒu��from����to�ɕς������̂̃n�b�V����Ԃ��B
	ha get_changed_hash(const int index, const ll from, const ll to)const {
		const ha p(hash());
		return make_pair(
			(p.first + (to - from) * pmo_[len - index - 1].first)%mod,
			(p.second + (to - from) * pmo_[len - index - 1].second)%mod
		);
	}
};
