lint powmod(lint x, lint n, lint mod){
  lint ret = 1;
  while(n > 0){
    if(n&1) ret *= x, ret %= mod, n -= 1;
    else x *= x, x %= mod, n >>= 1;
  }
  return ret;
}

int d[500010], n, m;
vector<int> G[500010];

void scc_dfs(int v, vector<bool> &used, vector<int> &vs){
    used[v] = true;
    for(int nv: G[v])if(!used[nv]) scc_dfs(nv, used, vs);
    vs.push_back(v);
}

void scc_rdfs(int v, int k, vector<int> &cmp, vector<bool> &used, vector<vector<int>> &rG){
    used[v] = true;
    cmp[v] = k;
    for(int nv: rG[v])if(!used[nv]) scc_rdfs(nv, k, cmp, used, rG);
}

pair<int, vector<int>> scc(){
    vector<vector<int>> rG(n);
    rep(i, n)for(int nv: G[i]) rG[nv].push_back(i);
    vector<bool> used(n, false);
    vector<int> vs;
    vector<int> cmp(n);
    rep(i, n)if(!used[i]) scc_dfs(i, used, vs);
    fill(used.begin(), used.end(), false);
    int k = 0;
    rrep(i, n)if(!used[vs[i]]) scc_rdfs(vs[i], k++, cmp, used, rG);
    return make_pair(k, cmp);
}

int longest_path(int v){
    if(d[v] >= 0) return d[v];
    int ret = 0;
    for(int nv: G[v]) ret = max(ret, longest_path(nv) + 1);
    return d[v] = ret;
}

