vector<int> zfunc(string s){
    int n=s.size();
    vector<int> z(n,0);
    int left=0,right=0;
    for(int i=1;i<n;++i){
        if(i<right)z[i]=min(z[i-left],right-i);
        while((s[z[i]]==s[i+z[i]])&&(i+z[i]<n))++z[i];
        if(i+z[i]>right)left=i,right=i+z[i];
    }
    return z;
}

