ll POWER(ll x, ll y){
    if(y==0) return 1;
    ll f=POWER(x,y/2);
    f*=f;
    f%=p1;
    if(y%2==1){
        f*=x;
        f%=p1;
    }
    return f;
}

ll Pow(ll x, ll y){
    ll x1=x%p1;
    x1+=p1;
    x1%=p1;
    ll y1=y%(p1-1);
    y1+=(p1-1);
    y1%=(p1-1);
    return POWER(x1,y1);
}

ll inverse(ll x){
    return Pow(x,p1-2);
}


