ll ssegm(int i1, int i2){
    ll ret=(shash[i2]-shash[i1]*invq[i2-i1])%p1;
    (ret+=p1)%=p1;
    return ret;
}
ll tsegm(int i1, int i2){
    ll ret=(thash[i2]-thash[i1]*invq[i2-i1])%p1;
    (ret+=p1)%=p1;
    return ret;
}
