struct RollingHash{
    const int MASK30=(1ul<<30)-1;
    const int MASK31=(1ul<<31)-1;
    const int MOD=(1ul<<61)-1;
    int Base=9973;
    vector<int>hash,power;
    int calcmod(int x){
        int res=(x>>61)+(x&MOD);
        if(res>=MOD)res-=MOD;
        return res;
    }
    int mul(int a,int b){
		int au=a>>31;
		int ad=a&MASK31;
		int bu=b>>31;
		int bd=b&MASK31;
		int mid=ad*bu+au*bd;
		int midu=mid>>30;
		int midd=mid&MASK30;
		return calcmod(au*bu*2+midu+(midd<<31)+ad*bd);
	}
    RollingHash(string s,int base){
        //Base=Random(1<<7,1<<9)
        Base=base;
        int n=s.size();
        hash.resize(n+1,0);
        power.resize(n+1,1);
        rep(i,n){
            hash[i+1]=(mul(hash[i],Base)+s[i])%MOD;
            power[i+1]=mul(power[i],Base)%MOD;
        }
    }
    int get_hash(int l,int r){
        //[l,r)
        return (hash[r]-mul(hash[l],power[r-l])+MOD)%MOD;
    }
    int lcp(int x,int y){
        //Longest Common Prefix
        int len=min(hash.size()-y,hash.size()-x);
        int ok=0,ng=len+1;
        while(ng-ok>1){
            int mid=(ok+ng)/2;
            if(get_hash(x,x+mid)==get_hash(y,y+mid))ok=mid;
            else ng=mid;
        }
        return ok;
    }
};
