        rep(i, sz) s.push_back(s[i]);
        a += sz;
    }while(a < tz*2);
    Z_algorithm str; str.build(t+s);
    //cout << s << endl;
    //rep(i, str.size()-tz) cout << str.prefix[i+tz];
    sz = str.size() - tz;
    int cnt = 0;
    int ans = 0;
    while(1) {
        map<int, int> mp;
        int i=tz;
        while(i<=tz+sz) {
            if(mp[i] == 1){
                puts("-1");
                return 0;
            }
            if(str.prefix[i]>=tz) {
                mp[i] = 1;
                cnt++;
                i += tz ;
                if(i > tz + sz){
                    i = tz + (i-tz)%sz ;
                }
            }else{
                ans = max(ans, cnt);
                cnt = 0;
                i++;
            }
            ans = max(ans, cnt);
        }
        if(i==tz+sz+1) break;
    }
