    s += s + s + s+s+s+s+s+s+s+s+s+s+s+s+s;
    RollingHash rhs(s), rht(t);
    p Thash=rht.get(0, (int)t.size());
    rep(i, (int)s.size() - (int)t.size()) {
        if (rhs.get(i, i + (int)t.size()) == Thash) {
            v.push_back(i);
            v.push_back(i + (int)t.size() - 1);
            i += (int)t.size() - 1;
