int calc(const string &s, const string &t, int ok){
    int S = s.size(), T = t.size();

    RollingHash hs(s);

    int ng = S/T+1;
    if(ok>0){
        if(ng == ok+1) return ok;
        ng = ok+2;
    }
    // dbg(ng);
    while(ng-ok>1){
        int mid = (ok+ng)/2;

        string tt = "";
        string nt = t;
        rep(i,30){
            if(mid>>i&1) tt += nt;

            nt += nt;
            if(nt.size() > N) break;
        }
        RollingHash ht(tt);

        int TT = T*mid;
        ll tv = ht.calc(1, TT);

        bool valid = false;
        for(int i=1; i+TT-1<=S; ++i){
            if(hs.calc(i,i+TT-1) == tv){
                valid = true;
                break;
            }
        }

        if(valid) ok = mid;
        else ng = mid;
    }
    // dbg(s);dbg(ok);
    return ok;
}

