    cin >> s >> t;
    int n = s.length(), m = t.length();
    while (s.length() < n + m) {
        s += s;
    }
    RollingHash hs(s), ht(t);
    vector<int> f(n), vis(n, -1);
    for (int i = 0; i < n; i++) {
        if (hs.get(i, i + m) == ht.get(0, m)) {
            f[i] = 1;
        }
    }
