template<class T, class S> int KMP(T A[], int As, T B[], int Bs, S res[], int mem[]){
  int c=0, *f=(int*)mem, i, k;
  k=f[0]=-1;
  for(i=0;i<Bs;i++){
    while(k>=0&&B[k]!=B[i]){
      k=f[k];
    }
    f[i+1]=++k;
  }
  if(res!=NULL){
    for(i=0;i<As-Bs+1;i++){
      res[i]=0;
    }
  }
  k=0;
  for(i=0;i<As;i++){
    while(k>=0&&B[k]!=A[i]){
      k=f[k];
    }
    if(++k==Bs){
      c++;
      if(res!=NULL){
        res[i-Bs+1]=1;
      }
      k=f[k];
    }
  }
  return c;
}
