vector<ll> prefix_fun(string &s)
{

	vector<ll> pi((ll)s.size());
	pi[0]=0;
	for(ll i=1;i<(ll)s.size();i++)
	{

		ll j=pi[i-1];
		while(j>0 and s[j]!=s[i] ) j=pi[j-1];
		if(s[i]==s[j]) j++;
		pi[i]=j;
	}

	return pi;
}

