ll RHmul(ll A, ll B) {
	ll A1 = A >> 31;
	ll A2 = A & mask31;
	ll B1 = B >> 31;
	ll B2 = B & mask31;
	ll ret = 2 * A1 * B1 + A2 * B2 + ((A1 * B2 + A2 * B1 & mask30) << 31) + (A1 * B2 + A2 * B1 >> 30);
