vl z_algorithm(const string& s) {
  vl z(s.size(), 0);
  z[0] = s.size();
  ll lt = 0, rt = 0;
  for (ll k = 1; k < s.size(); k++) {
    if (k > rt) {
      ll n = 0;
      while (k + n < s.size() && s[n] == s[k + n]) {
        n++;
      }
      z[k] = n;
      if (n > 0) {
        lt = k;
        rt = k + n - 1;
      }
    } else {
      ll p = k - lt;
      ll right_len = rt - k + 1;
      if (z[p] < right_len) {
        z[k] = z[p];
      } else {
        ll i = rt + 1;
        while (i < s.size() && s[i] == s[i - k]) {
          i++;
        }
        z[k] = i - k;
        lt = k;
        rt = i - 1;
      }
    }
  }
  return z;
}

class Graph {
 private:
  vvl g;
  vl indeg;

 public:
  Graph(ll n) : g(n), indeg(n, 0) {}
  void addEdge(ll a, ll b) {
    g[a].push_back(b);
    indeg[b]++;
  }
  size_t size() { return g.size(); }
  void tsort(vl& ans) {
    priority_queue<ll, vl, greater<ll>> que;
    for (int i = g.size() - 1; i >= 0; i--) {
      if (indeg[i] == 0) que.push(i);
    }
    while (!que.empty()) {
      ll i = que.top();
      que.pop();
      ans.push_back(i);
      for (auto& j : g[i]) {
        indeg[j]--;
        if (indeg[j] == 0) que.push(j);
      }
    }
  }
};

