long long MOD(long long x){return x - x / mod * mod;}

void pre_h(){
	power[0] = 1;
	for (int i = 1; i <= m; i++){
		power[i] = MOD(power[i - 1] * P);
	}
	for (int i = 1; i <= now; i++){
		h[i] = MOD(h[i - 1] * P + s[i] - 'a' + 1);
	}
}

long long get_h(int l, int r){
	return MOD(h[r] - MOD(h[l - 1] * power[r - l + 1]) + mod);
}

