	for(int i=1;i<=n;i++) hs[i]=(1ll*hs[i-1]*mult%MOD+s[i])%MOD;
	for(int i=n+1;i<=2*n;i++) hs[i]=(1ll*hs[i-1]*mult%MOD+s[i-n])%MOD;
	int l=0,r=n/m;
	for(int i=0;i<n/m;i++) for(int j=1;j<=m;j++) hhs[i*m+j]=(1ll*hhs[i*m+j-1]*mult%MOD+t[j])%MOD;
