		f[i+1][1] = f[i][1]*37LL%mod;
	}
	rep(i,s.size()){
		rui[i+1][0] = rui[i][0]+f[i+1][0]*(s[i]-'0'+1)%mod;
		rui[i+1][1] = rui[i][1]+f[i+1][1]*(s[i]-'0'+1)%mod;
		rui[i+1][0] %= mod;
		rui[i+1][1] %= mod;
	}
	rep(i,t.size()){
		ss[0] += f[i+1][0]*(t[i]-'0'+1)%mod;
		ss[1] += f[i+1][1]*(t[i]-'0'+1)%mod;
		ss[0] %= mod; ss[1] %= mod;
	}
	rep(i,s.size()){
		if(i+t.size()-1 >= s.size()) continue;
		rep(j,2){
			ll x = rui[i+t.size()][j]-rui[i][j]; x = (x%mod+mod)%mod;
			ll y = ss[j]; y = y*f[i][j]%mod; y = (y%mod+mod)%mod;
			if(x != y) goto fail;
		}
		edge[i%n].pb((i+t.size())%n); in[(i+t.size())%n]++;
		fail:;
	}
	queue<int>que;
	rep(i,n) if(in[i] == 0) que.push(i);
	while(!que.empty()){
		int q = que.front(); que.pop();
		rep(i,edge[q].size()){
			in[edge[q][i]]--; if(in[edge[q][i]] == 0) que.push(edge[q][i]);
		}
	}
	rep(i,n) if(in[i]) { cout << -1 << endl; return 0; }
	int ans = 0; memset(dist,-1,sizeof(dist));
	rep(i,n) ans = max(ans,rec(i));
	cout << ans << endl;
}

