int mxi(string s, string t){
    int low = 0, high = s.size()/t.size();
    int ans = 0;
    while(low <= high){
        int mid = low+(high-low)/2;
        bool kk = 0;
        string tt;
        FOR(i,0,mid)
            tt += t;
        string ss = tt+'|'+s;
        /* if(mid <= 3) */
        /*     whatis(tt) */
        int n = ss.size();
        int z[n];
        z[0] = 0;
        int l = 0, r = 0;
        for(int i = 1; i < n; ++i){
            if(i > r){
                l = r = i;
                while(r < n && ss[r] == ss[r-l]) ++r;
                z[i] = r-l; --r;
            }
            else{
                int k = i-l;
                if(z[k] < r-i+1) z[i] = z[k];
                else{
                    l = i;
                    while(r < n && ss[r] == ss[r-l]) ++r;
                    z[i] = r-l; --r;
                }
            }
            if(z[i] == (int)tt.size()){
                kk = 1;
            }
        }
        if(kk){
            ans = mid;
            //high = mid-1; //Jak najmniejsza
            low = mid+1; //Jak największa
        }
        else{
            //low = mid+1; //Jak najmniejsza
            high = mid-1; //Jak największa
        }
    }
    return ans;
}

