	{
		while (S.size() < T.size()) {
			S += s;
		}
	}
	S += S;
	rolling_hash RHs(S), RHt(T);
	vector<vector<int> > G(s.size());

	REP(i, s.size()) {
		if (RHs.hash(i, i + T.size(), 0) == RHt.hash(0, T.size(), 0)) {
			if (RHs.hash(i, i + T.size(), 1) == RHt.hash(0, T.size(), 1)) {
				G[i].emplace_back((i + T.size()) % (s.size()));
			}
			else {
