void kmp() {
  dfa.resize(R, vector<int>(m+1));
  dfa[t[0]][0] = 1;
  for(int x = 0, j = 1; j <= m; j++) {
    for(int c = 0; c < R; c++) {
      dfa[c][j] = dfa[c][x];
    }
    dfa[t[j]][j] = (j+1)%(m+1);
    x = dfa[t[j]][x];
  }
}

int pathLength(int i) {
  if(!match[i]) return 0;
  if(L[i] != -1) return L[i];

  return L[i] = pathLength((i+m)%n) + 1;
}

bool hasLoop() {
  rep(i,m) {
    bool loop = true;
    for(int j = 0; j < n + m; j += m) {
      if(!match[(i+j)%n]) loop = false;
    }
    if(loop) return true;
  }
  return false;
}

