    const ll n = s.size(), m = t.size();

    FOR(i, n, n+m-1) s += s[i%n];
    s = t + s;

    vector<ll> v = Zalgo(s);

    vector<vector<ll>> g(n);
    REP(i, n) {
        // s[i],s[i+1],…,s[i+m-2],s[i+m-1] == t の判定
        if(v[i+m] >= m) {
            g[i].push_back((i+m)%n);
        }
    }

    ll idx = 1;
    bool loop = false;
    vector<ll> used(n);
    function<void(ll)> isloop = [&](ll v) {
        // cout << v << endl;
        if(used[v]) {
            if(used[v] == idx) loop = true;
            return;
        }
        used[v] = idx;
        for(auto to: g[v]) {
            isloop(to);
        }
    };
    REP(i, n) {
        if(!used[i]) {
            // cout << "start:" << i << endl;
            isloop(i);
            idx++;
            // cout << used << endl;
        }
    }
    if(loop) {
        cout << -1 << endl;
        return 0;
    }

    vector<ll> dist(n, -1);
    function<void(ll)> dfs = [&](ll v) {
        if(dist[v] != -1) return;
        dist[v] = 0;
        for(auto to: g[v]) {
            dfs(to);
            chmax(dist[v], dist[to] + 1);
        }
    };
    REP(i, n) {
        if(dist[i] == -1) {
            dfs(i);
        }
    }

    ll ma = 0;
    REP(i, n) chmax(ma, dist[i]);
    cout << ma << endl;

    return 0;
}

