vector<ll> prefix_function (string Z) 
{
    int n = (int) Z.length();
    vector<ll> F (n);
    F[0]=0;
    for (int i=1; i<n; ++i) 
   	{
        int j = F[i-1];
        while (j > 0 && Z[i] != Z[j])
            j = F[j-1];
        if (Z[i] == Z[j])  
        	++j;
        F[i] = j;
    }
    return F;
}
int LIM=5e5+10;
v previuos(LIM);

v ans(LIM,-1);
