	if (ans[n]!=-1)
		return ;
	stk[n]=1;
	int temp=0;
	if (previuos[n]==-1)
	{
		temp=0;
	}
	else
	{
		dfs(previuos[n],stk);
		temp=ans[previuos[n]]+1;
	}
	if (inf==1)
		return ;
	ans[n]=temp;
	stk[n]=0;
}
