long long int pow_mod(long long int p_a,long long int p_n){
	//p_a^p_n mod p_p
	long long int p_b=1,p_t=1;
	for(;p_b<=p_n;p_b<<=1);
	for(p_b>>=1;p_b>0;p_b>>=1){
		p_t*=p_t;
		if(p_n&p_b)p_t*=p_a;
	}
	return p_t;
}

