int par[500010]; 
int depth[500010]; 
int sz[500010];
string S, T; 
void init(){
	for(int i = 0; i < S.size(); i++){
		par[i] = i; depth[i] = 0; sz[i] = 1; 
	}
}
int find(int x){
	if(par[x] == x){
		return x;
	}
	else{
		return par[x] = find(par[x]); 
	}
}
void unite(int x, int y){
	x = find(x); 
	y = find(y); 
	if(x == y) return;
	else if(depth[x] < depth[y]){
		par[x] = y; 
		sz[y] += sz[x]; 
	}else{
		par[y] = x; 
		sz[x] += sz[y];  
		if(depth[x] == depth[y]) depth[x] ++; 
	}
}
bool same(int x, int y){
	return find(x) == find(y); 
}
int siz(int x){
	return sz[find(x)]; 
}
int main(){
	cin >> S >> T; init(); 
	string U = T + "*" + S; 
	while(1){
		if(U.size() > S.size() + T.size() * 2) break; 
		U += S; 	
	}
	int Z[2000010] = {}; 
	Z[0] = T.size(); 
	int i = 1, j = 0; 
	while(i < U.size()){
		while(i + j < U.size() && U[j] == U[i + j]) j++;
		Z[i] = j;
		if(j == 0){
			i++; continue;
		}
		int k = 1;
		while(k < j && k + Z[k] < j){
			Z[i + k] = Z[k]; k++;
		}
		i += k; j -= k;
	}
	for(int i = 0; i < S.size(); i++){
		if(Z[T.size() + 1 + i] != T.size()) continue; 
		int k = (i + T.size()) % S.size(); 
		if(same(i, k)){
			cout << -1 << endl; return 0; 
		}
		unite(i, k); 
	}
	int ans = 0; 
	for(int i = 0; i < S.size(); i++){
		ans = max(ans, siz(i)); 
	}
	cout << ans - 1 << endl;
}

