void zAlgo(){
	int lb = -1, rb = -1;
	z[0] = l;
	FOR(i, 1, l){
		if(i <= rb) z[i] = min(rb - i + 1, z[i - lb]);
		//printf("z = %d\n", z[i]);
		for(int &j = z[i]; i + j < l && str[j] == str[i + j]; ++j) /*printf("i = %d j = %d %c %c\n", i, j, str[i], str[i + j])*/;
		if(z[i] > rb) lb = i, rb = i + z[i] - 1;
	}
	return;
}

bool topoSort(){
	int hd = 0, tl = 0, ret = 0;
	FOR(i, 0, m) if(!deg[i]) q[tl++] = i;
	for(; hd < tl; ++hd){
		int u = q[hd];
		//printf("u = %d\n", u);
		++ret;
		if(g[u] && !(--deg[(u + n) % m])){
			//printf("v = %d\n", (u + n) % m);
			q[tl++] = (u + n) % m;
		}
	}
	return (ret == m);
}

