int KMPSearch(string pat, string txt) 
{ 
    int M = (pat).length(); 
    int N = (txt).length(); 

    int lps[M]; 

    computeLPSArray(pat, M, lps); 

    int i = 0;
    int j = 0;  
    int cnt=1;
    set<int> s;
    while (i < N) { 
        if (pat[j] == txt[i]) { 
            j++; 
            i++; 
        } 

        if (j == M) { 
            s.insert(i-j);
            j = lps[j - 1]; 
        } 
        else if (i < N && pat[j] != txt[i]) { 
            if (j != 0) 
                j = lps[j - 1]; 
            else
                i = i + 1; 
        } 
    } 
    int ans=0;
    for(auto x:s){
        int cnt=1;
        while(s.find(x+M)!=s.end()){
            cnt++;
            x=x+M;
            s.erase(s.find(x));
        }
        ans=max(ans,cnt);

    }
    return ans;
} 
void computeLPSArray(string pat, int M, int* lps) 
{ 
    int len = 0; 

    lps[0] = 0; 
    int i = 1; 
    while (i < M) { 
        if (pat[i] == pat[len]) { 
            len++; 
            lps[i] = len; 
            i++; 
        } 
        else 
        { 
            if (len != 0) { 
                len = lps[len - 1]; 
            } 
            else 
            { 
                lps[i] = 0; 
                i++; 
            } 
        } 
    } 
} 
