template<class T=string> struct rolling_hash2 {//@formatter:off
    const int b[2] = {11731, 11839};
    const int m[2] = {1000002571LL, 1000002631LL};
    int n;
    T s;//stringやvector
    vector<long long> hash[2], pow[2];
    rolling_hash2() {}
    rolling_hash2(const T &S) : s(S) {n = (int) S.size();for (int i = 0; i < 2; ++i) {hash[i].assign(n + 1, 0);pow[i].assign(n + 1, 1);for (int j = 0; j < n; ++j) {hash[i][j + 1] = (hash[i][j] * b[i] + S[j]) % m[i];pow[i][j + 1] = pow[i][j] * b[i] % m[i];}}}
    // get hash of S[left:right]
     ll get(int l, int r, int id) const {ll res = hash[id][r] - hash[id][l] * pow[id][r - l] % m[id];if (res < 0) res += m[id];return res;}
     ll get(int l, int r) {return (get(l, r, 0) << 32) | get(l, r, 1);}
     ll operator()(int l, int r) {return get(l, r, 0);}
     ll operator()() {return get(0, n, 0);}
    // get lcp of S[a:] and S[b:]
     int lcp(int a, int b) const {int len = min((int) s.size() - a, (int) s.size() - b);int low = -1, high = len + 1;while (high - low > 1) {int mid = (low + high) / 2;if (get(a, a + mid, 0) != get(b, b + mid, 0)) high = mid;else if (get(a, a + mid, 1) != get(b, b + mid, 1)) high = mid;else low = mid;}return low;}
    // get lcp of S[a:] and T[b:]
     int lcp(const rolling_hash2 &t, int a, int b) const {int len = min((int) s.size() - a, (int) s.size() - b);int low = -1, high = len + 1;while (high - low > 1) {int mid = (low + high) / 2;if (get(a, a + mid, 0) != get(b, b + mid, 0)) high = mid;else if (get(a, a + mid, 1) != get(b, b + mid, 1)) high = mid;else low = mid;}return low;}
};

//早い
struct rolling_hash {
    static constexpr int base1 =14341 ,base2 = 2009;
//            1007,

    static constexpr int mod1 = 1000000007, mod2 = 1000000009;
    vector<long long> hash1, hash2, power1, power2;
    int n;
    rolling_hash(const string &S) {        n = (int) S.size();        hash1.assign(n + 1, 0);        hash2.assign(n + 1, 0);        power1.assign(n + 1, 1);        power2.assign(n + 1, 1);        for (int i = 0; i < n; ++i) {            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;            power1[i + 1] = (power1[i] * base1) % mod1;            power2[i + 1] = (power2[i] * base2) % mod2;        }    }
    inline pair<int, int> get(int l, int r) const {        long long res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;        if (res1 < 0) res1 += mod1;        long long res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;        if (res2 < 0) res2 += mod2;        return {res1, res2};    }
    inline pair<int, int> operator()(int l, int r) const { return get(l, r); }
    inline pair<int, int> operator()() const { return get(0,n); }
    // get lcp of S[a:] and T[b:]
    //接頭語がどれだけ一致するか
    //範囲の重複を含む
    inline int lcp_dup(int a, int b) const {        int len = min((int) hash1.size() - a, (int) hash1.size() - b);        int low = 0, high = len;        while (high - low > 1) {            int mid = (low + high) >> 1;            if (get(a, a + mid) != get(b, b + mid)) high = mid; else low = mid;        }        return low;    }
    //重複を認めない
    inline int lcp_not(int a, int b) const { return min(lcp_dup(a, b), b - a); }//@formatter:on
};
