string s, t;
int n, m, nm, nxt[500009], cnt, ans;
vector<int> vec[500009];
int ind[500009], ld[500009];

void fun()
{
	for (int i = 0, j  = -1; i < m; i++, j++) {
		while (j >= 0 && t[i] != t[j + 1])
			j = nxt[j];
		nxt[i] = j;
	}
}

void gun(int cur, int v)
{
	cnt++;
	ld[cur] = max(ld[cur], v);
	ans = max(ans, ld[cur]);
	if (ind[cur] == 0) {
		for (int i = 0; i < (int)vec[cur].size(); i++) {
			ind[vec[cur][i]]--;
			gun(vec[cur][i], ld[cur] + 1);
		}
	}
}

