	fun();
	for (int i = 0, j = -1; i < nm; i++, j++) {
		while (j >= 0 && s[i%n] != t[j + 1]) {
			j = nxt[j];
		}
		if (j == m - 1) {
			vec[(i + 1 - m) % n].pb((i + 1)%n);
			ind[(i + 1)%n]++;
			j = nxt[j];
		}
	}
	for (int i = 0; i < n; i++) {
		if (ind[i] == 0)
