    std::string t = str;
    std::sort(rag(t));

    rep(i, str.size())
        rank[0][i] = std::lower_bound(rag(t), str[i]) - std::begin(t);

    int x = 1;

    for (int i = 1; i < MAXL; ++i)
    {
        std::vector<P> vec;
        rep(j, str.size())
        {
            vec.emplace_back(rank[i - 1][j], (j + x >= str.size()) ? -1 : rank[i - 1][j + x]);
        }

        std::sort(rag(vec));

        rep(j, str.size())
        {
            rank[i][j] = std::lower_bound(rag(vec), P(rank[i - 1][j], (j + x >= str.size()) ? -1 : rank[i - 1][j + x])) - std::begin(vec);
        }

        x *= 2;
    }

    sa.resize(str.size());

    rep(i, str.size())
    {
        sa[rank[MAXL - 1][i]] = i;
    }
}

auto lbound(const std::string &t)
{

    int lb = -1, ub = sa.size();

    while (ub - lb > 1)
    {
        int mid = (lb + ub) / 2;

        if (str.substr(sa[mid], t.size()) >= t)
        {
            ub = mid;
        }
        else
        {
            lb = mid;
        }
    }

    return std::begin(sa) + ub;
}

