vector<int> kmp_search(const string &s, const string &t, const vector<int> &kmp) {
  // ret[i] == true なら s[i:] starts with t
  vector<int> ret(s.size(), false);

  int m = 0;
  int i = 0;
  while (m + i < s.size()) {
    if (t[i] == s[m + i]) {
      i++;
      if (i == t.size()) {
        ret[m] = true;
        m += i - kmp[i];
        if (i > 0) {
          i = kmp[i];
        }
      }
    } else {
      m += i - kmp[i];
      if (i > 0) {
        i = kmp[i];
      }
    }
  }
  return ret;
}

int solve(const string &s, const string &t, int ls, int lt) {
  // https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
  vector<int> kmp(lt + 2, 0);
  kmp[0] = -1;
  kmp[1] = 0;
  {
    int i = 2;
    int j = 0;
    while (i < lt) {
      if (t[i - 1] == t[j]) {
        kmp[i] = j + 1;
        i++;
        j++;
      } else if (j > 0) {
        j = kmp[j];
      } else {
        kmp[i] = 0;
        i++;
      }
    }
  }

  int ret = 0;
  vector<int> matches = kmp_search(s, t, kmp);
  rep (i, matches.size()) {
    set<int> nodes;
    nodes.insert(i % ls);
    int j = i;
    while (j < matches.size() && matches[j]) {
      j += lt;
      if (nodes.count(j % ls)) {
        return -1;
      }
      nodes.insert(j % ls);
    }
    ret = max(int(nodes.size() - 1), ret);
  }
  return ret;
}

int main() {
  string s, t;
  cin >> s >> t;

  int ls, lt;
  ls = s.size();
  lt = t.size();

  do {
    s += s;
  } while (s.size() < t.size() * 3);
  int ret = solve(s, t, ls, lt);
  cout << ret << endl;
}

