using namespace std;

// まずtに対してZ配列を作成
vector<int> getZArr(const string& str) {
  int str_size = str.size();

  vector<int> a(str_size);
  a[0] = str_size; // 使ってないのでなんでもいい
  int i = 1, j = 0;
  while (i + j < str_size) {
    while (i + j < str_size && str[i+j] == str[j]) {
      j++;
    }
    a[i] = j;

    if (j == 0) {
      i++;
      continue;
    }

    int k = 1;
    while (k < j && a[k] + k < j) {
      a[i+k] = a[k];
      k++;
    }

    i += k;
    // k < jでbreakした場合は、k==jで全部チェック済みなので、次回はまた最初(j=0)から。
    // a[k] + k < j でbreakした場合は、a[k] + k >= j, a[k] >= j - kなので、次は最低でもj-k-1までは一致している。よって次はj-kからチェックする
    j -= k;
  }

  return a;
}

vector<bool> check_eq(const string& s, const string& t) {
  int s_size = s.size();
  int t_size = t.size();
  vector<bool> result(s_size - t_size + 1);

  const vector<int>& zarr = getZArr(t + "$" + s); // 先に検索文字列を入れて、長さが一致するかを調べる
  int zarr_size = zarr.size();
  // 照合
  for (int i = 0; i < zarr_size; i++) {
    int j = i - (t_size + 1);
    if (j < 0) {
      continue; // t+"$"はスキップ
    }
    if (j >= result.size()) {
      break;
    }
    result[j] = zarr[i] == t_size;
  }

  return result;
}

int main() {
  string s,t,s_origin;
  cin >> s >> t;
  s_origin = s;
  int s_origin_size = s_origin.size();
  int t_size = t.size();

  while(s.size() < t_size + s_origin_size - 1) {
    s += s_origin;
  }
  s = s.substr(0, t_size + s_origin_size - 1);

  const vector<bool>& eqs = check_eq(s,t);

  int max_length = 0;
  vector<int> length(s_origin_size, -1);

  for (int i = 0; i < s_origin_size; i++) {
    if (length[i] != -1) {
      continue;
    }

    if (!eqs[i]) {
      length[i] = 0;
      continue;
    }

    int current = i;
    int diff = 0;
    queue<int> q;
    while(eqs[current]) {
      if (!q.empty() && i == current) {
        // 無限に一致する
        max_length = -1;
        goto finish;
      }

      if (length[current] != -1) {
        diff = length[current]; // すでに到達済みの場合、計算済みの長さを加えて終了する
        break;
      }
      length[current] = 0; // 一旦到達マーク設定
      q.push(current);
      current = (current + t_size) % s_origin_size;
    }

    max_length = max(max_length, diff + (int)q.size());

    while(!q.empty()) {
      int len = q.size();
      int current = q.front();
      q.pop();
      length[current] = len + diff; // 正確な長さで上書き
    }
  }

finish:
  cout << max_length << endl;

  return 0;
}

