class KMP{
  private:
    string S;
    string W;
    vector<ll> T;
    vector<bool> flag;

  public:
    void make_table(void){
      T.resize(W.size());
      ll i = 2;
      ll j = 0;
      T[0] = -1;
      T[1] = 0;

      while(i<W.size()){
        if(W[i-1]==W[j]){
          T[i] = j+1;
          i++;
          j++;
        }else if(j>0){
          j = T[j];
        }else{
          T[i] = 0;
          i++;
        }
      }
      return;
    }

    KMP(string s, string w){
      S = s;
      W = w;
      make_table();
      flag.resize(S.size(), false);
      return;
    };

    ~KMP(void){
      return;
    };

    ll local_search(ll start){
      ll m = 0; // the start position in S
      ll i = start; // the start position in W

      while(m+i<S.size()){
        if(W[i] == S[m+i]){
          i++;
          if(i==W.size()) return m;
        }else{
          m+=i-T[i];
          if(i>0) i=T[i];
        }
      }
      return -1;
    };

    void total_search(void){
      ll m = 0; // the start position in S
      ll i = 0; // the start position in W

      while(m+i<S.size()){
        if(W[i] == S[m+i]){
          i++;
          if(i==W.size()){
            flag[m] = true;
            m++;
            i=0;
          }
        }else{
          m+=i-T[i];
          if(i>0) i=T[i];
        }
      }
      return;
    };

    bool start_check(ll start){
      return flag[start];
    };
};

vll dp;
vll jump;
bool total_flag = true;

ll calc(ll pos, const ll init){
  ll n_pos = jump[pos];
  if(n_pos<0){
    return dp[pos] = 0;
  }
  if(n_pos==init){
    total_flag = false;
    return -2;
  }
  if(dp[pos]>=0) return dp[pos];
  return dp[pos] = calc(n_pos, init) + 1;
}

