void build_kmp(const string &w){
	for(int i = 1, q = 0;i < w.size();++i){
		while(q and w[i] != w[q])q = f[q - 1];
		f[i] = q += w[i] == w[q];
	}
}
int os, sl;
int form(int i){
	return i >= os ? i - os : i;
}
bool infinity(int b){
	static bool tried[maxn << 2] = {};
	int e = b;
	for(b = form(b + t.size());b != e;b = form(b + t.size())){
		if(tried[b] || !cnt[(b < sl ? b + sl : b > sl + sl ? b - sl : b)])return false;
		tried[b] = true;
	}
	return cnt[e < sl ? e + sl : e];
}
int main(){
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> s >> t;
	while(s.size() < t.size() * 2)s += s;
	build_kmp(t);
	sl = s.size();
	os = sl * 3;
	s += s + s + s;
	for(int i = 0, q = 0;i < s.size();++i){
		while(q and s[i] != t[q])q = f[q - 1];
		q += s[i] == t[q];
		cnt[max(0, (i - (int)t.size() + 1))] = (q == t.size()) ? t.size() : 0;
		if(cnt[i])q = f[q - 1];
	}
	ull res = 0;
	for(int i = 0;i < s.size();++i){
		if(cnt[i]){
			if(i >= t.size() and cnt[i - t.size()])cnt[i] += cnt[i - t.size()];
			if(s.size() - cnt[i] == sl)res = -1;
			res = max(res, (ull)(cnt[i] / t.size()));
		}
	}
	for(int i = 0;i < t.size() and res != -1;++i)
		if(infinity(i))res = -1;
	cout << (int)res << '\n';
}

