struct KMP{
    vi a;
    KMP() = default;
    KMP(const string& s) : a(s.size() + 1, -1) {
        int j = -1;
        REP(i, s.size()) {
            while(j >= 0 && s[i] != s[j]) j = a[j];
            a[i + 1] = ++j;
        }
    }

    inline int operator[](int i) { return a[i]; }
};

vll memo;
vi E;

ll dfs (int p) {
    if (memo[p] > -1) return memo[p];

    if (E[p] == -1) {
        return memo[p] = 0;
    } else {
        memo[p] = inf; // to detect loop
        return memo[p] = dfs(E[p]) + 1;
    }
}

int main(){
    cin.tie(0);
    ios_base::sync_with_stdio(false);
    cout << fixed << setprecision(20);

    string s, t;
    cin >> s >> t;

    string ss = s;
    while(ss.size() < s.size() + t.size()) {
        ss += s;
    }

    KMP kmp(t);

    E.resize(s.size(), -1);

    int i = 0, j = 0;
    while(i < s.size()) {
        while(j < t.size() && ss[i + j] == t[j]) ++j;

        if (j == t.size()) E[i] = (i + t.size()) % s.size();

        i += j - kmp[j];
        if (j > 0) j = kmp[j];
    }

    ll ans = 0;
    memo.resize(s.size(), -1);
    REP(i, s.size()) {
        if (memo[i] > -1) continue;
        ans = max(ans, dfs(i));
    }

    if (ans >= inf) {
        print(-1);
    } else {
        print(ans);
    }

}

