string S;
int d[MAX_N];

int loop(int v) {
	if(d[v] != -1) return d[v];
	d[v] = 0;
	rep(i, 0, sz(SCC::G[v])) {
		int n = SCC::G[v][i];
		MAX(d[v], loop(n) + 1);
	}
	return d[v];
}

void solve() {
	cin >> str >> T;
	N = sz(str); M = sz(T);
	S += str;
	S += str;
	while(sz(S) - N + 1 < M) S += str;
	vector<int> kmp = KMP(T);
	int at = 0;
	// debug(S, sz(S));

	SCC::init(N);
	rep(i, 0, sz(S)) {
		while(at >= 0 && S[i] != T[at]) at = kmp[at];
		at++;
		if(at == M && i - M + 1 < N) {
			SCC::add_edge((i - M + 1) % N, (i + 1) % N);
			// debug((i - M + 1) % N, (i + 1) % N);
			at = kmp[at];
		}
	}
	int K = SCC::get();
	debug(K);
