		cout << -1 << "\n";
	}
	else {
		memset(d, -1, sizeof(d));
		int ans = 0;
		rep(i, 0, N) {
			MAX(ans, loop(i));
		}
		// debug(vi(d, d + N));
		cout << ans << "\n";
	}
}

