void getnex(string m)
{
	int k=-1,j=0;
	nex[0] = -1;
	while(j<m.length())
	{
		if(k==-1 || m[k]==m[j])
		{
			k++;
			j++;
			nex[j] = k;
		}
		else
			k = nex[k];
	}
}

int kmp()
{
	int k=0,j=0;
	while(j<h.length())
	{
		if(k==-1 || s[k]==h[j])
		{
			k++;
			j++;
		}
		else
			k = nex[k];
		if(k==s.length())
		{
//			printf("%d %d\n",j-k+1,j);
			sum++;
		}
	}
//	cout<<sum<<endl;
}

int main()
{
	cin>>h>>s;
	if(h.length()>s.length())
	{
		getnex(s);
		kmp();
		cout<<sum<<endl;
	}
	else if(h.length()<s.length())
	{
		swap(h,s);
		getnex(s);
		kmp();
		if(sum>0)
			cout<<-1<<endl;
		else
			cout<<0<<endl;
	}
	else if(h.length()==s.length())
	{
		string tmp=s;
		s += s;
		swap(h,s);
		getnex(s);
		kmp();
		if(sum>0)
		{
			cout<<-1<<endl;
			exit(0);
		}
		memset(nex,0,sizeof(nex));
		swap(h,s);
		s = tmp;
		getnex(s);
		kmp();
		cout<<sum<<endl;
	}

	return 0;
}

