	int resCnt = 0;
	for (int i = 0; i < 2 * (int)s.length(); i++)
	{
		if (used[i])
			continue;
		else
		{
			int cnt = 0;
			for (int j = i; j < 2 * (int)s.length(); j += (int)t.length())
			{
				if (!foundPos[j])
					break;
				used[j] = true;
				cnt++;
			}
			resCnt = max(resCnt, cnt);
		}
