	while ((int)s.size() < exsize) s += pat;
	s += pat, n = (int)s.size();
	pair <vector <int>, vector <int> > pr = kmp_match(s, t, build_fail(t));
	vector <int> len = pr.first, chk = pr.second;
	for (int i = n - 1; ~i; --i)
		if (chk[i]) ans[i - m + 1] = max(ans[i - m + 1], ans[i + 1] + 1);
