		ok[i]=(hat[t.size()-1]==get_has(i));
	for(int i=s.size();i>=0;i--)
		if(i+t.size()<N && ok[i]) ok[i]+=ok[i+t.size()];
	for(int i=0;i<s.size();i++)
		ans=max(ans,ok[i]);
	if(ans+1>=s.size()/t.size()) cout<<-1<<'\n';
	else cout<<ans<<'\n';

	return 0;
}

