vi init(string& P)
{
    vi b(P.size() + 1);
    int i = 0, j = -1; b[0] = -1;
    while (i < P.size())
    {
        while (j >= 0 && P[i] != P[j]) j = b[j];
        b[++i] = ++j;
    }
    return b;
}

vi kmp(string& T, string& P, vi& b)
{
    vi ret;
    int i = 0, j = 0;
    while (i < T.size())
    {
        while (j >= 0 && T[i] != P[j]) j = b[j];
        ++i; ++j;
        if (j == P.size())
        {
            ret.push_back(i - j);
            j = b[j];
        }
    }
    return ret;
}

std::string operator*(const std::string& s, size_t n) {
    std::string result;
    result.reserve(s.size()*n);
    for(size_t i = 0; i < n; ++i) {
        result += s;
    }
    return result;
}

void solve() {
    string s, t;
    cin >> s >> t;

    if (s.length() < t.length())
        s = s * ((t.length() + s.length() - 1) / s.length());
    int n = s.length();
    s = s * 3;

    int lo = 0;
    int hi = (s.length() + t.length() - 1) / t.length();
    while (lo < hi) {
        int mi = (lo + hi) / 2;
        string u = t * mi;
        vi b = init(u);
        vi m = kmp(s, u, b);
        if (m.empty() == string::npos)
            hi = mi;
        else
            lo = mi + 1;
    }

    string u = t * (lo - 1);
    if (u.length() >= 2 * n) {
        cout << -1 << '\n';
        return;
    }

    cout << lo - 1 << '\n';
    return;
}

