  for (int i = 0; i < n; ++i) if (b[i]) {
    if (n == m) return cout << -1 << '\n', 0;
    int j = (i + m) % n;
    if (b[j]) {
      g[zip(i)].push_back(zip(j));
    }
  }
  V<> comp;
  scc(g, comp);

  set<int> se;
  for (int v = 0; v < (int)g.size(); ++v) {
    if (se.count(comp[v])) return cout << -1 << '\n', 0;
    se.insert(comp[v]);
  }

  UnionFind uf(n);
  for (int v = 0; v < (int)g.size(); ++v) for (int w : g[v]) {
    uf.unite(v, w);
  }
  int res = 0;
  for (int v = 0; v < (int)g.size(); ++v) {
    res = max(res, uf.size(v));
  }
  cout << res << '\n';
}

