		pw1[0]=pw2[0]=1;
		for(int i=1;i<=len;i++)
			pw1[i]=1ll*pw1[i-1]*hbase1%hmod1,
			pw2[i]=1ll*pw2[i-1]*hbase2%hmod2,
			Hsh1[i]=(1ll*Hsh1[i-1]*hbase1+str[i])%hmod1,
			Hsh2[i]=(1ll*Hsh2[i-1]*hbase2+str[i])%hmod2;
	}
	pair<int,int> hsh(int l,int r){
		return mp((Hsh1[r]-1ll*Hsh1[l-1]*pw1[r-l+1]%hmod1+hmod1)%hmod1,(Hsh2[r]-1ll*Hsh2[l-1]*pw2[r-l+1]%hmod2+hmod2)%hmod2);
	}
}hsha,hshb;
bool ne1(int ra,int rb){
	for(int i=1;i<=ra;i++)if(hsha.hsh(i,i+ra-1)==hshb.hsh(1,rb))return true;
