// http://www.prefield.com/algorithm/string/knuth_morris_pratt.html
int* buildFail(const char* p) {
	int m = strlen(p);
	int* fail = new int[m + 1];
	int j = fail[0] = -1;
	for (int i = 1; i <= m; ++i) {
		while (j >= 0 && p[j] != p[i - 1]) j = fail[j];
		fail[i] = ++j;
	}
	return fail;
}
int match(const char* t, const char* p, const int* fail, int* found) {
	int n = strlen(t), m = strlen(p);
	int count = 0;
	for (int i = 0, k = 0; i < n; ++i) {
		while (k >= 0 && p[k] != t[i]) k = fail[k];
		if (++k >= m) {
			found[i-m+1] = true;
			++count; // match at t[i-m+1 .. i]
			k = fail[k];
		}
	}
	return count;
}


int main(int argc, char** argv) {
	string s, t;
	cin >> s >> t;

	while (s.length() < t.length()) {
		s = s + s;
	}
	auto slen = s.length();
	s = s + s;

	vector<int> found(s.length());


	auto fail = buildFail(t.c_str());
	match(s.c_str(), t.c_str(), fail, &found[0]);

	int ans = 0;

	for (int i = 0; i < slen; i++) {
		int rep = 0;
		int k = i;
		while (found[k]) {
			k = (k + t.length()) % slen;
			rep++;
			if (k == i) {
				cout << -1 << endl;
				return 0;
			}
		}
		ans = max(ans, rep);
	}

	cout << ans << endl;
}

