int kmp(string s, string p) {
    int n = s.length(), m = p.length();
    vector<int> table(m, 0); // ずらしテーブル
    {
        int j = 0;
        for(int i=1;i<m;++i) {
            table[i] = j;
            if(p[i] == p[j]) {
                ++j;
            } else {
                j = 0;
            }
        }
    }

    int ret = 0, tmp_cnt = 0, i = 0, j = 0;
    while(i < n) {
        if(s[i] == p[j]) {
            ++i;
            ++j;
        } else {
            tmp_cnt = 0;
            if(j == 0) {
                ++i;
            } else {
                j = table[j];
            }
        }

        if(j == m) {
            ++tmp_cnt;
            ret = max(tmp_cnt, ret);
            j = 0;
        }
    }
    ret = max(tmp_cnt, ret);
    return ret;
}

int calc_period(string s, int n) {
    int s_period = INF;
    for(int i=1;i<=sqrt(n+1);++i) {
        if(n % i) continue;
        bool is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%i]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, i);
        }
        is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%(n/i)]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, n/i);
        }
    }
    return s_period;
}

bool is_inf(string s, string t, int n, int m) {
    int s_period = calc_period(s, n), t_period = calc_period(t, m);
    if(s_period == t_period) {
        bool are_same = true;
        for(int i=0;i<s_period;++i) {
            if(s[i] != t[i]) {
                are_same = false;
            }
        }
        if(are_same) return true;
    }
    return false;
}

