ll power(ll x, ll n, ll mod) {
  ll res = 1;
  x %= mod;
  while (n) {
    if (n & 1)
      res = (res * x) % mod;
    x = (x * x) % mod;
    n >>= 1;
  }
  return res;
}

// 1 based indexing
ll lps[N];
void computeLps(ll *lps, char *text, ll textLen) {
  lps[1] = 0;
  ll i = 2;
  ll len1 = 0; // best longest proper prefix which is also a suffix upto prev
  // Val
  while (i <= textLen) {
    if (text[i] == text[len1 + 1]) {
      len1++;
      lps[i] = len1;
      i++;
    } else {
      if (len1 != 0) {
        len1 = lps[len1];
      } else {
        len1 = 0;
        lps[i] = len1;
        i++;
      }
    }
  }
}

bool starts[N];

ll kmp(char *text, char *pattern, ll textLen, ll patternLen) {
  ll i = 1, j = 1; // i is pointing to main,j is pointing to pattern
  computeLps(lps, pattern, patternLen);
  ll res = 0;
  while (i <= textLen) {
    if (text[i] == pattern[j]) {
      i++;
      j++;
      if (j == (patternLen + 1)) {
        starts[i - patternLen - 1] = true;
        j = lps[j - 1] + 1;
        res++;
      }
    } else {
      if (j != 1) {
        j = lps[j - 1] + 1;
      } else {
        i++;
        j = 1;
      }
    }
  }
  return res;
}

ll dp[N];
bool visited[N];
ll nt, ns;
ll recur(ll pos) {
  if (!starts[pos])
    return 0;
  if (visited[pos]) {
    return -inf;
  }

  ll &ans = dp[pos];
  if (ans != -1)
    return ans;

  visited[pos] = true;
  ans = 1 + recur((pos + nt) % ns);
  visited[pos] = false;
  return ans;
}

