const int maxn=2e6+5;
typedef long long ll;
const ll mod=191981019260817247;
ll base=233;
ll pw[maxn],ha[maxn];
inline ll mul(ll a,ll b){
	ll k=(ll)((long double)a*b/mod);
	ll r=a*b-mod*k;
	if (r<0) r+=mod;
	if (r>=mod) r-=mod;
	return r;
}
inline ll geth(int l,int r){
	return (ha[r]-mul(pw[r-l+1],ha[l-1])+mod)%mod;
}
vector<int> adj[maxn];
int d[maxn];
int n,m,len;
char s[maxn],t[maxn];
int id[maxn];
queue<int> q;
int main(){
	scanf("%s",s+1);
	scanf("%s",t+1);
	n=strlen(s+1);
	m=strlen(t+1);
	len=n;
	while(len<m*2){
		for (int i=1;i<=n;i++){
			s[++len]=s[i];
		}
	}
	pw[0]=1;
	for (int i=1;i<=len;i++){
		pw[i]=mul(pw[i-1],base);
		ha[i]=(mul(ha[i-1],base)+s[i])%mod;
	}
	ll hat=0;
	for (int i=1;i<=m;i++){
		hat=(mul(hat,base)+t[i])%mod;
	}
	for (int i=1;i<=n;i++){
		int r=i+m-1;
		if (hat==geth(i,r)){
			int tp=r%n+1;
			adj[i].push_back(tp);
			id[tp]++;
		}
	}
	for (int i=1;i<=n;i++){
		if (id[i]==0){
			q.push(i);
		}
	}
	while(!q.empty()){
		int u=q.front();
		q.pop();
		for (int i=0;i<adj[u].size();i++){
			int v=adj[u][i];
			id[v]--;
			d[v]=max(d[u]+1,d[v]);
			if (id[v]==0){
				q.push(v);
			}
		}
	}
	int ans=0;
	for (int i=1;i<=n;i++){
		ans=max(ans,d[i]);
		if (id[i]!=0){
			cout<<"-1"<<endl;
			return 0;
		}
	}
	cout<<ans<<endl;
	return 0;
}

