            auto s2=sh(i,s.size())*(x/s.size())+sh(i,x%s.size());
            auto t2=th()*(x/t.size())+th(0,x%t.size());
            return s2==t2;
        }));
    }
    if(ans>IINF/2)cout<<-1<<endl;
    else cout<<ans/t.size()<<endl;
}

