vector<int> zAlgorithm(string s) {
    int n = s.size();
    vector<int> ret(n,0);
    ret[0] = n;
    int i = 1,j = 0;
    while (i < n) {
        while (i+j < n && s[j] == s[i+j]) ++j;
        ret[i] = j;
        if (j == 0) {
            ++i;
            continue;
        }
        int k = 1;
        while (i+k < n && k+ret[k] < j) {
            ret[i+k] = ret[k];
            ++k;
        }
        i += k;
        j -= k;
    }
    return ret;
}

int main() {
    string s,t;
    cin >> s >> t;
    int n = s.size(),m = t.size();
    for (int i = 0;i < (m+n-1)/n+1;++i) t += s;
    vector<int> a = zAlgorithm(t);
    vector<bool> b(n,false),used(n,false);
    for (int i = 0;i < n;++i) if (a[m+i] >= m) b[i] = true;
    int ans = 0;
    for (int i = 0;i < n;++i) if (b[i] && !used[i]) {
        if (b[(i-m%n+n)%n]) continue;
        int cnt = 0,j = i;
        while (b[j]) {
            cnt++;
            used[j] = true;
            (j += m) %= n;
            ans = max(ans,cnt);
        }
    }
    for (int i = 0;i < n;++i) if (b[i] && !used[i]) ans = -1;
    cout << ans << endl;
}

