const ull B = 1000000007;

bool contain(string a, string b){
    int al = a.size(), bl = b.size();
    if(al > bl) return false;
    ull t = 1;
    for(int i = 0; i < al; i++) t *= B;
    ull ah = 0, bh = 0;
    for(int i = 0; i < al; i++) ah = ah * B + a[i];
    for(int i = 0; i < al; i++) bh = bh * B + b[i];
    for(int i = 0; i + al <= bl; i++){
        if(ah == bh) return true;
        if(i + al < bl) bh = bh * B + b[i + al] - b[i] * t;
    }
    return false;
}

int count(string s, string t, int k){
    string reps;
    while(reps.size() < t.size()) reps += s;
    for(int i = 0; i < k; i++) reps += reps;
    int n = reps.size();
    int m = t.size();
    int maxans = n / m;
    int now = 1;
    while(now < maxans) now *= 2;
    string maxt;
    for(int i = 0; i < now; i++) maxt += t;
    int mid = now / 2;
    while(mid){
        if(contain(maxt.substr(0, now * m), reps)) now += mid;
        else now -= mid;
        mid /= 2;
    }
    if(!contain(maxt.substr(0, now * m), reps)) now--;
    return now;
}

