    ull b = 1e9 + 7;
    ll ss = S.size(), st = T.size();
    vector<ull> hs(ss);
    ull ht = 0, hs0 = 0, bt = 1;
    for ( int i = 0; i < st; i++ ) {
        ht = b * ht + (ull)T[i];
        hs0 = b * hs0 + (ull)S[i % ss];
        bt *= b;
    }
    for ( int i = 0; i < ss; i++ ) {
        hs0 = b * hs0  - bt * (ull)S[i] + (ull)S[(st + i) % ss];
        hs[(st + i) % ss] = hs0;
    }
    vector<ll> num(ss, -1);
    for ( ll j = 0; j < ss; j++ ) {
        ll i = 0;
        while ( hs[(j+i*st) % ss] == ht ) {
            i++;
            if ( i > 0 && i * st % ss == 0 ) num[(j+i*st) % ss] = INF;
            if ( num[(j+i*st) % ss] != -1 ) break;
        }
        ll len = 0;
        if ( num[(j+i*st) % ss] != -1 ) {
            len = num[(j+i*st) % ss];
            if ( len != INF ) len++;
            i--;
        }
        while ( i >= 0 ) {
            num[(j+i*st) % ss] = len;
            if ( len != INF ) len++;
            i--;
        }
    }

    ll ans = 0;
    for ( int j = 0; j < ss; j++ ) {
        if ( ans < num[j] ) ans = num[j];
    }
    if ( ans == INF ) ans = -1;
