    while (i < matches.size() && !matches[i]) i++;
    if (i > ls) break;
    if (seen[i]) continue;

    ll j = 0;
    while (matches[i + j * lt]) {
      if (i + j * lt < ls) seen[i + j * lt] = true;
      if (j * lt >= ls) return -1;
      j += 1;
    }
    ret = max(ret, j);
  }
  return ret;
}

