         ans = std::max(ans, tmp);
         tmp = 1;
       } else ++tmp;
       last = i;
     }
     ans = std::max(ans, tmp);
  }
  if(M >= N) {
    if(ans > 1) ans = -1;
    fin(ans);
  }
  if(ans*M >= N) ans = -1;
  fin(ans);
  return 0;
}

