Vec< int > makeKMPfail(const string& S) {
	int n = S.size();	
	Vec< int > fail(n+1, 0);
	int j = fail[0] = -1;
	for_(i,1,n+1) {
		while (j >= 0 && S[j] != S[i - 1]) j = fail[j];
		fail[i] = ++j;
	}
	return fail;
}

