vector<int> suffix_array(string const & s) {
	int n = SI(s);
	vector<int> r(n + 1);
	inc(i, n + 1) { r[i] = (i < n ? s[i] : 0); }

	vector<pair<pair<int, int>, int>> v(n + 1);
	for(int k = 0; k < 1 || (1 << k) < n; k++) {
		inc(i, n + 1) {
			int j = min(SC<int>(i) + (1 << k), n);
			v[i] = { { r[i], r[j] }, i };
		}
		sort(ALL(v));

		int c = 0;
		inc(i, n + 1) {
			if(i > 0 && v[i].FI != v[i - 1].FI) { c++; }
			r[v[i].SE] = c;
		}
	}

	inc(i, n + 1) { r[i] = v[i].SE; }
	return r;
}

