int lcp(string const & s, string const & t) {
	int n = min(SI(s), SI(t));
	inc(i, n) { if(s[i] != t[i]) { return i; } }
	return n;
}

// s の substr かつ t の prefix である最長の文字列の長さを返す
int f(string const & s, string const & t) {
	auto sa = suffix_array(s);

	int ok = -1, ng = SI(sa);
	auto g = [&](int v) -> bool { return (s.substr(sa[v], SI(t)) <= t); };
	while(abs(ok - ng) > 1) {
		int m = (ok + ng) / 2;
		(g(m) ? ok : ng) = m;
	}

	return max(
		lcp(t, s.substr(sa[ok], SI(t))),
		lcp(t, s.substr(sa[ng], SI(t)))
	);
}

