struct StringSearch{
  string &s;
  const SuffixArray &sa;
  const LCPArray &lcp;
  SparseTable<int> sparse;
  StringSearch(LCPArray &lcp)
    : s(lcp.SA.s) , sa(lcp.SA) , lcp(lcp) , sparse(lcp.LCP){ }

  pair<int,int> comp(const string &t  , int len , int si , int ti = 0){
    int sn = (int)s.size() , tn = (int) t.size();
    si += len , ti += len;
    while(si < sn && ti < tn){
      if(s[si] != t[ti]) return make_pair( s[si]<t[ti] , ti);
      si++ , ti++;
    }
    return make_pair( (si>=sn && ti<tn) , ti);
  }  

  // 全ての出現範囲をSA上の[left , right]の範囲で返す
  // 存在しない場合は-1を返す
  pair<int,int> find(string &t){
    // 条件を満たす[left , right]を見つける
    // sa[0]は空文字列なので left = 1 とする
    // lenは既に一致している文字列の長さ
    int left = 1 , right = sa.size() - 1, len = 0;
    while(1){
      int med = (left + right) / 2;
      pair<int,int> ret = comp(t , len , sa[med]);
      if(len < ret.se){
        len = ret.se;
        {
          int ng = left - 1, ok = med;
          whlie(ng + 1 < ok){
            int cur = (ng + ok) / 2;
            if(sparse.query(cur , med) >= len) ok = cur;
            else ng = cur;
          }
          left = ok;
        }
        {
          int ok = med , ng = right + 1;
          whlie(ok + 1 < ng){
            int cur = (ng + ok) / 2;
            if(sparse.query(med, cur) >= len) ok = cur;
            else ng = cur;
          }
          right = ok;
        }      
        if(len == (int)t.size()) return make_pair(left , right);
      }
      else{
        if(ret.fi == 1) left = med;
        else right = med;
      }
      if(left + 1 >= right){
        if(comp(t , len , sa[left + right - med]).se == (int)t.size()){
          return make_pair(left + right - med , left + right - med);
        }
        else return make_pair(-1 , -1);
      }
    }
  }
};

void solve(){
  ins(SS , T);
  int N = SS.size();
  string S = SS;
  S += SS;
  while(sz(S) < sz(T) * 2) S += SS;
  SuffixArray sa(S);
  LCPArray lcp(sa);
  lcp.output();
  StringSearch search(lcp);
  auto nya = search.find(T);
  trc(nya);
  if(nya == P(-1 , -1)) die(0);
  vi v;
  for(int i = nya.fi ; i <= nya.se ; i++) v.pb(sa[i]);
  vi ok(N , 0) , used(N , 0);
  int ans = 0;
  each(x , v) ok[x % N] = 1;
  rep(i , N){
    if(used[i]) continue;
    int cur = 0 , idx = i;
    do{
      used[idx] = 1;
      idx = (idx + T.size()) % N;
      if(idx == i) die(-1);
    }while(ok[idx] && ++cur);
    amax(ans , cur);
  }
  out(ans);
}

