vector<int> z_algorithm(string s) {
	vector<int> res(s.size());

	res[0] = s.size();

	int i = 1, j = 0;

	while (i < s.size()) {
		while (i + j < s.size() && s[j] == s[i + j]) j++;
		res[i] = j;
		if (j == 0) { i++; continue; }
		int k = 1;
		while (i + k < s.size() && k + res[k] < j) res[i + k] = res[k], k++;
		i += k;
		j -= k;
	}

	return res;
}

std::vector<int> build_period_table(const std::string &S) {
	std::vector<int> table(S.size() + 1);
	table[0] = -1;
	int j = -1;
	for (int i = 1; i <= S.size(); ++i) {
		while (j >= 0 && S[i - 1] != S[j]) j = table[j];
		++j;
		table[i] = j;
	}

	table[0] = 0;
	for (int i = 1; i <= S.size(); ++i) table[i] = i - table[i];
	return table;
}

int solve(string str, string T, string elem) {
	int tt = elem.size();
	vector<int> vs = z_algorithm(str);
	vector<int> dp(str.size() + 1, 0);
	FOR(i, tt, str.size() + 1) {
		if (i >= tt + tt && vs[i - tt] >= tt) chmax(dp[i], dp[i - tt] + 1);
	}
	int mx = *max_element(ALL(dp));
	int res = mx / (T.size() / tt);
	return res;
}

int main() {
	string S, T;
	cin >> S >> T;
	auto it = build_period_table(T);
	int tt = it[T.size()];
	string elem = T.substr(0, tt);

	while (S.size() < T.size()) S += S;

	int ans = solve(elem + S + S + S, T, elem);
	if (ans < solve(elem + S + S + S + S, T, elem)) puts("-1");
	else cout << ans << endl;

	return 0;
}

