template<typename T>
struct RollingHash{
    vector<T>hashed;
    T base;
    RollingHash(const string &s,T base = 10007):base(base){
        lint sz=s.size();
        hashed.assign(sz+1,0);
        T power=0;
        rep(i,sz){
            power*=base;
            hashed[i+1]=hashed[i]*base+s[i];
        }
    }
    T get(lint l,lint r){
        T ret = hashed[r]-hashed[l]*pow(base,r-l);
        return ret;
    }
    T connect(T h1,T h2,lint len){
        T ret=h1*pow(base,len)+h2;
        return ret;
    }
    pair<T,T> pow_connect(T h,lint val,T power){
        if(val==0)return make_pair(0,1);
        if(val==1)return make_pair(h,power);
        if(val%2){
            auto tmp=pow_connect(h,val-1,power);
            return make_pair(tmp.first*power+h,tmp.second*power);
        }else{
            auto tmp=pow_connect(h,val/2,power);
            return make_pair(tmp.first*(tmp.second+1),tmp.second*tmp.second);
        }
    }
};

lint bs(lint mn=0,lint mx=INF,function<bool(lint)> func=[](lint x){return true;}) {
    lint left = mn-1;
    lint right =mx;
    while (right - left > 1) {
        lint mid = left + (right - left) / 2;
        if (func(mid)) right = mid;
        else left = mid;
    }
    return right;
}


