vector<int> Zalgorithm(string s){
  int i=1,j=0,k=0,N=s.size();
  vector<int> res(N);
  res[0]=N;
  while(i<N){
    while(i+j<N&&s[i+j]==s[j])++j;
    res[i]=j;
    if(!j){
      ++i;
      continue;
    }
    k=1;
    while(res[k]+k<j){
      res[i+k]=res[k];
      ++k;
    }
    i+=k;
    j-=k;
  }
  return res;
}

int main(){
  startupcpp();
  int i,N,K,ans=0;
  string first,s="",t;
  cin>>first>>t;
  while(s.size()<t.size())s+=first;
  N=s.size();K=t.size();
  vector<int> v=Zalgorithm(t+s+s);
  queue<pair<int,int>> que;
  rep(i,N){
    if(v[i+K]<K)que.push(pair<int,int>(0,(i+K)%N));
  }
  rep(i,N){
    if(que.empty()){
      print(-1);
      return 0;
    }
    auto x=que.front();que.pop();
    chmax(ans,x.first++);
    if(v[x.second+=K]>=K){
      x.second%=N;
      que.push(x);
    }
  }
  print(ans);
}

