constexpr ll base1 = 1007, base2 = 2009, mod1 = 1000000007, mod2 = 1000000009;

struct RollingHash {
    vector<ll> hash1, hash2, pow1, pow2;
    RollingHash (const string &S) {
        int length = sz(S);
        hash1.assign(length + 1, 0);
        hash2.assign(length + 1, 0);
        pow1.assign(length + 1, 1);
        pow2.assign(length + 1, 1);
        rep(i, length) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            pow1[i + 1] = pow1[i] * base1 % mod1;
            pow2[i + 1] = pow2[i] * base2 % mod2;
        }
    }
    pair<ll, ll> find(int l, int r) const {
        ll res1 = hash1[r] - hash1[l] * pow1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        ll res2 = hash2[r] - hash2[l] * pow2[r - l] % mod2;
        if (res2 < 0) res2 += mod2;
        return pair<ll, ll>{res1, res2};
    }
};


string make(string s, long long x) {
  string res = "";
  string temp = s;
  while(x > 0) {
    if(x & 1) res += temp;
    x >>= 1;
    temp = temp + temp;
  }
  return res;
}

long long isOk(RollingHash rh, RollingHash th, string r) {
  // string temp = make(t, key);
  long long cnt = 0;
  long long i = 0;
  long long res = 0;
  while(i < s.size() + t.size()) {
    if(rh.find(i, i + t.size()) == th.find(0, t.size())) {
      // cout << t.size() << endl;
      // cout << i << " " << temp.size() << " " << r.substr(i, temp.size()) << " " << temp << endl;
      if(r.substr(i, t.size()) == t) {
        // cout << cnt << " " << i << " " << r.substr(i, t.size()) << " " << t << endl;
        i = i + t.size();
        cnt++;
      } else {
        cnt = 0;
        i++;
      }
    } else {
      cnt = 0;
      i++;
    }
    res = max(res, cnt);
    // cout << i << endl;
  }
  return res;
}

