long long gcd(long long a, long long b) {
  if(b == 0) return a;
  long long d;
  a = a % b;
  swap(a, b);
  d = gcd(a, b);
  return d;
}

int main() {
  cin >> s >> t;

  string r = make(s, (s.size() + t.size() - 2) / s.size() + 1);

  long long l = s.size() * t.size() / gcd(s.size(), t.size());
  // cout << l << endl;
