  if(make(s, l / s.size()) == make(t, l / t.size())) {
    cout << -1 << endl;
    return 0;
  }

  RollingHash rh(r);
  RollingHash th(t);
  long long ans = isOk(rh, th, r);
  cout << ans << endl;
  return 0;
}

