    {
        string Q = t + "_" + s;
        vector<long> KMP(Q.size() + 1);
        KMP[0] = -1;
        long j = -1;
        for(unsigned long i = 0; i < Q.size(); ++i){
            while(j >= 0 && Q[i] != Q[j])j = KMP[j];
            ++j;
            KMP[i + 1] = j;
            if(KMP[i + 1] >= M && i > KMP[i + 1] && i <= KMP[i + 1] + N)idx[i - KMP[i + 1] - 1] = ~0UL;
        }
