bool toposort(int n, int max_lim) //Returns 1 if there exists a toposort, 0 if there is a cycle
{  
   priority_queue<int, vector<int>, greater<int> > pq;
   for(int i=0;i<n;i++){
      for(auto &it:g[i])
         indeg[it]++;
   }
   for(int i=0;i<n;i++)
   {
      if(!indeg[i])
         pq.push(i);
   }
   while(!pq.empty())
   {
      int u=pq.top();
      pq.pop();
      topo.push_back(u);
      for(auto &v:g[u])
      {
         indeg[v]--;
         if(!indeg[v])
            pq.push(v);
      }
   }
   if(topo.size() != max_lim)
      return 0;
   return 1;
}

