		n = n * m.n % MOD; return *this;
	}
	constexpr modint& operator/=(const modint& m)noexcept {
		assert(m.n);
		T a = m.n, b = MOD, u = 1, v = 0;
		while (b) {
			T t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		n = n * u % MOD;
		if (n < 0)n += MOD;
		return *this;
	}
