void make_table(string p, int m) {
    int j = 0;
    for(int i=1;i<m;++i) {
        table[i] = j;
        if(p[i] == p[j]) {
            ++j;
        } else {
            j = 0;
        }
    }
}

int kmp(string s, string p, int i0=0, int j0=0) {
    int n = s.length(), m = p.length();

    int i = i0, j = j0;
    while(i < max(n, m)) {
        // cerr << i << s[i%n] << " " << j << p[j] << endl;
        if(s[i%n] == p[j]) {
            ++i;
            ++j;
            if(j == m) return i - m;
        } else if(j == 0) {
            ++i;
        } else {
            j = table[j];
        }
    }
    return -1;
}

int calc_period(string s, int n) {
    int s_period = INF;
    for(int i=1;i<=sqrt(n+1);++i) {
        if(n % i) continue;
        bool is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%i]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, i);
        }
        is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%(n/i)]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, n/i);
        }
    }
    return s_period;
}

bool is_inf(string s, string t, int n, int m) {
    int s_period = calc_period(s, n), t_period = calc_period(t, m);
    if(s_period == t_period) {
        bool are_same = true;
        for(int i=0;i<s_period;++i) {
            if(s[i] != t[i]) {
                are_same = false;
            }
        }
        if(are_same) return true;
    }
    return false;
}

int main() {
    string s,t;
    cin >> s >> t;
    int n = s.length(), m = t.length();

    // 答えが -1 の場合をここでふるい落とす
    // 周期が同じで，周期内の文字列が同じなら -1
    if(is_inf(s, t, n, m)) {
        cout << -1 << endl;
        return 0;
    }

    string ss = s;
    while(ss.length() < m) ss += s;
    int nn = ss.length();

    make_table(t, m);

    int i0 = 0, j0 = 0, ans = 0;
    vector<bool> end_of_pattern(nn, false);
    while(i0 < 2*n) {
        int k = kmp(ss, t, i0, j0);
        if(k == -1) {
            ++i0;
        } else {
            end_of_pattern[k+m-1] = true;
            i0 = k + m;
            j0 = table[m-1];
        }
    }

    vector<int> tmp_cnt(m, 0);
    for(int i=0;i<nn;++i) {
        if(end_of_pattern[i]) {
            ++tmp_cnt[i%m];
            ans = max(ans, tmp_cnt[i%m]);
        } else {
            tmp_cnt[i%m] = 0;
        }
    }

    cout << ans << endl;

}

