class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

typedef unsigned long long ull;

class RHash{
public:
  static const ull BASE = 2971215073LL;
  vector<ull> hash, powBase;
  RHash(){}
  RHash(const string &s){
    hash = vector<ull>(s.length()+1);
    powBase = vector<ull>(s.length()+1);
    hash[0] = 0;
    powBase[0] = 1;
    rep(i, s.length()){
      hash[i+1] = hash[i] * BASE + s[i];
      powBase[i+1] = powBase[i] * BASE;
    }
  }
  //[l, r]
  inline ull getSubHash(int l, int r){
    return hash[r+1] - hash[l] * powBase[r+1-l];
  }
};

class Solver {
public:
  Int ans = 0;
  string S, T;
  Solver() {}
  void input() {
    cin >> S >> T;
  }
  void solve() {
    Int oldSLen = Int(S.length());
    while(S.length()  <= T.length() * 2+ 10){
      S += S;
    }
    RHash sHash(S), tHash(T);

    bool check[S.length()];

    rep(i, oldSLen){
      check[i] = false;
      Int sa_begin = i;
      Int sa_end = Int(i + T.length()-1);
      Int ta_begin = 0;
      Int ta_end = Int(T.length()-1);

      if(sHash.getSubHash(sa_begin, sa_end) != tHash.getSubHash(ta_begin, ta_end)) {
        continue;
      }

      if(ta_end == T.length()-1) {
        check[i] = true;
      }
    }

    rep(i, oldSLen){
      pp(check[i]);
    }

    bool maybeLoop = false;
    queue<Int> Q;
    rep(i, oldSLen){
      if(!check[i])continue;
      maybeLoop = true;
      Int pre = (i - T.length() + Int(T.length() )* Int(oldSLen))%oldSLen;
      if(!check[pre]){
        Q.push(i);
      }
    }
    ans = 0;
    if(!maybeLoop)return;
    if(Q.empty()){
      ans = -1;
      return;
    }
    while(!Q.empty()) {
      Int now = Q.front();
      Q.pop();
      Int cnt = 0;
      while (check[now]) {
        cnt++;
        now = (now + T.length()) % oldSLen;
      }
      ans = max(cnt, ans);
    }
  }
  void output() {
    cout << ans <<endl;
  }
};

