inline void Z_algor()
{
    int l=1, r, k;
    z[0]=t.size();
    for(l=1; l<t.size(); l=k)
    {
        r=max(r, l);
        while(r<t.size()&&t[r-l]==t[r]) r++;
        z[l]=r-l;
        k=l+1;
        while(k+z[k-l]<r)
            z[k]=z[k-l], k++;
    }
    forn(i, t.size()) if(i>=M&&z[i]>=M)
    {
        int tr=(i-M)%N;
        mark[tr]=1;
    }
}

inline int dfs(int x)
{
    int &ret=dp[x];
    if(~ret) return 1;
    ret=0;
    if(!mark[x]) return 1;
    ret=-2;
    if(dp[(x+M)%N]==-2) return 0;
    if(!dfs((x+M)%N)) return 0;
    ret=dp[(x+M)%N]+1;
    return 1;
}

