    while(SZ(s) < SZ(t)) s += _;
    s += s + s;
    RollingHash RH(s);

    auto check = [&](ll mid){
        string u = "";
        REP(i, mid) u += t;
        RollingHash mew(u);
        ll c = mew.s_hash();
        REP(i, SZ(s) - SZ(t)){
            if(RH.get(i, i + SZ(u)) == c) return true;
        }
        return false;
    };
    ll k = Roundup_div(SZ(s), SZ(t));
    ll ok = 0, ng = k;
    while(abs(ok - ng) > 1){
        ll m = (ok + ng) / 2;
        if(check(m)) ok = m;
        else ng = m;
    }
    cout << (ok == k - 1 ? -1 : ok) << endl;
}

