string s, t, S;
bool match[550000];
int mod = 1e9 + 7;
void rolliha(int hash) {
    int hpow = 1;
    for (int i = 0; i < t.length(); i++) { hpow = hpow * hash % mod; }
    int th = 0, Sh = 0;
    for (int i = 0; i < t.length(); i++) {
        th = (th * hash + t[i]) % mod;
        Sh = (Sh * hash + S[i]) % mod;
    }
    for (int i = 0; i < s.length(); i++) {
        if (th != Sh) { match[i] = false; }
        Sh = (Sh * hash + S[i + t.length()] - S[i] * hpow + mod) % mod;
    }
}
int dp[550000];
int dfs(int idx, int depth = 0) {
    if (depth > 550000) {
        cout << -1 << endl;
        exit(0);
    }
    if (!match[idx]) { return 0; }
    if (dp[idx] != 0) { return dp[idx]; }
    return dp[idx] = dfs((idx + t.length()) % s.length(), depth + 1) + 1;
}
signed main() {
    cin >> s >> t;
    while (S.length() < s.length() + t.length()) { S += s; }
    fill(match, match + s.length(), true);
    rolliha(114514), rolliha(1919), rolliha(810);
    int ans = 0;
    for (int i = 0; i < s.length(); i++) { chmax(ans, dfs(i)); }
    cout << ans << endl;
}

#include <bits/stdc++.h>
#include <boost/algorithm/searching/knuth_morris_pratt.hpp>

int main() {
    using namespace std;
    using namespace boost::algorithm;
    string s, t;
    cin >> s >> t;
    unsigned long loop{1}, M{t.size()};
    {
        auto tt = t + t;
        auto it = knuth_morris_pratt_search(tt.begin() + 1, tt.end() - 1, t.begin(), t.end()).first;
        if(it != tt.end() - 1){
            auto l = it - tt.begin();
            t = string(tt.begin(), it);
            loop = M / l;
            M = l;
        }
    }
    {
        auto ss = s + s;
        auto it = knuth_morris_pratt_search(ss.begin() + 1, ss.end() - 1, s.begin(), s.end()).first;
        if(it != ss.end() - 1)s = string(ss.begin(), it);
    }
    unsigned long N{s.size()};
    {
        unsigned long n{(N + M - 1) / N};
        string ss(s.begin(), s.end());
        while(n){
            if(n & 1)s += ss;
            ss += ss;
            n >>= 1;
        }
    }

    vector<unsigned long> morris_pratt_search_result;
    auto morris_pratt_search_all = [&morris_pratt_search_result](auto s, auto t){
        string Q(t + "_" + s);
        unsigned long N{s.size()}, M{t.size()}, L{Q.size()};
        vector<unsigned long> MP(L + 1);
        for(unsigned long i = 1, j = 0; i <= L; MP[i++] = j){
            while(j > 0 && Q[i - 1] != Q[j - 1])j = MP[j - 1];
            if(++j > M && i >= j + M && i < j + N + M)morris_pratt_search_result.push_back(i - j - M);
        }
    };

    morris_pratt_search_all(s, t);
    vector<unsigned long> idx(N);
    for(const auto& i : morris_pratt_search_result)if(i < N)idx[i] = ~0UL;

    auto f = [rec = [&idx, &M, &N](auto f, unsigned long i, unsigned long t, unsigned long k) -> unsigned long{
        if(!idx[i])return 0;
        if(i == t && k)idx[i] = 2 * N;
        else if(!~idx[i])idx[i] = f(f, (i + M) % N, t, 1) + 1;
        return idx[i];
    }](unsigned long n){rec(rec, n, n, 0);};
    for(unsigned long i = 0; i < N; ++i)f(i);

    unsigned long ans{*max_element(idx.begin(), idx.end())};
    if(ans > N)puts("-1");
    else cout << ans / loop << endl;
    return 0;
}

