int dfs(int a){
	if(dp[a]>=0)return dp[a];
	if(dp[a]==-2)return mod;
	dp[a]=-2;
	int ret=0;
	if(FIN[a]==0)return dp[a]=ret;
	ret=dfs((a+L)%b);
	if(ret==mod)return dp[a]=mod;
	return dp[a]=ret+1;
}
