	RollingHash rht(t);
	pair<long long, long long> r = rht.get(1, m);
	int cnt = 0, res = 0;
	int i = 0;
	while(i < 3 * n) {
		pair<long long, long long> p = rh.get(i + 1, i + m);
		if(p == r) {
			++cnt;
			chmax(res, cnt);
			i += m;
		} else {
			cnt = 0;
			i ++;
		}
	}
	if(res * m >= n) {
		cout << - 1 << endl;
		return 0;
	}
	cout << res << endl;
	return 0;
}

