		hs[0] %= mod;
		hs[0] += sv[i%n];
		hs[0] %= mod;
	}

	zep(i, 1, n){
		hs[i] = hs[i-1]*base;
		hs[i] %= mod;
		hs[i] += mod-(bf*sv[(i-1)%n])%mod;
		hs[i] %= mod;
		hs[i] += sv[(i+m-1)%n];
		hs[i] %= mod;
	}

	ht = 0;
	zep(i, 0, m){
		ht *= base;
		ht %= mod;
		ht += tv[i];
		ht %= mod;
	}

	ll ans = 0;
	memset(memo, 0, sizeof(memo));
	zep(i, 0, n){
		ans = max(get_memo(i, 0), ans);
	}

	if(ans >= n){
		ans = -1;
	}
