using namespace std;

class RollingHash {
public:
    vector<int64_t> hs[2], pw[2];
    const int64_t base = 9973;
    const int64_t mod[2] = {1000000007LL, 999999937LL};
    int len = 0;
    RollingHash(const string &s) {
        len = s.size();
        for(int i = 0; i < 2; ++i) {
            hs[i].assign(len + 1, 0);
            pw[i].assign(len + 1, 1);
            for (int j = 0; j < len; ++j) {
                pw[i][j + 1] = pw[i][j] * base % mod[i];
                hs[i][j + 1] = (hs[i][j] * base + s[j]) % mod[i];
            }
        }
    }
    void connect(const string &s) {
        int n = s.size();
        for(int i = 0; i < 2; ++i) {
            hs[i].resize(len + n + 1);
            pw[i].resize(len + n + 1);
            for (int j = len; j < len + n; ++j) {
                pw[i][j + 1] = pw[i][j] * base % mod[i];
                hs[i][j + 1] = (hs[i][j] * base + s[j - len]) % mod[i];
            }
        }
        len += n;
    }
    pair<int64_t, int64_t> hash(const int l, const int r) {
        int64_t t1 = ((hs[0][r] - hs[0][l] * pw[0][r - l]) % mod[0] + mod[0]) % mod[0];
        int64_t t2 = ((hs[1][r] - hs[1][l] * pw[1][r - l]) % mod[1] + mod[1]) % mod[1];
        return make_pair(t1, t2);
    }
};

int main() {
    string S, T; cin >> S >> T;
    while(S.size() < 2 * T.size()) S += S;
    S += S;
    RollingHash s(S), t(T);
    int N = S.size(), M = T.size();
    vector<int> match(N);
    for(int i = 0; i < N - M + 1; ++i) {
        auto shash = s.hash(i, i + M);
        auto thash = t.hash(0, M);
        match[i] = (shash == thash);
    }

    int ans = 0;
    for(int m = 0; m < M; ++m) {
        int cnt = 0;
        for(int i = m; i < N; i += M) {
            if(match[i]) ans = max(ans, ++cnt);
            else cnt = 0;
        }
    }

    bool ng = true;
    for(int i = 0; (i + 1) * M <= s.len; ++i) {
        if(s.hash(i * M, (i + 1) * M) != t.hash(0, M)) ng = false;
    }
    if(ng) ans = -1;
    cout << ans << '\n';
    return 0;
}

