    vector<int> v(s.size());
    for(int i = 0; i < s.size(); ++i)
        v[i] = (s_hash.get(i, i + t.size()) == t_hash);
    for(int i = 0; i < s.size(); ++i)
        if(v[i] && v[(i + t.size()) % s.size()] && !u.Unite(i, (i + t.size()) % s.size())){
