    while (s.size() < 2 * t.size() + 1) {
        s += origs;
    }
    KMP kmp(s);
    vi e = kmp.match(t);
    vvi edges(ns);
    for (auto &ee : e) {
        if (ee >= ns)
            continue;
        edges[ee].push_back((ee + t.size()) % ns);
    }

    int ret = 0;
    vi dp(ns, -1);
    for (int i = 0; i < ns; ++i) {
        chmax(ret, dfs(i, dp, edges, 0));
    }
