using namespace std;

// make the "partial match" table
bool MP(vector<int> &table, string s) {
    // The size of table should be s.size() + 1
    if (table.size() != s.size() + 1) return false;

    table[0] = -1;
    int j = -1;
    for (int i = 0; i < s.size(); i++) {
        while (j >= 0 && s[i] != s[j]) j = table[j];
        j++;
        table[i + 1] = j;
    }

    return true;
}

void KMP_search(string S, string W, vector<int> MP_table, vector<bool> &match){
    fill(match.begin(), match.end(), false);
    int i = 0;
    int m = 0;
    while (m + i < S.size()) {
        if (S[m + i] == W[i]) i++;
        else {
            m = m + i - MP_table[i];
            if (i > 0) i = MP_table[i];
        }
        if (i == W.size()) {
            match[m] = true;
            m = m + i - MP_table[i];
            i = MP_table[i];
        }
    }
}

