vector<vector<ll>> rolling_hash(string s, int l, char st='0') {
  ll m1 = pow(10,9)+7, m2 = 998244353, mul = pow(10,5);
  ll tm1 = 1, tm2 = 1; rep(i,l) { tm1 = (tm1*mul)%m1; tm2 = (tm2*mul)%m2; }
  vector<vector<ll>> result;
  ll n1 = 0, n2 = 0;
  if (s.size()>=l) {
    rep(i,s.size()-l+1) {
      if (i==0) rep(i,l) { n1 = (n1*mul+(s[i]-st))%m1; n2 = (n2*mul+(s[i]-st))%m2; }
      else { n1 = ((n1*mul-tm1*(s[i-1]-st)+(s[i+l-1]-st))%m1+m1)%m1; n2 = ((n2*mul-tm2*(s[i-1]-st)+(s[i+l-1]-st))%m2+m2)%m2; }
      result.push_back((vector<ll>){n1,n2});
    }
  }
  else cout << "error: s.length()<l" << endl;
  return result;
}

