class KMP{
private:
  string p;
  vector<int> table;

public:
  KMP(const string &p): p(p), table(p.size()+1, 0){
    table[0] = -1;
    int j = -1;

    FORE(i,1,p.size()){
      while(j >= 0 and p[i-1] != p[j]) j = table[j];
      table[i] = ++j;
    }
  }

  vector<int> find(const string &s){
    int m = p.size();
    vector<int> ret;

    int j = 0;
    REP(i,s.size()){
      while(j >= 0 and p[j] != s[i]) j = table[j];

      if(++j >= m){
        ret.push_back(i-m+1);
        j = table[j];
      }
    }

    return ret;
  }
};



bool tsort_priority_queue(const vector<vector<int>> &graph, vector<int> &&ret = {}){
  int n = graph.size();
  vector<int> indeg(n);
  REP(i,n){
    for(auto j : graph[i]){
      ++indeg[j];
    }
  }
  priority_queue<int,vector<int>,greater<int>> q;
  REV(i,n-1,0){
    if(indeg[i] == 0) q.push(i);
  }

  while(!q.empty()){
    int cur = q.top(); q.pop();
    ret.push_back(cur);
    for(auto next : graph[cur]){
      --indeg[next];
      if(indeg[next]==0){
        q.push(next);
      }
    }
  }

  return (int)ret.size() == n;
}

int dp[1001000];
bool used[1001000];

int dfs(vector<vector<int>> &graph, int cur){
  if(used[cur]) return dp[cur];
  used[cur] = true;

  for(auto next : graph[cur]){
    chmax(dp[cur], dfs(graph, next)+1);
  }
  return dp[cur];
}

