struct RollingHash {
    int n;
    string s;
    const ll mod1 = 1000000007LL, mod2 = 1000000009LL, base1 = 1007LL,
             base2 = 1009LL;
    vector<ll> hash1, hash2, pow1, pow2;
    RollingHash(const string &str) {
        s = str;
        n = str.length();
        hash1.resize(n + 10);
        hash2.resize(n + 10);
        pow1.resize(n + 10, 1);
        pow2.resize(n + 10, 1);
        for (int i = 0; i < n; i++) {
            hash1[i + 1] = (hash1[i] + s[i]) * base1 % mod1;
            hash2[i + 1] = (hash2[i] + s[i]) * base2 % mod2;
            pow1[i + 1] = pow1[i] * base1 % mod1;
            pow2[i + 1] = pow2[i] * base2 % mod2;
        }
    }
    pair<ll, ll> get(int l, int r) {
        ll t1 = (hash1[r] - hash1[l] * pow1[r - l] % mod1 + mod1) % mod1;
        ll t2 = (hash2[r] - hash2[l] * pow2[r - l] % mod2 + mod2) % mod2;
        return make_pair(t1, t2);
    }
};
