string s, t;
int m, n, pre[2000200], match[2000200], f[2000200];

void calcPre()
{
  int i = 0, j = -1;
  pre[0] = -1;
  while (i < n)
  {
    while (j >= 0 && t[i] != t[j])
      j = pre[j];
    pre[++i] = ++j;
  }
}

void findMatch()
{
  int i = 0, j = 0;
  while (i < s.size())
  {
    while (j >= 0 && s[i] != t[j])
      j = pre[j];
    i++;
    j++;
    if (j == n)
    {
      j = pre[j];
      match[(i - n) % m] = 1;
    }
  }
}

int go(int x)
{
  if (f[x] >= 0)
    return f[x];
  if (!match[x])
    return 0;
  return f[x] = go((x + n) % m) + 1;
}

int main()
{
  cin >> s >> t;
  m = s.size();
  n = t.size();
  while (s.size() < m + n)
    s += s.substr(0, m);

  calcPre();
  findMatch();

  int ans = 0, found = 0, hasMatch = 0;
  memset(f, -1, sizeof f);
  for (int i = 0; i < m; i++)
  {
    hasMatch |= match[i];
    if (match[i] && !match[(i - n + m) % m])
    {
      found = 1;
      ans = max(ans, go(i));
    }
  }

  cout << (!found && hasMatch ? -1 : ans) << endl;
}

