bool is_ok[MAX_LEN], is_visited[MAX_LEN];
int period[MAX_LEN];

void dfs(int idx) {
    is_visited[idx] = true;
    period[idx] = -1;
    int next_idx = (idx + M) % N;
    if (!is_ok[next_idx]) {
        period[idx] = 1;
        return;
    }
    if (is_visited[next_idx]) {
        if (period[next_idx] < 0) {
            period[idx] = -1;
            return;
        }
        else {
            period[idx] = period[next_idx] + 1;
            return;
        }
    }
    dfs(next_idx);
    if (period[next_idx] >= 0) period[idx] = period[next_idx] + 1;
}

