		int n = s.size();
		int len = 0;
		for(int i=1;i<n;i++){
			while(len && s[i] != s[len]){
				len = fail[len-1];
			}
			if(s[i] == s[len]){
				len++;
			}
			fail[i] = len;
		}
	}

	int occers(string s,string t){
		int n = s.size();
