// make the "partial match" table
bool MP(vector<int> &table, string s) {
    // The size of table should be s.size() + 1
    if (table.size() != s.size() + 1) return false;

    table[0] = -1;
    int j = -1;
    for (int i = 0; i < s.size(); i++) {
        while (j >= 0 && s[i] != s[j]) j = table[j];
        j++;
        table[i + 1] = j;
    }

    return true;
}

