    fill(match.begin(), match.end(), false);
    int i = 0;
    int m = 0;
    while (m + i < S.size()) {
        if (S[m + i] == W[i]) i++;
        else {
            m = m + i - MP_table[i];
            if (i > 0) i = MP_table[i];
        }
        if (i == W.size()) {
            match[m] = true;
            m = m + i - MP_table[i];
            i = MP_table[i];
        }
    }
}

