vector<int> z_algo(string s){
    int n = s.size();
    vector<int> res(n);
    res[0] = 0;
    int now = 0, l = 0;
    for(int i = 1;i < n;i++){
        res[i] = now-i;
        if(now-i >= 0 && res[i-l] != res[i])res[i] = min(res[i-l], res[i]);
        else{
            res[i] = max(res[i], 0);
            while(res[i] < n && s[i + res[i]] == s[res[i]])res[i]++;
            now = i + res[i];
            l = i;
        }
    }
    return res;
}

