        if (used[to]) {
            return memo[v] = INF;
        }
        if (pos.count(to)) {
            return memo[v] = dfs(to) + 1;
        } else {
            return memo[v] = 1;
        }
    }

    void solve(std::istream& cin, std::ostream& cout) {
        cin >> s >> t;

        u = s;
        while (u.size() < s.size() + t.size()) {
            u += s;
        }

        auto v = kmp(u, t);
        REP(i, v.size()) pos.insert(v[i] % s.size());

        used = vector<bool>(s.size());
        memo = vector<int>(s.size(), -1);

        for (auto i : pos) {
            dfs(i);
        }

        int ans = 0;
        REP(i, s.size()) {
            ans = max(ans, memo[i]);
        }
        if (ans >= INF) ans = -1;

        cout << ans << endl;
    }
};


