// KMP法 S内でpが現れるindexを列挙する
struct KMP {
    string pat; // pのcopy
    vector<int> fail;

    // constract : p[0,i-1]の接頭辞と接尾辞が最大で何文字一致するかを前処理する (fail[i]=iは除く)
    KMP(const string &p) { init(p); }
    void init(const string &p) {
        pat = p; // pのcopy
        int m = (int)pat.size();
        fail.resize(m+1);
        fail[0] = -1;
        fail[1] = 1;
        int j = -1;
        for (int i = 0; i < m; i++) {
            while (j >= 0 && pat[i] != pat[j]) j = fail[j];
            j++;
            fail[i+1] = j;
        } // fail[0]=-1, fail[1]=0;
    }

    // the period of p[0:i]
    int period(int i) { return i - fail[i]; }

    // the index i such that S[i:] has the exact prefix p
    vector<int> match(const string &S) {
        int n = (int)S.size(), m = (int)pat.size();
        vector<int> res;
        for (int i = 0, k = 0; i < n; i++) {
            while (k >= 0 && S[i] != pat[k]) k = fail[k]; // k文字目まで一致している状態から再スタート
            k++;
            if (k >= m) res.push_back(i - m + 1), k = fail[k]; // k文字目まで一致している状態から再スタート
        }
        return res;
    }
};

