vector<int> Zalgorithm(const string &str) {
  vector<int> ret(str.size());
  ret[0] = str.size();
  int i = 1, j = 0;
  while (i < str.size()) {
    while (i+j < str.size() && str[j] == str[i+j]) ++j;
    ret[i] = j;
    if (j == 0) {
      ++i;
      continue;
    }
    int k = 1;
    while (i+k < str.size() && k+ret[k] < j) {
      ret[i+k] = ret[k];
      ++k;
    }
    i += k; j -= k;
  }
  return ret;
}

bool eternity;
vb seen, visited;

void dfs(vi &ans, const vb &portion, string &s, string &t, int v) {
  seen[v] = true;
  if (portion[v]) {
    int nv = (v + t.size()) % s.size();
    if (seen[nv] && !visited[nv]) {
      eternity = true;
      return;
    }
    if (!visited[nv]) {
      dfs(ans, portion, s, t, nv);
      if (eternity) return;
    }
    ans[v] = ans[nv] + 1;
  }
  visited[v] = true;
}

void solve() {
  string s, t; cin >> s >> t;

  vi Zt = Zalgorithm(t);

  vb portion(s.size(), false);
  int idx = 0, cnt = 0;
  while (idx < s.size()) {
    while (cnt < t.size() && s[(idx+cnt)%s.size()] == t[cnt]) {
      ++cnt;
    }
    if (cnt == 0) {
      ++idx;
      continue;
    }
    if (cnt == t.size()) {
      portion[idx] = true;
    }
    int move = 1;
    while (idx+move < s.size() && move+Zt[move] < cnt) {
      ++move;
    }
    idx += move; cnt -= move;
  }

  vi ans(s.size(), 0);
  eternity = false;
  seen.assign(s.size(), false);
  visited.assign(s.size(), false);

  rep(i,s.size()) {
    if (seen[i]) continue;
    dfs(ans, portion, s, t, i);
    if (eternity) {
      cout << -1 << endl;
      return;
    }
  }

  cout << *max_element(all(ans)) << endl;
  return;
}

