        if (kmp.pre[ i ] == t.size()) v.push_back(i);
    }
    if (alwaysMatching(v,t.size()))
    {
        io.WL(-1);
        return 0;
    }
    int ans = 0, cnt = 0,lst=0,m=t.size();
    for (int i = 0; i < v.size(); i++)
    {
