  const usize m = t.size();
  while (s.size() < m) {
    s = s + s;
  }
  const usize n = s.size();
  s = s + s;
  const hash sh(s.cbegin(), s.cend());
  const u64 th = hash(t.cbegin(), t.cend())(0_z, m);
  std::vector<usize> next(n, n), prev(n, n);
  for (const auto i : rep(0_z, n)) {
    if (sh(i, i + m) == th) {
      next[i] = (i + m) % n;
      prev[next[i]] = i;
    }
  }
  usize r_cnt = 0_z;
  usize ans = 0_z;
  for (const auto i : rep(0_z, n)) {
    if (prev[i] == n) {
