      usize count = 0_z;
      usize v = next[i];
      while (v != n) {
        ++r_cnt;
        v = next[v];
        ++count;
      }
      ans = std::max(ans, count);
    }
  }
  if (r_cnt == n) {
    std::cout << ans << std::endl;
  } else {
