vector<int> topological_sort(const vector<vector<int>>& graph){
  // if graph is not DAG, return {}
  // else topological sorted vertices
  int N = graph.size();
  stack<int> st;
  vector<int> h(N), res;
  for(int i = 0; i < N; i++)
    for(auto& v: graph[i]) h[v]++;
  for(int i = 0; i < N; i++)
    if(h[i] == 0) st.push(i);
  while(st.size()) {
    int u = st.top(); st.pop();
    res.push_back(u);
    for(auto& v: graph[u]){
      h[v]--;
      if(h[v] == 0) st.push(v);
    }
  }
  if(res.size() != N) res.clear();
  return res;
}

class RollingHash
{
  using ull = unsigned long long;
  ll N;
  const ull MASK30 = (1UL << 30) - 1;
  const ull MASK31 = (1UL << 31) - 1;
  const ull MOD = (1UL << 61) - 1;
  const ull POSITIVIZER = MOD * ((1UL << 3) - 1);
  static ull Base;
  static vector<ll> powMemo;
  vector<ull> dat;
public:
  void init(){
    if(powMemo.size() < N) {
      ll from = powMemo.size();
      powMemo.resize(N);
      powMemo[0] = 1;
      for (int i = from; i < N; i++) if(i != 0)
        powMemo[i] = CalcMod(Mul(powMemo[i - 1], Base));
    }
  }
  RollingHash(){}
  RollingHash(string s): N(s.size()), dat(s.size()+1)
  {
    init();
    for (int i = 0; i < N; i++)
      dat[i + 1] = CalcMod(Mul(dat[i], Base) + s[i]);
  }

  ull hash(int l, int r)
  {
    return CalcMod(dat[r] + POSITIVIZER - Mul(dat[l], powMemo[r-l]));
  }

  bool match(int l1, int r1, int l2, int r2){
    return hash(l1, r1) == hash(l2, r2);
  }

  ull Mul(ull l, ull r)
  {
    long long lu = l >> 31;
    long long ld = l & MASK31;
    long long ru = r >> 31;
    long long rd = r & MASK31;
    long long middleBit = ld * ru + lu * rd;
    return ((lu * ru) << 1) + ld * rd + ((middleBit & MASK30) << 31) + (middleBit >> 30);
  }

  ull CalcMod(ull val)
  {
    val = (val & MOD) + (val >> 61);
    if (val > MOD) val -= MOD;
    return val;
  }
};
