void getFail(char *P, int *f) {
	int m = strlen(P);
	f[0] = f[1] = 0;
	for (int i = 1; i < m; ++i) {
		int j = f[i];
		while (j && P[i] != P[j]) j = f[j];
		f[i+1] = P[i] == P[j] ? j+1 : 0;
	}
}

int find(char *T, char *P, int *f) {
	int n = strlen(T), m = strlen(P), j = 0;
	getFail(P, f);
	for (int i = 0; i < n; ++i) {
		while (j && P[j] != T[i]) j = f[j];
		if (P[j] == T[i]) j++;
		if (j == m) return 1;
	}
	return 0;
}

int find2(char *T, char *P, int *f) {
	int n = strlen(T), m = strlen(P), j = 0;
	getFail(P, f);
	int mx = 0, cur = 0, pre = -1e9;
	for (int i = 0; i < n; ++i) {
		while (j && P[j] != T[i]) j = f[j];
		if (P[j] == T[i]) j++;
		if (j == m) {
            int pos = i-m+1;
            if (pos - pre == m) {
                cur++;
                pre = pos;
            } else {
                mx = max(mx, cur);
                cur = 1;
                pre = pos;
            }
		}
	}
	mx = max(mx, cur);
	return mx;
}


