int tz[500005];
int Z[3600005], z[3600005];
int dp[3600005];

void z_algorithm(string s, int z[])
{
	z[0] = s.size();

	int x = 0, y = 0;
	for(int i = 1; i < s.size(); i++){
		if(i > y){
			z[i] = 0;
			for(int j = 0; j < s.size(); j++){
				if(i+j > s.size() || s[i+j] != s[j]) break;
				z[i]++;
			}
			x = i, y = i + z[i] - 1;
		}
		else if(i + z[i-x] <= y) z[i] = z[i-x];
		else{
			z[i] = y-i+1;
			for(int j = y-i+1; j < s.size(); j++){
				if(i+j > s.size() || s[i+j] != s[j]) break;
				z[i]++;
			}
			x = i, y = i + z[i] - 1;
		}
	}
}

int main(void)
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> s >> t;

	z_algorithm(t, tz);
	int p = t.size();
	for(int i = 1; i < t.size(); i++){
		if(t.size() % i == 0 && tz[i] == t.size()-i){
			p = i;
			break;
		}
	}
	//for(int i = 0; i < t.size(); i++) cout << tz[i] << " "; cout << endl;
	llint mul = t.size() / p;
	t = t.substr(0, p);

	string tmp = s;
	llint rep = (t.size()+s.size()-1)/s.size(); s = "";
	for(int i = 0; i < rep; i++) s += tmp;

	int n = s.size() * 2, m = t.size();
	string S = t + "#" + s + s;
	z_algorithm(S, Z);

	for(int i = 0; i < n; i++) z[i] = Z[i+m+1];

	for(int i = 0; i < n; i++){
		if(z[i] == m && i+m < n) dp[i+m] = max(dp[i+m], dp[i] + 1);
	}
	int ans = 0;
	for(int i = 0; i < n; i++) ans = max(ans, dp[i]);
	if(s.size() % m == 0 && ans >= n / m - 1) ans = -1;
	if(ans != -1) ans /= mul;
	cout << ans << endl;

	return 0;
}

