            i++;
            p++;
        } else if (p == 0) {
            //パターン先頭文字が不一致
            i++;
        } else {
            p = table[p];
        }
        if (p == pattern.length()) {
            match[i - p] = true;
            p = table[p] + 1;
        }
    }

    int ans = 0;
    int gcd = Gcd(pattern.length(), target.length());

    for (int start = 0; start < gcd; ++start) {
        int cnt = 0;
        int maxv = 0;
        for (int at = start; at != start + 2 * target.length() * pattern.length() / gcd; at += pattern.length()) {
