vector<int> Z_Fun(string req) {
  vector<int> Z(req.size(), 0);
  int L = 0, R = 0, K;
  for (int i = 1; i < (int)req.size(); ++i) {
    if(i > R) {
      L = R = i;
      while(R < (int)req.size() && req[R] == req[R - L])
        ++R;
      Z[i] = R - L;
      --R;
    } else {
      K = i - L;
      if(Z[K] < R - i + 1)
        Z[i] = Z[K];
      else {
        L = i;
        while(R < (int)req.size() && req[R] == req[R - L])
          ++R;
        Z[i] = R - L;
        --R;
      }
    }
  }
  return Z;
