            v.pb(i-j);
            j = lps[j - 1]; 
        } 
		else if (i < N && pat[j] != txt[i]) { 
            if (j != 0) 
                j = lps[j - 1]; 
            else
                i = i + 1; 
        } 
    } 
} 


