bool dfs(ll now, ll root) {
    st.emplace(now);
    used[now] = true;
    bool res = true;
    FOREACH(to, G[now]) {
        if(res == false) break;
        if(to == root) return false;
        res &= dfs(to, root);
    }
    return res;
}

