struct KMP{

    string s;
    string t;
    int s_size,t_size;
    vector<bool> match;
    vector<int> table;

    KMP(string a, string b){
        s = a;
        t = b;
        s_size = s.size();
        t_size = t.size();
        match.resize(s.size());
        REP(i,s_size) match[i] = false;

        table.resize(t_size + 1);

        make_table();
        compute_match();
    }


    void make_table();

    void compute_match();

};


void KMP::make_table(){
    table[0] = -1;
    table[1] = 0;

    int j = 0;
    int i = 2;
    while(i < t.size() + 1){

        if(t[i-1] == t[j]){
            j += 1;
            table[i] = j;
        }
        else if(j > 0){
            j = table[j];
            i -= 1;
        }

        i += 1;
    }
}


void KMP::compute_match(){
    int m = 0,i = 0;
    int cnt = 0;

    while(m  < s_size){
        if(s[(m + i) % s_size] != t[i]){
            m = m + i - table[i];
            i = table[i];
        }

        i += 1;
        if(i == t.size()){
            match[m] = true;
            m = m + i - table[i];
            i = table[i];
        }
    }


}


int t_size,s_size;

int dfs(vector<bool>& match,int roop[],int x,int cnt){
    cnt += 1;
    if(cnt == s_size){
        roop[x] = s_size;
        return s_size;
    }
    if(match[x]){
        roop[x] = dfs(match,roop, (x + t_size) % s_size ,cnt);
    }
    else{
        roop[x] = 0;
    }
    return roop[x] + 1;
}

