bool memo[2000055] = {0};
long long used[2000050] = {0};
long long tsize, ssize;

long long solve();

int main() {
  cin >> s >> t;
  tsize = t.size();
  ssize = s.size();
  while((long long)ns.size() < (long long)t.size() * 3)
    ns += s;
  rh[0] = RollingHash(ns);
  rh[1] = RollingHash(t);
