typedef long long hash_type;

struct rolling_hash {
	int n;
	hash_type mod1, mod2, base1, base2;
	vector <hash_type> hash1, hash2, pow1, pow2;
	rolling_hash() { clear(); }
	rolling_hash(const rolling_hash &x) { *this = x; }
	rolling_hash(const string &s) { init(s); }
	inline void clear() {
		mod1 = 1e9 + 7;
		mod2 = 1e9 + 9;
		base1 = 1007;
		base2 = 1009;
		hash1.clear();
		hash2.clear();
		pow1.clear();
		pow2.clear();
	}
	inline void init(const string &s){
		clear();
		n = s.length();
		hash1.assign(n + 1, 0);
		hash2.assign(n + 1, 0);
		pow1.assign(n + 1, 1);
		pow2.assign(n + 1, 1);
		for (int i = 0; i < n; ++i) {
			hash1[i+1] = (hash1[i] * base1 + s[i]) % mod1;
			hash2[i+1] = (hash2[i] * base2 + s[i]) % mod2;
			pow1[i+1] = (pow1[i] * base1) % mod1;
			pow2[i+1] = (pow2[i] * base2) % mod2;
		}
	}
	// [l, r)
	inline pair <hash_type, hash_type> get_hash(int l, int r){
		hash_type h1 = ((hash1[r] - hash1[l] * pow1[r-l]) % mod1 + mod1) % mod1;
		hash_type h2 = ((hash2[r] - hash2[l] * pow2[r-l]) % mod2 + mod2) % mod2;
		return make_pair(h1, h2);
	}

	inline bool match(int l1, int r1, int l2, int r2){
		if (r1 > n || r2 > n) return false;
		return get_hash(l1, r1) == get_hash(l2, r2);
	}
	inline bool match(int l1, int l2, int k){
		return match(l1, l1 + k, l2, l2 + k);
	}
	inline int lcp(int l1, int l2){
		int ok = 0, ng = n;
		while (ng - ok > 1){
			int m = (ok + ng) / 2;
			if (match(l1, l2, m)) ok = m;
			else ng = m;
		}
		return ok;
	}
};

