pair<int, int> Catch(int x1, int y1, int x2, int y2)
{
    int dx = abs(x2 - x1);
    int dy = abs(y2 - y1);
    if (dx > 2 * k || dy > 2 * k)
    {
        return {-MOD, -MOD};
    }
    int mx1 = x1 + y1;
    int my1 = x1 - y1;
    int mx2 = x2 + y2;
    int my2 = x2 - y2;
    int h[4] = {mx1 - k, mx1 + k, mx2 - k, mx2 + k};
    sort(h, h + 4);
    int w[4] = {my1 - k, my1 + k, my2 - k, my2 + k};
    sort(w, w + 4);
    int mX = h[1];
    int mY = w[1];
    int x = (mX + mY) / 2;
    int y = (mX - mY) / 2;
    return {x, y};
}

