    op(ll, +=);    op(ll, -=);    op(ll, *=);    op(ll, /=);    op(ll, %=);    op(ll, +);    op(ll, -);    op(ll, *);    op(ll, /);    op(ll, %);    op(bool, ==);    op(bool, !=);    op(bool, <);    op(bool, <=);    op(bool, >);    op(bool, >=);
#undef op
    template<class T>  ll operator<<=(T r) { return v *= p10[r]; }
    template<class T>  ll operator<<(T r) { return v * p10[r]; }
    template<class T>  ll operator>>=(T r) { return v /= p10[r]; }
