vi dijkstra2(const graph<int> &g, int s, int init_value = -1) {    if (!(0 <= s && s < g.n)) {        debugline("dijkstra");        deb(s, g.n);        ole();    }    int initValue = MAX(int);    vi dis(g.n, initValue);    radixheap<int> q;    dis[s] = 0;    q.push(0, s);    while (!q.empty()) {        int nowc, i;        tie(nowc, i) = q.pop();        if (dis[i] != nowc)continue;        for (auto &&e  : g.g[i]) {            int to = e.t;            int c = nowc + e.c;            if (dis[to] > c) {                dis[to] = c;                q.push(dis[to], to);            }        }    }    /*基本、たどり着かないなら-1*/   for (auto &&d :dis) if (d == initValue)d = init_value;    return dis;}
template<class T> vector<T> dijkstra(const graph<T> &g, int s, int init_value = -1) {    if (!(0 <= s && s < g.n)) {        debugline("dijkstra");        deb(s, g.n);        ole();    }    T initValue = MAX(T);    vector<T> dis(g.n, initValue);    priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;    dis[s] = 0;    q.emplace(0, s);    while (q.size()) {        T nowc = q.top().fi;        int i = q.top().se;        q.pop();        if (dis[i] != nowc)continue;        for (auto &&e  : g.g[i]) {            int to = e.t;            T c = nowc + e.c;            if (dis[to] > c) {                dis[to] = c;                q.emplace(dis[to], to);            }        }    }    /*基本、たどり着かないなら-1*/    for (auto &&d :dis) if (d == initValue)d = init_value;    return dis;}
template<class T> vector<vector<T>> dijkstra_all(const graph<T> &g, int init_value = -1){    vector<vector<T>> dis(g.n);    rep(i, g.n){        dis[i] = dijkstra(g,i,init_value);    }    return dis;}
