vector<int> generate_divisors (int n) {
	vector<int> ans;
	for (int i = 1; i * i <= n; ++i) {
		if (n % i)
			continue; 
		ans.push_back(i);
		if (i * i != n) ans.push_back(n / i);
	}
	return ans;
}
