		}
	}
	s += s;
	h[0] = h2[0] = 0; 
    for (int i = 0; i < (int) s.size(); i++)
        h[i+1] = (h[i] + (s[i] - 'a' + 1) * p_pow[i]) % m, h2[i+1] = (h2[i] + (s[i] - 'a' + 1) * p_pow2[i]) % m2; 
    int lo = 0, hi = 1e6 + 55;
    int ans = 0;
    while (lo < hi - 1) {
    	int mid = (lo + hi) >> 1;
    	if (rabin_karp(t, s, mid)) {
    		lo = mid;
    	}
