#include <bits/stdc++.h>
using namespace std;
const long long int MOD = (1LL<<31) - 1;
const long long int base1 = 48271;
const long long int base2 = 69621;
vector<int> match;

void contain(string a, string b, long long int BASE){// find a from b
    if(a.length() > b.length()) return ;

    long long int powB = 1;
    for(int i=0; i<a.length(); i++){
        powB *= BASE;
        powB %= MOD;
    }

    // Hash
    long long int hash_a = 0;// a[0] * BASE^(la-1) + ... + a[la-2] * BASE + a[la-1] 
    long long int hash_b = 0;
    for(int i=0; i<a.length(); i++){
        hash_a = hash_a * BASE + a[i];
        hash_b = hash_b * BASE + b[i];// hash of b.substr(0, a.length())

        hash_a %= MOD;
        hash_b %= MOD;
    }

    // Roll
    for(int i=0; i+a.length()<=b.length(); i++){
        if(hash_a == hash_b){// b.substr(i,la) == a
            match[i] += 1;
        }

        if(i + a.length() < b.length()){
            hash_b = hash_b * BASE + b[i+a.length()] - b[i] * powB;
            hash_b = (hash_b % MOD + MOD) % MOD;
        }
    }
    return ;// i + a.length() == b.length() : coudln't find
}

vector<vector<int>> graph, inv_graph;
vector<int> dp;
vector<bool> visited;

long long int DFS(int v){
    if(visited[v] == true) return dp[v];
    visited[v] = true;

    if(graph[v].empty() == false){
        int len = DFS(graph[v][0]);
        if(len != -1) return dp[v] = len + 1;
        else return -1;
    }

    return dp[v] = 0;// empty
}

