int calc(std::string s_, std::string t) {
	auto s = t + "$" + s_;
	V<int> z(s.size(), 0);
	z[0] = s.size();
	int i = 1, j = 0;
	while (i < s.size()) {
		while (i + j < s.size() && s[j] == s[i + j]) ++j;
		z[i] = j;
		if (j == 0) { ++i; continue; }
		int k = 1;
		while (i + k < s.size() && k + z[k] < j) z[i + k] = z[k], ++k;
		i += k; j -= k;
	}

	V<int> dp(s.size() + 1, 0);
	int ans = 0;
	FOR(i, t.size() + 1, s.size()) {
		if (z[i] == t.size()) {
			CHMAX(dp[i + t.size()], dp[i] + 1);
		}
	}
	REP(i, dp.size()) CHMAX(ans, dp[i]);
	return ans;
}

signed main() {
	INIT;

	VAR(std::string, s, t);

	auto S(s);
	while (S.size() < std::max(3*s.size(), t.size())) S += s;

	int t0 = calc(S, t);
	S += S;
	int t1 = calc(S, t);
	if (t0 == t1) {
		OUT(t0)BR;
	}
	else {
		OUT(-1)BR;
	}

	return 0;
}

