vector<int> buildKMPFailTable(const string& t) {
	int m = sz(t);
	vector<int> fail(m + 1);
	int j = fail[0] = -1;
	for (int i = 1; i <= m; i++) {
		while (j >= 0 && t[j] != t[i - 1]) j = fail[j];
		fail[i] = ++j;
	}
	return fail;
}

int solve(string s, string t) {
	int originalSSize = sz(s);
	while (sz(s) < ten(6) * 2) s += s;
	auto fail = buildKMPFailTable(s);

	vector<int> ok;
	for (int i = 0, k = 0; i < originalSSize + sz(t) - 1; i++) {
		while (k >= 0 && t[k] != s[i]) k = fail[k]; 
		k++;
		if (i >= sz(t) - 1) {
			ok.push_back(k >= sz(t));
		}
	}
	int g = gcd(sz(s), sz(t));
	int ans = 0;
	vector<bool> used(sz(ok));
	FOR(i, sz(used)) {
		if (used[i]) continue;
		int x = i;
		vector<int> cur;
		while (!used[x]) {
			used[x] = true;
			cur.push_back(ok[x]);
			x = (x + sz(t)) % sz(ok);
		}
		const int xx = sz(cur);
		FOR(i, xx) cur.push_back(cur[i]);
		int cnt = 0;
		for (auto c : cur) {
			if (c == 1) cnt++;
			if (c == 0) cnt = 0;
			ans = max(ans, cnt);
		}
		if (cnt == sz(cur)) return -1;
	}

	return ans;
}

int main() {
	string s, t; reader(s, t);

	int ans = solve(s, t);
	writerLn(ans);

	return 0;
}

