const int MOD = 1000000007;
const int INF = 0x3f3f3f3f3f3f3f3f;
const double EPS = 1e-10;

struct RollingHash {
  const int bs = 9973;
  const vector<int> m = {999999937LL, 1000000007LL};
  string S;
  vector<int> h[2], p[2];

  RollingHash() {}
  RollingHash(const string &cs) { init(cs); }
  void init(const string &cs) {
    S = cs;
    int n = S.size();
    for (int it = 0; it < 2; it++) {
      h[it].assign(n+1,0);
      p[it].assign(n+1,1);
      for (int i = 0; i < n; i++) {
        h[it][i+1] = (h[it][i]*bs + S[i]) % m[it];
        p[it][i+1] = p[it][i]*bs % m[it];
      }
    }
  }
  // S[left:right) のハッシュ値を取得
  inline int get(int l, int r, int id) const {
    int res = h[id][r] - h[id][l] * p[id][r-l] % m[id];
    if (res < 0) res += m[id];
    return res;
  }
  // S[a:] と S[b:] のLCPの長さを取得
  inline int getLCP(int a, int b) const {
    int len = min(S.size()-a,S.size()-b);
    int lo = -1, hi = len+1;
    while (hi-lo > 1) {
      int mid = (lo+hi)/2;
      if (get(a,a+mid,0) != get(b,b+mid,0)) hi = mid;
      else if (get(a,a+mid,1) != get(b,b+mid,1)) hi = mid;
      else lo = mid;
    }
    return lo;
  }
  // S[a:] と T[b:] のLCPの長さを取得
  inline int getLCP(const RollingHash &T, int a, int b) const {
    int len = min(S.size()-a,T.S.size()-b);
    int lo = -1, hi = len+1;
    while (hi-lo > 1) {
      int mid = (lo+hi)/2;
      if (get(a,a+mid,0) != T.get(b,b+mid,0)) hi = mid;
      else if (get(a,a+mid,1) != T.get(b,b+mid,1)) hi = mid;
      else lo = mid;
    }
    return lo;
  }
};

