// 蟻本でみた、ローリングハッシュを試してみる
vector<bool> check_eq(string s, string t) {
  int s_size = s.size();
  int t_size = t.size();
  vector<bool> result(s_size - t_size + 1);
  // modは2**64だと簡単に衝突する。また、複数用意して衝突しづらくする
  // http://hos.ac/blog/#blog0003 より
  vector<uint64_t> mods{1000000007, 999999937};
  uint64_t b = 10007;
  vector<uint64_t> bns(mods.size(), 1);
  vector<uint64_t> s_hash(mods.size(), 0);
  vector<uint64_t> t_hash(mods.size(), 0);
  int m_size = mods.size();

  for (int i = 0; i < t_size; i++) {
    for(int j = 0; j < m_size; j++) {
      const auto& m = mods[j];
      bns[j] = (bns[j] * b) % m;
    }
  }

  int i = 0;
  for(; i < t_size; i++) {
    for(int j = 0; j < m_size; j++) {
      const auto& m = mods[j];
      t_hash[j] = ((t_hash[j] * b) % m + t[i]) % m;
      s_hash[j] = ((s_hash[j] * b) % m + s[i]) % m;
    }
  }

  for(;;i++) {
    bool current_result = true;
    for(int j = 0; j < m_size; j++) {
      current_result &= s_hash[j] == t_hash[j];
    }

    result[i - t_size] = current_result;

    if (i >= s_size) {
      break;
    }

    for(int j = 0; j < m_size; j++) {
      const auto& m = mods[j];
      s_hash[j] = ((s_hash[j] * b) % m + s[i] - s[i - t_size] * bns[j]) % m;
    }
  }

  return result;
}

int main() {
  string s,t,s_origin;
  cin >> s >> t;
  s_origin = s;

  while(s.size() < t.size()+s_origin.size()) {
    s += s_origin;
  }

  vector<bool> eqs = check_eq(s,t);

  int s_origin_size = s_origin.size();
  int t_size = t.size();

  for (int i = 0; i < s_origin_size; i++) {
    if (eqs[i] && (s.substr(i, t_size) != t)) {
      cout << s_origin << " " << s << " " << t << " " << i << " " << (s.substr(i, t_size)) << " " << t << " " << eqs[i] << endl;
      throw 1;
    }
  }

  return 0;
}

