// Z-Algorithm
// Z_array の構築, 「S と S[i:|S|-1] の最長共通接頭辞の長さ」
vector<int> Z_array(string S){
    int n = S.size();
    vector<int>res(n, 0);
    res[0] = -1;
    int i = 1, j = 0;
    while (i < S.size()) {
        while (i+j < n && S[j] == S[i+j]) ++j;
        res[i] = j;
        if (j == 0) { ++i; continue; }
        int k = 1;
        while (i+k < S.size() && k+res[k] < j) res[i+k] = res[k], ++k;
        i += k; j -= k;
    }
    return res;
}

int Z_Algorithm(string word, string S){
    string concat = word + "$" + S;
    auto v = Z_array(concat);
    int res = 0;
    for (int i = word.size() + 1; i < concat.size(); ++i) {
        res = max(res, v[i]);
    }
    return res;
}

