vector<ll> mp(string s) {
  ll n = s.size();
  vector<ll> ret(n + 1);
  ret[0] = -1;
  ll j = -1;
  rep(i, n) {
    while (j >= 0 && s[i] != s[j]) j = ret[j];
    ret[i + 1] = ++j;
  }
  return ret;
}

vector<ll> kmp(string str, string word) {
  vector<ll> table = mp(word), ret;
  ll m = 0, i = 0, n = str.size();
  while (m + i < n) {
    if (word[i] == str[m + i]) {
      if (++i == (ll)(word.size())) {
        ret.push_back(m);
        m = m + i - table[i];
        i = table[i];
      }
    }
    else {
      m = m + i - table[i];
      if (i > 0) i = table[i];
    }
  }
  return ret;
}

