const int maxn=5000010;

inline vector<int> buildfail(string p)
{
	int n=p.size();
	vector<int> fail(n+1);

	fail[0]=-1;
	for(int i=1,j=-1;i<=n;i++)
	{
		while(j>=0&&p[i-1]!=p[j]) j=fail[j];
		fail[i]=++j;
	}

	return fail;
}

bool ok[maxn];

string S;

inline void match(string t,string p,vector<int> fail)
{
	int n=t.size(),m=p.size();

	for(int i=0,j=0;i<n;i++)
	{
		while(j>=0&&t[i]!=p[j]) j=fail[j];
		if(++j>=m) ok[(i-m+1)%SZ(S)]=1;
	}
}

string s,t;
int dag[maxn],cnt,dp[maxn];
vector<int> e[maxn];

int main()
{
	cin>>S>>t;

	int sz=2*(S.size()+t.size());
	while(s.size()<sz) s+=S;

	match(s,t,buildfail(t));

	rep(i,S.size()) if(ok[i])
	{
		int j=(i+t.size())%SZ(S);
		e[i].push_back(j);
		dag[j]++;
	}

	queue<int> q;
	rep(i,S.size()) if(!dag[i]) q.push(i);
	while(!q.empty())
	{
		cnt++;

		int x=q.front();q.pop();
		repV(y,e[x])
		{
			dp[y]=max(dp[y],dp[x]+1);
			if(--dag[y]==0) q.push(y);
		}
	}

	if(cnt==S.size())
	{
		int ans=0;
		rep(i,S.size()) ans=max(ans,dp[i]);
		cout<<ans;
	}
	else cout<<-1;

	return 0;
}
