int infi(string S, string T) {
	int N = S.size(), M = T.size();
	int N1 = N;
	int siz = 1e7;
	while (S.size() < siz)S += S;
	N = S.size();
	char c = T[0];
	T += T;
	int idx = 0;
	int mx = 0;
	if (S[0] == c) {
		mx = 1;
		dp[0] = 1;
		c = T[1];
		idx++;
	}
	FOR(i,1, 1e7) {
		idx %= M;
		c = T[idx];
		if (S[i] == c) {
			dp[i] = dp[i-1] + 1;
			idx++;
			mx = max(mx, dp[i]);
		}
		else {
			idx = 0;
			c = T[0];
			dp[i] = 0;
		}
		if (mx > 5*1e6)return -1;
	}
	return mx / M;
}

