    bool prime(const int &n) {        assert(n < 9223372036854775808ULL);        if (!sz(primes))setprime();        /*エラトステネスの篩 偶数省略ver        [i] = i*2+1*/        if (n < prime_len)return era.prime(n);        if (n < 4294967296) {            rep(i, 30) if (!(n % primes[i]))return false;            constexpr uint64_t witness[] = {2, 7, 61, 0};            auto modmul = [&](uint64_t a, uint64_t b) -> uint64_t { return a * b % n; };            return miller_rabin(n, witness, modmul);        } else {            rep(i, 50) if (!(n % primes[i]))return false;            constexpr uint64_t witness[] = {2, 325, 9375, 28178, 450775, 9780504, 1795265022, 0};            auto modmul = [&](uint64_t a, uint64_t b) -> uint64_t { return (uint64_t) ((__uint128_t) a * b % n); };            return miller_rabin(n, witness, modmul);        }}
