			b[i*lb+pos]=b[pos];
		}
	}
	build(b);
	int c1=search(0,la),c2=search(0,la*2),c3=search(0,la*3);
	if(c2==c1) over(c1);
	if(c2>c1 && c3>c2) over(-1);
	cout<<c2<<endl;
	return 0;
}

