  for (int i=0; i<N; i++) {
    //cout<<0<<" " << t.size()+i << " " << sa.prefixCommonLength(0, t.size()+i) << endl;
    if(sa.prefixCommonLength(0, NT+i) >= NT ){
      ok[i%N] = true;
      none  = false;
    }
  }

  if (none) {
    cout<<0<<endl;
    return 0;
  }

  auto uf = UnionFind(N);
  rep(i,0,N){
