template<typename T>
vector<int> build_kmp(const T &s) {
  vector<int> f(s.size());
  int fp = f[0] = -1;
  for (int i = 1; i < s.size(); ++i) {
    while (~fp && s[fp + 1] != s[i]) fp = f[fp];
    if (s[fp + 1] == s[i]) ++fp;
    f[i] = fp;
  }
  return f;
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  string s, t; cin >> s >> t;
  while (s.size() < t.size() * 32) s += s;
  auto kmpt = build_kmp(t);
  int ans = 0, cur = 0, i = -1;
  for (auto c : s) {
    while (i != -1 and t[i + 1] != c) i = kmpt[i], cur = 0;
    if (c == t[i + 1]) ++i;
    else cur = 0;
    if (i == t.size() - 1) {
      i = kmpt[i];
      ++cur;
      ans = max(ans, int(((t.size() - 1 - i) * (cur - 1) + t.size()) / t.size()));
    }
  }
  cout << (ans >= 30 ? -1 : ans) << '\n';
}

