struct suffix_array {
  const string& S;
  int n;
  vector<int> sa;
  suffix_array(const string& S_)
      : S(S_), n(S.size()), sa(n) {
    vector<int> r(n), t(n);
    for (int i = 0; i < n; ++i) r[sa[i] = i] = S[i];
    for (int h = 1; t[n - 1] != n - 1; h *= 2) {
      auto cmp = [&](int i, int j) {
        if (r[i] != r[j]) return r[i] < r[j];
        return i + h < n && j + h < n ? r[i + h] < r[j + h] : i > j;
      };
      sort(sa.begin(), sa.end(), cmp);
      for (int i = 0; i + 1 < n; ++i) t[i + 1] = t[i] + cmp(sa[i], sa[i + 1]);
      for (int i = 0; i < n; ++i) r[sa[i]] = t[i];
    }
  }
  int partion(const string& T, int v = 0) const {
    int a = 0, b = n;
    while (b - a > 1) {
      int c = (a + b) / 2;
      if (S.compare(sa[c], T.length(), T) < v) {
        a = c;
      } else {
        b = c;
      }
    }
    return b;
  }
  int lower_bound(const string& T) const {
    return partion(T, 0);
  }
  int upper_bound(const string& T) const {
    return partion(T, 1);
  }
  vector<int> find_pattern_all(const string& T) const {
    int lb = lower_bound(T);
    int ub = upper_bound(T);
    return vector<int>(sa.begin() + lb, sa.begin() + ub);
  }
};

struct UnionFind {
  vector<int> parent;  // parent[root] is the negative of the size.
  UnionFind(int n)
      : parent(n, -1){};
  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v];
    parent[v] = u;
    return true;
  }
  bool find(int u, int v) {
    return root(u) == root(v);
  }
  int root(int u) {
    return parent[u] < 0 ? u : parent[u] = root(parent[u]);
  }
  int size(int u) {
    return -parent[root(u)];
  }
};

