typedef long long LL;

template<typename T>
T gcd(T a, T b) 
{
    if (b < a) { //! make sure a <= b
        T tmp = b;
        b = a;
        a = tmp;
    }

    T r = b % a;
    while (r) {
        b = a;
        a = r;
        r = b % a;
    }

    return a;
}

//! return lcm of a and b
template<typename T>
T lcm(T a, T b) 
{
    return a * b / gcd<T>(a, b);
}

int main()
{
    string s, t;
    cin >> s >> t;

    LL slen = s.length();
    LL tlen = t.length();
    LL len = lcm(slen, tlen);

    string sn = s;
    while (sn.length() < len) {
        sn += s;
    }
    sn = sn + sn;

    size_t tPos = sn.find(t);
    if (tPos == string::npos) {
        //! repetition of s does not contain t
        cout << 0 << endl;
        return 0;
    }

    //! shift the head of sn so that sn and t matches from the top
    sn = sn.substr(tPos) + sn.substr(0, tPos);

    int curr = 0;
    int longest = 0;
    int head = 0;
    while (head < sn.length()) {
        tPos = sn.find(t, head);
        if (tPos == string::npos) {
            break;
        } else if (tPos == head) {
            ++curr;
        } else {
            longest = max(longest, curr);
            curr = 1;
        }
        head = tPos + t.length();
    }

    if (head == sn.length() && longest == 0) {
        longest = -1;
    }

    cout << longest << endl;
    return 0;
}

