int main() {
    using namespace std;
    string s, t;
    cin >> s >> t;
    unsigned long N = s.size(), M = t.size();
    {
        unsigned long n = (s.size() + t.size() - 1) / s.size();
        string sss(s.begin(), s.end());
        while(n){
            if(n & 1)s += sss;
            sss += sss;
            n >>= 1;
        }
    }

    vector<unsigned long> idx(N);
    {
        string Q = t + "_" + s;
        vector<unsigned long> KMP(Q.size() + 1);
        for(unsigned long i = 1, j = 0; i <= Q.size(); ++i){
            while(j > 0 && Q[i - 1] != Q[j - 1])j = KMP[j - 1];
            KMP[i] = ++j;
            if(KMP[i] > M && i >= KMP[i] + M && i < KMP[i] + N + M)idx[i - KMP[i] - M] = ~0UL;
        }
    }

    auto f = [rec = [&idx, &M, &N](auto f, unsigned long i, unsigned long t, unsigned long k) -> unsigned long{
        if(!idx[i])return 0;
        if(i == t && k)idx[i] = 2 * N;
        else if(!~idx[i])idx[i] = f(f, (i + M) % N, t, 1) + 1;
        return idx[i];
    }](unsigned long n){rec(rec, n, n, 0);};
    for(unsigned long i = 0; i < N; ++i)f(i);

    unsigned long ans = *max_element(idx.begin(), idx.end());
    if(ans > N)puts("-1");
    else cout << ans << endl;
    return 0;
}

