long long h[2000010];
long long power[500010];
vector <int> from[500010];
int in[500010];
queue <int> q;
int dp[500010];

long long MOD(long long x){return x - x / mod * mod;}

void pre_h(){
	power[0] = 1;
	for (int i = 1; i <= m; i++){
		power[i] = MOD(power[i - 1] * P);
	}
	for (int i = 1; i <= now; i++){
		h[i] = MOD(h[i - 1] * P + s[i] - 'a' + 1);
	}
}

long long get_h(int l, int r){
	return MOD(h[r] - MOD(h[l - 1] * power[r - l + 1]) + mod);
}

int main(){
	scanf("%s%s", s + 1, t + 1), n = strlen(s + 1), m = strlen(t + 1), now = n;
	while (now < m){
		for (int i = now + 1; i <= now + n; i++){
			s[i] = s[i - now];
		}
		now += n;
	}
	for (int i = now + 1; i <= now + now; i++){
		s[i] = s[i - now];
	}
	now += now;
	pre_h();
	long long my = 0;
	for (int i = 1; i <= m; i++){
		my = MOD(my * P + t[i] - 'a' + 1);
	}
	for (int i = 1; i <= n; i++){
		if (get_h(i, i + m - 1) == my){
			from[i].push_back((i + m - 1) % n + 1);
			in[(i + m - 1) % n + 1]++;
		}
	}
	for (int i = 1; i <= n; i++){
		if (!in[i]) q.push(i), dp[i] = 0;
	}
	int ans = 0;
	while (!q.empty()){
		int x = q.front(); q.pop();
		for (int i = 0; i < from[x].size(); i++){
			int v = from[x][i];
			in[v]--, dp[v] = max(dp[v], dp[x] + 1);
			ans = max(ans, dp[v]);
			if (!in[v]) q.push(v);
		}
	}
	for (int i = 1; i <= n; i++){
		if (in[i]){
			printf("-1\n");
			return 0;
		}
	}
	printf("%d\n", ans);
	return 0;
