	ll left = -1, right = v.size();
	while ( abs( right - left ) > 1 )
	{
		ll mid = ( left + right ) / 2;
		if ( val > v[mid] )
			left = mid;
		else
			right = mid;
	}

	return ( mp( v[right] == val, right ) );
}

struct TopologicalSort {
	vector<vector<ll>> g;
	vector<ll> order;
	vector<ll> color;
	TopologicalSort( ll n, vector<vector<ll>> &G ) {
		color.assign( n, 0 );
		g = G;
	}

    bool visit( ll v ) {
		color[v] = 1;
        arep( u, g[v] )
		{
			if ( color[u] == 2 ) continue;
			if ( color[u] == 1 ) return ( false );
			if ( visit( u ) == false ) return ( false );
		}
		order.eb( v ); color[v] = 2;
		return true;
	}

    bool sort() {
		ll n = g.size();
        rep( u, n )
			if ( color[u] == false && visit( u ) == false ) return ( false );
        reverse( ALL( order ) );
		return ( true );
	}
};

