using namespace std;

const int INF = 1e9;

map<int, int> nexts;
vector<bool> vis;
pair<int, int> trace(int pos, int init) {
    if (pos == init) {
        return make_pair(pos, INF);
    } else if (nexts.count(pos) == 0) {
        return make_pair(pos, 1);
    } else {
        auto recur = trace(nexts[pos], init);
        return make_pair(recur.first, recur.second + 1);
    }
}

int main() {
    string s, t;
    cin >> s >> t;

    string u;
    while (u.size() < s.size() + t.size()) {
        u.insert(u.end(), s.begin(), s.end());
    }

    KMP kmp(t);
    auto matches = kmp.search(u);
    for (const auto &fr : matches) {
        nexts[fr] = (fr + t.size()) % s.size();
    }
    vis = vector<bool>(s.size(), false);

    int ans = 0;
    for (int fr = 0; fr < s.size(); ++fr) {
        if (nexts.count(fr) == 0) {
            continue;
        }
        if (vis[fr]) {
            continue;
        }
        ans = max(ans, trace(nexts[fr], fr).second);
    }

    cout << ((ans >= INF) ? -1 : ans) << endl;
    return 0;
}

