    for (int i = 0; i < slen; i++) {
        if (!v[i] && z[tlen+1+i] == tlen) {
            int x = i;
            int cnt = 0;
            while (!v[x] && z[tlen+1+x] == tlen) {
                v[x] = true;
                cnt++;
                x = (x + slen - tlen) % slen;
            }
            if (v[x]) {
                cout << -1 << endl;
                return 0;
            }

            x = (i + tlen) % slen;
            while (!v[x] && z[tlen+1+x] == tlen) {
                v[x] = true;
                cnt++;
                x = (x + tlen) % slen;
            }

            ans = max(ans, cnt);
        }
    }

    cout << ans << endl;

    return 0;
}

