// Rolling hash with mod 2^64-1
// https://qiita.com/keymoon/items/11fac5627672a6d6a9f6
// https://ei1333.github.io/luzhiled/snippets/string/rolling-hash.html
struct RollingHash{
    static const vector<ull> primes;
    static const ull base, MASK30, MASK31, RHMOD;
    vector<ull> hash, pow;
    inline ull calcmod(ull val) const{
        val = (val & RHMOD) + (val >> 61);
        if (val > RHMOD) val -= RHMOD;
        return val;
    }
    inline ull mulmod(ull a, ull b) const{
        ull au = a >> 31;
        ull ad = a & MASK31;
        ull bu = b >> 31;
        ull bd = b & MASK31;
        ull mid = ad * bu + au * bd;
        ull midu = mid >> 30;
        ull midd = mid & MASK30;
        return calcmod(au * bu * 2 + midu + (midd << 31) + ad * bd);
    }
    RollingHash(const string &s){
        int n = s.size();
        hash.assign(n+1, 0);
        pow.assign(n+1, 0);
        pow[0] = 1;
        for(int i = 0; i < n; i++) {
            pow[i+1] = mulmod(pow[i], base);
            hash[i+1] = mulmod(hash[i], base) + s[i];
            if(hash[i+1] >= RHMOD) hash[i+1] -= RHMOD;
        }
    }
    // [l, r)
    ull get(int l, int r) const{
        ull ret = hash[r] + RHMOD - mulmod(hash[l], pow[r-l]);
        if(ret >= RHMOD) ret -= RHMOD;
        return ret;
    }
    ull connect(ull h1, int h2, int h2len) const{
        ull ret = mulmod(h1, pow[h2len]) + h2;
        if(ret >= RHMOD) ret -= RHMOD;
        return ret;
    }
    int LCP(const RollingHash& b, int l1, int r1, int l2, int r2) {
        int len = min(r1 - l1, r2 - l2);
        int low = -1, high = len + 1;
        while(high - low > 1) {
            int mid = (low + high) >> 1;
            if(get(l1, l1 + mid) == b.get(l2, l2 + mid)) low = mid;
            else high = mid;
        }
        return low;
    }
};
