VL Zalgo(const string &S) {
    int N = (int)S.size();
    VL res(N);
    res[0] = N;
    int i = 1, j = 0;
    while(i < N) {
        while(i + j < N && S[j] == S[i + j]) ++j;
        res[i] = j;
        if(j == 0) {
            ++i;
            continue;
        }
        int k = 1;
        while(i + k < N && k + res[k] < j) res[i + k] = res[k], ++k;
        i += k, j -= k;
    }
    return res;
}

VVL G;
VB used, nused;

ll dfs(ll now, ll root) {
    used[now] = true;
    ll res = 0;
    FOREACH(to, G[now]) {
        if(res < 0) break;
        if(to == root) return -LINF;
        ll tmp = dfs(to, root);
        if(tmp < 0) return -LINF;
        res = max(res, tmp + 1);
    }
    return res;
}

signed main() {
    SCIN(S, T);
    string tmp = S;
    while(tmp.length() < T.length()) {
        tmp += S;
    }
    VL z = Zalgo(T + "$" + tmp + tmp);
    ll N = tmp.length();
    G.resize(N);
    REP(i, N) {
        if(z[T.length() + 1 + i] == T.length()) {
            G[i].emplace_back((i + T.length()) % N);
        }
    }
    used.assign(N, false);
    ll ans = 0;
    REP(i, N) {
        if(used[i]) continue;
        ll val = dfs(i, i);
        if(val == -LINF) eputs(-1);
        ans = max(ans, val);
    }
    cout << ans << "\n";
}

