using vi = vector<int>;

vi init(string& P)
{
    vi b(P.size() + 1);
    int i = 0, j = -1; b[0] = -1;
    while (i < P.size())
    {
        while (j >= 0 && P[i] != P[j]) j = b[j];
        b[++i] = ++j;
    }
    return b;
}

vi kmp(string& T, string& P, vi& b)
{
    vi ret;
    int i = 0, j = 0;
    while (i < T.size())
    {
        while (j >= 0 && T[i] != P[j]) j = b[j];
        ++i; ++j;
        if (j == P.size())
        {
            ret.push_back(i - j);
            j = b[j];
        }
    }
    return ret;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    string s, t;
    cin >> s >> t;
    s.reserve(max(s.size(), t.size()));
    while (s.size() < t.size())
        s += s;
    vi b = init(t);
    string z = s + s;
    vi m = kmp(z, t, b);
    vi a(s.size());
    for (int x : m)
        if (x < s.size())
            a[x] = 1;

    vi vis(s.size());
    int bst = 0;
    for (int x : m)
    {
        if (vis[x]) continue;
        int curr = 0;
        while (a[x])
        {
            curr++;
            if (vis[x])
                return cout << -1, 0;
            vis[x] = 1;
            x += t.size();
            x %= s.size();
        }
        bst = max(bst, curr);
    }
    cout << bst;
}

