constexpr unsigned int rh_b[] = { 1333133303 , 1145141999 };
constexpr int rh_sz = 2;
struct RH{
  using P = pair<unsigned int , unsigned int>;
  vector< vector< unsigned int> > hashed, power;
  RH(const string &s){
    int size_ = (int)s.size();
    hashed.resize(rh_sz , vector<unsigned int>(size_ + 1 , 0));
    power.resize(rh_sz , vector<unsigned int>(size_ + 1 , 0));
    rep(i , rh_sz) power[i][0] = 1;
    rep(i , rh_sz) rep(j , size_){
      power[i][j + 1] = ((unsigned long long)power[i][j] * rh_b[i]) % rh_mod;
      hashed[i][j + 1]= ((unsigned long long)hashed[i][j] * rh_b[i] + s[j] ) % rh_mod;
      //trc(i , j , power[i][j + 1] , hashed[i][j + 1]);
    }
  }

  P get(int l,int r) const{
    unsigned int ret[rh_sz];
    rep(i , rh_sz)
      ret[i] = ( hashed[i][r] + rh_mod - (unsigned int)( (long long)hashed[i][l] * power[i][r-l] % rh_mod ) ) % rh_mod;
    return P(ret[0] , ret[1]);
  }
};
pair<unsigned int , unsigned int> get_hash(const string &S){
  unsigned int ret[rh_sz];
  rep(i , rh_sz){
    unsigned long long cur = 0;
    rep(j , sz(S)){
      cur = (cur * rh_b[i] + S[j]) % rh_mod;
    }
    ret[i] = cur;
  }
  return pair<unsigned int , unsigned int>(ret[0] , ret[1]);
}

void solve(){
  ins(SS,T);
  int N = sz(SS) , M = sz(T);
  string S;
  while(sz(S) < N + M){
    S += SS;
  }
  vvi g(N);
  RH rh(S);
  auto th = get_hash(T);
  int ans = 0;
  rep(i , N){
    int cur = 0 , idx = i;
    while(rh.get(idx , idx + M) == th){
      idx = (M + idx) % N; cur++;
      if(idx == i) die(-1);
    }
    amax(ans , cur);
  }
  out(ans);


}

