using namespace std;
#define N 500005

int table[N];
void makeTable(string &t) {
	int n = t.size(), pos = 1, match = 0;
	while (pos + match < n) {
		if (t[match] == t[pos + match]) {
			++match;
			table[pos + match - 1] = match;
		}
		else {
			if (match == 0) {
				++pos;
			}
			else {
				pos += match - table[match - 1];
				match = table[match - 1];
			}
		}
	}
}
bool vis[N], isMatch[N];
int dp[N];
int main(void) {
	string s, t;
	cin >> s >> t;
	makeTable(t);
	int pos = 0, match = 0;
	int n = s.size();
	while (pos < n) {
		int id = (pos + match) % n;
		if (match < t.size() && s[id] == t[match]) {
			++match;
			if (match == t.size()) {
				isMatch[pos] = true;
			}
		}
		else {
			if (match == 0) {
				++pos;
			}
			else {
				pos += match - table[match - 1];
				match = table[match - 1];
			}
		}
	}

	int ret = 0;
	for (int i = 0; i < n; ++i) {
		if (isMatch[i] && !vis[i]) {
			int cc = 0;
			bool cycleOccured = false;
			int id = i;
			while (true) {
				if (vis[id]) {
					cc += dp[id];
					if (id == i) {
						cycleOccured = true;
					}
					break;
				}
				vis[id] = true;
				++cc;
				id = (id + t.size()) % n;
				if (!isMatch[id]) {
					break;
				}
			}
			if (cycleOccured) {
				ret = -1;
				break;
			}
			dp[i] = cc;
			ret = max(ret, cc);
		}
	}
	printf("%d\n", ret);
	return 0;
}

