struct IO
{
    bool goodReadBit;
    IO() { goodReadBit = 1; space = ' ';}
    template <typename T>
    void __RI(T &x)
    {
        int ch = getchar(), neg = 1;
        x = 0;
        for (; !(isdigit(ch) || ch == '-' || ch == EOF); ch = getchar())
            ;
        if (ch == EOF)
        {
            goodReadBit = 0;

            return;
        }
        if (ch == '-') neg = -1, ch = getchar();
        for (; isdigit(ch); ch = getchar()) x = x * 10 + ch - 48;
        x *= neg;
    }
    void R(int &x) { __RI(x); }
    void R(int64_t &x) { __RI(x); }
    template <typename T1, typename T2>
    void R(std::pair<T1, T2> &x)
    {
        R(x.first);
        R(x.second);
    }
    template <typename T>
    void R(std::vector<T> &x)
    {
        for (typename std::vector<T>::iterator it = x.begin(); it != x.end(); ++it) { R(*it); }
    }
    template <typename T>
    void R(T &x)
    {
        std::cin >> x;
        if (!std::ios::goodbit) goodReadBit = 0;
    }
#if __cplusplus >= 201103L
    template <typename T, typename... Args>
    void R(T &x, Args &... args)
    {
        R(x), R(args...);
    }
#endif
    bool goodRead() { return goodReadBit; }
    char space;
    template <typename T>
    void __WI(T x)
    {
        if (x == 0) putchar('0');
        if (x < 0) putchar('-'), x = -x;
        char ch[ 64 ];
        int  pos = 0;
        while (x) ch[ pos++ ] = x % 10 + 48, x /= 10;
        while (pos) putchar(ch[ --pos ]);
    }
    void W() {}
    void W(const int &x) { __WI(x); }
    void W(const int64_t &x) { __WI(x); }
    void W(const double &x) { printf("%lf", static_cast<double>(x)); }
    void W(const char &x) { putchar(x); }
    void W(const std::string &x) { printf("%s", x.c_str()); }
    template <typename T1, typename T2>
    void W(const std::pair<T1, T2> &x)
    {
        W(x.first);
        W(space);
        W(x.second);
    }
    template <typename T>
    void W(const std::vector<T> &x)
    {
        for (typename std::vector<T>::const_iterator it = x.begin(); it != x.end(); it++)
        {
            W(*it);
            W(space);
        }
        W('\n');
    }
    template <typename T>
    void W(const T &x)
    {
        std::cout << x;
    }
    void WL() { W('\n'); }
    template <typename T>
    void WL(const T &x)
    {
        W(x), W('\n');
    }
    void WS() { W(' '); }
    template <typename T>
    void WS(const T &x)
    {
        W(x), W(' ');
    }
#if __cplusplus >= 201103L
    template <typename T, typename... Args>
    void W(const T &x, const Args &... args)
    {
        W(x), W(space), W(args...);
    }
    template <typename... Args>
    void WL(const Args &... args)
    {
        W(args...), W('\n');
    }
#endif
    template <typename T>
    IO &operator>>(T &x)
    {
        R(x);
        return (*this);
    }
