using Int = long long;
struct RollingHash {
    const Int M1 = 1000000007, M2 = 1000000009;
    const Int BASE = 131;
    vector<Int> hash1, hash2, power1, power2;
    RollingHash(const string& s) {
        hash1.resize(s.size() + 1);
        hash2.resize(s.size() + 1);
        power1.resize(s.size() + 1);
        power2.resize(s.size() + 1);
        power1[0] = power2[0] = 1;
        for (int i = 0; i < s.size(); i++) {
            hash1[i+1] = (hash1[i] * BASE + s[i]) % M1;
            hash2[i+1] = (hash2[i] * BASE + s[i]) % M2;
            power1[i+1] = (power1[i] * BASE) % M1;
            power2[i+1] = (power2[i] * BASE) % M2;
        }
    }
    Int get(int l, int r) {
        Int h1 = (hash1[r] + (M1 - hash1[l]) * power1[r - l]) % M1;
        Int h2 = (hash2[r] + (M2 - hash2[l]) * power2[r - l]) % M2;
        return (h1 << 32) + h2;
    }
};
int main()
{
    string S, T; cin >> S >> T;
    string U;
    while (U.size() < max(S.size(), T.size())*2) U += S;
    auto rh = RollingHash(U);
    auto t = RollingHash(T).get(0, T.size());
    vector<int> dp(U.size()+1);
    for (int i = 0; i+T.size() <= U.size(); i++) {
        bool b = rh.get(i, i+T.size()) == t;
        if (b) {
            dp[i] = (i >= T.size() ? dp[i-T.size()] : 0) + b;
        }
    }
    int maxval = *max_element(begin(dp), end(dp));
    if (maxval * T.size() >= S.size()) {
        cout << -1 << endl;
    } else {
        cout << maxval << endl;
    }
    return 0;
}

