namespace KMP {
    typedef char TYPE;

    int prev[ran];

    int prepare(TYPE B[], int LB) {
        prev[0] = -1;
        for(int i=1;i<LB;i++) {
            int d=prev[i-1];
            while(d>=0 && B[i]!=B[d+1]) d=prev[d];
            prev[i]=(B[d+1]==B[i]) ? d+1 : -1;
        }
        return true;
    }

    int match(TYPE A[], int LA, TYPE B[], int LB, int M[], int &LM) {
        prepare(B, LB);
        int d=-1,ret=0;
        LM=0;
        for(int i=0;i<LA;i++) {
            while(d>=0&&B[d+1]!=A[i]) d=prev[d];
            if (B[d+1]==A[i]) d++;
            if (d==LB-1) {
                M[LM++] = i-LB+1;
                d=prev[d];
            }
        }
        return true;
    }
}

