    vector<vector<long long>> hash_t(3, vector<long long>(t.size() + 1));
    set_hash(new_s, hash_s);
    set_hash(t, hash_t);
    vector<int> roots(s.size());
    for (int i = 0; i < s.size(); i++) roots[i] = i;
    root = roots;
    vector<int> rankz(s.size(), 0);
