vector<int> Zalgo(string s){
    int n=s.size();
    vector<int> a(n,0);
    int from=-1,last=-1;
    for(int i=1;i<n;i++){
        int &same=a[i];
        if(from!=-1){
            same=min(a[i-from],last-i);
            same=max(0,same);
        }
        while(i+same<n&&s[same]==s[i+same]){
            same++;
        }
        if(last<i+same){
            last=i+same;
            from=i;
        }
    }
    a[0]=n;
    return a;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    string s,t; cin >> s >> t;
    string r=t;
    while(r.size()<t.size()+s.size()+t.size()){
        r+=s;
    }
    int n=s.size();
    int m=t.size();
    vector<bool> can(n,false);
    auto z=Zalgo(r);
    for(int i=m;i<m+n;i++){
        if(z[i]>=m)can[i-m]=true;
    }
    vector<int> cnt(n);
    int res=0;
    for(int i=0;i<n;i++){
        if(cnt[i])continue;
        if(can[i]){
            int id=i;
            while(can[id]){
                if(cnt[id]){
                    cnt[i]+=cnt[id];
                    break;
                }
                cnt[i]++;
                id+=m;
                id%=n;
            }
        }
    }
    for(int i=0;i<n;i++){
        res=max(res,cnt[i]);
    }
    if(res>=n)res=-1;
    printf("%d\n",res);
}

