#define _base 73

const int N = 500003;

string s, t, g;
pair<int,int> m[N << 2];
pair<int,int> ht;
pair<int,int> hs[N << 2];
int legit[N];
int vis[N];

signed main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> s >> t;
	int S = s.size(), T = t.size();
	g = s;
	while(g.size() < T)
		g += s;
	g += s;
	// generate power
	m[0].first = m[0].second = 1;
	for(int i = 1 ; i < (N << 2) ; i ++)
		m[i].first = m[i - 1].first * base % mod, m[i].second = m[i - 1].second * _base % _mod;
	// generate hash for t
	t = '~' + t;
	for(int i = 1 ; i <= T ; i ++)
		ht.first = (ht.first + (t[i] - 'a' + 1) * m[i].first) % mod, ht.second = (ht.second + (t[i] - 'a' + 1) * m[i].second) % _mod;
	// generate hash for g
	g = '~' + g;
	for(int i = 1 ; i < g.size() ; i ++)
		hs[i].first = (hs[i - 1].first + (g[i] - 'a' + 1) * m[i].first) % mod, hs[i].second = (hs[i - 1].second + (g[i] - 'a' + 1) * m[i].second) % _mod;
	// legitimate
	for(int i = 1 ; i <= S ; i ++){
		pair<int,int> pre;
		pre.first = (hs[i + T - 1].first - hs[i - 1].first) % mod;
		if(pre.first < 0) pre.first += mod;
		pre.second = (hs[i + T - 1].second - hs[i - 1].second) % _mod;
		if(pre.second < 0) pre.second += _mod;
		if(pre.first == (ht.first * m[i - 1].first % mod) && pre.second == (ht.second * m[i - 1].second % _mod))
			legit[i - 1] = true;
	}
	int ans = 0;
	for(int i = 0 ; i < S ; i ++){
		//cout << "examine " << i << endl;
		if(!vis[i] && legit[i]){
			int u = (i + T)%S;
			int cnt = 1;
			while(!vis[u] && legit[u]){
				//cout << "forward " << u << endl;
				cnt ++;
				vis[u] = 1;
				u = (u + T)%S;
			}
			if(vis[u]) return cout << "-1", 0;
			u = ((i - T) % S);
			if(u < 0) u += S;
			while(!vis[u] && legit[u]){
				//cout << "backward " << u << endl;
				cnt ++;
				vis[u] = 1;
				u = (u - T)%S;
				if(u < 0) u += S;
			}
			if(vis[u]) return cout << "-1", 0;
			ans = max(ans, cnt);
		}
	}
	cout << ans;
}

