vll RollingHash(string &s, string &t){
	vll ret;
	ll N = Size(s);
	ll M = Size(t);
	if (N<M) return ret;

	using mllA = mll_<1000000007LL>;
	using mllB = mll_<998244353LL>;

	random_device rd;
	mt19937 mt(rd());
	ll r = mt()%1000000LL+1000000LL;

	auto hash = [](string &s, ll len, ll r){
		mllA hA=0;  mllB hB=0;
		REP(i, len){
			hA *= r;    hB *= r;
			hA += s[i]; hB += s[i];
		}
		return tuple<mllA, mllB>(hA, hB);
	};

	mllA hAs; mllB hBs; tie(hAs, hBs) = hash(s, M, r);
	mllA hAt; mllB hBt; tie(hAt, hBt) = hash(t, M, r);
	//auto h_t = hash(t, M, r);

	mllA rMA = POW(mllA(r), M);
	mllB rMB = POW(mllB(r), M);
	rep(i, 0, N-M){
		if (i!=0){
			hAs*=r;          hBs*=r;
			hAs+=s[i+M-1];   hBs+=s[i+M-1];
			hAs-=s[i-1]*rMA; hBs-=s[i-1]*rMB;
			//get<0>(h_s)*=r;          get<1>(h_s)*=r;
			//get<0>(h_s)+=s[i+M-1];   get<1>(h_s)+=s[i+M-1];
			//get<0>(h_s)-=s[i-1]*rMA; get<1>(h_s)-=s[i-1]*rMB;
		}
		if (hAs==hAt && hBs==hBt) ret.push_back(i);
	}

	return move(ret);
}



