bool is_cycle(string a, const string& b) {
    // cout << "is_cycle: " << a << ", " << b << endl;
    if (b.length() % a.length() != 0) return false;
    int i = 0;
    for (int q = 0; q < b.length(); ++q) {
        if (b[q] != a[i]) return false;
        ++i;
        if (i == a.length()) i = 0;
    }
    return true;
}

void get_p(const string& b, vector<int>& p) {
    assert(p.size() == b.length());
    if (b.empty()) return;
    p[0] = 0;
    for (int i = 1; i < p.size(); ++i) {
        int k = p[i - 1];
        while (k > 0 && b[k] != b[i]) {
            k = p[k - 1];
        }
        if (b[i] == b[k]) ++k;
        p[i] = k;
    }
}

bool is_eq_cycle(string a, string b) {
    // cout << "is_eq_cycle: " << a << ", " << b << endl;
    if (a.length() != b.length()) return false;
    b = a + "#" + b + b;
    vector<int> p(b.length());
    get_p(b, p);
	for (int i = 1; i < b.length(); ++i) {
		if (p[i] == a.length()) {
            return true;
		}
	}
	return false;
}

int get_ans(const string& a, const string& b) {
    string s = a + "#" + b + b;
    vector<int> dp(s.length()), p(s.length());
    get_p(s, p);
    int ans = 0;
    // cout << s << endl;
    // for (int i = 0; i < s.length(); ++i) cout << p[i] << " "; cout << endl;
    for (int i = a.length(); i < s.length(); ++i) {
        if (p[i] == a.length()) {
            dp[i] = dp[i - a.length()] + 1;
            ans = max(ans, dp[i]);
        }
    }
    return ans;
}

