string s;
string t;

vector<int> graph[MAX_N];
vector<int> tsorted;
int flg[MAX_N];  // 0: not-visited, 1: done, -1, temporary

int path[MAX_N];

int ans;

bool visit(int i) {
  if (flg[i] == -1) {
    return false;
  }

  if (flg[i] == 0) {
    flg[i] = -1;

    for (auto &e : graph[i]) {
      if (!visit(e)) {
        return false;
      }
    }

    flg[i] = 1;

    tsorted.push_back(i);
  }

  return true;
}

bool topological_sort() {
  for (int i = 0; i < s.size(); ++i) {
    flg[i] = 0;
  }

  for (int i = 0; i < s.size(); ++i) {
    if (flg[i] == 0) {
      if (!visit(i)) {
        return false;
      }
    }
  }

  reverse(tsorted.begin(), tsorted.end());

  return true;
}

int main(void) {
  // Here your code !
  cin >> s;
  cin >> t;

  int target_size = s.size() + t.size();

  string s_replicate = s;

  while (s_replicate.size() < target_size) {
    s_replicate += s;
  }

  StringMatching sm(s_replicate, t, '_');

  for (int i = 0; i < s.size(); ++i) {
    if (sm.match_from(i)) {
      int target = (i + t.size()) % s.size();

      graph[i].push_back(target);
    }
  }

  if (!topological_sort()) {
    printf("%d\n", -1);
    return 0;
  }

  int length = 0;

  for (auto &e: tsorted) {
    for (auto &child: graph[e]) {
      path[child] = max(path[child], path[e] + (int)(t.size()));
      length = max(length, path[child]);
    }
  }

  ans = length / t.size();

  printf("%d\n", ans);

  return 0;
}

