///AUTOMATA
const int M = MM*20;
struct state
{
    int len, link,fpos;
    bool isclone;
    map < char , int > next;
} st[2*M];

int sz, last;

void initialize()
{
    rep(sz+1)
    {
        st[i].next.clear();
    }
    sz = last = 0;
    st[0].len = 0;
    st[0].link = -1;
}
void build_automata(char c)
{
    int cur = ++sz;
    st[cur].len = st[last].len + 1;
    st[cur].isclone = 0;
    st[cur].fpos = st[cur].len;
    int p;
    for(p=last;p!=-1 && !st[p].next[c];p=st[p].link)
    {
        st[p].next[c] = cur;
    }
    if(p==-1)
    {
        st[cur].link = 0;
    }
    else
    {
        int q = st[p].next[c];
        if(st[p].len+1==st[q].len)
        {
            st[cur].link = q;
        }
        else
        {
            int clone = ++sz;
            st[clone] = st[q];
            st[clone].len = st[p].len+1;
            st[clone].isclone = 1;
            for(;p!=-1 && st[p].next[c]==q;p=st[p].link)
            {
                st[p].next[c] = clone;
            }
            st[q].link = st[cur].link = clone;
        }
    }
    last = cur;
}

