ll max_match(int len)
{
    int now = 0;
    int cnt = 0;
    rep(len)
    {
        now = st[now].next[s[i]-'a'];
        if(now==0)break;
        cnt++;
        if(i==len-1)i = -1;
    }
    return cnt/len;
}
