	}

	if (cyclic[idx] > 0) {
		return cyclic[idx];
	}

	if (cyclic[idx] == IN_PROCESS) {
		cyclic[idx] = INF;
		return INF;
	}

	cyclic[idx] = IN_PROCESS;
	int val = calc(cyclic, (idx+step)%T.size(), T, step, expected);
	if (val != INF) {
		val++;
	}
	cyclic[idx] = val;
	return val;
}

vector<int> prefix_function(vector<char> &s) {
    int n = (int)s.size();
    vector<int> pi(n);
    for (int i = 1; i < n; i++) {
        int j = pi[i-1];
        while (j > 0 && s[i] != s[j])
            j = pi[j-1];
        if (s[i] == s[j])
            j++;
        pi[i] = j;
    }
    return pi;
}

int main() {
