vector<int> kmpFailureFunc(const string& S)
{
    const int n = S.size();
    vector<int> F(n + 1, -1);
    F[1] = 0;
    for (int i = 2;i <= n; i++) {
        char c = S[i - 1];
        int l = F[i - 1];
        while (l >= 0 && S[l] != c)
            l = F[l];
        F[i] = l + 1;
    }

    return F;
}

