    VEC(int) kmpT = kmpFailureFunc(T);

    // Scanning S*
    int suff = 0;
    FOR(i, 0, MAXN) {
        char c = S[i % S.size()];
        while (suff >= 0 && T[suff] != c)
            suff = kmpT[suff];
