// kmp をやるための前計算
vector<int> makeTable(const string& s) {
  int n = s.size();
  vector<int> ret(n+1);
  ret[0] = -1;
  int j = -1;
  for (int i = 0; i < n; i++) {
    while (j >= 0 && s[i] != s[j]) j = ret[j];
    ret[i+1] = ++j;
  }
  return ret;
}

// str の中に word とマッチする場所のリストを返す
// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す


set<int> found;
int n,m;
map<int, int> used;
map<int, int> memo;

set<int> kmp(const string& str, const string& word) {
  vector<int> table = makeTable(word);
  set<int> ret;
  int m = 0, i = 0, n = str.size();
  while (m+i < n) {
    if (word[i] == str[m+i]) {
      if (++i == (int)(word.size())) {
        ret.insert(m);
        m = m+i-table[i];
        i = table[i];
      }
    } else {
      m = m+i-table[i];
      if (i > 0) i = table[i];
    }
  }
  return ret;
}

int dfs(int i){
  dump(i);
  assert(i<=n-1);
  if (memo[i]>0) return memo[i];

  used[i] = 1;
  int ni = (i+m)%n;

  if(used[ni] && memo[ni]>0){  // found previous result
    memo[i] = memo[ni]+1;
    return memo[i];
  }
  else if (used[ni]){  // found loop
    memo[i] = INF;
    return memo[i];
  }
  else if (found.find(ni)!=found.end()){
    memo[i] = dfs(ni)+1;
    return memo[i];
  }
  else{
    memo[i] = 1;
    return memo[i];
  }
}
