  for(int x = 0, j = 1; j <= m; j++) {
    for(int c = 0; c < R; c++) {
      dfa[c][j] = dfa[c][x];
    }
    dfa[t[j]][j] = (j+1)%(m+1);
    x = dfa[t[j]][x];
  }
}

int pathLength(int s, int i, int d) {
  if(d != 0 && s == i) return INF;
  if(!match[i]) return d;
  if(L[i] != -1) return d + L[i];

  return L[i] = pathLength(s, (i+m)%n, d+1);
}

int main () {
  cin >> s >> t;
  n = s.size(), m = t.size();
  match.resize(n);
  L.resize(n, -1);

  kmp();
  for(int i = 0, j = 0; i < n + m - 1; i++) {
    j = dfa[s[i%n]][j];
    if(j == m) match[i-m+1] = 1;
  }

  int ans = 0;
  rep(i,n) {
    if(match[i]) ans = max(ans, pathLength(i, i, 0));
  }

  cout << (ans == INF ? -1 : ans) << endl;

  return 0;
}

