void KMPMatch(string src, string pat){
    int ini[pat.size()], i=1, j=0;
    ini[0] = 0;
    while(i<pat.size()){
      if(pat[i] == pat[j]) j++, ini[i] = j, i++;
      else if(j == 0) ini[i] = 0, i++;
      else j = ini[j - 1];
    }
    i = j = 0;
    while(j<pat.size()&&i<src.size()/2+pat.size()-2){
      if(src[i] == pat[j]) i++, j++;
      else if(j == 0) i++;
      else j = ini[j - 1];
      if(j==pat.size()-1) add_edge(abs(i-j), i%(src.size()/2));
    }
}
vector<ll> d(2000001, -1);
ll df(int now){
  if(d[now]!=-1) return d[now];
  if(G[now].size()==0) d[now] = 0;
  for(int i=0;i<G[now].size();i++){
    d[now] = max(d[now], df(G[now][i])+1);
  }
  return d[now];
}
