	vector<int> mtbl;
	vector<int> h;

	hasher(const string& s) : n(sz(s)), mtbl(sz(s) + 1), h(sz(s) + 1) {
		h[0] = 0;
		FOR(i, n) h[i + 1] = (ll(h[i]) * a + s[i]) % m;
		mtbl[0] = 1;
		FOR(i, n) mtbl[i + 1] = ll(mtbl[i]) * a % m;
	}
	X substr(int l, int r) const {
		assert(l <= r);
		return X(ll(h[r] - ll(h[l]) * mtbl[r - l]) % m, r - l);
	}

	// l + r
	X add(X l, X r) const {
		X ret;
		ret.hash = (ll(l.hash) * mtbl[r.len] + r.hash) % m;
		ret.len = l.len + r.len;
		return ret;
	}
};

struct Matcher {
	using H1 = hasher<ten(8) + 7, ten(9) + 7>;
	using H2 = hasher<ten(8) + 7, ten(9) + 9>;

	H1 h1;
	H2 h2;

	Matcher(string& s) :h1(s), h2(s) {}
	Pii substr(int l, int r) const {
		return Pii(h1.substr(l, r).hash, h2.substr(l, r).hash);
	}
};

int solve(string s, string t) {
	int originalSSize = sz(s);
	while (sz(s) < originalSSize + sz(t)) s += s;

	Matcher ms(s), mt(t);
	Pii base = mt.substr(0, sz(t));

	vector<int> ok;
	FOR(i, originalSSize) {
		bool match = ms.substr(i, i + sz(t)) == base;
		ok.push_back(match);
	}

	int ans = 0;
	vector<bool> used(sz(ok));
	FOR(i, sz(used)) {
		if (used[i]) continue;
		int x = i;
		vector<int> cur;
		while (!used[x]) {
			used[x] = true;
			cur.push_back(ok[x]);
			x = (x + sz(t)) % sz(ok);
		}
		const int xx = sz(cur);
		FOR(i, xx) cur.push_back(cur[i]);
		int cnt = 0;
		for (auto c : cur) {
			if (c == 1) cnt++;
			if (c == 0) cnt = 0;
			ans = max(ans, cnt);
		}
		if (cnt == sz(cur)) return -1;
	}

	return ans;
}

int main() {
	string s, t; reader(s, t);

	int ans = solve(s, t);
	writerLn(ans);

	return 0;
}

