	vector<vector<ll>> g(S.size());
	for(auto it=z.begin()+T.size()+1; it!=z.begin()+T.size()+1+S.size(); it++){
		if(*it==T.size()){
			ll i=it-z.begin()-T.size()-1;
			ll to=(i+T.size()) % S.size();
			g[i].push_back(to);
			indegree[to]++;
		}
	}

	queue<ll> q;
	rep(i,S.size()) if(indegree[i]==0)q.push(i);

	vector<ll> dp(S.size(),0);
	ll sortcount=0;
	while(!q.empty()){
		ll v=q.front();
		q.pop();
		sortcount++;
		for(ll nextv : g[v]){
			dp[nextv]=dp[v]+1;
			indegree[nextv]--;
			if(indegree[nextv]==0)q.push(nextv);
