static void getStrMatchPos(
    string s, 
    string pat, 
    vector<SQWORD> &vsqRet)
{
    rolling_hash64 hash_str(s);
    rolling_hash64 hash_pat(pat);
    SQWORD size_str = s.size();
    SQWORD size_pat = pat.size();
    SQWORD sqHashVal = hash_pat.hash(0, size_pat);

    for (SQWORD i = 0; i < size_str - size_pat; i++) {
        if (hash_str.hash(i, i+size_pat) == sqHashVal) {
            vsqRet.emplace_back(i);
        } 
    }
}


