	mul[0] = 1;
	rep (i, 1, MAXN - 1) {
		mul[i] = mul[i - 1] * 41;
	}
	DoHash(Hash[0], t);
	DoHash(Hash[1], s);
	if (checkINF()) {
		cout << -1 << endl;
		return 0;
	}
	int l = 1, r = SZ(t) / SZ(s);
