class Matrix{
public:
	ull a, b, c, d;
	Matrix(){}
	Matrix(ull _a, ull _b, ull _c, ull _d): a(_a), b(_b), c(_c), d(_d){}
	Matrix operator * (const Matrix &M)const{
		Matrix ret;
		ret.a = a * M.a + b * M.c;
		ret.b = a * M.b + b * M.d;
		ret.c = c * M.a + d * M.c;
		ret.d = c * M.b + d * M.d;
		return ret;
	}
};

inline Matrix matpow(Matrix M, ull y){
	if(!y) return Matrix(1, 0, 0, 1);
	Matrix ret = M;
	for(--y; y; y >>= 1){
		if(y & 1) ret = ret * M;
		M = M * M;
	}
	return ret;
}

inline ull qpow(ull x, ull y){
	ull ret = 1;
	for(; y; y >>= 1){
		if(y & 1) ret *= x;
		x *= x;
	}
	return ret;
}

inline void add(ull &h, char c, ull P){
	(h *= P) += (c - 'a' + 1);
	return;
}

bool overlap(){
