	FOR(i, 0, m) (rs1 *= pw1[n]) += hs1, (rs2 *= pw2[n]) += hs2;
	FOR(i, 0, n) (rt1 *= pw1[m]) += ht1, (rs2 *= pw2[m]) += ht2;
	//printf("hs = %llu ht = %llu rs = %llu rt = %llu\n", hs, ht, rs, rt);
	return (rs1 == rt1 && rs2 == rt2);
}

bool check(int md){
	//printf("md = %d\n", md);
	ull rs1 = 0, rs2 = 0, rt1 = 0, rt2 = 0;
	FOR(i, 0, md) (rs1 *= pw1[n]) += hs1, (rs2 *= pw2[n]) += hs2;
	FOR(i, 0, m) if(m - i <= 1ll * md * n){
		rt1 = suf1[i], rt2 = suf2[i];
		ll copy = (1ll * md * n - (m - i)) / m, tail = (1ll * md * n - (m - i)) % m;
		//printf("i = %d copy = %d tail = %d\n", i, copy, tail);
		//printf("rt1 = %llu rs1 = %llu\n", rt1, rs1);
		rt1 *= qpow(P1, copy * m);
		rt2 *= qpow(P2, copy * m);
		Matrix M1 = Matrix(pw1[m], 0, 1, 1), M2 = Matrix(pw2[m], 0, 1, 1);
		M1 = matpow(M1, copy);
		M2 = matpow(M2, copy);
		//printf("M = (%llu %llu %llu %llu)\n", M1.a, M1.b, M1.c, M1.d);
		rt1 += ht1 * M1.c;
		rt2 += ht2 * M2.c;
		//printf("rt1 = %llu pw1 = %llu pre1 = %llu\n", rt1, pw1[tail], (tail) ? (pre1[tail - 1]) : 0);
		//printf("rt2 = %llu pw2 = %llu pre2 = %llu\n", rt2, pw2[tail], (tail) ? (pre2[tail - 1]) : 0);
		rt1 *= pw1[tail];
		rt2 *= pw2[tail];
		if(tail) rt1 += pre1[tail - 1];
		if(tail) rt2 += pre2[tail - 1];
		//printf("rt1 = %llu rs1 = %llu rt2 = %llu, rs2 = %llu\n", rt1, rs1, rt2, rs2);
		if(rs1 == rt1 && rs2 == rt2) return true;
	}
	return false;
}

