int Get(int ind)
{
    if (dp[ind] == -1) return -1;
    if (Z[tlen + 1 + ind] >= tlen) {
        int nind = (ind + tlen) % slen;
        dp[ind] = -1;
        int got = Get(nind);
        if (got == -1) return -1;
        dp[ind] = got + 1;
        return dp[ind];
    } else return 0;
}

