struct mint {
	int64_t value;
	mint() :value(0) {}
	mint(int64_t value_) : value(value_% MOD) {}
	inline mint& operator += (const mint& rhs) {
		value += rhs.value;
		if (value >= MOD) { value -= MOD; }
		return *this;
	}
	inline mint& operator -= (const mint& rhs) {
		value -= rhs.value;
		if (value < 0) {
			value += MOD;
		}
		return *this;
	}
	inline mint& operator *= (const mint& rhs) {
		value *= rhs.value;
		value %= MOD;
		return *this;
	}
	inline mint& operator %= (const mint& rhs) {
		return *this;
	}
};

inline mint operator + (const mint & lhs, const mint & rhs) { mint res = lhs; res += rhs; return res; }
inline mint operator - (const mint & lhs, const mint & rhs) { mint res = lhs;	res -= rhs;	return res; }
inline mint operator * (const mint & lhs, const mint & rhs) { mint res = lhs;	res *= rhs;	return res; }
inline mint operator % (const mint & lhs, const uint64_t & rhs) { return lhs; }

ostream& operator << (ostream & out, mint n) { return out << n.value; }

// x^n % mod
// O(log n)
mint mod_pow(mint x, uint64_t n) {
	mint res = 1;
	while (n > 0) {
		if (n & 1) res = res * x;
		x = x * x;
		n >>= 1;
	}
	return res;
}

const long long mod[] = { 999999937LL, 1000000007LL }, base = 9973;
struct rolling_hash64 {
	int n;
	vector<long long> hs, pw;
	rolling_hash64() {}
	rolling_hash64(const string& s) {
		n = s.size();
		hs.assign(n + 1, 0);
		pw.assign(n + 1, 0);
		pw[0] = 1;
		for (int i = 0; i < n; i++) {
			hs[i + 1] = hs[i] * base + s[i];
			pw[i + 1] = pw[i] * base;
		}
	}

	long long hash(int l, int r) { return hs[r] - hs[l] * pw[r - l]; }
	bool match(int l1, int r1, int l2, int r2) { return hash(l1, r1) == hash(l2, r2); }
};

class UnionFind {
	vector<int> to;
	vector<int> cnt;
	vector<int> rank;

public:
	UnionFind(int N) {
		to = vector<int>(N); REP(i, N) to[i] = i;
		cnt = vector<int>(N, 1);
		rank = vector<int>(N, 1);
	}

	size_t size() {
		return to.size();
	}

	int root(int node) {
		if (node == to[node]) {
			return node;
		}
		to[node] = root(to[node]);
		return to[node];
	}

	int count(int node) {
		return cnt[root(node)];
	}

	int same(int a, int b) {
		return root(a) == root(b);
	}

	void unite(int a, int b) {
		if (rank[a] < rank[b]) swap(a, b);
		int rootb = root(b), roota = root(a);
		to[rootb] = roota;
		cnt[roota] += cnt[rootb];
		if (rank[a] == rank[b]) ++rank[a];
	}
};

template<class T>
vector<T> tsort(const vector<vector<T> >& G) {
	vector<T> res;
	vector<T> in(G.size());
	for (auto &node : G) for (auto &to : node) ++in[to];

	queue<int> que;
	REP(i, in.size()) if (in[i] == 0) que.push(i);

	while (not que.empty()) {
		int n = que.front(); que.pop();
		res.push_back(n);
		for (auto &to : G[n]) if (--in[to] == 0) que.push(to);
	}
	return *max_element(ALL(in)) == 0 ? res : vector<T>();
}


void solve() {
	string S, T; cin >> S >> T;
	string s = S;
	{
		while (S.size() < T.size()) {
			S += s;
		}
	}
	S += S;
	rolling_hash64 RHs(S), RHt(T);
	vector<vector<int> > G(s.size());

	REP(i, s.size()) {
		if (RHs.hash(i, i + T.size()) == RHt.hash(0, T.size())) {
			G[i].emplace_back((i + T.size()) % (s.size()));
		}
	}

	vector<bool> isVisited(G.size());
	vector<int> ans = tsort(G);

	if (ans.size() == 0) {
		cout << -1 << endl;
		return;
	}

	vector<int> dp(G.size());
	int res = 0;
	for (auto& node : ans) {
		for (auto& to : G[node]) {
			dp[to] = dp[node] + 1;
			res = max(res, dp[to]);
		}
	}

	cout << res<< endl;
}

