	while (s.size() < 3 * t.size())
		s += ss;
	AhoCorasick<characters> aho(init);
	set<int> pos;
	{
		vvi res = aho.match(s);
		REP(i, res[0].size()) pos.insert(res[0][i] - t.size() + 1);
	}
	int n = s.size();
	UnionFind uf(n);
	for (auto a : pos) {
		if (a >= n) break;
		if (uf.same(a, (a + t.size()) % n)) {
			cout << -1 << endl;
			return 0;
		}
		uf.unite(a, (a + t.size()) % n);
	}
	map<int, int> mp;
	REP(i, n) mp[uf.root(i)]++;
	if (mp.size() == 1) {
		cout << -1 << endl;
	} else {
		int ans = 0;
		for (auto a : mp) {
			chmax(ans, a.second - 1);
		}
