using namespace std;
const int N = 8e6+1;

string s,t;
string Ls;
string Lt;

int z[N];

void Z(int siz){
   z[1] = siz;
   int mx,R; R = mx = 0;
   for(int i = 2;i <= siz; ++i){
      z[i] = (i < R)?min(R-i,z[i-mx+1]):0;
      while(Lt[i-1+z[i]] == Lt[z[i]])++z[i];
      if(i+z[i] > R)R = i+z[i],mx = i;
   }
}

int main(){
   ios::sync_with_stdio(false);
   cin >> s; cin >> t;
   Ls = s;
   while(Ls.size()-s.size() < t.size())Ls = Ls+s;
   Lt = t;
   while(Lt.size() < Ls.size())Lt = Lt+t;
   int pos = Lt.size()+1;
   Lt = Lt+"#"+Ls;
   Z(Lt.size());
   int ans = 0;
   for(int i = pos;i <= (int)Lt.size(); ++i){
      if(z[i])ans = max(ans,z[i]/(int)t.size());
   }
   if(ans == 0)puts("0");
   else {
      Ls = Ls+Ls;
      Lt = Lt+Lt;
      pos = Lt.size()+1;
      Lt = Lt+"#"+Ls;
      int ans2 = 0;
      Z(Lt.size());
      for(int i = pos;i <= (int)Lt.size(); ++i){
         ans2 = max(ans2,z[i]/(int)t.size());
      }
      //cerr << ans2 << ' ' << ans << endl;
      if(ans2 > ans)puts("-1");
      //else if(ans2 > ans)cerr << "error" << endl;
      else printf("%d\n",ans);
   }
   return 0;
}

