auto calc(const std::string &s) {
    std::vector<int> a(s.size() + 1);
    a[0] = -1;
    for (int i = 0, j = -1; i < s.size(); i++) {
        while (j >= 0 && s[i] != s[j]) j = a[j];
        j++;
        a[i + 1] = j;
    }
    return a;
}

auto find(const std::string &s, const std::string &p, const std::vector<int> &a, int start = 0) {
    int i = 0, m = start;
    while (m + i < s.size()) {
        if (p[i] == s[m + i]) {
            i++;
            if (i == p.size()) return m;
        } else {
            m = m + i - a[i];
            if (i > 0) i = a[i];
        }
    }

    return -1;
}

int main() {
    std::string s, t;
    std::cin >> s >> t;
    int n = s.size(), m = t.size();
    std::vector<int> e(s.size());
    auto ss = s;
    while (ss.size() < s.size() + t.size()) ss += s;
    auto a = calc(ss);

    for (int i = 0; i < n;) {
        auto next = find(ss, t, a, i);
        if (next < 0) break;
        e[next % n] = 1;
        i = next + 1;
    }

    int ret = 0;
    std::vector<int> p(n);
    for (int i = 0; i < n; i++) {
        if (e[i] < 0 || p[i]) continue;
        int j = i, tmp = 0;
        while (!p[j] && e[j]) {
            j = (j + m) % n;
            if (j == i) {
                std::cout << -1 << std::endl;
                return 0;
            }
            tmp++;
        }
        p[i] = tmp + p[j];
        ret = std::max(ret, p[i]);
    }

    std::cout << ret << std::endl;

    return 0;
}

