ht[1000010],ht2[1000010],res[4000010],ans=0;

pii gethash(LL a,LL b)
{
	return {(h[b+1]-h[a]*pw[b-a+1]%MOD+MOD)%MOD,(h2[b+1]-h2[a]*pw2[b-a+1]%MOD+MOD)%MOD};
}

pii gethash2(LL a,LL b)
{
	return {(ht[b+1]-ht[a]*pw[b-a+1]%MOD+MOD)%MOD,(ht2[b+1]-ht2[a]*pw2[b-a+1]%MOD+MOD)%MOD};
}

int main()
{
	pw[0]=pw2[0]=1;
	repn(i,4000005)
	{
		pw[i]=pw[i-1]*hn%MOD;
		pw2[i]=pw2[i-1]*hn2%MOD;
	}
	cin>>s>>t;
	ss=s;
	s+=s;
	s+=s;
	repn(i,s.size())
	{
		h[i]=(h[i-1]*hn+s[i-1]-'a')%MOD;
		h2[i]=(h2[i-1]*hn2+s[i-1]-'a')%MOD;
	}
