// strongly connected component
struct scc {
  using Graph = std::vector<std::vector<int>>;
  Graph G, rG;
  std::vector<int> vs, cmp;
  std::vector<bool> used;

  explicit scc(int N): G(N), rG(N) {}

  void dfs(int v) {
    used[v] = true;
    for(auto c: G[v]) if(!used[c]) dfs(c);
    vs.push_back(v);
  }
  void rdfs(int v, int k) {
    used[v] = true;
    cmp[v] = k;
    for(auto c: rG[v]) if(!used[c]) rdfs(c, k);
  }
  int build() {
    int V = G.size();
    used.assign(V, false);
    vs.clear();
    vs.reserve(V);
    cmp.resize(V);
    for(int v = 0; v < V; ++v) if(!used[v]) dfs(v);
    std::fill_n(used.begin(), V, false);
    int k = 0;
    for(int i = vs.size()-1; i >= 0; --i) {
      if(!used[vs[i]]) rdfs(vs[i], k++);
    }
    return k;
  }
  void add_edge(int fr, int to) {
    G[fr].push_back(to); rG[to].push_back(fr);
  }
};

// zarray
void zarray(std::string s, std::vector<int>& Z) {
  int N = s.size(), L, R = 0;
  Z.resize(N);
  for(int i = 1; i < N; ++i) {
    if(i > R) {
      L = R = i;
      while(R < N && s[R-L]==s[R]) ++R;
      Z[i] = R-- -L;
    } else if(Z[i-L] < R-i+1) {
      Z[i] = Z[i-L];
    } else {
      L = i;
      while(R < N && s[R-L] == s[R]) ++R;
      Z[i] = R-- -L;
    }
  }
}

int main() {
  std::string S, T; std::cin >> S >> T;
  int N = S.size(), M = T.size(), K = N+M-1;
  std::string U = S;
  for(int i = 0; i < (M-1)/N; ++i) U += S;
  U += S.substr(0, K - U.size());
  std::vector<int> Z;
  zarray(T+" "+U, Z);
  std::vector<int> v;
  for(int i = 0; i < N; ++i) if(Z[M+1+i]>=M) v.push_back(i);

  scc sc(N);
  if(v.size() < 1) fin(0);
  for(int fr: v) {
    int to = (fr+M)%N;
    if(fr == to) fin(-1);
    sc.add_edge(fr, to);
  }
  if(sc.build() < N) fin(-1);

  std::vector<int> depth(N, -1);
  int ans = 0;
  auto calc_depth = [&](auto&& f, int v) {
    if(depth[v] >= 0) return depth[v];
    int res = -1;
    for(auto c: sc.G[v]) res = std::max(res, f(f, c));
    ++res;
    return depth[v] = res;
  };
  for(int i = 0; i < N; ++i) {
    ans = std::max(ans, calc_depth(calc_depth, i));
  }
  fin(ans);

  return 0;
}

