class KnuthMorrisPratt
{
private:
    int n;
    string pattern;
    vector<int> failure;
public:
    KnuthMorrisPratt(const string& pattern){
        n = pattern.size();
        this->pattern = pattern;
        failure.assign(n+1, 0);
        for(int i=0; i<n; ++i){
            int j = i;
            while(j != 0){
                if(pattern[failure[j]] == pattern[i]){
                    failure[i+1] = failure[j] + 1;
                    break;
                }
                j = failure[j];
            }
        }
    }
    int transition(int curr, char c){
        if(curr < n && pattern[curr] == c)
            return curr + 1;
        if(curr == 0)
            return 0;
        return transition(failure[curr], c);
    }
};

int main()
{
    string s, t;
    cin >> s >> t;

    KnuthMorrisPratt kmp(t);
    int n = max(s.size(), t.size());
    vector<int> dp(3*n+1, 0);
    int curr = 0;
    for(int i=0; i<3*n; ++i){
        curr = kmp.transition(curr, s[i%s.size()]);
        if(curr == t.size())
            dp[i+1] = dp[i+1-t.size()] + 1;
    }

    int ans = *max_element(dp.begin(), dp.end());
    if(ans * t.size() >= 2 * n)
        ans = -1;
    cout << ans << endl;

    return 0;
}

