vector<int> KMPsearchV(const string& s, const string& t){
    int s_len = s.size(), t_len = t.size(), m = 0, k = 0;
    if(s_len < t_len) return vector<int>();
    if(t_len == 0) return vector<int>();
    vector<int> shift(t_len), ret;
    int i = 2, j = 0;
    if(t_len >= 1) shift[0] = -1;
    if(t_len >= 2) shift[1] = 0;
    while(i < t_len){
        if(t[i-1] == t[j]){
            shift[i] = j + 1;
            i++;
            j++;
        }else if(j > 0){
            j = shift[j];
        }else{
            shift[i] = 0;
            i++;
        }
    }
    while(m + k < s_len){
        if(t[k] == s[m+k]){
            if(k == t_len-1){
                ret.emplace_back(m);
                m = m + k - shift[k];
                if(k > 0) k = shift[k];
            }
            k++;
        }else{
            m = m + k - shift[k];
            if(k > 0) k = shift[k];
        }
    }
    return ret;
}

struct UnionFind{
    // par[i] parent. if i == par[i] i is root
    vector<ll> par;
    // sizes[i] sizeof tree i if i is root
    vector<ll> sizes;

    UnionFind(ll n): par(n), sizes(n, 1){
        // init: all node is root i
        rep(i, n) par[i] = i;
    }

    // find root of x
    ll find(ll x){
        if (x == par[x])
            return x;
        return par[x] = find(par[x]); // recursive, editing root
    }

    // merge x, y
    void unite(ll x, ll y){
        // root
        x = find(x);
        y = find(y);

        // do not merge if same tree
        if (x == y)
            return;

        // force size x > y
        if (sizes[x] < sizes[y])
            swap(x, y);

        // unite: x is parent of y
        par[y] = x;
        sizes[x] += sizes[y];
    }

    // x, y same root
    bool same(ll x, ll y){
        return find(x) == find(y);
    }

    // size of tree containing x
    ll size(ll x){
        return sizes[find(x)];
    }
};


int main(){
    string s;
