int solve(const string &s, const string &t, unsigned long ls, unsigned long lt) {
  int ret = 0;
  vector<bool> seen(ls, false);

  int i = -1;
  while (++i < ls) {
    i = boost::algorithm::boyer_moore_search(
        s.begin() + i, s.end(), t.begin(), t.end()).first - s.begin();
    if (i > ls) break;
    if (seen[i]) continue;

    int j = 0;
    while (true) {
      int p = boost::algorithm::boyer_moore_search(
          s.begin() + i + j * lt, s.end(), t.begin(), t.end()).first - s.begin();
      if (p - (i + j * lt) != 0) {
        break;
      }
      if (p < ls) seen[p] = true;
      if (j * lt >= ls) return -1;

      j += 1;
    }
    ret = max(ret, j);
  }
  return ret;
}

int main() {
  string s, t;
  cin >> s >> t;

  unsigned long ls, lt;
  ls = s.size();
  lt = t.size();

  do {
    s += s;
  } while (s.size() < t.size() * 3);
  int ret = solve(s, t, ls, lt);
  cout << ret << endl;
}

