///AUTOMATA
const int M = MM*20;
struct state
{
    int len, link,fpos;
    bool isclone;
    map < char , int > next;
} st[2*M];

int sz, last;

void initialize()
{
    rep(sz+1)
    {
        st[i].next.clear();
    }
    sz = last = 0;
    st[0].len = 0;
    st[0].link = -1;
}
void build_automata(char c)
{
    int cur = ++sz;
    st[cur].len = st[last].len + 1;
    st[cur].isclone = 0;
    st[cur].fpos = st[cur].len;
    int p;
    for(p=last;p!=-1 && !st[p].next[c];p=st[p].link)
    {
        st[p].next[c] = cur;
    }
    if(p==-1)
    {
        st[cur].link = 0;
    }
    else
    {
        int q = st[p].next[c];
        if(st[p].len+1==st[q].len)
        {
            st[cur].link = q;
        }
        else
        {
            int clone = ++sz;
            st[clone] = st[q];
            st[clone].len = st[p].len+1;
            st[clone].isclone = 1;
            for(;p!=-1 && st[p].next[c]==q;p=st[p].link)
            {
                st[p].next[c] = clone;
            }
            st[q].link = st[cur].link = clone;
        }
    }
    last = cur;
}

char s[M];

ll max_match(int len)
{
    int now = 0;
    int cnt = 0;
    rep(len)
    {
        now = st[now].next[s[i]-'a'];
        if(now==0)break;
        cnt++;
        if(i==len-1)i = -1;
    }
    return cnt/len;
}
set < int > stt;
int main() {

    sf("%s",s);
    initialize();
    int len = strlen(s);
    rep(len)build_automata(s[i]-'a'),stt.insert(s[i]);
    rep(len)build_automata(s[i]-'a');
    rep(len)build_automata(s[i]-'a');

    sf("%s",s);
    len = strlen(s);
    rep(len)stt.insert(s[i]);
    if(stt.size()==1)
    {
        cout<<-1<<endl;
        return 0;
    }
    cout<<max_match(len)<<endl;
    return 0;
}

