int getans(bool *smap, int ls, int lt)
{
    int *check = new int[ls];
    rep(j, ls) check[j] = 0;
    int ans = 0;

    rep(j, ls)
    {
        int count = 0;
        int jj = j;
        if( smap[jj] && check[jj] == 0 )
        {
            while( smap[jj] && check[jj] == 0 ) 
            {
                check[jj] = -1;
                count++;
                jj = (jj + lt) % ls;
                if( jj == j ) return -1;
            }
            check[j] = count + check[jj];
            ans = max(ans, check[j]);
        }
    }
    return ans;
}

