int n, m, dp[N];
long long hs[N], ht[N], pw[N];
char s[N], t[N];

long long get_hash(long long hsh[], int l, int r) {
    return ((hsh[r] - hsh[l - 1] * pw[r - l + 1]) % MOD + MOD) % MOD;
}

int solve() {
    pw[0] = 1;
    for (int i = 1; i < N; i++) {
        pw[i] = pw[i - 1] * 31 % MOD;
    }
    int n = strlen(s + 1), m = strlen(t + 1);
    for (int i = 1; i <= n; i++) {
        hs[i] = (hs[i - 1] * 31 + s[i] - 'a' + 1) % MOD;
    }
    for (int i = 1; i <= m; i++) {
        ht[i] = (ht[i - 1] * 31 + t[i] - 'a' + 1) % MOD;
    }
    int ans = 0;
    for (int i = m; i <= n; i++) {
        if (get_hash(ht, 1, m) == get_hash(hs, i - m + 1, i)) {
            dp[i] = dp[i - m] + 1;
        } else {
            dp[i] = 0;
        }
        ans = max(ans, dp[i]);
    }
    return ans;
}

