const int maxn=5000010,lg=24;

string s,t;
int n,m,z[maxn],p[lg][maxn],ans;

int main()
{
	cin>>s>>t;

	int sz=2*(t.size());
	while(s.size()<sz) s+=s;
	n=s.size();m=t.size();
	s+=s;

	string str=t+"$"+s;int l=0,r=0;

	z[0]=str.size();
	for(int i=1;i<str.size();i++)
    {
    	if(i>r)
        {
            l=r=i;
            while(r<str.size()&&str[r-l]==str[r]) r++;
            z[i]=r-l;r--;
        }
        else
        {
            int k=i-l;

            if(z[k]<r-i+1) z[i]=z[k];
            else
            {
                l=i;
                while(r<str.size()&&str[r-l]==str[r]) r++;
                z[i]=r-l;r--;
            }
        }
    }

    repa(i,m+1,n+m+1)
    {
    	int from=i-(m+1);
    	if(z[i]>=m)
    	{
    		int to=i+m-(m+1);
    		p[0][from]=to%n;
    	}
    	else
    	{
    		p[0][from]=-1;
    	}
    }

    rep1(i,lg-1) rep(j,n) if(p[i-1][j]==-1) p[i][j]=-1; else p[i][j]=p[i-1][p[i-1][j]];

    rep(j,n)
    {
    	int cur=j,res=0;
    	repd(i,lg)
    	{
    		if(p[i][cur]!=-1)
    		{
    			cur=p[i][cur];
    			res+=1<<i;
    		}
    	}

    	ans=max(ans,res);
    }

    if(ans>=n) cout<<-1; else cout<<ans;

	return 0;
}
