int MP(std::string &S, std::vector<long long int> &A){

  A[0] = -1;
  long long int L = S.length();
  long long int j = -1;

  for(long long int i = 0; i < L; i++){
    while(j >= 0 && S[i]!=S[j]) j=A[j];
    j++;
    A[i+1] = j;
  }

  return 0;
}

int KMP(std::string &S, std::string &word, std::vector<long long int> &match_table){

  // preparation: MP calculation
  std::vector<long long int> MP_table(word.length()+1);
  MP(word, MP_table);
  match_table.clear();

  // make match_table
  long long int m  = 0, i = 0, ls = S.length(), lword = word.length();

  while(m+i < ls){
    if(word[i] == S[m+i]){
      i++;
      if(i == lword){
        match_table.push_back(m);
        m = m+i - MP_table[i];
        i = MP_table[i];
      }
    }
    else{
      m = m+i - MP_table[i];
      if(i > 0){
        i = MP_table[i];
      }
    }
  }

  return 0;
}

long long int euclid_gcd(long long int x, long long int y){
  if(y == 0){
    return x;
  }
  /*else if(x == 0){
    return y;
  }*/
  else{
    return euclid_gcd(y, x%y);
  }
}

#include<bits/stdc++.h>
using namespace std;

const unsigned long long bigp=(1ULL<<61)-1ULL;
const unsigned long long smallp=(1ULL<<31)-1ULL;
const unsigned long long smallpplus=(1ULL<<31);
const unsigned long long smallpminus=(1ULL<<30)-1ULL;

unsigned long long b=80173;

class hash_mod{
    public:
    unsigned long long val;
    unsigned long long val_u, val_d;
    unsigned long long another_u, another_d;
    unsigned long long m, m_u, m_d;

    void remainder(){
        val_u=(val>>61);
        val_d=val&bigp;
        if(val_u + val_d <bigp) val= val_u + val_d;
        else val= (val_u + val_d) -bigp;
    }

    void update(unsigned long long v){
        val=v;
        remainder();
    }

    void addition(unsigned long long another){
        val+=another;
        remainder();
    }

    void subtraction(unsigned long long another){
        val+=bigp;
        val-=another;
        remainder();
    }

    void multiple(unsigned long long another){
        val_u=(val>>31);
        val_d=val&smallp;
        another_u=(another>>31);
        another_d=another&smallp;
        m=val_u*another_d + val_d*another_u;
        m_u=(m>>30);
        m_d=m&smallpminus;
        val=0;
        val+=val_u*another_u*(2ULL);
        val+=m_u + m_d*smallpplus;
        val+=val_d*another_d;
        remainder();
    }
};

int main(){
    //input
    string S,T;
    cin >> S >> T;

    unsigned long long i,j;

    unsigned long long N,M;
    N=S.length();
    M=T.length();
    while(S.length()<3*M) S+=S;

    char c='a';
    c--;

    hash_mod T_hash;
    T_hash.update(0ULL);
    for(i=0; i<M; i++){
        T_hash.multiple(b);
        T_hash.addition((unsigned long long)(T[i]-c));
    }

    hash_mod sub, b_pow;
    b_pow.update(1ULL);
    for(i=0; i<M-1; i++){
        b_pow.multiple(b);
    }

    bool in[N], out[N], visited[N];
    for(i=0; i<N; i++){
        in[i]=0;
        out[i]=0;
        visited[i]=0;
    }

    hash_mod S_hash;
    S_hash.update(0ULL);
    for(i=0; i<M; i++){
        S_hash.multiple(b);
        S_hash.addition((unsigned long long)(S[i]-c));
    }
    if(S_hash.val==T_hash.val){
        out[0]=1;
        in[M]=1;
    }
    for(i=M; i<N+M; i++){
        sub.update((unsigned long long)(S[i-M]-c));
        sub.multiple(b_pow.val);
        S_hash.subtraction(sub.val);
        S_hash.multiple(b);
        S_hash.addition((unsigned long long)(S[i]-c));
        if(S_hash.val==T_hash.val){
            out[i-(M-1)]=1;
            in[(i+1)%N]=1;
        }
    }
    //dfs
    unsigned long long ans=0, val;
    for(i=0; i<N; i++){
        if(out[i]==1&&in[i]==0){
            visited[i]=1;
            val=1;
            j = (i+M)%N;
            while(out[j]==1){
                visited[j]=1;
                val++;
                j = (j+M)%N;
            }
            ans=max(ans,val);
        }
    }
    bool loop=0;
    for(i=0; i<N; i++){
        if(visited[i]==0&&out[i]==1){
            loop=1;
        }
    }

    //output
    if(loop==1){
        cout << -1 << endl;
    }else{
        cout << ans << endl;
    }
    system("pause");
    return 0;
}

