using namespace std;

typedef vector<int> vi;

void init(string& P, vi& b)
{
    int i = 0, j = -1; b[0] = -1;
    while (i < P.size())
    {
        while (j >= 0 && P[i] != P[j]) j = b[j];
        b[++i] = ++j;
    }
}

vi kmp(string& T, string& P, vi& b)
{
    vi ret(T.size());
    int i = 0, j = 0;
    while (i < T.size())
    {
        while (j >= 0 && T[i] != P[j]) j = b[j];
        ++i; ++j;
        if (j == P.size())
        {
            ret[i - j] = 1;
            j = b[j];
        }
    }

    return ret;
}

vi A, B, r;
int d;
int n;

void cycle() { cout << -1; exit(0); }
int next(int i) {
    if((i += d) >= r.size()) i -= r.size();
    return i;
}

int dfs(int i) {
    if(r[i] == 0) {
        B[i] = 2;
        return 0;
    }

    B[i] = 1;
    int l = next(i);
    if(B[l] == 1) cycle();
    if(B[l] == 2) A[i] = A[l] + 1;
    else A[i] = dfs(l) + 1;

    B[i] = 2;
    return A[i];
}

int main() {
    string s, t; cin >> s >> t;
    n = s.size();
    while(s.size() < t.size())
        s += s;

    d = t.size();
    s += s;

    vi b(t.size() + 1);
    init(t, b);
    r = kmp(s, t, b);
    for(int i = 0; i < s.size(); ++i)
        r[(i + n) % r.size()] |= r[i];

    A.resize(r.size());
    B.resize(r.size());

    int mx = 0;
    for(int i = 0; i < r.size(); ++i)
        if(!B[i]) mx = max(mx, dfs(i));

    cout << mx;
    return 0;
}

