struct Rand{
    mt19937_64 mt;
    random_device rd;
    Rand(){ mt.seed(rd()); }
    void seed(){ mt.seed(rd()); }
    void seed(const ull seed_){ mt.seed(seed_); }

    // x1.5 slower than prepared uid
    // 64bit
    ull operator()(){
        return mt();
    }
    // int [0, max)
    ll operator()(const ll max_){
        uniform_int_distribution<> uid(min<ll>(0, max_-1), max<ll>(0, max_-1));
        return uid(mt);
    }
    // int [min, max]
    ll operator()(const ll min_, const ll max_){
        uniform_int_distribution<> uid(min(min_, max_), max(min_, max_));
        return uid(mt);
    }
    // real [0, max)
    ld operator()(const ld max_){
        uniform_real_distribution<> uid(min<ld>(0, max_), max<ld>(0, max_));
        return uid(mt);
    }
    // real [min, max)
    ld operator()(const ld min_, const ld max_){
        uniform_real_distribution<> uid(min(min_, max_), max(min_, max_));
        return uid(mt);
    }
};
