int main(){
    cin.tie(0); ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    string s;
    cin >> s;
    string t;
    cin >> t;
    ll ns = SZ(s);
    ll nt = SZ(t);
    ll gn = GCD(ns, nt);
    RollingHash rs(s), rt(t);
    {
        ull tmp = rs.get(0, gn);
        bool f = 1;
        rep(i, ns/gn){
            if(rs.get(i*gn, (i+1)*gn) != tmp){
                f = 0;
                break;
            }
        }
        rep(i, nt/gn){
            if(rt.get(i*gn, (i+1)*gn) != tmp){
                f = 0;
            }
            if(!f){
                break;
            }
        }
        if(f){
            cout << -1 << endl;
            return 0;
        }
    }
    // ring
    vll ans(ns, 0);
    vi ansf(ns, 0);
    string s2 = "";
    while(SZ(s2) < max(2*nt-1, ns+nt-1)){
        s2 += s;
    }
    RollingHash rs2(s2);
    rep(i, ns){
        ansf[i] = (rs2.get(i, i+nt) == rt.get(0, nt));
    }
    vvi node(ns);
    rep(i, ns){
        if(ansf[i] == 1){
            node[i].emplace_back((i+nt)%ns);
            node[(i+nt)%ns].emplace_back(i);
        }
    }
    rep(i, ns)if(ans[i] == 0){
        int deepest = 0;
        int diameter = 0;
        queue<vll> q;
        q.push({0, i, i}); // depth, self, parent
        while (!q.empty())
        {
            vll qf = q.front();
            q.pop();
            deepest = qf.at(1);
            for (auto &e : node.at(qf.at(1)))
            {
                if (e != qf.at(2))
                {
                    q.push({qf.at(0) + 1, e, qf.at(1)});
                }
            }
        }
        q.push({0, deepest, deepest}); // depth, self, parent
        vll nodes;
        while (!q.empty())
        {
            vll qf = q.front();
            q.pop();
            diameter = qf.at(0);
            nodes.emplace_back(qf[1]);
            for (auto &e : node.at(qf.at(1)))
            {
                if (e != qf.at(2))
                {
                    q.push({qf.at(0) + 1, e, qf.at(1)});
                }
            }
        }
        rep(j, SZ(nodes)){
            ans[nodes[j]] = diameter;
        }
    }
    dump(ans);
    cout << *max_element(ALL(ans)) << endl;
    return 0;
}

