// Z algorithm
struct Z {
  vi a;
  Z(){}
  Z(string& s):a(sz(s)) {
    int n = sz(s); a[0] = n;
    for (int i=1,j=0;i<n;) {
      while (i+j<n && s[j]==s[i+j]) ++j;
      a[i] = j;
      int k = !!j;
      while (i+k<n && k+a[k]<j) a[i+k] = a[k], ++k;
      i += k+!j; j -= k;
    }
  }
  inline int operator[](int i) { return a[i];}
};
//

// KMP
struct KMP {
  vi a;
  KMP(){}
  KMP(const string& s):a(sz(s)+1,-1) {
    int i = 0, j = -1;
    while (i < sz(s)) {
      while (~j && s[i] != s[j]) j = a[j]; //
      a[++i] = ++j;
      // if (i < sz(s) && s[i] == s[j]) a[i] = a[j]; // Knuth
    }
  }
  inline int operator[](int i) { return a[i];}
};
