{
    int z = x*m;
    int ha = h2.hash(0, z), hax = h2x.hash(0, z);
    for(int i = 0; i+z < n; ++i)
        if(h1.hash(i, z) == ha and h1x.hash(i, z) == hax)
            return 1;
    return 0;
}

long binsearch(long lo, long hi)
{
    while(lo <= hi)
    {
        long mid = lo + (hi-lo)/2;
        if(check(mid))
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return hi;
}

