vector<int> Z_algorithm(string S){
  // cerr << S << endl;
  int c = 0, n = S.length();
  vector<int> Z(n,0);
  for(int i = 1; i < n; ++i){
    int l = i - c;
    if(i + Z[l] < c + Z[c]){
      Z[i] = Z[l];
    }else{
      int j = max(0, c + Z[c] - i);
      while(i + j < n && S[j] == S[i+j]) ++j;
      Z[i] = j;
      c = i;
    }
  }
  return Z;
}

string min_cycle(string S){
  vector<int> Z = Z_algorithm(S+S);
  int L = S.length();
  // for(auto e : Z) cerr << e << " ";
  // cerr << endl;
  for(int i = 0; i < L; ++i){
    if(Z[i] >= L){
      return S.substr(0,i);
    }
  }
  return S;
}

