class RollingHash {
    template <int B, int M>
    class RollingHashPart {
      private:
        size_t len;
        std::vector<int> pow_b, hash;

      public:
        RollingHashPart() {}
        template <typename T>
        RollingHashPart(const T &s) : len(s.size()), pow_b(s.size() + 1), hash(s.size() + 1) {
            pow_b[0] = 1;
            hash[0]  = 0;
            for (int i = 0; i < len; i++) {
                pow_b[i + 1] = (ll)pow_b[i] * B % M;
                hash[i + 1]  = ((ll)hash[i] * B + s[i]) % M;
            }
        }
        // [l, r)
        int get(int l, int r) const {
            int res = (hash[r] - (ll)hash[l] * pow_b[r - l]) % M;
            if (res < 0)
                res += M;
            return res;
        }
    };

  public:
    using HashData = pair<int, int>;
    RollingHashPart<1033, 1000000007> rh1;
    RollingHashPart<6037, 999999937> rh2;

    RollingHash() {}
    template <typename T>
    RollingHash(const T &s) : rh1(s), rh2(s) {}
    // [l, r)
    HashData get(int l, int r) const { return HashData{rh1.get(l, r), rh2.get(l, r)}; }
    // [l1, r1), [l2, r2)
    int lcp(const RollingHash &rhs, int l1, int r1, int l2, int r2) const {
        int lb = 0, ub = std::min(r1 - l1, r2 - l2) + 1;
        while (ub - lb > 1) {
            int md                                               = (lb + ub) >> 1;
            (get(l1, l1 + md) == rhs.get(l2, l2 + md) ? lb : ub) = md;
        }
        return lb;
    }
};

int main() {
    string s, t;
    cin >> s >> t;
    string ss = s;
    int ns    = s.size();
    int nt    = t.size();
    while ((int)ss.size() < (int)nt * 4) {
        ss += ss;
    }
    RollingHash rhs(ss), rht(t);
    vector<vector<int>> edges(ns);
    for (int i = 0; i < ns; ++i) {
        if (rht.get(0, nt) == rhs.get(i, i + nt)) {
            edges[i].emplace_back((i + nt) % ns);
        }
    }
    vector<int> dist(ns, -1);
    bool loop                   = false;
    function<int(int, int)> dfs = [&](int c, int d) {
        if (loop || d > ns * 2) {
            loop = true;
            return 0;
        }
        if (dist[c] != -1)
            return dist[c];
        int temp = -1;
        for (auto &v : edges[c]) {
            chmax(temp, dfs(v, d + 1));
        }
        return dist[c] = temp + 1;
    };
    for (int i = 0; i < ns; ++i) {
        dfs(i, 1);
    }
    if (loop) {
        assert(false);
        cout << -1 << "\n";
        return 0;
    } else {
        int maxi = 0;
        for (int i = 0; i < ns; ++i) {
            chmax(maxi, dist[i]);
        }
        cout << maxi << "\n";
    }

    return 0;
}

