vector<int> Z_algo(const string &S) {
	int N = S.size();
	vector<int> z(N);
	z[0] = N;
	int i = 1, j = 0;
	while (i < N) {
		while (i + j < N && S[j] == S[i + j]) j++;
		z[i] = j;
		if (j == 0) { i++; continue; }
		int k = 1;
		while (i + k < N && k + z[k] < j) z[i + k] = z[k], k++;
		i += k; j -= k;
	}
	return z;
}
