struct Segment_tree{
    ll N;
    T mem;
    vector<T> node;
    Segment_tree(vector<T> &X,T m):mem(m){
        ll sz=X.size();
        N=1;
        while(N<sz) N*=2;
        node.resize(2*N-1,mem);
        rep(i,0,sz) node[N-1+i]=X[i];
        per(i,N-2,0){
            node[i]=Compare(node[i*2+1],node[i*2+2]);
        }
    }
    T Compare(T &A,T &B){
        return std::max(A,B);
    }
    void update(ll X,T val){
        X+=N-1;
        node[X]=val;
        while(X>0){
            X=(X-1)/2;
            node[X]=Compare(node[X*2+1],node[X*2+2]);
        }
    }
    T Query(ll a,ll b,ll now,ll l,ll r){ //[a,b),[l,r)
        if(r<0) r=N;
        if(r<=a||b<=l) return mem;
        if(a<=l&&r<=b) return node[now];
        auto vl=Query(a,b,now*2+1,l,(l+r)/2),vr=Query(a,b,now*2+2,(l+r)/2,r);
        return Compare(vl,vr);
    }
};
struct Binary_indexed_tree{
    int N;
    vi bit;
    Binary_indexed_tree(int n):N(n){
        bit.resize(N+1,0);
    }
    void add(int x,int a){
        for(x;x<=N;x+=(x&-x)) bit[x]+=a;
    }
    ll sum(int x){
        ll ret=0;
        for(x;x>0;x-=(x&-x)) ret+=bit[x];
        return ret;
    }
    ll lower_bound(ll X){
        if(sum(N)<X) return -1;
        ll ret=0,memo=1,sum=0;
        while(memo*2<=N) memo*=2;
        while(memo>0){
            if(memo+ret<=N&&sum+bit[memo+ret]<X){
                sum+=bit[memo+ret];
                ret+=memo;
            }
            memo/=2;
        }
        return ret+1;
    }
};
struct Union_Find{
    ll N;
    vi par;
    vi siz;
    Union_Find(int n):N(n){
        par.resize(N);
        siz.resize(N,1);
        rep(i,0,N) par[i]=i;
    }
    ll root(ll X){
        if(par[X]==X) return X;
        return par[X]=root(par[X]);
    }
    bool same(ll X,ll Y){
        return root(X)==root(Y);
    }
    void unite(ll X,ll Y){
        X=root(X);
        Y=root(Y);
        if(X==Y) return;
        par[X]=Y;
        siz[Y]+=siz[X];
        siz[X]=0;
    }
    ll size(ll X){
        return siz[root(X)];
    }
};
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}
vi fac,finv,inv;
void COMinit() {
    fac.resize(MAX);
    finv.resize(MAX);
    inv.resize(MAX);
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
ll COM(ll n,ll r){
    if(n<r||n<0||r<0) return 0;
    return fac[n]*finv[r]%MOD*finv[n-r]%MOD;
}
void comp(vi &A){
    std::map<ll,ll> mem;
    rep(i,0,A.size()) mem[A[i]]=0;
    ll cnt=0;
    for(auto &p:mem) p.second=cnt++;
    rep(i,0,A.size()) A[i]=mem[A[i]];
}
void change(string &S){
    ll N=S.size();
    std::set<ll> memo;
    REP(i,1,sqrt(N)){
        if(N%i==0){
            memo.insert(i);
            memo.insert(N/i);
        }
    }
    for(auto p:memo){
        string T=S.substr(0,p);
        string X;
        bool flag=1;
        rep(i,p,N){
            X+=S[i];
            if(X.size()==p){
                if(X==T) X="";
                else{
                    flag=0;
                    break;
                }
            }
        }
        if(flag){
            S=T;
            return;
        }
    }
}
bool judge(string S,string T){
    srand((unsigned)time(NULL));
    vi mod(3);
    vi memo(3);
    rep(i,0,100) rand();
    rep(i,0,3) mod[i]=rand()%MOD+1;
    ll N=S.size(),M=T.size();
    rep(i,0,3) memo[i]=modpow(10,M,mod[i]);
    vi model(3);
    vi now(3);
    rep(i,0,3){
        rep(j,0,M){
            ll X=T[j]-'a';
            ll Y=S[j]-'a';
            model[i]=(model[i]*10%mod[i]+X)%mod[i];
            now[i]=(now[i]*10+Y)%mod[i];
        }
    }
    bool flag=1;
    rep(i,0,3){
        if(model[i]!=now[i]){
            flag=0;
            break;
        }
    }
    if(flag) return 1;
    rep(i,M,N){
        flag=1;
        rep(j,0,3){
            ll X=S[i-M]-'a',Y=S[i]-'a';
            now[j]=(now[j]*10+Y)%mod[j];
            now[j]-=memo[j]*X%mod[j];
            now[j]%=mod[j];
            if(now[j]<0) now[j]+=mod[j];
            if(model[j]!=now[j]) flag=0;
        }
        if(flag) return 1;
    }
    return 0;
}
int main(){
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    string S,T; cin>>S>>T;
    change(S);
    ll N=S.size(),M=T.size();
    ll ans;
    if(N<=M){
        string X;
        REP(i,0,M/N) X+=S;
        if(judge(X,T)){
            if(M%N) ans=1;
            else ans=-1;
        }
        else ans=0;
    }
    else{
        S+=S;
        N*=2;
        ll left=0,right=N/M;
        while(left+1<right){
            ll mid=(left+right)/2;
            string X;
            rep(i,0,mid) X+=T;
            if(judge(S,X)) left=mid;
            else right=mid;
        }
        ans=left;
        string X;
        rep(i,0,right) X+=T;
        if(judge(S,X)) ans=right;
        if(ans*M>=N&&N%M>0) ans=-1;
    }
    cout<<ans<<endl;
}

