// https://github.com/beet-aizu/library/blob/master/string/knuth_morris_pratt.cpp
// longest prefix suffix matching of [0, i)
vector<int> KMPTable(const string &s){
    int n = s.size();
    vector<int> kmp(n+1, -1), mp(n+1, -1);
    for(int i = 0, j = -1; i < n; i++){
        while(~j && s[i] != s[j]) j = kmp[j];
        kmp[i+1] = mp[i+1] = ++j;
        if(i + 1 < n && s[i+1] == s[j]) kmp[i+1] = kmp[j];
    }
    return mp;
}
// smallest d s.t. s[x] == s[x + d] for all x
vector<int> minimum_period(const string &s){
    int n = s.size();
    vector<int> mp = KMPTable(s);
    for(int i = 1; i < n; i++) mp[i] = i - mp[i];
    return mp;
}
// positions for s that match t
vector<int> KMPSearch(const string &s,const string &t){
    int n = s.size(), m = t.size();
    vector<int> kmp = KMPTable(t);

    vector<int> res;
    int i = 0, j = 0;
    while(i + j < n){
        if(t[j] == s[i+j]){
            if(++j != m) continue;
            res.emplace_back(i);
        }
        i += j - kmp[j];
        j = max(kmp[j], 0);
    }
    return res;
}

struct UnionFind{
    // par[i] parent. if i == par[i] i is root
    vector<ll> par;
    // sizes[i] sizeof tree i if i is root
    vector<ll> sizes;

    UnionFind(ll n): par(n), sizes(n, 1){
        // init: all node is root i
        rep(i, n) par[i] = i;
    }

    // find root of x
    ll find(ll x){
        if (x == par[x])
            return x;
        return par[x] = find(par[x]); // recursive, editing root
    }

    // merge x, y
    void unite(ll x, ll y){
        // root
        x = find(x);
        y = find(y);

        // do not merge if same tree
        if (x == y)
            return;

        // force size x > y
        if (sizes[x] < sizes[y])
            swap(x, y);

        // unite: x is parent of y
        par[y] = x;
        sizes[x] += sizes[y];
    }

    // x, y same root
    bool same(ll x, ll y){
        return find(x) == find(y);
    }

    // size of tree containing x
    ll size(ll x){
        return sizes[find(x)];
    }
};


