const int N=2e6+5;
vi ln(N),idx(N,-1),Z,vals(N,-1),asked(N);
vector<int> z_function(string s) {
    int n = (int) s.length();
    vector<int> z(n); 
    for (int i = 1, l = 0, r = 0; i < n; ++i) {
        if (i <= r)
            z[i] = min (r - i + 1, z[i - l]); // use previous z val
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) // trivial matching
            ++z[i];
        if (i + z[i] - 1 > r)
            l = i, r = i + z[i] - 1; // update rightmost segment matched
    }
    return z;
}
int get(int i){
	if(vals[i]>-1)
		return vals[i];
	if(idx[i]==-1)
		return vals[i]=ln[i];
	asked[i]=1;
	if(asked[idx[i]]){
		cout<<-1<<endl;
		exit(0);
	}
	vals[i]=ln[i]+get(idx[i]);
	asked[i]=0;
	return vals[i];
}
int main()
{
