		s+=s1;
	string temp=t+"$"+s+s;
	Z=z_function(temp);
	int n=s.size(),m=t.size();
	int ans=0;
	for(int i=n-1;i>=0;i--){
		if(i+m-1>=n-1){
			int c=Z[i+m+1];
			if(c<m)continue;
			ans=1;
			ln[i]=1;
			idx[i]=m-(n-i);
			continue;
		}
		int c=Z[i+m+1];
		if(c<m)continue;
		ans=max(ans,1+ln[i+m]);
		ln[i]=1+ln[i+m];
		if(idx[i+m]>-1)
			idx[i]=idx[i+m];
	}
	for(int i=0;i<n;i++){
		ans=max(ans,get(i));
	}
	cout<<ans<<endl;
}

