class knuth_morris_pratt {
public:
  using size_type = size_t;

private:
  static constexpr size_type npos = -1;
  std::string M_p;
  std::vector<size_type> M_a;

public:
  knuth_morris_pratt() = default;
  knuth_morris_pratt(std::string const& p): M_p(p), M_a(p.length()+1) {
    M_a[0] = npos;
    for (size_type i = 0, j = npos; i < p.length(); ++i) {
      while (j != npos && p[i] != p[j]) j = M_a[j];
      ++j;
      M_a[i+1] = ((p[i+1] == p[j])? M_a[j]: j);
    }
  }

  std::vector<size_type> find_all(std::string const& s) const {
    std::vector<size_type> res;
    size_type j = 0;
    for (size_type i = 0; i < s.length(); ++i) {
      while (j != npos && M_p[j] != s[i]) j = M_a[j];
      if (++j == M_p.length()) {
        res.push_back(i-j+1);
        j = M_a[j];
      }
    }
    return res;
  }
};

void test(std::string const& pat, std::string const& text, std::vector<size_t> const& expected) {
  knuth_morris_pratt kmp(pat);
  auto res = kmp.find_all(text);
  for (size_t i = 0; i < res.size(); ++i)
    fprintf(stderr, "%zu%c", res[i], i+1<res.size()? ' ': '\n');

  assert(res == expected);
}

