intmax_t neko(std::string const& s, std::string const& t) {
  size_t n = s.length();
  size_t m = t.length();
  knuth_morris_pratt kmp(t);
  auto res = kmp.find_all(s+s);
  std::vector<int> a(2*n);
  for (auto ri: res) ++a[ri];
  for (size_t i = m; i < 2*n; ++i)
    if (a[i]) a[i] += a[i-m];

  int a0 = *std::max_element(a.begin(), a.begin()+n);
  int a1 = *std::max_element(a.begin()+n, a.end());
  if (a0 < a1) return -1;
  return a0;
}

