void hashIt(){
    h1[ n-1 ] = a[n-1]-'a'+1;
    for(ll i=n-2; i>=0; i--) h1[i] = ( (( h1[i+1]*p )%mod) + a[i]-'a'+1 )%mod;

    h2[ m-1 ] = b[m-1]-'a'+1;
    for(ll i=m-2; i>=0; i--) h2[i] = ( (( h2[i+1]*p )%mod) + b[i]-'a'+1 )%mod;
