}

ll getHash( ll L , ll R ){
    if( R==n-1 ) return h1[L];
    ll quita = (h1[R+1]*pot[ R-L+1 ])%mod;
    return (h1[L]-quita+mod)%mod;
}

vector<ll> z;

void fZ(){

    z.resize(s.size());
    fill( z.begin() , z.end() , 0);
    ll myN = s.size();

    for(ll i=1,l=-1,r=-1; i<myN; i++){
        if(r > i) z[i] = min( z[i-l] , r-i+1);
        while( i+z[i]<myN && s[i+z[i]] == s[z[i]] ) z[i]++;
        if(i+z[i]-1>r) l = i , r = i + z[i] - 1;
    }

    return;
}

