void cmp()
{
	int j;
	for(int i=0;i<=n;)
	{
		for(j=0;j<m;j++)
			if(a[i+j]!=t[j])
			{
				i+=j-nxt[j];
				j=m+1;
			}
		if(j==m)
		{
			ok[i]=true;
			i++;
		}
	}
