using namespace std;

vector<int> suffix_array(string s) {
  int n = s.size();
  int k, no, ne;
  vector<int> sa(n + 1);
  vector<vector<int>> rank(2, vector<int>(n + 1));
  auto compare = [&](int i, int j) {
    if (rank[no][i] != rank[no][j]) return rank[no][i] < rank[no][j];
    int ri = i + k <= n ? rank[no][i + k] : -1;
    int rj = j + k <= n ? rank[no][j + k] : -1;
    return ri < rj;
  };
  for (int i = 0; i <= n; i++) {
    sa[i] = i;
    rank[0][i] = i < n ? s[i] : -1;
  }
  for (int i = 0; (1 << i) <= n; i++) {
    k = 1 << i;
    no = i % 2, ne = (no + 1) % 2;
    sort(sa.begin(), sa.end(), compare);
    rank[ne][sa[0]] = 0;
    for (int i = 1; i <= n; i++) {
      rank[ne][sa[i]] = rank[no][sa[i - 1]] + compare(sa[i - 1], sa[i]);
    }
  }
  return sa;
}

struct UnionFind {
  vector<int> data;
  UnionFind(int n) {
    data.assign(n, -1);
  }
  int root(int k) {
    if (data[k] < 0) return k;
    return data[k] = root(data[k]);
  }
  bool unite(int x, int y) {
    x = root(x), y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }
  int size(int k) {
    return -data[root(k)];
  }
};

