template<unsigned long long M, unsigned long long B>
struct BasicRollingHash {
  using Uint = unsigned long long;
  using U128 = __uint128_t;
  vector<Uint> hashes, pows;

  template<class T>
  BasicRollingHash(const T& s) { init(s); }

  template<class T>
  void init(const T& s) {
    size_t n = s.size();
    hashes.assign(n + 1, 0);
    pows.assign(n + 1, 0);
    pows[0] = 1;
    for (size_t i = 1; i <= n; ++i) {
      hashes[i] = U128(hashes[i - 1] + s[i - 1]) * B % M;
      pows[i] = U128(pows[i - 1]) * B % M;
    }
  }

  template<class T>
  static Uint hash_once(const T& s) {
    Uint h = 0;
    for (size_t i = 1; i <= s.size(); ++i) {
      h = U128(h + s[i - 1]) * B % M;
    }
    return h;
  }

  // [l, r)
  Uint hash(size_t l, size_t r) const {
    r = min(r, size());
    U128 h = M + U128(hashes[r]) - U128(pows[r - l]) * hashes[l] % M;
    if (h > M) h -= M;
    return h;
  }

  size_t size() const {
    return hashes.size() - 1;
  }

  template<class T>
  vector<size_t> search_all(const T& s, size_t l = 0, size_t r = 1 << 30) 
  const {
    auto h = hash_once(s);
    int n = s.size();
    vector<size_t> res;
    for (int i = l; i <= int(min(r, size() - n)); ++i) {
      if (hash(i, i + n) == h) res.push_back(i);
    }
    return res;
  }
};
using RollingHash = BasicRollingHash<(1ull << 61) - 1, 263>;

int main() {
  string s, t;
  cin >> s >> t;
  while (s.size() < t.size()) {
    s += s;
  }
  i64 n = s.size();
  s = s + s + s;
  auto ms = RollingHash(s).search_all(t);
  vector<i64> dp(s.size());
  vector<bool> mp(s.size());
  i64 m = t.size();
  for (i64 i : ms) {
    mp[i] = true;
  }
  i64 ans = 0;
  for (i64 i = 0; i < s.size(); ++i) {
    if (mp[i]) dp[i]++;
    if (i - m >= 0) dp[i] += dp[i - m];
    if (i < 2 * n) {
      ans = max(ans, dp[i]);
    } else if (ans < dp[i]) {
      cout << -1 << endl;
      return 0;
    }
  }
  cout << ans << endl;
  return 0;
}

