bool isOK(string SS, string T, LL mid) {
    LL cnt = 0;
    LL maxV = 0;
    for (int i = 0; i < SS.size(); i++) {
        bool good = true;
        LL k = -1;
        for (int j = 0; j < T.size(); j++) {
            if (SS[(i + j)] != T[j]) {
                good = false;
                k = j;
                break;
            }
        }
        if (good) {
            cnt++;
            i += T.size() - 1;
        } else {
            maxV = max(cnt, maxV);
            cnt = 0;
            i += max(0LL, (k - 1));
        }
    }
    maxV = max(maxV, cnt);
    return maxV >= mid;
}

