	j = 0;

	for (i = 1; i < m; i++)
	{
		while (j > 0 && t[i] != t[j])
		{
			j = f[j - 1];
		}

		if (t[i] == t[j])
		{
			f[i] = ++j;
		}
	}

	for (i = 0; i < n; i++)
	{
		ptr1 = i%qn;

		while (j > 0 && s[ptr1] != t[j%m])
		{
			j = f[j%m - 1];
		}

		if (s[ptr1] == t[j%m])
		{
			j++;
		}

		if (j > lmax)
		{
			lmax = j;
		}
	}

	if (lmax >= n / 2)
	{
		printf("-1\n");
	}

	else
	{
		printf("%d\n", lmax / m);
	}

	return 0;
}

