void zalgo(string s, vector<int>& z){
	int c = 0, n = s.size();
	z.resize(m, 0);
	for(int i=1; i<m; i++){
		if(i+z[i-c] < c+z[c]){
			z[i] = z[i-c];
		}else{
			int j = max(0, c+z[c]-i);
			while(i+j < n && s[j] == s[i+j]) j++;
			z[i] = j;
			c = i;
		}
	}
	z[0] = n;
}

int dfs(int v, int c=0){
