    string s, t;
    cin >> s >> t;
    unsigned long loop = 1;
    {
        auto p = knuth_morris_pratt<decltype(t.begin())>(t.begin(), t.end());
        string tt{t + t};
        auto it = p(tt.begin() + 1, tt.end() - 1);
        if(it != tt.end() - 1){
            loop = t.size() / (it - tt.begin());
            t = string(tt.begin(), it);
        }
    }
    {
        auto p = knuth_morris_pratt<decltype(s.begin())>(s.begin(), s.end());
        string ss{s + s};
        auto it = p(ss.begin() + 1, ss.end() - 1);
        if(it != ss.end() - 1)s = string(ss.begin(), it);
    }
    auto p = knuth_morris_pratt<decltype(t.begin())>(t.begin(), t.end());
    while(s.size() < t.size())s += s;
    unsigned long N = s.size(), M = t.size();
    s += s;

    vector<unsigned long> idx(N);
    {
        string Q = t + s;
        vector<long> KMP(Q.size() + 1);
        KMP[0] = -1;
        long j = -1;
        for(unsigned long i = 0; i <= Q.size(); ++i){
            while(j >= 0 && Q[i] != Q[j])j = KMP[j];
            ++j;
            KMP[i + 1] = j;
            if(KMP[i + 1] >= M && i >= KMP[i + 1] && i < KMP[i + 1] + N)idx[i - KMP[i + 1]] = ~0UL;
        }
    }

    auto f = [rec = [&idx, &M, &N](auto f, unsigned long i, unsigned long t, unsigned long k) -> unsigned long{
        if(!idx[i])return 0;
        if(i == t && k)idx[i] = 2 * N;
        else if(!~idx[i])idx[i] = f(f, (i + M) % N, t, 1) + 1;
        return idx[i];
    }](unsigned long n){rec(rec, n, n, 0);};
    for(unsigned long i = 0; i < N; ++i)f(i);

    unsigned long ans = *max_element(idx.begin(), idx.end());
    if(ans > N)puts("-1");
    else cout << ans / loop << endl;
    return 0;
}

