    RH rhs(s), rht(t);

    int tlen = t.size();
    int ans = 0;
    for (int i = 0; i < s.size(); i++) {
        Long thash = rht.hash_substr(0, (long long)1e9 * tlen);
        if (rhs.hash_substr(i, i + (long long)1e9 * tlen) == thash) {
            cout << -1 << endl;
            return 0;
        }
        thash = rht.hash_substr(0, (long long)ans * tlen);
        if (rhs.hash_substr(i, i + (long long)ans * tlen) != thash) {
            continue;
        }
        int l = ans, r = 1e9;
        while (l < r - 1) {
            int m = (l + r) / 2;
            long long len = (long long)m * tlen;
            thash = rht.hash_substr(0, len);
            if (rhs.hash_substr(i, i + len) == thash) {
                l = m;
            } else {
                r = m;
            }
        }
        ans = max(ans, l);
    }
    cout << ans << endl;
}

