int prefix_function(const string &s,const string &t) {
    ///search t on s
    int m=(int)t.length();
    int n = t.length()+s.length()+1;
    auto ss=[&](int idx){
        if(idx==m)return '#';
        if(idx<m)return t[idx];
        return s[idx-m-1];
    };
    pi[0]=0;
    for (int i = 1; i < n; i++) {
        int j = pi[i-1];
        while (j > 0 && ss(i) != ss(j))
            j = pi[j-1];
        if (ss(i) == ss(j))
            j++;
        pi[i] = j;
    }
    int ma=-1;
    for(int i=n-1;i>m;i--){
        dp[i]=0;
        if(pi[i]==m){
            dp[i]=1;
        }
        if(i+m<n&&dp[i]==1){
            dp[i]+=dp[i+m];
        }
        ma=max(ma,dp[i]);
    }
    return ma;
}
