class UnionFind {
public:
  vector<int> parent;

  UnionFind(int n) : parent(n) {
    //all are root at initial state
    for (int i = 0; i < n; i++) {
      parent[i] = i;
    }
  }

  int root(int x) {//return the tree to which tree x belongs
    if (parent[x] == x){
      return x;
    }
    return parent[x] = root(parent[x]);
  }

  void unite(int x, int y) {//unite two trees, x and y
    int rx = root(x);
    int ry = root(y);
    if (rx == ry) {
      return;//x and y share same root
    }
    //if they are in independent trees
    parent[rx] = ry;//connect root of x to root of y
    return;
  }

  bool same(int x, int y){
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};

