struct rollingHash {
  vector<ll> ah;
  vector<vector<ll> > bh;
  int n, m, M = 2;

  rollingHash(string a, string b) {
    n = sz(a), m = sz(b);

    int B[] = { 1007, 2009 };
    int mod[] = { 1000000007, 1000000009 };
    ah.resize(M);
    bh.resize(M);

    auto calc = [&](int B, int mod, int k) {
      ll _bh = 0, t = 1;
      // 最初のハッシュ値を生成
      rep(i, n) {
        (ah[k] = ah[k] * B + a[i]) %= mod;
        (_bh = _bh * B + b[i]) %= mod;
        (t *= B) %= mod;
      }
      rep(i, m) {
        bh[k].eb(_bh);
        (_bh = _bh * B - b[i] * t + b[i + n]) %= mod;
      }
      // cout << ah[k] << endl << bh[k] << endl;
    };
    rep(i, M) calc(B[i], mod[i], i);
  }

  vector<int> get() {
    vector<int> table(m);
    rep(i, M) rep(j, m) if (ah[i] == bh[i][j]) table[j]++;
    return table;
  }
};

const int N = 200005;
vector<vector<int> > G(N);
vector<int> seen(N);
int pos = -1; // cycle 中に含まれる頂点 pos
stack<int> hist; // 訪問履歴

void dfs(int v, int p) {
  seen[v] = 1;
  hist.push(v);
  for (auto nv : G[v]) {
    if (seen[nv] == 2) continue;

    if (seen[nv] == 1) { // cycle を検出
      pos = nv;
      return;
    }
    dfs(nv, v);
    if (pos != -1) return;
  }
  hist.pop();
  seen[v] = 2;
}

int dfs2(int v, int p) {
  if (sz(G[v]) == 1 && p != -1) {
    return 0;
  }
  int ret;
  for (int nv : G[v]) {
    if (nv == p) continue;
    ret = dfs2(nv, v) + 1;
  }
  return ret;
}

