    int nv = (i + sz(t)) % n;
    // cout << i << " " << nv << endl;
    G[i].eb(nv);
  }

  // cycle 検出
  rep(i, n) {
    dfs(i, -1);
    if (sz(hist)) {
      cout << -1 << endl;
      return;
    }
  }

  rep(i, n) {
