struct UnionFind {
    std::vector<int> par;
    std::vector<int> sizes;

    UnionFind(int n) : par(n), sizes(n, 1) {
        for (int i = 0; i < n; i++)
            par[i] = i;
    }

    int find(int x) {
        return x == par[x] ? x : par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if (x == y)
            return;

        if (sizes[x] > sizes[y])
            std::swap(x, y);

        par[x] = y;
        sizes[y] += sizes[x];
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return sizes[find(x)];
    }
};

