vector<int> kmp(string T, string S){
    vector<int> ans;
    int k = 0;
    init(S);
    int i = 0;
    while(i < T.size()){
        if(S[k] == T[i]){
            k++;
            i++;
        }else{
            if(h[k] == 0){
                k = 0;
                i++;
            }else{
                k = h[k];
            }
        }
        if(k == S.size()){
            ans.push_back(i-S.size());
            k = h[k];
        }
    }
    return ans;
}

