class UnionFind
{
  vector<long long> par;

public:
  UnionFind() {}
  UnionFind(int n) : par(n, -1) {}

  bool is_same(int x, int y)
  {
    return root(x) == root(y);
  }

  bool merge(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y)
    {
      return false;
    }
    if (par[x] > par[y])
    {
      swap(x, y);
    }
    par[x] += par[y];
    par[y] = x;
    return true;
  }

  long long size(int x)
  {
    return -par[root(x)];
  }

private:
  int root(int x)
  {
    if (par[x] < 0)
    {
      return x;
    }
    return par[x] = root(par[x]);
  }
};

class RollingHash
{
  string S;
  static mint B;
  vector<mint> H;

public:
  RollingHash(string s, int t = -1) : S{s}
  {
    if (t == -1)
    {
      t = s.size();
    }
    assert(1 <= t && t <= static_cast<int>(s.size()));
    H = make_init_hash(t);
  }

  RollingHash(string s, size_t t) : RollingHash{s, static_cast<int>(t)} {}

  size_t size()
  {
    return S.size() + 1u - H.size();
  }

  const mint operator[](size_t t) const { return H[t]; }

private:
  mint Sm(size_t k) { return static_cast<mint>(S[k]); }
  vector<mint> make_init_hash(int);
};

mint RollingHash::B = 1234567;

vector<mint> RollingHash::make_init_hash(int t)
{
  vector<mint> res(S.size() + 1 - t);
  mint now = 0;
  const mint pb = B.power(t);
  for (auto i = 0; i < t; i++)
  {
    now = now * B + Sm(i);
  }
  res[0] = now;
  for (auto i = 0u; i < res.size() - 1; i++)
  {
    res[i + 1] = res[i] * B - Sm(i) * pb + Sm(i + t);
  }
  return res;
}

