//size of longest common prefix between s and s[i,n-1]
vector<int> Zalgorithm(const string &s){
    int n=s.size();
    vector<int> z(n,0);
    int L=0,R=0;
    for(int i=1;i<n;i++){
        if(R<i){
            L=i;R=i;
            while(R<n&&s[R-L]==s[R]) R++;
            R--;
            z[i]=R-L+1;
        }else{
            int k=i-L;
            if(z[k]<R-i+1) z[i]=z[k];
            else{
                L=i;
                while(R<n&&s[R-L]==s[R]) R++;
                R--;
                z[i]=R-L+1;
            }
        }
    }

    z[0]=0;
    return z;
}

