  SuffixArray sa(S);
  LCPArray lcp(sa);
  StringSearch search(lcp);
*/

void solve(){
  ins(SS , T);
  int N = SS.size();
  string S = SS;
  S += SS;
  while(sz(S) < sz(T) * 2) S += SS;
  SuffixArray sa(S);
  LCPArray lcp(sa);
  StringSearch search(lcp);
  auto nya = search.find(T);
  trc(nya);
  if(nya == P(-1 , -1)) die(0);
  vi v;
  for(int i = nya.fi ; i <= nya.se ; i++) v.pb(sa[i]);
  vi ok(N , 0) , used(N , 0);
  int ans = 0;
  each(x , v) ok[x % N] = 1;
  rep(i , N){
    if(used[i]) continue;
    int cur = 0 , idx = i;
    do{
      used[idx] = 1;
      idx = (idx + T.size()) % N;
      if(ok[idx] == 0) break;
      if(idx == i) die(-1);
      cur++;

    }while(1);
    amax(ans , cur);
  }
  out(ans);
}

