using namespace std;
typedef long long ll;
const ll MAXN=2e6+5;
const ll MOD=1e9+7;
const ll MOD1=13;
ll n,m,nex[MAXN],len[2],vavid[MAXN],dist[MAXN],du[MAXN];
char str[2][MAXN];
vector<ll>G[MAXN];
ll myceil(ll x,ll y)
{
    if(x%y)
    {
        return x/y+1;
    }
    return x/y;
}
void ext()
{
    if(m>n)
    {
        ll mul=myceil(m,n);
        for(ll i=2;i<=mul;i++)
        {
            for(ll j=0;j<n;j++)
            {
                str[0][j+(i-1)*n]=str[0][j];
            }
        }
        n*=mul;
    }
    for(ll i=0;i<n;i++)
    {
        str[0][i+n]=str[0][i];
    }
    n*=2;
}
void get_nex()

{

    int i,j;

    i = 0;

    nex[0]=j = -1;

    while(i < m)

    {

        while(j!=-1&&str[1][i] != str[1][j])

        {

            j = nex[j];

        }

        nex[++i] = ++j;

    }

    return;

}

int kmp()

{

    int i,j;

    i = j = 0;

    while(i < n)

    {

        while(j!=-1&&str[0][i]!=str[1][j])

            j = nex[j];

        if(j == m-1)

        {

            vavid[i-m+1]=1;

            j = nex[j];

        }

        i ++;

        j ++;

    }


}
void solve()
{
    n=strlen(str[0]);
    m=strlen(str[1]);
    ll nn=n;
    ext();
    get_nex();
    kmp();

    for(ll i=0;i<n;i++)
    {
        if(vavid[i%nn])
        {
            ll nexv=(i+m)%n;
            G[i].push_back(nexv);
            du[nexv]++;
        }
    }
    for(ll i=0;i<n;i++)dist[i]=-1;
    queue<ll>q;
    for(ll i=0;i<n;i++)
    {
        if(!du[i])
        {
            q.push(i);
            dist[i]=0;
        }
    }
    while(!q.empty())
    {
        ll u=q.front();
        q.pop();

        for(ll i=0;i<G[u].size();i++)
        {
            ll v=G[u][i];
            dist[v]=max(dist[v],dist[u]+1);
            du[v]--;
            if(!du[v])
            {
                q.push(v);
            }
        }
    }

    ll maxdist=0;
    for(ll i=0;i<n;i++)
    {
        if(dist[i]==-1)
        {
            printf("-1\n");
            return;
        }
        maxdist=max(maxdist,dist[i]);
    }
    printf("%lld\n",maxdist);
}
