    int ans = 0;
    string TS = T + S;
    auto Z = zAlgorithm(TS);
    rep(i, N) {
        int j = (i + M) % N;
        if (Z[i + M] >= M && Z[j + M] >= M) {
            uf.unite(i, j);
        }
    }

    vector<bool> vis(N);
    rep(i, N) {
        if (Z[i + M] >= M) {
            smax(ans, uf.getSize(i));
        }
