using namespace std;

vector<int> Z(string s) {
    vector<int> z(s.size() , 0);
    int l = 0 , r = 0;
    for (int i = 1 ;i < s.size() ;i++) {
        if (i <= r)
            z[i] = min(z[i - l] , r - i + 1);

        while (i + z[i] < s.size() && s[i + z[i]] == s[z[i]])
            z[i]++;

        if (i + z[i] - 1 > r)
            l = i , r = i + z[i] - 1;
    }

    return z;
}

const int N = 1e6 + 5;
vector<int> adj[N];
int vis[N];

bool cycle(int node) {
    if (vis[node])
        return vis[node] == 1;

    vis[node] = 1;
    for (int c : adj[node])
        if (cycle(c))
            return 1;
    vis[node] = 2;

    return 0;
}

int memo[N];
int solve (int node) {
    int &ret = memo[node];
    if (~ret)
        return ret;

    ret = 0;
    for (int c : adj[node])
        ret = max(ret , solve(c) + 1);

    return ret;
}

