  int *R = new int[sub_str.length()];

	int c = Zsearch(sub_str, t, R);

	vector<edge> G[ls];
	for (size_t i = 0; i < c; ++i) {
		G[R[i]].emplace_back((edge){(R[i] + lt) % ls});
	}

	// グラフの最長パス求める
	// 各ノードから出るedgeは 1本/0本 なので開始点が分かれば経路は1通り
	vector<int> path_len(ls);
	for (size_t i = 0; i < ls; ++i) {
		vector<bool> vis(ls);
		int length = 0;

		int pos = i;
		vis[pos] = true;

		while(!G[pos].empty()) {
			++length;

			pos = G[pos].at(0).to;
			if (vis[pos] == true) {
				// 無限ループの場合
				cout << -1 << endl;
				delete[] R;
				return 0;
			}
			vis[pos] = true;
		}

		path_len[i] = length;
	}

	int ret = *max_element(begin(path_len), end(path_len));
	cout << ret << endl;

	delete[] R;
	return 0;
}

