const int base = 29 ;
int mod[4] = {(int)1e9+9 ,(int)1e9+7 ,(int)1e9-63 ,(int)1e9-71};
int p[N][4] = {{1, 1, 1 ,1}} ;
int inv[N][4] = {{1, 1, 1 ,1}} ;
int pwr(int b,int md){
    int p = md - 2 ;
    int res = 1 ;
    while(p){
        if(p&1) res = (1ll * res * b) %md;
        b = (1ll * b * b) %md;
        p >>= 1;
    }
    return res ;
}
void init(){
    for(int i=1;i<N;++i)
        for(int j=0;j<4;++j){
            p[i][j] = (1ll * p[i-1][j] * base) %mod[j] ;
            inv[i][j] = pwr(p[i][j], mod[j]) ;
        }
}
struct rabinKarp{
    int val[4] ,len ;
    deque<int> cur ;
    rabinKarp(){
        memset(val,0,sizeof val);
        cur.clear();
        len = 0 ;
    }
    void push_back(int x){
        for(int i=0;i<4;++i){
            val[i] = (1ll * val[i] * base) %mod[i];
            val[i] = (val[i] + x) %mod[i];
        }
        cur.push_back(x);
        ++len ;
    }
    void push_front(int x){
        for(int i=0;i<4;++i){
            int v = (1ll * x * p[len][i]) %mod[i];
            val[i] = (val[i] + v) %mod[i];
        }
        cur.push_front(x);
        ++len ;
    }
    void pop_back(){
        for(int i=0;i<4;++i){
            int v = val[i] %base ;
            val[i] = ((val[i] - v) %mod[i] + mod[i]) %mod[i] ;
            val[i] = (1ll * val[i] * inv[1][i]) %mod[i];
        }
        cur.pop_back();
        --len ;
    }
    void pop_front(){
        --len ;
        for(int i=0;i<4;++i){
            int v = (1ll * cur.front() * p[len][i]) %mod[i] ;
            val[i] = ((val[i] - v) %mod[i] + mod[i]) %mod[i] ;
        }
        cur.pop_front();
    }
    int size(){
        return len ;
    }
    bool operator ==(const rabinKarp &rhs){
        if(rhs.len != len) return 0 ;
        for(int i=0;i<4;++i)
            if(val[i] != rhs.val[i]) return 0 ;
        return 1 ;
    }
    pair<ull ,ull> hashVal(){
        ull a = val[0] ,b = val[2] ;
        a *= 1e10 ,b *= 1e10 ;
        a += val[1] ,b += val[3] ;
        return {a ,b} ;
    }
};



