vl z_algorithm(const string& s) {
  vl z(s.size(), 0);
  z[0] = s.size();
  ll lt = 0, rt = 0;
  for (ll k = 1; k < s.size(); k++) {
    if (k > rt) {
      ll n = 0;
      while (k + n < s.size() && s[n] == s[k + n]) {
        n++;
      }
      z[k] = n;
      if (n > 0) {
        lt = k;
        rt = k + n - 1;
      }
    } else {
      ll p = k - lt;
      ll right_len = rt - k + 1;
      if (z[p] < right_len) {
        z[k] = z[p];
      } else {
        ll i = rt + 1;
        while (i < s.size() && s[i] == s[i - k]) {
          i++;
        }
        z[k] = i - k;
        lt = k;
        rt = i - 1;
      }
    }
  }
  return z;
}

ll longest(vl& z, ll tsize, ll start, ll i, vl& data) {
  if (start == i) {
    data[i] = -1;
    return -1;
  }
  if (data[i] >= -1) {
    return data[i];
  }

  if (z[tsize + 1 + i] == tsize) {
    ll next = (i + tsize) % data.size();
    ll tmp = longest(z, tsize, start, next, data);
    if (tmp == -1) {
      data[i] = -1;
      return -1;
    } else {
      data[i] = 1 + tmp;
      return 1 + tmp;
    }
  } else {
    data[i] = 0;
    return 0;
  }
}

