  rep(i, T.size()){
    hashS = (hashS * a + S[i % S.size()]) % MOD;
  }
  rep(i, T.size()){
    hashT = (hashT * a + T[i]) % MOD;
  }
  ll po = pow_mod(a, T.size());
  rep(i, S.size()){
    if(hashS == hashT) canStart[i] = 1;
    hashS = ((hashS * a + S[(i + T.size()) % S.size()] - S[i] * po) % MOD + MOD) % MOD;
  }
  init_UF();
  bool inf = 0;
  rep(i, S.size()){
    ll to = (i + T.size()) % S.size();
    if(canStart[i] == 0 || canStart[to] == 0) continue;
    if(same(i, to)) inf = 1;
    unite(i, to);
  }
  ll ans = 0;
  if(inf) cout << -1 << endl;
  else{
    rep(i, S.size()){
      ans = max(ans, child[i]);
    }
    cout << ans << endl;
  }
}

