using namespace std;

vector<bool> check_eq(string s, string t) {
  int s_size = s.size();
  int t_size = t.size();
  vector<bool> result(s_size - t_size + 1);

  // まず部分マッチテーブル作成
  int a[s_size+1];
  a[0] = -1;
  a[1] = 0;
  for (int i = 1, j = 0; i < s_size; i++) {
    while (j >= 0 && s[i] != s[j]) {
      j = a[j];
    }

    j++;
    if (s[i+1] == s[j]) {
      a[i+1] = a[j]; // 同じ文字ならさらに前に。これがKMPのKとのこと。http://potetisensei.hatenablog.com/entry/2017/07/10/174908
    } else {
      a[i+1] = j;
    }
  }

  // 照合
  int m = 0, i = 0;
  while (m + i < s_size) {
    bool need_to_move_m = false;

    if (t[i] == s[m + i]) {
      i++;
      if (i == t_size) {
        result[m] = true;
        //全部見つけるので、一致した場合もmを進める
        i--;
        need_to_move_m = true;
      }
    } else {
      need_to_move_m = true;
    }

    if (need_to_move_m) {
      m = m + i - a[i];
      if (i > 0) {
        i = a[i];
      }
    }
  }

  return result;
}

int main() {
  string s,t,s_origin;
  cin >> s >> t;
  s_origin = s;
  int s_origin_size = s_origin.size();
  int t_size = t.size();

  while(s.size() < t_size + s_origin_size) {
    s += s_origin;
  }

  vector<bool> eqs = check_eq(s,t);

  int max_length = 0;
  vector<int> length(s_origin_size, -1);

  for (int i = 0; i < s_origin_size; i++) {
    if (length[i] != -1) {
      continue;
    }

    if (!eqs[i]) {
      length[i] = 0;
      continue;
    }

    int current = i;
    int diff = 0;
    queue<int> q;
    while(eqs[current]) {
      if (!q.empty() && i == current) {
        // 無限に一致する
        max_length = -1;
        goto finish;
      }

      if (length[current] != -1) {
        diff = length[current]; // すでに到達済みの場合、計算済みの長さを加えて終了する
        break;
      }
      length[current] = 0; // 一旦到達マーク設定
      q.push(current);
      current = (current + t_size) % s_origin_size;
    }

    max_length = max(max_length, diff + (int)q.size());

    while(!q.empty()) {
      int len = q.size();
      int current = q.front();
      q.pop();
      length[current] = len + diff; // 正確な長さで上書き
    }
  }

finish:
  cout << max_length << endl;

  return 0;
}

