int main(){
    string S,T;
    cin >> S >> T;
    int M = T.size();
    string SS;
    while(SS.size()<2*M) SS += S;
    int N = SS.size();
    vector<int> kmpnext(M+1,0);
    vector<vector<int>> v(N+1);
    auto prekmp = [&](string x,int m){
        int i = 0,j = kmpnext[0] = -1;
        while(i<m){
            while(j>-1 && x[i]!=x[j]) j = kmpnext[j];
            i++; j++;
            if(x[i]==x[j]) kmpnext[i] = kmpnext[j];
            else kmpnext[i] = j;
        }
    };
    auto KMP = [&](string x,int m,string y,int n){
        int i = 0,j = 0;
        prekmp(x,m);
        while(j<n){
            while(i>-1 && x[i]!=y[j]) i = kmpnext[i];
            i++; j++;
            if(i>=m){
//                cerr << j-i << " " << (j-i+x.size())%n << endl;
                v[j-i].push_back((j-i+x.size())%n);
                i = kmpnext[i];
            }
        }
    };
    KMP(T,M,SS,N);
    vector<int> vis(N+1,0);
    int ans = -1;
    function<bool(int,int)> dfs = [&](int n,int len){
        vis[n] = -1;
        ans = max(ans,len);
        bool ok = true;
        for(auto x:v[n]){
            if(vis[x]==0) ok &= dfs(x,len+1);
            else if(vis[x]==-1) return false;
        }
        vis[n] = 1;
        return ok;
    };
    for(int i=1;i<=N;i++){
        if(vis[i]==0 && !v[i].empty()){
            if(!dfs(i,0)){
                cout << -1 << endl;
                return 0;
            }
        }
    }
    cout << ans << endl;
}

