string S, T;
vector<bool> canStart;
const ll MAX_V = 200010;

ll par[MAX_V];//
ll Rank[MAX_V];
ll child[MAX_V];

void init_UF(){
  for(ll i = 0; i < MAX_V; i++){
    par[i] = i;
    Rank[i] = 1;
    if(canStart[i]) child[i] = 1;
  }
}

ll find(ll x){
  if(par[x] == x) return x;
  else{
    return par[x] = find(par[x]);
  }
}

bool same(ll x, ll y){
  return find(x) == find(y);
}

void unite(ll x, ll y){
  ll rx = find(x), ry = find(y);
  if(rx != ry){
    if(Rank[rx] >= Rank[ry]){
      par[ry] = rx;
      if(Rank[rx] == Rank[ry]) Rank[rx]++;
      child[rx] += child[ry];
    }else{
      par[rx] = ry;
      child[ry] += child[rx];
    }
  }
}

int main(){
  cin >> S >> T;
  canStart.resize(S.size(), 0);
  ll a = 998244353;
  ll hashS = 0, hashT = 0;
  rep(i, T.size()){
    hashS = (hashS * a + S[i % S.size()]) % MOD;
  }
  rep(i, T.size()){
    hashT = (hashT * a + T[i]) % MOD;
  }
  ll po = pow_mod(a, T.size());
  rep(i, S.size()){
    if(hashS == hashT) canStart[i] = 1;
    hashS = ((hashS * a + S[(i + T.size()) % S.size()] - S[i] * po) % MOD + MOD) % MOD;
  }
  init_UF();
  bool inf = 0;
  rep(i, S.size()){
    ll to = (i + T.size()) % S.size();
    if(canStart[i] == 0 || canStart[to] == 0) continue;
    if(same(i, to)) inf = 1;
    unite(i, to);
  }
  ll ans = 0;
  if(inf) cout << -1 << endl;
  else{
    rep(i, S.size()){
      ans = max(ans, child[i]);
    }
    cout << ans << endl;
  }
}

