using namespace std;

void z_func(const string &p, vector<int> &z)
{
	z.assign(p.size(), 0);
	for (int l = 0, r = 0, i = 1; i < p.size(); i++)
		if (r >= i && z[i - l] < r - i + 1) {
			z[i] = z[i - l];
		} else {
			if (i > r) r = i;
			for (l = i; r < p.size() && p[r - l] == p[r]; ) r++;
			z[i] = r - l;
			r--;
		}
}

int find(const string &s, const string &t)
{
	int n = s.size(), m = t.size();
	string r = t + "|" + s;
	vector<int> z;
	z_func(r, z);
	vector<int> dp(z.size() + 1);
	for (int i = 0; i < dp.size(); i++)
		if (z[i] == m) dp[i + m] = dp[i] + 1;
	return *max_element(dp.begin(), dp.end());
}

int main(int argc, char *argv[])
{
	ios::sync_with_stdio(false); cin.tie(0);
	string s, t;
	cin >> s >> t;
	string r = s;
	while (r.size() <= s.size() + t.size()) r += s;

	int ans = find(r, t);
	if (ans > 0 && find(r + r, t) != ans)
		ans = -1;

	cout << ans << endl;

	return 0;
}

