/**
 * https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
 * 文字列検索
 */
class KMP {
 private:
  string needle;
  vector<ll> kmp;

 public:
  explicit KMP(const string &needle) : needle(needle), kmp(needle.size() + 2, 0) {
    // 部分マッチテーブルを構築
    kmp[0] = -1;
    kmp[1] = 0;
    {
      ll i = 2;
      ll j = 0;
      while (i < needle.size()) {
        if (needle[i - 1] == needle[j]) {
          kmp.at(i++) = ++j;
        } else if (j > 0) {
          j = kmp.at(j);
        } else {
          kmp.at(i++) = 0;
        }
      }
    }
  }

  /**
   * @param haystack
   * @param m The position of the current character in haystack
   * @param i The position of the current character in needle
   */
  ll index_of(const string &haystack, ll m = 0, ll i = 0) {
    while (m + i < haystack.size()) {
      if (needle.at(i) == haystack.at(m + i)) {
        if (++i == needle.size()) {
          return m;
        }
      } else {
        m += i - kmp.at(i);
        if (i > 0) {
          i = kmp.at(i);
        }
      }
    }
    return -1;
  }

  /**
   * ret[i]: haystack[i] 以降の文字列の最初が needle と同じなら true
   * @param haystack
   */
  vector<ll> search(const string &haystack) {
    vector<ll> ret(haystack.size(), false);

    ll m = 0;
    ll i = 0;
    while (m + i < haystack.size()) {
      m = index_of(haystack, m, i);
      if (m < 0) break;
      ret.at(m) = true;
      m += needle.size() - kmp.at(needle.size() - 1) - 1;
      i = max(0ll, kmp.at(needle.size() - 1));
    }
    return ret;
  }
};

ll dfs(ll i, const vector<ll> &matches, vector<ll> &memo, ll size) {
  if (memo[i]) {
    return memo[i];
  }
  memo[i] = -1;
  if (!matches[i]) {
    return memo[i] = 0;
  }
  ll r = dfs((i + size) % memo.size(), matches, memo, size);
  return memo[i] = r >= 0 ? r + 1 : -1;
}

ll solve() {
  string s, t;
  cin >> s >> t;

  while (s.size() < t.size()) {
    s += s;
  }
  s += s;

  KMP kmp = KMP(t);
  vector<ll> matches = kmp.search(s);
  vector<ll> memo(s.size() / 2, 0);
  ll ans = 0;
  rep (i, memo.size()) {
    if (!memo[i]) {
      ll r = dfs(i, matches, memo, t.size());
      if (r < 0) {
        return -1;
      }
      ans = max(r, ans);
    }
  }
  return ans;
}

