	}
	RollingHash h1(s2), h2(t2);
	int u = 0;
	for (int i = 0; i < s2.size(); i++) {
		auto lcp = h1.LCP(h2, i, s2.size(), 0, t2.size());
		if (lcp % t.size() == 0) {
