  if(used[ni] && memo[ni]>0){  // found previous result
    memo[i] = memo[ni]+1;
    return memo[i];
  }
  else if (used[ni]){  // found loop
    memo[i] = INF;
    return memo[i];
  }
  else if (found.find(ni)!=found.end()){
    memo[i] = dfs(ni)+1;
    return memo[i];
  }
  else{
    memo[i] = 1;
    return memo[i];
  }
}
