    int hpow = 1;
    for (int i = 0; i < t.length(); i++) { hpow = hpow * hash % mod; }
    int th = 0, Sh = 0;
    for (int i = 0; i < t.length(); i++) {
        th = (th * hash + t[i]) % mod;
        Sh = (Sh * hash + S[i]) % mod;
    }
