constexpr int P = 1000000009;

ll inv(int n) {
    int m = P, y = 0, v = 1;
    while (1) {
        int q = m / n;
        int r = m % n;
        if (r == 0) return v < 0 ? v + P : v;
        y -= v * q;
        swap(y, v);
        m = n;
        n = r;
    }
}

int f(string &s) {
    int n = (int)s.size();
    for (int f = 1; f <= n; f++) {
        if (n % f != 0) continue;
        int b = 1;
        for (int i = 0; i < f; i++) {
            char c = s[i];
            for (int j = i + f; j < n; j += f) {
                if (s[j] != c) {
                    b = 0;
                    break;
                }
            }
            if (!b) break;
        }
        if (b) return f;
    }
    throw;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    string s, t;
    cin >> s >> t;

    int n = f(s);
    int m = f(t);

    if (n == m) {
        int b = 1;
        for (int i = 0; i < n; i++) {
            if (s[i] != t[i]) {
                b = 0;
                break;
            }
        }
        if (b) {
            cout << -1 << endl;
            exit(0);
        }
    }

    s += s;
    n = (int)s.size();

    constexpr int K = 11113;
    ll ht = 0;
    ll iv = 1;
    for (int i = 0; i < m; i++) {
        ht *= K;
        ht += t[i];
        ht %= P;
        iv = iv * K % P;
    }

    ll hs = 0;
    vector<int> hss(n + 1);
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        hs *= K;
        hs += s[i];
        hs %= P;
        hss[i + 1] = (int)hs;
        if (i + 1 >= m) {
            ll h = hss[i + 1] - hss[i + 1 - m] * iv % P;
            if (h < 0) h += P;
            if (h == ht) {
                a[i + 1 - m] = 1;
            }
        }
    }

    int f = m;
    int r = 0;
    for (int i = 0; i < f; i++) {
        int b = 0;
        for (int j = i; j < n; j += f) {
            if (a[j]) {
                b++;
                r = max(r, b);
            } else {
                b = 0;
            }
        }
    }

    cout << r / ((int)t.size() / m) << endl;

    return 0;
}

