ll base = 10007;
ll bf = 1;
ll mod = 1000000009;

ll get_memo(ll st, ll cnt){
	if(hs[st] != ht){
		return 0;
	}
	if(cnt == n){
		return n;
	}
	if(memo[st] == 0){
		return memo[st] = get_memo((st+m)%n, cnt+1)+1;
	}
	return memo[st];
}

