template<int MAXV>
struct scc {
  std::vector<int> G[MAXV], rG[MAXV], vs;
  bool used[MAXV];
  //int cmp[MAXV];
  scc() {}
  void dfs(int v) {
    used[v] = true;
    for(auto c: G[v]) if(!used[c]) dfs(c);
    vs.push_back(v);
  }
  void rdfs(int v, int k) {
    used[v] = true;
    //cmp[v] = k;
    for(auto c: rG[v]) if(!used[c]) rdfs(c, k);
  }
  int build(int V) {
    std::fill_n(used, V, false);
    vs.clear();
    for(int v = 0; v < V; ++v) if(!used[v]) dfs(v);
    std::fill_n(used, V, false);
    int k = 0;
    for(int i = vs.size()-1; i >= 0; --i) {
      if(!used[vs[i]]) rdfs(vs[i], k++);
    }
    return k;
  }
  void add_edge(int fr, int to) {
    G[fr].push_back(to); rG[to].push_back(fr);
  }
};

int const MAXN = 5e5;

scc<MAXN> sc;
int depth[MAXN];
int calc_depth(int v) {
  if(depth[v] >= 0) return depth[v];
  int res = -1;
  for(auto c: sc.G[v]) res = std::max(res, calc_depth(c));
  ++res;
  return depth[v] = res;
}

int64_t const B1 = 1e8+7;
int64_t const B2 = 1e9+7;

int main() {
  std::string S, T; std::cin >> S >> T;
  int N = S.size(), M = T.size(), K = N+M-1;
  std::string U = S;
  for(int i = 0; i < (M-1)/N; ++i) U += S;
  U += S.substr(0, K - U.size());
  int64_t t1 = 0, t2 = 0, u1 = 0, u2 = 0;
  int64_t B1M = 1, B2M = 1;
  for(int i = 0; i < M; ++i) { B1M *= B1; B2M *= B2; }
  // initial
  for(int i = 0; i < M; ++i) {
    t1 = t1*B1 + T[i];
    u1 = u1*B1 + U[i];
    t2 = t2*B2 + T[i];
    u2 = u2*B2 + U[i];
  }
  std::vector<int> v;
  for(int i = 0; i < N; ++i) {
    if(t1 == u1 && t2 == u2) v.push_back(i);
    if(M+i >= K) break;
    u1 = u1*B1 + U[M+i] - U[i]*B1M;
    u2 = u2*B2 + U[M+i] - U[i]*B2M;
  }

  if(v.size() < 1) fin(0);
  for(int fr: v) {
    int to = (fr+M)%N;
    if(fr == to) fin(-1);
    sc.add_edge(fr, to);
  }
  if(sc.build(N) < N) fin(-1);
  std::fill_n(depth, N, -1);
  int ans = 0;
  for(int i = 0; i < N; ++i) {
    ans = std::max(ans, calc_depth(i));
  }
  fin(ans);

  return 0;
}

