struct rolling_hash{
    using u64 = std::uint_fast64_t;
    class hash_string{
        public:
        u64 digit;
        vector<u64> hash;
        rolling_hash* par;
        u64 base,mod_num;
        vector<u64> mod;
        hash_string(){cerr<<"err"<<endl;}
        hash_string(rolling_hash* par):digit(0),par(par),base(par->base),mod_num(par->mod_num),mod(par->mod){hash.resize(mod_num,0);}
        hash_string(rolling_hash* par,u64 digit,vector<u64> hash):digit(digit),hash(hash),par(par),base(par->base),mod_num(par->mod_num),mod(par->mod){}
        hash_string operator +(char c){
            vector<u64>hashTable(mod_num);
            rep(i,mod_num)hashTable[i]=(hash[i]*base+c)%mod[i];
            return hash_string(par,digit+1,hashTable);
        }
        hash_string operator +(hash_string s){
            vector<u64>hashTable(mod_num);
            rep(i,mod_num)hashTable[i]=(hash[i]*mod_pow(base,s.digit,mod[i])+s.hash[i])%mod[i];
            return hash_string(par,digit+s.digit,hashTable);
        }
        hash_string operator -(hash_string s){
            vector<u64>hashTable(mod_num);
            rep(i,mod_num)hashTable[i]=(hash[i]+mod[i]-(s.hash[i]*mod_pow(base,digit-s.digit,mod[i]))%mod[i])%mod[i];
            return hash_string(par,digit-s.digit,hashTable);
        }
        hash_string operator -(char c){
            vector<u64>hashTable(mod_num);
            rep(i,mod_num)hashTable[i]=(hash[i]+mod[i]-(c*mod_pow(base,digit-1,mod[i]))%mod[i])%mod[i];
            return hash_string(par,digit-1,hashTable);
        }
        hash_string operator *(u64 num){
            u64 exp=num;
            auto res=hash_string(par);
            auto x=*this;
            while(exp){
                if(exp%2)res=res+x;
                x=x+x;
                exp/=2;
            }
            return res;
        }
        bool operator ==(hash_string s){
            return hash==s.hash;
        }
        private:
        inline u64 mod_pow(u64 x,u64 y,u64 _mod){
            if(par->cache[_mod].count(y)){return par->cache[_mod][y];}
            u64 exp=y;
            u64 res=1;
            while(exp){
                if(exp%2){
                    res*=x;
                    res%=_mod;
                }
                x*=x;
                x%=_mod;
                exp/=2;
            }
            return par->cache[_mod][y]=res;
        }
    };
    vector<hash_string>hash;
    u64 base=10007,mod_num=3;
    vector<u64> mod={1000000007,999999937,998244353};
    unordered_map<u64,unordered_map<u64,u64>>cache;
    rolling_hash(){
        hash.resize(1,hash_string(this));
    }
    rolling_hash(string s){
        hash.resize(s.size()+1,hash_string(this));
        repi(i,1,s.size()+1)hash[i]=hash[i-1]+s[i-1];
    }
    hash_string operator()(int l,int len=-1){
        if(len==-1)return hash[hash.size()-1]-hash[l];
        else return hash[l+len]-hash[l];
    }
    hash_string operator()(){
        return hash[hash.size()-1];
    }
};

lint bs(lint mn=0,lint mx=INF,function<bool(lint)> func=[](lint x){return true;}) {
    lint left = mn-1;
    lint right =mx;
    while (right - left > 1) {
        lint mid =(right+left)/2;
        if (!func(mid)) right = mid;
        else left = mid;
    }
    return left;
}

struct UF{
    public:
    vector<lint> par;
    vector<lint> rank;
    lint _s;
    UF(lint size){
        _s=size;
        par.resize(size);
        rep(i,size)par[i]=i;
        rank.resize(size,0);
    }
    bool unite(lint x,lint y){
        x=root(x);y=root(y);
        if(x==y)return false;
        if(rank[x]<rank[y])swap(x,y);
        if(rank[x]==rank[y])rank[x]++;
        par[y]=x;
        _s--;
        return true;
    }
    lint root(lint x){
        while(x!=par[x]){
            x=par[x]=par[par[x]];
        }
        return x;
    }
    bool same(lint x, lint y) {
        return root(x) == root(y);
    }
    lint size(){
        return _s;
    }
};

