int nxt[N],num[N*8];char s[N*8],t[N];
void getnxt(char s[]){
    nxt[0]=nxt[1]=0;
    int l=strlen(s);
    for(int i=1;i<l;++i){
        int j=nxt[i];
        while(j && s[i]!=s[j]) j=nxt[j];
        nxt[i+1]= s[i]==s[j] ? j+1 : 0 ;
    }
}
int kmp(char s1[],char s2[]){
    getnxt(s1);
    int ans=0;
    int n=strlen(s1),m=strlen(s2);
    for(int i=0,j=0;i<m;++i){
    	num[i]=0;
        while(j && s1[j]!=s2[i]) j=nxt[j];
        if(s1[j]==s2[i]) ++j;
        if(j==n) num[i]=1+num[i-n],ans=max(ans,num[i]);
    }
    return ans;
}
