#define rep2(i, s, e) for (int i = (s); i < (int)(e); ++i)
using namespace std;
using ll = long long;

int kmp_search(const string &s, const string &t, const vector<int> &kmp, int offset) {
  int m = offset;
  int i = 0;
  while (m + i < s.size()) {
    if (t[i] == s[m + i]) {
      i++;
      if (i == t.size()) {
        return m;
      }
    } else {
      m += i - kmp[i];
      if (i > 0) {
        i = kmp[i];
      }
    }
  }
  return s.size();
}

int solve(const string &s, const string &t, int ls, int lt) {
  // https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
  vector<int> kmp(lt + 2, 0);
  kmp[0] = -1;
  kmp[1] = 0;
  {
    int i = 2;
    int j = 0;
    while (i < lt) {
      if (t[i - 1] == t[j]) {
        kmp[i] = j + 1;
        i++;
        j++;
      } else if (j > 0) {
        j = kmp[j];
      } else {
        kmp[i] = 0;
        i++;
      }
    }
  }

  int ret = 0;
  vector<bool> seen(ls, false);

  int i = -1;
  while (++i < ls) {
    i = kmp_search(s, t, kmp, i);
    if (i > ls) break;
    if (seen[i]) continue;

    int j = 0;
    while (true) {
      int p = kmp_search(s, t, kmp, i + j * lt);
      if (p - (i + j * lt) != 0) {
        break;
      }
      if (p < ls) seen[p] = true;
      if (j * lt >= ls) return -1;

      j += 1;
    }
    ret = max(ret, j);
  }
  return ret;
}

int main() {
  string s, t;
  cin >> s >> t;

  int ls, lt;
  ls = s.size();
  lt = t.size();

  do {
    s += s;
  } while (s.size() < t.size() * 3);
  int ret = solve(s, t, ls, lt);
  cout << ret << endl;
}

