		if (!match[j]) { q.push(i); top[i] = 0; }
	}

	while (!q.empty()) {
		ll i = q.front();
		q.pop();

		if (!match[i]) { continue; }
		ll j = (i + M) % N;

		top[j] = top[i] + 1;
		q.push(j);
	}

	ll ans = 0;
	rep(i, N) {
		if (top[i] == -1) { ans = -1; break; }
		ans = max(ans, top[i]);
	}

	cout << ans << endl;

	system("PAUSE");

}

