            if(used_index.find(nxt) != used_index.end()){
                cout << -1 << endl;
                return 0;
            }

            while(sindex[nxt]){
                sindex[nxt] = false;
                used_index.emplace(nxt);
                sum++;
                nxt = (nxt + m) % n;

                if(used_index.find(nxt) != used_index.end()){
                    cout << -1 << endl;
                    return 0;
                }
            }

            int pre = (i - m + (int)S.size()) % n;

            if(used_index.find(pre) != used_index.end()){
                cout << -1 << endl;
                return 0;
            }

            while(sindex[pre]){
                sindex[pre] = false;
                used_index.emplace(pre);
                sum++;
                pre = (pre - m + (int)S.size()) % n;

                if(used_index.find(pre) != used_index.end()){
                    cout << -1 << endl;
                    return 0;
                }
            }

            chmax(ans, sum);
        }
    }

    cout << ans << endl;
}

