    vector<int> next(s.size(), -1);
    vector<int> d(s.size(), -1);
    for (int i = 0; i < s.size(); i++) {
        if (z[t.size()+i] >= t.size()) {
            next[i] = (i + t.size()) % s.size();
        }
    }
    int ans = 0;
    for (int st = 0; st < s.size(); st++) {
        if (d[st] != -1) continue;
        stack<int> s({st});
        int plus = 0;
        while (next[s.top()] != -1) {
            if (next[s.top()] == st) {
                cout << -1 << endl;
                return 0;
            }
            if (d[s.top()] != -1) {
                plus = d[s.top()];
                break;
            }
            s.push(next[s.top()]);
        }
        while (!s.empty()) {
            d[s.top()] = plus++; 
            s.pop();
        }
    }
    for (auto x: d) {
        ans = max(ans, x);
    }
    cout << ans << endl;
