template <u64 Mod, u64 Base> class rolling_hash {
  std::vector<u64> suf, pow;

public:
  explicit rolling_hash(std::string s)
      : suf(s.size() + 1_z), pow(s.size() + 1_z) {
    suf.back() = static_cast<u64>(0);
    for (usize i = s.size(); i;) {
      --i;
      suf[i] = (suf[i + 1_z] * Base + static_cast<u64>(s[i] - 'a')) % Mod;
    }
    pow[0_z] = static_cast<u64>(1);
    for (usize i = 0_z; i != s.size(); ++i) {
      pow[i + 1_z] = pow[i] * Base % Mod;
    }
  }

  u64 operator()(const usize l, const usize r) const {
    return (suf[l] + Mod - suf[r] * pow[r - l] % Mod) % Mod;
  }
};

void main_() {
  using hash = rolling_hash<1000000007, 62479294>;
  auto s = scan<std::string>();
  const auto t = scan<std::string>();
  const usize m = t.size();
  while (s.size() < m) {
    s = s + s;
  }
  const usize n = s.size();
  s = s + s;
  const hash sh(s);
  const u64 th = hash(t)(0_z, m);
  std::vector<usize> next(n, n);
  for (const auto i : rep(0_z, n)) {
    if (sh(i, i + m) == th) {
      next[i] = (i + m) % n;
    }
  }
  std::vector<usize> memo(n, n + 1_z);
  const auto dfs = [&](const auto &dfs, const usize v) -> usize {
    if (memo[v] > n) {
      if (next[v] == n) {
        memo[v] = 0_z;
      } else {
        memo[v] = n;
        memo[v] = dfs(dfs, next[v]) + 1_z;
      }
    }
    return memo[v];
  };
  usize ans = 0_z;
  for (const auto i : rep(0_z, n)) {
    ans = std::max(ans, dfs(dfs, i));
  }
  if (ans >= n) {
    std::cout << "-1" << std::endl;
  } else {
    std::cout << ans << std::endl;
  }
}

