  while (S.length() + 1 < s.length() + t_len) S += s;
  RollingHash<> rh_s(S), rh_t(t);
  bool ans = false;
  for (int i = 0; i + t_len - 1 < S.length(); ++i) {
    if (rh_s.get(i, i + t_len) == rh_t.get(0, t_len)) {
      ans = true;
      break;
    }
  }
  if (!ans) {
    cout << "0\n";
    return 0;
  }
  MP mp_s(S), mp_t(t);
  if (mp_s.period(S.length()) == mp_t.period(t_len)) {
    cout << "-1\n";
    return 0;
  }
  int lb = 1, ub = S.length() / t_len + 1;
  string T = "";
  REP(_, ub - 1) T += t;
  RollingHash<> rh_T(T);
  while (ub - lb > 1) {
    int mid = (lb + ub) >> 1;
    bool ok = false;
    for (int i = 0; i + t_len * mid - 1 < S.length(); ++i) {
      if (rh_s.get(i, i + t_len * mid) == rh_T.get(0, t_len * mid)) {
        ok = true;
        break;
      }
    }
    (ok ? lb : ub) = mid;
  }
  cout << lb << '\n';
  return 0;
}

