void solve() {
  string s, t;
  cin >> t >> s;
  hashPow[0] = 1;
  for(int i = 1; i <= s.size(); i++) {
    hashPow[i] = hashPow[i-1] * HASH;
    hashPow[i] %= MOD;
  }
  ll sHash = 0;
  for(int i = 0; i < s.size(); i++) {
    sHash *= HASH;
    sHash += s[i];
    sHash %= MOD;
  }
  int tSize = t.size();
  for(int i = 0; i <= 1000000; i++) {
    thash[i+1] = thash[i] * HASH + t[i%t.size()];
    thash[i+1] %= MOD;
  }
  for(int i = 0; i < t.size(); i++) {
    ll val = thash[i + s.size()] - thash[i] * hashPow[s.size()];
    val %= MOD;
    val += MOD;
    val %= MOD;
    if(val == sHash) {
      to[i].push_back((i+s.size())%t.size());
      indeg[(i+s.size())%t.size()]++;
    }
  }
  queue<int> q;
  for(int i = 0; i < t.size(); i++) {
    if(indeg[i] == 0) {
      q.push(i);
    }
  }
  while(!q.empty()) {
    int curr = q.front();
    visited[curr] = true;
    q.pop();
    for(int out: to[curr]) {
      if(--indeg[out] == 0) q.push(out);
      dp[out] = max(dp[out], dp[curr] + 1);
    }
  }
  int ret = 0;
  for(int i = 0; i < t.size(); i++) {
    ret = max(ret, dp[i]);
    if(!visited[i]) {
      cout << "-1\n";
      return;
    }
  }
  cout << ret << "\n";
}

