const int MAX = 543210;
bool match[MAX];
int kmpTable[MAX];
vector<vector<int>> graph(MAX);
int depth[MAX];

// KMPテーブルの作成を行う.
// https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
// @param W: 解析する単語.
// @return: 特に無し.
void createTableOfKMP(string W){

    // 1. 変数宣言.
    int c = 2; // KMPテーブル の中で, 現在計算している位置.
    int n = 0; // 現在見ているサブ文字列の次の文字のインデックス.

    // 2. 先頭ふたつの値を設定.
    kmpTable[0] = -1;
    kmpTable[1] =  0;

    // 3. KMPテーブルの更新.
    int l = W.size();
    while(c < l){
        // サブ文字列は, 継続中.
        if(W[c - 1] == W[n]) kmpTable[c] = n + 1, c++, n++;

        // サブ文字列は継続しないが, フォールバック可能.
        else if(n > 0) n = kmpTable[n];

        // 対象をはみ出した.
        else kmpTable[c] = 0, c++;
    }

    return;
}

// KMPアルゴリズムで文字列検索を行う.
// https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
// @param S: 検索対象のテキスト.
// @param W: 検索する単語.
// @param ver: 照合開始位置.
// @return ret: W が 見つかった際の S 内 の 位置, 0-indexとする.
int searchByKMP(string S, string W, int ver){

    // 1. 変数宣言.
    int cs = ver; // S内の現在照合中の開始位置.
    int cw = 0;   // W内の現在位置.

    // 2. KMPテーブルをもとに, S 内 で, W を 照合していく.
    int sLen = S.size(), wLen = W.size();
    while(cs + cw < sLen){
        if(W[cw] == S[cs + cw]){
            cw++;
            if(cw == wLen) return cs;
        }else{
            cs = cs + cw - kmpTable[cw];
            if(cw > 0) cw = kmpTable[cw];
        }
    }

    // 3. W が S 内 で見つからなかった場合.
    return sLen;
}

// グラフの経路を探索する.
// 深さ優先探索(depth-first search).
// https://ja.wikipedia.org/wiki/深さ優先探索
// @param c: 探索地点となる頂点.
// @param b: 探索地点から見て, 前回探索済の頂点.
// @param d: 探索開始地点からの距離.
// @return : 特に無し.
void dfs(int c, int b, int d) {
    depth[c] = d;
    for (auto &e : graph[c]) {
        if(e == b) continue;
        dfs(e, c, d + 1);
    }
}

