	cin >> s >> t;
	auto ss = get(s);
	auto tt = get(t);
	if (comp(ss, tt)) {
		cout << -1 << endl;
		return 0;
	}
	string x = s;
	while (x.size() < tt.size()) {
		x += s;
	}
	x += x;
	int c = t.size() / tt.size();
	cout << (calc(x, tt) / c) << endl;
	return 0;
}

