void z_algorithm(const string& s, const string& t, vector<ll>& A) {
    A.resize(s.size(), 0);
    A[0] = s.size();

    int i = 0, j = 0;
    while(i < s.size()) {
        while(j < t.size() && s[(i + j) % s.size()] == t[j]) ++j;
        A[i] = j;
        if (j == 0) {++i; continue;}
        int k = 1;
        while(i + k < s.size() && k + A[k - 1] < j) A[i+k] = A[k - 1], ++k;
        i += k; j -= k;
    }
}

vector<int> g;
vector<ll> dist;

ll dfs(int cur, vector<bool> &v) {
    v[cur] = true;

    ll ret = 0;
    int e = g[cur];
    if (e == -1) return dist[cur] = 0;

    if (v[e]) return dist[cur] = inf;

    if (dist[e] > 0) ret = max(dist[e] + 1, ret);
    else ret = max(dfs(e, v) + 1, ret);

    return dist[cur] = ret;
}

