const int MAXN=550000;
const int MAXM=MAXN*8;
const int MAXS=26;
struct SAM
{
	struct Node
	{
		int nxt[MAXS], par;
		int len;
	} st[MAXM];
	int n, m, root, lst;
	inline int newNode(int l)
	{
		m++;
		memset(st[m].nxt, 0, sizeof st[m].nxt);
		st[m].par=0; st[m].len=l;
		return m;
	}
	void extend(char c)
	{
		int x=c-'a', p=lst, np=newNode(st[p].len+1); lst=np;
		while (p&&!st[p].nxt[x]) st[p].nxt[x]=np, p=st[p].par;
		if (!p) { st[np].par=root; return; }
		int q=st[p].nxt[x]; if (st[q].len==st[p].len+1) { st[np].par=q; return; }
		int nq=newNode(st[p].len+1); memcpy(st[nq].nxt, st[q].nxt, sizeof st[q].nxt);
		st[nq].par=st[q].par; st[q].par=st[np].par=nq;
		while (p&&st[p].nxt[x]==q) st[p].nxt[x]=nq, p=st[p].par;
	}
	void build(char* s, int ls, int lt)
	{
		int c=2*((lt-1)/ls+1);
		n=c*ls; m=0; lst=root=newNode(0);
		for (int i=1; i<=c; i++)
			for (int j=0; j<ls; j++) extend(s[j]);
	}
	int query(char* s, int l)
	{
		int p=root, ans=0;
		bool flag=1;
		while (flag)
		{
			for (int i=0; i<l; i++)
			{
				p=st[p].nxt[s[i]-'a'];
				if (!p) { flag=0; break; }
			}
			if (flag) ans++;
		}
		return ans;
	}
} sam;
char s[MAXN], t[MAXN];
int nxt[MAXN];
int getnxt(char* s, int l)
{
	for (int i=1, j=nxt[0]=-1; i<l; i++)
	{
		while (~j&&s[i]!=s[j+1]) j=nxt[j];
		if (s[i]==s[j+1]) j++;
		nxt[i]=j;
	}
	int d=l-nxt[l-1]-1;
	return l%d==0?d:l;
}
bool cmp(char* s, char* t, int l)
{
	for (int i=0, j=-1; i<2*l; i++)
	{
		if (~j&&s[i%l]!=t[j+1]) j=nxt[j];
		if (s[i%l]==t[j+1]) j++;
		if (j==l) return 1;
    }
    return 0;
}
