void kmp_search_f(const string &text, ll slen, const string &pattern,
                  const ll kmp_next[], ll start_to_next[])
{
    ll text_size = text.size();
    ll pattern_size = pattern.size();
    ll text_idx = 0LL;
    ll pattern_idx = 0LL;

    assert(pattern_size <= text_size);

    for ( ; text_idx - pattern_idx <= text_size - pattern_size; ) {
        if (text_idx - pattern_idx >= slen) break;
        for ( ; pattern_idx < pattern_size; ) {
            if (text[text_idx] != pattern[pattern_idx]) break;
            ++pattern_idx;
            ++text_idx;
        }
        if (pattern_idx == pattern_size) assert(false);
        if (pattern_idx == pattern_size - 1LL) {
            start_to_next[text_idx - pattern_idx] = text_idx % slen;
        }
        if (pattern[pattern_idx] == pattern[0]) text_idx++;
        pattern_idx = kmp_next[pattern_idx];
    }
}

