        string ss(s.begin(), s.end());
        while(n){
            if(n & 1)s += ss;
            ss += ss;
            n >>= 1;
        }
    }

    vector<unsigned long> morris_pratt_search_result;
    auto morris_pratt_search_all = [&morris_pratt_search_result](auto s, auto t){
        string Q = t + "_" + s;
        unsigned long N = s.size(), M = t.size(), L = Q.size();
        vector<unsigned long> MP(L + 1);
        for(unsigned long i = 1, j = 0; i <= L; MP[i++] = j){
            while(j > 0 && Q[i - 1] != Q[j - 1])j = MP[j - 1];
            if(++j > M && i >= j + M && i < j + N + M)morris_pratt_search_result.push_back(i - j - M);
        }
    };

    morris_pratt_search_all(s, t);
    vector<unsigned long> idx(N), dep(N), id(N);
    iota(id.begin(), id.end(), 0UL);
    for(const auto& i : morris_pratt_search_result)if(i < N)idx[i] = 1;

    auto f = [rec = [&idx, &dep, &id, &M, &N](auto f, unsigned long i) -> unsigned long{
        if(dep[i])return dep[i];
        if(!idx[i])return 0;
        idx[i] = 0;
        id[i] = min(id[i], id[(i + M) % N]);
        dep[i] = 1 + f(f, (i + M) % N);
        if(id[(i + M) % N] == i)return dep[i] = 2 * N;
        return dep[i];
    }](unsigned long n){rec(rec, n);};
    for(unsigned long i = 0; i < N; ++i)if(idx[i])f(i);

    unsigned long ans = *max_element(dep.begin(), dep.end());
    if(ans >= N)puts("-1");
    else cout << ans << endl;
    return 0;
}

