void change(string &S){
    ll N=S.size();
    std::set<ll> memo;
    REP(i,1,sqrt(N)+1){
        if(N%i==0){
            memo.insert(i);
            memo.insert(N/i);
        }
    }
    for(auto p:memo){
        string T=S.substr(0,p);
        string X;
        bool flag=1;
        rep(i,p,N){
            X+=S[i];
            if(X.size()==p){
                if(X==T) X="";
                else{
                    flag=0;
                    break;
                }
            }
        }
        if(flag){
            S=T;
            return;
        }
    }
}
bool judge(string S,string T){
    srand((unsigned)time(NULL));
    vi mod(3);
    vi memo(3);
    rep(i,0,100) rand();
    rep(i,0,3) mod[i]=rand()%100000000000+1;
    ll N=S.size(),M=T.size();
    rep(i,0,3) memo[i]=modpow(27,M,mod[i]);
    vi model(3);
    vi now(3);
    rep(i,0,3){
        rep(j,0,M){
            ll X=T[j]-'a'+1;
            ll Y=S[j]-'a'+1;
            model[i]=(model[i]*27%mod[i]+X)%mod[i];
            now[i]=(now[i]*27+Y)%mod[i];
        }
    }
    bool flag=1;
    rep(i,0,3){
        if(model[i]!=now[i]){
            flag=0;
            break;
        }
    }
    if(flag) return 1;
    rep(i,M,N){
        flag=1;
        rep(j,0,3){
            ll X=S[i-M]-'a'+1,Y=S[i]-'a'+1;
            now[j]=(now[j]*27+Y)%mod[j];
            now[j]-=memo[j]*X%mod[j];
            now[j]%=mod[j];
            if(now[j]<0) now[j]+=mod[j];
            if(model[j]!=now[j]) flag=0;
        }
        if(flag) return 1;
    }
    return 0;
}
