            if(M%N) ans=1;
            else ans=-1;
        }
        else ans=0;
    }
    else{
        S+=S;
        ll left=0,right=N/M+1;
        while(left+1<right){
            ll mid=(left+right)/2;
            string X;
            rep(i,0,mid) X+=T;
            if(judge(S,X)) left=mid;
            else right=mid;
        }
        ans=left; 
        if(N%M==0){
            string X;
            rep(i,0,N/M) X+=T;
            if(judge(S,X)) ans=-1;
        }
    }
    cout<<ans<<endl;
