struct SuffixArray {
  string s;
  int n;
  vector<int> sa;
  vector<vector<int>> rank;
  int k, no, ne;
  SuffixArray(string s) : s(s), n((int) s.size()), sa(n + 1) {
    rank.assign(2, vector<int>(n + 1));
  }
  vector<int> build() {
    auto compare = [&](int i, int j) {
      if (rank[no][i] != rank[no][j]) return rank[no][i] < rank[no][j];
      int ri = i + k <= n ? rank[no][i + k] : -1;
      int rj = j + k <= n ? rank[no][j + k] : -1;
      return ri < rj;
    };
    for (int i = 0; i <= n; i++) {
      sa[i] = i;
      rank[0][i] = i < n ? s[i] : -1;
    }
    for (int i = 0; (1 << i) <= n; i++) {
      k = 1 << i;
      no = i % 2, ne = (no + 1) % 2;
      sort(sa.begin(), sa.end(), compare);
      rank[ne][sa[0]] = 0;
      for (int i = 1; i <= n; i++) {
        rank[ne][sa[i]] = rank[ne][sa[i - 1]] + compare(sa[i - 1], sa[i]);
      }
    }
    return sa;
  }
};

struct UnionFind {
  vector<int> data;
  UnionFind(int n) {
    data.assign(n, -1);
  }
  int root(int k) {
    if (data[k] < 0) return k;
    return data[k] = root(data[k]);
  }
  bool unite(int x, int y) {
    x = root(x), y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }
  int size(int k) {
    return -data[root(k)];
  }
};

