int f[N];

int PF(int len, char c) {
    while (len && pat[len] != c)
        len = f[len - 1];
    if (pat[len] == c)
        len++;
    return len;
}

void computeF() {
    f[0] = 0;
    int len = 0;
    if (*pat) {
        for (int i = 1; pat[i]; i++) {
            len = PF(len, pat[i]);
            f[i] = len;
        }
    }
}

vector<int> match() {
    vector<int> ind;
    int len = 0;
    for (int i = 0; str[i]; i++) {
        len = PF(len, str[i]);
        if (!pat[len])
            ind.push_back(i - len + 1), len = f[len - 1];
    }
    return ind;
}

int solve(const vi &v, int len, int c) {
    int ret = 0;
    vi good(c);
    for (int idx : v)good[idx] = true;
    rloop(i, SZ(v) - 1) {
        int cur = 1;
        if (v[i] + len < c)cur = good[v[i] + len] + 1;
        good[v[i]] = cur;
        ret = max(ret, cur);
    }
    return ret;
}

