    while(m + i < sloop.size()) {
        if(t[i] == sloop[m + i]) {
            i++;
            if(i == t.size()) {
                pat[m] = true;
                i--;
                m = m + i - table[i];
                if(i > 0) {
                    i = table[i];
                }
            }
        } else {
            m = m + i - table[i];
            if(i > 0) {
                i = table[i];
            }
        }
    }
    int ans = 0;
    vector<bool> used(s.size(), false);
    int smul = 0;
    while(smul < t.size()) {
        smul += s.size();
    }
    REP(i, s.size()) {
        if(pat[i] == true && used[i] == false) {
            int j = i;
            while(true) {
                if(pat[(j - t.size() + smul) % s.size()] == true) {
                    j = (j - t.size() + smul) % s.size();
                    if(i == j) {
                        cout << -1 << endl;
                        return 0;
                    }
                } else {
                    break;
                }
            }
            int k = 0;
            while(true) {
                used[j] = true;
                k++;
                if(pat[(j + t.size()) % s.size()] == true) {
                    j = (j + t.size()) % s.size();
                } else {
                    break;
                }
            }
            if(k > ans) ans = k;
        }
    }

    cout << ans << endl;
}

