// Fills Z array for given string str[] 
void getZarr(string str, int Z[]) { 
  int n = str.length(); 
  int L, R, k; 

	// [L, R] をsのprefixとして一致する範囲とする
  L = R = 0; 
  for (int i = 1; i < n; ++i) { // str[i]からの部分文字列についてチェック
    if (i > R) { 
      L = R = i; 
      while (R<n && str[R-L] == str[R]) // R-Lは0から始まる，つまりstrの最初から順に見てる
        R++; 
      Z[i] = R-L; 
      R--; // 行きすぎてるので一つ戻る？
    } else {
			// prefixとして成り立つ途中のところを見てるとき
      k = i-L; // 今見てるとこまでの長さ

    	// Z[k]が部分一致の残りより短い（その長さのprefix自身の部分一致がprefixの途中で終わってる?）場合，Z[i]=Z[k]
			// ex) str = "ababab", i=3, L=2, R=5 => Z[3] = Z[1]
      if (Z[k] < R-i+1) {
      	Z[i] = Z[k]; 
      } else { 
        L = i; 
        while (R<n && str[R-L] == str[R]) 
            R++; 
        Z[i] = R-L; 
        R--; 
      } 
    } 
  } 
}

// Z algorithm による部分文字列検索
// 一致したtext中でのindexを全てRに入れ，その数を返す
// Rのsizeはtext.length()以上である必要がある
int Zsearch(string text, string pattern, int R[]) { 
  // Create concatenated string "P$T" 
  string concat = pattern + "$" + text; 
  int l = concat.length(); 

  // Construct Z array 
  int Z[l];
  getZarr(concat, Z); 

  // now looping through Z array for matching condition 
  int c = 0;
  for (int i = 0; i < l; ++i) { 
    // if Z[i] (matched region) is equal to pattern length, we got the pattern 
    if (Z[i] == pattern.length()) {
      R[c] = i - pattern.length() - 1;
      ++c;
    }
  }

  return c;
}

struct edge {
	int to;
};

int main(){
	string s;
	string t;

	cin >> s;
	cin >> t;

	const int ls = s.length();
	const int lt = t.length();

	string sd; // sの繰り返し文字列 ls + lt 以上の長さが必要
	while (sd.length() < ls + lt) {
		sd.append(s);
	}

	const string sub_str = sd.substr(0, ls + lt -1);
	int R[MAX] = {0};

	int c = Zsearch(sub_str, t, R);

	vector<edge> G[ls];
	for (size_t i = 0; i < c; ++i) {
		G[R[i]].emplace_back((edge){(R[i] + lt) % ls});
	}

	// グラフの最長パス求める
	// 各ノードから出るedgeは 1本/0本 なので開始点が分かれば経路は1通り
	vector<int> path_len(ls);
	for (size_t i = 0; i < ls; ++i) {
		bool vis[MAX] = {false};
		int length = 0;

		int pos = i;
		vis[pos] = true;

		while(!G[pos].empty()) {
			++length;

			pos = G[pos].at(0).to;
			if (vis[pos] == true) {
				// 無限ループの場合
				cout << -1 << endl;
				return 0;
			}
			vis[pos] = true;
		}

		path_len[i] = length;
	}

	int ret = *max_element(begin(path_len), end(path_len));
	cout << ret << endl;

	return 0;
}

