            }
            auto s3=shi[i]+s2;
            auto s4=s3+uh(0,t2.digit-s3.digit);
            if(s4==t2){
                return true;
            }
        }
        return false;
    });
    if(ans>IINF/2)cout<<-1<<endl;
    else cout<<ans<<endl;
}

