const ll MS = 2;
const ll mods[] = {999999937ll, 1000000007ll}, base = 9973;
struct rolling_hash {
    int n;
    vector<ll> hs[MS], pw[MS];
    rolling_hash(){}
    rolling_hash(const string &s) {
        n = s.size();
        for (int i = 0; i < MS; i++) {
            hs[i].assign(n+1,0);
            pw[i].assign(n+1,0);
            hs[i][0] = 0;
            pw[i][0] = 1;
            for (int j = 0; j < n; j++) {
                pw[i][j+1] = pw[i][j]*base%mods[i];
                hs[i][j+1] = (hs[i][j]*base+s[j])%mods[i];
            }
        }
    }

    // hash number of segment [l, r)
    ll hash(int l, int r, int i) { return ((hs[i][r]-hs[i][l]*pw[i][r-l])%mods[i]+mods[i])%mods[i]; }

    bool match(int l1, int r1, int l2, int r2) {
        bool ret = 1;
        for (int i = 0; i < MS; i++) ret &= hash(l1,r1,i)==hash(l2,r2,i);
        return ret;
    }

    bool match(int l, int r, ll h[]) {
        bool ret = 1;
        for (int i = 0; i < MS; i++) ret &= hash(l,r,i)==h[i];
        return ret;
    }
};

ll count(string& X, string& Y){
	rolling_hash rx(X), ry(Y);
	ll cnt = 0;
	ll N = Y.size();
	ll ha[2] = {ry.hash(0, N, 0), ry.hash(0, N, 1)};
	REP(i, X.size()){
		ll j = i;
		while(j+N<=X.size() && rx.match(j, j+N, ha)) j += N;
		ll tmp = (j - i)/N;
		//printf("%lld %lld\n", i, j);
		cnt = max(cnt, tmp);
		if(i==j) i = j;
		else i = j-1;
	}
	return cnt;
}

