// https://www.geeksforgeeks.org/z-algorithm-linear-time-pattern-searching-algorithm/
vector<int> z_algo( const string &s ){
	int len = s.length();
	vector<int> Z(len);
	Z[0] = len;

	// LとR: 区間[L,R]が、文字列先頭の区間[0,R-L]と一致していることを表す
	int L = 0, R = 0;

	for ( int i = 1; i < len; i++ ){

		if ( R < i ){
			L = R = i;
			while ( R < len && s[R-L] == s[R] )
				R++;
			Z[i] = R-L;
			R--;
		}
		else {
			int k = i-L;

			if ( Z[k] < R-i+1 ){
				Z[i] = Z[k];
			}
			else {
				L = i; 

				while ( R < len && s[R-L] == s[R] )
					R++;
				Z[i] = R-L;
				R--;
			}
		}
	}

//	cout << s << endl;
//	for ( auto it : Z )
//		cout << it << " ";
//	cout << endl;

	return Z;
}

// 周期を調べる
int get_period( const vector<int> z ){
	int len = z.size();

	for ( int i = 1; i <= len / 2; i++ ){
		if ( i + z[i] == len && len % i == 0 ){
			return i;
		}
	}
	return len;
}




int main(){
	string s, t;
	cin >> s;
	cin >> t;

	int slen = s.size();
	int tlen = t.size();
	auto zs = z_algo(s);
	auto zt = z_algo(t);

	int period_s = get_period(zs);
	int period_t = get_period(zt);

	if ( period_s == period_t ){
		// 無限かどうか調べる。周期が同じで、周期以上の長さの部分一致があれば無限
		string sxtt = s + "X" + t + t;
		auto z_sxtt = z_algo(sxtt);
		for ( int i = 0; i < period_s; i++ ){
			if ( z_sxtt[slen+1+i] >= period_s ){
				cout << "-1" << endl;
				return 0;
			}
		}
	}


	// ttXsss...sX の文字列を作る
	int ssslen = slen*2+tlen*2;
	string sss(ssslen, ' ');
	for ( int i = 0; i < ssslen; i++ )
		sss[i] = s[i%slen];
	string ttxsss = t + t + "X" + sss + "X";
	auto z = z_algo(ttxsss);
	int pos = tlen*2+1;

	int max_repeat = 0;
	vector<int> ct(ssslen); // ct[i] : 位置iで一致回数を調べるとき、それより前に ct[i]回分の一致があることを表す
	for ( int i = 0; i < ssslen; i++ ){
		if ( z[pos+i] >= tlen ){
			// この位置から数えると、少なくとも1回分の長さの一致がある。
			max_repeat = max( max_repeat, ct[i]+1 );
			if ( i+tlen < ssslen )
				ct[i+tlen] = ct[i]+1;
		}
	}

	cout << max_repeat << endl;

	return 0;
}

