				for (int k = 0; k < 2; k++)
				{
					bh[k] = (bh[k] * base[k] + b[i + al] - b[i] * t[k]) % mod[k];
				}
			}
			i++;
		}
		ans = max(ans, res);
	}
	return ans;
}

signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	string s, t;

	cin >> s >> t;

	string tts;
	while (SZ(tts) < SZ(t))
	{
		tts += s;
	}

	string ts = tts;
	bool ok = true;
	int ans = -1;
	rep(i, 0, 10)
	{
		if (!chmax(ans, rolling_hash_count(t, ts)))
		{
			ok = false;
			break;
		}
		ts += tts;
	}

	if (ok)
	{
		cout << -1 << endl;
	}
	else
	{
		cout << ans << endl;
	}

	return 0;
}

