#define N 5000005
#define P 998244353
int nn, n, m, ha[N], hb, pw;
char a[N], b[N];
bool vis[N], used[N];
int hash(int l){
	return (ha[l + m - 1] - 1ll * ha[l - 1] * pw % P + P) % P;
}
int main(){
	scanf("%s", a + 1), nn = n = strlen(a + 1);
	scanf("%s", b + 1), m = strlen(b + 1);
	while (n < m){
		for (register int i = 1; i <= nn; ++i) a[n + i] = a[i];
		n += nn;
	}
	for (register int i = 1; i <= n; ++i) a[n + i] = a[i];
	nn = n << 1;
	ha[0] = 0;
	for (register int i = 1; i <= nn; ++i)
		ha[i] = (1ll * ha[i - 1] * 31 + a[i] - 'a') % P;
//	putchar('\n');
	hb = 0, pw = 1;
	for (register int i = 1; i <= m; ++i)
		hb = (1ll * hb * 31 + b[i] - 'a') % P, pw = 1ll * pw * 31 % P;
//	printf("%d\n", hash(1));
	int ans = 0;
	for (register int i = 1; i <= n; ++i)
		if (!vis[i]){
			int s = 0;
			for (register int j = i; hash(j) == hb; used[j] = 1, j = (j + m - 1) % n + 1)
				if (used[j]) return printf("-1\n"); else vis[j] = 1, ++s;
			for (register int j = i; hash(j) == hb; j = (j + m - 1) % n + 1) used[j] = 0;
			ans = std :: max(ans, s);
		}
	printf("%d\n", ans);
}

