int diameter(digraph<> &g) {    vi per;    if (!topo(per, g))return -1;    int n = g.n;    vi dp(n,1);    fora(v, per) {        forg(gi, g[v]) {            chma(dp[t], dp[f] + 1);        }    }    return max(dp);}
