vector<int> FindMatchAllByRollingHash(const string& s, const string& key) {
  if (s.length() < key.length()) return {};

  constexpr int64 P1 = 1000000007;
  constexpr int64 P2 = 999999937;
  constexpr int64 B = 257;

  int m = key.length();
  int64 bm1 = 1;
  int64 bm2 = 1;
  for (int i = 0; i < m; i++) {
    bm1 = bm1 * B % P1;
    bm2 = bm2 * B % P2;
  }
  int64 kh1 = 0;
  int64 kh2 = 0;
  for (int i = 0; i < m; i++) {
    kh1 = (kh1 * B + key[i]) % P1;
    kh2 = (kh2 * B + key[i]) % P2;
  }

  vector<int> positions;
  int64 h1 = 0;
  int64 h2 = 0;
  for (int i = 0; i < m; i++) {
    h1 = (h1 * B + s[i]) % P1;
    h2 = (h2 * B + s[i]) % P2;
  }

  if (DEBUG) cout << "s.length: " << s.length() << endl;
  if (DEBUG) cout << "m: " << m << endl;

  if (h1 == kh1 && h2 == kh2) {
    if (DEBUG) cout << "push_back: " << 0 << endl;
    positions.push_back(0);
  }

  for (int i = 1; i + m <= s.length(); i++) {
    if (DEBUG) cout << "i: " << i << endl;
    if (DEBUG) {
      cout << "h1: " << h1 << endl;
      cout << "h2: " << h2 << endl;
    }
    h1 = (h1 * B + s[i + m - 1]) % P1;
    h1 = (h1 + P1 - (bm1 * s[i - 1] % P1)) % P1;
    h2 = (h2 * B + s[i + m - 1]) % P2;
    h2 = (h2 + P2 - (bm2 * s[i - 1] % P2)) % P2;
    if (h1 == kh1 && h2 == kh2) {
      if (DEBUG) cout << "push_back: " << i << endl;
      positions.push_back(i);
    }
  }
  return positions;
}

