template<typename T,T MOD,T B>
struct RollingHash{
  vector<T> hash,p;
  RollingHash(){}
  RollingHash(const string &s){
    int n=s.size();
    hash.assign(n+1,0);
    p.assign(n+1,1);
    for(int i=0;i<n;i++){
      hash[i+1]=(hash[i]*B+s[i])%MOD;
      p[i+1]=p[i]*B%MOD;
    }
  }
  //S[l, r)
  T find(int l,int r){
    T res=hash[r]+MOD-hash[l]*p[r-l]%MOD;
    return res>=MOD?res-MOD:res;
  }
};

string make(string s, long long x) {
  string res = "";
  string temp = s;
  while(x > 0) {
    if(x & 1) res += temp;
    x >>= 1;
    temp = temp + temp;
  }
  return res;
}

int isOk(RollingHash<long long, MOD, B> rh, RollingHash<long long, MOD, B> th, string r) {
  // string temp = make(t, key);
  int cnt = 0;
  int i = 0;
  int res = 0;
  while(i < s.size() + t.size()) {
    if(rh.find(i, i + t.size()) == th.find(0, t.size())) {
      // cout << t.size() << endl;
      // cout << i << " " << temp.size() << " " << r.substr(i, temp.size()) << " " << temp << endl;
      if(r.substr(i, t.size()) == t) {
        // cout << cnt << " " << i << " " << r.substr(i, t.size()) << " " << t << endl;
        i = i + t.size();
        cnt++;
      } else {
        cnt = 0;
        i++;
      }
    } else {
      cnt = 0;
      i++;
    }
    res = max(res, cnt);
    // cout << i << endl;
  }
  return res;
}

