// z[i] stores the value of the longest common prefix between s 
// and the suffix of s starting at i
vector<int> z_function(string s) {
    int n = (int) s.length();
    vector<int> z(n);
    for (int i = 1, l = 0, r = 0; i < n; ++i) {
        if (i <= r)
            z[i] = min (r - i + 1, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]])
            ++z[i];
        if (i + z[i] - 1 > r)
            l = i, r = i + z[i] - 1;
    }
    return z;
}

bool find_match(vector<int> &z, int tlen, int pos) {
	return z[pos + tlen + 1] == tlen;
}

int main() {
