	vector<int> z = z_function(nw);
	for (int i = 0; i < slen; ++i) {
		bool good = find_match(z, tlen, i);
		adj[i] = -1;
		visit[i] = false;
		if (good) {
			int j = (i + tlen) % slen;
			adj[i] = j;
			++indeg[j];
