public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var s = cr.Ascii;
        var t = cr.Ascii;
        var sb = new StringBuilder((s.Length + t.Length) << 1);
        while (sb.Length < s.Length + t.Length) sb.Append(s);
        var ss = sb.ToString();

        var oks = new bool[s.Length];
        var matches = new KMP(t).Matches(ss).Where(i => i < s.Length).ToArray();
        if (matches.Length == 0) return 0;
        foreach (var i in matches)
            oks[i] = true;

        var uf = new UnionFind(s.Length);
        for (int i = 0; i < oks.Length; i++)
        {
            if (oks[i] && oks[(i + t.Length) % oks.Length])
            {
                if (!uf.TryUnionSet(i, (i + t.Length) % oks.Length))
                    return -1;
            }
        }


        return Enumerable.Range(0, s.Length).Max(i => uf.Count(i));
    }
}
class KMP // https://algoful.com/Archive/Algorithm/KMPSearch
{
    string pattern;
    int[] table;
    public KMP(string pattern) { this.pattern = pattern; table = CreateTable(pattern); }
    static int[] CreateTable(string pattern)
    {
        var table = new int[pattern.Length + 1];
        int j = 0;
        for (int i = 1; i < table.Length; i++)
        {
            if (i < pattern.Length && pattern[i] == pattern[j])
                table[i] = j++;
            else
            {
                table[i] = j;
                j = 0;
            }
        }
        return table;
    }

    public IEnumerable<int> Matches(string target)
    {
        int i = 0, p = 0;
        while (i < target.Length && p < pattern.Length)
        {
            if (target[i] == pattern[p])
            {
                // 文字が一致していれば次の文字に進む
                i++; p++;
            }
            else if (p == 0)
            {
                // パターン先頭文字が不一致の場合、次の文字
                i++;
            }
            else
            {
                // 不一致の場合、パターンのどの位置から再開するか設定
                p = table[p];
            }

            if (p == pattern.Length)
            {
                yield return i - p;
                p = table[p];
            }
        }
    }
}
class UnionFind
{
    int[] data;
    public UnionFind(int size)
    {
        this.data = NewArray(size, -1);
    }

    public int Root(int x)
    {
        if (data[x] < 0) return x;
        return data[x] = Root(data[x]);
    }
    public int Count(int x) => -data[Root(x)];
    public void UnionSet(int x, int y) => TryUnionSet(x, y);
    public bool TryUnionSet(int x, int y)
    {
        var xRoot = Root(x);
        var yRoot = Root(y);
        if (xRoot == yRoot) return false;
        else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
        {
            var tmp = yRoot;
            yRoot = xRoot;
            xRoot = tmp;
        }
        data[xRoot] += data[yRoot];
        data[yRoot] = xRoot;
        return true;
    }
    public bool IsSameSet(int x, int y) => Root(x) == Root(y);
}

