vector<int> Z_algorithm(string S){
  vector<int> A(S.length(),0);
  A[0] = S.size();
  int i = 1, j = 0;
  while (i < S.size()) {
    while (i+j < S.size() && S[j] == S[i+j]) ++j;
    A[i] = j;
    if (j == 0) { ++i; continue;}
    int k = 1;
    while (i+k < S.size() && k+A[k] < j) A[i+k] = A[k], ++k;
    i += k; j -= k;
  }
  return A;
}

string min_cycle(string S){
  vector<int> Z = Z_algorithm(S+S);
  int L = S.length();
  // for(auto e : Z) cerr << e << " ";
  // cerr << endl;
  for(int i = 1; i < L; ++i){
    if(Z[i] >= L){
      return S.substr(0,i);
    }
  }
  return S;
}

