vector<int> kmp(string s, string w) {
    int n = s.size(), m = w.size();
    vector<int> t(m + 1), res;
    t[0] = -1;
    int k = -1, i = 0;
    for (int i = 0; i < m; i++) {
        while (k >= 0 && w[i] != w[k]) k = t[k];
        t[i + 1] = ++k;
    }
    k = 0;
    while (k + i < n) {
        if (w[i] == s[k + i]) {
            if (++i == m) {
                res.emplace_back(k);
                k = k + i - t[i];
                i = t[i];
            }
        } else {
            k = k + i - t[i];
            if (i > 0) {
                i = t[i];
            }
        }
    }
    return res;
}

