struct rolling_hash{
	vector<long long> h;
	vector<vector<long long>> t_hash;
	vector<vector<long long>> power;
	long long b;
	string t;

	rolling_hash(string &T){
		h.push_back(998244353);h.push_back(1000000007);h.push_back(1000000009);
		t_hash.resize(h.size(),vector<long long>(T.size()+1,0));
		power.resize(h.size(),vector<long long>(T.size()+1,1));
		b = 1010101;
		t=T;

		for(int i=0;i<h.size();i++){
			for(int j=1;j<=t.size();j++){
				power[i][j] = (power[i][j-1] * b)%h[i];
			}
		}

		for(int i=0;i<h.size();i++){
			for(int j=1;j<=t.size();j++){
				t_hash[i][j] = ((t_hash[i][j-1]*b + (long long)t[j-1]))%h[i];
			}
		}


	}

	//[l,r)
	vector<long long> get(int l,int r){
		vector<long long> ret(h.size());
		for(int i=0;i<h.size();i++){
			ret[i] = t_hash[i][r] - (t_hash[i][l] * power[i][r-l]);
			if(ret[i]>=0)ret[i]%=h[i];
			else{
				ret[i] = (-ret[i]%h[i]);
				ret[i] = (h[i]-ret[i])%h[i];
			}
		}
		return ret;
	}

};

int main(){

	string s,t;
	cin>>s>>t;

	rolling_hash ro_t(t);


	int sz = s.size();
	s = s+s;
	while(true){
		if(s.size()>=t.size()*2)break;
		s = s+s;
	}

	rolling_hash ro_s(s);


	vector<vector<int>> E(sz,vector<int>(0));
	vector<int> jisuu(sz,0);

	for(int i=0;i<sz;i++){
		if(ro_s.get(i,i+t.size())==ro_t.get(0,t.size())){
			int k = (i+(int)t.size())%sz;
			E[i].push_back(k);
			jisuu[k]++;
		}
	}
	queue<int> que;
	vector<int> sorted(0);

	for(int i=0;i<sz;i++){
		if(jisuu[i]==0){
			que.push(i);
		}
	}

	while(que.size()!=0){
		int x = que.front();
		que.pop();
		sorted.push_back(x);
		for(int i=0;i<E[x].size();i++){
			int a = E[x][i];
			jisuu[a]--;
			if(jisuu[a]==0)que.push(a);
		}
	}
	vector<int> dis(sz,-1);
	if(sorted.size()!=sz){
		cout<<-1<<endl;
		return 0;
	}

	for(int i=0;i<sz;i++){
		int now = sorted[i];
		vector<int> k(0);
		int cnt = 0;
		while(true){
			if(dis[now]!=-1){
				cnt += dis[now];
				break;
			}
			k.push_back(now);
			if(E[now].size()==0)break;
			cnt++;
			now = E[now][0];
		}
		for(int j=0;j<k.size();j++){
			dis[k[j]]=cnt-j;
		}
	}

	int ans = 0;
	for(int i=0;i<sz;i++)ans = max(ans,dis[i]);



	cout<<ans<<endl;





	return 0;
}

