            srep.push_back(S[i]);
        }
    }

    vector<char> Tvec;
    for (int i=0;i<T.length();i++) Tvec.push_back(T[i]);

    vector<modnum<MOD>> Shashes = gen_hashes(srep);
    vector<modnum<MOD>> Thashes = gen_hashes(Tvec);

    modnum<MOD> thash = Thashes[NT];
    vi cycles(NS, -1);
    for(int i=0;i<NS;i++) {
        modnum<MOD> shash = Shashes[i+NT] - Shashes[i];
        modnum<MOD> factor = modnum<MOD>(A).pow(i);
        if ((thash * factor) == shash) {
            cycles[i] = (i+NT) % NS;
        }
    }


    vi clens(NS, -1);
    for (int i=0;i<NS;i++) {
        if (clens[i] == -1) {
            int count = 0;
            int ind = i;
