	while (m + i < S.size()) {
		if (W[i] == S[m + i]) {
			++i;
			if (i == W.size())return m;
		}
		else {
			m = m + i - T[i];
			if (i > 0) {
				i = T[i];
			}
		}
	}
	//W が S 内に見つからなかった場合
	return -1;
}







