// ローリングハッシュ
// 二分探索で LCP を求める機能つき
struct RollingHash {
    static const int base1 = 1007, base2 = 2009;
    static const int mod1 = 1000000007, mod2 = 1000000009;
    vector<long long> hash1, hash2, power1, power2;

    // construct
    RollingHash(const string& S) {
        int n = (int)S.size();
        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        power1.assign(n + 1, 1);
        power2.assign(n + 1, 1);
        for (int i = 0; i < n; ++i) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }

    // get hash of S[left:right]
    inline pair<long long, long long> get(int l, int r) const {
        long long res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        long long res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;
        if (res2 < 0) res2 += mod2;
        return { res1, res2 };
    }
};


int main() {
    string s, t;
    vec v;
    cin >> s >> t;
    while (s.size() < t.size()) {
        s += s;
    }
    int lent = t.size();
    int lens = s.size();
    s += s + s;
    RollingHash rhs(s), rht(t);
    p Thash=rht.get(0, lent);
    rep(i, lens) {
        if (rhs.get(i, i + lent) == Thash) {
            v.push_back(i);
        }
    }
    if (v.empty())cout << 0 << endl;
    else {
        map<int, int> ma;
        int i = 0;
        rep(i, v.size()) {
            ma[v[i]] = 1;
        }
        int CNT = 0;
        int a = v[0];
        while (CNT <= 500000) {
            a += lent;
            a %= lens;
            if (ma.count(a))CNT++;
            else break;
        }
        if (CNT == 500001)cout << -1 << endl;
        else {
            int ans = 1;
            int cnt = 1;
            rep(i, v.size()) {
                int q = v[i];
                while (ma.count(q)) {
                    cnt++;
                    q += lent;
                    q %= lens;
                }
                ans = max(ans, cnt-1);
                cnt = 1;
            }
            cout << ans << endl;
        }
    }

    return 0;
}

