void solve()
{
	string s, t;
	cin >> s >> t;

	string temp = s;

	while(len(s) <= len(t))
	{
		s += temp;
	}

	int n = len(s);
	s += s;

	string f = t + '#' + s;
	int k = len(t);
	int m = len(f);
	vector<int> z(m, 0);

	int l = NIL, r = NIL;

	for(int i = 1; i < m; ++i)
	{
		if(i <= r)
			z[i] = min(z[i - l], r - i + 1);

		while(i + z[i] < m && f[i + z[i]] == f[z[i]])
			++z[i];

		if(i + z[i] - 1 >= r)
			l = i, r = i + z[i] - 1;
	}

	vector<int> jump(n, NIL);

	for(int i = 0; i < n; ++i)
	{
		int go = z[i + k + 1];

		if(go == k)
		{
			jump[i] = (i + go) % n;

#ifdef __LOCAL
			cout << i << " -> " << jump[i] << endl;
#endif
		}
	}

	vector<int> met(n, NIL);
	vector<int> ord;
	int answ = 0;

	for(int i = 0; i < n; ++i)
	{
		if(met[i] == NIL)
		{
			vector<int> st;

			for(int j = i; j != NIL; j = jump[j])
			{
				st.push_back(j);

				if(met[j] == i)
				{
					cout << NIL << endl;
					exit(0);
				}

				if(met[j] != NIL)
					break;

				met[j] = i;
			}

			while(!st.empty())
			{
				ord.push_back(st.back());
				st.pop_back();
			}
		}		
	}

	reverse(ord.begin(), ord.end());
	fill(met.begin(), met.end(), NIL);

	for(auto& i: ord)
	{
		if(met[i] == NIL)
		{
			int local = 0;

			for(int j = i; j != NIL; j = jump[j])
			{
				if(met[j] != NIL)
					break;

				++local;
				met[j] = i;
			}

			answ = max(answ, local - 1);
		}
	}

	cout << answ << endl;
}

