int p_pow[(int) 2e6 + 55];
int p_pow2[(int) 2e6 + 55];
int h[(int) 2e6 + 55];
int h2[(int) 2e6 + 55];
bool rabin_karp(string s, string t, int repeat) {
    int S = s.size(), T = t.size();
    if (S * repeat > T)
    	return false;
    string ss = s;
    for (int i = 0; i < repeat - 1; ++i)
    	ss += s;
    s = ss;
    S = (int) s.size();
    long long h_s = 0, h_s2 = 0; 
    for (int i = 0; i < S; i++) 
        h_s = (h_s + (s[i] - 'a' + 1) * p_pow[i]) % m, h_s2 = (h_s2 + (s[i] - 'a' + 1) * p_pow2[i]) % m2; 
    for (int i = 0; i + S - 1 < T; i++) { 
        long long cur_h = (h[i+S] + m - h[i]) % m, cur_h2 = (h2[i+S] + m2 - h2[i]) % m2; 
        if (cur_h == (h_s * p_pow[i]) % m && cur_h2 == (h_s2 * p_pow2[i]) % m2)
			return true;            
    }
    return false;
}
void solve() {
	p_pow[0] = 1; 
	p_pow2[0] = 1;
	for (int i = 1; i < (int) 1e6 + 55; i++) 
		p_pow[i] = (p_pow[i-1] * p) % m, p_pow2[i] = (p_pow2[i - 1] * p) % m2;
	string s, t;
	cin >> s >> t;
	auto D = generate_divisors((int) s.size());
