	auto S(s + s);
	while (t.size() * 3 >= S.size()) S += s;

	int t0 = calc(S, t);
	S += S;
	int t1 = calc(S, t);
	if (t0 == t1) {
		OUT(t0)BR;
	}
	else {
		OUT(-1)BR;
	}

	return 0;
}

#include <cstdio>
