vector<int> pf(string &s)
{
	vector<int> p(s.size());
	int k = 0;
	for (int i = 1; i < s.size(); ++i)
	{
		while (k && s[i] != s[k])
		{
			k = p[k - 1];
		}
		k += (s[i] == s[k]);
		p[i] = k;
	}
	return p;
}
bool check(string &s, string & t, int m)
{
	string kek = "";
	for (int i = 0; i < m; ++i) kek += t;
	string tkek = s;
	while (tkek.size() / 2 < kek.size()) tkek += tkek;
	string toc = kek + "#" + tkek;
	auto lole = pf(toc);
	if (find(all(lole), kek.size()) != lole.end())
	{
		return 1;
	}
	return 0;
}
