int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	string S, T;
	cin >> S >> T;
	string temp = S;
	while (S.size() < T.size())S += temp;

	RollingHash rhs1(S+S, 1007, 1e9 + 7);
	RollingHash rht1(T, 1007, 1e9 + 7);


	vector<int>in(S.size());
	vector<int>e[1010101];
	for (int left = 0; left < S.size(); left++) {
		int h1 = rhs1.between(left,left + T.size());
		int h2 = rht1.between(0,T.size());
		if (h1 == h2) {
			in[(left + T.size()) % S.size()]++;
			e[left].pb((left+T.size())%S.size());
		}
	}
	vector<int>ord = TopologicalSort(S.size(),in,e);

	if (ord.size() != S.size()) {
		puts(-1);
		return 0;
	}

	int ans = 0;
	for (int i = 0; i < S.size() - 1; i++) {
		int cur = ord[i];
		fore(to, e[cur]) {
			dp[to] = max(dp[cur] + 1, dp[to]);
			ans = max(dp[to], ans);
		}
	}
	puts(ans);

	return 0;
}

