Vec< int > makeKMPfail(const string& S) {
	int n = S.size();	
	Vec< int > fail(n+1, 0);
	int j = fail[0] = -1;
	for_(i,1,n+1) {
		while (j >= 0 && S[j] != S[i - 1]) j = fail[j];
		fail[i] = ++j;
	}
	return fail;
}

bool cyclic(const string& S, const string& T) {
	string x = S + S;
	Vec< int > t_fail = makeKMPfail(T);
	int N = x.size(), m = T.size();
	for (int i=0, k=0; i < N; ++i) {
		while (k >= 0 && T[k] != x[i]) k = t_fail[k];
		if (++k >= m) return true;
	}
	return false;
}

int main() {
	string s, t;
	cin >> s >> t;
	int n = s.size(), m = t.size();

	///
	Vec< int > s_fail = makeKMPfail(s);
	Vec< int > t_fail = makeKMPfail(t);
	int sp = n - s_fail[n], tp = m - t_fail[m];
	if (n % sp == 0 && m % tp == 0) {
		if (sp == tp && cyclic(s.substr(0, sp), t.substr(0, tp))) {
			puts("-1");
			return 0;
		}
	}
//	cerr << "sp " << sp << endl;
//	cerr << "tp " << tp << endl;

	///
	string x = s;
	while (x.size() < t.size()) x += x;
	for_(i,0,5) x += x;
	int N = x.size();
//	cerr << x << endl;
//	cerr << t << endl;

	Vec< bool > match(N+1, false);
	for (int i=0, k=0; i < N; ++i) {
		while (k >= 0 && t[k] != x[i]) k = t_fail[k];
		if (++k >= m) {
			match[i] = true;
			k = t_fail[k];
		}
	}

	int ans = 0;
	for_(i,1,N+1) {
		if (match[i]) {
			int j = i, cnt = 0;
			while (j <= N && match[j]) {
				match[j] = false;
				j += m;
				++cnt;
			}
			ans = max(ans, cnt);
		}
	}
	cout << ans << endl;
}
