int zal[2000010], bfs[500010], mx=1e7;

int main() {
	string S, T;
	cin >> S >> T;
	string z=T+S;
	for(int i=0; i+1<T.size(); ++i){
		z += S[i%S.size()];
	}
	zal[0]=z.size();
	int i=1, j=0;
	while(i<T.size()+S.size()){
		while(i+j<z.size()){
			if(z[i+j]!=z[j]) break;
			++j;
		}
		zal[i]=j;
		if(j==0){
			++i;
			continue;
		}
		int k=1;
		while(k<j && i+k<T.size()+S.size()){
			if(k+zal[k]>=j) break;
			zal[i+k]=zal[k];
			++k;
		}
		i += k, j -= k;
	}
	deque<int> dq;
	for(int i=0; i<S.size(); ++i){
		if(zal[i+T.size()]<T.size()){
			bfs[i]=0;
			dq.emplace_back(i);
		}
		else{
			bfs[i]=mx;
		}
	}
	while(!dq.empty()){
		int nx=(dq.front()+S.size()-T.size()%S.size())%S.size();
		if(bfs[nx]>bfs[dq.front()]+1){
			dq.emplace_back(nx);
			bfs[nx]=bfs[dq.front()]+1;
		}
		dq.pop_front();
	}
	int ans=0;
	for(int i=0; i<S.size(); ++i) ans=max(ans, bfs[i]);
	if(ans==mx) cout << -1 << endl;
	else cout << ans << endl;
	return 0;
}

