vector<int> rotation_array(string const & s) {
	int n = SI(s);
	vector<int> r(n), a(n);
	inc(i, n) {
		r[i] = s[i];
		a[i] = i;
	}
	for(int k = 1; k < n; k <<= 1) {
		auto comp = [&](int x, int y) -> bool {
			int x1 = r[x], x2 = r[x + k - (x + k < n ? 0 : n)];
			int y1 = r[y], y2 = r[y + k - (y + k < n ? 0 : n)];
			return (MP(x1, x2) < MP(y1, y2));
		};
		stable_sort(ALL(a), comp);
		vector<int> rr(n);
		inc(i, n - 1) { rr[a[i + 1]] = rr[a[i]] + (comp(a[i], a[i + 1]) ? 1 : 0); }
		r = rr;
	}
	return a;
}

vector<int> rotation_lcp_array(string const & s, vector<int> const & RA) {
	int n = SI(s);
	vector<int> r(n), l(n); // l.back() == 0
	inc(i, n) { r[RA[i]] = i; }
	int c = 0;
	inc(i, n) {
		if(c > 0) { c--; }
		if(r[i] + 1 == n) { continue; }
		int j = RA[r[i] + 1];
		while(c < n && s[(i + c) % n] == s[(j + c) % n]) { c++; }
		l[r[i]] = c;
		if(j + 1 == n) { c = 0; }
	}
	return l;
}


