// >>> z-algorithm
template <class str>
vector<int> z_alg(str const& s) {
    const int n = s.size();
    vector<int> z(n); z[0] = n;
    for (int i = 1, l = 0, r = 1; i < n; ++i) {
        if (i < r) z[i] = min(r-i, z[i-l]);
        while (i+z[i] < n && s[z[i]] == s[i+z[i]]) ++z[i];
        if (r <= i+z[i]) l=i, r=i+z[i];
    }
    return z;
}

template <class str>
vector<int> z_search(str const& s, str const& p) {
    str t(p.size()+s.size(),0);
    rep (i,p.size()) t[i] = p[i];
    rep (i,s.size()) t[p.size()+i] = s[i];
    auto z = z_alg(t);
    vector<int> ret;
    rep (i,s.size()) if (z[p.size()+i] >= (int)p.size()) ret.push_back(i);
    return ret;
}
