struct KMP {
    string const s;
    vector<int> const table;
    vector<int> makeTable(const string &s) {
        int n = s.size();
        vector<int> ret(n + 1);
        ret[0] = -1;
        int j = -1;
        for (int i = 0; i < n; i++) {
            while (j >= 0 && s[i] != s[j])
                j = ret[j];
            ret[i + 1] = ++j;
        }
        return ret;
    }

    KMP(string s) : s(s), table(makeTable(s)) {}

    // return the list of indices of s where its substring matches t
    vector<int> match(string const &t) {
        vector<int> ret;
        int m = 0, i = 0, n = s.size();
        while (m + i < n) {
            if (t[i] == s[m + i]) {
                if (++i == (int)(t.size())) {
                    ret.push_back(m);
                    m = m + i - table[i];
                    i = table[i];
                }
            } else {
                m = m + i - table[i];
                if (i > 0)
                    i = table[i];
            }
        }
        return ret;
    }
};

template <typename T> // T : type of cost
struct BellmanFord {
    T inf = numeric_limits<T>::max(); // initial value, reused when clear() is called
    int n;                            // number of nodes
    vector<T> dist;                   // distance from start node
    bool negativeLoop;
    struct edge {
        int from, to;
        T cost;
        edge(int from, int to, T cost) : from(from), to(to), cost(cost) {}
    };
    vector<edge> edges;

    BellmanFord(int n) : n(n), negativeLoop(false), dist(n, inf){};
    // 0-indexed!
    void addEdge(int from, int to, T cost) { edges.emplace_back(from, to, cost); }
    // calculate dist[i] as a shortest distance from start (to end)
    // end is used to check if there is "relevant" negative circuit
    // even if there is negative curcuit, it might not affect the path of interest
    void build(int start, int end = -1) {
        dist[start] = 0;
        for (int i = 0; i < n; ++i) {
            for (auto &e : edges) {
                if (dist[e.from] != inf && dist[e.to] > dist[e.from] + e.cost) {
                    dist[e.to] = dist[e.from] + e.cost;
                    if (i == n - 1 && (end == -1 || end == e.to)) {
                        negativeLoop = true;
                        break;
                    }
                }
            }
        }
    }
};

// topologically sort the directed graph
// 0-indexed

struct TopologicalSort {
    int n;
    vector<set<int>> G;
    vector<bool> used;
    vector<int> indeg, p;

    TopologicalSort(int size) : n(size), G(n), used(n), indeg(n), p(0) {}

    void addEdge(int s, int t) { G[s].insert(t); }
    void bfs(int s) {
        queue<int> q;
        q.push(s);
        used[s] = 1;
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            p.push_back(v);
            for (int u : G[v]) {
                indeg[u]--;
                if (indeg[u] == 0 && !used[u]) {
                    used[u] = 1;
                    q.push(u);
                }
            }
        }
    }
    // returns topologically sorted nodes
    vector<int> build() {
        fill(used.begin(), used.end(), 0);
        fill(indeg.begin(), indeg.end(), 0);
        for (int i = 0; i < n; ++i) {
            for (int v : G[i])
                indeg[v]++;
        }
        for (int i = 0; i < n; ++i) {
            if (indeg[i] == 0 && !used[i])
                bfs(i);
        }
        return p;
    }
};

int dfs(int c, vi &dp, vvi &edges) {
    if (dp[c] != -1) {
        return dp[c];
    }
    if (edges[c].size() == 0)
        return dp[c] = 0;
    else {
        return dp[c] = dfs(edges[c].front(), dp, edges) + 1;
    }
}

