struct KMP {
    string const s;
    vector<int> const table;
    vector<int> makeTable(const string &s) {
        int n = s.size();
        vector<int> ret(n + 1);
        ret[0] = -1;
        int j = -1;
        for (int i = 0; i < n; i++) {
            while (j >= 0 && s[i] != s[j])
                j = ret[j];
            ret[i + 1] = ++j;
        }
        return ret;
    }

    KMP(string s) : s(s), table(makeTable(s)) {}

    // return the list of indices of s where its substring matches t
    vector<int> match(string const &t) {
        vector<int> ret;
        int m = 0, i = 0, n = s.size();
        while (m + i < n) {
            if (t[i] == s[m + i]) {
                if (++i == (int)(t.size())) {
                    ret.push_back(m);
                    m = m + i - table[i];
                    i = table[i];
                }
            } else {
                m = m + i - table[i];
                if (i > 0)
                    i = table[i];
            }
        }
        return ret;
    }
};

