vector<bool> used(MAX_V);
vector<int> cmp(MAX_V);
vector<int> depth(2000001, -1);
vector<int> vs;
void add_edge(int from, int to){ G[from].push_back(to), rG[to].push_back(from);}
void dfs(int v){
  used[v] = true;
  for(int i=0;i<G[v].size();i++) if(!used[G[v][i]]) dfs(G[v][i]);
  vs.push_back(v);
}
void rdfs(int v, int k){
  used[v] = true;
  cmp[v] = k;
  for(int i=0;i<rG[v].size();i++) if(!used[rG[v][i]]) rdfs(rG[v][i], k);
}
int scc(int V){
  for(int i=0;i<MAX_V;i++) used[i] = false;
  vs.clear();
  for(int i=0;i<=V;i++) if(!used[i]) dfs(i);
  for(int i=0;i<MAX_V;i++) used[i] = false;
  int k = 0;
  for(int i=vs.size()-1;i>=0;i--) if(!used[vs[i]]) rdfs(vs[i], k++);
  return k;
}
//-------------------------------------------------------------------
void KMPMatch(string src, string pat){
    int ini[pat.size()], i=1, j=0;
    ini[0] = 0;
    while(i<pat.size()){
      if(pat[i] == pat[j]) j++, ini[i] = j, i++;
      else if(j == 0) ini[i] = 0, i++;
      else j = ini[j - 1];
    }
    i = j = 0;
    while(j<pat.size()&&i<src.size()/2+pat.size()-2){
      if(src[i] == pat[j]) i++, j++;
      else if(j == 0) i++;
      else j = ini[j - 1];
      if(j==pat.size()-1) add_edge(abs(i-j), i%(src.size()/2));
    }
}
int df(int now){
  if(now<0||now>2000001){
    while(true) now = now+1-1;
  }
  if(depth[now]!=-1) return depth[now];
  if(G[now].size()==0) return depth[now] = 0;
  for(int i=0;i<G[now].size();i++){
    depth[now] = max(depth[now], df(G[now][i])+1);
  }
  return depth[now];
}
