//Union Find
const ll MAX_V = 1000010;

ll par[MAX_V];//
ll Rank[MAX_V];
ll child[MAX_V];

void init_UF(vector<bool> ok){
  for(ll i = 0; i < ok.size(); i++){
    par[i] = i;
    Rank[i] = 1;
    if(ok[i]) child[i] = 1;
  }
}

ll find(ll x){
  if(par[x] == x) return x;
  else{
    return par[x] = find(par[x]);
  }
}

bool same(ll x, ll y){
  return find(x) == find(y);
}

bool unite(ll x, ll y){
  ll rx = find(x), ry = find(y);
  if(rx == ry){
    return 0;
  }
  if(rx != ry){
    if(Rank[rx] >= Rank[ry]){
      par[ry] = rx;
      if(Rank[rx] == Rank[ry]) Rank[rx]++;
      child[rx] += child[ry];
    }else{
      par[rx] = ry;
      child[ry] += child[rx];
    }
  }
  return 1;
}

struct RollingHash{
  string S;
  ll sl;//Sのサイズ
  vector<ll> hashed, power;
  ll base = 998244353;
  ll MOD = 1000000007;
  void getS(string S){
    S = S;
    sl = S.size();
    hashed.resize(sl + 1, 0);
    power.resize(sl + 1);
    power[0] = 1;
    rep(i, sl){
      power[i+1] = (power[i] * base) % MOD;
      hashed[i+1] = (hashed[i] * base + S[i]) % MOD;
    }
  }

  ll getHash(ll l, ll r){//[l, r)
    ll res = ((hashed[r] - hashed[l] * power[r-l]) % MOD + MOD) % MOD;
    return res;
  }

  //使ったことない
  ll connect(ll hash1, ll hash2, ll hash2size){
    ll res = (hash1 * power[hash2size] + hash2) % MOD;
    return res;
  }
};

void solve(){
  string tmpS, S, T;
  cin >> tmpS >> T;
  while(S.size() < T.size()){
    S += tmpS;
  }
  S += S;
  S += S;
  vector<bool> ok(S.size(), 0);
  RollingHash RS, RT;
  RS.getS(S + S);
  RT.getS(T);
  ll hash_of_T = RT.getHash(0, T.size());
  rep(i, S.size()){
    if(RS.getHash(i, i+T.size()) == hash_of_T){
      ok[i] = 1;
    }
  }
