template<class T> auto type_list(undigraph<T> &g, int types = -1) {    int tn = types;    if (types == -1)tn = g.n;    rep(i, g.n) { forg2(gi, g[i]) { chma(tn, ty); }}    vector<vector<edge<T>>> res(tn + 1);    vi was(g.n);    rep(i, g.n) {        forg2(gi, g[i]) {            if (f < t)res[ty].push_back(g[i][gi]);            else if (f == t && !was[f]) {                res[ty].push_back(g[i][gi]);                was[f] = 1;            }        }    }    return res;}
