int kmp(string s, string p) {
    int n = s.length(), m = p.length();
    vector<int> table(m, 0); // ずらしテーブル
    {
        int j = 0;
        for(int i=1;i<m;++i) {
            table[i] = j;
            if(p[i] == p[j]) {
                ++j;
            } else {
                j = 0;
            }
        }
    }

    int i = 0, j = 0;
    vector<int> s_to_p(n, -1);
    while(i < n) {
        if(s_to_p[i] != m-1) s_to_p[i] = j;
        if(s[i] == p[j]) {
            if(j == m-1) {
                j = table[j];
            } else {
                ++i;
                ++j;
            }
        } else {
            if(j == 0) {
                ++i;
            } else {
                j = table[j];
            }
        }
    }

    int ret = 0, tmp_cnt = 0;
    j = 0;
    for(int j=0;j<m;++j) {
        for(int i=j;i<n;i+=m) {
            if(s_to_p[i] == m-1) {
                ++tmp_cnt;
            } else {
                ret = max(ret, tmp_cnt);
                tmp_cnt = 0;
            }
        }
        ret = max(ret, tmp_cnt);
        tmp_cnt = 0;
    }

    return ret;
}

int calc_period(string s, int n) {
    int s_period = INF;
    for(int i=1;i<=sqrt(n+1);++i) {
        if(n % i) continue;
        bool is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%i]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, i);
        }
        is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%(n/i)]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, n/i);
        }
    }
    return s_period;
}

bool is_inf(string s, string t, int n, int m) {
    int s_period = calc_period(s, n), t_period = calc_period(t, m);
    if(s_period == t_period) {
        bool are_same = true;
        for(int i=0;i<s_period;++i) {
            if(s[i] != t[i]) {
                are_same = false;
            }
        }
        if(are_same) return true;
    }
    return false;
}

