using namespace std;

string get(const string& S) {
	const int n = S.size();
	for (int i = 1; i < n; i++) if (n % i == 0) {
		bool ng = false;
		for (int j = 0; j < n; j++) if (S[j % i] != S[j]) {
			ng = true;
			break;
		}
		if (!ng) return S.substr(0, i);
	}
	return S;
}

vector<int> knuth_morris_pratt(const string& S) {
	int N = S.size();
	vector<int> A(N + 1);
	A[0] = -1;
	for (int i = 0, j = -1; i < N; i++) {
		while (j >= 0 && S[i] != S[j]) {
			j = A[j];
		}
		j++;
		A[i + 1] = (i + 1 == N ? '*' : S[i + 1]) == (j == N ? '*' : S[j]) ? A[j] : j;
	}
	return A;
}

vector<int> string_search(const string& S, const string& T) {
	auto A = knuth_morris_pratt(T);
	int N = T.size();
	vector<int> res;
	for (int i = 0, j = 0; i < (int)S.size(); i++) {
		while (j >= 0 && S[i] != T[j]) {
			j = A[j];
		}
		j++;
		if (j == N) {
			res.push_back(i + 1);
			j = A[j];
		}
	}
	return res;
}

bool comp(string s, string t) {
	if (s.size() != t.size()) return false;
	s += s;
	return !string_search(s, t).empty();
}

int calc(const string& s, const string& t) {
	auto ids = string_search(s, t);
	vector<int> dp(s.size() + 1);
	for (auto id : ids) {
		dp[id] = dp[id - t.size()] + 1;
	}
	return *max_element(dp.begin(), dp.end());
}

