VL Zalgo(const string &S) {
    int N = (int)S.size();
    VL res(N);
    res[0] = N;
    int i = 1, j = 0;
    while(i < N) {
        while(i + j < N && S[j] == S[i + j]) ++j;
        res[i] = j;
        if(j == 0) {
            ++i;
            continue;
        }
        int k = 1;
        while(i + k < N && k + res[k] < j) res[i + k] = res[k], ++k;
        i += k, j -= k;
    }
    return res;
}

VVL G;
VB used, nused;
set<ll> st;

bool dfs(ll now) {
    st.emplace(now);
    used[now] = true;
    bool res = true;
    FOREACH(to, G[now]) {
        if(res == false) break;
        if(st.find(to) != st.end()) return false;
        res &= dfs(to);
    }
    return res;
}

ll dfs2(ll now, ll par) {
    used[now] = true;
    ll res = 0;
    FOREACH(to, G[now]) {
        if(to == par || used[to]) continue;
        res = max(res, dfs2(to, now) + 1);
    }
    return res;
}

