int nibutan() { //めぐる式

	int ng = (s.size() + t.size() - 1) / t.size() + 1; //最大値ならs.size()
	int ok = 0; // 最大値なら0

	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;

		if (solve(mid)) ok = mid;
		else ng = mid;
	}
	return ok; //満たさない最大ならng
}

