const LL LINF = 1LL<<60;
const int IINF = 1<<30;
const LL MOD = 1e9+7;

struct RollingHash {
    const int base = 9973;
    const vector<int> mod = {999999937LL, 1000000007LL};
    vector<int> S;
    vector<long long> hash[2], power[2];

    // construct
    RollingHash(){}
    RollingHash(const vector<int> &cs) { init(cs); }
    void init(const vector<int> &cs) {
        S = cs;
        int n = (int)S.size();
        for (int iter = 0; iter < 2; ++iter) {
            hash[iter].assign(n+1, 0);
            power[iter].assign(n+1, 1);
            for (int i = 0; i < n; ++i) {
                hash[iter][i+1] = (hash[iter][i] * base + S[i]) % mod[iter];
                power[iter][i+1] = power[iter][i] * base % mod[iter];
            }
        }
    }
    // get hash of S[left:right]
    inline long long get(int l, int r, int id = 0) const {
        long long res = hash[id][r] - hash[id][l] * power[id][r-l] % mod[id];
        if (res < 0) res += mod[id];
        return res;
    }
    // get lcp of S[a:] and S[b:]
    inline int getLCP(int a, int b) const {
        int len = min((int)S.size()-a, (int)S.size()-b);
        int low = -1, high = len + 1;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (get(a, a+mid, 0) != get(b, b+mid, 0)) high = mid;
            else if (get(a, a+mid, 1) != get(b, b+mid, 1)) high = mid;
            else low = mid;
        }
        return low;
    }
    // get lcp of S[a:] and T[b:]
    inline int getLCP(const RollingHash &t, int a, int b) const {
        int len = min((int)S.size()-a, (int)S.size()-b);
        int low = -1, high = len + 1;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (get(a, a+mid, 0) != t.get(b, b+mid, 0)) high = mid;
            else if (get(a, a+mid, 1) != t.get(b, b+mid, 1)) high = mid;
            else low = mid;
        }
        return low;
    }
};

int main()
{
    string s, t; cin >> s >> t;

    int n = s.size(), m = t.size();

    while (s.size() < 2 * t.size()) {
        s += s;
    }

    vector<int> S(s.size()), T(t.size());
    for (int i = 0; i < s.size(); ++i) {
        S[i] = s[i] - 'a';
    }
    for (int i = 0; i < t.size(); ++i) {
        T[i] = t[i] - 'a';
    }

    auto rs = RollingHash(S);
    auto rt = RollingHash(T);

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int cnt = 0;
        if (rs.get(i, i+m) == rt.get(0, m)) ++cnt;

        int id = (i+m) % n;
        for (; id != i; (id += m) %= n) {
            if (rs.get(id, id+m) != rt.get(0, m)) break;
            ++cnt;
        }

        if (id == i) {
            ans = -1;
            break;
        }
        chmax(ans, cnt);
    }

    cout << ans << endl;

