void createTable() {
    table[0] = 0;
    int j = 0;
    for (int i = 1; i < pattern.length(); ++i) {
        if (pattern[i] == pattern[j]) {
            table[i] = j++;
        } else {
            table[i] = j;
            j = 0;
        }
    }
    for (int i = 1; i < pattern.length(); ++i) {
        //pattern[i:n]==pattern[0:n-i]?
        bool flag = false;
        for (int j = pattern.length() - 1; j >= i; --j) {
            if (pattern[j] != pattern[j - i]) {
                flag = true;
                break;
            }
        }
        if (flag)continue;
        table[pattern.length()] = pattern.length() - 1 - i;
        return;
    }
    table[pattern.length()] = pattern.length() - 2;
}

int Gcd(int a, int b) {
    if (b == 0)return a;
    return Gcd(b, a % b);
}

signed main() {
