    createTable();
    int i = 0, p = 0;
    while (i - (int) pattern.length() < (int) target.length()) {
        if (target[i % target.length()] == pattern[p]) {
            i++;
            p++;
        } else if (p == 0) {
            //パターン先頭文字が不一致
            i++;
        } else {
            p = table[p];
        }
        if (p == pattern.length()) {
            match[i - p] = true;
            p = table[p] + 1;
        }
    }

    int ans = 0;
    int gcd = Gcd(pattern.length(), target.length());

    for (int start = 0; start < gcd; ++start) {
