using namespace std;
vector<int> kmp(string text, string word)
{
    // make table
    vector<int> table(word.length() + 1);

    table[0] = -1;

    for (int i = 0, j = -1; i < word.length(); i++)
    {
        while (j >= 0 && word[i] != word[j])
        {
            j = table[j];
        }
        table[i + 1] = ++j;
    }
    // search word from text
    vector<int> ret;
    int m = 0, i = 0;

    while (m + i < text.length())
    {
        if (word[i] == text[m + i])
        {
            if (++i == (int)(word.size()))
            {
                ret.push_back(m);
                m = m + i - table[i];
                i = table[i];
            }
        }
        else
        {
            m = m + i - table[i];
            if (i > 0)
                i = table[i];
        }
    }
    return ret;
}
