void Z(int siz){
   z[1] = siz;
   int mx,R; R = mx = 0;
   for(int i = 2;i <= siz; ++i){
      z[i] = (i < R)?min(R-i,z[i-mx+1]):0;
      while(i-1+z[i] < siz && Lt[i-1+z[i]] == Lt[z[i]])++z[i];
      if(i+z[i] > R)R = i+z[i]-1,mx = i;
   }
}

