using namespace std;
const int maxd =1e6+10;
struct
{
    int v,net;
}e[maxd<<1];
int f[maxd],eid,in[maxd];
void insert(int u,int v)
{
    e[eid].v =v;
    e[eid].net = f[u];
    f[u] = eid++;
}
void init()
{
    memset(f,-1,sizeof(f));
    eid = 0;
}
int fail[maxd],pos[maxd],vis[maxd];
char str[maxd],p[maxd];// 文本串，匹配串
int lena,lenb,n,m,sum;
void getfail()
{
    fail[1] = 0;
    int match = 0;
    for(int i=2;p[i];i++)
    {
        while(match&& p[match+1] != p[i])
            match = fail[match];
        if(p[match+1] == p[i]) match++;
        fail[i] = match;
    }
}
int dp[maxd],ans = 0;

void kmp()
{
    int match = 0;
    for(int i=1;str[i];i++)
    {
        while(match&&p[match+1] != str[i])
            match = fail[match];
        if(p[match+1] == str[i])  match++;
        if(match == lenb && i-lenb+1 <= n)
        {
            pos[i-lenb+1] = 1;
            match = fail[match];
            ++sum;
        }
    }
}
void topsort()
{
    queue<int> que;
    for(int i=1;i<=n;i++) if(vis[i] && in[i] == 0) 
    {
        que.push(i);
        dp[i]=1;ans = max(dp[i],ans); 
    }
    while(!que.empty())
    {
        int x = que.front();que.pop();
        for(int i=f[x];i+1;i=e[i].net)
        {
            int v = e[i].v;
            in[v]--;
            dp[v] = max(dp[x]+1,dp[v]);
            ans = max(dp[v],ans); 
            if(!in[v]) que.push(v);
        }
    }
    for(int i=1;i<=n;i++) if(in[i])
    {
        printf("-1");
        return;
    }
    printf("%d",ans);
}
int main()
{
    // freopen("a.in","r",stdin);
    // freopen("k.out","w",stdout);
    init();
    scanf("%s %s",str+1,p+1);
    n = lena = strlen(str+1);
    m = lenb = strlen(p+1);
    while(m > 0)
    {
        for(int i=1;i<=n;i++)
            str[++lena] = str[i];
        m -= n;
    }
    getfail();
    kmp();
    for(int i=1;i<=n;i++)
    {
        int k = (i+lenb)% n;
        if(!k) k = n;
        if(pos[i] && pos[k])
        {
            //printf("%d %d\n",i,k);
            insert(i,k);
            vis[i] = vis[k]=1;
            in[k]++;
        }
    }
    topsort();
    return 0;
}

