const int N = 2e6;

int go(string s){
	int m = sz(s);
	int pi[sz(s)*3+5]={0};
	s = s + '#' + s + s;
	int k = 0;
	int n = sz(s);
	rep(i,1,n){
		while(k && s[i]!=s[k]) k = pi[k-1];
		if(s[i]==s[k]) k++;
		if(k==m && i>2*m) return i-2*m;
		pi[i]=k;
	}
}

bool inf(string s, string t){
	int n = go(s);
	int m = go(t);
	if(n==m){
		rep(i,0,n) 
			if(s[i]!=t[i]) return 0;
		return 1;
	}else return 0;
}

