        i_i now = que.front();
        //cerr << now.first << " " << now.second << " " << dp[now.first][now.second] << endl;
        que.pop();
        if(now.first == 0) {
            if(now.second >= t.size()) {
                if(chmin(dp[0][now.second - t.size()], dp[0][now.second] + 1)) {
                    que.push({0, now.second - t.size()});
                }
                continue;
            } else {
                if(chmin(dp[1][t.size() - now.second], dp[0][now.second])) {
                    que.push({1, t.size() - now.second});
                }
            }
        }
        if(now.first == 1) {
            if(now.second > s.size()) {
                if(chmin(dp[1][now.second - s.size()], dp[1][now.second])) {
                    que.push({1, now.second - s.size()});
                }
                continue;
            } else {
                if(chmin(dp[0][s.size() - now.second], dp[1][now.second] + 1)) {
                    chmax(dp[0][s.size() - now.second], (ll)0);
                    que.push({0, s.size() - now.second});
                }
            }
        }
    }
    ll ans = 0;
    for(int i = 0; i < s.size(); i++) {
        chmax(ans, dp[0][i]);
    }
    if(ans == INF) ans = -1;
    cout << ans << endl;
    return 0;
}

