#include <bits/stdc++.h>

using namespace std;

vector<int> lps;

vector<int> kmp_lps(const string &s)
{
	vector<int> lps(s.size());
	for (int i = 1, j = 0; i < s.size(); )
		if (s[i] == s[j]) lps[i++] = ++j;
		else if (j > 0) j = lps[j - 1];
		else lps[i++] = 0;
	return lps;
}

int kmp_find(const string &s, const string &p, int start = 0)
{
	int n = s.size(), m = p.size();
	for (int i = start, j = 0; i < n; ) {
		while (i < n && j < m && s[i] == p[j]) i++, j++;
		if (j == m) return i - j;
		if (i < n && s[i] != p[j]) {
			if (j > 0) j = lps[j - 1];
			else i++;
		}
	}
	return -1;
}

int find(const string &s, const string &t)
{
	int n = s.size(), m = t.size();
	vector<int> a(n + 1);
	for (int i = 0, p; i < n; ) {
		if ((p = kmp_find(s, t, i)) < 0) break;
		a[p + m] = a[p] + 1;
		i = p + 1;
	}
	return *max_element(a.begin(), a.end());
}

