void get_z_function(const string &s, int z[]) {
    z[0] = 0;
    int l = 0, r = 0;
    for (int i = 1; i < s.length(); ++i) {
        z[i] = 0;
        if (i <= r) {
            z[i] = min(z[i - l], r - i + 1);
        }
        while (i + z[i] < s.length() && s[i + z[i]] == s[z[i]]) {
            ++z[i];
        }
        if (i + z[i] - 1 > r) {
            r = i + z[i] - 1;
            l = i;
        }
    }
}

int nxt[max_n], used[max_n], dp[max_n];

int dfs(int v) {
    if (v == -1 || nxt[v] == -1) {
        return 0;
    }
    if (used[v]) {
        return dp[v];
    }
    used[v] = 1;
    if (used[nxt[v]] == 1) {
        puts("-1");
        exit(0);
    }
    dp[v] = dfs(nxt[v]) + 1;
    used[v] = 2;
    return dp[v];
}

