vector<ll> prefix_function(string s) {
    ll n = (ll)s.length();
    vector<ll> pi(n);
    for (ll i = 1; i < n; i++) {
        ll j = pi[i-1];
        while (j > 0 && s[i] != s[j])
            j = pi[j-1];
        if (s[i] == s[j])
            j++;
        pi[i] = j;
    }
    return pi;
}

vector<ll> adj[MAX];
ll visited[MAX];

bool is_cycle(ll start){
	if(visited[start]==1) return 1;
	visited[start] = 1;
	for(ll x:adj[start]) if(visited[x]!=2){
		if(is_cycle(x)) return 1;
	}
	visited[start] = 2;	
	return 0;
}

ll dp[MAX];

ll f(ll s){
	if(dp[s]!=-1) return dp[s];
	ll ans = 0;
	for(ll x:adj[s]){
		ll t = f(x)+1;
		ans = max(ans,t);
	}
	dp[s] = ans;
	return ans;
}

