#define all(x) (x).begin(), (x).end()
#define reveal(x) cerr << #x << " = " << (x) << endl
#define rep(it, f, e) for (rint it = (f); it <= (e); ++it)
#define per(it, f, e) for (rint it = (f); it >= (e); --it)
#define repe(it, x) for (auto it = (x).begin(); it != (x).end(); ++it)
const int MAXN = 2e6 + 20;
string s, t, T;
int fail[MAXN];
ulint Hash[2][MAXN], mul[MAXN];
inline void DoHash(ulint HHH[], string & SSS) {
	#define s SSS
	#define Hash HHH
	Hash[0] = s[0] - 'a' + 1;
	rep (i, 1, SZ(s) - 1) {
		if (i) Hash[i] = Hash[i - 1] * 232323 + s[i] - 'a' + 1;
	}
	#undef s
	#undef Hash
}
inline ulint getHash(ulint HHH[], int l, int r) {
	if (!l) return HHH[r];
	return HHH[r] - HHH[l - 1] * mul[r - l + 1];
}
inline bool checkINF() {
	int j = fail[0] = -1;
	rep (i, 1, SZ(s) - 1) {
		while (~j && s[i - 1] != s[j]) j = fail[j];
		fail[i] = ++j;
	}
	int now = 0, flag = 0;
	rep (i, 0, SZ(t) - 1) {
		if (t[i] != s[now] && flag == -1) return false;
		while (~now && t[i] != s[now]) now = fail[now];
		if (++now == SZ(s)) flag = -1, now = 0;
	}
	if (~flag) return false;
	return true;
}
inline bool check(int mid) {
	int l = SZ(s) * mid;
	ulint use = 0;
	rep (i, 1, mid) {
		use = use * mul[SZ(s)] + getHash(Hash[1], 0, SZ(s) - 1);
	}
	rep (i, 0, SZ(t)) {
		if (i + l > SZ(t)) return false;
		if (getHash(Hash[0], i, i + l - 1) == use) return true;
	}
	return false;
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(NULL), cout.tie(NULL);
	cin >> T >> s;
	while (SZ(t) < SZ(s)) t += T; t += t;
	mul[0] = 1;
	rep (i, 1, MAXN - 1) {
		mul[i] = mul[i - 1] * 232323;
	}
	DoHash(Hash[0], t);
	DoHash(Hash[1], s);
	int l = 1, r = SZ(t) / SZ(s);
	while (l <= r) {
		int mid = (l + r) >> 1;
		if (check(mid)) l = mid + 1;
		else r = mid - 1;
	}
	if (l == SZ(t) / SZ(s) + 1) {
		cout << -1 << endl;
		return 0;
	}
	cout << l - 1 << endl;
	return 0;
}

