        while (i0 < i1) {
            int i = q[i0++];
            for (int j = v[i].n; j >= 0; j = e[j].n) {
                Edge &o = e[j];
                if (--v[o.i].k == 0) q[i1++] = o.i, v[o.i].d = v[i].d + 1;
            }
        }
        if (i1 < n) {
            cout << -1 << endl;
        } else {
            cout << v[q.back()].d << endl;
        }
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

