struct RollingHash{
	using mllA = mll_<1000000007LL>;
	using mllB = mll_<998244353LL>;
	using Hash = pll;
	ll b, N;
	vector<Hash> cum, pw;
	RollingHash(): b(0), N(0){}
	RollingHash(string &s, ll base=1000003) { Init(s, base); }

	void Init(string &s, ll base=1000003){
		b=base;
		N=(ll)s.size();
		cum.resize(N+1);
		pw.resize(N+1, Hash(1, 1));
		mllA pA=1;  mllB pB=1;
		mllA hA=0;  mllB hB=0;
		REP(i, N){
			pA *= b;     pB *= b;
			hA *= b;     hB *= b;
			hA += s[i];  hB += s[i];
			pw [i+1] = Hash(pA.val, pB.val);
			cum[i+1] = Hash(hA.val, hB.val);
		}
	}
	Hash operator () (ll l, ll r) const {
		mllA hA; mllB hB; tie(hA, hB) = cum[r+1];
		mllA iA; mllB iB; tie(iA, iB) = cum[l];
		mllA pA; mllB pB; tie(pA, pB) = pw [r-l+1];
		iA*=pA;  iB*=pB;
		return Hash((hA-iA).val, (hB-iB).val);
	}
	vll Search(string &t){
		vll ret;
		ll M = (ll)t.size();
		Hash hash_t = RollingHash(t,b)(0, M-1);
		REP(i,N-M+1) if((*this)(i,i+M-1)==hash_t) ret.push_back(i);
		return move(ret);
	}
};

