/**
 * https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
 * 文字列検索
 */
class KMP {
 private:
  string needle;
  vector<ll> kmp;

 public:
  explicit KMP(const string &needle) : needle(needle), kmp(needle.size() + 2, 0) {
    kmp[0] = -1;
    kmp[1] = 0;
    {
      ll i = 2;
      ll j = 0;
      while (i < needle.size()) {
        if (needle[i - 1] == needle[j]) {
          kmp[i++] = ++j;
        } else if (j > 0) {
          j = kmp[j];
        } else {
          kmp[i++] = 0;
        }
      }
    }
  }

  vector<ll> search(const string &haystack) {
    vector<ll> ret(haystack.size(), false);

    ll m = 0;
    ll i = 0;
    while (m + i < haystack.size()) {
      if (needle[i] == haystack[m + i]) {
        i++;
        if (i == needle.size()) {
          ret[m] = true;
          m += i - kmp[i - 1] - 1;
          if (i >= 0) {
            i = max(0ll, kmp[i - 1]);
          }
        }
      } else {
        m += i - kmp[i];
        if (i > 0) {
          i = kmp[i];
        }
      }
    }
    return ret;
  }

};

ll solve() {

  string s, t;
  cin >> s >> t;

  ll ls, lt;
  ls = s.size();
  lt = t.size();

  do {
    s += s;
  } while (s.size() < t.size() * 3);

  ll ret = 0;
  KMP kmp = KMP(t);
  vector<ll> matches = kmp.search(s);
  vector<bool> seen(ls, false);

  ll i = -1;
  while (++i < ls) {
    while (i < matches.size() && !matches[i]) i++;
    if (i > ls) break;
    if (seen[i]) continue;

    ll j = 0;
    while (matches[i + j * lt]) {
      if (i + j * lt < ls) seen[i + j * lt] = true;
      if (j * lt >= ls) return -1;
      j += 1;
    }
    ret = max(ret, j);
  }
  return ret;
}

