// Z algorithm O(|S|)
vector<int> Z_algorithm(string s) {
  vector<int> Z(s.size());
  Z[0] = s.size();

  int i = 1, j = 0;
  while (i < s.size()) {
    while (i + j < s.size() && s[j] == s[i + j]) j++;
    Z[i] = j;
    if (j == 0) {
      i++;
      continue;
    }
    int k = 1;
    while (k < j && k + Z[k] < j) {
      Z[i + k] = Z[k];
      k++;
    }
    i += k;
    j -= k;
  }
  return Z;
}

// sのi文字目以降とtが何文字一致しているか
vector<int> cor_length(string s, string t) {
  vector<int> cor(s.size());
  vector<int> Z = Z_algorithm(t + s);
  for (int i = 0; i < s.size(); i++) {
    cor[i] = min((int) Z[i + t.size()], (int) t.size());
  }
  return cor;
}

// 隣接リストを用いた深さ優先探索（再帰ver.） O(|V|+|E|)
bool cycle = false;
vector<int> color(1e6, 0), d;

void dfs(const vector<vector<int>> &G, int u) {
  color[u] = 1; // GRAY
  int dist = 0;
  for (int i = 0; i < G[u].size(); i++) {
    if (color[G[u][i]] == 0) {
      dfs(G, G[u][i]);
      dist = d[G[u][i]] + 1;
    }
    else if (color[G[u][i]] == 1) {
      cycle = true;
      return;
    }
    else {
      dist = d[G[u][i]] + 1;
    }
  }
  color[u] = 2; // BLACK
  d[u] = dist;
  return;
}

