  for (int i = 0; i < tmp.size(); i++) {
    if (cor[i] >= t.size()) G[i].emplace_back((i + t.size()) % tmp.size());
  }

  d.assign(tmp.size(), -1);
  for (int i = 0; i < tmp.size(); i++) {
    if (d[i] == -1) dfs(G, i);
  }

  if (cycle) {
    cout << -1 << '\n';
  }
  else {
    int ans = 0;
    for (int i = 0; i < tmp.size(); i++) ans = max(ans, d[i]);
