    Int j=i+len;
    // [i, j)
    // = [i, n) + [0, n) * k + [0, j % n)
    Int k=(len-(n-i))/n;
    auto G=A.pow(k);
    M res=G[0][0]*M(hs.find(i,n))+G[0][1]*M(hs.find(0,n));
    res*=M(hs.p[j%n]);
    res+=M(hs.find(0,j%n));
    //cout<<x<<" "<<i<<":"<<res<<" "<<val<<endl;
    if(res==val) return 1;
  }

  return 0;
}

