class RollingHash {
public:
    vector<long long> hs[2], pw[2];
    const long long base = 9973;
    const long long mod[2] = {1000000007LL, 999999937LL};
    int len = 0;
    RollingHash(const string &s) {
        len = s.size();
        for(int i = 0; i < 2; ++i) {
            hs[i].assign(len + 1, 0);
            pw[i].assign(len + 1, 1);
            for (int j = 0; j < len; ++j) {
                pw[i][j + 1] = pw[i][j] * base % mod[i];
                hs[i][j + 1] = (hs[i][j] * base + s[j]) % mod[i];
            }
        }
    }
    void connect(const string &s) {
        int n = s.size();
        for(int i = 0; i < 2; ++i) {
            hs[i].resize(len + n + 1);
            pw[i].resize(len + n + 1);
            for (int j = len; j < len + n; ++j) {
                pw[i][j + 1] = pw[i][j] * base % mod[i];
                hs[i][j + 1] = (hs[i][j] * base + s[j - len]) % mod[i];
            }
        }
        len += n;
    }
    pair<long long, long long> hash(const int l, const int r) {
        long long t1 = ((hs[0][r] - hs[0][l] * pw[0][r - l]) % mod[0] + mod[0]) % mod[0];
        long long t2 = ((hs[1][r] - hs[1][l] * pw[1][r - l]) % mod[1] + mod[1]) % mod[1];
        return make_pair(t1, t2);
    }
};

int main() {
    string s, t;
    cin >> s >> t;
    RollingHash rhs(s), rht(t);
    while(rhs.len <= 7777777) rhs.connect(s);
    using P = pair<long, long>;
    int ans = 0;
    for(int i = 0; i + rht.len < rhs.len; ++i) {
        while(i + rht.len < rhs.len && rhs.hash(i, i + rht.len) != rht.hash(0, rht.len)) i++;
        int cnt = 0;
        while(i + rht.len < rhs.len && rhs.hash(i, i + rht.len) == rht.hash(0, rht.len)) {
            i += rht.len;
            cnt++;
        }
        ans = max(ans, cnt);
    }
    if(ans * t.size() >= 3 * s.size()) ans = -1;
    cout << ans << endl;
    return 0;
}

