const int MAXN = 1000*1000+5;
const int mod = 1000*1000*1000+7;
const int p = 31;

vector<int> g[MAXN], topo;
int color[MAXN], p31[MAXN], p_inv[MAXN], h[MAXN];

int mul(int a, int b) { return 1LL * a * b % mod; }
int mpow(int a, int n) {
	if(n == 0) return 1;
	int x = mpow(a, n/2);
	x = mul(x, x);
	if(n % 2) x = mul(x, a);
	return x;
}

void fix(int& a) {
	while(a >= mod) a -= mod;
	while(a < 0) a += mod;
}

int add(int a, int b) {
	fix(a), fix(b);
	a += b;
	fix(a);
	return a;
}

int sub(int a, int b) {
	fix(a), fix(b);
	a -= b;
	fix(a);
	return a;
}

int hash_s(int i, int j) {
	int L = i == 0 ? 0 : h[i-1];
	return mul(p_inv[i], sub(h[j], L));
}

bool dfs(int u) {
	color[u] = 1;
	for(int v : g[u]) {
		if(color[v] == 1) {
			return false;
		} else if(color[v] == 0 && !dfs(v)) {
			return false;
		}

	}
	color[u] = 2;
	topo.push_back(u);
	return true;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	p31[0] = p_inv[0] = 1;
	for(int i = 1; i < MAXN; i++) {
		p31[i] = mul(p, p31[i-1]);
		p_inv[i] = mpow(p31[i], mod-2);
	}

	string s, t;
	cin >> s >> t;
	int old_length = s.length();
	int n = s.length(), m = t.length();
	while((int) s.length() < n+m) {
		s += s;
	}
	n = s.length();
	for(int i = 0; i < n; i++) {
		int L = i == 0 ? 0 : h[i-1];
		h[i] = add(L, mul(p31[i], s[i]-'a'+1));
	}

	int hash_t = 0;
	for(int i = 0; i < m; i++) {
		hash_t = add(hash_t, mul(p31[i], t[i]-'a'+1));
	}

	for(int i = 0; i <= n-m; i++) {
		if(hash_s(i, i+m-1) == hash_t) {
			g[i % old_length].push_back((i+m) % old_length);
		}
	}

	for(int i = 0; i < old_length; i++) {
		if(color[i] == 0 && !dfs(i)) {
			cout << -1 << endl;
			exit(0);
		}
	}

	int ans = 0;
	vector<int> dp(old_length);

	for(int u : topo) {
		for(int v : g[u]) {
			dp[u] = max(dp[u], 1+dp[v]);
		}
		ans = max(ans, dp[u]);
	}

	cout << ans << endl;

}

