V<ll> same_idx(const string &S, const string &T) {
    V<ll> max_prefix(S.size());
    string SS = S;
    while(SS.size() < T.size() + S.size()) SS += S;
    for(; max_prefix[0] < T.size() && SS[max_prefix[0]] == T[max_prefix[0]]; max_prefix[0]++);
    ll cur_max_idx = 1;
    for(ll i = 1; i < S.size(); i++) {
        if(max_prefix[cur_max_idx] < T.size() && max_prefix[i - cur_max_idx] < max_prefix[cur_max_idx] - (i - cur_max_idx)) {
            max_prefix[i] = max_prefix[i - cur_max_idx];
        } else {
            ll j = max<ll>(0, max_prefix[cur_max_idx] - (i - cur_max_idx));
            for(; i + j < SS.size() && j < T.size() && SS[i + j] == T[j]; j++);
            max_prefix[i] = j;
            cur_max_idx = i;
        }
    }
    DEBUG(max_prefix);
    V<ll> ret;
    for(ll i = 0; i < S.size(); i++) if(max_prefix[i] == T.size()) ret.push_back(i);
    return ret;
}

