{
    cin.tie(0);
    ios::sync_with_stdio(false);

    string s, t;
    cin >> s >> t;
    string u = s;
    int n = s.size(), m = t.size();
    while ((int)u.size() < n + m)
    {
        u += s;
    }
    vector<vector<int>> g(n);
    Scc scc(n);
    string w = t + "$" + u;
    auto z = z_algorithm(w);
    TopologicalSort ts(n);
    for (int i = 0; i < n; i++)
    {
        int index = m + 1 + i;
        if (z[index] >= m)
        {
            if (i == (i + m) % n)
            {
                cout << -1 << endl;
                return 0;
            }
            g[i].push_back((i + m) % n);
            ts.addEdge(i, (i + m) % n);
            scc.add_edge(i, (i + m) % n);
        }
    }
    if (scc.scc() != n)
    {
        cout << -1 << endl;
        return 0;
    }
    auto topo = ts.topologicalSort();
    if (topo.size() != n)
    {
        cout << -1 << endl;
        return 0;
    }
    vector<int> ret(n, 0);
    int ans = 0;
