void concat(string& to, string s) {
    for (char c: s) to += c;
}


string unit(string s) {
    int n = s.length();
    int len = n;

    auto strstr = [&](int m, string s) {
	int n = s.length();
	if (n%m) return false;
	for (int i=0; i<n; i++) {
	    if (s[i] != s[i%m]) return false;
	}
	return true;
    };

    for (int i=1; i*i<=n; i++) {
	if (n%i==0) {
	    if (strstr(i, s)) {
		len = min(len, i);
	    }
	    if (i>1 && n/i!=i && strstr(n/i, s)) {
		len = min(len, n/i);
	    }
	}
    }

    return s.substr(0,len);
}

bool contained(string s, string t) {
    s = unit(s);
    t = unit(t);
    int n = s.length();
    int m = t.length();
    if (n%m) return false;

    for (int i=0; i<n; i++) {
	if (s[i] != t[i%m]) return false;
    }
    return true;
}


