    public:
        int par[N_MAX];
        int siz[N_MAX];

        UF(int n) {
            for(int i = 0;i <= n;i++) {
                par[i] = i;
                siz[i] = 1;
            }
        }

        int root(int x) {
            return x == par[x] ? x : par[x] = root(par[x]);
        }

        int same(int x,int y) {
            return root(x) == root(y);
        }

        void merge(int x,int y) {
            x = root(x);
            y = root(y);
            if(x == y)
                return;
            par[x] = y;
            siz[y] += siz[x];

            return;
        }
        int size(int x) {
            return siz[root(x)];
        }
};

