    string S = s;
    while((int)S.size() <= m * 2){
        S += s;
    }

    auto v = kmp(S, t);

    vector<bool> sindex(n, false);
    for(auto i : v){
        sindex[i % n] = true; 
    }

    int ans = 0;
    set<int> used_index;
    for(int i=0; i<n; i++){
        int sum = 0;
        if(sindex[i]){
            sindex[i] = false;
            used_index.emplace(i);
            sum++;
            int nxt = (i + m) % n;

            if(used_index.find(nxt) != used_index.end()){
                cout << -1 << endl;
                return 0;
            }

            while(sindex[nxt]){
                sindex[nxt] = false;
                used_index.emplace(nxt);
                sum++;
                nxt = (nxt + m) % n;

                if(used_index.find(nxt) != used_index.end()){
                    cout << -1 << endl;
                    return 0;
                }
            }

            int pre = (i - m + (int)S.size()) % n;

            if(used_index.find(pre) != used_index.end()){
                cout << -1 << endl;
                return 0;
            }

            while(sindex[pre]){
                sindex[pre] = false;
                used_index.emplace(pre);
                sum++;
                pre = (pre - m + (int)S.size()) % n;

                if(used_index.find(pre) != used_index.end()){
                    cout << -1 << endl;
                    return 0;
                }
            }

            chmax(ans, sum);
        }
    }

    cout << ans << endl;
