using namespace std;

vector<bool> kmp(string& pattern, string& text) {
  vector<int> kmp_next(pattern.size()+1);
  kmp_next[0] = -1;
  for (int i = 0, j = -1; i < pattern.size(); ) {
    while (j >= 0 && pattern[i] != pattern[j])
      j = kmp_next[j];
    i++; j++;
    if (i < pattern.size() && pattern[i] == pattern[j])
      kmp_next[i] = kmp_next[j];
    else
      kmp_next[i] = j;
  }
  vector<bool> matches(text.size(), false);
  for (int i = 0, j = 0; j < text.size(); ) {
    while (i >= 0 && pattern[i] != text[j])
      i = kmp_next[i];
    i++; j++;
    if (i == pattern.size()) {
      matches[j - i] = true;
      i = kmp_next[i];
    }
  }
  return matches;
};

int main() {
    string s, t; cin >> s >> t;
    const int n = s.size();
    while (s.size() < 2 * t.size()) s += s;
    vector<bool> matches = kmp(t, s);
    vector<int> dp(n, -1);
    function<void(int, int)> dfs = [&](int i, int l) {
      if (l > n) { cout << "-1\n"; exit(0); }
      if (matches[i]) {
        const int j = (i + t.size()) % n;
        dfs(j, l+1);
        dp[i] = 1 + dp[j];
      } else
        dp[i] = 0;
    };
    for (int i = 0; i < n; i++) {
      if (dp[i] == -1) dfs(i, 0);
    }
    cout << *max_element(dp.begin(), dp.end()) << endl;
}

