vec d;
ll dfs (ll v, ll start) {
    if (d[v] != -1) return d[v];
    if (graph[v].size() == 0) {
        d[v] = 0;
        return 0;
    }
    if (graph[v][0] == start) {
        cout << -1 << "\n";
        exit(0);
    }
    d[v] = dfs(graph[v][0], start) + 1;
    return d[v];
}

