bool prefix_function(const string &s,const string &t) {
    ///search t on s
    int m=(int)t.length();
    string ss=t+'#'+s;
    int n = (int)ss.length();
    pi[0]=0;
    for (int i = 1; i < n; i++) {
        int j = pi[i-1];
        while (j > 0 && ss[i] != ss[j])
            j = pi[j-1];
        if (ss[i] == ss[j])
            j++;
        pi[i] = j;
        if(pi[i]==m&&i>m){
            return true;
        }
    }
    return false;
}
