void z_algorithm(string s, int *z) {
    int n = s.length(), k = 0;
    for(int i=1;i<n;++i) {
        if(i + z[i-k] < k + z[k]) {
            z[i] = z[i-k];
        } else {
            int j = max(0, k + z[k] - i);
            while(i + j < n && s[i+j] == s[j]) ++j;
            z[i] = j;
            k = i;
        }
    }
    z[0] = n;
}

