vector<int>Z(string s){
	vector<int>z(s.size());
	z[0]=s.size();
	int i=1,j=0;
	while(i<s.size()){
		while(i+j<s.size()&&s[j]==s[i+j])j++;
		if(j==0){
			z[i]=0;i++;continue;
		}
		z[i]=j;
		int k=1;
		while(i+k<s.size()&&k+z[k]<z[i]){
			z[i+k]=z[k];
			k++;
		}
		i+=k;
		j-=k;
	}
	return z;
}

