bool rolling_hash_contain(string a, string b)
{
	static const unsigned long long B = 1e9 + 7;

	int al = a.size(), bl = b.size();
	if (al > bl)return false;

	unsigned long long t = 1;
	for (int i = 0; i < al; i++)t *= B;

	unsigned long long ah = 0, bh = 0;
	for (int i = 0; i < al; i++)ah = ah * B + a[i];
	for (int i = 0; i < al; i++)bh = bh * B + b[i];

	for (int i = 0; i + al <= bl; i++)
	{
		if (ah == bh)return true;
		if (i + al < bl)bh = bh * B + b[i + al] - b[i] * t;
	}
	return false;
}

//b > a 
int rolling_hash_count(string a, string b)
{
	//cout << a << endl << b << endl;
	unsigned long long base[2] = { 9973,9973 };
	unsigned long long mod[2] = { 1000000007,1000000009 };


	int al = a.size(), bl = b.size();
	if (al > bl)return false;

	unsigned long long t[2];
	unsigned long long ah[2] = { 0 }, bh[2] = { 0 };
	t[0] = t[1] = 1;

	for (int i = 0; i < al; i++)
	{
		for (int j = 0; j < 2; j++)
		{
			ah[j] = (ah[j] * base[j] + a[i]) % mod[j];
			bh[j] = (bh[j] * base[j] + b[i]) % mod[j];
			t[j] = (t[j] * base[j]) % mod[j];
		}
	}

	int res = 0;
	int ans = 0;
	for (int i = 0; i + al <= bl;)
	{
		if (ah[0] == bh[0] && ah[1] == bh[1])
		{
			res++;
			for (int j = 0; j < al; j++)
			{
				if (i + al + j < bl)
				{
					for (int k = 0; k < 2; k++)
					{
						bh[k] = (bh[k] * base[k] + b[i + al + j] - b[i + j] * t[k]) % mod[k];
					}
				}
			}
			i += al;
		}
		else
		{
			res = 0;
			if (i + al < bl)
			{
				for (int k = 0; k < 2; k++)
				{
					bh[k] = (bh[k] * base[k] + b[i + al] - b[i] * t[k]) % mod[k];
				}
			}
			i++;
		}
		ans = max(ans, res);
	}
	return ans;
}

