struct rolling_hash{
    using u64 = std::uint_fast64_t;
    class hash_string{
        u64 base=10007,mod_num=3;
        vector<u64> mod={1000000007,999999937,998244353};
        public:
        u64 digit;
        vector<u64> hash;
        hash_string(){digit=0;hash.resize(mod_num,0);}
        hash_string(u64 digit,vector<u64> hash):digit(digit),hash(hash){}
        hash_string operator +(char c){
            vector<u64>hashTable(mod_num);
            rep(i,mod_num)hashTable[i]=(hash[i]*base+c)%mod[i];
            return hash_string(digit+1,hashTable);
        }
        hash_string operator +(hash_string s){
            vector<u64>hashTable(mod_num);
            rep(i,mod_num)hashTable[i]=(hash[i]*mod_pow(base,s.digit,mod[i])+s.hash[i])%mod[i];
            return hash_string(digit+s.digit,hashTable);
        }
        hash_string operator -(hash_string s){
            vector<u64>hashTable(mod_num);
            rep(i,mod_num)hashTable[i]=(hash[i]+mod[i]-(s.hash[i]*mod_pow(base,digit-s.digit,mod[i]))%mod[i])%mod[i];
            return hash_string(digit-s.digit,hashTable);
        }
        hash_string operator *(u64 num){
            if(num==0)return hash_string();
            if(num==1)return *this;
            if(num%2==0){
                auto tmp=(*this)*(num/2);
                return tmp+tmp;
            }else{
                return (*this)*(num-1)+(*this);
            }
        }
        bool operator ==(hash_string s){
            return hash==s.hash;
        }
        private:
        u64 mod_pow(u64 x,u64 y,u64 _mod){
            if(y==0)return 1;
            else if(y==1)return x;
            else if(y%2==1)return x*mod_pow(x,y-1,_mod)%_mod;
            else {
                auto t=mod_pow(x,y/2,_mod);
                return t*t%_mod;
            }
        }
    };
    vector<hash_string>hash;
    rolling_hash(string s){
        hash.resize(s.size()+1);
        hash[0]=hash_string();
        repi(i,1,s.size()+1)hash[i]=hash[i-1]+s[i-1];
    }
    hash_string operator()(int l,int len=-1){
        if(len==-1)return hash[hash.size()-1]-hash[l];
        else return hash[l+len]-hash[l];
    }
    hash_string operator()(){
        return hash[hash.size()-1];
    }
};
