  }) - sa.sa.begin();
  std::vector<int> v;
  for(int i = lb; i < ub; ++i) v.push_back(sa.sa[i]);

  if(v.size() < 1) fin(0);
  for(int x: v) if(x < N) sc.add_edge(x, (x+M)%N);
  if(sc.build(N) < N) fin(-1);
  std::fill_n(depth, N, -1);
  int ans = 0;
  for(int i = 0; i < N; ++i) {
    ans = std::max(ans, calc_depth(i));
  }
  fin(ans);

  return 0;
}

