bool looped;

int dfs(int v, int h = 0) {
    if (h > (int)s.length()) {
        looped = true;
        return 0;
    }
    if (dep[v] >= 0) {
        return dep[v];
    }
    if (matched[v]) {
        return (dep[v] = 1 + dfs((v + t.length()) % s.length(), h + 1));
    }
    return (dep[v] = 0);
}

