typedef unsigned long long ull;

class RabinKarp {
    // MODは2^64(unsigned long long を使えば桁あふれでmodと同じ)
    ull B;

  public:
    RabinKarp(ull mod = 100000007ULL) : B(mod) {}
    //文字列strのハッシュ値を求める
    ull hash(const std::string &str) {
        ull ret = 0;
        for (int i = 0; i < str.length(); i++) {
            ret = ret * B + (char)(str[i]);
        }
        return ret;
    }

    //文字列str中に文字列subが含まれているかどうか(見つかる場合はそのインデックスを返す)
    int find(const std::string &str, const std::string &sub) {
        if (str.length() < sub.length())
            return false;
        ull t = 1;
        for (int i = 0; i < sub.length(); i++)
            t *= B; // t = B^{sub.length()}

        ull sub_hash = hash(sub);
        ull str_sub_hash = 0;
        for (int i = 0; i < sub.length(); i++) {
            str_sub_hash = str_sub_hash * B + (char)(str[i]);
        }

        for (int i = 0; i <= str.length() - sub.length(); i++) {
            // hash値が一致
            if (str_sub_hash == sub_hash) {
                //念のため同じ文字列か確認
                bool issame = true;
                for (int j = 0; j < sub.length(); j++) {
                    if (sub[j] != str[i + j]) {
                        issame = false;
                        break;
                    }
                }
                if (issame)
                    return i; //最初に見つかったstrでのindex
            }

            // 1文字分ずらしたhash値を計算
            if (i < str.length() - sub.length()) {
                str_sub_hash =
                    str_sub_hash * B + str[i + sub.length()] - str[i] * t;
            }
        }
        return -1; //見つからなかった
    }

    //文字列str中に長さmの文字列集合subsetが含まれているかどうか(見つかる場合はそのインデックスを返す)
    int findset(const std::string &str, const std::vector<std::string> &subset,
                int m) {
        if (str.length() < m)
            return false;

        std::map<ull, std::string> hsubs; //文字列集合subsetのハッシュ値

        ull t = 1;
        for (int i = 0; i < m; i++)
            t *= B; // t = B^m

        // subsetの文字列のハッシュ値を計算
        for (int i = 0; i < subset.size(); i++) {
            ull sub_hash = hash(subset[i]);
            if (hsubs.count(sub_hash) != 0) {
                //簡単のため、subsetに同じハッシュ値を持つものがあったらエラーで終了
                std::cerr << "error: same hash value string exists."
                          << std::endl;
                return -1;
            }
            hsubs[sub_hash] = subset[i];
        }

        ull str_sub_hash = 0;
        for (int i = 0; i < m; i++) {
            str_sub_hash = str_sub_hash * B + (char)(str[i]);
        }

        for (int i = 0; i <= str.length() - m; i++) {
            // hash値が一致するものがある
            if (hsubs.count(str_sub_hash) != 0) { //【注意】mapは探索O(log n)
                return i; //最初に見つかったstrでのindex
            }

            // 1文字分ずらしたhash値を計算
            if (i < str.length() - m) {
                str_sub_hash = str_sub_hash * B + str[i + m] - str[i] * t;
            }
        }
        return -1; //見つからなかった
    }

    //ナイーブな方法(1:1文字ずつ確認、2:find関数を使って探索)
    int NaiveSearchSet1(const std::string &str,
                        const std::vector<std::string> &subset, int m) {
        for (int i = 0; i < subset.size(); i++) {
            for (int j = 0; j < str.length(); j++) {
                bool issame = true;
                for (int k = 0; k < subset[i].length(); k++) {
                    if (str[j + k - 1] != subset[i][k]) {
                        issame = false;
                        break;
                    }
                }
                if (issame)
                    return j;
            }
        }
        return -1;
    }
    int NaiveSearchSet2(const std::string &str,
                        const std::vector<std::string> &subset, int m) {
        int first_find_index = str.length() + 1;

        for (int i = 0; i < subset.size(); i++) {
            std::string::size_type idx = str.find(subset[i]);
            if (idx != std::string::npos) {
                if (first_find_index > (int)(idx)) {
                    first_find_index = (int)(idx);
                }
            }
        }
        if (first_find_index > str.length())
            return -1;
        return first_find_index;
    }
};

string pow(string s, int n) {
    if (n <= 1)
        return s;
    if (n & 1)
        return s + pow(s + s, n / 2);
    else
        return pow(s + s, n / 2);
}

int gcd(int m, int n) {
    if (m < n)
        swap(m, n);
    while (n > 0) {
        m %= n;
        swap(m, n);
    }
    return m;
}

LL solve() {
    string s, t;
    cin >> s >> t;
    int slen = s.size(), tlen = t.size();
    RabinKarp rk(1000000007), rk2(1000000009);
    // 繰り返しの場合がある TODO
    if (slen < tlen) {
        string s2 = "";
        while (s2.size() < tlen)
            s2 += s;
        // dump(s2.size());
        // dump(tlen);
        bool b = false;
        REP(i, 0, s2.size() - tlen + 1) {
            if (rk.find(s2, t) > -1 && rk2.find(s2, t) > -1) {
                b = true;
                break;
            }
        }
        if (!b)
            return 0;
        if (s2.size() == tlen) {
            return -1;
        }
        int g = gcd(s2.size(), tlen);
        string c = t.substr(0, g);
        for (int i = 0; i < s2.size() - g + 1; i += g) {
            if (s2.substr(i, g) != c)
                return 1;
        }
        for (int i = 0; i < t.size() - g + 1; i += g) {
            if (t.substr(i, g) != c)
                return 1;
        }
        return -1;
    }
    int ok = -1, ng = 1000000 + 1;
    s += s;
    slen *= 2;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;
        if (mid * tlen > slen) {
            ng = mid;
            continue;
        }
        string rept = pow(t, mid);
        if (rk.find(s, rept) > -1 && rk.find(s, rept) > -1)
            ok = mid;
        else
            ng = mid;
    }
    return ok;
}

