    }

    std::string v = t + "?" + u;

    std::vector<int> Z = Zalgorithm(v);

    //printvec(Z);

    rep (i, 0, s.size() - 1) {
        if (t.size() <= Z[t.size() + 1 + i]) {
            int next = (i + t.size()) % s.size();
            if (next == i) {
                std::cout << -1 << std::endl;
                return 0;
            }
            dg.add_directed_edge(i, next, 1);
            //std::cout << "e:" << i << " " << next << std::endl;
