vector<int> lps;

vector<int> kmp_lps(const string &s)
{
	vector<int> lps(s.size());
	for (int i = 1, j = 0; i < s.size(); )
		if (s[i] == s[j]) lps[i++] = ++j;
		else if (j > 0) j = lps[j - 1];
		else lps[i++] = 0;
	return lps;
}

int kmp_find(const string &s, const string &p, const vector<int> &lps, int start = 0, int repeat = 1)
{
	int n = s.size(), m = p.size(), nn = n * repeat;
	for (int i = start, j = 0; i < nn; ) {
		while (i < nn && j < m && s[i % n] == p[j]) i++, j++;
		if (j == m) return i - j;
		if (i < nn && s[i % n] != p[j]) {
			if (j > 0) j = lps[j - 1];
			else i++;
		}
	}
	return -1;
}

int find(const string &s, const string &t, int c = 1)
{
	int n = s.size(), m = t.size();
	int ans = 0;
	int p = kmp_find(s, t, lps, 0, c);
	if (p < 0) return 0;
	for (int start = 0, cur = 1; ; ) {
		if ((p = kmp_find(s, t, lps, start, c)) < 0) break;
		if (p == start) {
			++cur;
			ans = max(ans, cur);
		} else
			cur = 1;
		start = p + m;
	}
	return ans;
}

