int rollinghash(int l) {
  unsigned long long start=0LL;int sslen=SS.size();int count=0;base1=1LL;
  for (int i=tlen-1;i>=0;i--) {
    start+=SS[i+l]*base1;
    base1*=b;
  }
  if (start==tt) {
    count++;
    unsigned long long x=start;
    for (int i=0;i<sslen-tlen-l;i++) {
      x=x*b-base1*SS[i+l]+SS[i+l+tlen];
      if ((i+1)%tlen==0) {
        if (x==tt) count++;
        else break;
      }
    }
  }
  return count;
}

