        vi depth(N), used(N);
        auto dfs = [&](auto &&dfs, int now, int d) {
            if (used[now])
                return d + depth[now];
            depth[now] = d;
            for (auto [nxt, _] : g.adjList[now]) {
                chmax(depth[now], dfs(dfs, nxt, d + 1));
            }
            used[now] = 1;
            return depth[now];
        };
        REP(i, N) {
            if (used[i])
                continue;
            chmax(ans, (ll)dfs(dfs, i, 0));
        }
        //dump(depth);
        cout << ans << endl;
    }
}

