class RollingHash {
  using ulint = unsigned long long;
  const ulint mod = (1ULL << 61) - 1, mod7 = mod * 7, m30 = (1ULL << 30) - 1, m31 = (1ULL << 31) - 1;
  const unsigned base;
  vector<ulint>  hash, lookup;
  ulint mul(ulint a, ulint b) const {
    ulint au = a >> 31, ad = a & m31, bu = b >> 31, bd = b & m31;
    ulint m = ad * bu + au * bd, mu = m >> 30, md = m & m30;
    return au * bu * 2 + mu + (md << 31) + ad * bd;
  }
  ulint modulo(ulint x) const {
    if ((x = (x & mod) + (x >> 61)) > mod) x -= mod;
    return x;
  }

  public:
  RollingHash(void) : base(10007) {}
  RollingHash(const string &s, const unsigned base = 10007) : base(base) { init(s); }
  void init(const string &s) {
    const int len = s.length();
    hash.assign(len + 1, 0);
    lookup.assign(len + 1, 0);
    lookup[0] = 1;
    for (int i = 0; i < len; ++i) {
      hash[i + 1]   = modulo(mul(hash[i], base) + s[i]);
      lookup[i + 1] = modulo(mul(lookup[i], base));
    }
  }
  ulint get(const int l, const int r) const {
    return modulo(hash[r] + mod7 - mul(hash[l], lookup[r - l]));
  }
  bool same(const int a_begin, const int a_end, const int b_begin, const int b_end) const {
    if (a_end - a_begin != b_end - b_begin) return false;
    return get(a_begin, a_end) == get(b_begin, b_end);
  }
  bool same(const int a_begin, const int a_end, const int b_begin, const int b_end, const RollingHash &b_rh) const {
    if (a_end - a_begin != b_end - b_begin) return false;
    assert(base == b_rh.base);
    return get(a_begin, a_end) == b_rh.get(b_begin, b_end);
  }
};

int main(void) {
