	int len_t = T.length();
	while (S.length() < len_t * 3)S += S;

	ok.resize(len_s);

	vll key = { 1007,1009, 1013 };
	vll MOD_v = { (ll)(1e9 + 7), (ll)(1e9 + 9), 1234567891LL };
	vll pow_t = { 1,1,1 };
	rep(j,3) rep(i, len_t)pow_t[j] = pow_t[j]*key[j]%MOD_v[j];
	vll s_hash = { 0,0,0 }, t_hash = { 0,0,0 };
	rep(j,3)rep(i, len_t)s_hash[j] = (s_hash[j]*key[j]+S[i])%MOD_v[j];
	rep(j, 3)rep(i, len_t)t_hash[j] = (t_hash[j] * key[j] + T[i]) % MOD_v[j];

	rep(i, len_s) {
		if (i == 0) {
			if (same(s_hash,t_hash))ok[i] = 1;
		}
		else {
			rep(j, 3) {
				s_hash[j] = (s_hash[j]*key[j]%MOD_v[j] + S[i - 1 + len_t] + MOD_v[j] - (S[i - 1] * pow_t[j]) % MOD_v[j]) % MOD_v[j];
			}
			if (same(s_hash, t_hash))ok[i] = 1;
		}
	}
	UF uf(len_s);
	rep(i, len_s) {
		if (ok[i] && ok[(i + len_t) % len_s]) {
			if (!uf.unite(i, (i + len_t) % len_s)) {
				P(-1);
				return 0;
			}
		}

	}
	int ans = 0;
	rep(i, len_s) {
		if(ok[i])ans = max(ans, uf.size(i));
	}
	P(ans);

