struct UnionFind {
  vector<int> data;
  int sz;
  UnionFind(int _sz) : data(_sz, -1) { sz = _sz; }
  bool connect(int x, int y) {
      if ((x = root(x)) == (y = root(y))) return false;
      if (data[x] > data[y]) swap(x, y);
      data[x] += data[y]; data[y] = x; sz--;
      return true;
  }
  bool issame(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
  int size() { return sz; }
};

// https://ta7uw.hatenablog.com/entry/2019/10/13/223431
class RollingHash {
  static const ll base1 = 1009;
  static const ll base2 = 2009;
  static const ll mod1 = 1000000007;
  static const ll mod2 = 1000000009;
  vector<ll> hash1, hash2, pow1, pow2;

public:
  RollingHash(const string &S) {
    int n = (int) S.size();
    hash1.assign(n + 1, 0);
    hash2.assign(n + 1, 0);
    pow1.assign(n + 1, 1);
    pow2.assign(n + 1, 1);
    for (int i = 0; i < n; ++i) {
      hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
      hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
      pow1[i + 1] = (pow1[i] * base1) % mod1;
      pow2[i + 1] = (pow2[i] * base2) % mod2;
    }
  }

  // S の [l, r) のハッシュ値を返す
  inline pair<ll, ll> get(int l, int r) const {
    ll res1 = hash1[r] - hash1[l] * pow1[r - l] % mod1;
    if (res1 < 0) res1 += mod1;
    ll res2 = hash2[r] - hash2[l] * pow2[r - l] % mod2;
    if (res2 < 0) res2 += mod2;
    return make_pair(res1, res2);
  }
};

void solve() {
  string s, t;
  cin >> s >> t;

  // 長さの調節大事, RE になる
  string u = s + s; // debuged
  while (sz(u) < 2 * sz(t)) u += s;

  RollingHash ru(u), rt(t);
  vector<int> v(sz(s));
  rep(i, sz(s)) {
    auto ht = rt.get(0, sz(t));
    auto hu = ru.get(i, i + sz(t));
    v[i] = (ht == hu);
  }

  UnionFind uni(sz(s));
  rep(i, sz(s)) {
    int j = (i + sz(t)) % sz(s);

    if (v[i] && v[j]) {
      if (!uni.connect(i, j)) {
        cout << -1 << endl;
        return;
      }
    }
  }

  int ans = 0;
  rep(i, sz(s)) if (v[i]) chmax(ans, uni.size(i));
  cout << ans << endl;
}

