#include <bits/stdc++.h>

int main() {
    using namespace std;
    string s, t;
    cin >> s >> t;
    unsigned long N = s.size(), M = t.size();
    {
        unsigned long n = (N + M - 1) / N;
        string ss(s.begin(), s.end());
        while(n){
            if(n & 1)s += ss;
            ss += ss;
            n >>= 1;
        }
    }

    vector<unsigned long> MP_find_result;
    auto MP_find = [&MP_find_result](auto s, auto t){
        string Q = t + "_" + s;
        unsigned long N = s.size(), M = t.size(), L = Q.size();
        vector<unsigned long> MP(L + 1);
        for(unsigned long i = 1, j = 0; i <= L; ++i){
            while(j > 0 && Q[i - 1] != Q[j - 1])j = MP[j - 1];
            MP[i] = ++j;
            if(MP[i] > M && i >= MP[i] + M && i < MP[i] + N + M)MP_find_result.push_back(i - MP[i] - M);
        }
    };

    MP_find(s, t);

    vector<unsigned long> idx(N);
    for(const auto& i : MP_find_result)if(i < N)idx[i] = ~0UL;

    auto f = [rec = [&idx, &M, &N](auto f, unsigned long i, unsigned long t, unsigned long k) -> unsigned long{
        if(!idx[i])return 0;
        if(i == t && k)idx[i] = 2 * N;
        else if(!~idx[i])idx[i] = f(f, (i + M) % N, t, 1) + 1;
        return idx[i];
    }](unsigned long n){rec(rec, n, n, 0);};
    for(unsigned long i = 0; i < N; ++i)f(i);

    unsigned long ans = *max_element(idx.begin(), idx.end());
    if(ans > N)puts("-1");
    else cout << ans << endl;
    return 0;
}

