void getZarr(string str, vi& Z) {
    int n = str.length();
    int L, R, k;

    L = R = 0;
    REP (i, n) {
        if (i > R) {
            L = R = i;
            while (R < n && str[R-L] == str[R]) R++; 
            Z[i] = R-L;
            R--;
        } else {
            k = i-L;
            if (Z[k] < R-i+1) Z[i] = Z[k];
            else {
                L = i;
                while (R<n && str[R-L] == str[R]) R++;
                Z[i] = R-L;
                R--;
            }
        }
    }
}

vi search(string text, string pattern) {
    string concat = pattern + "$" + text;
    int l = concat.length();

    vi Z(l);
    getZarr(concat, Z);

    vi ret;
    REP (i, l) if (Z[i] == pattern.length()) {
        ret.push_back(i-pattern.length()-1);
    }
    return ret;
}

string S, T;

ll solve() {
    S += S;
    while (S.size() <= 2 * T.size()) S += S;

    set<ll> indices;
    FORE (i, search(S, T)) if (i < S.size()/2) {
        indices.insert(i);
    }

    ll ret = 0;
    vi check(S.size(), 0);
    FORI (iter, indices) {
        int index = *iter;
        if (check[index] != 0) continue;
        stack<int> s;

        int i = index;
        while (1) {
            s.push(i);
            int next = (i + T.size()) % (S.size()/2);
            if (next == index) return -1;
            if (indices.find(next) == indices.end()) break;
            i = next;
        }
        ll size = 0;
        while (!s.empty()) {
            check[s.top()] = ++size;
            s.pop();
        }
        CHMAX(ret, size);
    }

    return ret;
}

int main() {
    cin >> S >> T;
    cout << solve() << endl;
}

