struct KMP{
    const string word;
    int word_sz;
    // 単語に関する表
    // table[i] := S[0, i) において、prefix と suffix が一致している最大の長さ
    // つまり、S[0, table[i]), S[i-table[i], i) が等しいことを表す。
    // S[0, 0) では定義できないので、table[0] = -1 とする。
    // table[1] では、S[i-table[i], i) = S[1, 1) となるが、この場合は 1 文字も一致していないとみなして、table[1] = 0
    vector<int> table;

    KMP(const string &s) : word(s), word_sz(s.length()){
        table.resize(word_sz + 1);
        table[0] = -1;

        // 現在の prefix と suffix が等しい時の prefix の長さを表す。
        int len = -1;
        for(int i = 0; i < word_sz; ++i){
            // 次の文字が等しくなければ、len を短くしていく。
            // 今見ている prefix だけを見て、
            // その中での prefix' と suffix' が一致する最長のものが次の len の候補となる。
            // prefix の prefix'(=suffix') は、suffix の後ろの部分とも一致する。
            while(len >= 0 && word[i] != word[len]) len = table[len];
            table[i + 1] = ++len;
        }
    }

    vector<int> get_list(const string& str){
        vector<int> res;
        int st = 0;     // 今見ている部分文字列の先頭
        int cnt = 0;    // 今見ている部分文字列の文字数
        int n = str.size();
        while(st + cnt < n){
            if(word[cnt] == str[st + cnt]){
                if(++cnt == word_sz){
                    res.push_back(st);
                    st = st + cnt - table[cnt];
                    cnt = table[cnt];
                }
            }
            else{
                st = st + cnt - table[cnt];
                if(cnt > 0) cnt = table[cnt];
            }
        }
        return res;
    }

    void print(){
        int sz = table.size();
        for(int i = 0; i < sz; ++i){
            cerr << table[i];
            cerr << ((i == sz - 1) ? "\n" : " ");
        }
    }
};

struct CountUnionFind{
    int sz;     // vertex number
    vector<int> par;
    vector<int> rank;
    vector<int> cnt;

    CountUnionFind(int n) : sz(n) {
        par.resize(sz);
        rank.assign(sz, 0);
        cnt.assign(sz, 1);
        for(int i = 0; i < sz; ++i){
            par[i] = i;
        }
    }

    int find(int x){
        if(par[x] == x) return x;
        else    return par[x] = find(par[x]);
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    bool unite(int x, int y){
        x = find(x), y = find(y);
        if(x == y)  return false;
        if(rank[x] < rank[y]){
            par[x] = y;
            cnt[y] += cnt[x];
        }
        else{
            par[y] = x;
            cnt[x] += cnt[y];
            if(rank[x] == rank[y])  ++rank[x];
        }
        return true;
    }

    int get_cnt(int x){
        return cnt[find(x)];
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    KMP kmp(t);
    string S = s;
    int ns = s.length(), nt = t.length();
    while(2 * nt > (int)S.length())  S += s;
    vector<int> id = kmp.get_list(S);
    CountUnionFind uf(ns);
    for(int i = 0; i < id.size(); ++i){
        if(id[i] >= ns) continue;
        int foo = id[i], bar = (id[i] + nt) % ns;
        if(!uf.unite(foo, bar)){
            cout << -1 << endl;
            return 0;
        }
    }
    int res = 0;
    for(int i = 0; i < ns; ++i) chmax(res, uf.get_cnt(i) - 1);
    cout << res << endl;
}

#include <bits/stdc++.h>
using namespace std;

int64_t bpow[2][1000001];
int64_t binv[2];

template <size_t N>
class rolling_hash{
    vector<int64_t> mod;
    vector<int64_t> base;
    vector<int64_t> hash;
    size_t len;

    int64_t mpow(int64_t x, int64_t y, int64_t m){
        if(y == 0) return 1;
        if(y == 1) return x % m;
        if(y%2 == 0) return mpow(x*x%m, y/2, m);
        return mpow(x*x%m, y/2, m)%m * x % m;
    }
public:
    rolling_hash(vector<int64_t> bases, vector<int64_t> mods)
    : base(bases), mod(mods){
        hash.resize(N);
        for(int i=0;i<N;++i){
            hash[i] = 0;
        }
        len = 0;
        bpow[0][0] = bpow[1][0] = 1;
        for(int i=1;i<=1000000;++i){
            bpow[0][i] = bpow[0][i-1] * base[0] % mod[0];
            bpow[1][i] = bpow[1][i-1] * base[1] % mod[1];
        }
        binv[0] = mpow(base[0], mod[0]-2, mod[0]);
        binv[1] = mpow(base[1], mod[1]-2, mod[1]);
    }
    vector<int64_t> operator()(){
        return hash;
    }
    int64_t operator[](size_t n){
        return hash[n];
    }
    void push_back(char c){
        ++len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i]*base[i]%mod[i] + c) % mod[i];
        }
    }
    void push_front(char c){
        ++len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i] + c*bpow[i][len-1]%mod[i]) % mod[i];
        }
    }
    void pop_front(char c){
        --len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i] - c*bpow[i][len]) % mod[i];
            if(hash[i] < 0) hash[i] += mod[i];
        }
    }
    void pop_back(char c){
        --len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i] + mod[i] - c) % mod[i];
            hash[i] = hash[i] * binv[i] % mod[i];
        }
    }
};

int main(){
    int p;
    string s, t;
    cin >> s >> t;

    vector<int64_t> mods = {1'000'000'007, 1'000'000'009};
    vector<int64_t> bases = {rand() % mods[0], rand() % mods[1]};
    rolling_hash<2> s_rh(bases, mods), t_rh(bases, mods);

    for(int i=0;i<t.size();++i) t_rh.push_back(t[i]);
    for(int i=0;i<t.size();++i) s_rh.push_back(s[i%s.size()]);
    bool match[500000];
    for(int i=0;i<s.size();++i){
        match[i] = s_rh()==t_rh();
        s_rh.push_back(s[(i+t.size())%s.size()]);
        s_rh.pop_front(s[i]);
    }

    static int dp[500000];
    int ans = 0;
    for(int i=0;i<s.size();++i) dp[i] = -1;
    for(int i=0;i<s.size();++i){
        if(dp[i] >= 0) continue;
        stack<int> st;
        int pos = i;
        while(match[pos]){
            st.push(pos);
            pos = (pos+t.size()) % s.size();
            if(pos == i){
                cout << -1 << endl;
                return 0;
            }
            if(dp[pos] >= 0){
                while(!st.empty()){
                    int f = st.top();
                    st.pop();
                    dp[f] = 1 + dp[pos];
                    ans = max(ans, dp[f]);
                    pos = f;
                }
                goto l_nx;
            }
        }
        dp[pos] = 0;
        while(!st.empty()){
            int f = st.top();
            st.pop();
            dp[f] = dp[pos] + 1;
            ans = max(ans, dp[f]);
            pos = f;
        }
        l_nx:;
    }
    cout << ans << endl;

    return 0;
}

