struct SeqSearchTable {
	string v;
	vector<UL> t;
	SeqSearchTable(string seq) { init(move(seq)); }
	void init(string seq) {
		v = move(seq);
		t.resize(v.size());
		t[0] = (UL)-1;
		UL p = 1, q = -1;
		while (p < v.size()) {
			if (q == (UL)-1) { t[p] = 0; p++; q = 0; }
			else if (v[q] == v[p - 1]) { t[p] = q + 1; p++; q++; }
			else { q = t[q]; }
		}
	}
};

vector<UL> SeqSearch(const string &seq, const SeqSearchTable &tg) {
	vector<UL> f(seq.size());
	UL p = 0, q = 0;
	while (p < seq.size()) {
		if (seq[p] == tg.v[q]) {
			f[p] = q + 1;
			p++; q++;
			if (q == tg.v.size()) {
				q = tg.t[q - 1] + 1;
			}
		}
		else {
			q = tg.t[q];
			if (q == (UL)-1) { p++; q = 0; }
		}
	}
	return move(f);
}

UL gcd(UL a, UL b) { return b ? gcd(b, a % b) : a; }

struct Problem {

	void Solve() {
		string s, t; cin >> s >> t;
		string S; while (S.size() < t.size() + s.size()) S += s;
		auto F = SeqSearch(S, SeqSearchTable(t));
		cout << "S = " << S << endl;
		cout << "T = " << t << endl;
		rep(i, F.size()) cout << F[i] << " "; cout << endl;
		UL G = gcd(s.size(), t.size());
		UL ans = 0;
		rep(m, G) {
			UL n = 0;
			rep(i, s.size() / G * 2) {
				UL p = (t.size() * i + m) % s.size();
				if (F[p + t.size() - 1] >= t.size()) n++;
				else n = 0;
				ans = max(ans, n);
				cout << p << " ";
			} cout << endl;
		}
		if (ans >= s.size() / G) { cout << -1 << endl; return; }
		cout << ans << endl;
	}


	Problem();
};
