struct Z_algorithm
{
    vector< int > prefix;

    void build(const string &s)
    {
    prefix.assign(s.size(), 0);
    for(int i = 1, j = 0; i < s.size(); i++) {
        if(i + prefix[i - j] < j + prefix[j]) {
            prefix[i] = prefix[i - j];
        } else {
            int k = max(0, j + prefix[j] - i);
            while(i + k < s.size() && s[k] == s[i + k]) ++k;
            prefix[i] = k;
            j = i;
        }
    }
    prefix[0] = (int) s.size();
    }

    int operator[](const int k) const
    {
    return (prefix[k]);
    }

    size_t size()
    {
    return(prefix.size());
    }
};
int main(){
    string s, t; cin >> s >> t;
    int sz = s.size(), tz = t.size();
    int a = sz;
    do {
        rep(i, sz) s.push_back(s[i]);
        a += sz;
    }while(a < tz*2);
    Z_algorithm str; str.build(t+s);
    //cout << s << endl;
    //rep(i, str.size()-tz) cout << str.prefix[i+tz];
    sz = str.size() - tz;
    int cnt = 0; int ans = 0;
    bool flag = false;
    vector<int> p(sz);
    rep(i, sz) p[i] = str.prefix[i+tz];
    //rep(i,sz) cout << p[i];
    //puts("");
    while(1) {
        map<int, int> mp;
        int i=0;
        while(i<sz) {
            //printf("%d ",i);
            if(mp[i] == 1){
                puts("-1");
                return 0;
            }
            if(p[i]>=tz) {
                mp[i] = 1;
                cnt++;
                i += tz ;
                if(i >= sz){
                    i %= sz;
                    flag = true;
                }
            }else{
                mp.clear();
                ans = max(ans, cnt);
                cnt = 0;
                i++;
                if(flag){
                    cout << ans << endl;
                    return 0;
                }
            }
            ans = max(ans, cnt);
        }
        if(i==sz) break;
    }
    cout << ans << endl;
}

