template<typename T> struct kmp {
    int P;
    vector<T> word;
    vi fail;

    int adv(int len, const T& nxt) const {
        while (len > 0 && word[len] != nxt)
            len = fail[len];
        return len + int(word[len] == nxt);
    }

    /*
     * Initializes the "failure table" for the search word.
     * For i > 0, fail[i] is the length of the longest proper
     * suffix of word[0, i) that is a prefix of word.
     */
    kmp(const vector<T>& word) : P(word.size()), word(word) {
        fail.resize(P + 1);
        for (int i = 2; i <= P; i++)
            fail[i] = adv(fail[i - 1], word[i - 1]);
    }

    /*
     * Finds all occurences of the search word in the given text.
     * match[i] indicates whether there exists a match starting at
     * index i of text.
     */
    vb find(const vector<T>& text) const {
        vb match(text.size());
        for (int i = 0, len = 0; i < text.size(); i++) {
            len = adv(len, text[i]);
            if (len == P) {
                match[i - len + 1] = true;
                len = fail[len];
            }
        }
        return match;
    }
};

int main() {
    setIO();

    string s, t; re(t, s);

    vector<char> word, text;
    trav (c, s) word.pb(c);

    trav (c, t) text.pb(c);
    trav (c, t) text.pb(c);
    while (sz(text) < 3 * sz(word)) {
        trav (c, t) text.pb(c);
    }

    kmp<char> ss(word);
    vb matches = ss.find(text);

    vi maxc(sz(matches));
    F0Rd (i, sz(maxc)) {
        if (matches[i])
            maxc[i] = 1 + (i + sz(word) < sz(maxc) ? maxc[i+sz(word)] : 0);
    }

    int mm = *max_element(all(maxc));
    if (mm * sz(s) >= sz(text)/3*2) { ps(-1); }
    else { ps(mm); }

    return 0;
}

