constexpr LL INF = 1e13;
using RH         = RollingHash<>;
string s, t;

RH::Table S, T;
using I = __int128;

LL ret = 0;

RH rep(RH rh, I rep_num) {
    RH ret;
    while (rep_num > 0) {
        if (rep_num & 1) {
            ret = ret + rh;
        }
        rh = rh + rh;
        rep_num >>= 1;
    }
    return ret;
}

bool check(int t_bg, LL s_rep) {
    I s_size  = s.size();
    RH target = rep(S.substr(0, s.size()), s_rep);

    if (t_bg + s_size * s_rep <= t.size()) {
        return T.substr(t_bg, (int)(t_bg + s_size * s_rep)) == target;
    }
    else {
        I t_rep   = (t_bg + s_size * s_rep) / t.size() - 1;
        int t_mod = (int)((t_bg + (I)s.size() * s_rep) % t.size());
        return T.substr(t_bg, t.size()) + rep(T.substr(0, t.size()), t_rep)
                   + T.substr(0, t_mod)
               == target;
    }
}

LL solve(int t_bg) {
    LL ok = ret;
    LL ng = INF + 1;
    while (abs(ok - ng) > 1) {
        const LL md                 = (ok + ng) / 2;
        (check(t_bg, md) ? ok : ng) = md;
    }
    return ok;
}

