    REP(i, ns) {
        if (to[i] != -1) {
            g[to[i]].push_back(i);
            g[i].push_back(to[i]);
            indeg[to[i]]++;
            uf.unite(i, to[i]);
        }
    }

    vector<ll> roots; roots.reserve(ns);
    REP(i, ns) {
        if (g[i].size() && uf.root(i) == i) {
            roots.push_back(i);
        }
