    vector<ll> dp(ns, INF), from(ns, -1);
    for (ll root : roots) {
        deque<ll> q = {root};
        dp[root] = 0;
        while (q.size()) {
            ll u = q.front(); q.pop_front();
            for (ll v : g[u]) {
                if (v != from[u] && dp[v] != INF) {
