        }
    }

    vector<ll> roots2(ns, -1), ds1(ns, 0);
    REP(i, ns) {
        if (dp[i] < INF) {
            ll p = uf.root(i);
            if (chmax(ds1[p], dp[i])) {
                roots2[p] = i;
            }
        }
    }

    vector<ll> dp2(ns, INF);
