struct KMP {
	vector<ll> a;//0-index!
	vector<ll> b;

	vector<ll> pma;

	vector<ll> match;

	KMP(vector<ll>a0, vector<ll>b0) {
		a = a0;
		b = b0;

		ll N = a.size();
		ll M = b.size();

		pma.assign(M, 0);

		ll p = 0;
		repn(i, M - 1) {
			pma[i] = p;
			if (b[i] == b[p]) { p++; }
			else { p = 0; }
		}

		ll sa = 0;
		ll sb = 0;

		while (sa < N) {
			if (a[sa] == b[sb]) {
				if (sb == M - 1) { match.push_back(sa - sb); sb = pma[M - 1]; }
				else { sb++; sa++; }
			}

			else {
				if (sb == 0) { sa++; }
				sb = pma[sb];
			}
		}
	}


};


int main() {
	string s, t;
	cin >> s >> t;
	ll N = s.size();
	ll M = t.size();

	vector<ll> a(M+N), b(M);

	rep(i, M) b[i] = t[i];

	rep(i, M + N) a[i] = s[i%N];

	KMP a_b(a, b);

	vector<bool> match(N, 0);
	for (ll i : a_b.match) {
		if (i < N) { match[i] = 1; }
	}

	queue<ll> q;
	vector<ll> top(N, -1);

	rep(i, N) {
		ll j = (i - M) % N;
		if (j < 0) { j += N; }
		if (!match[j]) { q.push(i); top[i] = 0; }
	}

	//rep(i, N) cout << match[i];
	//cout << endl;

	while (!q.empty()) {
		ll i = q.front();
		q.pop();

		if (!match[i]) { continue; }
		ll j = (i + M) % N;

		top[j] = top[i] + 1;
		q.push(j);
	}

	ll ans = 0;
	rep(i, N) {
		if (top[i] == -1) { ans = -1; break; }
		ans = max(ans, top[i]);
	}

	cout << ans << endl;

	system("PAUSE");

}

