struct Find {
    Find(const T &s, const T &t) : m(t.size()), o(m * 2), a(o + s.size()) {
        int j = a[0] = -1;
        for (int i = 0; i < m; a[++i] = ++j) {
            while (j >= 0 && t[i] != t[j]) j = a[j];
        }
        int n = s.size(), l = a.size() - 1, h = 0;
        for (int i = m; i < l; a[++i] = ++j) {
            while (j >= 0 && (j == m || s[h] != t[j])) j = a[j];
            if (++h == n) h -= n;
        }
    }
    int operator[](int i) const {
        return a[o + i] == m;
    }
    const int m, o;
    vector<int> a;
};

struct Graph {
    struct Vertex { int n, k, d; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1, 0, 0 }), e(m), n(n), m(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        v[j].k++;
        m++;
    }
    void tsort() {
        vector<int> q(n);
        int i0 = 0, i1 = 0;
        for (int i = 0; i < n; i++) {
            if (v[i].k == 0) q[i1++] = i, v[i].d = 0;
        }
        while (i0 < i1) {
            int i = q[i0++];
            for (int j = v[i].n; j >= 0; j = e[j].n) {
                Edge &o = e[j];
                if (--v[o.i].k == 0) q[i1++] = o.i, v[o.i].d = v[i].d + 1;
            }
        }
        if (i1 < n) {
            cout << -1 << endl;
        } else {
            cout << v[q.back()].d << endl;
        }
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

