int n, m;
string s, t;

int nxt(int &idx) {
    return idx + m - n >= m - 1 ? idx + m - n : idx + m;
}
int prv(int &idx) {
    return idx - m >= m - 1 ? idx - m : idx - m + n;
}

bool thereIsCycle(vector <int> tInS) {
    for(int i = m - 1; i <= 2 * m; i++) {
        bool cycle = true;
        int idx = i;
        do {
            cycle &= (tInS[idx] == m);
            idx = nxt(idx);
        } while(idx != i && cycle);
        if(cycle) return true;
    }
    return false;
}

