    vector <int> tInS = kmp(s + s, t);

    if(thereIsCycle(tInS)) {
        cout << -1 << endl;
        assert(false);
        return 0;
    }

    int ans = 0;

    for(int i = m - 1; i < m - 1 + n; i++) {
        if(tInS[nxt(i)] == m)
            continue;

        int idx = prv(i), res = 0;
        while(tInS[idx] == m) {
            res++;
            idx = prv(idx);
        }
        ans = max(ans, res);
    }
    cout << ans << endl;
}

