struct Suffix_Automaton {
    int cnt, root, last, prt[MAXN << 1], son[MAXN << 1][CHARSET_SIZE], size[MAXN << 1],
        mx[MAXN << 1]; //root表示parent树的根/起始节点,prt表示的是当前匹配串的后缀
    int topo[MAXN << 1], buc[MAXN << 1]; //topo拓扑序 buc度数
    inline void init() {
        root = last = cnt = 1;
        size[cnt] = mx[cnt] = prt[cnt] = 0;
    }
    inline void extend(int c) //扩展SAM
    {
        int np = ++cnt, p = last; //np表示新的母串
        mx[np] = mx[p] + 1;
        size[np] = 1;
        for (; p && !son[p][c]; p = prt[p])
            son[p][c] = np; //将last的后缀连接路径上没有字符c出边的p连向np
        if (!p)                //如果p跳到了0 需要把np连向parent树的根
            prt[np] = root;
        else {
            int q = son[p][c];
            if (mx[q] == mx[p] + 1)
                prt[np] = q; //把u连接到trans(v,c)
            else //需要新建节点
            {
                int nq = ++cnt; //nq是new q是old
                memcpy(son[nq], son[q], sizeof(son[q])); //复制出边到新节点
                size[nq] = 0;
                mx[nq] = mx[p] + 1;
                prt[nq] = prt[q];      //nq的后缀链接指向q的后缀连接
                prt[q] = prt[np] = nq; //q和np的后缀链接指向nq
                for (; p && son[p][c] == q; p = prt[p])
                    son[p][c] = nq; //把路径上原来有转移的q的节点改成指向nq
            }
        }
        last = np; //替换整个母串
    }
    void toposort() //按照maxl从小到大排序
    {
        int maxv = 0;
        for (int i = 1; i <= cnt; i++)
        {
            buc[mx[i]]++;
            maxv = max(maxv, mx[i]);
        }
        for (int i = 1; i <= maxv; i++)
            buc[i] += buc[i - 1];
        for (int i = cnt; i >= 1; i--)
            topo[buc[mx[i]]--] = i;
    }
    void cal_right()
    {
        toposort();
        for (int i = cnt; i >= 1; i--) //递推right按照maxl从大到小
        {
            int v = topo[i];
            size[prt[v]] += size[v];
        }
    }
