		while (j > 0 && b[i] != b[j])
			j = pi[j - 1];
		if (b[i] == b[j])
			pi[i] = ++j;
	}

	for (int i = 0, j = 0; i < n; ++i) {
		while (j > 0 && a[i] != b[j])
			j = pi[j - 1];
		if (a[i] == b[j]) {
			if (j == m - 1)
				return true;
			else
				j++;
		}
	}
	return false;
}

int sol(string& a, string& b) {
	int l = 0, r = a.length() / b.length(), ans = 0;
	while (l <= r) {
		int m = (l + r) / 2;

		string tmp;
		for (int i = 0; i < m; ++i)
			tmp += b;

		if (kmp(a, tmp)) {
			l = m + 1;
			ans = max(ans, m);
		}
		else
			r = m - 1;
	}

	return ans;
}

