struct ZAlgorithm
{
	std::vector<int> z;
	ZAlgorithm(std::string s) : z(s.size(),0) {
		int l,r;
		// [l,r)
		l=r=0;
		for(int i=1;i<s.size();i++) {
			if(i>=r) {
				l=r=i;
				while(r<s.size() && s[r]==s[r-l]) r++;
				z[i] = r-l;
				continue;
			}
			if(z[i-l]<r-i) {
				z[i] = z[i-l];
				continue;
			}
			l=i;
			while(r<s.size() && s[r]==s[r-l]) r++;
			z[i] = r-l;
			continue;
		}
		z[0] = s.size();
	}
};

int dfs(int i,int c,std::vector<int>&to,std::vector<int>&went) {
	if(to[c]==i) return -1;
	if(to[c]==-1) return 0;
	if(went[c]>0) return went[c];
	int x = dfs(i,to[c],to,went);
	if(x==-1) return -1;
	return went[c]=x+1;
}

