// 蟻本でみた、ローリングハッシュを試してみる
vector<bool> check_eq(string s, string t) {
  int s_size = s.size();
  int t_size = t.size();
  vector<bool> result(s_size - t_size + 1);
  // modは2**64だと簡単に衝突する。また、複数用意して衝突しづらくする
  // http://hos.ac/blog/#blog0003 より
  vector<uint64_t> mods{1000000007, 999999937}; //modは素数。2乗してもオーバーフローしない数で
  uint64_t b = 10007;
  vector<uint64_t> bns(mods.size(), 1);
  vector<uint64_t> s_hash(mods.size(), 0);
  vector<uint64_t> t_hash(mods.size(), 0);
  int m_size = mods.size();

  for (int i = 0; i < t_size; i++) {
    for(int j = 0; j < m_size; j++) {
      const auto& m = mods[j];
      bns[j] = (bns[j] * b) % m;
    }
  }

  int i = 0;
  for(; i < t_size; i++) {
    for(int j = 0; j < m_size; j++) {
      const auto& m = mods[j];
      t_hash[j] = ((t_hash[j] * b) % m + t[i]) % m;
      s_hash[j] = ((s_hash[j] * b) % m + s[i]) % m;
    }
  }

  for(;;i++) {
    bool current_result = true;
    for(int j = 0; j < m_size; j++) {
      current_result &= s_hash[j] == t_hash[j];
    }

    result[i - t_size] = current_result;

    if (i >= s_size) {
      break;
    }

    for(int j = 0; j < m_size; j++) {
      const auto& m = mods[j];
      s_hash[j] = ((s_hash[j] * b) % m + s[i] - (s[i - t_size] * bns[j]) % m + m /*マイナスにならないようにmたす*/) % m;
    }
  }

  return result;
}

int main() {
  string s,t,s_origin;
  cin >> s >> t;
  s_origin = s;
  int s_origin_size = s_origin.size();
  int t_size = t.size();

  while(s.size() < t_size + s_origin_size) {
    s += s_origin;
  }

  vector<bool> eqs = check_eq(s,t);

  int max_length = 0;
  vector<int> length(s_origin_size, -1);

  for (int i = 0; i < s_origin_size; i++) {
    if (length[i] != -1) {
      continue;
    }

    if (!eqs[i]) {
      length[i] = 0;
      continue;
    }

    int current = i;
    int diff = 0;
    queue<int> q;
    while(eqs[current]) {
      if (!q.empty() && i == current) {
        // 無限に一致する
        max_length = -1;
        goto finish;
      }

      if (length[current] != -1) {
        diff = length[current]; // すでに到達済みの場合、計算済みの長さを加えて終了する
        break;
      }
      length[current] = 0; // 一旦到達マーク設定
      q.push(current);
      current = (current + t_size) % s_origin_size;
    }

    max_length = max(max_length, diff + (int)q.size());

    while(!q.empty()) {
      int len = q.size();
      int current = q.front();
      q.pop();
      length[current] = len + diff; // 正確な長さで上書き
    }
  }

finish:
  cout << max_length << endl;

  return 0;
}

