// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す


set<int> found;
int n,m;
map<int, int> used;
map<int, int> memo;

set<int> kmp(const string& str, const string& word) {
  vector<int> table = makeTable(word);
  set<int> ret;
  int m = 0, i = 0, N = str.size();
  while (m+i < N) {
    if (word[i] == str[m+i]) {
      if (++i == (int)(word.size())) {
        ret.insert(m);
        m = m+i-table[i];
        i = table[i];
      }
    } else {
      m = m+i-table[i];
      if (i > 0) i = table[i];
    }
    if (m>=n) break;
  }
  return ret;
}

int dfs(int i){
  dump(i);
  assert(i<=n-1);
  if (memo[i]>0) return memo[i];

  used[i] = 1;
  int ni = (i+m)%n;

  if(used[ni] && memo[ni]>0){  // found previous result
    memo[i] = memo[ni]+1;
    return memo[i];
  }
  else if (used[ni]){  // found loop
    memo[i] = INF;
    return memo[i];
  }
  else if (found.find(ni)!=found.end()){
    memo[i] = dfs(ni)+1;
    return memo[i];
  }
  else{
    memo[i] = 1;
    return memo[i];
  }
}
int solve(){
  string os,s,t;
  cin>>os>>t;
  n = sz(os);
  m = sz(t);
  while (sz(s)<sz(t)){
    s += os;
  }
  s += os;

  dump(s,t);
  found = kmp(s, t);
  dump(found);

  each(e, found){
    if (e<=n-1) dfs(e);
    else{ break; }
  }
  dump(used);
  dump(memo);

  int ans = 0;
  each(el, memo){
    chmax(ans, el.second);
  }
  if (ans>=INF){
    cout << -1 << endl;
  }
  else{
    cout << ans << endl;
  }

  return 0;
}

