struct rolling_hash{
	vector<long long> h;
	vector<long long> t_hash;
	long long b;
	string t;

	rolling_hash(string &T){
		h.push_back(998244353);h.push_back(1000000007);h.push_back(1000000009);
		t_hash.resize(h.size(),0);
		b = 1010101;
		t=T;


		vector<long long> b_beki(h.size(),1);

		for(int i=0;i<t.size();i++){
			int x = t.size()-1-i;
			for(int j=0;j<h.size();j++){
				t_hash[j] += (b_beki[j] * t[x])%h[j];
				b_beki[j] *= b;
				t_hash[j] %= h[j];
				b_beki[j] %= h[j];
			}
		}

	}

	//文字列Sの(先頭が)[l,r)文字目について検索
	vector<int> check(string &S,int l,int r){
		vector<int> ret(0);
		vector<long long> s_hash(h.size(),0);
		vector<long long> beki_max(h.size());
		for(int i=l;i<min((int)S.size()-(int)t.size()+1,r);i++){
			if(i==l){

				vector<long long> b_beki(h.size(),1);
				for(int j=0;j<t.size();j++){
					int x = i + t.size() - 1 - j;
					for(int k=0;k<h.size();k++){
						s_hash[k] += (b_beki[k] * S[x])%h[k];



						b_beki[k] *= b;
						s_hash[k] %= h[k];
						b_beki[k] %= h[k];
						if(j==t.size()-1){
							beki_max[k] = b_beki[k];
						}
					}
				}
			}
			else{
				for(int j=0;j<h.size();j++){
					s_hash[j] = (s_hash[j] * b)%h[j];

					s_hash[j] -= (beki_max[j] * S[i-1])%h[j];
					if(s_hash[j]<0) s_hash[j] += h[j];

					s_hash[j] = (s_hash[j] + S[i + t.size()-1])%h[j];
				}

			}
			bool f = true;
			for(int j=0;j<h.size();j++){
				if(s_hash[j]!=t_hash[j]){
					f=false;
					break;
				}


			}

			if(f){
				ret.push_back(i);
			}

		}
		return ret;

	}

};

int main(){

	string s,t;
	cin>>s>>t;
	rolling_hash ro(t);
	int sz = s.size();
	while(true){
		if(s.size()>=t.size()*2)break;
		s = s+s;
	}

	vector<int> V = ro.check(s,0,sz);

	vector<vector<int>> E(sz,vector<int>(0));


	for(int i=0;i<V.size();i++){
		E[V[i]].push_back((V[i]+t.size())%(sz));
	}

	vector<int> dis(sz,-1);

	for(int i=0;i<sz;i++){
		if(dis[i]!=-1)continue;
		int cnt = 0;
		int now = i;
		vector<int> X(0);
		set<int> S;
		while(true){
			X.push_back(now);
			S.insert(now);
			if(E[now].size()==0)break;
			cnt++;
			now = E[now][0];
			if(S.find(now)!=S.end()){
