			}
			if(dis[now]!=-1){
				cnt += dis[now];
				break;
			}
		}
		for(int j=0;j<X.size();j++){
			dis[X[j]]=cnt-j;
		}



	}
	int ans = 0;
	for(int i=0;i<sz;i++){
		ans = max(ans,dis[i]);
	}



	cout<<ans<<endl;





