    int val1 = 0, val2 = 0;
    for(auto it : t) {
        val1 = (val1 * B + it - 'a' + 1) % MOD1;
        val2 = (val2 * B + it - 'a' + 1) % MOD2;
    }

    vector <ull> hsh1(aux.size() + 1), hsh2(aux.size() + 1);

    int pw1 = 1, pw2 = 1;
    for(i = 1; i <= t.size(); i++) {
        pw1 *= B, pw2 *= B;
        pw1 %= MOD1, pw2 %= MOD2;
    }

    hsh1[0] = hsh2[0] = aux[0] - 'a' + 1;
