    string s = inp1, t = inp1;
    ll ns = s.size(), nt = t.size();

    string ss = srepeat(s, nt / ns + 2);
    string tss = t + ss;

    auto cp = common_prefix(ALL_OF(tss));

    vector<ll> to(ns, -1);
    REP(i, ns) {
        ll pfl = min(cp[nt+i], nt);
        if (pfl == nt) {
            to[i] = (i + pfl) % ns;
        }
    }

    // DUMPALL(to);

    if (count(ALL_OF(to), -1) == to.size()) {
        cout << 0 << endl;
        return 0;
    }

    vector<vector<ll>> g(ns);
    vector<ll> indeg(ns);
    REP(i, ns) {
        if (to[i] != -1) {
            g[to[i]].push_back(i);
            g[i].push_back(to[i]);
            indeg[to[i]]++;
        }
    }

    ll root = -1;
    REP(i, ns) {
        if (g[i].size()) {
            root = i;
            break;
        }
    }

    vector<ll> dp(ns, INF), from(ns, -1);
    deque<ll> q = {root};
    dp[root] = 0;
    while (q.size()) {
        ll u = q.front(); q.pop_front();
        for (ll v : g[u]) {
            if (v != from[u] && dp[v] != INF) {
                cout << -1 << endl;
                return 0;
            }
            if (chmin(dp[v], dp[u]+1)) {
                q.push_back(v);
                from[v] = u;
            }
        }
    }

    ll root2 = 0, d1 = 0;
    REP(i, ns) {
        if (dp[i] < INF) {
            if (chmax(d1, dp[i])) {
                root2 = i;
            }
        }
    }

    vector<ll> dp2(ns, INF);
    deque<ll> q2 = {root2};
    dp2[root2] = 0;
    while (q2.size()) {
        ll u = q2.front(); q2.pop_front();
        for (ll v : g[u]) {
            if (chmin(dp2[v], dp2[u]+1)) {
                q2.push_back(v);
            }
        }
    }

    ll ans = 0;
    REP(i, ns) {
        if (dp2[i] < INF) {
            chmax(ans, dp2[i]);
        }
    }
    say(ans);

}

