class RollingHash{
    const ll mod = 1e9+7;
    const ll base = 1007;
    V<> hash, power;
public:
    RollingHash(const string &s){
        ll n = SZ(s);
        hash.assign(n+1, 0);
        power.assign(n+1, 1);
        REP(i,n){
            hash[i+1] = (hash[i] * base + s[i]) % mod;
            power[i+1] = (power[i] * base) % mod;
        }
    }
    inline ll get(ll l, ll r) const {
        ll res = hash[r] - hash[l] * power[r-l] % mod;
        if(res < 0) res += mod;
        return res;
    }
    inline ll s_hash(){return get(0, SZ(hash) - 1);}
    inline ll getLCP (int a, int b) const {
        ll len = min(SZ(hash)-a, SZ(hash)-b);
        ll ok = 0, ng = len;
        while(abs(ok-ng) > 1){
            ll mid = (ok+ng) / 2;
            if(get(a, a+mid) != get(b, b+mid)) ng = mid;
            else ok = mid;
        }
        return ok;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s, t; cin >> s >> t;
    string _ = s;
    while(SZ(s) < SZ(t)) s += _;
    s += s + s;
    RollingHash RH(s);

    auto check = [&](ll mid){
        string u = "";
        REP(i, mid) u += t;
        RollingHash mew(u);
        ll c = mew.s_hash();
        REP(i, SZ(s) - SZ(u)){
            if(RH.get(i, i + SZ(u)) == c) return true;
        }
        return false;
    };
    ll ok = 0, ng = SZ(s) / SZ(t) + 1;
    while(abs(ok - ng) > 1){
        ll m = (ok + ng) / 2;
        if(check(m)) ok = m;
        else ng = m;
    }
    cout << (ok == SZ(s) / SZ(t) ? -1 : ok) << endl;
}

