  rep(i,0,(ll)m/n+1){
    s+=s;
  }

  std::vector<ll> a=kmp(s,t),tsort;

  std::vector<std::vector<ll>> graph(n,std::vector<ll>());
  std::vector<int> used(n,-1);

  if(a.empty()){
    std::cout<<0;
    return 0;
  }


  for(ll i:a){
    if(0<=i&&i<n){
      graph[i].push_back((i+m)%n);
    }
  }

  rep(i,0,n){
    if(used[i]==-1)dfs(i,ans2,used,graph,tsort);
  }

  std::reverse(all(tsort));

  if(ans2==-1){
    std::cout<<-1;
    return 0;
  }

  std::vector<ll> ans(n,0);

  for(ll i=n-1;i>=0;i--){
    if(graph[tsort[i]].size()){
