        i += k, j -= k;
    }
    return ret;
}

const int MAX_V = 5e5;
vector<int> es[MAX_V], rs[MAX_V];
vector<int> vs;
vector<bool> used(MAX_V, false);

void add_edge(int from, int to){
    es[from].pb(to), rs[to].pb(from);
}

void dfs(int now){
    used[now] = true;
    for(auto &e: es[now]) if(!used[e]) dfs(e);
    vs.pb(now);
}

bool find_loop(){
    rep(i, MAX_V) if(!used[i]) dfs(i);
    fill(all(used), false);
    rep3(i, (int)vs.size()-1, 0){
        int j = vs[i];
        used[j] = true;
        for(auto &e: rs[j]){
            if(!used[e]) return true;
        }
    }
    return false;
}

vector<int> mp(MAX_V, -1);

int max_path(int now){
    int ret = 0;
    for(auto &e: es[now]){
        if(mp[e] == -1) ret = max(ret, max_path(e)+1);
        else ret = max(ret, mp[e]+1);
    }
    return ret;
}

