        rep(i, N) s.pb(S[i]);
    }
    vector<int> res = z_algorithm(s);
    rep(i, N){
        if(res[M+i] >= M){
            int j = (i+M)%N;
            add_edge(i, j);
        }
    }
    if(find_loop()) {cout << -1 << endl; return 0;}
    int ans = 0;
    rep(i, MAX_V){
        ans = max(ans, max_path(i));
    }
    cout << ans << endl;
}

