        if (pfl == nt) {
            to[i] = (i + pfl) % ns;
        }
    }

    DUMPALL(to);

    if (count(ALL_OF(to), -1) == to.size()) {
        cout << 0 << endl;
        return 0;
    }

    vector<vector<ll>> g(ns);
    vector<ll> indeg(ns);
    REP(i, ns) {
        if (to[i] != -1) {
            g[to[i]].push_back(i);
            indeg[to[i]]++;
        }
    }

    ll root = -1;
    REP(i, ns) {
        if (indeg[i] == 1 && to[i] == -1) {
            root = i;
            break;
        }
