    */

    decltype(RH::power) t_hash_fact, s_hash_fact;
    t_hash_fact.emplace_back(make_pair(ModInt<MOD>(0), ModInt<MOD + 2>(0)));
    s_hash_fact.emplace_back(make_pair(ModInt<MOD>(0), ModInt<MOD + 2>(0)));
    for(int i = 0; i < 6e5 + 3; ++i){
        t_hash_fact.emplace_back(RH::connect(t_hash, t_hash_fact.back(), t.size()));
        s_hash_fact.emplace_back(RH::connect(s_hash.get(), s_hash_fact.back(), n));
    }
    abort();

    auto f = [&](i64 val, i64 i){
        auto th = t_hash_fact[val];
        // auto th = hashpow(t_hash, t.size(), val);
        i64 target_len = t.size() * val;
        i64 st_size = n - i;
        if(target_len <= st_size)
            return s_hash.get(i, i + st_size) == th;
        target_len -= st_size;
        i64 loop_cnt = target_len / n;
        i64 mod_cnt = target_len % n;
        target_len -= st_size;
        auto st_hash = s_hash.get(i);
        // auto loop_hash = hashpow(s_hash.get(), n, loop_cnt);
        auto loop_hash = s_hash_fact[loop_cnt];
        auto en_hash = s_hash.get(0, mod_cnt);
        return RH::connect(st_hash, RH::connect(loop_hash, en_hash, n * loop_cnt), st_size) == th;
    };

    i64 ans = 0;
    for(i64 i = 0; i < n; ++i){
        i64 ok = 0, ng = s.size() + 1;
        while(ng - ok > 1){
            if(ng <= ans)
                break;
            i64 mid = (ok + ng) >> 1;
            (f(mid, i) ? ok : ng) = mid;
        }
        chmax(ans, ok);
        if(ans == s.size()){
            cout << -1 << endl;
            return 0;
        }
    }
    cout << ans << endl;

    return 0;
}


