struct Hash{
    vector<vector<ll> > powb, rhash;
    vector<ll> MODS = {ll(1e9+7), ll(1e9+9)};
    void rolling_hash(string str, ll base = ll(1e5 + 7)) {
        int N = str.size();
        int M = MODS.size();
        powb.resize(M);
        rhash.resize(M);
        for(int k=0;k<M;k++){
            powb[k].resize(N + 1);
            rhash[k].resize(N + 1);
            powb[k][0] = 1;
            rhash[k][0] = 0;
            for (int i = 0; i < N; i++) {
                rhash[k][i + 1] = (str[i] + rhash[k][i] * base) % MODS[k];
                powb[k][i + 1] = powb[k][i] * base % MODS[k];
            }
        }
    }
    //[l,r)
    ll get_hash(int k, int l, int r) { return ((rhash[k][r] - rhash[k][l] * powb[k][r - l])%MODS[k]+MODS[k])%MODS[k];}
};

int main() {
    int n, m;
    string s, t, ss;
    cin >> s >> t;
    n = s.size();
    m = t.size();
    for(int i=0;i<max(2,m*2/n+1);i++) ss += s;
    Hash sh, th;
    sh.rolling_hash(ss);
    th.rolling_hash(t);
    vector<ll> dp(ss.size()+1);
    for(int i=0;i<=int(ss.size())-m;i++){
        bool ok = true;
        for(int j=0;j<2;j++){
            ok &= sh.get_hash(j,i,i+m) == th.get_hash(j,0,m);
        }
        if(ok) dp[i+m] = dp[i]+1;
    }
    ll ans = 0;
    for(int i=0;i<=int(ss.size());i++){
        ans = max(ans, dp[i]);
    }
    if((n > m && ans*m < n) || (n < m && ans < 2)){
        cout << ans << endl;
    }
    else{
        cout << -1 << endl;
    }
    return 0;
}

