template<typename T>
struct KMP{
    const T& word;
    int word_sz;
    // 単語に関する表
    // table[i] := S[0, i) において、prefix と suffix が一致している最大の長さ
    // つまり、S[0, table[i]), S[i-table[i], i) が等しいことを表す。
    // S[0, 0) では定義できないので、table[0] = -1 とする。
    // table[1] では、S[i-table[i], i) = S[1, 1) となるが、この場合は 1 文字も一致していないとみなして、table[1] = 0
    vector<int> table;

    KMP(const T &s) : word(s), word_sz(s.size()){
        table.resize(word_sz + 1);
        table[0] = -1;
        int len = -1;       // 現在の prefix と suffix が等しい時の prefix の長さを表す。
        for(int i = 0; i < word_sz; ++i){
            // 次の文字が等しくなければ、len を短くしていく。
            // 今見ている prefix だけを見て、
            // その中での prefix' と suffix' が一致する最長のものが次の len の候補となる。
            // prefix の prefix'(=suffix') は、suffix の後ろの部分とも一致する。
            while(len >= 0 && word[i] != word[len]) len = table[len];
            table[i + 1] = ++len;
        }
    }

    vector<int> get_list(const T& str){
        vector<int> res;
        int st = 0;     // 今見ている部分文字列の先頭
        int len = 0;    // 今見ている部分文字列の長さ
        int n = str.size();
        while(st + len < n){
            if(word[len] == str[st + len]){
                if(++len == word_sz){
                    res.push_back(st);
                    st = st + len - table[len];
                    len = table[len];
                }
            }
            else{
                st = st + len - table[len];
                if(len > 0) len = table[len];
            }
        }
        return res;
    }

    void print(){
        int sz = table.size();
        for(int i = 0; i < sz; ++i){
            cerr << table[i];
            cerr << ((i == sz - 1) ? "\n" : " ");
        }
    }
};

struct CountUnionFind{
    int sz;     // vertex number
    vector<int> par;
    vector<int> rank;
    vector<int> cnt;

    CountUnionFind(int n) : sz(n) {
        par.resize(sz);
        rank.assign(sz, 0);
        cnt.assign(sz, 1);
        for(int i = 0; i < sz; ++i){
            par[i] = i;
        }
    }

    int find(int x){
        if(par[x] == x) return x;
        else    return par[x] = find(par[x]);
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    void unite(int x, int y){
        x = find(x), y = find(y);
        if(x == y)  return;
        if(rank[x] < rank[y]){
            par[x] = y;
            cnt[y] += cnt[x];
        }
        else{
            par[y] = x;
            cnt[x] += cnt[y];
            if(rank[x] == rank[y])  ++rank[x];
        }
    }

    int get_cnt(int x){
        return cnt[find(x)];
    }
};

bool ok[500005];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    KMP<string> kmp(t);
    string S = s;
    S += s;
    int ns = s.length(), nt = t.length();
    while(2 * nt > (int)S.length())  S += s;
    vector<int> id = kmp.get_list(S);
    CountUnionFind uf(ns);
    for(int i = 0; i < id.size(); ++i){
        if(id[i] >= ns) break;
        ok[id[i]] = true;
    }
    for(int i = 0; i < ns; ++i){
        if(!ok[i])  continue;
        int foo = i, bar = (i + nt) % ns;
        if(uf.same(foo, bar)){
            cout << -1 << endl;
            return 0;
        }
        uf.unite(foo, bar);
    }
    int res = 0;
    for(int i = 0; i < ns; ++i){
        if(ok[i])   chmax(res, uf.get_cnt(i) - 1);
    }
    cout << res << endl;
}

