struct ROLLING_HASH {
    #define BASE1 10007
    #define BASE2 1009
    #define MOD1 1000000007
    #define MOD2 1000000009
    vector<ll> vec;
    vector<pl> acc;
    vector<pl> po;

    ll mod_pow (ll x, ll y, ll m) {
        ll ret = 1;
        while (y) {
            if (y&1) ret = ret * x % m;
            x = x * x % m;
            y /= 2;
        }
        return ret;
    }

    void init(vector<ll> _vec) {
        vec = _vec;
        /*
        rep(i,vec.size()) cerr << vec[i] << " ";
        cerr << endl;
        */
        acc.resize(vec.size());
        po.resize(vec.size());
        pl val = pl(0,0);
        rep(i,vec.size()) {
            if (i == 0) {
                po[0] = pl(1,1);
            } else {
                po[i].first = po[i-1].first*BASE1%MOD1;
                po[i].second = po[i-1].second*BASE2%MOD2;
            }
            val.first = (val.first+vec[i]*po[i].first)%MOD1;
            val.second = (val.second+vec[i]*po[i].second)%MOD2;
            acc[i] = val;
        }
    }

    pl get_hash (int l, int r) {
        pl ret;
        ret.first = (acc[r].first-(l==0?0:acc[l-1].first))%MOD1;
        ret.second = (acc[r].second-(l==0?0:acc[l-1].second))%MOD2;
        ret.first = ret.first * mod_pow(po[l].first, MOD1-2, MOD1) % MOD1;
        ret.second = ret.second * mod_pow(po[l].second, MOD2-2, MOD2) % MOD2;
        return ret;
    }
} rs, rt;

