set<int> kmpSearch(int n2) {
	int i = 0, j = 0;
	set<int> matches;

	while (i < n) {
		while (j >= 0 && s[i] != t[j]) j = prefix[j];
		i++; j++;
		if (j == m) {
			matches.insert((i - j)%n2);
			// printf("P is found at index %d in T\n", i - j);
			j = prefix[j]; // prepare j for the next possible match
		}
	}

	return matches;
}

