void dfs(int curr, vi &ts, set<int> &pars) {
	if (cyclic)
	{
		return;
	}
	pars.insert(curr);		
	visited[curr] = true;
	for(auto nxt: g[curr]) {
		if (!visited[nxt])
		{
			dfs(nxt, ts, pars);
		} else if (pars.find(nxt) != pars.end())
		{
			cyclic = true;
			return;
		}
	}
	pars.erase(curr);
	ts.push_back(curr);
}

void dfs2(int curr) {
	visited[curr] = true;
	for(auto nxt : g[curr]) {
		if (!visited[nxt])
		{
			dist[nxt] = dist[curr] + 1;
			dfs2(nxt);
