struct knuth_morris_pratt {
  int m;
  const string& P;
  vector<int> fail;
  knuth_morris_pratt(const string& P_)
      : P(P_), m(P.size()) {
    fail.resize(m + 1, -1);
    for (int i = 1, j = -1; i <= m; ++i) {
      while (j >= 0 && P[j] != P[i - 1]) j = fail[j];
      fail[i] = ++j;
    }
  }
  vector<int> match(const string& S) const {
    int n = S.size();
    vector<int> occur;
    for (int i = 0, k = 0; i < n; ++i) {
      while (k >= 0 && S[i] != P[k]) k = fail[k];
      if (++k == m) {
        /* match at s[i-m+1 ... i] */
        occur.push_back(i - m + 1);
      }
    }
    return occur;
  }
};

struct UnionFind {
  vector<int> parent;  // parent[root] is the negative of the size.
  UnionFind(int n)
      : parent(n, -1){};
  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v];
    parent[v] = u;
    return true;
  }
  bool find(int u, int v) {
    return root(u) == root(v);
  }
  int root(int u) {
    return parent[u] < 0 ? u : parent[u] = root(parent[u]);
  }
  int size(int u) {
    return -parent[root(u)];
  }
};

