	            if (tlen >= tsize + S.size()) {
	                ans = -1;
	                roop = false;
	                break;
	            }
                ans = max(ans, tlen/tsize);
	            tlen += tsize;
	        } else {
	            front += ti-skip[ti%tsize];
	            break;
	        }
	    }
	}
	cout << ans << endl;

    return 0;
}

