struct RollingHash{
    static const int base1=1007,base2=2009;
    static const int MOD1=1000000007LL,MOD2=1000000009LL;
    vector<long long> hash1,hash2,pow1,pow2;
    RollingHash(const string &s /* ここを変える */){
        int sz=(int)s.size();
        hash1.assign(sz+1,0); hash2.assign(sz+1,0);
        pow1.assign(sz+1,1); pow2.assign(sz+1,1);
        for(int i=0;i<sz;i++){
            hash1[i+1]=(hash1[i]*base1+s[i]) % MOD1;
            hash2[i+1]=(hash2[i]*base2+s[i]) % MOD2;
            pow1[i+1]=(pow1[i]*base1) % MOD1;
            pow2[i+1]=(pow2[i]*base2) % MOD2;
        }
    }
    inline pair<long long,long long> query(int l,int r)const{
        long long ret1=hash1[r]-hash1[l]*pow1[r-l]%MOD1;
        ret1=(ret1+MOD1)%MOD1;
        long long ret2=hash2[r]-hash2[l]*pow2[r-l]%MOD2;
        ret2=(ret2+MOD2)%MOD2;
        return {ret1,ret2};
    }
    inline int lcp(const RollingHash &t,int a,int b)const{
        int len=min((int)hash1.size()-a,(int)hash1.size()-b);
        int ok=0,ng=len;
        while(ng-ok>1){
            int mid=(ng+ok)>>1;
            if(query(a,a+mid)==t.query(b,b+mid)) ok=mid;
            else ng=mid;
        }
        return ok;
    }
};
signed main(){
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    string s,t;
    cin >> s >> t;
    string add=s;
    while(s.size()<=2*t.size()){
        s+=add;
    }
    RollingHash rh1(s);
    RollingHash rh2(t);
    int n=(int)s.size();
    vector<int> to(n,-1);
    int szt=(int)t.size();
    rep(i,n){
        if(rh1.lcp(rh2,i,0)==szt){
            int j=(i+szt)%n;
            to[i]=j;
        }
    }
    vector<ll> d(n,0);
    rep(i,n){
        if(d[i]>0) continue;
        int p=i;
        while(to[p]!=-1){
            int q=to[p];
            chmax(d[q],d[p]+1);
            if(d[q]>=n+1){
                cout << -1 << endl;
                return 0;
            }
            p=q;
        }
    }
    ll ans=0;
    rep(i,n){
        chmax(ans,d[i]);
    }
    cout << ans << endl;
}

