class SA {
  int n;
  string s;
public:
  vector<int> rank, sa;

  SA(string s) : s(s) {
    n = s.size();
    rank.resize(n + 1);
    sa.resize(n + 1);
    for (int i = 0; i < n; i++) rank[i] = s[i];
    s[n] = -1;
    for (int i = 0; i <= n; i++) sa[i] = i;
    vector<int> tmp(n + 1);
    for (int k = 1; k <= n; k <<= 1) {
      function<bool(int, int)> comp = [&](int i, int j) {
        if (rank[i] != rank[j]) {
          return rank[i] < rank[j];
        } else {
          int lvalue = i + k <= n ? rank[i + k] : -1;
          int rvalue = j + k <= n ? rank[j + k] : -1;
          return lvalue < rvalue;
        }
      };
      sort(sa.begin(), sa.end(), comp);
      tmp[sa[0]] = 0;
      for (int i = 0; i < n; i++) {
        tmp[sa[i + 1]] = tmp[sa[i]] + (comp(sa[i], sa[i + 1]) ? 1 : 0);
      }
      rank = tmp;
    }
  }

  pair<bool, int> contains(string t) {
    if (t.size() == 0) return make_pair(true, 0);
    int l = 0, r = n;
    while (r - l > 1) {
      int m = (l + r) / 2;
      if (s.compare(sa[m], t.size(), t) < 0) {
        l = m;
      } else {
        r = m;
      }
    }
    return make_pair(s.compare(sa[r], t.size(), t) == 0, sa[r]);
  }
};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  string s, t;
  cin >> s >> t;

  int m = s.size();
  for (int l = s.size(), i = 0; i < l; i++) s.push_back(s[i]);
  string u = s;
  while (u.size() < 2 * t.size()) {
    for (int l = u.size(), i = 0; i < l; i++) u.push_back(u[i]);
  }

  vector<int> A(t.size() + 1);

  A[0] = -1;
  int jj = -1;
  for (int i = 0; i < t.size(); i++) {
    while (jj >= 0 && t[i] != t[jj]) jj = A[jj];

    jj++;
    // 元のコードでは A[i+1] = j;
    if (t[i + 1] == t[jj]) A[i + 1] = A[jj];
    else A[i + 1] = jj;
  }

  SA sa(u);
  auto v = sa.contains(t);
  if (!v.first) {
    cout << 0 << endl;
    return 0;
  }
  bool loop = true;
  for (int i = 0; i < u.size(); i++) {
    if (u[(i + v.second) % u.size()] != t[i % t.size()]) loop = false;
  }
  if (loop) {
    cout << -1 << endl;
    return 0;
  }
  return -1;
  v.second %= m;

  ll ans = 0, score = 0, j = 0;
  for (int i = 0; i < u.size(); i++) {
    if (u[(i + v.second) % u.size()] == t[j]) {
      score++;
      ans = max(ans, score / (ll) t.size());
      j = (j + 1) % t.size();
    } else {
      score = A[j + 1];
      j = A[j + 1];
    }
  }
  cout << ans << endl;

  return 0;
}

