	FOR(i, 0, m) (((rs *= pw[n]) %= INF) += hs) %= INF;
	FOR(i, 0, n) (((rt *= pw[m]) %= INF) += ht) %= INF;
	//printf("hs = %llu ht = %llu rs = %llu rt = %llu\n", hs, ht, rs, rt);
	return (rs == rt);
}

bool check(int md){
	//printf("md = %d\n", md);
	ull rs = 0, rt = 0;
	FOR(i, 0, md) (((rs *= pw[n]) %= INF) += hs) %= INF;
	if(1ll * n * md <= m){
		FOR(i, 0, m) if(i + md * n <= m){
			rt = (pre[i + md * n - 1] - (i ? pre[i - 1] : 0) * pw[n] % INF + INF) % INF;
			if(rt == rs) return true;
		}
	}
	FOR(i, 0, m) if(m - i <= 1ll * md * n){
		rt = suf[i];
		ll copy = (1ll * md * n - (m - i)) / m, tail = (1ll * md * n - (m - i)) % m;
		(rt *= qpow(P, copy * m)) %= INF;
		//Matrix M = Matrix(pw[m], 0, 1, 1);
		//M = matpow(M, copy);
		//(rt += ht * M.c % INF) %= INF;
		(rt += tpw[copy]) %= INF;
		(rt *= pw[tail]) %= INF;
		if(tail) (rt += pre[tail - 1]) %= INF;
		//printf("i = %d copy = %d rs = %llu rt = %llu\n", i, copy, rs, rt);
		if(rs == rt) return true;
	}
	return false;
}

