// F - Strings of Eternity
#include <bits/stdc++.h>

using namespace std;

vector<int> lps;

vector<int> kmp_lps(const string &s)
{
	vector<int> lps(s.size());
	for (int i = 1, j = 0; i < s.size(); )
		if (s[i] == s[j]) lps[i++] = ++j;
		else if (j > 0) j = lps[j - 1];
		else lps[i++] = 0;
	return lps;
}

int kmp_find(const string &s, const string &p, int start = 0, int repeat = 1)
{
	int n = s.size(), m = p.size(), nn = n * repeat;
	for (int i = start, j = 0; i < nn; ) {
		while (i < nn && j < m && s[i % n] == p[j]) i++, j++;
		if (j == m) return i - j;
		if (i < nn && s[i % n] != p[j]) {
			if (j > 0) j = lps[j - 1];
			else i++;
		}
	}
	return -1;
}

int find(const string &s, const string &t, int c = 1)
{
	int n = s.size(), m = t.size();
	int ans = 0;
	for (int p = 0, start = 0, cur = 0; ; ) {
		if ((p = kmp_find(s, t, start, c)) < 0) break;
		if (p == start) ++cur;
		else cur = 1;
		ans = max(ans, cur);
		start = p + m;
	}
	return ans;
}

int main(int argc, char *argv[])
{
	ios::sync_with_stdio(false); cin.tie(0);
	string s, t;
	cin >> s >> t;
	string r = s;
	while (r.size() < t.size() + s.size()) r += s;

	lps = kmp_lps(t);

	int ans = find(r, t);
	if (ans > 0) {
		int c = find(r, t, 2);
		if (c > ans) ans = -1;
	}

	cout << ans << endl;

	return 0;
}

