  int scnt = (sl + tl - 2 + sl - 1) / sl;
  rep (i, scnt) {
    x += s;
  }
  int xl = x.length();
  vll vx(xl, 0);
  rep (i, xl) {
    vx[i] = x[i] - '/';
  }
  vll vt(tl, 0);
  rep (i, tl) {
    vt[i] = t[i] - '/';
  }

  RollingHash rh(vx);
  auto match = rh.include(vt);
  debug(x);
  debug(t);
  debug(match);

  vi g(sl, -1);
  vi dig_in(sl, 0);
  for (int ind : match) {
    if (ind >= sl) {
      break;
    }
    g[ind] = (ind + tl) % sl;
    dig_in[g[ind]] += 1;
  }

  int ans = 0;
  vector<bool> arrived(sl, false);
  rep (i, sl) {
    if (dig_in[i] > 0) {
      continue;
    }
    set<int> si;
    int current_index = i;
    si.insert(current_index);
    arrived[current_index] = true;
    while (true) {
      int next_index = g[current_index];
      if (next_index == -1) {
        break;
      }
      current_index = next_index;
      si.insert(current_index);
      arrived[current_index] = true;
    }
    ans = max(ans, (int)si.size() - 1);
  }
  rep (i, sl) {
    if (!arrived[i]) {
      ans = -1;
      break;
    }
  }
  print(ans);

