class Z_algorithm{
  public:
    string S;
    vector<ll> A;
    Z_algorithm(string s){
      S = s;
      A.resize(S.size());
      return;
    };

    ~Z_algorithm(void){
      return;
    };

    void calc(void){
      A[0] = S.size();
      ll i=1, j=0;
      while(i<S.size()){
        while(i+j < S.size() && S[j] == S[i+j]) ++j;
        A[i] = j;
        if(j==0){
          ++i;
          continue;
        }
        ll k=1;
        while(i+k<S.size() && k+A[k]<j){
          A[i+k] = A[k];
          ++k;
        }
        i += k;
        j -= k;
      }
      return;
    };

    void calc(string W){
      S = W+S;
      A.resize(S.size());
      calc();
      return;
    };
};

vll dp;
vll jump;
bool total_flag = true;

ll calc(ll pos, const ll init){
  ll n_pos = jump[pos];
  if(n_pos<0){
    return dp[pos] = 0;
  }
  if(n_pos==init){
    total_flag = false;
    return -2;
  }
  if(dp[pos]>=0) return dp[pos];
  return dp[pos] = calc(n_pos, init) + 1;
}

