{
    int n = (int)s.size();

    vector<int> sa(n);
    vector<int> rank(n);
    vector<int> tmp(n);

    for (int i=0; i<n; i++)
        sa[i] = i;
    sort(sa.begin(), sa.end(), [&](int a, int b){return s[a]<s[b];});
    for (int i=0; i<n; i++)
        rank[i] = s[i];

