    ios::sync_with_stdio(false);
    string s,t; cin>>s>>t;
    int n=s.size(), m=t.size();
    string u;
    int l=0;
    while(l<n+m-1) u+=s, l+=n;
    SuffixArray sa(u);
    auto range = sa.lower_upper_bound(t);
    UnionFind uf(n);
    FOR(i,range.fi,range.se-1){
        if (sa[i]>=n) continue;
        if (uf.same(sa[i],(sa[i]+m)%n)){
            cout<<"-1\n";
            return 0;
        }
        uf.unite(sa[i],(sa[i]+m)%n);
    }
    int ans=0;
    map<int,int> cnt;
    rep(i,n){
        int r = uf.root(i);
        cnt[r]++;
        chmax(ans,cnt[r]);
    }
    cout<<ans-1<<"\n";
    return 0;
}

