class Matrix{
public:
	ull a, b, c, d;
	Matrix(){}
	Matrix(ull _a, ull _b, ull _c, ull _d): a(_a), b(_b), c(_c), d(_d){}
	Matrix operator * (const Matrix &M)const{
		Matrix ret;
		ret.a = (a * M.a % INF + b * M.c) % INF;
		ret.b = (a * M.b % INF + b * M.d) % INF;
		ret.c = (c * M.a % INF + d * M.c) % INF;
		ret.d = (c * M.b % INF + d * M.d) % INF;
		return ret;
	}
};

inline Matrix matpow(Matrix M, ull y){
	if(!y) return Matrix(1, 0, 0, 1);
	Matrix ret = M;
	for(--y; y; y >>= 1){
		if(y & 1) ret = ret * M;
		M = M * M;
	}
	return ret;
}

inline ull qpow(ull x, ull y){
	ull ret = 1;
	for(; y; y >>= 1){
		if(y & 1) (ret *= x) %= INF;
		(x *= x) %= INF;
	}
	return ret;
}

inline void add(ull &h, char c){
	(((h *= P) %= INF) += (c - 'a' + 1)) %= INF;
	return;
}

inline void add(ull &h1, ull h2, char c){
	h1 = (h2 * P % INF + c - 'a' + 1) % INF;
	return;
}

bool overlap(){
	ull rs = 0, rt = 0;
	FOR(i, 0, m) (((rs *= pw[n]) %= INF) += hs) %= INF;
	FOR(i, 0, n) (((rt *= pw[m]) %= INF) += ht) %= INF;
	//printf("hs = %llu ht = %llu rs = %llu rt = %llu\n", hs, ht, rs, rt);
	return (rs == rt);
}

bool check(int md){
	//printf("md = %d\n", md);
	ull rs = 0, rt = 0;
	FOR(i, 0, md) (((rs *= pw[n]) %= INF) += hs) %= INF;
	FOR(i, 0, m) if(m - i <= 1ll * md * n){
		rt = suf[i];
		ll copy = (1ll * md * n - (m - i)) / m, tail = (1ll * md * n - (m - i)) % m;
		(rt *= qpow(P, copy * m)) %= INF;
		Matrix M = Matrix(pw[m], 0, 1, 1);
		M = matpow(M, copy);
		(rt += ht * M.c % INF) %= INF;
		(rt *= pw[tail]) %= INF;
		if(tail) (rt += pre[tail - 1]) %= INF;
		if(rs == rt) return true;
	}
	return false;
}

