void dfs(int nod) {
    vis[nod] = 1;

    if(to[nod] != -1 && vis[to[nod]] == 1) {
        cout << -1;
        exit(0);
    }

    if(to[nod] != -1) {
        dfs(to[nod]);
    }

    vis[nod] = 2;

