struct rollingHash {
  vector<ll> ah;
  vector<vector<ll> > bh;
  int n, m, M = 2;

  rollingHash(string a, string b) {
    n = sz(a), m = sz(b);

    int B[] = { 1007, 2009 };
    int mod[] = { 1000000007, 1000000009 };
    ah.resize(M);
    bh.resize(M);

    auto calc = [&](int B, int mod, int k) {
      ll _bh = 0, t = 1;
      // 最初のハッシュ値を生成
      rep(i, n) {
        (ah[k] = ah[k] * B + a[i]) %= mod;
        (_bh = _bh * B + b[i]) %= mod;
        (t *= B) %= mod;
      }
      rep(i, m) {
        bh[k].eb(_bh);
        (_bh = _bh * B - b[i] * t + b[i + n]) %= mod;
      }
      // cout << ah[k] << endl << bh[k] << endl;
    };
    rep(i, M) calc(B[i], mod[i], i);
  }

  vector<int> get() {
    vector<int> table(m);
    rep(i, M) rep(j, m) if (ah[i] == bh[i][j]) table[j]++;
    rep(j, m) table[j] = (table[j] == M);
    return table;
  }
};

struct UnionFind {
  vector<int> data;
  int sz;
  UnionFind(int _sz) : data(_sz, -1) { sz = _sz; }
  bool connect(int x, int y) {
      if ((x = root(x)) == (y = root(y))) return false;
      if (data[x] > data[y]) swap(x, y);
      data[x] += data[y]; data[y] = x; sz--;
      return true;
  }
  bool issame(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
  int size() { return sz; }
};


void solve() {
  string s, t;
  cin >> s >> t;

  string u = s;
  while (sz(u) < 2 * sz(t)) u += s;
  u = u + u + u;

  rollingHash roll(t, u);
  auto v = roll.get();
  // cout << v << endl;

  UnionFind uni(sz(s));
  rep(i, sz(s)) {
    int I = i + sz(s);
    int j = (i + sz(t)) % sz(s);
    int J = j + sz(s);

    if (v[I] && v[J]) {
      if (!uni.connect(i, j)) {
        cout << -1 << endl;
        return;
      }
    }
  }
  // rep(i, sz(s)) cout << uni.root(i) << " "; cout << endl;

  int ans = 0;
  // if (v[i]) 重要
  rep(i, sz(s)) if (v[i]) chmax(ans, uni.size(i));

  cout << ans << endl;
}

