	repd(i,s.size()) if(dp[i]) dp[i]+=dp[i+t.size()];
	repd(i,s.size()) ans=max(ans,dp[i]);

	cout<<(ans+1>=SZ(s)/SZ(t)?-1:ans);

	return 0;
}
