const int MAX_N = 5e5 + 10;
Directed_Graph dg(MAX_N);

int dp[MAX_N];

int calc(int i) {
    if (dp[i] != -1) {
        return dp[i];
    }

    int ret = 0;
    for (auto e : dg.G[i]) {
        ret = std::max(ret, calc(e.to) + 1);
    }
    dp[i] = ret;
