using namespace std;
typedef unsigned long long ull;

vector<int> prm;
const ull B = 1000000007;

void prime(){
    for(int i = 2; i < 1000; i++){
        bool p = true;
        for(int x : prm)
            if(i % x == 0) p = false;
        if(p) prm.push_back(i);
    }
}

bool contain(string a, string b){
    int al = a.size(), bl = b.size();
    if(al > bl) return false;
    ull t = 1;
    for(int i = 0; i < al; i++) t *= B;
    ull ah = 0, bh = 0;
    for(int i = 0; i < al; i++) ah = ah * B + a[i];
    for(int i = 0; i < al; i++) bh = bh * B + b[i];
    for(int i = 0; i + al <= bl; i++){
        if(ah == bh) return true;
        if(i + al < bl) bh = bh * B + b[i + al] - b[i] * t;
    }
    return false;
}

string primestr(string s){
    int n = s.size();
    int t = n;
    for(int p : prm) if(t % p == 0) while(t % p == 0) t /= p;
    if(t > 2) prm.push_back(t);
    int mincycle = 1;
    for(int p : prm){
        bool cyclic = true;
        int exp = 1;
        while(cyclic){
            int c = pow(p, exp);
            if(n % c) break;
            int w = n / c;
            for(int i = 0; i < w; i++){
                for(int j = 0; j < c - 1; j++){
                    if(s[i + j * w] != s[i + (j + 1) * w]) cyclic = false;
                }
            }
            if(cyclic) mincycle *= p;
            exp++;
        }
    }
    return s.substr(0, n / mincycle);
}

int main()
{
    prime();
    string s, t;
    cin >> s >> t;
    string sprime = primestr(s);
    string tprime = primestr(t);
    sprime += sprime;
    if(sprime.size() == tprime.size() * 2){
        if(contain(tprime, sprime)) cout << -1 << endl;
        else cout << 0 << endl;
    }
    else{
        int n = sprime.size();
        int m = t.size();
        int maxans = n / m;
        int now = 1;
        while(now < maxans) now *= 2;
        string maxt;
        for(int i = 0; i < now; i++) maxt += t;
        int mid = now / 2;
        while(mid){
            if(contain(maxt.substr(0, now * m), sprime)) now += mid;
            else now -= mid;
            mid /= 2;
        }
        if(!contain(maxt.substr(0, now * m), sprime)) now--;
        cout << now << endl;
    }
}

