int find(const string &s, const string &t, int c, int start = 0)
{
	int n1 = s.size(), n2 = t.size();
	int ans = 0, cur = 0;
	for (int i = start; i < n1 * c; i++) {
		if (s[i % n1] != t[0]) {
			cur = 0;
			continue;
		}
		bool ok = true;
		for (int j = 1; j < n2; j++)
			if (s[(i + j) % n1] != t[j]) {
				ok = false;
				break;
			}
		if (ok) {
			ans = max(ans, ++cur);
			i += n2 - 1;
		}
	}

	return ans;
}

