    REP(i, 26)REP(j, 26){
        if((cnts[i] == (int)s.size()) && (cntt[j] == (int)t.size())){
            cout << -1 << endl;
            return 0;
        }
    }

    if((int)s.size() % (int)t.size() == 0){
        bool flg = true;
        REP(i, s.size()){
            if(s[i] != t[i%(int)t.size()])flg = false;
        }
