            cout << -1 << endl;
            return 0;
        }
    }

    if(ig)swap(s, t);
    if((int)s.size() < (int)t.size()){
        cout << 0 << endl;
        return 0;
    }
    s = s + s + s + s;

    contain(t, s);


    LL ans = 0;
	REP(i, 1010101){
        ans = max(ans, dp[i]);
    }
    for(int i = 1010101;i < 2020202;i++){
        if(ans < dp[i]){
            cout << -1 << endl;
