struct KMP {
  int n;
  string s;
  vector<int> a;
  // a[i] = s[0:i]のprefixとsuffixが最大何文字一致しているか
  void build(const string &s) {
    this->s = s;
    n = s.size();
    a.assign(n+1,-1);
    for(int i=0,j=-1;i<n;a[++i]=++j)while(j>=0&&s[i]!=s[j])j=a[j];
  }
  // find s from t
  vector<int> match(const string &t) {
    int j=0;
    int cnt = 0;
    vector<int> v;
    REP(i,t.size()) {
      while(j>=0 && s[j]!=t[i]) j = a[j];
      if (++j>=n) {
        v.push_back(i - n + 1);
        ++cnt, j=a[j];
      }
    }
    return v;
  }
  // s[0:i]の最小周期
  int period(int i) {
    return i - a[i];
  }
};

