template <i64 mod = MOD>
struct ModInt{
    i64 p;

    ModInt() : p(0){}
    ModInt(i64 x){p = x >= 0 ? x % mod : x + (-x + mod - 1) / mod * mod;}

    ModInt& operator+=(const ModInt& y){p = p + *y - ((p + *y) >= mod ? mod : 0); return *this;}
    ModInt& operator-=(const ModInt& y){p = p - *y + (p - *y < 0 ? mod : 0); return *this;}
    ModInt& operator*=(const ModInt& y){p = (p * *y) % mod; return *this;}
    ModInt& operator%=(const ModInt& y){if(y)p %= *y; return *this;}

    ModInt operator+(const ModInt& y) const{ModInt x = *this; return x += y;}
    ModInt operator-(const ModInt& y) const{ModInt x = *this; return x -= y;}
    ModInt operator*(const ModInt& y) const{ModInt x = *this; return x *= y;}
    ModInt operator%(const ModInt& y) const{ModInt x = *this; return x %= y;}

    friend ostream& operator<<(ostream& stream, const ModInt<mod>& x){
        stream << *x;
        return stream;
    }

    friend ostream& operator>>(ostream& stream, const ModInt<mod>& x){
        stream >> *x;
        return stream;
    }

    ModInt& operator++(){p = (p + 1) % mod; return *this;}
    ModInt& operator--(){p = (p - 1 + mod) % mod; return *this;}

    bool operator==(const ModInt& y) const{return p == *y;}
    bool operator!=(const ModInt& y) const{return p != *y;}

    const i64& operator*() const{return p;}
    i64& operator*(){return p;}

};

using mint = ModInt<>;

template <typename T = mint>
T mpow(T x, i64 y){
    T z = x;
    T val = y & 1 ? x : T(1);
    while(z *= z, y >>= 1)
        if(y & 1)
            val *= z;
    return val;
}

template <i64 mod1 = MOD, i64 mod2 = MOD + 2, i64 base = 10007, typename T = string>
struct RollingHash{

    using mint1 = ModInt<mod1>;
    using mint2 = ModInt<mod2>;
    using pair_type = pair<mint1, mint2>;
    int len;
    std::vector<pair_type> v;
    static std::vector<pair_type> power, inv;

    RollingHash(T s) :
    len(s.size())
    {
        v.assign(1, make_pair(mint1(0), mint2(0)));
        for(int i = 0; i < len; ++i){
            auto c = s[i];
            v.emplace_back(v.back().first + power[i].first * c,
                           v.back().second + power[i].second * c);
            if(static_cast<int>(power.size()) == i + 1){
                power.emplace_back(power.back().first * base,
                                   power.back().second * base);
                inv.emplace_back(mpow<mint1>(power.back().first, mod1 - 2),
                                 mpow<mint2>(power.back().second, mod2 - 2));
            }
        }
    };

    pair_type get(int l = 0, int r = -1){
        if(r == -1)
            r = len;
        assert(l <= r);
        assert(r <= len);
        auto l_cut = make_pair(v[r].first - v[l].first,
                               v[r].second - v[l].second);
        return make_pair(l_cut.first * inv[l].first,
                         l_cut.second * inv[l].second);
    }

    static pair_type connect(pair_type l, pair_type r, int l_len){
        if(l_len >= power.size()){
            return make_pair(l.first + mpow<mint1>(mint1(base), l_len) * r.first,
                     l.second + mpow<mint2>(mint2(base), l_len) * r.second);
        }
        return make_pair(l.first + power[l_len].first * r.first,
                         l.second + power[l_len].second * r.second);
    }
};

using RH = RollingHash<MOD, MOD + 2, 10007>;
template<> vector<pair<ModInt<MOD>, ModInt<MOD + 2>>> RH::power = {make_pair(ModInt<MOD>(1), ModInt<MOD + 2>(1))};
template<> vector<pair<ModInt<MOD>, ModInt<MOD + 2>>> RH::inv = {make_pair(ModInt<MOD>(1), ModInt<MOD + 2>(1))};



i64 solve(i64 _count){

    string s, t;
    cin >> s >> t;

    if(!static_cast<bool>(cin))
        return MOD;
#ifdef TEST
    cout << "Case: " << _count << endl;
#endif

    i64 n = s.size();
    RH s_hash(s);
    auto t_hash = RH(t).get();

    /*
    auto hashpow = [&](auto x, i64 x_len, i64 y){
        auto z = x;
        using mi641 = ModInt<MOD>;
        using mi642 = ModInt<MOD + 2>;
        auto val = y & 1 ? x : make_pair(mi641(0), mi642(0));
        i64 zl = x_len;
        while(z = RH::connect(z, z, zl), y >>= 1){
            zl <<= 1;
            if(y & 1)
                val = RH::connect(z, val, zl);
        }
        return val;
    };
    */

    decltype(RH::power) t_hash_fact, s_hash_fact;
    t_hash_fact.emplace_back(make_pair(ModInt<MOD>(0), ModInt<MOD + 2>(0)));
    s_hash_fact.emplace_back(make_pair(ModInt<MOD>(0), ModInt<MOD + 2>(0)));
    for(int i = 0; i < 3e6 + 3; ++i){
        t_hash_fact.push_back(RH::connect(t_hash, t_hash_fact.back(), t.size()));
        s_hash_fact.push_back(RH::connect(s_hash.get(), s_hash_fact.back(), n));
    }

    auto f = [&](i64 val, i64 i){

        auto th = t_hash_fact[val];
        // auto th = hashpow(t_hash, t.size(), val);
        i64 target_len = t.size() * val;
        i64 st_size = n - i;
        if(target_len <= st_size)
            return s_hash.get(i, i + st_size) == th;
        target_len -= st_size;
        i64 loop_cnt = target_len / n;
        i64 mod_cnt = target_len % n;
        auto st_hash = s_hash.get(i);
        // auto loop_hash = hashpow(s_hash.get(), n, loop_cnt);
        auto loop_hash = s_hash_fact[loop_cnt];
        auto en_hash = s_hash.get(0, mod_cnt);
        return RH::connect(st_hash, RH::connect(loop_hash, en_hash, n * loop_cnt), st_size) == th;
    };

    int d = max(s.size(), t.size()) / min(s.size(), t.size()) * 3;

    i64 ans = 0;
    for(i64 i = 0; i < n; ++i){
        i64 ok = 0, ng = d;
        while(ng - ok > 1){
            if(ng <= ans)
                break;
            i64 mid = (ok + ng) >> 1;
            (f(mid, i) ? ok : ng) = mid;
        }
        chmax(ans, ok);
        if(ans == d - 1){
            cout << -1 << endl;
            return 0;
        }
    }
    cout << ans << endl;

    return 0;
}


