inline int find(int x)
{
    int id=lower_bound(pos.begin(), pos.end(), x)-pos.begin();
    if(id>=pos.size()) return 0;
    return pos[id]==x;
}

inline int solve(int len)
{
    memset(mark, 0, sizeof(mark));
    int tag=0;
    foreach(it, pos) if(!mark[*it])
    {
        if(*it+M>=len) break;
        int tmp=1;
        mark[*it]=1;
        for(int j=*it+M; j<len; j+=M) if(!find(j)) break;
            else mark[j]=1, tmp++;
        tag=max(tag, tmp);
    }
    return tag;
}

