vector<int> buildKMPFailTable(const string& t) {
	int m = sz(t);
	vector<int> fail(m + 1);
	int j = fail[0] = -1;
	for (int i = 1; i <= m; i++) {
		while (j >= 0 && t[j] != t[i - 1]) j = fail[j];
		fail[i] = ++j;
	}
	return fail;
}

int solve(string s, string t) {
	int originalSSize = sz(s);
	while (sz(s) < originalSSize + sz(t)) s += s;
	auto fail = buildKMPFailTable(s);

	vector<int> ok;
	for (int i = 0, k = 0; i < originalSSize + sz(t) - 1; i++) {
		while (k >= 0 && t[k] != s[i]) k = fail[k]; 
		k++;
		if (i >= sz(t) - 1) {
			ok.push_back(k >= sz(t));
		}
	}
	int g = gcd(sz(s), sz(t));
	int ans = 0;
	FOR(i, g) {
		vector<int> cur;
		FOR(j, sz(s) / g) {
			cur.push_back(ok[(i + sz(t) * j) % sz(ok)]);
		}
		FOR(i, sz(s) / g) cur.push_back(cur[i]);
		int cnt = 0;
		for (auto c : cur) {
			if (c == 1) cnt++;
			if (c == 0) cnt = 0;
			ans = max(ans, cnt);
		}
		if (cnt == sz(cur)) return -1;
	}

	return ans;
}

