int h[N_MAX];

void init(string S){
    h[0] = 0;
    h[1] = 0;
    for(int i = 2; i <= S.size(); i++){
        if(h[i-1] == 0){
             if(S[i-1] == S[0]) {
                h[i] = 1;
             }
             else h[i] = 0;
        }else{
            if(S[i-1] == S[h[i-1]]) h[i] = h[i-1]+1;
            else h[i] = 0;
        }
    }
}

//find S in T
vector<int> kmp(string T, string S){
    vector<int> ans;
    int k = 0;
    init(S);
    int i = 0;
    while(i < T.size()){
        if(S[k] == T[i]){
            k++;
            i++;
        }else{
            if(h[k] == 0){
                k = 0;
                i++;
            }else{
                k = h[k];
            }
        }
        if(k == S.size()){
            ans.push_back(i-S.size());
            k = h[k];
        }
    }
    return ans;
}

struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

