string unit(string s) {
    int n = s.length();
    string res = s;

    auto strstr = [&](string sub, string s) {
	int n = s.length();
	int m = sub.length();
	if (n%m) return false;
	for (int i=0; i<n; i++) {
	    if (s[i] != sub[i%m]) return false;
	}
	return true;
    };

    for (int i=1; i*i<=n; i++) {
	if (n%i==0) {
	    string cur = s.substr(0,i);
	    if (strstr(cur, s)) {
		if (cur.length() < res.length()) {
		    res = cur;
		}
	    }
	    if (i>1 && n/i!=i) {
		string cur = s.substr(0, n/i);
		if (strstr(cur, s)) {
		    if (cur.length() < res.length()) {
			res = cur;
		    }
		}
	    }
	}
    }

    return res;
}

bool contained(string s, string t) {
    s = unit(s);
    t = unit(t);
    int n = s.length();
    int m = t.length();
    if (n%m) return false;

    for (int i=0; i<n; i++) {
	if (s[i] != t[i%m]) return false;
    }
    return true;
}


