#include <bits/stdc++.h>

std::vector<int> MPAlgorithm(const std::string& str)
{
	std::vector<int> vec(str.size() + 1);
	vec[0] = -1;
	for (int i{}; i < (int)str.size(); i++)
	{
		int prev{vec[i]};
		while (prev >= 0 && str[prev] != str[i]) prev = vec[prev];
		vec[i + 1] = prev + 1;
	}
	return std::move(vec);
}

std::vector<int> edges, length, rootTable;
int dfs(int, int);

int main()
{
	std::string S, T;
	std::cin >> S >> T;
	auto mp{MPAlgorithm(T)};
	edges.resize(S.size(), -1);
	for (int t_i{}, s_i{}; s_i <= (int)(S.size() + T.size()); s_i++)
	{
		while (t_i >= 0 && T[t_i] != S[s_i % (int)S.size()]) t_i = mp[t_i];
		t_i++;
		if (t_i != (int)T.size()) continue;
		edges[(s_i - (int)T.size() + 1) % (int)S.size()] = (s_i + 1) % (int)S.size();
		t_i = mp[t_i];
	}
	length.resize(S.size(), -1);
	rootTable.resize(S.size(), -1);
	int max{};
	for (int i{}; i < (int)S.size(); i++)
		max = std::max(max, dfs(i, i));
	if (max >= (1 << 30)) puts("-1");
	else printf("%d\n", max);

	return 0;
}

int dfs(int index, int root)
{
	if (index < 0) return -1;
	if (rootTable[index] == root) return 1 << 30;
	rootTable[index] = root;
	if (length[index] >= 0) return length[index];
	length[index] = dfs(edges[index], root) + 1;
	return length[index];
}

