void build(string& model){
	int j=-1;
	fail[0]=-1;
	for(int i=1;i<=model.size();i++){
		while(j>=0 && model[j]!=model[i-1]){
			j=fail[j];
		}

		j++;
		fail[i]=j;
	}
}

void match(string& str,string& model){
	build(model);

	int j=0;
	for(int i=0;i<str.size();i++){
		while(j>=0 && str[i]!=model[j]){
			j=fail[j];
		}

		j++;
		if(j==model.size()){

			found[i-int(model.size())+1]=true;

//			cout<<i-model.size()+2<<endl;
		}
	}
}




int visit[sz]; //0=unvisit 1=visiting 2=visited

int dp[sz];

inline int dfs(int pos){
	if(found[pos]==0){
		return 0;
	}
	if(visit[pos]==1){
		cout<<"-1";
		exit(0);
	}
	if(dp[pos]!=-1){
		return dp[pos];
	}

	visit[pos]=1;

	int ans=dfs((pos+b.size())%sa.size());

	visit[pos]=2;
	return dp[pos]=ans+1;
}

