vector<int> z_algorithm(vector<char> s){
    int n = s.size();
    vector<int> ret(n);
    ret[0] = n;
    int i = 1, j = 0;
    while(i < n){
        while(i+j < n && s[j] == s[i+j]) j++;
        ret[i] = j;
        if(j == 0) {i++; continue;}
        int k = 1;
        while(i+k < n && k+ret[k] < j) {ret[i+k] = ret[k], k++;}
        i += k, j -= k;
    }
    return ret;
}

const int MAX_V = 5e5;
vector<int> es[MAX_V], rs[MAX_V];
vector<int> vs;
vector<bool> used(MAX_V, false);

void add_edge(int from, int to){
    es[from].pb(to), rs[to].pb(from);
}

void dfs(int now){
    used[now] = true;
    for(auto &e: es[now]) if(!used[e]) dfs(e);
    vs.pb(now);
}

bool find_loop(){
    rep(i, MAX_V) if(!used[i]) dfs(i);
    fill(all(used), false);
    rep3(i, (int)vs.size()-1, 0){
        int j = vs[i];
        for(auto &e: rs[j]){
            if(!used[e]) return true;
        }
        used[j] = true;
    }
    return false;
}

vector<int> mp(MAX_V, -1);

int max_path(int now){
    int ret = 0;
    for(auto &e: es[now]){
        if(mp[e] == -1) ret = max(ret, max_path(e)+1);
        else ret = max(ret, mp[e]+1);
    }
    mp[now] = ret;
    return ret;
}

int main(){
    string S, T;
    cin >> S >> T;
    vector<char> s;
    int N = S.size(), M = T.size();
    rep(i, M) s.pb(T[i]);
    int n = 0;
    while(n < N+M){
        rep(i, N) s.pb(S[i]);
        n += N;
    }
    vector<int> res = z_algorithm(s);
    rep(i, N){
        if(res[M+i] >= M){
            int j = (i+M)%N;
            add_edge(i, j);
        }
    }
    if(find_loop()) {cout << -1 << endl; return 0;}
    int ans = 0;
    rep(i, N){
        ans = max(ans, max_path(i));
    }
    cout << ans << endl;
}

