template <intmax_t X = 943681729, intmax_t MOD = 1000000007>
class rolling_hash {
  std::vector<intmax_t> hash, offset;

public:
  rolling_hash(const std::string& s): hash(s.length()+1), offset(s.length()+1) {
    for (size_t i = 0; i < s.length(); ++i)
      hash[i+1] = (hash[i]*X+s[i]) % MOD;

    offset[0] = 1;
    for (size_t i = 1; i <= s.length(); ++i)
      offset[i] = offset[i-1] * X % MOD;
  }

  intmax_t get_base() const { return X; }
  intmax_t get_mod() const { return MOD; }

  intmax_t prefix(size_t i) const {
    // hash of prefix s[0..i-1] (inclusive)
    assert(0 < i);
    return hash[i];
  }

  intmax_t substr(size_t i, size_t j) const {
    // hash of substring s[i..j-1] (inclusive)
    assert(i < j);
    intmax_t res = hash[j];
    res = (res - offset[j-i]*hash[i]) % MOD;
    if (res < 0) res += MOD;
    return res;
  }

  intmax_t inserted(size_t i, int ch) const {
    intmax_t res = 0;
    if (i > 0) res += prefix(i);
    res = (res*X + ch) % MOD;
    size_t n = hash.size()-1;
    if (i < n) res = (res*offset[n-i] + substr(i, n)) % MOD;
    return res;
  }

  void inspect() const {
    for (size_t i = 0; i < hash.size(); ++i)
      fprintf(stderr, "%jd%c", hash[i], i+1<hash.size()? ' ':'\n');
  }
};

intmax_t pomae(std::string const& s, std::string const& t) {
  using rh0 = rolling_hash<>;
  using rh1 = rolling_hash<943681729, 1000000009>;
  rh0 rs0(s), rt0(t);
  rh1 rs1(s), rt1(t);
  // fprintf(stderr, "%s\n", s.c_str());
  // fprintf(stderr, "%s\n", t.c_str());

  size_t n = s.length();
  size_t m = t.length();

  std::vector<bool> vb(n);
  for (size_t i = 0; i+m <= n; ++i) {
    vb[i] = ((rs0.substr(i, i+m) == rt0.substr(0, m)) && (rs1.substr(i, i+m) == rt1.substr(0, m)));
  }

  std::vector<intmax_t> dp(n+1);
  for (size_t i = m; i <= n; ++i)
    if (vb[i-1]) dp[i] = dp[i-m] + 1;

  // for (size_t i = 0; i < n; ++i)
  //   fprintf(stderr, "%d%c", !!vb[i], i+1<n? ' ': '\n');
  // for (size_t i = 0; i <= n; ++i)
  //   fprintf(stderr, "%jd%c", dp[i], i<n? ' ': '\n');

  return *std::max_element(dp.begin(), dp.end());
}

