class RollingHash {
using ull=unsigned long long;
ull POW(ull a, ull b) { ull c = 1; while (b > 0) { if (b & 1) { c = a * c; }a = a * a; b >>= 1; }return c; }
public:
	vector<ull> hash[2],power[2];
	ull base[2], mod[2];
	RollingHash (string &s) {
		base[0] = 1000000007; base[1] = 999999937;
		mod[0] = 998244353, mod[1] = 1000000009;
		int sz = (int)s.size();
		for (int i=0; i<2; i++) {
			hash[i].assign(sz+1,0);
			power[i].assign(sz+1,0);
			power[i][0] = 1;
		}
		rep (i,sz) {
			for (int j=0; j<2; j++) {
				power[j][i+1] = power[j][i] * base[j] % mod[j];
				hash[j][i+1] = (hash[j][i] * base[j] + s[i]) % mod[j];
			}
		}
	}
	//半開区間!!!
	//abcde
	//hash[0]=0,hash[1]=a,hash[2]=ab,hash[3]=abc;
	//bcならget(1,3)
	pair<ull,ull> get(int l,int r) {
		ull h1 = hash[0][r] - (hash[0][l] * power[0][r - l] % mod[0]) + mod[0];
		ull h2 = hash[1][r] - (hash[1][l] * power[1][r - l] % mod[1]) + mod[1];
		h1 %= mod[0], h2 %= mod[1];
		return {h1, h2};
	}
};

