std::vector<int> KMP_all(const std::string& S_raw, const std::string& W){
  std::string S(S_raw);
  if(S_raw.size() > W.size()){
    S += S_raw.substr(0, W.size());
  }else{
    while(S.size() < S_raw.size()+W.size()-1){
      S += S_raw;
    }
  }
  std::vector<int> T(W.size());
  T[0] = -1;
  int i = 2, j = 0;
  while(i < W.size()){
    if(W[i-1] == W[j]){
      T[i] = j+1;
      i++;
      j++;
    }else if(j > 0){
      j = T[j];
    }else{
      T[i] = 0;
      i++;
    }
  }
  i = 0;
  int m = 0;
  std::vector<int> ans(S_raw.size());
  while(m < S.size()){
    if(W[i] == S[m+i]){
      i++;
      if(i == W.size()){
        i--;
        ans[m] = 1;
        m = m+i-T[i];
        if(i > 0) i = T[i];
      }
    }else{
      m = m+i-T[i];
      if(i > 0) i = T[i];
    }
  }
  return ans;
}

