struct KMP {
	std::string W;	//検索する文字列
	std::vector<int> T;	//テーブル
public:
	//計算量:O(|W|)
	KMP(const std::string& W_) :W(W_) {
		T.resize(W.size() + 1);
		int i = 2;		//T の中で現在計算している位置
		int j = 0;		//現在見ているサブ文字列の次の文字のインデックス。0から始まる
		//先頭ふたつの値は固定。ただしアルゴリズムの実装によっては具体的値は異なる
		T[0] = -1;
		if (2 <= W.size()) {
			T[1] = 0;
		}
		while (i <= W.size()) {
			if (W[i - 1] == W[j]) {
				T[i] = j + 1;
				i = i + 1;
				j = j + 1;
			}
			else if (j > 0) {
				j = T[j];
			}
			else {
				T[i] = 0;
				i = i + 1;
			}
		}
	}
	//return: W が見つかった際の S 内の位置を全列挙(先端が0番目)
	//全列挙でも計算量的に問題ない
	//Sを変えて複数回呼べる
	//計算量:O(|S|)
	std::vector<int> searchAll(const std::string& S)const {
		std::vector<int>res;
		//S 内の現在照合中の開始位置
		int m = 0;
		//W 内の現在位置
		int i = 0;
		while (m + i < S.size()) {
			if (W[i] == S[m + i]) {
				++i;
				if (i == W.size()) {
					res.push_back(m);
				}
				else {
					continue;
				}
			}
			m = m + i - T[i];
			if (i > 0) {
				i = T[i];
			}
		}
		return res;
	}
};










void proc() {
	LOAD(std::string, s);
	LOAD(std::string, t);
	int K = (t.size() + s.size() - 1) * 2 / s.size();
	MAX(K, 3LL);
	std::string ss;
	for (int k = 0; k < K; ++k) {
		ss += s;
	}
	KMP kmp(t);
	std::vector<bool>val(s.size());
	fill(ALL(val), false);
	auto reses = kmp.searchAll(ss);
	for (int i = 0; i < reses.size(); ++i) {
		val[reses[i] % s.size()] = true;
	}
	int res = 0;
	for (int i = 0; i < s.size(); ++i) {
		if (!val[i])continue;
		int L = 0, R = 0;
		int pos = i;
		bool loop = false;
		do {
			val[pos] = false;
			pos = mod(pos - t.size(), s.size());
			if (pos == i) {
				loop = true;
				break;
			}
			++L;
		} while (val[pos]);
		pos = i;
		do {
			val[pos] = false;
			pos = mod(pos + t.size(), s.size());
			if (pos == i) {
				loop = true;
				break;
			}
			++R;
		} while (val[pos]);
		if (loop) {
			cout << -1 << endl;
			return;
		}
		MAX(res, L + R - 1);
	}

