const int N = 2e6;

int go(string s){
	int m = sz(s);
	int pi[sz(s)*3+5]={0};
	s = s + '#' + s + s;
	int k = 0;
	int n = sz(s);
	rep(i,1,n){
		while(k && s[i]!=s[k]) k = pi[k-1];
		if(s[i]==s[k]) k++;
		if(k==m && i>2*m) return i-2*m;
		pi[i]=k;
	}
}

bool inf(string s, string t){
	int n = go(s);
	int m = go(t);
	if(n==m){
		string s1 = s.substr(0,n);
		string t1 = t.substr(0,n);
		s1 = s1 + '#' + t1 + t1;
		int pi[sz(s1)]={0};
		int k=0;
		n = sz(s1);
		rep(i,1,n){
			if(k && s1[i]!=s1[k]) k = pi[k-1];
			if(s1[i]==s1[k]) k++;
			if(k==m) return 1;
			pi[i]=k;
		}
		return 0;
	}else return 0;
}

int dp[N];
