inline vector<int> buildfail(string p)
{
	int m=p.size(),j=-1;
	vector<int> fail(m+1);

	fail[0]=-1;
	for(int i=1;i<=m;i++)
	{
		while(j>=0&&p[j]!=p[i-1]) j=fail[j];
		fail[i]=++j;

		//if(p[fail[i]]==p[i]&&fail[fail[i]]!=-1) fail[i]=fail[fail[i]];
	}

	return fail;
}

inline vector<int> match(string t,string p,vector<int> fail)
{
	int n=t.size(),m=p.size();
	vector<int> res;res.clear();

	for(int i=0,k=0;i<n;i++)
	{
		while(k>=0&&p[k]!=t[i]) k=fail[k];
		if(++k>=m) res.push_back(i-m+1);
	}

	return res;
}

