vector<int> zAlgorithm(const string &s) {
    int n = (int)s.size(), l = 0, r = 0;
    vector<int> Z(n, n);
    for (int i = 1; i < n; ++i) {
        if (i > r) {
            l = r = i;
        } else if (Z[i - l] >= r - i + 1) {
            l = i;
        } else {
            Z[i] = Z[i - l];
            continue;
        }
        while (r < n&&s[r] == s[r - l])r++;
        Z[i] = r - l; r--;
    }
    return Z;
}

class UnionFind {
    int cnt;
    vector<int> par, rank, size;
public:
    UnionFind() {}
    UnionFind(int _n) :cnt(_n), par(_n), rank(_n), size(_n, 1) {
        for (int i = 0; i<_n; ++i) par[i] = i;
    }
    int find(int k) {
        return (k == par[k]) ? k : (par[k] = find(par[k]));
    }
    int operator[](int k) {
        return find(k);
    }
    int getSize(int k) {
        return size[find(k)];
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return;
        --cnt;
        if (rank[x] < rank[y]) {
            par[x] = y;
            size[y] += size[x];
        } else {
            par[y] = x;
            size[x] += size[y];
            if (rank[y] == rank[x]) ++rank[x];
        }
    }
    int count() {
        return cnt;
    }
};

void solve() {
    string S, T;
    cin >> S >> T;
    int N = sz(S), M = sz(T);

    string s = S;
    while (sz(S) < 2 * M) {
        S += s;
    }

    UnionFind uf(N);
    int ans = 0;
    string TS = T + S;
    auto Z = zAlgorithm(TS);
    rep(i, N) {
        int j = (i + M) % N;
        if (Z[i + M] >= M) {
            uf.unite(i, j);
        }
    }

    vector<bool> vis(N);
    rep(i, N) {
        smax(ans, uf.getSize(i) - 1);
        int cur = i;
        if (vis[cur])continue;
        bool ok = true;
        do {
            vis[cur] = true;
            if (Z[cur + M] < M)ok = false;
            cur = (cur + M) % N;
        } while (cur != i);
        if (ok) {
            cout << -1 << endl;
            return;
        }
    }

    cout << ans << endl;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

