int rabin_karp(string const& s, string const& t) {

    int S = s.size(), T = t.size();
    vector<long long> h1(T + 1),h2(T + 1) , h3( T + 1); 
    for (int i = 0; i < T; i++){
        h1[i+1] = (h1[i] + (t[i] - 'a' + 1) * p_pow1[i]) % m1; 
        h2[i+1] = (h2[i] + (t[i] - 'a' + 1) * p_pow2[i]) % m2; 
        h3[i+1] = (h3[i] + (t[i] - 'a' + 1) * p_pow3[i]) % m2;}
    long long h_s1=0,h_s2= 0 , h_s3=0; 
    for (int i = 0; i < S; i++){
        h_s1 = (h_s1 + (s[i] - 'a' + 1) * p_pow1[i]) % m1; 
        h_s2 = (h_s2 + (s[i] - 'a' + 1) * p_pow2[i]) % m2; 
        h_s3 = (h_s3 + (s[i] - 'a' + 1) * p_pow3[i]) % m2;}


    vector<int>p;
    for (int i = 0; i + S - 1 < T; i++) { 
        long long cur_h1 = (h1[i+S] + m1 - h1[i]) % m1; 
        long long cur_h2 = (h2[i+S] + m2 - h2[i]) % m2; 
        long long cur_h3 = (h3[i+S] + m2 - h3[i]) % m2; 
        if( (cur_h1 == h_s1 * p_pow1[i] % m1)&&(cur_h2 == h_s2 * p_pow2[i] % m2)&& (cur_h3 == h_s3 * p_pow3[i] % m2) )
        {
			//cout<<i<<" ";
			p.push_back(i);


		}

    }
    //cout<<endl;

    int mx=0;
    int i=0;
    int size=p.size();
    while( i < size )
    {
		int cnt=1;
		int j=i;
		while( j+1 <size && p[j+1]==p[j]+S )
		{
			cnt++;
			j++;
		}
		mx=max(cnt,mx);
		i=j+1;
	}
    return mx;
}
