int main()
{
    string s, t;
    cin>>s>>t;

    string tmp = s;
    while (s.length() < t.length())
        s += tmp;

    string s2 = s+s;
    vector<int> Z = z_algorithm(t+s2);

    vector<bool> f(s.size());
    for (int i=0; i<(int)s.size(); i++)
        f[i] = Z[t.size()+i] >= t.size();

    vector<int> memo(s.size(), -1);
    function<int(int)> BT = [&](int p)
    {
        if (memo[p]==-2)
            return -1;
        if (memo[p]!=-1)
            return memo[p];
        memo[p] = -2;
        if (!f[p])
            return memo[p]=0;
        int r = BT((p+t.size())%s.size());
        if (r==-1)
            return -1;
        return memo[p] = r+1;
    };
    int ans = 0;
    for (int i=0; i<(int)s.size(); i++)
    {
        int r = BT(i);
        if (r==-1)
        {
            cout<<-1<<endl;
            return 0;
        }
        ans = max(ans, r);
    }
    cout<<ans<<endl;
}

