vector<int>TopologicalSort(int n,vector<int>in,vector<int>e[]) {
	stack<int>st;
	for (int i = 0; i < n; i++)if (!in[i])st.push(i);
	vector<int>ret;
	while (st.size()) {
		int i = st.top();
		st.pop();
		ret.pb(i);
		fore(x, e[i]) {
			in[x]--;
			if (!in[x])st.push(x);
		}
	}
	return ret;
}

int A[10101010];
vector<int>beg(10101010);
void preKmp(string x) {
	A[0] = -1;
	int j = -1;
	for (int i = 0; i < x.size(); i++) {
		while (j >= 0 && x[i] != x[j])j = A[j];
		j++;
		if (x[i + 1] == x[j])A[i + 1] = A[j];
		else A[i + 1] = j;
	}
}
void Kmp(string x, string y) {
	preKmp(x);
	int xind = 0;
	for (int yind = 0; yind < y.size(); yind++) {
		while (xind >= 0 && x[xind] != y[yind])xind = A[xind];
		xind++;
		if (xind == x.size()) {
			beg[yind - x.size() + 1]++;
			xind = A[xind];
		}
	}
}

