	for (int i = 0; i < S.size(); i++) {
		if (beg[i]){
			int to = (i + T.size()) % S.size();
			edge[i].pb(to);
			in[to]++;
		}
	}


	vector<int>ord = TopologicalSort(S.size(),in,edge);
	if (ord.size() != S.size()) {
		puts(-1);
		return 0;
	}

	int ans = 0;
	for (int i = 0; i < S.size()-1; i++) {
		int cur = ord[i];
		fore(to, edge[cur]) {
			dp[to] = max(dp[to], dp[cur] + 1);
			ans = max(ans, dp[to]);
		}
	}
	puts(ans);

	return 0;
}

