// prefix function O(n) (kmp algorithm)
// from https://cp-algorithms.com/string/prefix-function.html
vector<int> prefix_function(string s) {
    int n = (int)s.length();
    vector<int> pi(n);
    for (int i = 1; i < n; i++) {
        int j = pi[i-1];
        while (j > 0 && s[i] != s[j])
            j = pi[j-1];
        if (s[i] == s[j])
            j++;
        pi[i] = j;
    }
    return pi;
}

// verified with https://codeforces.com/contest/1138/problem/D
int min_period_of_string(string s) {
  int n=s.length();
  vector<int> pi=prefix_function(s);
  return n-pi[n-1];
}

// https://www.coursera.org/lecture/algorithms-on-strings/knuth-morris-pratt-algorithm-73RS1
// expects p and t dont include '$'
vector<int> mp_pattern_search(string p, string t) {
  string s = p+'$'+t;
  vector<int> pi=prefix_function(s);
  vector<int> ret;
  for(int i=p.size()+1;i<s.size(); i++)
    if(pi[i]==p.size())
      ret.push_back(i-2*p.size());
  return ret;
}

