template<typename T>
class KMP{
    vector<int> a;
    T s;

public:
    KMP(T s_arg): s(s_arg){
        int n = s_arg.size();
        a = vector<int>(n+1, -1);   // a[j+1]が[0, j]のboarderの最大の長さ
        constructBorderArray();
    }

    void constructBorderArray(){
        int j = -1;
        for(int i = 0; i < s.size(); i++){
            while(j >= 0 && s[i] != s[j]){
                j = a[j];
            }

            j++;
//            if(s[i+1] == s[j]) a[i+1] = a[j];
//            else a[i+1] = j;
            a[i+1] = j;
        }
    }

    /**
     *
     * @param x: sとマッチングさせる配列
     * @return : マッチング位置
     */
    vector<int> search(T x, int pos=0){
        int j = 0;
        vector<int> res;
        for(int i = pos; i < x.size(); i++){
            while(j >= 0 && x[i] != s[j]){
                j = a[j];
            }
            j++;
            if(j == s.size()){
                res.push_back(i - j + 1);
                j = a[j];
            }
        }
        return res;
    }

    int periodicity(int pos){
        return pos - a[pos];
    }
};


int main(){
    string s, t;    cin >> s >> t;
    string s2 = s;
    while(s2.length() < t.length() + s.length() - 1){
        s2 += s;
    }

    KMP<string> kmp{t};
    vector<int> res = kmp.search(s2);
    vector<int> nextPos(s.length(), -1);

    for(auto pos: res){
        if(pos >= s.length()){
            break;
        }
        int remain = s2.length() - pos - t.length();
        if(remain > s.length()){
            nextPos[pos] = 2 * s.length() - remain;
        }
        else {
            nextPos[pos] = s.length() - remain;
        }
    }

    vector<int> posNum(s.length(), 0);
    vector<bool> state(s.length(), false);
    for(int i = 0; i < s.length(); i++){
        int x = i;
        deque<int> que;
        int num = 0;
        while(true){
            if(!que.empty() && que.front() == x){     // ループを検知
                cout << -1 << endl;
                return 0;
            }

            if(state[x]){
                num = posNum[x];
                break;
            }

            state[x] = true;
            if(nextPos[x] == -1){
                break;
            }
            que.push_back(x);
            x = nextPos[x];
        }

        while(!que.empty()){
            x = que.back(); que.pop_back();
            posNum[x] = ++num;
        }
    }

    int ret = 0;
    for(int i = 0; i < s.length(); i++){
        ret = max(posNum[i], ret);
    }

    cout << ret << endl;



