int solve(const string &s, const string &t, unsigned long ls, unsigned long lt) {
  int ret = 0;
  vector<bool> seen(ls, false);

  rep (i, ls) {
    if (seen[i]) continue;

    int j = 0;
    while (s.compare(i + j * lt, lt, t) == 0) {
      seen[i + j * lt] = true;
      if (j * lt >= ls) {
        return -1;
      }
      j += 1;
    }
    ret = max(ret, j);
  }
  return ret;
}

