ll modExp(ll base, ll power) {
    if (power == 0) {
        return 1;
    } else {
        ll cur = modExp(base, power / 2); cur = cur * cur; cur = cur % MOD;
        if (power % 2 == 1) cur = cur * base;
        cur = cur % MOD;
        return cur;
    }
}

ll inv(ll base) {
    return modExp(base, MOD-2);
}

ll mul(ll A, ll B) {
    return (A*B)%MOD;
}

ll add(ll A, ll B) {
    return (A+B)%MOD;
}

ll dvd(ll A, ll B) {
    return mul(A, inv(B));
}

ll sub(ll A, ll B) {
    return (A-B+MOD)%MOD;
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);

    string S, T; cin >> S >> T;
    int N = sz(S), M = sz(T);
    int total = 0, count = 0;
    while (total < M) {
        total += N; count++;
    }
    total += N; count++;

    string L(count*N, '*');
    int K = sz(L);
    F0R(i, K) {
        L[i] = S[i % N];
    }

    ll hsh = 805306457;

    ll hashT = 0;
    F0Rd(i, M) {
        hashT *= hsh; hashT %= MOD;
        hashT += T[i] - 'a'; hashT %= MOD;
    }

    ll hashS = 0;
    ll bigPower = modExp(hsh, M);
    bool valid[N]; F0R(i, N) valid[i] = false;
    //cout << hashT << endl;
    F0Rd(i, K) {
        hashS = mul(hashS, hsh);
        hashS = add(hashS, L[i] - 'a');
        if (i + M < K) {
            hashS = sub(hashS, mul(L[i+M] - 'a', bigPower));
        }
        if (i < N && hashS == hashT) {
            valid[i] = true;
            //cout << i << " is valid" << endl;
        }
        //cout << i << " " << hashS << endl;

    }



    int starter[N]; F0R(i, N) starter[i] = 0;


    int succ[N]; F0R(i, N) succ[i] = -1;
    F0R(i, N) {
        if (valid[i]) {
            //cout << i << " is valid" << endl;
            succ[i] = (i+M)%N;
            starter[(i+M)%N]++;
        }
    }

    queue<int> q;
    int dist[N]; F0R(i, N) dist[i] = -1;
    F0R(i, N) {
        if (starter[i] == 0) {
            dist[i] = 0;
            q.push(i);
        }
    }

    while (!q.empty()) {
        int cur = q.front(); q.pop();
        if (succ[cur] == -1) continue;
        int nxt = succ[cur];
        starter[succ[cur]]--;
        dist[nxt] = max(dist[nxt], dist[cur] + 1);
        if (starter[nxt] == 0) {
            q.push(nxt);

        }
    }

    int bestDist = -1;
    F0R(i, N) {
        bestDist = max(bestDist, dist[i]);
        if (dist[i] == -1) {
            cout << -1 << endl; return 0;
        }
    }

    cout << bestDist << endl;




    return 0;
}

