VL Zalgo(const string &S) {
    int N = (int)S.size();
    VL res(N);
    res[0] = N;
    int i = 1, j = 0;
    while(i < N) {
        while(i + j < N && S[j] == S[i + j]) ++j;
        res[i] = j;
        if(j == 0) {
            ++i;
            continue;
        }
        int k = 1;
        while(i + k < N && k + res[k] < j) res[i + k] = res[k], ++k;
        i += k, j -= k;
    }
    return res;
}

VVL G;
VB used, nused;
set<ll> st;
VL hist;
bool finished[1000];
ll start = -1;

void findroop(int v) {
    used[v] = true;
    hist.emplace_back(v);
    FOREACH(to, G[v]) {
        if(finished[to]) continue;
        if(used[to]) {
            start = to;
            return;
        }
        findroop(to);
        if(start != -1) return;
    }
    hist.pop_back();
    finished[v] = true;
}

bool dfs(ll now) {
    st.emplace(now);
    used[now] = true;
    bool res = true;
    FOREACH(to, G[now]) {
        if(res == false) break;
        if(st.find(to) != st.end()) return false;
        res &= dfs(to);
    }
    return res;
}

ll dfs2(ll now, ll par) {
    used[now] = true;
    ll res = 0;
    FOREACH(to, G[now]) {
        if(to == par || used[to]) continue;
        res = max(res, dfs2(to, now) + 1);
    }
    return res;
}

signed main() {
    SCIN(S, T);
    string tmp = S;
    while(tmp.length() < T.length()) {
        tmp += S;
    }
    VL z = Zalgo(T + "$" + tmp + tmp);
    ll N = tmp.length();
    G.resize(N);
    REP(i, N) {
        if(z[T.length() + 1 + i] == T.length()) {
            G[i].emplace_back((i + T.length()) % N);
        }
    }
    used.assign(N, false);
    ll ans = 0;
    REP(i, N) {
        if(used[i]) continue;
        findroop(i);
        if(start != -1) eputs(-1);
    }
    used.assign(N, false);
    REP(i, N) {
        if(used[i]) continue;
        st.clear();
        dfs(i);
        ans = max(ans, (ll)st.size() - 1);
    }
