// kmp をやるための前計算
std::vector<ll> makeTable(const std::string& s) {
    ll n = s.size();
    std::vector<ll> ret(n+1);
    ret[0] = -1;
    ll j = -1;
    for (ll i = 0; i < n; i++) {
        while (j >= 0 && s[i] != s[j]) j = ret[j];
        ret[i+1] = ++j;
    }
    return ret;
}

// str の中に word とマッチする場所のリストを返す
// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す
std::vector<ll> kmp(const std::string& str, const std::string& word) {
    std::vector<ll> table = makeTable(word), ret;
    ll m = 0, i = 0, n = str.size();
    while (m+i < n) {
        if (word[i] == str[m+i]) {
            if (++i == (ll)(word.size())) {
                ret.push_back(m);
                m = m+i-table[i];
                i = table[i];
            }
        } else {
            m = m+i-table[i];
            if (i > 0) i = table[i];
        }
    }
    return ret;
}

//非再帰トポロジカルソート 隣接リストを渡す 返り値のサイズがnじゃないならnot DAG
std::vector<ll> topo_sort(std::vector<std::vector<ll>>& graph){
  ll n=graph.size();
  std::vector<ll> ret,num(n,0);
  std::queue<ll> que;
  rep(i,0,n){
    for(ll j:graph[i])num[j]++;
  }
  rep(i,0,n){
    if(num[i]==0)que.push(i);
  }
  while(!que.empty()){
    ll u=que.front();que.pop();
    ret.push_back(u);
    for(ll i:graph[u]){
      num[i]--;
      if(num[i]==0)que.push(i);
    }
  }

  return ret;
}

