class RollingHash {
using ull=unsigned long long;
ull POW(ull a, ull b) { ull c = 1; while (b > 0) { if (b & 1) { c = a * c; }a = a * a; b >>= 1; }return c; }
public:
	vector<ull> hash,power;
	RollingHash (string &s, ull base = 1000000007) {
		int sz = (int)s.size();
		hash.assign(sz+1,0);
		power.assign(sz+1,0);
		power[0] = 1;
		rep (i,sz) {
			power[i+1] = power[i] * base;
			hash[i+1] = hash[i] * base + s[i];
		}
	}
	//半開区間!!!
	//abcde
	//hash[0]=0,hash[1]=a,hash[2]=ab,hash[3]=abc;
	//bcならget(1,3)
	ull get(int l,int r) {
		return hash[r] - (hash[l] * power[r - l]);
	}
};

