ll bigMod (ll a, int e){
  if (e == -1) 
    e = MOD - 2;
  ll r = 1;
  while (e) {
      if (e & 1) r = (r * a) % MOD;
      a = (a * a) % MOD, e >>= 1;
  }
  return r;
}

ll getHash (int l, int r) 
{
    ll ret = ((h[r] - h[l - 1]) * inv[l - 1]) % MOD;
    if (ret < 0) ret += MOD;
    return ret;
}

