	cin >> s >> t;
	int n = s.size(), m = t.size();

	///
	Vec< int > s_fail = makeKMPfail(s);
	Vec< int > t_fail = makeKMPfail(t);
	int sp = n - s_fail[n], tp = m - t_fail[m];
	if (n % sp == 0 && m % tp == 0) {
		if (sp == tp && cyclic(s.substr(0, sp), t.substr(0, tp))) {
			puts("-1");
			return 0;
		}
	}
//	cerr << "sp " << sp << endl;
//	cerr << "tp " << tp << endl;

	///
	string x = s;
	while (x.size() < t.size()) x += x;
	for_(i,0,8) x += x;
	int N = x.size();
//	cerr << x << endl;
//	cerr << t << endl;

	Vec< bool > match(N, false);
	for (int i=0, k=0; i < N; ++i) {
		while (k >= 0 && t[k] != x[i]) k = t_fail[k];
		if (++k >= m) {
			match[i-1] = true;
			k = t_fail[k];
		}
	}

	int ans = 0;
	for_(i,0,N) {
		if (match[i]) {
			int j = i, cnt = 0;
			while (j < N && match[j]) {
				match[j] = false;
				j += m;
				++cnt;
			}
			ans = max(ans, cnt);
		}
	}
	cout << ans << endl;
}
