bool dfs(ll now, ll par) {
    st.emplace(now);
    used[now] = true;
    bool res = true;
    FOREACH(to, G[now]) {
        if(res == false) break;
        if(to == par) continue;
        if(st.find(to) != st.end()) return false;
        res &= dfs(to, now);
    }
    return res;
}

ll dfs2(ll now, ll par) {
    used[now] = true;
    ll res = 0;
    FOREACH(to, G[now]) {
        if(to == par || used[to]) continue;
        res = max(res, dfs2(to, now) + 1);
    }
    return res;
}

