    kmp_pre(x,m,Next);
    i=j=0;
    while(i<n){
        while(j!=-1&&y[i]!=x[j]) j=Next[j];
        i++,j++;
        if(j>=m){
            ans++;
            j=Next[j];
            vis[i-m]=1;
        }
    }
    return ans;
}
