const int M = 5e5 + 10;
vi graph[M], sorted;
int valid[M] = {0}, n, m, visited[M] = {0};

void stringMatching(string s, string t)
{
    string a = t + '#' + s;
    int n = a.size();
    int z[n]; z[0] = 0;

    int l = 0, r = 0;
    FOR(i,1,n)
    {
        if (i > r)
        {
            l = r = i;
            while (r < n and a[r] == a[r-l]) ++r;
            z[i] = r-l; --r;
        }

        else
        {
            if (z[i-l] < r-i+1) z[i] = z[i-l];

            else
            {
                l = i;
                while (r < n and a[r-l] == a[r]) ++r;
                z[i] = r-l; --r;
            }
        }
    }

    FOR(i,0,n)
    {
        if (z[i] == t.size()) 
            valid[i-t.size()-1] = 1;
    }
}

bool isCycle(int curr, int code)
{
    visited[curr] = code;
    int next = (curr + m)%n;
    if (not valid[next])
    {
        sorted.pb(curr); 
        return false;
    }

    if (visited[next] == code) return true;
    if (visited[next] == 0 and isCycle(next, code)) return true;

    sorted.pb(curr);
    return false;
}

int dfs(int curr, int len)
{
    visited[curr] = 1;
    int next = (curr + m)%n;
    if (not valid[next]) return len;

    return dfs(next, len+1);
}

int solve(string x, string y)
{
    n = x.size(); m = y.size(); int req = n+m;
    string t = y, s = x;

    while (s.size() < req) s += x; 
    stringMatching(s,t);

    int code = 1;
    FOR(i,0,n)
    {
        if (valid[i] and visited[i] == 0)
        {
            if (isCycle(i,code)) return -1;
            ++code;
        }
    }
    if (sorted.size() == 0) return 0;

    int ans = 0;
    FOR(i,0,n) visited[i] = 0;
    FORR(i,sorted.size()-1,-1)
    {
        int curr = sorted[i];
        if (valid[curr] and not visited[curr]) ans = max(ans, dfs(curr, 1));
    }

    return ans;
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    string s,t; cin >> s >> t;
    cout << solve(s,t);
    return 0;
}

