bool check_atom (string &s, int d) {
	ss = "";
	for (int i = 0; i < d; ++i)
		ss += s[i];
	string sss = ss;
	while ((int) ss.size() < (int) s.size())
		ss += sss;
	if (ss == s) {
		ss = sss;
		return true;
	}
	return false;
}
const int p = 31; 
const int m = 1e9 + 9;
int p_pow[(int) 1e6 + 55]; 
int h[(int) 1e6 + 55];
bool rabin_karp(string s, string t, int repeat) {
    int S = s.size(), T = t.size();
    if (S * repeat > T)
    	return false;
    string ss = s;
    for (int i = 0; i < repeat - 1; ++i)
    	ss += s;
    s = ss;
    S = (int) s.size();
    long long h_s = 0; 
    for (int i = 0; i < S; i++) 
        h_s = (h_s + (s[i] - 'a' + 1) * p_pow[i]) % m; 
    for (int i = 0; i + S - 1 < T; i++) { 
        long long cur_h = (h[i+S] + m - h[i]) % m; 
        if (cur_h == h_s * p_pow[i] % m)
			return true;            
    }
    return false;
}
void solve() {
	p_pow[0] = 1; 
	for (int i = 1; i < (int) 1e6 + 55; i++) 
		p_pow[i] = (p_pow[i-1] * p) % m;
	string s, t;
	cin >> s >> t;
	auto D = generate_divisors((int) s.size());
	sort(D.begin(), D.end());
	for (auto d : D) {
		if (!check_atom(s, d))
			continue;
		string sss = ss;
		while ((int) sss.size() < (int) t.size())
			sss += ss;
		if (sss == t) {
			cout << -1;
			return;
		}
	}
	s += s;
	h[0] = 0;
    for (int i = 0; i < (int) s.size(); i++)
        h[i+1] = (h[i] + (s[i] - 'a' + 1) * p_pow[i]) % m; 
    int lo = 0, hi = 1e6 + 55;
    int ans = 0;
    while (lo < hi - 1) {
    	int mid = (lo + hi) >> 1;
    	if (rabin_karp(t, s, mid)) {
    		lo = mid;
    	}
    	else {
    		hi = mid - 1;
    	}
    }
    for (int i = hi; i >= lo; --i) {
    	if (rabin_karp(t, s, i)) {
    		cout << i << endl;
    		return;
    	}
    }
    cout << 0;
}

