void kmp_pre(char s[],int m,int nxt[])
{
	int i = 0, j = nxt[0] = -1;
	while(i<m)
	{
		while(j!=-1&&s[i]!=s[j]) j = nxt[j];
		nxt[++i] = ++j;
	}
}
void kmp_work(char s[],int m,char t[],int n) 
{
	int i = 0, j = 0;
	kmp_pre(s, m, nxt);
	while(i<n)
	{
		while(j!=-1&&t[i]!=s[j]) j = nxt[j];
		i++; j++;
		if(j>=m)
		{
			ok[i-m] = 1;
			j = nxt[j];
		}
	}
}
int main()
{
