vector<bool> starts_with(string s, string t, long long x) {
    int n = (int)s.size(), m = (int)t.size();
    long long prime = 1000000007;
    auto mod = [&](long long a) {
        return (a % prime + prime) % prime;
    };
    x = mod(x);
    if (x == 0) {
        x = 1;
    }
    function<long long (long long, long long)> pow = [&](long long a, long long r) {
        if (r == 0) return 1LL;
        long long y = pow(a, r/2);
        long long z = mod(y * y);
        return r % 2 == 1 ? mod(a * z) : z;
    };
    long long inv_x = pow(x, prime-2);
    long long t_sig = 0LL;
    long long x_pow = 1; // x_pow = x^i during the loop
    for (int i = 0; i < m; ++i) {
        t_sig = mod(t_sig + x_pow * t[i]);
        x_pow = mod(x_pow * x);
    }
    x_pow = 1;
    long long s_sig = 0LL;
    for (int i = 0; i < m; ++i) {
        s_sig = mod(s_sig + x_pow * s[i%n]);
        x_pow = mod(x_pow * x);
    }
    vector<bool> equal(n, false);
    for (int i = 0; i < n; ++i) {
        equal[i] = t_sig == s_sig;
        s_sig = mod(s_sig + x_pow * s[(i+m)%n] - s[i]);
        s_sig = mod(s_sig * inv_x);
    }
    return equal;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    mt19937 rng(chrono::system_clock::now().time_since_epoch().count());
    string s, t;
    cin >> s >> t;
    int n(s.size()), m(t.size());
    vector<bool> equal(n, true);
    for (int k = 0; k < 5; ++k) { // doing 5 checks
        vector<bool> equal_check = starts_with(s, t, rng());
        for (int i = 0; i < n; ++i) {
            equal[i] = equal[i] && equal_check[i];
        }
    }
    bool cycle_found = false;
    vector<int> color(n, -1);
    vector<int> max_length(n, -1);
    function<void (int, int)> dfs = [&](int i, int c) {
        color[i] = c;
        if (!equal[i]) {
            max_length[i] = 0;
            return;
        }
        int j = (i + m) % n;
        if (color[j] == c) {
            cycle_found = true;
        }
        if (color[j] == -1) {
            dfs(j, c);
        }
        max_length[i] = 1 + max_length[j];
    };
    for (int i = 0; i < n; ++i) {
        if (max_length[i] == -1) {
            dfs(i, i);
        }
    }
    if (cycle_found) {
        cout << -1 << endl;
    } else {
        cout << *max_element(max_length.begin(), max_length.end()) << endl;
    }
    return 0;
}

