struct rolling_hash{
    private:
        ll b = 10007;
        vector<vector<ll>> hash;
        int MAX_L = 5000000;
        vector<ll> b_pow;

    public:
        void init(){
            hash={};
            b_pow={1};
            rep(i,MAX_L){
                b_pow.push_back(b_pow.back()*b%mod);
                //cout << b_pow.back() << endl;
            }
        }

        void make_hash(string s){
            int l=s.length();
            vector<ll> h;
            h.push_back(0);
            rep(i,l){
                h.push_back((h.back()*b%mod+s[i])%mod);
                //cout << i << " " << h.back() << endl;
            }
            hash.push_back(h);
        }

        bool same(int a1,P d1,int a2,P d2){
            int l1=d1.first,r1=d1.second,l2=d2.first,r2=d2.second;
            if (r1-l1 != r2-l2) return false;
            ll h1=(hash[a1][r1]-b_pow[r1-l1]*hash[a1][l1]%mod)%mod,h2=(hash[a2][r2]-b_pow[r2-l2]*hash[a2][l2]%mod)%mod;
            if (h1<0) h1+=mod;if (h2<0) h2+=mod;
            //cout << h1 << " " << h2 << endl;
            if (h1==h2) return true;
            return false;
        }

};

