void make_parent(const V<ll> linklist[], ll root, ll n,
                 ll parent[], ll level[])
{
    queue<ll> q;
    bool checked[n+1];

    memset(checked, 0, sizeof(checked));

    q.push(root);
    checked[root] = true;
    parent[root] = root;
    level[root] = 0LL;

    for ( ; !(q.empty()); ) {
        ll now = q.front(); q.pop();
        for (auto next : linklist[now]) {
            if (checked[next]) continue;
            q.push(next);
            checked[next] = true;
            parent[next] = now;
            level[next] = level[now] + 1LL;
        }
    }
}

#define POW_ANCESTOR_MAXSIZE   20

// preprocess for get_common_ancestor()
void make_pow_ancestor(const ll parent[], ll n,
                       ll (*pow_ancestor)[POW_ANCESTOR_MAXSIZE])
{
    rep (i, n) pow_ancestor[i+1][0] = parent[i+1];

    for (int pow2 = 1; pow(2, pow2) <= n; ++pow2) {
        rep (i0, n) {
            int i = i0+1;
            ll prev = pow_ancestor[i][pow2-1];
            pow_ancestor[i][pow2] = pow_ancestor[prev][pow2-1];
        }
    }
}

ll get_common_ancestor(ll n, ll x, ll y,
                       const ll (*pow_ancestor)[POW_ANCESTOR_MAXSIZE],
                       const ll level[])
{
    if (level[x] < level[y]) {
        ll diff = level[y] - level[x];
        for ( ; diff; ) {
            ll bit = diff & -diff;
            y = pow_ancestor[y][(int)log2(bit)];
            diff -= bit;
        }
    }
    else {
        ll diff = level[x] - level[y];
        for ( ; diff; ) {
            ll bit = diff & -diff;
            x = pow_ancestor[x][(int)log2(bit)];
            diff -= bit;
        }
    }

    if (x == y) return x;

    rrep (i, (int)log2(n)+1) {
        if (pow_ancestor[x][i] != pow_ancestor[y][i]) {
            x = pow_ancestor[x][i];
            y = pow_ancestor[y][i];
        }
    }

    return pow_ancestor[x][0];
}

void kmp_init(const string &pattern, ll kmp_next[])
{
    kmp_next[0] = 0LL;

    ll plen = pattern.size();

    for (ll shift = 1LL; ; ++shift) {
        ll idx = 0LL;
        for ( ; idx + shift < plen; ++idx) {
            if (pattern[idx] != pattern[idx+shift]) break;
        }
        if (idx + shift == plen) break;
        shift += idx;
        kmp_next[shift] = idx;
    }
}

ll kmp_search(const string &text, const string &pattern, const ll kmp_next[])
{
    ll text_size = text.size();
    ll pattern_size = pattern.size();
    ll text_idx = 0LL;
    ll pattern_idx = 0LL;

    assert(pattern_size <= text_size);

    for ( ; text_idx - pattern_idx <= text_size - pattern_size; ) {
        for ( ; pattern_idx < pattern_size; ) {
            if (text[text_idx] != pattern[pattern_idx]) break;
            ++pattern_idx;
            ++text_idx;
        }
        if (pattern_idx == pattern_size) return text_idx - pattern_idx;
        if (pattern[pattern_idx] == pattern[0]) text_idx++;
        pattern_idx = kmp_next[pattern_idx];
    }

    return -1LL; // not found
}

