struct KMP {
	using T = char;

	int P;
	vector<T> word;
	vector<int> fail;

	int adv(int len, const T& nxt) const {
		while (len > 0 && word[len] != nxt)
			len = fail[len];
		return len + int(word[len] == nxt);
	}

	/*
	* Initializes the "failure table" for the search word.
	* For i > 0, fail[i] is the length of the longest proper
	* suffix of word[0, i) that is a prefix of word.
	*/
	KMP(const string& word) : P(word.size()), word(word.begin(), word.end()) {
		fail.resize(P + 1);
		for (int i = 2; i <= P; i++)
			fail[i] = adv(fail[i - 1], word[i - 1]);
	}

	/*
	* Finds all occurences of the search word in the given text.
	* match[i] indicates whether there exists a match starting at
	* index i of text.
	*/
	vector<bool> find(const string& text) const {
		vector<bool> match(text.size());
		for (int i = 0, len = 0; i < sz(text); i++) {
			len = adv(len, text[i]);
			if (len == P) {
				match[i - len + 1] = true;
				len = fail[len];
			}
		}
		return match;
	}
};

int solve(string s, string t) {
	int originalSSize = sz(s);
	while (sz(s) < originalSSize + sz(t)) s += s;

	KMP kmp(t);
	vector<bool> ok = kmp.find(s);
	ok.resize(originalSSize);

	int ans = 0;
	vector<bool> used(sz(ok));
	FOR(i, sz(used)) {
		if (used[i]) continue;
		int x = i;
		vector<int> cur;
		while (!used[x]) {
			used[x] = true;
			cur.push_back(ok[x]);
			x = (x + sz(t)) % sz(ok);
		}
		const int xx = sz(cur);
		FOR(i, xx) cur.push_back(cur[i]);
		int cnt = 0;
		for (auto c : cur) {
			if (c == 1) cnt++;
			if (c == 0) cnt = 0;
			ans = max(ans, cnt);
		}
		if (cnt == sz(cur)) return -1;
	}

	return ans;
}

int main() {
	string s, t; reader(s, t);

	int ans = solve(s, t);
	writerLn(ans);

	return 0;
}

