i64 solve(i64 _count){

    string s, t;
    cin >> s >> t;

    if(!static_cast<bool>(cin))
        return MOD;
#ifdef TEST
    cout << "Case: " << _count << endl;
#endif

    i64 n = s.size();
    RH s_hash(s);
    auto t_hash = RH(t).get();

    auto hashpow = [&](auto x, i64 x_len, i64 y){
        auto z = x;
        using mi641 = ModInt<MOD>;
        using mi642 = ModInt<MOD + 2>;
        auto val = y & 1 ? x : make_pair(mi641(0), mi642(0));
        i64 zl = x_len;
        while(z = RH::connect(z, z, zl), y >>= 1){
            zl <<= 1;
            if(y & 1)
                val = RH::connect(z, val, zl);
        }
        return val;
    };

    s += s;
    auto f = [&](i64 val, i64 i){

        auto th = hashpow(t_hash, t.size(), val);
        i64 target_len = t.size() * val;
        i64 st_size = n - i;
        if(target_len <= st_size)
            return s_hash.get(i, i + st_size) == th;
        target_len -= st_size;
        i64 loop_cnt = target_len / n;
        i64 mod_cnt = target_len % n;
        target_len -= st_size;
        auto st_hash = s_hash.get(i);
        auto loop_hash = hashpow(s_hash.get(), n, loop_cnt);
        auto en_hash = s_hash.get(0, mod_cnt);
        return RH::connect(st_hash, RH::connect(loop_hash, en_hash, n * loop_cnt), st_size) == th;
    };

    i64 ans = 0;
    for(i64 i = 0; i < n; ++i){
        i64 ok = 0, ng = 6e5;
        while(ng - ok > 1){
            i64 mid = (ok + ng) >> 1;
            (f(mid, i) ? ok : ng) = mid;
        }
        chmax(ans, ok);
    }
    cout << (ans == 6e5 - 1 ? -1 : ans) << endl;

    return 0;
}


