struct KMP {
    const std::string& pattern;
    std::vector<int> table;

    explicit KMP(const std::string& p): pattern(p), table(p.size() + 1) {
        table[0] = -1;
        table[1] = 0;

        int i = 2;
        int j = 0;
        while (i < pattern.size()) {
            if (pattern[i - 1] == pattern[j]) {
                table[i] = j + 1;
                i += 1;
                j += 1;
            } else if (j > 0) {
                j = table[j];
            } else {
                table[i] = 0;
                i += 1;
            }
        }
        table[pattern.size()] = j + 1;
    }

    std::vector<int> search(const std::string& text) {
        std::vector<int> matches;
        int m = 0;
        int i = 0;
        while (m + i < text.size()) {
            if (i < pattern.size() && pattern[i] == text[m + i]) {
                i += 1;
            } else {
                if (i == pattern.size()) {
                    matches.push_back(m);
                }
                m = m + i - table[i];
                if (i > 0) {
                    i = table[i];
                }
            }
        }
        return matches;
    }
};


