Int check(Int x){
  Int n=s.size(),m=t.size();
  Int len=m*x;

  auto H=C.pow(x);
  M val=H[0][1]*M(ht.find(0,m));

  memo.clear();
  for(Int i=0;i<n;i++){
    Int j=i+len;
    if(j<=n){
      if(hs.find(i,j)==val.v) return 1;
      continue;
    }
    // [i, j)
    // = [i, n) + [0, n) * k + [0, j % n)
    Int k=(len-(n-i))/n;
    assert(k>=0);
    M res=calc(k,hs.find(i,n),hs.find(0,n));
    res*=M(hs.p[j%n]);
    res+=M(hs.find(0,j%n));
    if(res==val) return 1;
  }

  return 0;
}

