  cin.tie(0);
  ios::sync_with_stdio(false);

  cin>>S>>T;
  {
    string sS;
    while(sS.size()<T.size()){
      sS+=S;
    }
    S=sS;
  }

  int N=S.size();
  int M=T.size();
  vector<ll> Sh(N+1,0),Th(N+1,0);
  nxt.resize(N,-1); ind.resize(N,0);
  rep(i,N)Sh[i+1]=(Sh[i]+S[i]*mod_pow(B,i)%mod)%mod;
  rep(i,M)Th[i+1]=(Th[i]+T[i]*mod_pow(B,i)%mod)%mod;

  auto extract = [&](ll l,ll r,bool f) {
    if(!f) return (Sh[r]-Sh[l]+mod)*mod_pow(mod_pow(B,mod-2),l)%mod;
    else return (Th[r]-Th[l]+mod)*mod_pow(mod_pow(B,mod-2),l)%mod;
  };

  rep(i,N){
    if(i+M<=N){
      if(extract(i,i+M,false)==extract(0,M,true)){
        nxt[i]=(i+M)%N;
      }
    }else{
      int l=N-i;
      if(extract(i,N,false)==extract(0,l,true)&&extract(0,M-l,false)==extract(l,M,true)){
        nxt[i]=(i+M)%N;
      }
    }
