	while (s.size() < t.size())
		s += s;
	int t_sz = t.size();
	int old_sz = s.size();
	s += s;
	string w = t + "#" + s;
	//cout << w << "\n";
	vector <int> vec = kmp(w);

	for (int i = 2+t_sz; i < vec.size(); ++i){
		if (vec[i] == t_sz){
			int b = i - t_sz;
			int a = b - t_sz;

			if (b > old_sz)
				b -= old_sz;
			if (a > old_sz)
				a -= old_sz;
			//cout << a << " -> " << b << "\n";
