    while(tt.size() <= ss.size()) tt += t;
    string r = ss + "$" + tt;
    int tidx = ss.size() + 1; 
    RollingHash rh(r);
    int MAX = 0;
    for(int i = 0; i < len; i++){
        int tmp = rh.LCP(i, tidx);
        MAX = max(MAX, tmp);
    }
    if(MAX >= len) cout << -1 << endl;
    else cout << MAX / m << endl;
}

