V<PLL> ans;

void simulate(ll cur_x, ll cur_y, ll X, ll Y, ll K) {
    while(cur_x < X || cur_y < Y) {
        ll rest = K;
        if(cur_x < X) {
            ll adv = min(rest, X - cur_x);
            cur_x += adv;
            rest -= adv;
        }
        if(cur_y < Y) cur_y += rest;
        ans.emplace_back(cur_x, cur_y);
    }
}

ll solve() {
    ll K, X, Y;
    cin >> K >> X >> Y;
    bool xm = X < 0;
    bool ym = Y < 0;
    X = abs(X);
    Y = abs(Y);
    bool swaped = X < Y;
    if(swaped) swap(X, Y);
    ll sum = X + Y;
    ll mod = (K - (X + Y) % K) % K;
    if(mod % 2 == 1 && K % 2 == 0) return -1;
    if(mod == 0) {
        simulate(0, 0, X, Y, K);
    } else if(mod % 2 == K % 2) {
        ll over = (K - mod) / 2;
        ll cur_y = -over;
        ll cur_x = K - over;
        ans.emplace_back(cur_x, cur_y);
        simulate(cur_x, cur_y, X, Y, K);
    } else {
        ll over = (2 * K - mod) / 2;
        simulate(0, 0, X, Y + mod, K);
        ans.emplace_back(X + over, Y + mod - (K - over));
        ans.emplace_back(X, Y);
    }
    for(auto &&ele : ans) {
        if(swaped) swap(ele.first, ele.second);
        if(xm) ele.first *= -1;
        if(ym) ele.second *= -1;
    }
    return ans.size();
}

