map<int, int> memo;

int dfs(int i){
  assert(i<=n-1);
  if (memo[i]>0) return memo[i];

  used[i] = 1;
  int ni = (i+m)%n;
  if (used[ni] && memo[ni]==0){
    memo[i] = INF;
    return memo[i];
  }
  else if(used[ni] && memo[ni]>0){
    memo[i] = memo[ni]+1;
    return memo[i];
  }
  else if(used[ni]){
    assert(false);
  }

  if (found.find(ni)!=found.end()){
    memo[i] = dfs(ni)+1;
    return memo[i];
  }
  else{
    memo[i] = 1;
    return memo[i];
  }
}
