template <unsigned mod>
struct RollingHash {
  vector<unsigned> hashed;
  vector<unsigned> power;
  RollingHash(const string &s, unsigned base = 10007) {
    int n = (int) s.size();
    hashed.assign(n + 1, 0);
    power.assign(n + 1, 0);
    power[0] = 1;
    for (int i = 0; i < n; i++) {
      power[i + 1] = (long long) power[i] * base % mod;
      hashed[i + 1] = ((long long) hashed[i] * base + s[i]) % mod;
    }
  }
  unsigned get(int l, int r) const {
    unsigned ret = hashed[r] + mod - ((long long) hashed[l] * power[r - l]) % mod;
    if (ret >= mod) ret -= mod;
    return ret;
  }
};

using RH = RollingHash<1000000007>;

struct UnionFind {
  vector<int> par;
  vector<int> siz;
  UnionFind(int n) {
    par = vector<int>(n);
    siz = vector<int>(n, 1);
    iota(par.begin(), par.end(), 0);
  }
  int root(int x) {
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    par[x] = y;
    siz[y] += siz[x];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int size(int x) {
    return siz[root(x)];
  }
};

