vi kmp(string& T, string& P, vi& b){
    vi ret;
    int i = 0, j = 0;
    while(i < T.size()){
        while(j >= 0 && T[i] != P[j]){
            j = b[j];
        }
        i++;
        j++;
        if(j == P.size()){
            ret.push_back(i - j);
            j = b[j];
        }
    }
    return ret;
}

