using namespace std;
typedef long long ll;

class KMP {
public:
    string pattern;
    int plen;
    vector<int> table;

    // tからsを探す(探すものを引数に)
    KMP(const string& s) : pattern(s), plen((int)pattern.size()), table(plen + 1) {
        table[0] = -1;
        int j = -1;
        for (int i = 0; i < plen; i++) {
            while (j >= 0 && pattern[i] != pattern[j]) j = table[j];
          	j++;
            if (i + 1 < plen && pattern[i + 1] == pattern[j]) table[i + 1] = table[j];
            else table[i + 1] = j;
        }
    }

    // マッチする左端の箇所
    vector<int> search(const string& text) {
        vector<int> res;
        int head = 0, j = 0, tlen = (int)text.size();
        while (head + j < tlen) {
            if (pattern[j] == text[head + j]) {
                if (++j != plen) continue;
                res.push_back(head);
            }
            head += j - table[j], j = max(table[j], 0);
        }
        return res;
    }
};

struct DAG {
private:
    struct Edge {
        int to;
    };
    std::vector<std::vector<Edge>> graph;
    bool is_dag = false;
    std::vector<int> sorted; // トポロジカルソート
    int V; // 頂点数
public:

    DAG(int v) {
        assert(v > 0);
        V = v;
        graph.resize(v);
    }

    // from から to への有向辺を張る
    void add_edge(int from, int to) {
        graph[from].push_back({to});
    }

    // トポロジカルソート O(V + E)
    // DAG じゃないなら size 0 の vectorを返す
    std::vector<int> topological_sort(int &ret) {
        ret = 0;
        std::stack<int> sta;
        std::vector<int> dist(V, 0);//その頂点までの最長路
        std::vector<int> in(V, 0);// 入次数
        int used_cnt = 0;//使用した頂点の数
        for (int i = 0; i < V; i++) {
            for (Edge e : graph[i]) {
                in[e.to]++;
            }
        }
        for (int i = 0; i < V; i++) if (in[i] == 0) {
            sta.push(i);
            used_cnt++;
        }
        while (!sta.empty()) {
            int p = sta.top(); sta.pop();
            sorted.push_back(p);
            for (Edge e : graph[p]) {
                int v = e.to;
                in[v]--;
                dist[v] = std::max(dist[v], dist[p] + 1);
                ret = max(ret, dist[v]);
                if (in[v] == 0) {
                    sta.push(v);
                    used_cnt++;
                }
            }
        }
        if (used_cnt == V) {
            return sorted;
        }
        else {
            return std::vector<int>(0);
        }
    }

    vector<Edge>& operator[](int x) {
        return graph[x];
    }
};

int main() {
    string s, t; cin >> s >> t;
    string s2 = s;
    int n = s.size();
    DAG g(n);
    while (n + t.size() - 1 > s.size()) {
        s += s2;
    }
    KMP kmp(t);
    //cout << "s : " << s << endl;
    for (int v : kmp.search(s)) {
        if (v >= n) break;
        g.add_edge(v, (v + t.size()) % n);
        //cout << v << " " << (v + t.size()) % n << endl;
    }
    int ans;
    if (g.topological_sort(ans).size() == 0) {
        cout << -1 << endl;
    }
    else {
        //cout << g.topological_sort(ans).size() << endl;;
        cout << ans << endl;
    }
    return 0;
}

