}

int kmp_search() {
    int m = 0, i = 0;
    while (m + i < k && m < l) {
        if (w[i] == s[m + i]) {
            if (++i == n) {
                ver[m].to = (m + n) % l;
                ver[(m + n) % l].num++;
                m = m + i - 1 - t[i - 1];
                i = t[i - 1];
            }
        }
        else {
            m = m + i - t[i];
            if (i > 0) i = t[i];
        }
    }
    return k;
}

