    while(S.length()<3*M) S+=S;

    char c='a';
    c--;

    hash_mod T_hash;
    T_hash.update(0ULL);
    for(i=0; i<M; i++){
        T_hash.multiple(b);
        T_hash.addition((unsigned long long)(T[i]-c));
    }

    hash_mod sub, b_pow;
    b_pow.update(1ULL);
    for(i=0; i<M-1; i++){
        b_pow.multiple(b);
    }

    bool in[N], out[N], visited[N];
    for(i=0; i<N; i++){
        in[i]=0;
        out[i]=0;
        visited[i]=0;
    }

    hash_mod S_hash;
    S_hash.update(0ULL);
    for(i=0; i<M; i++){
        S_hash.multiple(b);
        S_hash.addition((unsigned long long)(S[i]-c));
    }
    if(S_hash.val==T_hash.val){
        out[0]=1;
        in[M%N]=1;
    }
    for(i=M; i<N+M; i++){
        sub.update((unsigned long long)(S[i-M]-c));
        sub.multiple(b_pow.val);
        S_hash.subtraction(sub.val);
        S_hash.multiple(b);
        S_hash.addition((unsigned long long)(S[i]-c));
        if(S_hash.val==T_hash.val){
            out[i-(M-1)]=1;
            in[(i+1)%N]=1;
        }
    }
    //dfs
    unsigned long long ans=0, val;
    for(i=0; i<N; i++){
        if(out[i]==1&&in[i]==0){
            visited[i]=1;
            val=1;
            j = (i+M)%N;
            while(out[j]==1){
                visited[j]=1;
                val++;
                j = (j+M)%N;
            }
            ans=max(ans,val);
        }
    }
    bool loop=0;
    for(i=0; i<N; i++){
        if(visited[i]==0&&out[i]==1){
            loop=1;
        }
    }

    //output
    if(loop==1){
        cout << -1 << endl;
    }else{
        cout << ans << endl;
    }
    system("pause");
    return 0;
}

