    for (int i = 0; i + S - 1 < T; i++) { 
        long long cur_h = (h[i+S] + m - h[i]) % m, cur_h2 = (h2[i+S] + m2 - h2[i]) % m2, cur_h3 = (h3[i+S] + m3 - h3[i]) % m3; 
        if (cur_h == (h_s * p_pow[i]) % m && cur_h2 == (h_s2 * p_pow2[i]) % m2)
