	RollingHash_<T,998244353>RH1;
	RollingHash_<T,1000000007>RH2;

	RollingHash(T s){
		RH1=RollingHash_<T,998244353>(s);
		RH2=RollingHash_<T,1000000007>(s);
	}

	Hash get(int l,int r){
		return make_pair(RH1.get(l,r),RH2.get(l,r));
	}
};

char S[600000],T[600000];
int main(){
	scanf("%s%s",T,S);
	string s=S,t=T;
	t+=t;
	s+=s;
	while(t.size()<s.size()*2){
		t+=T;
	}
	while(s.size()<t.size()){
		s+=S;
	}
	RollingHash<string>rh1(s),rh2(t);
	if(t.size()==s.size()){
		string tt=t+t;
		RollingHash<string>rh2(tt);
		rep(i,t.size()){
			Hash h1=rh1.get(0,s.size()),h2=rh2.get(i,i+s.size());
			if(h1!=h2)continue;
			h2=rh2.get(i+s.size(),i+2*s.size());
			if(h1==h2){
				puts("-1");return 0;
			}
		}
	}
	int Max=0;
	rep(i,t.size()){
		int ok=0,ng=s.size()+1;
		while(ng-ok>1){
			int md=(ok+ng)/2;
			if(i+md>t.size()){ng=md;continue;}
			Hash h1=rh1.get(0,md),h2=rh2.get(i,i+md);
			if(h1==h2){
				ok=md;
			}
			else ng=md;
		}
		Max=max(Max,ok);
	}
	int ss=strlen(S);
	cout<<Max/ss<<endl;
}

