template<class T>class RollingHash {
	int n; T base;
	vector<T> pow, hash;
public:
	RollingHash(const string& s, T b = 10007) :n(s.size()), base(b), pow(n + 1), hash(n + 1) {
		pow[0] = 1; hash[0] = 0;
		for (int i = 0; i < n; ++i) {
			pow[i + 1] = pow[i] * base;
			hash[i + 1] = (T(s[i]) + hash[i] * base);
		}
	}
	// [0, r)
	T operator()(int r)const {
		return hash[r];
	}
	// [l, r)
	T operator()(int l, int r)const {
		return operator()(r) - operator()(l) * pow[r - l];
	}
};
