				return true;
			}
		}
		return false;
	};

	if (check(sz(S) / sz(t) - 1)) {
		out.exit(-1);
	} else if (!check(1)) {
		out.exit(0);
	}

	int ok = 0, ng = sz(S) / sz(t) + 1;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		(check(mid) ? ok : ng) = mid;
	}
	out(ok);
}

