    memset(checked, 0, sizeof(checked));
    ll ans = 0LL;
    rep (i, slen) {
        if (start_to_next[i] < 0LL && next_to_start[i] < 0LL) continue;
        if (next_to_start[i] < 0LL) {
            ll now = i;
            ll lans = 0LL;
            for ( ; ; ) {
                checked[now] = true;
                now = start_to_next[now];
                if (now < 0LL) break;
                lans++;
                if (now == i) {
                    cout << -1;
                    return 0;
                }
            }
            ans = max(lans, ans);
        }
    }

    // loop check
    rep (i, slen) {
        if (start_to_next[i] < 0LL && next_to_start[i] < 0LL) continue;
        if (checked[i]) continue;
        cout << -1;
        return 0;
    }

    cout << ans;

    return 0;
}

