namespace SCC {
	int n;
	vi G[MAX_N], rG[MAX_N];
	vi nG[MAX_N];//if you don't want to create a new graph, comment out
	vi vs;
	bool used[MAX_N];
	int cmp[MAX_N]; // cycle number that nodes are in, topological order
	//for scc:
	//cmp[i] == cmp[i + N] impossible
	//cmp[i] > cmp[i + N] vi is true
	//cmp[i] < cmp[i + N] vi is false
	vi C[MAX_N];//this too. all nodes in cycle

	void init(int N) {
		n = N;
		rep(i, 0, n) {
			G[i].clear();
			rG[i].clear();
			nG[i].clear();
			C[i].clear();
		}
	}

	void add_edge(int from, int to) {
		G[from].push_back(to);
		rG[to].push_back(from);
	}

	void dfs(int v) {
		used[v] = true;
		rep(i, 0, (int)G[v].size()) {
			int n = G[v][i];
			if(!used[n]) dfs(n);
		}
		vs.push_back(v);
	}

	void rdfs(int v, int k) {
		used[v] = true;
		cmp[v] = k;
		//* //C
		C[k].push_back(v);
		//*/
		rep(i, 0, (int)rG[v].size()) {
			int n = rG[v][i];
			if(!used[n]) rdfs(n, k);
			//* //nG
			if(used[n] && cmp[n] < k) nG[cmp[n]].push_back(k);
			//*/
		}
	}

	int get() {
		memset(used, 0, sizeof(used));
		vs.clear();
		rep(v, 0, n) {
			if(!used[v]) dfs(v);
		}
		memset(used, 0, sizeof(used));
		fill(cmp, cmp + n, n);
		int k = 0;
		rer(i, (int)vs.size(), 0) {
			if(!used[vs[i]]) rdfs(vs[i], k++);
		}
		//* //C
		rep(i, 0, k) reverse(all(C[i]));
		//*/

		//* //nG
		rep(i, 0, k) {
			sort(all(nG[i]));
			nG[i].erase(unique(all(nG[i])), nG[i].end());
		}
		//*/
		return k;
	}
}

vector<int> KMP(string S) {
	int n = (int)S.size();
	S += '_';
	vector<int> A(n + 1);
	A[0] = -1;
	int j = -1;
	rep(i, 0, n) {
		while (j >= 0 && S[i] != S[j]) j = A[j];
		j++;
		if(S[i + 1] == S[j]) A[i + 1] = A[j];
		else A[i + 1] = j;
	}
	return A;
}

int N, M;
string str, T;
string S;
int d[MAX_N];

int loop(int v) {
	if(d[v] != -1) return d[v];
	d[v] = 0;
	rep(i, 0, sz(SCC::G[v])) {
		int n = SCC::G[v][i];
		MAX(d[v], loop(n) + 1);
	}
	return d[v];
}

void solve() {
	cin >> str >> T;
	N = sz(str); M = sz(T);
	S += str;
	S += str;
	while(sz(S) - M + 1 < N) S += str;
	vector<int> kmp = KMP(T);
	int at = 0;

	SCC::init(N);
	rep(i, 0, sz(S)) {
		while(at >= 0 && S[i] != T[at]) at = kmp[at];
		at++;
		if(at == M && i - M + 1 < N) {
			int from = (i - M + 1) % N;
			int to = (i + 1) % N;
			if(from == to) {
				cout << -1 << "\n"; return;
			}
			SCC::add_edge(from, to);
			// debug(from, to);
			at = kmp[at];
		}
	}
	int K = SCC::get();
	debug(K);
	if(K != N) {
		cout << -1 << "\n";
	}
	else {
		memset(d, -1, sizeof(d));
		int ans = 0;
		rep(i, 0, N) {
			MAX(ans, loop(i));
		}
		cout << ans << "\n";
	}
}

