    rolling_hash br(b);

    ll bs = b.size();
    int aes = ae.size();
    vector<bool> ok(aes, false);
    for(int i = 0; i + bs <= aes; i++)
    {
        bool match = true;
        if(i + bs < aes)
        {
            for(int j = 0; j < 2; j++)
            {
                if(ar.hash(i, i+bs, j) != br.hash(0, bs, j)) match = false;
            }
            ok[i] = match;
        }
    }
    int seq = 0;
    int ans = 0;
    for(int start = 0; start < bs; start++)
    {
        int seq = 0;
        for(int i = 0; start + i < aes; i += bs)
        {
            if(ok[start+i])
            {
                seq++;
                ans = max(ans, seq);
            }
            else seq = 0;
        }
    }
    ae += ae;
