template <typename T> class RollingHash{
private:
  T str;
  LLI base, mod;
  int sl;
  vector<LLI> shash, pow;
public:
  RollingHash(const T &str, LLI base, LLI mod): str(str), base(base), mod(mod), sl(str.size()), shash(sl+1), pow(sl+1){
    pow[0] = 1;
    shash[0] = 0;
    FORE(i,1,sl){
      shash[i] = (shash[i-1]*base+str[i-1]) % mod;
      pow[i] = pow[i-1]*base % mod;
    }
  }

  LLI hash(int i, int j){ // [i, j)
    return (shash[j] - shash[i] * pow[j-i] + mod*mod) % mod;
  }

  LLI hash(const T &p){
    LLI phash = 0;
    REP(i,(int)p.size()) phash = (phash*base+p[i]) % mod;
    return phash;
  }

  vector<int> find(const T &p){
    vector<int> ret;
    int pl = p.size();
    LLI phash = hash(p);
    REPE(i,sl-pl) if(hash(i,i+pl) == phash) ret.push_back(i);
    return ret;
  }
};


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  string s,t;
  while(cin >> s >> t){
    int ans = 0;

    if(s.size() < t.size()){
      string ss(s);
      while(s.size() < t.size()){
        s += ss;
      }
    }

    RollingHash<string> rht(t,31,1000000007);
    string t_min;
    FORE(i,1,(int)t.size()){
      LLI h = rht.hash(0,i);

      bool b = true;
      for(int j=0; j<(int)t.size(); j+=i){
        if(h != rht.hash(j,min<int>(t.size(),j+i))){
          b = false;
          break;
        }
      }

      if(b){
        t_min = t.substr(0,i);
        break;
      }
    }


    RollingHash<string> rhs(s,31,1000000007);
    string s_min;
    FORE(i,1,(int)s.size()){
      LLI h = rhs.hash(0,i);

      bool b = true;
      for(int j=0; j<(int)s.size(); j+=i){
        if(h != rhs.hash(j,min<int>(s.size(),j+i))){
          b = false;
          break;
        }
      }

      if(b){
        s_min = s.substr(0,i);
        break;
      }
    }

    if(s_min.size() == t_min.size()){

      int m = s_min.size();

      FORE(i,0,m){

        if(rhs.hash(0,i) == rht.hash(m-i,m) and 
           rht.hash(0,i) == rhs.hash(m-i,m)){
          ans = -1;
          break;
        }
      }
    }

    if(ans != -1){
      s += s;
      s += s;
      RollingHash<string> rhs(s,31,1000000007);

      auto check =
        [&](int x){
          if(t.size() * x > s.size()) return false;

          string temp;
          REP(i,x) temp += t;

          auto res = rhs.find(temp);

          return !res.empty();
        };


      int lb = -1, ub = s.size()+1, mid;
      while(abs(lb-ub) > 1){
        mid = (ub+lb) / 2;

        if(check(mid)){
          lb = mid;
        }else{
          ub = mid;
        }
      }

      ans = lb;
    }


    cout << ans << endl;
  }

  return 0;
}

