// str の中に word とマッチする場所のリストを返す
// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す
vll KMP(string &str, string &word){
	ll len=(ll)word.size(), n=(ll)str.size(), j=-1;
	vll table(len+1, -1), ret;
	REP(i, len){
		while (j>=0 && word[i]!=word[j]) j=table[j];
		table[i+1] = ++j;
	}

	//vll table = makeTable(word), ret;
	ll m=0, i=0;// , n=(ll)str.size();
	while (m+i < n){
		if (word[i] == str[m+i]) {
			if (++i == (int)(word.size())) {
				ret.push_back(m);
				m = m+i-table[i];
				i = table[i];
			}
		}
		else {
			m = m+i-table[i];
			if (i > 0) i = table[i];
		}
	}
	return move(ret);
}



