		if (W[i - 1] == W[j]) {
			T[i] = j + 1;
			i = i + 1;
			j = j + 1;
		}
		else if (j > 0) {
			j = T[j];
		}
		else {
			T[i] = 0;
			i = i + 1;
		}
	}
	return T;
}

//return: W が見つかった際の S 内の位置。ただし先頭文字は 0番目とする
int kmp_search(const std::string& S, const std::string& W, const std::vector<int>& T, int start = 0) {
	//S 内の現在照合中の開始位置
	int m = start;
	//W 内の現在位置
	int i = 0;
	//
	while (m + i < S.size()) {
		if (W[i] == S[m + i]) {
			++i;
			if (i == W.size())return m;
		}
		else {
			m = m + i - T[i];
			if (i > 0) {
				i = T[i];
			}
		}
	}
	//W が S 内に見つからなかった場合
	return -1;
}







