    RollingHash hs(s), ht(t);
    vector<int> f(n), vis(n);
    for (int i = 0; i < n; i++) {
        if (hs.get(i, i + m - 1) == ht.get(0, m - 1)) {
            // cout << i << endl;
            f[i] = 1;
        }
    }
    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (vis[i] || !f[i]) {
            continue;
        }
        int id = i, co = 0;
        set<int> st;
        vector<int> vv;
        while (1) {
            vv.push_back(id);
            st.insert(id);
            co++;
            id += m;
            id %= n;
            if (f[id]) {
                if (id == i || st.count(id)) {
                    cout << -1 << endl;
                    return 0;
                } else if (vis[id]) {
                    co += vis[id];
                    break;
                } else {
                    vis[id] = 1;
                }
            } else {
                break;
            }
        }
        chmax(ans, co);
        for (int j = 0; j < vv.size(); j++) {
            vis[j] = co;
            co--;
        }
    }
    cout << ans << endl;
}

