struct RollingHash{
	using mllA = mll_<1000000007LL>;
	using mllB = mll_<998244353LL>;
	ll r, N;
	vpll hash, pw;
	RollingHash(string &s, ll r=1000003):r(r),N(Size(s)),hash(N+1),pw(N+1,pll(1,1)){
		mllA pA=1;  mllB pB=1;
		mllA hA=0;  mllB hB=0;
		REP(i, N){
			pA *= r;     pB *= r;
			hA *= r;     hB *= r;
			hA += s[i];  hB += s[i];
			pw  [i+1] = pll(pA.val, pB.val);
			hash[i+1] = pll(hA.val, hB.val);
		}
	}
	pll operator () (ll l, ll r) const {
		mllA hA; mllB hB; tie(hA, hB) = hash[r+1];
		mllA iA; mllB iB; tie(iA, iB) = hash[l];
		mllA pA; mllB pB; tie(pA, pB) = pw[r-l+1];
		iA*=pA;  iB*=pB;
		return pll((hA-iA).val, (hB-iB).val);
	}
};

