vector<int> makeTable(string &s){
    int n = s.size();
    vector<int> ret(n+1);
    ret[0] = -1;
    int j = -1;
    for (int i=0; i<n; i++) {
        while (j >= 0 && s[i] != s[j]) j = ret[j];
        ret[i+1] = ++j;
    }

    return ret;
}

vector<int> kmp(string &str, string &word){
    vector<int> table = makeTable(word), ret;
    int m = 0, i = 0, n = str.size();
    while(m + i < n){
        if(word[i] == str[m+i]){
            if(++i == (int)(word.size())){ 
                ret.emplace_back(m);
                m = m + i - table[i];
                i = table[i];
            }
        }
        else{
            m = m + i - table[i];
            if (i > 0) i = table[i];
        }
    }

    return ret;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    string s, t; cin>>s>>t;
    int n = s.size(), m = t.size();

    string S = s;
    while((int)S.size() <= m * 2){
        S += s;
    }

    auto v = kmp(S, t);

    vector<bool> sindex(n, false);
    for(auto i : v){
        sindex[i % n] = true; 
    }

    int ans = 0;
    for(int i=0; i<n; i++){
        int sum = 0;
        set<int> used_index;
        if(sindex[i]){
            sindex[i] = false;
            used_index.emplace(i);
            sum++;
            int nxt = (i + m) % n;

            if(used_index.find(nxt) != used_index.end()){
                cout << -1 << endl;
                return 0;
            }

            while(sindex[nxt]){
                sindex[nxt] = false;
                used_index.emplace(nxt);
                sum++;
                nxt = (nxt + m) % n;

                if(used_index.find(nxt) != used_index.end()){
                    cout << -1 << endl;
                    return 0;
                }
            }

            int pre = (i - m + (int)S.size()) % n;

            if(used_index.find(pre) != used_index.end()){
                cout << -1 << endl;
                return 0;
            }

            while(sindex[pre]){
                sindex[pre] = false;
                used_index.emplace(pre);
                sum++;
                pre = (pre - m + (int)S.size()) % n;

                if(used_index.find(pre) != used_index.end()){
                    cout << -1 << endl;
                    return 0;
                }
            }

            chmax(ans, sum);
        }
    }

    cout << ans << endl;
}

