vector<int> table(T_MAX, 0); // ずらしテーブル
vector<int> graph[S_MAX];

void make_table(string p, int m) {
    int j = 0;
    for(int i=1;i<m;++i) {
        table[i] = j;
        if(p[i] == p[j]) {
            ++j;
        } else {
            j = 0;
        }
    }
}

int kmp(string s, string p, int i0=0, int j0=0) {
    int n = s.length(), m = p.length();

    int i = i0, j = j0;
    while(i < n) {
        // cerr << i << s[i%n] << " " << j << p[j] << endl;
        if(s[i%n] == p[j]) {
            ++i;
            ++j;
            if(j == m) return i - m;
        } else if(j == 0) {
            ++i;
        } else {
            j = table[j];
        }
    }
    return -1;
}

int calc_period(string s, int n) {
    int s_period = INF;
    for(int i=1;i<=sqrt(n+1);++i) {
        if(n % i) continue;
        bool is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%i]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, i);
        }
        is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%(n/i)]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, n/i);
        }
    }
    return s_period;
}

bool is_inf(string s, string t, int n, int m) {
    int s_period = calc_period(s, n), t_period = calc_period(t, m);
    if(s_period == t_period) {
        bool are_same = true;
        for(int i=0;i<s_period;++i) {
            if(s[i] != t[i]) {
                are_same = false;
            }
        }
        if(are_same) return true;
    }
    return false;
}

vector<int> topological_sort(int n){
    int indeg[n];
    set<int> st; // 入次数が0の頂点の番号
    fill(indeg, indeg+n, 0);
    for(int i=0;i<n;++i) for(int to: graph[i]) indeg[to]++;
    for(int i=0;i<n;++i) if(indeg[i] == 0) st.insert(i);

    vector<int> ret;
    int used[n];
    fill(used, used+n, 0);
    while(!st.empty()){
        int node = *st.begin();
        st.erase(node);
        ret.push_back(node);
        used[node] = 1;
        for(int next: graph[node]){
            --indeg[next];
            if(!used[next] && indeg[next] == 0) st.insert(next);
        }
    }
    return ret;
}

int main() {
    string s,t;
    cin >> s >> t;
    int n = s.length(), m = t.length();

    // 答えが -1 の場合をここでふるい落とす
    // 周期が同じで，周期内の文字列が同じなら -1
    if(is_inf(s, t, n, m)) {
        cout << -1 << endl;
        return 0;
    }

    string ss = s;
    while(ss.length() < m) ss += s;
    int nn = ss.length();

    make_table(t, m);

    int i0 = 0, j0 = 0;
    bool is_zero = true;
    while(i0 < 2*n) {
        int k = kmp(ss, t, i0, j0);
        if(k == -1) {
            ++i0;
        } else {
            is_zero = false;
            graph[k].push_back((k+m)%n);
            // cerr << k << "->" << (k+m)%n << endl;
            i0 = k + m;
            j0 = table[m-1];
        }
    }

    if(is_zero) {
        cout << 0 << endl;
        return 0;
    }

    vector<int> ordered_nodes = topological_sort(n);
    if(ordered_nodes.size() < n) {
        cout << -1 << endl;
        return 0;
    }
    vector<int> length(n, 1);
    for(int i=0;i<n;++i) {
        for(int j: graph[i]) {
            length[j] = max(length[j], length[ordered_nodes[i]] + 1);
        }
    }

    cout << *max_element(length.begin(), length.end()) << endl;

}

