void z_func(char s[], int z[]) {
    int len = strlen(s);
    for (int i = 1, l = 0, r = 0; i < len; ++i) {
        if (i < r) {
            z[i] = min(z[i - l], r - i);
        }
        for (; i + z[i] < len && s[i + z[i]] == s[z[i]]; ++z[i]) {}
        if (r <= i + z[i]) {
            l = i;
            r = i + z[i];
        }
    }
}

