void make_graph() {
  while (S2.size() < M + N) S2 += S;
  BASE_POW_N = 1;
  for (ll i = 0; i < M; ++i) (BASE_POW_N *= BASE) %= MOD;
  ll t_hash = 0;
  for (ll i = 0; i < M; ++i) {
    (t_hash = t_hash * BASE + (T[i] - 'a')) %= MOD;
  }
  Ok.resize(N);
  ll hash = 0;
  for (ll i = 0; i < M; ++i) {
    (hash = hash * BASE + (S2[i] - 'a')) %= MOD;
  }
  for (ll i = 0; i < N; ++i) {
    if (hash == t_hash) {
      Ok[i] = true;
      OkSome = true;
    }
    (hash = hash * BASE + (S2[i + M] - 'a')) %= MOD;
    (hash += MOD - BASE_POW_N * (S2[i] - 'a') % MOD) %= MOD;
  }
}
