struct rollinghash{
	static const int MD=2;
	static const int MAX=1500005;
	const ll base[MD]={1007LL,1009LL};
	const ll mods[MD]={999999937LL, 1000000007LL};
	ll pw_sum[MD][MAX+1];
	ll hash[MD][MAX+1];
	ll pw[MD][MAX+1];
	void init(){
		for(int i=0;i<MD;i++){
			pw[i][0]=1;
			for(int j=0;j<MAX;j++){
				pw[i][j+1]=pw[i][j]*base[i]%mods[i];
			}
		}
	}
	void construct(const string &str){
		int n=str.size();
		for(int i=0;i<MD;i++){
			hash[i][0]=0;
			for(int j=0;j<n;j++){
				hash[i][j+1]=(hash[i][j]*base[i]%mods[i]+str[j])%mods[i];
			}
		}
		int n2=n/2;

	}

	void construct(const vector<int> &vec){
		int n=vec.size();
		for(int i=0;i<MD;i++){
			hash[i][0]=0;
			for(int j=0;j<n;j++){
				hash[i][j+1]=(hash[i][j]*base[i]%mods[i]+vec[j])%mods[i];
			}
		}
	}

	// calc hash value [l,r)
	ll hash_value(int l,int r,int i){
		return ((hash[i][r]-hash[i][l]*pw[i][r-l])%mods[i]+mods[i])%mods[i];
	}
};

