int repcount(string s, string t){
    string t2;
    t2.reserve(s.length());
    int lower = 0;
    int upper = s.length() / t.length() + 1;
    int mid;
    do{
        mid = (upper + lower + 1) / 2;
        t2 = "";
        for(int i = 0; i < mid; i++) t2.append(t);
        int pos = s.find(t2);
        // cout << s << " " << t2 << " " << pos << endl;
        // cout << lower << " " << upper << endl;
        if(pos == -1) upper = mid - 1;
        else lower = mid;
    }while(upper != lower);
    return lower;
}

