bool rolling_hash_contain(string a, string b)
{
	static const unsigned long long B = 1e9 + 7;

	int al = a.size(), bl = b.size();
	if (al > bl)return false;

	unsigned long long t = 1;
	for (int i = 0; i < al; i++)t *= B;

	unsigned long long ah = 0, bh = 0;
	for (int i = 0; i < al; i++)ah = ah * B + a[i];
	for (int i = 0; i < al; i++)bh = bh * B + b[i];

	for (int i = 0; i + al <= bl; i++)
	{
		if (ah == bh)return true;
		if (i + al < bl)bh = bh * B + b[i + al] - b[i] * t;
	}
	return false;
}

//b > a 
int rolling_hash_count(string a, string b)
{
	//cout << a << endl << b << endl;
	static const unsigned long long B = 1e9 + 7;

	int al = a.size(), bl = b.size();
	if (al > bl)return false;

	unsigned long long t = 1;
	for (int i = 0; i < al; i++)t *= B;

	unsigned long long ah = 0, bh = 0;
	for (int i = 0; i < al; i++)ah = ah * B + a[i];
	for (int i = 0; i < al; i++)bh = bh * B + b[i];

	int res = 0;
	int ans = 0;
	for (int i = 0; i + al <= bl;)
	{
		if (ah == bh)
		{
			res++;
			for (int j = 0; j < al; j++)
			{
				if (i + al + j < bl)bh = bh * B + b[i + al + j] - b[i + j] * t;
			}
			i += al;
		}
		else
		{
			res = 0;
			if (i + al < bl)bh = bh * B + b[i + al] - b[i] * t;
			i++;
		}
		ans = max(ans, res);
	}
	return ans;
}

