const mint r = 114514;
mint invr;

mvec calcrephash(string &s, int n){
    mint c = 1, h = 0;
    REP(i, SZ(s)){
        h += (mint)s[i] * c;
        c *= r;
    }
    mvec rephash(n + 1, 0);
    c = 1;
    mint r0 = r.pow(SZ(s));
    REP(i, n){
        rephash[i + 1] = rephash[i] + h * c;
        c *= r0;
    }
    return rephash;
}

mvec calchash(string &s){
    mvec hash(SZ(s) + 1, 0);
    mint c = 1;
    REP(i, SZ(s)){
        hash[i + 1] = hash[i] + (mint)s[i] * c;
        c *= r;
    }
    return hash;
}

mint calch0(string &s, mvec &rephash, mvec &hash, int i, int N){
    if(i + N <= SZ(s)) return (hash[i + N] - hash[i]) * invr.pow(i);
    else{
        mint h0 = (hash[SZ(s)] - hash[i]) * invr.pow(i);
        int n = (N - (SZ(s) - i)) / SZ(s), k = (N - (SZ(s) - i)) % SZ(s);
        h0 += rephash[n] * r.pow(SZ(s) - i);
        h0 += hash[k] * r.pow(N - k);
        return h0;
    }
}

signed main(){

    string s, t; cin >> s >> t;
    int n = SZ(s), m = SZ(t);

    mvec rephash_s = calcrephash(s, m + 1), rephash_t = calcrephash(t, n + 1);
    mvec hash_s = calchash(s), hash_t = calchash(t);
    invr = r.inv();

