                int k = (k0 + k1) / 2;
                if(calch0(s, rephash_s, hash_s, i, m * k).val == rephash_t[k].val) k0 = k;
                else k1 = k;
            }
            Max(ans, k0);
        }
    }
    Out(ans);

    return 0;
}

