vector<int> Zalgorithm(const string &s) {
    vector<int> ans(s.size());
    ans[0] = s.size();
    int i = 1, j = 0;
    while (i < s.size()) {
        while (i + j < s.size() && s[j] == s[i+j]) ++j;
        ans[i] = j;
        if (!j) {
            ++i;
            continue;
        }
        int k = 1;
        while (i + k < s.size() && k + ans[k] < j) ans[i+k] = ans[k], ++k;
        i += k;
        j -= k;
    }
    return ans;
}


int solve(int len, string S, string T)
{
    string SS, TT;

    while (SS.length() < len) SS += S;
    while (TT.length() < len) TT += T;

    vector<int> z = Zalgorithm(TT + "_" + SS);

    lint maxi = *max_element(z.begin() + TT.length() + 1, z.end());
    lint ret = maxi / T.length();
    return ret;
}

