	int l=-1,r=-1;
	for(int i=1;in[i];i++){
		int j=i;
		if(i<=r){
			if(z[i-l]<r-i+1){
				z[i]=z[i-l];
				continue;
			}
			j=r+1;
		}
		while(in[j]==in[j-i]){
			j++;
		}
		z[i]=j-i;
		if(z[i]){
			r=j-1;
			l=i;
		}
	}
