void genKMPtable(string p, int table[]) {
	size_t len = p.length();

	int i = 2; // 計算してる位置
	int j = 0; // サブ文字列の次の文字列のインデックス

	table[0] = -1; // ここ二つは
	table[1] = 0; // 固定値

	while (i < len) {
		if (p[i-1] == p[j]) {
			// サブ文字列の一致が継続中
			table[i] = j + 1;
			++i;
			++j;
		} else if (j > 0) {
			// サブ文字列は一致しないが，途中まで一致してた場合
			// table[j]の値が先頭から何文字一致してたかを表しているので，
			// 次はそのインデックスから始めれば良い
			j = table[j];
		} else {
			// j = 0 かつ 一致しない時
			table[i] = 0;
			++i;
		}
	}
}

// KMP法による部分文字列検索
int KMPsearch(string text, string word) {
	int m = 0; // text中の照合開始位置
	int i = 0; // w 中の現在位置
	int tl = text.length();
	int wl = word.length();
	int table[wl];

	genKMPtable(word, table);

	while (m + i < tl) {
		if (word[i] == text[m+i]) { // 部分文字列一致中
			++i;
			if (i == wl) { // 最後まで一致
				return m;
			}
		} else {
			m = m + i - table[i]; // 次の開始位置は今見てる位置 - table[j] : KMPtableをそう構築してる
			if (i > 0) i = table[i]; // word内の次の開始位置もtable[j]でよい : 詳しくはgenKMPtable参照
		}
	}

	return -1; //見つからなかった場合
}

// limitまでの部分一致するindexを全て返す
void AllIndexKMPsearch(string text, string word, int limit, bool indices[]) {
	int m = 0; // text中の照合開始位置
	int i = 0; // w 中の現在位置
	int tl = text.length();
	int wl = word.length();
	int table[tl];

	genKMPtable(word, table);

	while (m + i < tl && m < limit) {
		if (word[i] == text[m+i]) { // 部分文字列一致中
			++i;
			if (i == wl) { // 最後まで一致
				indices[m] = true;

				// 次の位置から再スタート
				m = m + 1;
				i = 0;
			}
		} else {
			m = m + i - table[i]; // 次の開始位置は今見てる位置 - table[j] : KMPtableをそう構築してる
			if (i > 0) i = table[i]; // word内の次の開始位置もtable[j]でよい : 詳しくはgenKMPtable参照
		}
	}
}

