string s, t;
int best= 0;
bool cycle =false;
// 0 is unvisited, 1 is currently visited, 2 is retired
int dfs(int i){
   if(vis[i] == 2)return len[i];
   if(vis[i] == 1){cycle = true; return len[i];}
   vis[i] = 1;
   int nex = (i + t.length())% s.length();
   int ans = 1;
   if(match[nex]){
    ans += dfs(nex); 
   }
   vis[i] = 2;
   len[i] =ans;
   best = max(ans, best);
   return ans;
}
signed main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);
    cin >> s >> t;
    lpsComp(t);
    //matching loop
    int pre = 0; //matching at pre th position
    int cnt = 0;
    for(int i = 0; cnt < s.length() + t.length(); cnt++, i++, i %= s.length()){
        //    cout << pre <<endl;
        if(t[pre] == s[i]){ 
            pre++;
        }else if(pre != 0){
            pre = lps[pre - 1];
            i--;
        }
        if(pre == t.length()){
            // i th position is the ending
            int start  = (i - t.length() + 1) % s.length();
            while(start < 0)start += s.length();
            match[start] = true;
            pre = lps[pre- 1];
        }
    }
    FOR(i, s.length()){
        if(match[i] && !vis[i]){
            dfs(i);
        }
    }
    if(cycle)cout << -1;
    else cout << best;


}

