typedef long long ll;
const ll mod=(1e9)+7;
const ll M=998244353;
const int maxn=(2e6)+10;
int mx,n,m,dis[maxn],ans,b[maxn];
char s[maxn],t[maxn];
ll mi[maxn],iv,tmp,T;
ll ksm(ll x,int y) {
	ll res=1;
	while (y) {
		if (y&1) res=res*x%mod;
		y>>=1; x=x*x%mod;
	} return res;
}
queue<int> q;
int in[maxn],head[maxn];
int nxt[maxn];
int to[maxn],tot;
void add(int x,int y) {
	in[y]++;
	tot++; nxt[tot]=head[x];
	head[x]=tot; to[tot]=y;
}
int main() {
	//freopen("1.txt","r",stdin);
	scanf("%s",s+1);
	scanf("%s",t+1);
	n=strlen(s+1);
	m=strlen(t+1);
	mi[0]=1;
	iv=ksm(M,mod-2);
	for (int i=1;i<=max(n,m);i++)
		mi[i]=mi[i-1]*M%mod;
	for (int i=1;i<=n;i++) b[i]=i;
	mx=n;
	for (int i=1;;i++) {
		for (int j=1;j<=n;j++)
			s[n*i+j]=s[j],b[n*i+j]=j;
		mx=max(mx,n*i+n);
		if (mx>=n+m) break;
	}
	b[mx+1]=1;
	for (int i=1;i<=m;i++) {
		T=(T+mi[i]*s[i])%mod;
		tmp=(tmp+mi[i]*t[i])%mod;
	}
	for (int i=1;i+m-1<=mx;i++) {
		if (T==tmp) add(b[i],b[i+m]);
		T-=M*s[i]%mod;
		if (T<0) T+=mod;
		T=T*iv%mod;
		T+=mi[m]*s[i+m]%mod;
		if (T>=mod) T-=mod;
	}
	for (int i=1;i<=n;i++) if (!in[i]) q.push(i);
	int cnt=n;
	while (!q.empty()) {
		int u=q.front();
		q.pop(); cnt--;
		ans=max(ans,dis[u]);
		for (int i=head[u],v;i;i=nxt[i]) {
			v=to[i];
			in[v]--;
			dis[v]=max(dis[v],dis[u]+1);
			if (!in[v]) q.push(v);
		}	
	}
	if (cnt) ans=-1;
	printf("%d\n",ans);
	return 0;
}

