	rep (i, 1, SZ(s) - 1) {
		if (i) Hash[i] = (Hash[i - 1] * 32323 + s[i] - 'a' + 3) % MOD1;
	}
	#undef s
	#undef Hash
}
inline void DoHash3(ulint HHH[], string & SSS) {
	#define s SSS
	#define Hash HHH
	Hash[0] = s[0] - 'a' + 1;
	rep (i, 1, SZ(s) - 1) {
