	vector <int> pref(s.size()+1, -1);
	for (int i = 0, j = -1; i < s.size(); ++i){
		while (j >= 0 && s[j] != s[i])
			j = pref[j];
		pref[i+1] = ++j;
	}
	return pref;
}
const int maxS = 5e5;
set <int> G[maxS+5];
bool odw[maxS+5];

bool cykl = false;

void dfs(int v){
	odw[v] = true;
	for (auto u: G[v]){
		if (odw[u]){
			cykl = true;
			continue;
		}
		dfs(u);
	}
}

int deg[maxS+5];
vector <int> topo_kol;
int dp[maxS+5];

int main(){
	ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	string s, t; // maksymalizujemy kolejne wystapienia t w substr(s)
	cin >> s >> t;
	while (s.size() < t.size())
		s += s;
	int t_sz = t.size();
	int old_sz = s.size();
	s += s;
	string w = t + "#" + s;
	//cout << w << "\n";
	vector <int> vec = kmp(w);

	for (int i = 2+t_sz; i < vec.size(); ++i){
		if (vec[i] == t_sz){
			int b = i - t_sz - 1;
			int a = b - t_sz + 1;
			b++;
			if (b > old_sz)
				b -= old_sz;
			if (a > old_sz)
				a -= old_sz;
			//cout << a << " -> " << b << "\n";
			G[a].insert(b);
		}
	}
	cykl = false;
	dfs(1);
	if (cykl){
		cout << "-1\n";
		return 0;
	}

	for (int i = 1; i <= old_sz; ++i){
		for (auto u: G[i])
			deg[u]++;
	}
	queue <int> Q;

	for (int i = 1; i <= old_sz; ++i){
		if (G[i].size() == 0)
			continue;
		if (deg[i] == 0)
			Q.push(i);
	}
	while (! Q.empty()){
		int v = Q.front();
		Q.pop();
		topo_kol.push_back(v);
		for (auto u: G[v]){
			deg[u]--;
			if (deg[u] == 0)
				Q.push(u);
		}
	}
	int wynik = 0;
	for (auto v: topo_kol){
		wynik = max(wynik, dp[v]);
		for (auto u: G[v])
			dp[u] = max(dp[u], dp[v]+1);
	}
	cout << wynik << "\n";
	return 0;
}

