ll MOD[2]={(ll)(1e9+7),(ll)(1e9+9)};

void mul_mod(ll& a, ll b, int k){
	a *= b;
	a %= MOD[k];
}

void add_mod(ll& a, ll b, int k){
	a = (a<MOD[k])?a:(a-MOD[k]);
	b = (b<MOD[k])?b:(b-MOD[k]);
	a += b;
	a = (a<MOD[k])?a:(a-MOD[k]);
}

