            j=pi[j-1];
        if(t[i]==p[j]) {
            j++;
            if(j==m){
                ans.push_back(i-j+1);
                j = pi[j-1];
            }
        }
    }
    return ans.size();
}

int solve(string s,string t){
	int l=1,r = s.size()/t.size() + 1,ans = -1;

	while(l<=r){
		int m = (l + r)/2;
		string tt = "";
		for(int i=0;i<m;i++)
			tt += t;
		if(kmp(s,tt) > 0){
			ans = m;
			l = m + 1;
		}
		else
			r = m - 1;
	}
	return ans;
}

