    getline(cin, t);

    string s2 = s;
    s2 += s;
    while(s.size() + t.size() > s2.size()){
        s2 += s;
    }

    set<ll> pos;
    search(s2, t, pos);

    union_find uf(s.size());
    ll ans = 0;
    for(ll i = 0; i < s.size(); ++i){
        if(pos.count(i) == 0){ continue; }
        ans = max(ans, 1LL);

        ll next = (i + t.size()) % s.size();
        if(pos.count(next)){
            if(uf.same(i, next)){  // loop
                cout << -1 << endl;
                return 0;
            }else{
                uf.unite(i, next);
            }
            ans = max(ans, uf.size(i));
        }
    }
    cout << ans << endl;
    return 0;
}

