vector<int> z(string s) {
    int n = s.size();
    vector<int> z(n);
    int x = 0, y = 0;
    for (int i = 1; i < n; i++) {
        z[i] = max(0, min(z[i - x], y - i + 1));
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            x = i;
            y = i + z[i];
            z[i]++;
        }
    }
    return z;
}


int vis[MAXN];
int val[MAXN];
int dfs(int u) {
    vis[u] = 1;
    int &ret = val[u];
    for (int v : adj[u]) {
        if (vis[v] == 1)
            return oo;
        if (vis[v] == 2)
            ret = max(ret, 1 + val[v]);
        else
            ret = max(ret, dfs(v) + 1);
    }
    vis[u] = 2;
    return ret;
}


