template<typename T>
struct MP {
    int n;
    T t;
    vector<int> a;
    MP() {}
    MP(const T& t): t(t) {
        n = t.size();
        a = vector<int>(n+1);
        a[0] = -1;
        int j = -1;
        for (int i = 0; i < n; ++i) {
            while (j != -1 && t[j] != t[i]) j = a[j];
            j++;
            a[i+1] = j;
        }
    }
    int operator[](int i) { return a[i]; }
    vector<int> findAll(const T& s) {
        vector<int> res;
        int j = 0;
        for (int i = 0; i < s.size(); ++i) {
            while (j != -1 && t[j] != s[i]) j = a[j];
            j++;
            if (j == n) {
                res.push_back(i-j+1);
                j = a[j];
            }
        }
        return res;
    }
};
const int MX = 500005;
int to[MX];
bool used[MX];
bool visited[MX];
int path[MX];

bool dfs (int v) {
    if (visited[v]) return false;
    if (used[v]) return true;
    visited[v] = true;
    if (to[v]==-1) {
        path[v] = 0;
        used[v] = true;
        return true;
    }

    bool res = dfs(to[v]);
    if (!res) return false;
    path[v] = path[to[v]] + 1;

    visited[v] = false;
    used[v] = true;
    return true;
}

