int mul(int a, int b) { return 1LL * a * b % mod; }
int mpow(int a, int n) {
	if(n == 0) return 1;
	int x = mpow(a, n/2);
	x = mul(x, x);
	if(n % 2) x = mul(x, a);
	return x;
}

void fix(int& a) {
	while(a >= mod) a -= mod;
	while(a < 0) a += mod;
}

int add(int a, int b) {
	fix(a), fix(b);
	a += b;
	fix(a);
	return a;
}

int sub(int a, int b) {
	fix(a), fix(b);
	a -= b;
	fix(a);
	return a;
}

int hash_s(int i, int j) {
	int L = i == 0 ? 0 : h[i-1];
	return mul(p_inv[i], sub(h[j], L));
}

