struct UnionFind{ //素集合データ構造
private:
    vector<int> par;
public:
    UnionFind(int n): par(n, -1) {}
    int find(int x){
        if(par.at(x) < 0) return x;
        else return par.at(x) = find(par.at(x));
    }
    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(size(x) < size(y)) swap(x, y);
        par.at(x) += par.at(y);
        par.at(y) = x;
    }
    int size(int x){ return -par.at(find(x)); }
    bool same(int x, int y){ return find(x) == find(y); }
    void reset(int n){ par = vector<int>(n, -1); }
};

struct RollingHash{
private:
    const int base = 10007, mod = 1000000007;
    vector<int> hash, pow;
public:
    RollingHash(const string &s){
        int sz = (int)s.size();
        hash = vector<int>(sz + 1, 0);
        pow = vector<int>(sz + 1, 1);
        rep(i, sz){
            hash[i + 1] = (hash[i] * base + s[i]) % mod;
            pow[i + 1] = pow[i] * base % mod;
        }
    }
    int get(int l, int r) const {
        return ((hash[r] - hash[l] * pow[r - l]) % mod + mod) % mod;
    };
};

