int Next[maxn],vis[maxn],kmpcount;
struct Node{
    int to,next;
}q[maxn<<1];
int head[maxn],cnt=0,inde[maxn];
void add_edge(int from,int to){
    q[cnt].to=to;
    q[cnt].next=head[from];
    head[from]=cnt++;
}
void init(){
    memset(head,-1,sizeof(head));
    cnt=0;
}
void kmp_pre(char x[],int m,int next[]){
    int i,j;
    j=next[0]=-1;
    i=0;
    while(i<m){
        while(j!=-1&&x[i]!=x[j]) j=next[j];
        next[++i]=++j;
    }
}
int kmp(char x[],int m,char y[],int n){
    int i,j;
    int ans=0;
    kmp_pre(x,m,Next);
    i=j=0;
    while(i<n){
        while(j!=-1&&y[i]!=x[j]) j=Next[j];
        i++,j++;
        if(j>=m){
            ans++;
            j=Next[j];
            vis[i-m]=1;
        }
    }
    return ans;
}
vector<int>vec;
int dp[maxn];
bool topsort(int n){
    int cnt=0;
    queue<int>que;
    for(int i=0;i<n;i++) if(!inde[i]&&vis[i])que.push(i);
    while(!que.empty()){
        int x=que.front();
        vec.push_back(x);
        cnt++;
        que.pop();
        for(int i=head[x];i!=-1;i=q[i].next){
            int to=q[i].to;
            inde[to]--;
            if(inde[to]==0) que.push(to);
        }
    }
    return kmpcount==cnt;
}
