struct KMP {
  int n;
  string s;
  vector<int> a;
  // a[i] = s[0:i]のprefixとsuffixが最大何文字一致しているか
  void build(const string &s) {
    this->s = s;
    n = s.size();
    a.assign(n+1,-1);
    for(int i=0,j=-1;i<n;a[++i]=++j)while(j>=0&&s[i]!=s[j])j=a[j];
  }
  // find s from t
  vector<int> match(const string &t) {
    int j=0;
    int cnt = 0;
    vector<int> v;
    REP(i,t.size()) {
      while(j>=0 && s[j]!=t[i]) j = a[j];
      if (++j>=n) {
        v.push_back(i - n + 1);
        ++cnt, j=a[j];
      }
    }
    return v;
  }
  // s[0:i]の最小周期
  int period(int i) {
    return i - a[i];
  }
};

typedef int Weight;
struct Edge {
  int src, dst;
  Weight weight;
  Edge(int src, int dst, Weight weight) :
    src(src), dst(dst), weight(weight) { }
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

vector<int> tsort(const Graph &g) {
  int n = g.size();
  vector<int> num(n);
  REP(i, n) FOR(e, g[i]) num[e->dst]++;
  queue<int> Q;
  REP(i, n) if (num[i] == 0) Q.push(i);
  vector<int> res;
  while(!Q.empty()) {
    int v = Q.front(); Q.pop();
    res.push_back(v);
    FOR(e, g[v]) {
      if (num[e->dst]) {
        num[e->dst]--;
        if (num[e->dst] == 0) Q.push(e->dst);
      }
    }
  }
  REP(i, n) if (num[i]) return vector<int>();
  return res;
}

int longestPathDAG(const Graph &g, const vector<int> &ordered) {
  vector<int> dp(g.size());
  int ans = 0;
  FOR(it, ordered) {
    FOR(jt, g[*it]) {
      chmax(dp[jt->dst], dp[*it] + 1);
      chmax(ans, dp[jt->dst]);
    }
  }
  return ans;
}

