vector<int> FindMatchAllByRollingHash(const string& s, const string& key) {
  if (s.length() < key.length()) return {};

  constexpr int64 P1 = 1000000007;
  constexpr int64 P2 = 999999937;
  constexpr int64 B = 257;

  int m = key.length();
  int64 bm1 = 1;
  int64 bm2 = 1;
  for (int i = 0; i < m; i++) {
    bm1 = bm1 * B % P1;
    bm2 = bm2 * B % P2;
  }
  int64 kh1 = 0;
  int64 kh2 = 0;
  for (int i = 0; i < m; i++) {
    kh1 = (kh1 * B + key[i]) % P1;
    kh2 = (kh2 * B + key[i]) % P2;
  }

  vector<int> positions;
  int64 h1 = 0;
  int64 h2 = 0;
  for (int i = 0; i < m; i++) {
    h1 = (h1 * B + s[i]) % P1;
    h2 = (h2 * B + s[i]) % P2;
  }

  if (h1 == kh1 && h2 == kh2) {
    positions.push_back(0);
  }

  for (int i = 1; i + m <= s.length(); i++) {
    h1 = (h1 * B + s[i + m - 1]) % P1;
    h1 = (h1 + P1 - (bm1 * s[i - 1] % P1)) % P1;
    h2 = (h2 * B + s[i + m - 1]) % P2;
    h2 = (h2 + P2 - (bm2 * s[i - 1] % P2)) % P2;
    if (h1 == kh1 && h2 == kh2) {
      positions.push_back(i);
    }
  }
  return positions;
}

int Max(const vector<int>& xs) {
  int value = INT32_MIN;
  for (int x : xs) value = max(x, value);
  return value;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  string s, t;
  cin >> s >> t;
  string extended_s(s);
  while (extended_s.length() < s.length() + t.length()) {
    extended_s.append(s);
  }

  vector<int> matches = FindMatchAllByRollingHash(extended_s, t);
  vector<int> is_match(s.length());
  for (int match : matches) {
    if (match < s.length()) {
      is_match[match] = 1;
    }
  }

  vector<int> visited(s.length(), -1);
  vector<int> dp(s.length(), -1);
  function<void(int)> dfs = [&](int v) {
    if (visited[v] == 1) return;

    if (visited[v] == 0) {
      visited[v] = 1;
      dp[v] = INT32_MAX;
      return;
    }

    if (is_match[v] == 0) {
      visited[v] = 1;
      dp[v] = 0;
      return;
    }

    visited[v] = 0;
    int next_v = (v + t.length()) % s.length();
    dfs(next_v);
    if (dp[next_v] == INT32_MAX) dp[v] = INT32_MAX;
    else dp[v] = dp[next_v] + 1;
    visited[v] = 1;
  };

  for (int i = 0; i < s.length(); i++) dfs(i);

  int max = Max(dp);
  cout << ((max == INT32_MAX) ? -1 : max) << endl;
}

