vector<int> Zalgorithm(string s){
  int i=1,j=0,k=0,N=s.size();
  vector<int> res(N);
  res[0]=N;
  while(i<N){
    while(i+j<N&&s[i+j]==s[j])++j;
    res[i]=j;
    if(!j){
      ++i;
      continue;
    }
    k=1;
    while(res[k]+k<j){
      res[i+k]=res[k];
      ++k;
    }
    i+=k;
    j-=k;
  }
  return res;
}
