int get (const string& s) {
  int n = (int) s.size();
  vector <int> z(n);
  for (int i = 1, l = 0, r = 0; i < n; i++) {
    if (i <= r) z[i] = min(r - i + 1, z[i - l]);
    while (i + z[i] < n and s[z[i]] == s[i + z[i]]) z[i]++;
    if (i + z[i] - 1 > r) l = i, r = i + z[i] - 1;
  }
  vector <bool> vis(n, false);
  int ans = 0;
  for (int i = m; i < n; i++) {
    if (vis[i]) continue;
    vis[i] = true;
    if (z[i] >= m) {
      int cnt = 1;
      int j = i;
      while (j + m < n and z[j + m] >= m) {
        j += m;
        vis[j] = true;
        cnt++;
      }
      ans = max(ans, cnt);
    }
  }
  return ans;
}

