    for(int i=0; i<Ns; i++) vs[i] = vs[i+Ns] = s[i] - 'a';
    for(int i=0; i<Nt; i++) vt[i] = t[i] - 'a';

    RollingHash rhs, rht;
    rhs.set(vs);
    rht.set(vt);
    auto hash_t = rht.get(0, Nt);
    vector<int> G(Ns, -1), Ginv(Ns, -1);
    REP(l, Ns){
        int r = l + Nt;
