vector<int> ZAlgorithm(const string str) {
	int n = str.size();
	vector<int> res(n);
	for(int i = 1, j = 0; i < n; i++) {
		if(i + res[i - j] < j + res[j]) {
			res[i] = res[i - j];
		} 
		else {
			int k = max(0, j + res[j] - i);
			while(i + k < n && str[k] == str[i + k]) ++k;
			res[j = i] = k;
		}
	}
	res[0] = n;
	return res;
}

