const ull mod = 281474976710677, base = random_device()() % 100 + 256;
struct RollingHash {
    vector<ull> hashed, power;

    inline ull mul(ull a, ull b) const {
        return __uint128_t(a)*b%mod;
    }

    RollingHash(const string &s) {
        ll sz = s.size();
        hashed.assign(sz + 1, 0);
        power.assign(sz + 1, 0);
        power[0] = 1;
        for(ll i = 0; i < sz; i++) {
            power[i + 1] = mul(power[i], base);
            hashed[i + 1] = mul(hashed[i], base) + s[i];
            if(hashed[i + 1] >= mod) hashed[i + 1] -= mod;
        }
    }

    ull get(ll l, ll r) const {
        ull ret = hashed[r] + mod - mul(hashed[l], power[r - l]);
        if(ret >= mod) ret -= mod;
        return ret;
    }
};
struct UnionFind{
    vector<ll>data;
    UnionFind(ll n):data(n,-1){}
    bool Union(ll a,ll b){
        a=root(a);b=root(b);
        if(a==b)return 1;
        if(data[a]>data[b])swap(a,b);
        data[a]+=data[b];
        data[b]=a;
        return 0;
    }
    bool Find(ll a,ll b){return root(a)==root(b);}
    ll root(ll a){return data[a]<0?a:data[a]=root(data[a]);}
};
signed main(){
    STR(s,t);
    string u=s;
    while(s.size()<t.size()){
        s+=u;
    }
    ll n=s.size(),m=t.size();
    s+=s;
    RollingHash rhs(s),rht(t);
    UnionFind uf(n);
    rep(n){
        if(rhs.get(i,i+m)==rht.get(0,m)){
        bool a=uf.Union(i,(i+m)%n);
        if(a)return out(-1);
        }
    }
    ll ans=1;
    each(i,uf.data)chmax(ans,-i);
    out(ans-1);
}

