#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MAXN=1e6+5;
const ll MOD=1e9+7;
const ll MOD1=13;
ll n[2],nex[MAXN],len[2];
char str[2][MAXN];
ll myceil(ll x,ll y)
{
    if(x%y)
    {
        return x/y+1;
    }
    return x/y;
}
void get_next(ll op)
{
    nex[1]=0;ll k=0;
    for(ll i=2;i<=n[op];i++)
    {
        while(k>0&&str[op][k+1]!=str[op][i])
        {
            k=nex[k];
        }
        if(str[op][k+1]==str[op][i])
        {
            k++;
        }
        nex[i]=k;
    }
}
bool eq()
{
    if(len[0]==len[1])
    {
        for(ll i=1;i<=len[0];i++)
        {
            if(str[0][i]!=str[1][i])
            {
                return false;
            }
        }
        return true;
    }
    else
    {
        return false;
    }
}
void refine()
{
    if(n[0]%len[0]!=0)
    {
        len[0]=n[0];
    }
    if(n[1]%len[1]!=0)
    {
        len[1]=n[1];
    }
}
void ext()
{
    if(n[1]>n[0])
    {
        ll mul=myceil(n[1],n[0]);
        for(ll i=2;i<=mul;i++)
        {
            for(ll j=1;j<=n[0];j++)
            {
                str[0][j+(i-1)*n[0]]=str[0][j];
            }
        }
        n[0]*=mul;
    }
    for(ll i=1;i<=n[0];i++)
    {
        str[0][i+n[0]]=str[0][i];
    }
    n[0]*=2;
}
//nex[i]:x[i...m-1] 与x[0...m-1] 的最长公共前缀
//extend[i]:y[i...n-1] 与x[0...m-1] 的最长公共前缀
ll extend[1000001];
ll Next[1000001];
void getNext(string t)
{
    memset(Next,0,sizeof(Next));
    ll len=t.length();
    Next[0]=len;
    ll a,p;
    a=1;
    while( a<len && t[a]==t[a-1]) a++; // 求出长度为1的时候 解为多少
    Next[1]=a-1;
    a=1;
    for(ll i=2;i<len;i++) // 后续的按照算法来就好
    {
        p=a+Next[a]-1;
        if((i-1)+Next[i-a] < p ) Next[i]=Next[i-a];// 第一种情况 没有超过等于的部分
        else // 超过的话就不好直接用next的定义 需要后续的遍历
        {
            ll j = (p - i + 1) > 0 ? (p - i + 1) : 0;
            while(i + j < len && t[i+j] == t[j]) j++;
            Next[i]=j;
            a=i;
        }
    }
}
void exkmp(string s,string t) // s->extend  t->next
{
    getNext(t);
    ll a,p;//
    ll slen=s.length();
    ll tlen=t.length();
    a=p=0;
    ll len=min(s.length(),t.length());
    while(p<len && t[p]==s[p]) p++; // after
    extend[0]=p;
    for(ll i=1;i<slen;i++)
    {
        p=a+extend[a]-1; // update
        if( (i-1)+Next[i-a] < p) extend[i]=Next[i-a];
        else
        {
            ll j = (p - i + 1) > 0 ? (p - i + 1) : 0;
            while( j < tlen && i+j < slen && s[i + j] == t[j]) j++;
            extend[i]=j;
            a=i;
        }
    }
}
bool check(ll x)
{
    if(n[1]*x>=MAXN-5)
    {
        return false;
    }
    for(ll i=1;i<x;i++)
    {
        for(ll j=1;j<=n[1];j++)
        {
            str[1][n[1]*i+j]=str[1][j];
        }
    }

    string s=str[0]+1;
    string t=str[1]+1;
    exkmp(s,t);

    for(ll i=0;i<n[0];i++)
    {
        if(extend[i]==n[1]*x)
        {
            return true;
        }
    }
    return false;
}
void solve()
{
    n[0]=strlen(str[0]+1);
    n[1]=strlen(str[1]+1);


    get_next(0);
    len[0]=n[0]-nex[n[0]];

    get_next(1);
    len[1]=n[1]-nex[n[1]];

    refine();
    if(eq())
    {
        printf("-1\n");
        return;
    }

    ext();

    ll l=1,r=1e6;
    while(l<=r)
    {
        ll mid=(l+r)/2;

        if(check(mid))
        {
            l=mid+1;
        }
        else
        {
            r=mid-1;
        }
    }
    printf("%lld\n",r);
}
int main()
{
    scanf("%s",str[0]+1);
    scanf("%s",str[1]+1);
    solve();
}

