const long long INF = 200000;

string s, t;


constexpr ll base1 = 1007, base2 = 2009, mod1 = 1000000007, mod2 = 1000000009;

struct RollingHash {
    vector<ll> hash1, hash2, pow1, pow2;
    RollingHash (const string &S) {
        int length = sz(S);
        hash1.assign(length + 1, 0);
        hash2.assign(length + 1, 0);
        pow1.assign(length + 1, 1);
        pow2.assign(length + 1, 1);
        rep(i, length) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            pow1[i + 1] = pow1[i] * base1 % mod1;
            pow2[i + 1] = pow2[i] * base2 % mod2;
        }
    }
    pair<ll, ll> find(int l, int r) const {
        ll res1 = hash1[r] - hash1[l] * pow1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        ll res2 = hash2[r] - hash2[l] * pow2[r - l] % mod2;
        if (res2 < 0) res2 += mod2;
        return pair<ll, ll>{res1, res2};
    }
};

int main() {
  cin >> s >> t;

  int k = (sz(s) + sz(t) - 2) / sz(s) + 1;
  string r;
  rep(i, k) r += s;
  RollingHash rs_(r), rt(t);

  vector<bool> judge(s.size(), false);
  vector<bool> searched(s.size(), false);

  rep(i, s.size()) {
    if(rs_.find(i, i + t.size()) == rt.find(0, t.size())) {
      judge[i] = true;
    }
  }

  int ans = 0;
  rep(i, s.size()) {
    if(searched[i]) continue;
    if(!judge[i]) continue;
    int now = i, cnt = 0;
    do {
      now = (now + t.size()) % s.size();
      cnt++;
      searched[now] = true;
    } while (now != i && judge[now]);
    if(now == i) ans = INF;
    else chmax(ans, cnt);
  }

  if(ans == INF) cout << -1 << endl;
  else cout << ans << endl;
  return 0;
}

