	cin >> T;
	int ns = S.size();
	int nt = T.size();

	string sn;
	while(sn.size() < ns+nt) sn += S;

	mint B(1e9+7, 1LL<<63);
	mint th(0, 1LL<<63);
	for(int i=0; i<nt; i++){
		th = th * B + (T[i]-'a');
	}
	mint sh(0, 1LL<<63);
	for(int i=0; i<nt; i++){
		sh = sh * B + (sn[i]-'a');
	}

