	mint bpow = B.pow(T.size()-1);
	if(th==sh){
		match[0] = true;
	}
	for(int i=0; i<ns-1; i++){
		sh -= bpow * (sn[i]-'a');
		sh = sh * B + (sn[i+T.size()]-'a');
		if(th==sh){
			match[i+1] = true;
		}
	}
