void Knuth_Morris_Pratt(string &T, string &P, vector<int> &res){
	vector<int> pat(P.size()+1);
	pat[0] = -1;

	res.resize(T.size());

	for(int i = 0, j = -1; i < P.size(); i++){
		while(j >= 0 && P[i] != P[j]) j = pat[j];
		j++;
		if(P[i+1] == P[j]) pat[i+1] = pat[j];
		else pat[i+1] = j;
