template<int SZ> struct KMP{
	int fail[SZ];

	void build(string s){
		fail[0] = 0;
		int n = s.size();
		int len = 0;
		for(int i=1;i<n;i++){
			while(len && s[i] != s[len]){
				len = fail[len-1];
			}
			if(s[i] == s[len]){
				len++;
			}
			fail[i] = len;
		}
	}

	int occers(string s,string t){
		int n = s.size();
		int m = t.size();
		int len = 0;
		int ans = 0,mx = 0;
		for(int i=0;i<n;i++){
			if(s[i] != t[len]){
				mx = max(mx,ans);
				ans = 0;
			}
			while(len && s[i] != t[len]){
				len = fail[len-1];
			}
			if(s[i] == t[len])
				len++;
			if(len == m){
				ans++;
				len = 0;
			}
		}
		mx = max(mx,ans);
		return mx;
	}

};

