struct RollingHash {
    vector<unsigned long long> hash, power;
    const unsigned long long base = 1e9 + 7;

    RollingHash(const string &s) {
        int n = (int)s.size();
        hash.assign( n + 1, 0);
        power.assign(n + 1, 1);
        for(int i = 0; i < n; ++i) power[i+1] =power[i] *  base; // mod 2^64

        for(int i = 0; i < n; ++i) {
            hash[i+1]  = hash[i] * base + s[i];
        }
    }

    // [l, r)
    unsigned long long get_hash(int l, int r) {
        unsigned long long ret = hash[r] - hash[l] * power[r-l];
        return ret;
    }
};

struct UnionFind {
    vector<int> par, weight;
    UnionFind(int n) : par(n,-1), weight(n) {}
    bool unite(int x, int y, int w = 0) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y), w = -w;
        par[x] += par[y];
        par[y] = x;
        return true;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int root(int x) {
        if(par[x] < 0) return x;
        int r = root(par[x]);
        return par[x] = r;
    }
    int sizeOf(int x) { return -par[root(x)]; }
};

