std::vector<int> z_algorithm(const std::string &s)
{
    int sz = s.length();
    std::vector<int> z(sz, 0);
    int i = 1, j = 0;
    while (i < sz)
    {
        while (i + j < sz && s[j] == s[i + j])
            j++;
        z[i] = j;
        if (j == 0)
        {
            i++;
            continue;
        }
        int k = 1;
        while (i + k < sz && k + z[k] < j)
        {
            z[i + k] = z[k];
            k++;
        }
        i += k;
        j -= k;
    }
    return z;
}

struct Edge
{
    int from, to, cost;
    Edge(int from, int to, int cost) : from(from), to(to), cost(cost) {}
};

bool findNegativeLoop(int n, const std::vector<Edge> es, int s, std::vector<int> &d)
{
    int m = es.size();
    std::vector<int> pre(n, -1);
    std::vector<bool> negative(n, false);
    d[s] = 0;
    for (int j = 0; j < n - 1; j++)
    {
        for (int i = 0; i < m; i++)
        {
            Edge e = es[i];
            if (d[e.from] != INF && d[e.to] > d[e.from] + e.cost)
            {
                d[e.to] = d[e.from] + e.cost;
                pre[e.to] = pre[e.from];
            }
        }
    }
    for (int i = 0; i < m; i++)
    {
        Edge e = es[i];
        if (d[e.from] != INF && d[e.from] + e.cost < d[e.to])
        {
            return true;
        }
    }
    return false;
}

class TopologicalSort
{
    using Graph = std::vector<std::vector<int>>;
    // 頂点数
    int V;
    std::vector<std::vector<int>> G;
    void dfs(int v, std::vector<int> &res, std::vector<int> &used)
    {
        used[v] = 1;
        for (auto to : G[v])
            if (used[to] == 0)
            {
                dfs(to, res, used);
            }
        res.push_back(v);
    }

public:
    TopologicalSort(int _v) : V(_v), G(_v) {}
    void addEdge(int a, int b)
    {
        assert(0 <= a && a < V);
        assert(0 <= b && b < V);
        G[a].push_back(b);
    }
    std::vector<int> topologicalSort()
    {
        std::vector<int> ide(V);
        for (int i = 0; i < V; i++)
        {
            for (auto to : G[i])
            {
                ide[to]++;
            }
        }
        std::vector<int> res;
        std::vector<int> used(V);
        for (int i = V - 1; i >= 0; i--)
        {
            if (ide[i] == 0)
            {
                dfs(i, res, used);
            }
        }
        if (res.size() == 0)
            res = {-1};
        reverse(res.begin(), res.end());
        return res;
    }
};

