    {
        u += s;
    }
    vector<vector<int>> g(n);
    string w = t + "$" + u;
    auto z = z_algorithm(w);
    TopologicalSort ts(n);
    vector<Edge> es;
    for (int i = 0; i < n; i++)
    {
        int index = m + 1 + i;
        if (z[index] >= m)
        {
            g[i].push_back((i + m) % n);
            ts.addEdge(i, (i + m) % n);
            es.emplace_back(i, (i + m) % n, -1);
