using namespace std;
using ll = long long;

int solve(const string &s, const string &t, unsigned long ls, unsigned long lt) {
  int ret = 0;
  vector<bool> seen(ls, false);

  int i = -1;
  while (++i < ls) {
    i = boost::algorithm::boyer_moore_horspool_search(
        s.begin() + i, s.end(), t.begin(), t.end()) - s.begin();
    if (i > ls) break;
    if (seen[i]) continue;

    int j = 0;
    while (true) {
      int p = boost::algorithm::boyer_moore_horspool_search(
          s.begin() + i + j * lt, s.end(), t.begin(), t.end()) - s.begin();
      if (p - (i + j * lt) != 0) {
        break;
      }
      if (p < ls) seen[p] = true;
      if (j * lt >= ls) return -1;

      j += 1;
    }
    ret = max(ret, j);
  }
  return ret;
}

