template<typename T,T MOD,T B>
struct RollingHash{
  vector<T> hash,p;
  RollingHash(){}
  RollingHash(const string &s){
    int n=s.size();
    hash.assign(n+1,0);
    p.assign(n+1,1);
    for(int i=0;i<n;i++){
      hash[i+1]=(hash[i]*B+s[i])%MOD;
      p[i+1]=p[i]*B%MOD;
    }
  }
  //S[l, r)
  T find(int l,int r){
    T res=hash[r]+MOD-hash[l]*p[r-l]%MOD;
    return res>=MOD?res-MOD:res;
  }
};

string make(string s, long long x) {
  string temp = s;
  while(x > 0) {
    x >>= 1;
    temp = temp + temp;
    if(x & 1) s += temp;
  }
  return s;
}

bool isOk(int key, RollingHash<long long, MOD, B> rh, RollingHash<long long, MOD, B> th, string r) {
  // string temp = make(t, key);
  int cnt = 0;
  rep(i, s.size()) {
    if(rh.find(i, i + t.size()) == th.find(0, t.size())) {
      // cout << t.size() << endl;
      // cout << i << " " << temp.size() << " " << r.substr(i, temp.size()) << " " << temp << endl;
      if(r.substr(i, t.size()) == t) {
        i = i + t.size();
        cnt++;
        if(cnt >= key) return false;
      }
    } else {
      cnt = 0;
    }
  }
  return true;
}

int lower_search(RollingHash<long long, MOD, B> rh, RollingHash<long long, MOD, B> th, string s) {
  int l = 0, r = INF;
  while(r - l > 1) {
    int half = (r + l) / 2;
    if(isOk(half, rh, th, s)) r = half;
    else l = half;
  }
  return r;
}

