template <typename T>
struct RollingHash {
    static const int base1 = 1007, base2 = 2009;
    static const int mod1 = 1000000007, mod2 = 1000000009;
    vector<long long> hash1, hash2, power1, power2;

    // construct
    RollingHash(const T &S) {
        int n = (int)S.size();
        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        power1.assign(n + 1, 1);
        power2.assign(n + 1, 1);
        for(int i = 0; i < n; ++i) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }

    // get hash of S[left:right)
    inline pair<long long, long long> get(int l, int r) const {
        long long res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if(res1 < 0)
            res1 += mod1;
        long long res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;
        if(res2 < 0)
            res2 += mod2;
        return {res1, res2};
    }
};

void solve() {
    string s, t;
    cin >> s >> t;
    ll n = t.size();

    string ns = s;
    while(ns.size() <= n) {
        ns += s;
    }
    ll m = ns.size();
    s = ns + ns;
    RollingHash rs(s), rt(t);

    Array used(m, -2);
    auto dfs = [&](auto &&self, int p) -> ll {
        used[p] = -1;

        if(rt.get(0, n) == rs.get(p, p + n)) {
            ll np = (p + n) % m;
            if(used[np] == -1) {
                return used[p] = -1;
            } else if(used[np] == -2) {
                return used[p] = self(self, np) + 1;
            } else {
                return used[p] = used[np] + 1;
            }
        } else {
            return used[p] = 0;
        }
    };

    ll ans = 0;
    REP(i, m) {
        if(used[i] == -2) {
            ll ret = dfs(dfs, i);
            if(ret == -1) {
                cout << -1 << en;
                return;
            } else {
                chmax(ans, ret);
            }
        } else if(used[i] == -1) {
            cout << -1 << en;
            return;
        }
    }
    cout << ans << en;
}

