void dfs(int v) {
    seen[v] = true;
    if(g[v].size()) {
        int u = g[v][0];
        if(cnt[u] == -1) {
            if(seen[u]) { flag = true; return; }
            dfs(u);
            cnt[v] = cnt[u] + 1;
        } else {
            cnt[v] = cnt[u] + 1;
        }
    } else {
        cnt[v] = 0;
    }
    seen[v] = false;
}

