const int N = 2e6 + 7;
const int MOD = 1000 * 1000 * 1000 + 9;
const int BASE = 129;
inline int mod(int n) {
    if (n < 0) return n + MOD;
    else if (n < MOD) return n;
    else if (n < 2 * MOD) return n - MOD;
    else return n % MOD;
}   
int pw[N];
int h[N];
bool good[N];

int dist[N];
void calc(int n, int m) {
    for (int i = 0; i < n; ++i) dist[i] = N;
    queue <int> q;
    for (int i = 0; i < n; ++i) {
        if (!good[i]) {
            dist[i] = 0;
            q.push(i);
        }   
    }   
    while (q.size()) {
        int p = q.front(); q.pop();
        int pr = ((p - m) % n + n) % n;
        if (dist[p] + 1 < dist[pr]) {
            dist[pr] = dist[p] + 1;
            q.push(pr);
        }   
    }   
}   

signed main() {
    #ifdef HOME
    freopen("input.txt", "r", stdin);
    #else
    ios_base::sync_with_stdio(0); cin.tie(0);
    #endif
    pw[0] = 1;
    for (int i = 1; i < N; ++i) pw[i] = mod(pw[i - 1] * BASE);
    string s, t;
    cin >> s >> t;
    int n = s.size(), m = t.size();
    while (s.size() < 2 * t.size()) s += s;
    for (int i = 0; i < s.size(); ++i) h[i + 1] = mod(h[i] * BASE + s[i]);
    int w = 0;
    for (int i = 0; i < m; ++i) w = mod(w * BASE + t[i]);
    for (int i = 0; i < n; ++i) {
        good[i] = mod(h[i + m] - mod(h[i] * pw[m])) == w;
    }   
    int d = __gcd(n, m);
    for (int i = 0; i < d; ++i) {
        bool c = 1;
        for (int j = i; j < n; j += d) {
            c &= good[j];                    
        }   
        if (c) {
            cout << "-1\n";
            exit(0);
        }   
    }   
    calc(n, m);
    int ans = 0;
    for (int i = 0; i < n; ++i) ans = max(ans, dist[i]);
    cout << ans << '\n';
}

#include <bits/stdc++.h>
using namespace std;
const int MAXN=500010;
int n,lens,lent,tot,ans,dp[MAXN],hd[MAXN],in[MAXN],ver[MAXN],nx[MAXN];
char s[MAXN],t[MAXN];
queue <int> q;
void add_edge (int x,int y) {
	ver[++tot]=y;
	nx[tot]=hd[x];
	hd[x]=tot;
	in[y]++;
	return;
}
void topo () {
	for (int i=1;i<=n;i++) {
		if (in[i]==0) {q.push(i);}
	}
	while (!q.empty()) {
		int a=q.front();
		ans=max(ans,dp[a]);
		q.pop();
		for (int i=hd[a];i;i=nx[i]) {
			dp[ver[i]]=max(dp[ver[i]],dp[a]+1);
			if (--in[ver[i]]==0) {q.push(ver[i]);}
		}
	}
	for (int i=1;i<=n;i++) {
		if (in[i]) {ans=-1;}
	}
	return;
}
int main () {
	scanf("%s%s",s+1,t+1);
	lens=n=strlen(s+1),lent=strlen(t+1);
	while (lens<lent+n) {
		for (int i=lens+1;i<=lens+n;i++) {s[i]=s[i-lens];}
		lens+=n;
	}
	nx[1]=0;
	for (int i=2,j=0;i<=lent;i++) {
		while (j&&t[i]!=t[j+1]) {j=nx[j];}
		if (t[i]==t[j+1]) {j++;}
		nx[i]=j;
	}
	for (int i=1,j=0;i<=lens;i++) {
		while (j&&s[i]!=t[j+1]) {j=nx[j];}
		if (s[i]==t[j+1]) {j++;}
		if (j==lent) {add_edge((i-lent)%n+1,(i==lens?0:i)%n+1);}
	}
	topo();
	printf("%d\n",ans);
	return 0;
}

