#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

string S, T, S2;
ll N, M;
const ll BASE = 345, MOD = 1e9 + 7;
ll BASE_POW_N;
vector<vector<ll>> Out;
vector<ll> Seen;
vector<ll> Order;
vector<ll> Dp;
ll R;

void make_graph() {
  while (ll(S2.size()) - N < M) S2 += S;
  BASE_POW_N = 1;
  for (ll i = 0; i < M; ++i) (BASE_POW_N *= BASE) %= MOD;
  ll t_hash = 0;
  for (ll i = 0; i < M; ++i) {
    t_hash = t_hash * BASE + (T[i] - 'a');
  }
  Out.resize(N);
  ll hash = 0;
  for (ll i = 0; i < M; ++i) {
    (hash = hash * BASE + (S2[i] - 'a')) %= MOD;
  }
  for (ll i = 0; i < N; ++i) {
    if (hash == t_hash) {
      Out[i].push_back((i + M) % N);
    }
    (hash = hash * BASE + (S2[i + M] - 'a') + MOD -
            BASE_POW_N * (S2[i] - 'a') % MOD) %= MOD;
  }
}
bool dfs(ll v) {
  if (Seen[v] == 1) return true;
  if (Seen[v] == -1) return false;
  Seen[v] = -1;
  for (ll w : Out[v])
    if (!dfs(w)) return false;
  Seen[v] = 1;
  Order.push_back(v);
  return true;
}
ll solve() {
  Seen.resize(N);
  for (ll v = 0; v < N; ++v) {
    if (!dfs(v)) return -1;
  }
  reverse(Order.begin(), Order.end());
  Dp.resize(N);
  for (ll v : Order) {
    R = max(R, Dp[v]);
    for (ll w : Out[v]) Dp[w] = max(Dp[w], Dp[v] + 1);
  }
  return R;
}
int main() {
  cin >> S >> T;
  N = S.size();
  M = T.size();
  make_graph();
  cout << solve() << endl;
  return 0;
}

