template<int MAXV>
struct scc {
  std::vector<int> G[MAXV], rG[MAXV], vs;
  bool used[MAXV];
  //int cmp[MAXV];
  scc() {}
  void dfs(int v) {
    used[v] = true;
    for(auto c: G[v]) if(!used[c]) dfs(c);
    vs.push_back(v);
  }
  void rdfs(int v, int k) {
    used[v] = true;
    //cmp[v] = k;
    for(auto c: rG[v]) if(!used[c]) rdfs(c, k);
  }
  int build(int V) {
    std::fill_n(used, V, false);
    vs.clear();
    for(int v = 0; v < V; ++v) if(!used[v]) dfs(v);
    std::fill_n(used, V, false);
    int k = 0;
    for(int i = vs.size()-1; i >= 0; --i) {
      if(!used[vs[i]]) rdfs(vs[i], k++);
    }
    return k;
  }
  void add_edge(int fr, int to) {
    G[fr].push_back(to); rG[to].push_back(fr);
  }
};

int const MAXN = 5e5;

scc<MAXN> sc;
int depth[MAXN];
int calc_depth(int v) {
  if(depth[v] >= 0) return depth[v];
  int res = -1;
  for(auto c: sc.G[v]) res = std::max(res, calc_depth(c));
  ++res;
  return depth[v] = res;
}


struct rolling_hash {
  __uint128_t m_, b_, bl_;
  int l_;
  rolling_hash(int64_t mod, int64_t base, int length)
    : m_(mod), b_(base), l_(length) {
    bl_ = 1;
    __uint128_t v = b_;
    while(length > 0) {
      if(length&1) (bl_ *= v) %= m_;
      length/=2; (v *= v) %= m_;
    }
  }
  int64_t hash(char const* s) {
    __uint128_t res = 0;
    for(int i = 0; i < l_; ++i) (res = res*b_%m_ + s[i]) %= m_;
    return res;
  }
  int64_t next(int64_t hash, char in_c, char out_c) {
    __uint128_t h = hash;
    (h = h*b_%m_ + in_c + (m_ - out_c)*bl_%m_) %= m_;
    return h; 
  }
};


int main() {
