    if(M+i >= K) break;
    u1 = rh1.next(u1, U[M+i], U[i]);
  }

  if(v.size() < 1) fin(0);
  for(int fr: v) {
    int to = (fr+M)%N;
    if(fr == to) fin(-1);
    sc.add_edge(fr, to);
  }
