vector<int> z(const string &s)
{
    int n = (int) s.size(), L = 0, R = 0;
    vector<int> zs(n, 0);

    for (int i = 1; i < n; i++)
    {
        if (i <= R)
            zs[i] = min(zs[i - L], R - i + 1);

        while (zs[i] + i < n && s[zs[i]] == s[i + zs[i]])
            zs[i]++;

        if (R < i + zs[i] - 1)
            L = i, R = i + zs[i] - 1;
    }

    return zs;
}

int max_seq(const vector<int>& zs, int k)
{
    int i = k + 1, res = 0, N = (int) zs.size(), count = 0;

    while (i < N)
    {
        if (zs[i] != k)
        {
            count = 0; 
            ++i;
            continue;
        }

        ++count;
        res = max(res, count);

        i += k;
    } 

    return res;
}

int solve(string& s, string& t)
{
    while (s.size() < t.size())
        s += s;

    auto p = t + '#' + s;
    auto zs = z(p);

    int ans = max_seq(zs, (int) t.size());

#ifdef DEBUG
    cout << "zs = " << endl;

    for (size_t i = 0; i < p.size(); ++i)
        cout << setw(3) << p[i];
    cout << endl;

    for (size_t i = 0; i < p.size(); ++i)
        cout << setw(3) << i;
    cout << endl;

    for (auto x : zs)
        cout << setw(3) << x;
    cout << endl;

    cout << "ans = " << ans << endl;
#endif

    p += s;
    zs = z(p);

    int res = max_seq(zs, (int) t.size());

    if (res == ans)
        return ans;

    ans = res;

    p += s;
    zs = z(p);

    res = max_seq(zs, (int) t.size());

    if (res == ans)
        return ans;

    return -1;
}

int main()
{
    ios::sync_with_stdio(false);

    string s, t;
    cin >> s >> t;

    auto ans = solve(s, t);

    cout << ans << '\n';

    return 0;
}

