int edge[500010], dist[500010];
bool used[500010], in[500010];
signed main() {
	cin >> s >> t;
	int n = s.size();
	string ns;
	while (ns.size() < t.size() * 2)ns += s;
	s = ns;
	fill(edge, edge + n, -1);
	RollingHash rhs1(s, mod, 1007), rhs2(s, mod, 10007), rht1(t, mod, 1007), rht2(t, mod, 10007);
	bool f = false;
	rep(i, n) {
		if (i + t.size() > s.size())continue;
		if (rhs1.query(i, i + t.size()) == rht1 && rhs2.query(i, i + t.size()) == rht2) {
			edge[i] = (i + t.size()) % n;
			in[(i + t.size()) % n] = true;
			f = true;
		}
	}
	if (!f) {
		cout << 0 << endl;
		return 0;
	}
	queue<int> que;
	int ans = -1;
	rep(i, n) {
		if (!used[i] && !in[i]) {
			que.push(i);
			dist[i] = 0;
			used[i] = true;
			while (!que.empty()) {
				int node = que.front();
				que.pop();
				if (dist[node])ans = max(ans, dist[node]);
				if (edge[node] != -1) {
					if (used[edge[node]]) {
						cout << -1 << endl;
						return 0;
					}
					dist[edge[node]] = dist[node] + 1;
					used[node] = true;
					que.push(edge[node]);
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

