		}
	}
	string ss = s;
	while ((int) s.size() < (int) t.size()) s += ss;
	ss = s;
	s += ss;
	s += ss;
	s += ss;
	s += ss;
	h[0] = h2[0] = 0; 
    for (int i = 0; i < (int) s.size(); i++)
        h[i+1] = (h[i] + (s[i] - 'a' + 1) * p_pow[i]) % m, h2[i+1] = (h2[i] + (s[i] - 'a' + 1) * p_pow2[i]) % m2, h3[i+1] = (h3[i] + (s[i] - 'a' + 1) * p_pow3[i]) % m3; 
    int lo = 0, hi = 3e6 + 55;
