namespace zyt
{
	const int N = 5e5 * 5 + 10;
	string s, t;
	bool vis[N], cnt;
	int n, m;
	namespace KMP
	{
		int fail[N];
		void getfail(const string &s)
		{
			fail[0] = fail[1] = 0;
			for (int i = 1; i < s.size(); i++)
			{
				int tmp = fail[i];
				while (tmp && s[i] != s[tmp])
					tmp = fail[tmp];
				fail[i + 1] = (s[i] == s[tmp] ? tmp + 1 : 0);
			}
		}
		void query(const string &s, const string &t)
		{
			getfail(t);
			int now = 0;
			for (int i = 0; i < s.size(); i++)
			{
				while (now && (now == t.size() || s[i] != t[now]))
					now = fail[now];
				if (s[i] == t[now])
					++now;
				if (now == t.size())
					vis[i] = true;
			}
		}
	}
	bool check()
	{
		for (int i = 0; i < s.size(); i++)
			if (s[i] != s[0])
				return false;
		for (int i = 0; i < t.size(); i++)
			if (t[i] != t[0])
				return false;
		return s[0] == t[0];
	}
	int work()
	{
		cin >> s >> t;
		if (check())
		{
			printf("-1");
			return 0;
		}
		static string buf;
		buf = s;
		while (s.size() < t.size())
			s += buf;
		s += s;
		s += s.substr(0, t.size() - 1);
		KMP::query(s, t);
		n = s.size(), m = t.size();
		int ans = 0;
		for (int i = 0; i < n; i++)
		{
			if (vis[i] && (i < m || !vis[i - m]))
			{
				int num = 0, tmp = i;
				while (tmp < n && vis[tmp])
					++num, tmp += m;
				ans = max(ans, num);
			}
		}
		if (ans >= n / m)
		{
			printf("-1");
			return 0;
		}
		printf("%d", ans);
		return 0;
	}
}
int main()
{
	return zyt::work();
}

