	rep (i, 1, SZ(s) - 1) {
		while (~j && s[i - 1] != s[j]) j = fail[j];
		fail[i] = ++j;
	}
	int now = 0, flag = 0;
	rep (i, 0, SZ(t) - 1) {
		if (t[i] != s[now] && flag == -1) return false;
		while (~now && t[i] != s[now]) now = fail[now];
		if (++now == SZ(s)) flag = -1, now = 0;
	}
	if (~flag) return false;
	return true;
}
inline bool check(int mid) {
	int l = SZ(s) * mid;
	ulint use = 0, use2 = 0, use3 = 0;
	rep (i, 1, mid) {
		use = use * mul[SZ(s)] + getHash(Hash[1], 0, SZ(s) - 1);
		use2 = (use2 * mul2[SZ(s)] + getHash2(Hash2[1], 0, SZ(s) - 1)) % MOD1;
		use3 = (use3 * mul3[SZ(s)] + getHash3(Hash3[1], 0, SZ(s) - 1)) % MOD2;
	}
	rep (i, 0, SZ(t)) {
		if (i + l > SZ(t)) return false;
		if (getHash(Hash[0], i, i + l - 1) == use && getHash2(Hash2[0], i, i + l - 1) == use2 && getHash3(Hash3[0], i, i + l - 1) == use3) return true;
	}
	return false;
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(NULL), cout.tie(NULL);
	cin >> T >> s;
	while (SZ(t) < SZ(s)) t += T; t += t;
	mul[0] = 1;
	mul2[0] = 1;
	mul3[0] = 1;
	rep (i, 1, MAXN - 1) {
		mul[i] = mul[i - 1] * 2323;
		mul2[i] = mul2[i - 1] * 32323 % MOD1;
		mul3[i] = mul3[i - 1] * 20141023 % MOD2;
	}
	DoHash(Hash[0], t);
	DoHash(Hash[1], s);
	DoHash2(Hash2[0], t);
	DoHash2(Hash2[1], s);
	DoHash3(Hash3[0], t);
	DoHash3(Hash3[1], s);
	int l = 1, r = SZ(t) / SZ(s);
	while (l <= r) {
		int mid = (l + r) >> 1;
		if (check(mid)) l = mid + 1;
		else r = mid - 1;
	}
	int ans = l - 1;
	t += t;
	DoHash(Hash[0], t);
	DoHash2(Hash2[0], t);
	DoHash3(Hash3[0], t);
	l = 1, r = SZ(t) / SZ(s);
	while (l <= r) {
		int mid = (l + r) >> 1;
		if (check(mid)) l = mid + 1;
		else r = mid - 1;
	}
	if (ans == l - 1) cout << ans << endl;
	else cout << -1 << endl;
	return 0;
}

