int pre[MAXN];

void kmp(char *s, int n)
{
	for (int i = 2; i <= n; ++ i)
	{
		int j = pre[i-1];
		while (j && s[j+1] != s[i]) j = pre[j];
		pre[i] = s[j+1] == s[i] ? j+1 : 0;
	}
}

int n, m;
char s[MAXN], t[MAXN];

bool u[MAXN], in[MAXN];
int to[MAXN], F[MAXN];

int head, tail, Q[MAXN];

int main()
{

	scanf("%s", s+1);
	scanf("%s", t+1);
