	m = strlen(t+1);

	int multi = m/n+1;

	if ((multi+1)*n > 4000000)
	{
		puts("caonima");
		return 0;
	}

	for (int k = 1; k <= multi; ++ k)
		for (int i = 1; i <= n; ++ i)
		{
			if (k*n+i > 4000000)
			{
				puts("caonima");
				return 0;
			}
			s[k*n+i] = s[i];
		}

	return 0;

	int N = (multi+1)*n;

	kmp(t, m);

	int cur = 0;
	int flag = 0;
	for (int i = 1; i <= N; ++ i)
	{
		while (cur && s[i] != t[cur+1]) cur = pre[cur];
		if (s[i] == t[cur+1]) cur ++;
		if (cur == m)
		{
			flag = 1;
