    while (s.size() < t.size())
        s += s;

    int n = s.size();
    int m = t.size();

    vector<int> z = Z(t + "$" + s + s);
    int st = m + 1;
    int en = st + n - 1;

    for (int i = st ;i <= en ;i++)
        if (z[i] >= m)
            adj[i - st].push_back((i - st + m) % n);

    for (int i = 0 ;i < s.size() ;i++) {
        if (cycle(i)) {
            cout << -1;
            return 0;
        }
    }

    memset(memo , -1 , sizeof memo);
    int mx = 0;
    for (int i = 0 ;i < s.size() ;i++)
        mx = max(mx , solve(i));

    cout << mx;
}

