int calc(string S, string T) {
	int N = S.size();
	int M = T.size();
	while (S.size() < 5*1e6)S += S;
	int fir = 0;
	REP(i, M) {
		fir = mult(fir, b);
		fir += S[i] - 'a' + 1;
	}
	Hash[0] = fir;
	//print(Hash[0]);
	REP(i, 5*1e6 - M) {
		int res = Hash[i];
		res = mult(res, b);
		res = sub(res, mult(S[i] - 'a' + 1, bin_pow(b, M)));
		res = add(res, S[i + M] - 'a' + 1);
		Hash[i + 1] = res;
		//if(i<20)print(Hash[i + 1]);
	}
	int mx = 0;
	REP(i, 5*1e6 - M) {
		//if (i > 1000)break;
		if (used[i])continue;
		used[i] = true;
		int cnt = 0;
		if (Hash[i] == hash_t) {
			cnt++;
			//pe(i); print(cnt);
			int nex = i + M;
			used[nex] = true;
			while (nex < 5 * 1e6 - M &&Hash[nex] == hash_t) {
				cnt++;
