    const Int BASE = 131;
    vector<Int> hash, power;
    RollingHash(const string& s) {
        hash.resize(s.size() + 1);
        power.resize(s.size() + 1);
        hash[0] = 0; power[0] = 1;
        for (int i = 0; i < s.size(); i++) {
            hash[i+1] = (hash[i] * BASE + s[i]) % MOD;
            power[i+1] = (power[i] * BASE) % MOD;
        }
    }
    Int get(int l, int r) {
        return (hash[r] + (MOD - hash[l]) * power[r - l]) % MOD;
    }
};
int main()
{
    string S, T; cin >> S >> T;
    string U;
    while (U.size() < max(S.size(), T.size())*2) U += S;
    auto rh = RollingHash(U);
    auto t = RollingHash(T).get(0, T.size());
    vector<int> dp(U.size()+1);
    for (int i = 0; i+T.size() <= U.size(); i++) {
        bool b = rh.get(i, i+T.size()) == t;
        if (b) {
            dp[i] = (i >= T.size() ? dp[i-T.size()] : 0) + b;
        }
    }
    int maxval = *max_element(begin(dp), end(dp));
    if (maxval * T.size() >= S.size()) {
        cout << -1 << endl;
    } else {
        cout << maxval << endl;
    }
    return 0;
}

