RollingHash rht(t);
vector<int> scnt;

int func(int pos) {
	if (scnt[pos] == -2) {
		cout << -1 << endl;
		exit(0);
	}
	if (scnt[pos] == -1) {
		scnt[pos] = -2;
		if (rh.get(pos,pos+t.size()) == rht.get(0,t.size())) {
			return scnt[pos] = func((pos+t.size())%s.size()) + 1;
		} else {
			return scnt[pos] = 0;
		}
	} else {
		return scnt[pos];
	}
}

bool solve() {
	string cats = s + s;
