    SuffixArrayByInducedSorting<128> sa_repS;
    sa_repS.build_sa(repS);

    vector<bool> match(S.size());
    {
        int ll = 0, lh = repS.size();
        while (lh - ll > 1) {
            int lm = (ll + lh) / 2;
            if (compare(repS, T, sa_repS.sa[lm], 0) > 0) ll = lm;
            else lh = lm;
