        int hl = 0, hh = repS.size() + 1;
        while (hh - hl > 1) {
            int hm = (hl + hh) / 2;
            if (compare(repS, T, sa_repS.sa[hm], 0) < 0) hh = hm;
            else hl = hm;
        }
        rep(i, lh, hh) {
            if (sa_repS.sa[i] < (int)S.size()) match[sa_repS.sa[i]] = true;
        }
