            iseq.push_back(now);
            now = (now + T.size()) % S.size();
        }
        if (nrep[now] >= 0) {
            for (int i = iseq.size() - 1, n = nrep[now]  + 1; i >= 0; --i, ++n) {
                nrep[iseq[i]] = n;
            }
        }
