        par.resize(N);
        siz.resize(N,1);
        rep(i,0,N) par[i]=i;
    }
    ll root(ll X){
        if(par[X]==X) return X;
        return par[X]=root(par[X]);
    }
    bool same(ll X,ll Y){
        return root(X)==root(Y);
    }
    void unite(ll X,ll Y){
        X=root(X);
        Y=root(Y);
        if(X==Y) return;
        par[X]=Y;
        siz[Y]+=siz[X];
        siz[X]=0;
    }
    ll size(ll X){
        return siz[root(X)];
    }
};
ll modpow(ll X,ll Y,ll mod){
    ll sum=X,cnt=1;
    vi A;
    while(cnt<=Y){
        A.pb(sum);
        sum*=sum;
        sum%=mod;
        cnt*=2;
    }
    int M=A.size();
    ll ret=1;
    REP(i,1,M){
        if(Y>=(1ll<<M-i)){
            Y-=(1ll<<M-i);
            ret*=A[M-i];
            ret%=mod;
        }
    }
    return ret;
}
vi fac,finv,inv;
void COMinit() {
    fac.resize(MAX);
    finv.resize(MAX);
    inv.resize(MAX);
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
ll COM(ll n,ll r){
    if(n<r||n<0||r<0) return 0;
    return fac[n]*finv[r]%MOD*finv[n-r]%MOD;
}
bool check(string &S,string &T){
    S+=S;
    ll N=T.size(),M=S.size();
    vi hash(5),memo(5);
    srand((unsigned)time(NULL)); 
    rand(),rand(),rand(),rand();
    rep(i,0,10){
        hash[i]=rand()%MOD+1;
        memo[i]=modpow(10,N,hash[i]);
    }
    vi goal(5),now(5);
    rep(i,0,5){
        rep(j,0,N){
            ll X=T[j]-'a';
            goal[i]=(goal[i]*10+X)%hash[i];
            X=S[j]-'a';
            now[i]=(now[i]*10+X)%hash[i];
        }
    }
    rep(i,N,M){
        bool flag=1;
        rep(j,0,5){
            ll X=S[i-N]-'a';
            now[j]*=10;
            now[j]%=hash[j];
            now[j]-=memo[j]*X%hash[j];
            X=S[i]-'a';
            now[j]+=X;
            now[j]%=hash[j];
            if(now[j]<0) now[j]+=hash[j];
            if(now[j]!=goal[j]) flag=0;
        }
        if(flag) return 1;
    }
    return 0;
}
