        if(check(S,T)){
            if(S.size()==T.size()) cout<<-1<<endl;
            else{
                X="";
                T+=T;
                while(S.size()<T.size()){
                    S+=X;
                }
                if(check(S,T)) cout<<-1<<endl;
                else cout<<1<<endl;
            }
        }
        else cout<<0<<endl;
        return 0;
    }
    ll left=0,right=(N+M-1)/M;
    while(left+1<right){
        string X;
