	while (S.length() < len_t * 2)S += S;

	ok.resize(len_s);

	ll key = 101;
	ll pow_t=1LL;
	rep(i, len_t)pow_t = pow_t*key%MOD;
	ll s_hash=0, t_hash = 0;
	rep(i, len_t)s_hash = (s_hash*key+S[i])%MOD;
	rep(i, len_t)t_hash = (t_hash*key+T[i])%MOD;

	rep(i, len_s) {
		if (i == 0) {
			if (s_hash == t_hash)ok[i] = 1;
		}
		else {
			s_hash = (s_hash*key%MOD + S[i - 1 + len_t] + MOD - (S[i - 1] * pow_t)%MOD) % MOD;
			if (s_hash == t_hash)ok[i]=1;
		}
	}
	UF uf(len_s);
	rep(i, len_s) {
		if (ok[i] && ok[(i + len_t) % len_s]) {
			if (uf.same(i, (i + len_t) % len_s)) {
				P(-1);
				return -1;
			}
			uf.unite(i, (i + len_t) % len_s);
		}

	}
	int ans = 0;
	rep(i, len_s) {
		if(ok[i])ans = max(ans, uf.size(i));
	}
	P(ans);

	return 0;


}

