void dfs(int u){
    vis[u] = 1;
    for(int v : g[u]){
        if(vis[v] == 1){
            ok = 1;
        }
        if(!vis[v]){
            dfs(v);
        }
    }
    vis[u] = 2;
    if(has[u]) 
        topo.push_back(u);
}

