ll const M = mods[r()&63],base1 = r()%M,base2 = r()%M;

struct RollingHash {
private:
    vector<ll> power1,power2,hash1,hash2;
public:
    RollingHash(string& s) {
        int n = s.size();
        power1.resize(n+1);
        power2.resize(n+1);
        hash1.resize(n+1);
        hash2.resize(n+1);
        power1[0] = power2[0] = 1;
        hash1[0] = hash2[0] = 0;
        for (int i = 0;i < n;++i) power1[i+1] = power1[i]*base1%M;
        for (int i = 0;i < n;++i) power2[i+1] = power2[i]*base2%M;
        for (int i = 0;i < n;++i) hash1[i+1] = (hash1[i]*base1+s[i])%M;
        for (int i = 0;i < n;++i) hash2[i+1] = (hash2[i]*base2+s[i])%M;
    }

    Pll hash(int l, int r)  {
        if (l) return make_pair((hash1[r]+M-hash1[l]*power1[r-l]%M)%M,(hash2[r]+M-hash2[l]*power2[r-l]%M)%M);
        return make_pair(hash1[r],hash2[r]);
    }


    Pll connect(Pll h1,int l,int r) {
        Pll h2 = hash(l,r);
        return make_pair((h1.first*power1[r-l]+h2.first)%M,(h1.second*power2[r-l]+h2.second)%M);
    }

    int LCP(int l1,int r1,RollingHash& rh,int l2,int r2) {
        int ok = 0,ng = min(r1-l1,r2-l2)+1;
        while (ng-ok > 1) {
            int mid = (ok+ng)/2;
            if (hash(l1,l1+mid) == rh.hash(l2,l2+mid)) ok = mid;
            else ng = mid;
        }
        return ok;
    }
};

