auto calc(const std::string &s) {
    std::vector<int> a(s.size() + 1);
    a[0] = -1;
    for (int i = 0, j = -1; i < s.size(); i++) {
        while (j >= 0 && s[i] != s[j]) j = a[j];
        j++;
        a[i + 1] = s[i + 1] == s[j] ? a[j] : j;
    }
    return a;
}

auto find(const std::string &s, const std::string &t, const std::vector<int> &a, int ss = 0, int ts = 0) {
    for (int i = ss, j = ts; i < s.size(); i++) {
        while (j >= 0 && s[i] != t[j]) j = a[j];
        if (++j == t.size()) return i - t.size() + 1;
    }
    return s.size();
}

int main() {
    std::string s, t;
    std::cin >> s >> t;
    int n = s.size(), m = t.size();
    std::vector<int> e(s.size());
    auto ss = s;
    while (ss.size() < s.size() + t.size()) ss += s;
    auto a = calc(t);

    for (int i = 0, j = 0; i < ss.size();) {
        auto k = find(ss, t, a, i, j);
        if (k == ss.size()) break;
        e[k % n] = 1;
        i = k + t.size();
        j = a[m];
    }

    int ret = 0;
    std::vector<int> p(n);
    for (int i = 0; i < n; i++) {
        if (e[i] < 0 || p[i]) continue;
        int j = i, tmp = 0;
