void computeLPSArray(string str, int M, int lps[]) 
{ 
    int len = 0;
    int i; 

    lps[0] = 0;
    i = 1; 

    while (i < M) 
    { 
       if (str[i] == str[len]) 
       { 
           len++; 
           lps[i] = len; 
           i++; 
       } 
       else
       { 
          if (len != 0) 
          { 
             len = lps[len-1]; 

          } 
          else
          { 
             lps[i] = 0; 
             i++; 
          } 
       } 
    } 
} 

int isRepeat(string str) 
{ 
    int n = str.length();; 
    int lps[n]; 

    computeLPSArray(str, n, lps); 
    int len = lps[n-1]; 
    return (len > 0 && n%(n-len) == 0)? n-len: -1; 
} 

void KMPSearch(string pat, string txt) 
{ 
    int M =pat.length(); 
    int N = txt.length(); 


    int lps[M]; 

    computeLPSArray(pat, M, lps); 

    int i = 0; // index for txt[] 
    int j = 0; // index for pat[] 
    while (i < N) { 
        if (pat[j] == txt[i]) { 
            j++; 
            i++; 
        } 

        if (j == M) { 
            v.pb(i-j);
            j = lps[j - 1]; 
        } 
		else if (i < N && pat[j] != txt[i]) { 
            if (j != 0) 
                j = lps[j - 1]; 
            else
                i = i + 1; 
        } 
    } 
} 


bool is(string a,string b){
	int x=isRepeat(a), y=isRepeat(b);

	if(min(x,y)==-1 || x!=y ) return false;
	for(int i=0;i<x;i++) if(a[i]!=b[i]) return false;
	return true; 
}

