    }
    ll n = u.size();
    u += u;

    // cout << s << "\n";
    // cout << t << "\n";

    vec T = kmp_table(t);
    vec result = kmp_search(u, t, T);
    graph.assign(n, vec());
    for (ll e : result) {
        if (e < n) graph[e].push_back((e+t.size())%n);
    }

    dp.assign(n, 0);
    status.assign(n, -1);

    Rep (i, n) {
        if (status[i] == -1) {
            dfs(i);
        }
    }

    ll ans = 0;
    Rep (i, n) {
        chmax(ans, dp[i]);
    }

    cout << ans << "\n";
}

// 解き直し.
// ABC 135解説
// https://img.atcoder.jp/abc135/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
const int MAX = 543210;
bool match[MAX];
int kmpTable[MAX];
vector<vector<int>> graph(MAX);
int depth[MAX];

// KMPテーブルの作成を行う.
// https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
// @param W: 解析する単語.
// @return: 特に無し.
void createTableOfKMP(string W){

    // 1. 変数宣言.
    int c = 2; // KMPテーブル の中で, 現在計算している位置.
    int n = 0; // 現在見ているサブ文字列の次の文字のインデックス.

    // 2. 先頭ふたつの値を設定.
    kmpTable[0] = -1;
    kmpTable[1] =  0;

    // 3. KMPテーブルの更新.
    int l = W.size();
    while(c < l){
        // サブ文字列は, 継続中.
        if(W[c - 1] == W[n]) kmpTable[c] = n + 1, c++, n++;

        // サブ文字列は継続しないが, フォールバック可能.
        else if(n > 0) n = kmpTable[n];

        // 対象をはみ出した.
        else kmpTable[c] = 0, c++;
    }

    return;
}

// KMPアルゴリズムで文字列検索を行う.
// https://ja.wikipedia.org/wiki/クヌース–モリス–プラット法
// @param S: 検索対象のテキスト.
// @param W: 検索する単語.
// @param ver: 照合開始位置.
// @return ret: W が 見つかった際の S 内 の 位置, 0-indexとする.
int searchByKMP(string S, string W, int ver){

    // 1. 変数宣言.
    int cs = ver; // S内の現在照合中の開始位置.
    int cw = 0;   // W内の現在位置.

    // 2. KMPテーブルをもとに, S 内 で, W を 照合していく.
    int sLen = S.size(), wLen = W.size();
    while(cs + cw < sLen){
        if(W[cw] == S[cs + cw]){
            cw++;
            if(cw == wLen) return cs;
        }else{
            cs = cs + cw - kmpTable[cw];
            if(cw > 0) cw = kmpTable[cw];
        }
    }

    // 3. W が S 内 で見つからなかった場合.
    return sLen;
}

// グラフの経路を探索する.
// 深さ優先探索(depth-first search).
// https://ja.wikipedia.org/wiki/深さ優先探索
// @param c: 探索地点となる頂点.
// @param b: 探索地点から見て, 前回探索済の頂点.
// @param d: 探索開始地点からの距離.
// @return : 特に無し.
void dfs(int c, int b, int d) {
    depth[c] = d;
    for (auto &e : graph[c]) {
        if(e == b) continue;
        dfs(e, c, d + 1);
    }
}

int main(){

    // 1. 入力情報取得.
    char X[MAX], Y[MAX];
    scanf("%s %s", X, Y);
    string S(X), T(Y);
    int sLen = S.size(), tLen = T.size();

    // 2. (解説通り) s' の 部分文字列(i文字目 ～ (i + tLen - 1)文字目)が, 
    // t と 一致するかどうか.

    // 2-1. 部分マッチテーブル生成.
    // ex.
    // "ABCDABD" の 場合, kmpTable は, -1 0 0 0 0 1 2 
    // createTableOfKMP("ABCDABD");
    // for(int i = 0; i < 7; i++) printf("%d ", kmpTable[i]);

    // 2-2. 疑似文字列 s' の 生成.
    string pseudoS = "";
    while(pseudoS.size() < sLen + tLen) pseudoS += S;
    // printf("pseudoS=%s\n", pseudoS.c_str());
    createTableOfKMP(T);
    // for(int i = 0; i < tLen; i++) printf("%d ", kmpTable[i]);

    // 2-3. 検索アルゴリズムの結果を元に, matchテーブルを更新.
    // -> matchテーブル更新のために, 複数回必要に見える.
    // ex.
    // S = "ABC ABCDAB ABCDABCDABDE"
    // W = "ABCDABD"
    // の 場合, r=15
    // int r = searchByKMP("ABC ABCDAB ABCDABCDABDE", "ABCDABD", 0);
    // printf("r=%d\n", r);

    // ex.
    // S = ab, T = abab
    // -> pseudoS=ababab
    // -> pseudoS 内で, T が見つかる位置は, r = 0, 2
    int l = 0;
    while(l < sLen){
        // 検索アルゴリズムの実行.
        int r = searchByKMP(pseudoS, T, l);
        // printf("r=%d\n", r);

        // matchテーブル更新.
        match[r] = true;

        // ループ変数に加算.
        l += (r + 1);
    }

    // 3. 有向グラフの最長パスを計算.
    // 3-1. 有向グラフ構築.
    for(int i = 0; i < sLen; i++){
        if(match[i]){
            // u -> v
            int u = i, v = (i + tLen) % sLen;
            graph[u].push_back(v);
            // printf("u=%d ---> v=%d\n", u, v);
        }
    }

    // 3-2. 最長パスの計算.
    for(int i = 0; i < sLen; i++) if(depth[i] == 0) dfs(i, -1, 0);
    // for(int i = 0; i < sLen; i++) printf("match[%d]=%d depth[%d]=%d ", i, match[i], i, depth[i]);
    // printf("\n");
    int ans = 0;
    for(int i = 0; i < sLen; i++) ans = max(ans, depth[i]);

    // 4. TODO: 無限個存在する場合.
    // -> depth の 最大値 が, sLen - 1 に一致する場合と見做す.
    string inf = pseudoS.substr(0, tLen);
    if(ans == sLen - 1){
        printf("%d\n", -1);
        return 0;
    }

    // 5. 出力 ～ 後処理.
    printf("%d\n", ans);
    return 0;

}

