void relax(vector<pair<int, int>> cand) {
	int cx = 0;
	int cy = 0;
	for (auto t : cand) {
		cx += t.first;
		cy += t.second;
		assert(abs(t.first) == K || abs(t.second) == K);
		assert(abs(t.first) <= K && abs(t.second) <= K);

		assert((t.first + t.second) % 2 == 0);
	}
	int dx = abs(ex - cx);
	int dy = abs(ey - cy);
	if (dx % K || dy % K) return;
	assert(dx % K == 0);
	assert(dy % K == 0);
	int cur = max((dx / K), (dy / K)) + (int)cand.size();
	if (cur < ans)  {
		ans = cur;
		bx = cx;
		by = cy;
		fp = cand;
	}
}

