template <typename T>
struct RollingHash
{
	T& ary;
	int size;
	int n;
	vector<ll> factor;
	ll b = 0;
	ll mod = 0;
	ll hash = 0;
	int index = -1;

	RollingHash(T& _ary, int _size, int _n, ll _b = (ll)1e8 + 7, ll _mod = (ll)1e9 + 7) : ary(_ary)
	{
		size = _size;
		n = _n;
		b = _b;
		mod = _mod;
		auto temp = 1ll;
		for (auto i = 0; i < n; ++i)
		{
			factor.push_back(temp);
			temp = temp * b % mod;
		}
		for (auto i = 0; i < n; ++i)
		{
			hash = (hash + ary[i] * factor[n - i - 1] % mod) % mod;
		}
	}

	bool moveNext() {
		if (index + n >= size)
		{
			return false;
		}
		if (index < 0)
		{
			++index;
			return true;
		}

		hash = (((hash - ary[index] * factor[n - 1]) % mod) + mod) % mod;
		hash = hash * b % mod;
		hash = (hash + ary[index + n]) % mod;
		++index;
		return true;
	}

	ll getHash() { return hash; }
	int getIndex() { return index; }
};

int main()
{
	string s;
	string t;
	cin >> s >> t;

	auto temp = s;
	while (s.length() < t.length())
	{
		s += temp;
	}
	auto len = (int)s.length();
	s = s + s + s + s;

	auto b1 = (ll)1e5 + 7;
	auto b2 = (ll)1e8 + 7;
	RollingHash<string> hash1(t, t.length(), t.length(), b1);
	RollingHash<string> hash2(t, t.length(), t.length(), b2);

	RollingHash<string> r1(s, s.length(), t.length(), b1);
	RollingHash<string> r2(s, s.length(), t.length(), b2);
	vector<int> num((int)s.length());
	while (r1.moveNext() != false)
	{
		r2.moveNext();
		if (r1.getHash() == hash1.getHash()
			&& r2.getHash() == hash2.getHash())
		{
			auto index = r1.getIndex();
			++num[index];
		}
	}
	for (auto i = (int)s.length() - 1; i >= (int)t.length(); --i)
	{
		if (num[i - (int)t.length()] > 0)
		{
			num[i - (int)t.length()] += num[i];
		}
	}

	auto ans = -1;
	for (auto i = 0; i < len; ++i)
	{
		ans = max(num[i], ans);
	}

	if (ans * t.length() >= 2 * len)
	{
		ans = -1;
	}

	cout << ans << endl;

	return 0;
}

