vector< int > z_algorithm(const string &s) {
    vector< int > prefix(s.size());
    for (int i = 1, j = 0; i < s.size(); i++) {
        if (i + prefix[i - j] < j + prefix[j]) {
            prefix[i] = prefix[i - j];
        } else {
            int k = max(0, j + prefix[j] - i);
            while (i + k < s.size() && s[k] == s[i + k]) ++k;
            prefix[i] = k;
            j = i;
        }
    }
    prefix[0] = (int) s.size();
    return prefix;
}


const int maxv = 500005;
vi Grh[maxv];
vi indeg(maxv);
vi path(maxv);
vi color(maxv);



//cycle検出のみ
bool dfs1(int v) {
    if (color[v] == 0) color[v]  = 1;
    bool f = true;

    for (auto next : Grh[v]) {
        if (color[next] == 2) continue;
        if (color[next] == 1) return false;
        f &= dfs1(next);
    }

    color[v] = 2;
    return f;
}

//DAGのパス長
int dfs2(int v) {
    int &res = path[v];
    if (~res) return res;
    res = 0;

    for (auto next : Grh[v]) {
        res = max (res, dfs2(next) + 1);
    }
    return res;
}



