bool check(int len){
    if(len==0) return 1;
    if(len*m>s.size()) return 0;
    ll nowt=ts[len];
    ll cur=has[len*m-1];
    for(int i=1;i<=n-len*m;i++){
        if(cur==nowt) return 1;
        cur=(has[i+len*m-1]+mod-has[i-1]*po[len*m]%mod)%mod;
