	}

	void construct(const vector<int> &vec){
		int n=vec.size();
		for(int i=0;i<MD;i++){
			hash[i][0]=0;
			for(int j=0;j<n;j++){
				hash[i][j+1]=(hash[i][j]*base[i]%mods[i]+vec[j])%mods[i];
			}
		}
	}

	// calc hash value [l,r)
	ll hash_value(int l,int r,int i){
		return ((hash[i][r]-hash[i][l]*pw[i][r-l])%mods[i]+mods[i])%mods[i];
	}
};

