const int maxn = 1e6 + 10;
char s[maxn], t[maxn], s1[maxn];
int fs[maxn], ft[maxn], memo[maxn], lens, lent;
unordered_set<int> match;

void getfail(char p[], int f[]) {
  int n = strlen(p);
  for (int i = 1; i < n; ++i) {
    int j = f[i];
    while (j && p[j] != p[i]) j = f[j];
    if (p[j] == p[i]) f[i + 1] = j + 1;
  }
}

int dp(int i) {
  if (!match.count(i)) return 0;
  if (memo[i]) return memo[i];
  return memo[i] = dp((i + lent) % lens) + 1;
}

int main() {
  #ifdef LOCAL
  freopen("in", "r", stdin);
  freopen("out", "w", stdout);
  #endif

  ios::sync_with_stdio(false);
  cin >> s >> t;
  getfail(s, fs);
  getfail(t, ft);
  lens = strlen(s), lent = strlen(t);
  int cyclen = lens - fs[lens];

/*  for (int i = 0; i <= lens; ++i) cout << fs[i] << ' '; cout << endl;
  for (int i = 0; i <= lent; ++i) cout << ft[i] << ' '; cout << endl;*/
  if (cyclen == lent - ft[lent] && strncmp(s, t, cyclen) == 0) {
    cout << -1;
    return 0;
  }
  strcpy(s1, s);
  strcat(s, s1);

  int j = 0;
  for (int i = 0; i < lens * 2; ++i) {
    while (j && t[j] != s[i]) j = ft[j];
    if (t[j] == s[i]) ++j;
    if (j == lent) match.insert(i % lens);
  }

  int ans = 0;
  for (int i = 0; i < lens; ++i) {
    if (match.count(i)) ans = max(ans, dp(i));
  }
  cout << ans;
  return 0;
}

