class mint {
  using u64 = std::uint_fast64_t;
    public:
    u64 a;
    constexpr mint(const u64 x = 0) noexcept : a(x % MOD) {}
    constexpr u64 &value() noexcept { return a; }
    constexpr const u64 &value() const noexcept { return a; }
    constexpr mint operator+(const mint rhs) const noexcept {
        return mint(*this) += rhs;
    }
    constexpr mint operator-(const mint rhs) const noexcept {
        return mint(*this) -= rhs;
    }
    constexpr mint operator*(const mint rhs) const noexcept {
        return mint(*this) *= rhs;
    }
    constexpr mint operator/(const mint rhs) const noexcept {
        return mint(*this) /= rhs;
    }
    constexpr mint &operator+=(const mint rhs) noexcept {
        a += rhs.a;
        if (a >= MOD) {
            a -= MOD;
        }
        return *this;
    }
    constexpr mint &operator-=(const mint rhs) noexcept {
        if (a < rhs.a) {
            a += MOD;
        }
        a -= rhs.a;
        return *this;
    }
    constexpr mint &operator*=(const mint rhs) noexcept {
        a = a * rhs.a % MOD;
        return *this;
    }
    constexpr mint operator++(int n) const noexcept {
        return mint(*this) +=1;
    }
    constexpr mint operator--(int n) const noexcept {
        return mint(*this) -=1;
    }
    constexpr mint &operator/=(mint rhs) noexcept {
        u64 exp = MOD - 2;
        while (exp) {
            if (exp % 2) {
                *this *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return *this;
    }
};
ostream& operator<<(ostream& lhs, const mint& rhs) noexcept {
    lhs << rhs.a;
    return lhs;
}
istream& operator>>(istream& lhs, const mint& rhs) noexcept {
    lhs >> rhs.a;
    return lhs;
}
inline mint pow(mint m,lint n){
    if(n==0)return 1;
    else if(n%2==0){
        mint x=pow(m,n/2);
        return x*x;
    }else{
        return m*pow(m,n-1);
    }
}
inline mint fact(lint a){
    return a?fact(a-1)*a:1;
}

template<typename T>
struct RollingHash{
    vector<T>hashed;
    T base;
    RollingHash(const string &s,T base = 10007):base(base){
        lint sz=s.size();
        hashed.assign(sz+1,0);
        T power=0;
        rep(i,sz){
            power*=base;
            hashed[i+1]=hashed[i]*base+s[i];
        }
    }
    T get(lint l,lint r){
        T ret = hashed[r]-hashed[l]*pow(base,r-l);
        return ret;
    }
    T connect(T h1,T h2,lint len){
        T ret=h1*pow(base,len)+h2;
        return ret;
    }
    pair<T,T> pow_connect(T h,lint val,lint len){
        if(val==0)return make_pair(0,1);
        if(val==1)return make_pair(h,pow(base,len));
        if(val%2){
            auto tmp=pow_connect(h,val-1,len);
            return make_pair(connect(tmp.first,h,len),tmp.second*pow(base,len));
        }else{
            auto tmp=pow_connect(h,val/2,len);
            return make_pair(tmp.first*(tmp.second+1),tmp.second*tmp.second);
        }
    }
};

lint bs(lint mn=0,lint mx=INF,function<bool(lint)> func=[](lint x){return true;}) {
    lint left = mn-1;
    lint right =mx;
    while (right - left > 1) {
        lint mid = left + (right - left) / 2;
        if (func(mid)) right = mid;
        else left = mid;
    }
    return right;
}


int main(){
    string s,t;
    cin>>s>>t;
    RollingHash<mint> sh(s),th(t),sh2(s+s);
    lint mx=0;
    rep(i,s.size()){
        mint hash1=sh.get(i,s.size())+sh.get(0,i);
        chmax(mx,bs(0,INF,[&](lint x){
            mint a=sh.connect(sh.pow_connect(hash1,x/s.size(),s.size()).first,sh2.get(i+1,i+1+x%s.size()),x%s.size());
            mint b=th.connect(th.pow_connect(th.get(0,t.size()),x/t.size(),t.size()).first,th.get(0,x%t.size()),x%t.size());
            return a.a!=b.a;
        })-1);
    }
    if(mx>INF/2)cout<<-1<<endl;
    else cout<<mx/t.size()<<endl;
}

