std::vector<int> KMP_all(const std::string& S, const std::string& W){
  std::vector<int> T(W.size());
  T[0] = -1;
  int i = 2, j = 0;
  while(i < W.size()){
    if(W[i-1] == W[j]){
      T[i] = j+1;
      i++;
      j++;
    }else if(j > 0){
      j = T[j];
    }else{
      T[i] = 0;
      i++;
    }
  }
  i = 0;
  int m = 0;
  int ns = S.size();
  std::vector<int> ans(ns);
  while(m < ns){
    if(W[i] == S[(m+i)%ns]){
      i++;
      if(i == W.size()){
        i--;
        ans[m] = 1;
        m = m+i-T[i];
        if(i > 0) i = T[i];
      }
    }else{
      m = m+i-T[i];
      if(i > 0) i = T[i];
    }
  }
  return ans;
}

int main(){
  std::string S,T;
  std::cin >> S;
  std::cin >> T;

  int ns = S.size(), nt = T.size();
  std::vector<int> f_arr = KMP_all(S, T);
  std::vector<int> l_arr(ns);
  int ans = 0;
  for(int ni = 0; ni < ns; ni++){
    if(f_arr[((ni-nt)%ns+ns)%ns] == 1) continue;
    int n = ni, i = 0;
    while(true){
      l_arr[n] = 1;
      if(f_arr[n] == 0) break;
      n = (n+T.size())%S.size();
      i++;
    }
    ans = std::max(ans, i);
  }
  for(int i = 0; i < ns; i++){
    if(l_arr[i] == 0){
      std::cout << -1 << std::endl;
      return 0;
    }
  }
  std::cout << ans << std::endl;

  return 0;
}

