  cin >> s >> t;
  string r = make(s, INF * 10);
  RollingHash<long long, MOD, B> rh(r);
  int ans = lower_search(rh, r);
  if(ans == INF) ans = 0;
  cout << ans-1 << endl;
  return 0;
