    while(r.size()<t.size()+s.size()+t.size()){
        r+=s;
    }
    int n=s.size();
    int m=t.size();
    vector<bool> can(n,false);
    auto z=Zalgo(r);
    for(int i=m;i<m+n;i++){
        if(z[i]>=m)can[i-m]=true;
    }
    int res=0;
    UnionFind uf(n);
    for(int i=0;i<n;i++){
        if(can[i]){
            int j=(i+m)%n;
            if(uf.same(i,j)){
                printf("-1\n");
                return 0;
            }
            uf.unite(i,j);
        }
    }
    for(int i=0;i<n;i++){
        res=max(res,uf.size(i)-1);
    }
    printf("%d\n",res);
}

