void lpsComp(string pat) 
{ 
    int len = 0; 
    lps.resize(pat.size());
    lps[0] = 0; 

    int i = 1; 
    while (i < pat.size()) { 
        if (pat[i] == pat[len]) { 
            lps[i] = ++len;
            i++; 
        } 
        else // (pat[i] != pat[len]) 
        { 
            if (len != 0) { 
                len = lps[len - 1]; 
            } 
            else // if (len == 0) 
            { 
                lps[i] = 0; 
                i++; 
            } 
        } 
    } 
}
