// 0 is unvisited, 1 is currently visited, 2 is retired
int dfs(int i){
   if(vis[i] == 2)return len[i];
   if(vis[i] == 1){cycle = true; return len[i];}
   vis[i] = 1;
   int nex = (i + t.length())% s.length();
   int ans = 1;
   if(match[nex]){
    ans += dfs(nex); 
   }
   vis[i] = 2;
   len[i] =ans;
   best = max(ans, best);
   return ans;
}
