template<class T> using V = vector<T>;
template<class T> using V2 = V<V<T>>;
template<class T> using V3 = V<V2<T>>;


struct UF {
  int n;
  vector< int > par;
  UF(int n) : n(n), par(n, -1) {}
  int find(int x) { return par[x] < 0 ? x : par[x] = find(par[x]); }
  int size(int x) { return -par[find(x)]; }
  bool same(int a, int b) { return find(a) == find(b); }
  void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if(a == b) return;
    if(par[a] < par[b]) swap(a, b);
    par[b] += par[a];
    par[a] = b;
  }
  void clear() { par.assign(n, -1); }
};
template<typename T>
struct MP {
  int n;
  T t;
  std::vector<int> a;
  MP() {}
  MP(const T& t): t(t) {
    n = t.size();
    a = std::vector<int>(n+1);
    a[0] = -1;
    int j = -1;
    for (int i = 0; i < n; ++i) {
      while (j != -1 && t[j] != t[i]) j = a[j];
      j++;
      a[i+1] = j;
    }
  }
  int operator[](int i) { return a[i];}
  std::vector<int> findAll(const T& s) {
    vector<int> res;
    int j = 0;
    for (int i = 0; i < s.size(); ++i) {
      while (j != -1 && t[j] != s[i]) j = a[j];
      j++;
      if (j == n) {
        res.push_back(i-j+1);
        j = a[j];
      }
    }
    return res;
  }
};


void solve(){
  string s, t; cin >> s >> t;
  while(s.size()<t.size()) s += s;
  int ns = s.size(), nt = t.size();
  s = s + s + s;
  MP<string> mp(t);
  V<int> tbl = mp.findAll(s);
  UF uf(2*ns+5);
  bool ifinf = false; int ans = 0;
  for(auto x: tbl){
    if(x>=2*ns - nt) break;
    auto it = lower_bound( ALL(tbl), x+nt );
    if(it!=tbl.end() && (*it) == x + nt) {uf.unite(x, x+nt); }
  }
  for(auto x: tbl){
    if(x>=ns) break;
    ans = max(ans, uf.size(x) );
    if(x+nt < ns) continue;
    if( uf.same(x, x+nt) &&  uf.same((x+nt)%ns, (x+nt)%ns+nt) &&  uf.same((x+nt)%ns, x) ) {ifinf = true; break;}
  }
  if(ifinf) coutn(-1);
  else coutn(ans);
}

int main(void){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
