long long power1[1 << 22], power2[1 << 22];
long long hashs1[1 << 22], hashs2[1 << 22];
long long hasht1[1 << 22], hasht2[1 << 22];

void init() {
	string U1 = ""; while (U1.size() < MAX_N * 2) U1 += S;
	string U2 = ""; while (U2.size() < MAX_N * 2) U2 += T;
	power1[0] = 1; for (int i = 1; i <= MAX_N * 2; i++) power1[i] = (BASE * power1[i - 1]) % MOD1;
	power2[0] = 1; for (int i = 1; i <= MAX_N * 2; i++) power2[i] = (BASE * power2[i - 1]) % MOD2;
	for (int i = 1; i <= MAX_N * 2; i++) hashs1[i] = (BASE * hashs1[i - 1] + (long long)(U1[i - 1] - 'a' + 1)) % MOD1;
	for (int i = 1; i <= MAX_N * 2; i++) hashs2[i] = (BASE * hashs2[i - 1] + (long long)(U1[i - 1] - 'a' + 1)) % MOD2;
	for (int i = 1; i <= MAX_N * 2; i++) hasht1[i] = (BASE * hasht1[i - 1] + (long long)(U2[i - 1] - 'a' + 1)) % MOD1;
	for (int i = 1; i <= MAX_N * 2; i++) hasht2[i] = (BASE * hasht2[i - 1] + (long long)(U2[i - 1] - 'a' + 1)) % MOD2;
}

bool solve(int pos) {
	int len = pos * T.size();
	long long val1 = hasht1[len], val2 = hasht2[len];
	for (int i = 0; i <= MAX_N * 2 - len; i++) {
		long long cur1 = (hashs1[i + len] - hashs1[i] * power1[len] + MOD1 * MOD1) % MOD1;
		long long cur2 = (hashs2[i + len] - hashs2[i] * power2[len] + MOD2 * MOD2) % MOD2;
		if (val1 == cur1 && val2 == cur2) return true;
	}
	return false;
}

int main() {
	cin >> S >> T;
	init();

	int cl = 0, cr = MAX_N / (int)T.size(), cm, maxn = 0; cr++;
	for (int i = 0; i < 24; i++) {
		cm = ((cl + cr) >> 1);
		bool I = solve(cm);
		if (I == true) { cl = cm; maxn = max(maxn, cm); }
		else { cr = cm; }
	}
	if (cm == MAX_N / (int)T.size()) cout << "-1" << endl;
	else cout << maxn << endl;
	return 0;
}

