class UnionFind {
public:
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) std::swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
private:
    std::vector<int> data;
};

// --------- KMP法 ---------
// 計算量: O(n+m)
std::vector<int> kmp(const std::string& s, const std::string& t) {
    std::vector<int> ta(t.size() + 1);

    {
        ta[0] = -1;
        int j = -1;
        for (int i = 0; i < (int)t.size(); ++i) {
            while (j >= 0 && t[i] != t[j])
                j = ta[j];
            ta[i + 1] = ++j;
        }
    }

    std::vector<int> ret;
    int m = 0, i = 0, n = (int)s.size();
    while (m + i < n) {
        if (t[i] == s[m + i]) {
            if (++i == (int)t.size()) {
                ret.push_back(m);
                m = m + i - ta[i];
                i = ta[i];
            }
        }
        else {
            m = m + i - ta[i];
            if (i > 0)
                i = ta[i];
        }
    }

    return ret;
}


