    if (ss <= ts) {
        t += t;
        ts *= 2;

        bool same = true;
        for (int i = 0; i < ts; ++i) {
            if (s[i % ss] != t[i]) {
                same = false;
                break;
            }
        }

        if (same)
            std::cout << -1 << std::endl;
        else
            std::cout << 0 << std::endl;
    }
    else {
        s += s;
        ss *= 2;

        int maxL = 0;
        int nowL = 0;
        int pos = 0;
        for (int i = 0; i < ss; ++i) {
            pos %= ts;
            if (s[i] == t[pos++])
                ++nowL;
            else {
                maxL = std::max(maxL, nowL);
                nowL = 0;
                pos = 0;
            }
        }
        maxL = std::max(maxL, nowL);

        if (maxL >= ss)
            std::cout << -1 << std::endl;
        else
            std::cout << maxL / ts << std::endl;
    }

    return 0;
}

