vector<int> suffix_array(string const & s) {
	int n = SI(s);
	vector<int> r(n + 1);
	inc(i, n + 1) { r[i] = (i < n ? s[i] : 0); }

	vector<pair<pair<int, int>, int>> v(n + 1);
	for(int k = 0; k < 1 || (1 << k) < n; k++) {
		inc(i, n + 1) {
			int j = min(i + (1 << k), n);
			v[i] = { { r[i], r[j] }, i };
		}
		sort(ALL(v));

		int c = 0;
		inc(i, n + 1) {
			if(i > 0 && v[i].FI != v[i - 1].FI) { c++; }
			r[v[i].SE] = c;
		}
	}

	inc(i, n + 1) { r[i] = v[i].SE; }
	return r;
}

vector<int> lcp_array(string const & s, vector<int> const & sa) {
	int n = SI(s);
	vector<int> r(n + 1);
	inc(i, n + 1) { r[sa[i]] = i; }

	vector<int> l(n + 1);
	int c = 0;
	inc(i, n) {
		if(c > 0) { c--; }
		int j = sa[r[i] - 1];
		while(max(i, j) + c < n && s[i + c] == s[j + c]) { c++; }
		l[r[i] - 1] = c;
	}
	return l;
}

