// s の substr かつ t の prefix である最長の文字列の長さを返す
int f(string const & s, string const & t) {
	auto sa = suffix_array(s);
	auto lpc = lcp_array(s, sa);

	int n = SI(s), m = SI(t), c = 0;
	inc(i, n + 1) {
		while(sa[i] + c < n && c < m && s[sa[i] + c] == t[c]) { c++; }
		if(lpc[i] < c) { break; }
	}

	return c;
}

