ll dfs(ll v) {
  if (state[v] == 1) { return -1; } // cycle found
  if (state[v] == 2) { return dp[v]; } // already visited
  if (to[v] < 0) { // last
    state[v] = 2;
    return dp[v] = 0;
  }

  state[v] = 1;
  ll ret;
  ll nex = dfs(to[v]);
  if (nex < 0) { // cycle
    ret = -1;
  } else {
    ret = nex+1;
  }
  state[v] = 2;
  return dp[v] = ret;
}

