vector<int> build_next(const string &pat) {
  vector<int> next(pat.size() + 1);
  int i = 0, j = -1;
  next[i] = j;
  while (i < pat.size()) {
	while (j >= 0 and pat[j] != pat[i]) {
	  j = next[j];
	}
	i += 1;
	j += 1;
	next[i] = j;
  }
  return next;
}

int kmp_search(const string &txt, const string &pat) {
	vector<int> next = build_next(pat);
	int i = 0, j = 0;
	while (i < txt.size() and j < pat.size()) {
		while (j >= 0 and txt[i] != pat[j]) {
			j = next[j];
		}
		i += 1;
		j += 1;
	}
	if (j == pat.size()) {
		return i - j;
	} else {
		return -1;
	}
}
