    vector <int> pref(x.size() + 1, -1);
    for(int i = 0, j = -1; i < x.size(); i++) {
        while(j >= 0 && x[j] != x[i]) j = pref[j];
        pref[i + 1] = ++j;
    }
    return vector<int>(pref.begin() + t.size() + 2, pref.end());
