#define MAXN 2002000
void Zalgorithm(string S, int *A) {
  int N = S.size();
  A[0] = N;
  int i = 1, j = 0;
  while (i < N) {
    while (i + j < N && S[j] == S[i + j]) ++j;
    A[i] = j;
    if (j == 0) {
      ++i;
      continue;
    }
    int k = 1;
    while (i + k < N && k + A[k] < j) A[i + k] = A[k], ++k;
    i += k;
    j -= k;
  }
}
