#define MOD 1000000007

int minv(int n) {
	int res = 1;
	for (int i = MOD - 2; i; i >>= 1) {
		if (i & 1) res = (int64_t) res * n % MOD;
		n = (int64_t) n * n % MOD;
	}
	return res;
}
struct RollingHash {
	int base;
	std::vector<int> accumulated, beki, inv;
	RollingHash () = default;
	RollingHash (int base, const std::string &s) : base(base) {
		int n = s.size();
		accumulated.resize(n + 1);
		beki.resize(n + 1, 1);
		inv.resize(n + 1);
		for (int i = 0; i < n; i++) {
			beki[i + 1] = (int64_t) beki[i] * base % MOD;
			accumulated[i + 1] = (accumulated[i] + (int64_t) s[i] * beki[i]) % MOD;
		}
		inv[n] = minv(beki[n]);
		for (int i = n; i--; ) inv[i] = (int64_t) inv[i + 1] * base % MOD;
	}
	int substr(int l, int r) {
		int res = accumulated[r] - accumulated[l];
		if (res < 0) res += MOD;
		return (int64_t) res * inv[l] % MOD;
	}
};

