int main() {
	std::string s, t;
	std::cin >> s >> t;
	for (auto &i : s) i -= 'a';
	for (auto &i : t) i -= 'a';
	int n;
	{
		std::string s_bak = s;
		while (s.size() < t.size()) s += s_bak;
		n = s.size();
		s += s;
	}
	constexpr int bases[] = {998244353, 874899298, 372312948};
	RollingHash shash[3], thash[3];
	for (int i = 0; i < 3; i++) {
		shash[i] = RollingHash(bases[i], s);
		thash[i] = RollingHash(bases[i], t);
	}
	int m = t.size();
	bool ok[n];
	for (int i = 0; i < n; i++) {
		bool match = true;
		for (int j = 0; j < 3; j++) if (shash[j].substr(i, i + m) != thash[j].substr(0, m)) match = false;
		ok[i] = match;
	}
	int res = 0;
	std::vector<bool> used(n);
	for (int i = 0; i < n; i++) {
		if (used[i]) continue;
		std::vector<bool> cur;
		for (int j = i; !used[j]; j = (j + m) % n) used[j] = true, cur.push_back(ok[j]);
		if (std::accumulate(cur.begin(), cur.end(), 0) == (int) cur.size()) res = INF;
		else {
			std::vector<int> compressed{0};
			for (auto j : cur) {
				if (j) compressed.back()++;
				else if (compressed.back()) compressed.push_back(0);
			}
			if (!compressed.back()) compressed.pop_back();
			if (cur.front() && cur.back()) compressed.front() += compressed.back(), compressed.pop_back();
			for (auto i : compressed) res = std::max(res, i);
		}
	}
	printf("%d\n", res == INF ? -1 : res);
	return 0;
}

