		void getfail(const string &s)
		{
			fail[0] = fail[1] = 0;
			for (int i = 1; i < s.size(); i++)
			{
				int tmp = fail[i];
				while (tmp && s[i] != s[tmp])
					tmp = fail[tmp];
				fail[i + 1] = (s[i] == s[tmp] ? tmp + 1 : 0);
			}
		}
		void query(const string &s, const string &t)
		{
			getfail(t);
			int now = 0;
			for (int i = 0; i < s.size(); i++)
			{
				while (now && (now == t.size() || s[i] != t[now]) )
					now = fail[now];
				if (s[i] == t[now])
					++now;
				if (now == t.size())
					vis[i] = true;
			}
		}
	}
	bool check()
	{
		for (int i = 0; i < s.size(); i++)
			if (s[i] != s[0])
				return false;
		for (int i = 0; i < t.size(); i++)
			if (t[i] != t[0])
				return false;
		return s[0] == t[0];
	}
