		if (P[j] == T[i]) j++;
		if (j == m) {
            int pos = i-m+1;
            if (pos - pre == m) {
                cur++;
                pre = pos;
            } else {
                mx = max(mx, cur);
                cur = 1;
                pre = pos;
            }
		}
	}
	mx = max(mx, cur);
	return mx;
}


