// ----- UnionFind -----

class UnionFind
{
  int N;
  vector<int> par;

public:
  UnionFind() : N{0} {}
  UnionFind(int N) : N{N}, par(N, -1) {}

  bool is_same(int x, int y)
  {
    return root(x) == root(y);
  }

  bool merge(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y)
    {
      return false;
    }
    if (par[x] > par[y])
    {
      swap(x, y);
    }
    par[x] += par[y];
    par[y] = x;
    return true;
  }

  int size(int x)
  {
    return -par[root(x)];
  }

  int count_parts()
  {
    int ans{0};
    for (auto i = 0; i < N; i++)
    {
      if (par[i] < 0)
      {
        ++ans;
      }
    }
    return ans;
  }

private:
  int root(int x)
  {
    if (par[x] < 0)
    {
      return x;
    }
    return par[x] = root(par[x]);
  }
};

// ----- MP algorithm -----

template <typename Type = string>
class MP
{
  int N;
  Type S;
  vector<int> A;

public:
  MP() {}
  MP(Type const &S) : N(S.size()), S{S}, A(N + 1, -1)
  {
    int j{-1};
    for (auto i = 0; i < N; i++)
    {
      while (j != -1 && S[j] != S[i])
      {
        j = A[j];
      }
      ++j;
      A[i + 1] = j;
    }
  }

  int operator[](int i) { return A[i]; }

  vector<int> find_all(Type const &T)
  {
    vector<int> res;
    int j{0};
    for (auto i = size_t{0}; i < T.size(); i++)
    {
      while (j != -1 && S[j] != T[i])
      {
        j = A[j];
      }
      ++j;
      if (j == N)
      {
        res.push_back(i - j + 1);
        j = A[j];
      }
    }
    return res;
  }
};

// ----- main() -----

int main()
{
  string S, T;
  cin >> S >> T;
  int M{static_cast<int>(S.size())};
  int N{static_cast<int>(T.size())};
  int times{(3 * N + M - 1) / M};
  stringstream SS;
  for (auto t = 0; t < times; ++t)
  {
    SS << S;
  }
  S = SS.str();
  MP<string> mp(T);
  auto V{mp.find_all(S)};
  set<int> X(V.begin(), V.end());
  UnionFind uf{M};
  for (auto i = 0; i < M; ++i)
  {
    auto j{(i + N) % M};
    if (X.find(i) != X.end() && X.find(j) != X.end())
    {
      if (uf.is_same(i, j))
      {
        No();
      }
      uf.merge(i, j);
    }
  }
  int ans{0};
  for (auto i = 0; i < M; ++i)
  {
    if (X.find(i) != X.end())
    {
      ch_max(ans, uf.size(i));
    }
  }
  cout << ans << endl;
}

