// kmp をやるための前計算
vector<int> makeTable(const string& s) {
    int n = s.size();
    vector<int> ret(n+1);
    ret[0] = -1;
    int j = -1;
    for (int i = 0; i < n; i++) {
        while (j >= 0 && s[i] != s[j]) j = ret[j];
        ret[i+1] = ++j;
    }
    return ret;
}

// str の中に word とマッチする場所のリストを返す
// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す
vector<int> kmp(const string& str, const string& word) {
    vector<int> table = makeTable(word), ret;
    int m = 0, i = 0, n = str.size();
    while (m+i < n) {
        if (word[i] == str[m+i]) {
            if (++i == (int)(word.size())) {
                ret.push_back(m);
                m = m+i-table[i];
                i = table[i];
            }
        } else {
            m = m+i-table[i];
            if (i > 0) i = table[i];
        }
    }
    return ret;
}


string my(string s, int n)
{
	if (n==1)
	{
		return s;
	}
	string t=my(s,n/2);
	if (n%2==0)
	{
		return t+t;
	}
	else
	{
		return t+t+s; 
	}
}

int main(int argc, char const *argv[])
{
	string s,t;
	cin>>s>>t;
	int n=s.size(),m=t.size();
	while (s.size()<=2*t.size())
	{
		s+=s;
	}
	vector<int> match=kmp(s,t);
	int memo[n]={},dist[n]={},ans=0;
	for (int i = 0; i < n; ++i)
	{
		if (memo[i]==1)
		{
			continue;
		}
		int now=i,nans=0;
		memo[i]=1;
		while (binary_search(match.begin(), match.end(), now))
		{
			now+=m;
			now%=n;
			++nans;
			ans=max(ans,nans);
			if (i==now)
			{
				cout<<"-1\n";
				return 0;
			}
			if (memo[now]==1)
			{
				nans+=dist[now];
				ans=max(ans,nans);
				dist[i]=nans;
				break;
			}
			memo[now]=1;
		}
		dist[i]=nans;
	}
	cout<<ans<<endl;
	return 0;
}

