vector <int> kmp(string s, string t) { // t in s lengths
    string x = t + "#" + s;
    vector <int> pref(x.size() + 1, -1);
    for(int i = 0, j = -1; i < x.size(); i++) {
        while(j >= 0 && x[j] != x[i]) j = pref[j];
        pref[i + 1] = ++j;
    }
    return vector<int>(pref.begin() + t.size() + 2, pref.end());
}

int n, m;
string s, t;

int nxt(int &idx) {
    return idx + m - n >= m - 1 ? idx + m - n : idx + m;
}
int prv(int &idx) {
    return idx - m >= m - 1 ? idx - m : idx - m + n;
}

bool thereIsCycle(vector <int> tInS) {
    for(int i = m - 1; i <= 2 * m; i++) {
        bool cycle = true;
        int idx = i;
        do {
            cycle &= (tInS[idx] == m);
            idx = nxt(idx);
        } while(idx != i && cycle);
        if(cycle) return true;
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin >> s >> t;

    while(s.size() < t.size())
        s = s + s;

    n = s.size();
    m = t.size();

    vector <int> tInS = kmp(s + s, t);

    if(thereIsCycle(tInS)) {
        cout << -1 << endl;
        return 0;
    }

    int ans = 0;

    for(int i = m - 1; i < m - 1 + n; i++) {
        if(tInS[nxt(i)] == m)
            continue;

        int idx = prv(i), res = 0;
        while(tInS[idx] == m) {
            res++;
            idx = prv(idx);
        }
        ans = max(ans, res);
    }
    cout << ans << endl;
}

