struct KMP {
	vector<ll> a;//0-index!
	vector<ll> b;

	vector<ll> pma;

	vector<ll> match;

	KMP(vector<ll>a0, vector<ll>b0) {
		a = a0;
		b = b0;

		ll N = a.size();
		ll M = b.size();

		pma.assign(M, 0);

		ll p = 0;
		repn(i, M - 1) {
			pma[i] = p;
			if (b[i] == b[p]) { p++; }
			else { p = 0; }
		}

		ll sa = 0;
		ll sb = 0;

		while (sa < N) {
			if (a[sa] == b[sb]) {
				if (sb == M - 1) { match.push_back(sa - sb); sb = pma[M - 1]; }
				else { sb++; sa++; }
			}

			else {
				if (sb == 0) { sa++; }
				sb = pma[sb];
			}
		}
	}


};


