	KMP a_b(a, b);

	vector<bool> match(N, 0);
	for (ll i : a_b.match) {
		if (i < N) { match[i] = 1; }
	}

	queue<ll> q;
	vector<ll> top(N, -1);

	rep(i, N) {
		ll j = (i - M) % N;
		if (j < 0) { j += N; }
