struct RollingHash {
    int n;
    string s;
    const ll mod1 = 1000000007LL, mod2 = 1000000009LL, mod3 = 999999937LL,
             base1 = 1007LL, base2 = 1009LL, base3 = 9973LL;
    vector<ll> hash1, hash2, hash3, pow1, pow2, pow3;
    RollingHash(const string &str) {
        s = str;
        n = str.length();
        hash1.resize(n + 10);
        hash2.resize(n + 10);
        hash3.resize(n + 10);
        pow1.resize(n + 10, 1);
        pow2.resize(n + 10, 1);
        pow3.resize(n + 10, 1);
        for (int i = 0; i < n; i++) {
            hash1[i + 1] = (hash1[i] + s[i]) * base1 % mod1;
            hash2[i + 1] = (hash2[i] + s[i]) * base2 % mod2;
            hash3[i + 1] = (hash3[i] + s[i]) * base3 % mod3;
            pow1[i + 1] = pow1[i] * base1 % mod1;
            pow2[i + 1] = pow2[i] * base2 % mod2;
            pow3[i + 1] = pow3[i] * base3 % mod3;
        }
    }
    pair<ll, pair<ll, ll>> get(int l, int r) {
        ll t1 = (hash1[r] - hash1[l] * pow1[r - l] % mod1 + mod1) % mod1;
        ll t2 = (hash2[r] - hash2[l] * pow2[r - l] % mod2 + mod2) % mod2;
        ll t3 = (hash3[r] - hash3[l] * pow3[r - l] % mod3 + mod3) % mod3;
        return make_pair(t1, make_pair(t2, t3));
    }
};
