Vec< int > makeKMPfail(const string& S) {
	int n = S.size();	
	Vec< int > fail(n+1, 0);
	int j = fail[0] = -1;
	for_(i,1,n+1) {
		while (j >= 0 && S[j] != S[i - 1]) j = fail[j];
		fail[i] = ++j;
	}
	return fail;
}

int main() {
	string s, t;
	cin >> s >> t;
	int n = s.size(), m = t.size();

	///
	Vec< int > s_fail = makeKMPfail(s);
	Vec< int > t_fail = makeKMPfail(t);
	int sp = n - s_fail[n], tp = m - t_fail[m];
	if (n % sp == 0 && m % tp == 0) {
		if (sp == tp && s.substr(0, sp) == t.substr(0, tp)) {
			puts("-1");
			return 0;
		}
	}
