	int N = x.size();
//	cerr << x << endl;
//	cerr << t << endl;

	Vec< bool > match(N + 1, 0);
	for (int i=0, k=0; i < N; ++i) {
		while (k >= 0 && t[k] != x[i]) k = t_fail[k];
		if (++k >= m) {
			match[i] = true;
			k = t_fail[k];
		}
	}

	int ans = 0;
	for_(i,1,N+1) {
		if (match[i]) {
			int j = i, cnt = 0;
