vector<int> res;
void KMP(const string &s, const string &k){
    res.clear();
    if (k.empty())
        return ;
    vector<int> tmp(k.size(), 0);
    for (int i = 1, j = 0; i < k.size(); ++i){
        while (j && k[j] != k[i])
            j = tmp[j - 1];
        if (k[j] == k[i])
            ++j;
        tmp[i] = j;
    }
    for (int i = 0, j = 0; i < s.size(); ++i){
        while (j && k[j] != s[i])
            j = tmp[j - 1];
        if (k[j] == s[i])
            ++j;
        if (j == k.size())
            res.push_back(i - j + 1);
    }
}

int n, m;

int f(){
    n = res.size();
    bool ok = false;
    int cnt = 1, mx = 0;
    for(int i = 1 ; i < n ; ++i){
        if(res[i] - res[i - 1] == m)
            ++cnt, ok = true;
        else mx = max(mx, cnt), cnt = 1;
    }
    if(ok == false)return -1;
    return max(mx, cnt);
}

