bool cycle;
int w;

void go(int u, int p){
  vis[u] = 1;
  w++;
  for(int v : g[u]){
    if(v == p) continue;
    if(vis[v]) cycle = true;
    else if(vis[v] == 0) go(v, u);
  }
}

