template <class Container>
std::vector<int> zalgo(const Container& dat) {
    int n = dat.size();

    std::vector<int> ret(n);
    ret[0] = n;

    int i = 1, len = 0;
    while (i < n) {
        while (i + len < n && dat[len] == dat[i + len]) {
            ++len;
        }
        ret[i] = len;

        if (len == 0) {
            ++i;
            continue;
        }

        int nlen = 1;
        while (i + nlen < n && nlen + ret[nlen] < len) {
            ret[i + nlen] = ret[nlen];
            ++nlen;
        }

        i += nlen;
        len -= nlen;
    }

    return ret;
}

constexpr int INF = 1 << 30;

void solve() {
    std::string s, t;
    std::cin >> s >> t;
    while (s.length() < t.length()) s += s;

    auto v = zalgo(t + "$" + s + s);
    v.erase(v.begin(), v.begin() + t.length() + 1);
    v.erase(v.begin() + s.length(), v.end());

    int n = t.length(),
        m = v.size();
    for (auto& x : v) x = (x == n);

    std::vector<int> dist(m, -1);
    std::function<int(int)> dfs = [&](int i) {
        if (dist[i] != -1) return dist[i];
        if (!v[i]) return dist[i] = 0;
        dist[i] = INF;
        return dist[i] = dfs((i + n) % m) + 1;
    };

    int ans = 0;
    for (int i = 0; i < m; ++i) ans = std::max(ans, dfs(i));
    std::cout << (ans >= INF ? -1 : ans) << std::endl;
}

int main() {
    std::cin.tie(nullptr);
    std::cout.tie(nullptr);
    std::ios::sync_with_stdio(false);

    solve();

    return 0;
}

