void KMPMatch(string src, string pat){
    int ini[pat.size()], i=1, j=0;
    ini[0] = 0;
    while(i<pat.size()){
      if(pat[i] == pat[j]) j++, ini[i] = j, i++;
      else if(j == 0) ini[i] = 0, i++;
      else j = ini[j - 1];
    }
    i = j = 0;
    while(j<pat.size()&&i<src.size()/2+pat.size()-2){
      if(src[i] == pat[j]) i++, j++;
      else if(j == 0) i++;
      else j = ini[j - 1];
      if(j==pat.size()-1) {
        add_edge(abs(i-j), i%(src.size()/2));
        //std::cout << abs(i-j) << " " <<  i%(src.size()/2) << '\n';
      }
    }
}
