	REP(i, S.size()) if (indeg[i] == 0) que.push(i);

	int ans = 0;
	while (!que.empty()) {
		int u = que.front();
		que.pop();
		chmax(ans, dp[u]);

		for (int v : g[u]) {
			chmax(dp[v], dp[u] + 1);
			if (--indeg[v] == 0) que.push(v);
		}
	}

	REP(i, S.size()) if (indeg[i]) ans = -1;
	cout << ans << endl;
	return 0;
}

