std::vector<int> kmpMake(const std::string& W) {
	std::vector<int> T(W.size() + 1);
	int i = 2;		//T の中で現在計算している位置
	int j = 0;		//現在見ているサブ文字列の次の文字のインデックス。0から始まる
	//先頭ふたつの値は固定。ただしアルゴリズムの実装によっては具体的値は異なる
	T[0] = -1;
	if (2 <= W.size()) {
		T[1] = 0;
	}
	while (i < W.size()) {
		if (W[i - 1] == W[j]) {
			T[i] = j + 1;
			i = i + 1;
			j = j + 1;
		}
		else if (j > 0) {
			j = T[j];
		}
		else {
			T[i] = 0;
			i = i + 1;
		}
	}
	return T;
}

std::vector<int>reses;
