int kmp_search(const std::string& S, const std::string& W, const std::vector<int>& T, int start = 0) {
	//S 内の現在照合中の開始位置
	int m = start;
	//W 内の現在位置
	int i = 0;
	//
	while (m + i < S.size()) {
		if (W[i] == S[m + i]) {
			++i;
			//if (i == W.size())return m;
			if (i == W.size()) {
				reses.push_back(m);
				m = m + i - T[i];
				if (i > 0) {
					i = T[i];
				}
			}
		}
		else {
			m = m + i - T[i];
			if (i > 0) {
				i = T[i];
			}
		}
	}
	//W が S 内に見つからなかった場合
	return -1;
}







