vector<int> z(const string &s)
{
    int n = (int) s.size(), L = 0, R = 0;
    vector<int> zs(n, 0);

    for (int i = 1; i < n; i++)
    {
        if (i <= R)
            zs[i] = min(zs[i - L], R - i + 1);

        while (zs[i] + i < n && s[zs[i]] == s[i + zs[i]])
            zs[i]++;

        if (R < i + zs[i] - 1)
            L = i, R = i + zs[i] - 1;
    }

    return zs;
}

int dfs(int u, int v, int k, int N, vector<int>& dist, const vector<int>& zs)
{
    if (dist[u] > -1)
        return dist[u];

    if (u == v)
        return oo;

    if (zs[k + 1 + u] != k)
        return 0;

    auto w = (u + k) % N;
    dist[w] = dfs(w, v, k, N, dist, zs);

    return 1 + dist[w];
}

int max_seq(const vector<int>& zs, int k, int N)
{
#ifdef DEBUG
    for (int i = 0; i < N + k + 1; ++i)
        cout << setw(3) << i;
    cout << endl;
    for (int i = 0; i < N + k + 1; ++i)
        cout << setw(3) << zs[i];
    cout << endl;
#endif

    vector<int> dist(N, -1);

    for (int i = 0; i < N; ++i)
    {
        if (dist[i] > -1)
            continue;

        if (zs[k + 1 + i] != k)
            dist[i] = 0;
        else
            dist[i] = 1 + dfs((i + k) % N, i, k, N, dist, zs);
    }

#ifdef DEBUG
    for (int i = 0; i < N; ++i)
        cout << "dist[" << i << "] = " << (dist[i] == oo ? -1 : dist[i]) << endl;
#endif

    auto ans = *max_element(dist.begin(), dist.end());

    return ans >= oo ? -1 : ans;
}

