vector<bool> check_eq(string s, string t) {
  int s_size = s.size();
  int t_size = t.size();
  vector<bool> result(s_size - t_size + 1);
  uint64_t b = 100000007;
  uint64_t bn = 1;
  uint64_t s_hash = 0;
  uint64_t t_hash = 0;

  for (int i = 0; i < t_size; i++) {
    bn *= b;
  }

  int i = 0;
  for(; i < t_size; i++) {
    t_hash = t_hash * b + t[i];
    s_hash = s_hash * b + s[i];
  }

  for(;;i++) {
    result[i - t_size] = s_hash == t_hash;

    if (i >= s_size) {
      break;
    }

    s_hash = s_hash * b + s[i] - s[i - t_size] * bn;
  }

  return result;
}

