    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

const int MAXkai = 200010;
ll kai_memo[MAXkai];
ll kai(ll N){
  if(kai_memo[N] != 0) return kai_memo[N];
  if(N <= 1) return 1;
  return kai_memo[N] = N * kai(N-1) % MOD;
}

ll disit(ll s, ll base = 10){
  ll res = 0;
  while(s){
    res++;
    s /= base;
  }
  return res;
}



struct RollingHash{
  string S;
  ll sl;//Sのサイズ
  vector<ll> hashed, power;
  ll base = 998244353;
  ll MOD = 1000000007;
  void getS(string S){
    S = S;
    sl = S.size();
    hashed.resize(sl + 1, 0);
    power.resize(sl + 1);
    power[0] = 1;
    rep(i, sl){
      power[i+1] = (power[i] * base) % MOD;
      hashed[i+1] = (hashed[i] * base + S[i]) % MOD;
    }
  }

  ll getHash(ll l, ll r){//[l, r)
    ll res = ((hashed[r] - hashed[l] * power[r-l]) % MOD + MOD) % MOD;
    return res;
  }

  //使ったことない
  ll connect(ll hash1, ll hash2, ll hash2size){
    ll res = (hash1 * power[hash2size] + hash2) % MOD;
    return res;
  }
};


//Union Find
const ll MAX_V = 1000010;

ll par[MAX_V];//
ll Rank[MAX_V];
ll child[MAX_V];

void init_UF(){
  for(ll i = 0; i < MAX_V; i++){
    par[i] = i;
    Rank[i] = 1;
    child[i] = 1;
  }
}

ll find(ll x){
  if(par[x] == x) return x;
  else{
    return par[x] = find(par[x]);
  }
}

bool same(ll x, ll y){
  return find(x) == find(y);
}

void unite(ll x, ll y){
  ll rx = find(x), ry = find(y);
  if(rx != ry){
    if(Rank[rx] >= Rank[ry]){
      par[ry] = rx;
      if(Rank[rx] == Rank[ry]) Rank[rx]++;
      child[rx] += child[ry];
    }else{
      par[rx] = ry;
      child[ry] += child[rx];
    }
  }
}



string tmpS, T;

void solve(){
  cin >> tmpS >> T;
  string S = tmpS;
  while(S.size() < T.size() * 2){
    S += tmpS;
  }
  ll sl = S.size(), tl = T.size();
  S += S;
  RollingHash RS, TS;
  RS.getS(S);
  TS.getS(T);
  vector<bool> start(sl, 0);
  rep(i, sl){
    if(RS.getHash(i, i+tl) == TS.getHash(0, tl)){
      start[i] = 1;
    }
  }
  init_UF();
  bool inf = 0;
  rep(i, sl){
    if(start[i] && start[(i+tl)%sl]){
      if(same(i, (i+tl)%sl)) inf = 1;
      unite(i, (i+tl)%sl);
    }
  }
  if(inf){
    cout << -1 << endl;
    return;
  }
  ll ans = 0;
  rep(i, sl){
    if(start[i]) ans = max(ans, child[find(i)]);
  }
  cout << ans << endl;
}



int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

