			}
		} 
	}

	/*初始化失配指针*/
	void getFail(string& b){
		f[0]=f[1]=0;
		for(int i=1;i<b.size();i++){
			int j=f[i]; //取出上一次的失配指针
			while(j!=0 && b[i]!=b[j]){
				j=f[j]; //失配 
			} 

			f[i+1]=(b[i]==b[j]?j+1:0);
		}
	}

	/*[DEBUG]打印失配指针*/
	void __printFail(int n){
		for(int i=0;i<=n;i++){
			cout<<f[i]<<" ";
		}
		cout<<endl;
	}
};

