struct Num {
	int x = 0, y = 0;
	Num(int a = 0) {
		x = a, y = a;
	}
	Num operator + (const Num & a) const {
		Num res;
		res.x = x + a.x;
		if (res.x >= MOD.F) {
			res.x -= MOD.F;
		}
		res.y = y + a.y;
		if (res.y >= MOD.S) {
			res.y -= MOD.S;
		}
		return res;
	}
	Num operator - (const Num & a) const {
		Num res;
		res.x = x - a.x;
		if (res.x < 0) {
			res.x += MOD.F;
		}
		res.y = y - a.y;
		if (res.y < 0) {
			res.y += MOD.S;
		}
		return res;
	}
	Num operator * (const Num & a) const {
		Num res;
		res.x = (ll)x * a.x % MOD.F;
		res.y = (ll)y * a.y % MOD.S;
		return res;
	}
	bool operator == (const Num & a) const {
		return x == a.x && y == a.y;
	}
};

