ll ky = 127LL;

void solve()
{
	string s, t;  cin >> s >> t;
	ll N = Size(s);
	ll M = Size(t);

	string S = s;
	ll len = N;
	while (len<N+M){
		S += s;
		len+=N;
	}

	vll nx(N,-1), pv(N,-1);

	mll  htA=0; mllB htB=0;
	rep(i, 0, M-1){
		htA *= ky;   htB *= ky;
		htA += t[i]; htB += t[i];
	}
	mll  hsA = 0; mllB hsB = 0;
	rep(i, 0, M-1){
		hsA *= ky;   hsB *= ky;
		hsA += S[i]; hsB += S[i];
	}

	mll  kyMA = POW(mll (ky), M);
	mllB kyMB = POW(mllB(ky), M);
	rep(i, 0, N-1){
		if (i!=0){
			hsA *= ky;            hsB *= ky;
			hsA += S[i+M-1];      hsB += S[i+M-1];
			hsA -= kyMA * S[i-1]; hsB -= kyMB * S[i-1];
		}
		if (hsA==htA && hsB==htB){//一致
			nx[i] = (i+M)%N;
			pv[(i+M)%N] = i;
		}
	}

	ll ans = 0;
	rep(i, 0, N-1){
		if (pv[i]!=-1) continue;
		if (nx[i]==-1) continue;

		ll len = 0;
		ll cr = i;
		while (nx[cr] != -1){
			ll nxt = nx[cr];
			nx[cr] = -1;
			pv[nxt] = -1;
			cr = nxt;
			len++;
		}
		chmax(ans, len);
	}
	rep(i, 0, N-1){
		if (nx[i]!=-1) bye(-1);
	}
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

