		if (Z[T.size()+i] >= (int)T.size()) {
		    nxt[0][i] = (i + T.size()) % S.size();
		}
    }

    REP (t, 60) REP (i, S.size()) {
		int a = nxt[t][i];
		if (a >= 0) {
		    nxt[t+1][i] = nxt[t][nxt[t][i]];
		}
    }

    REP (i, S.size()) if (nxt[60][i] >= 0) {
		puts("-1");
