vector<int> z_algorithm(const vector<int>& S){
    int N = S.size(), c = 0;
    vector<int> ret(N, 0);
    for(int i=1; i<N; i++){
        if(i + ret[i-c] < c + ret[c]){
            ret[i] = ret[i-c];
        }else{
            int j = max(0, c + ret[c] - i);
            while(i+j < N && S[j] == S[i+j]) j++;
            ret[i] = j;
            c = i;
        }
    }
    ret[0] = N;
    return ret;
}

vector<int> z_algorithm(const string& S){
    int N = S.size();
    vector<int> s(N);
    for(int i=0; i<N; i++) s[i] = S[i];
    return z_algorithm(s);
}

