#include <iostream>
#include <unordered_map>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

vector<bool> check_eq(string s, string t) {
  int s_size = s.size();
  int t_size = t.size();
  vector<bool> result(s_size - t_size + 1);

  // まずtに対して部分マッチテーブル作成
  int a[t_size+1];
  a[0] = -1;
  for (int i = 0, j = -1; i < t_size; i++) {
    while (j >= 0 && t[i] != t[j]) {
      j = a[j];
    }

    j++;
    if (t[i+1] == t[j]) {
      a[i+1] = a[j]; // 同じ文字ならさらに前に。これがKMPのKとのこと。http://potetisensei.hatenablog.com/entry/2017/07/10/174908
    } else {
      a[i+1] = j;
    }
  }

  /*
  for (const auto& aa : a) {
    cout << aa << endl;
  }
  */

  // 照合
  int j = 0, i = 0;
  while (j < s_size) {
    // m,iで実装する方法わからないのでコピペ
    // http://www-igm.univ-mlv.fr/~lecroq/string/node8.html
    // cout << "i " << i << " j " << j <<endl;
    while (i > -1 && t[i] != s[j]) {
      i = a[i]; // 現在のs[j]と同じt[i]がないか、さかのぼって探す。ひとつ前は違う文字になっているので、ちょっと効率的？
      // cout << "i " << i << " j " << j <<endl;
    }

    i++;
    j++;

    if (i >= t_size) {
      result[j-i] = true;
      i = a[i];
    }
  }

  return result;
}

int main() {
  string s,t,s_origin;
  cin >> s >> t;
  s_origin = s;
  int s_origin_size = s_origin.size();
  int t_size = t.size();

  while(s.size() < t_size + s_origin_size) {
    s += s_origin;
  }

  vector<bool> eqs = check_eq(s,t);

  int max_length = 0;
  vector<int> length(s_origin_size, -1);

  for (int i = 0; i < s_origin_size; i++) {
    if (length[i] != -1) {
      continue;
    }

    if (!eqs[i]) {
      length[i] = 0;
      continue;
    }

    int current = i;
    int diff = 0;
    queue<int> q;
    while(eqs[current]) {
      if (!q.empty() && i == current) {
        // 無限に一致する
        max_length = -1;
        goto finish;
      }

      if (length[current] != -1) {
        diff = length[current]; // すでに到達済みの場合、計算済みの長さを加えて終了する
        break;
      }
      length[current] = 0; // 一旦到達マーク設定
      q.push(current);
      current = (current + t_size) % s_origin_size;
    }

    max_length = max(max_length, diff + (int)q.size());

    while(!q.empty()) {
      int len = q.size();
      int current = q.front();
      q.pop();
      length[current] = len + diff; // 正確な長さで上書き
    }
  }

finish:
  cout << max_length << endl;

  return 0;
}

