using Graph = vector<vector<int>>;

bool visit(int v, vector<int> &order, vector<int> &color, const Graph &g) {
    color[v] = 1;
    for (auto next : g[v]) {
        if (color[next] == 2) continue;
        if (color[next] == 1) return false;
        if (!visit(next, order, color, g)) return false;
    }
    order.push_back(v); color[v] = 2;
    return true;
}
bool topologicalSort(vector<int> &order, const Graph &g) {
    int n = g.size();
    vector<int> color(n, 0);
    rep(u, n) {
        if (!color[u] && !visit(u, order, color, g)) return false;
    }
    reverse(all(order));
    return true;
}


vector< int > z_algorithm(const string &s) {
    vector< int > prefix(s.size());
    for (int i = 1, j = 0; i < s.size(); i++) {
        if (i + prefix[i - j] < j + prefix[j]) {
            prefix[i] = prefix[i - j];
        } else {
            int k = max(0, j + prefix[j] - i);
            while (i + k < s.size() && s[k] == s[i + k]) ++k;
            prefix[i] = k;
            j = i;
        }
    }
    prefix[0] = (int) s.size();
    return prefix;
}




