bool isstart[500005];
bool used[500005];
ll ans[500005]={0};
ll pow(ll x,ll y,ll mod){
  if(y==0) return 1;
  ll res=pow(x,y/2,mod);
  res*=res;
  res%=mod;
  if(y%2==1) res*=x;
  return res%mod;
}
ll solve(vector<bool> vec){
  ll n=vec.size();
  for(int i=0;i<n;i++) vec.push_back(vec[i]);
  ll res=0,cnt=0;
  for(int i=0;i<n*2;i++){
    if(vec[i]) cnt++;
    else{
      res=max(res,cnt);
      cnt=0;
    }
  }
  return max(res,cnt);
}
int main(){
  string s,t;
  cin>>s>>t;
  ll sl=s.length();
  string ns=s;
  ll thash1=0,thash2=0;
  for(int i=0;i<t.length();i++){
    thash1+=(int)(t[i]);
    thash1*=H;
    thash1%=mod1;

    thash2+=(int)(t[i]);
    thash2*=H;
    thash2%=mod2;
  }
  while(ns.length()<=t.length()) ns+=s;
  ns+=s;
  ll shash1=0,shash2=0;
  for(int i=0;i<t.length();i++){
    shash1+=(int)(ns[i]);
    shash1*=H;
    shash1%=mod1;

    shash2+=(int)(ns[i]);
    shash2*=H;
    shash2%=mod2;
  }
  isstart[0]=(shash1==thash1&&shash2==thash2);
  ll mhash1=pow(H,t.length(),mod1),mhash2=pow(H,t.length(),mod2);
  for(int i=1;i<sl;i++){
    shash1-=(mhash1*(int)ns[i-1])%mod1;
    shash1+=mod1;
    shash1+=(int)(ns[i+t.length()-1]);
    shash1%=mod1;
    shash1*=H;
    shash1%=mod1;

    shash2-=(mhash2*(int)ns[i-1])%mod2;
    shash2+=mod2;
    shash2+=(int)(ns[i+t.length()-1]);
    shash2%=mod2;
    shash2*=H;
    shash2%=mod2;

    isstart[i]=(shash1==thash1&&shash2==thash2);
  }

  for(int i=0;i<sl;i++){
    used[i]=false;
  }
  ll ans=0;
  for(int i=0;i<sl;i++){
    if(!used[i]){
