#include<bits/stdc++.h>
using namespace std;

int b = 1'000'000'007;
int h1 = 1'000'000'009;
int h2 = 1'000'000'021;
int h3 = 1'000'000'033;

long long modpow(long long x, long long y, long long p){
    if (y == 0) return 1;
    if (y % 2) return x * modpow(x, y - 1, p) % p;
    return modpow(x, y / 2, p) * modpow(x, y / 2, p) % p;
}

void set_hash(string s, vector<vector<long long>> &hash){
    for (int i = 0; i < 3; i++) hash[i][0] = 0;
    for (int i = 0; i < s.size(); i++) hash[0][i + 1] = (hash[0][i] * b + s[i]) % h1;
    for (int i = 0; i < s.size(); i++) hash[1][i + 1] = (hash[1][i] * b + s[i]) % h2;
    for (int i = 0; i < s.size(); i++) hash[2][i + 1] = (hash[2][i] * b + s[i]) % h3;
}

bool check_equal(vector<vector<long long>> &hash_s, vector<vector<long long>> &hash_t, int &x, int &x_length){
    int cnt = 0;
    if (hash_s[0].back() == (hash_t[0][x + x_length] - hash_t[0][x] * modpow(b, x_length, h1) % h1 + h1) % h1) cnt++;
    if (hash_s[1].back() == (hash_t[1][x + x_length] - hash_t[1][x] * modpow(b, x_length, h2) % h2 + h2) % h2) cnt++;
    if (hash_s[2].back() == (hash_t[2][x + x_length] - hash_t[2][x] * modpow(b, x_length, h3) % h3 + h3) % h3) cnt++;
    if (cnt >= 2) return true;
    return false;
}

vector<int> root;
vector<int> ranks;

int find(int x){
    if (root[x] == x) return x;
    root[x] = find(root[x]);
    return root[x];
}

bool check(int x, int y){
    return find(x) == find(y);
}

bool Union(int x, int y){
    x = find(x);
    y = find(y);
    if (x == y) return false;
    if (ranks[x] >= ranks[y]) root[y] = x;
    else root[x] = y;
    if (ranks[x] == ranks[y]) ranks[x]++;
    return true;
}

int main(){
    string s, t;
    cin >> s >> t;
    string new_s = s;
    while (new_s.size() < s.size() + t.size()) new_s += s;
    vector<vector<long long>> hash_s(3, vector<long long>(new_s.size() + 1));
    vector<vector<long long>> hash_t(3, vector<long long>(t.size() + 1));
    set_hash(new_s, hash_s);
    set_hash(t, hash_t);
    vector<int> roots(s.size());
    for (int i = 0; i < s.size(); i++) roots[i] = i;
    root = roots;
    vector<int> rankz(s.size(), 0);
    ranks = rankz;
    vector<bool> ok(s.size(), false);
    bool flag = false;
    int t_size = t.size();
    for (int i = 0; i < s.size(); i++){
        if (check_equal(hash_t, hash_s, i, t_size)) ok[i] = true, flag = true;
    }
    for (int i = 0; i < s.size(); i++){
        if (ok[i] && ok[(i + t.size()) % s.size()]){
            if (!Union(i, (i + t.size()) % s.size())){
                cout << - 1 << endl;
                exit(0);
            }
        }
    }
    for (int i = 0; i < s.size(); i++) find(i);
    sort(root.begin(), root.end());
    int ans = 0;
    int tmp = 0;
    int now = 0;
    for (int i = 0; i < s.size(); i++){
        if (root[i] != now){
            ans = max(ans, tmp);
            tmp = 0;
            now = root[i];
        }
        tmp++;
    }
    if (!flag) cout << 0 << endl;
    else cout << ans << endl;
}

