        while(j>=0 && s[i] != s[j]) j = s_mp[j];
        ++j;
        s_mp[i+1] = j;
    }
    j = -1;
    for(int i=0;i<t.size();++i){
        while(j>=0 && t[i] != t[j]) j = t_mp[j];
        ++j;
        t_mp[i+1] = j;
    }
    int sp = s.size() - s_mp[s.size()];
    if(s.size() % sp != 0) sp = s.size();
    int tp = t.size() - t_mp[t.size()];
