	string S = t + "#" + s + s;
	z_algorithm(S, Z);

	for(int i = 0; i < n; i++) z[i] = Z[i+m+1];

	for(int i = 0; i < n; i++){
		if(z[i] == m && i+m <= n) dp[i+m] = max(dp[i+m], dp[i] + 1);
	}
	int ans = 0;
	for(int i = 0; i <= n; i++) ans = max(ans, dp[i]);
	if(s.size() % m == 0 && ans >= n / m - 1) ans = -1;
	if(ans != -1) ans /= mul;
	cout << ans << endl;

	return 0;
}

