vector<bool> match(string t, string p) {
    int n = t.size(), m = p.size();
    int M[0x100]; fill(M, M+0x100, 0);
    int count = 0;
    for (int i = 0; i < m; ++i) M[p[i]] |= (1 << i);
    vector<bool> ret(n, false);
    for (int i = 0, S = 0; i < n; ++i) {
        S = ((S << 1) | 1) & M[t[i]];
        if (S & (1 << (m-1))) {
            ret[i - m + 1] = true; // match at t[i-m+1 ... i]
        }
    }
    return ret;
}

struct UnionFind
{
    vector< int > data;

    UnionFind(int sz)
    {
        data.assign(sz, -1);
    }

    bool unite(int x, int y)
    {
        x = find(x), y = find(y);
        if(x == y) return(false);
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return(true);
    }

    int find(int k)
    {
        if(data[k] < 0) return(k);
        return(data[k] = find(data[k]));
    }

    int size(int k)
    {
        return(-data[find(k)]);
    }
};

