const int MAXN = 500005;
const int LOG = 21;
using namespace std;

int* z_function(const char s[],int n) {
    int* z = new int[n];
    memset(z, 0, sizeof(z));
    z[0] = n;
    int L = 0, R = 1;
    for (int i=1; i<n; ++i)
       if (R <= i || z[i-L] >= R-i){
            int x = (R <= i ? i : R);
            while (x < n && s[x] == s[x-i]) x++;
            z[i] = x-i;
            if (i < x) {L = i; R = x;}
        }
        else
           z[i] = z[i-L];
    return z;
}

int jump[LOG][MAXN];

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0);

	string s, t, big;
	cin >> s >> t;
	big = t;
	big += '$';
	for (int i = 0; i < (t.size() + s.size() - 1) / s.size() + 1; i++) {
		big += s;
	}

	int *z = z_function(big.c_str(), big.size());
	for (int i = 0; i < s.size(); i++) {
		if (z[t.size() + 1 + i] >= t.size()) {
			jump[0][i] = (i + t.size()) % s.size();
		}
		else {
			jump[0][i] = -1;
		}
	}

	for (int i = 1; i < LOG; i++) {
		for (int j = 0; j < s.size(); j++) {
			if (jump[i - 1][j] != -1) {
				jump[i][j] = jump[i - 1][jump[i - 1][j]];
			}
			else {
				jump[i][j] = -1;
			}
		}
	}

	int ans = 0;
	for (int i = 0; i < s.size(); i++) {
		int res = 0, cur = i;
		for (int j = LOG - 1; j >= 0; j--) {
			if (jump[j][cur] != -1) {
				res += 1 << j;
				cur = jump[j][cur];
			}
		}
		ans = max(ans, res);
	}

	if (ans >= s.size()) {
		cout << "-1\n";
	}
	else {
		cout << ans << '\n';
	}

	delete[] z;
	return 0;
}

