V<ll> calc_prefix(const string &T) {
    V<ll> ret(T.size(), 0);
    ll cur_max_idx = 0;
    for(ll i = 1; i < T.size(); i++) {
        if(ret[i - cur_max_idx] < ret[cur_max_idx] - (i - cur_max_idx)) {
            ret[i] = ret[i - cur_max_idx];
        } else {
            ll j = max<ll>(0, ret[cur_max_idx] - (i - cur_max_idx));
            for(; i + j < T.size() && T[i + j] == T[j]; j++);
            ret[i] = j;
            cur_max_idx = i;
        }
    }
    ret[0] = T.size();
    return ret;
}

V<ll> same_idx(const string &S, const string &T) {
    V<ll> max_prefix(S.size());
    V<ll> max_prefix_t = calc_prefix(T);
    DEBUG(max_prefix_t);
    string SS = S;
    while(SS.size() < T.size() + S.size()) SS += S;
    ll cur_max_idx = 0;
    for(ll i = 0; i < S.size(); i++) {
        DEBUG(PLL(i, cur_max_idx));
        if(max_prefix_t[i - cur_max_idx] < max_prefix[cur_max_idx] - (i - cur_max_idx)) {
            max_prefix[i] = max_prefix_t[i - cur_max_idx];
        } else {
            ll j = max<ll>(0, max_prefix[cur_max_idx] - (i - cur_max_idx));
            for(; i + j < SS.size() && j < T.size() && SS[i + j] == T[j]; j++);
            max_prefix[i] = j;
            cur_max_idx = i;
        }
    }
    DEBUG(max_prefix);
    V<ll> ret;
    for(ll i = 0; i < S.size(); i++) if(max_prefix[i] == T.size()) ret.push_back(i);
    return ret;
}

