// https://snuke.hatenablog.com/entry/2014/12/03/214243
// input  aaabaaaab
// output 921034210
int Zargorithm( int n, const int* S, int* A ) {
    A[0] = n;
    int i = 1, j = 0;
    while (i < n) {
        while (i+j < n && S[j] == S[i+j]) ++j;
        A[i] = j;
        if (j == 0) { ++i; continue;}
        int k = 1;
        while (i+k < n && k+A[k] < j) A[i+k] = A[k], ++k;
        i += k; j -= k;
    }
    return 0;
}


