  vector<int> G(sz(u), -1);
  rep(i, sz(u)) {
    pll hu = U.get(i, i + sz(t));
    if (hu == ht) {
      G[i] = (i + sz(t)) % sz(s);
    }
  }
  int ans = 0;
  vector<int> used(sz(s));
  rep(i, sz(s)) {
    int now = i;
    if (used[now]) continue;
    int cnt = 0;
    while (1) {
      used[now] = 1;
      now = G[now];
      if (now == -1) break;
      cnt++;
      if (cnt == sz(s)) {
        cout << -1 << endl;
