ll count(string& X, string& Y){
	rolling_hash rx(X);
	ll N = Y.size();
	ll lb = -1;
	ll ub = 707070;
	while(ub-lb>1){
		ll m = (lb+ub)/2;
		bool flag = false;
		if(X.size() >= m*N){
			string Z = "";
			REP(i, m) Z += Y;
			rolling_hash rz(Z);
			//dump(Z)
			ll ha[2] = {rz.hash(0, m*N, 0), rz.hash(0, m*N, 1)};
			REP(i, X.size()){
				if(i+m*N>X.size()) break;
				if(rx.match(i, i+m*N, ha)) flag = true;
			}
		}
		if(flag) lb = m;
		else ub = m;
	}
	return ub-1;
}

