int main(int argc, const char * argv[]) {

    ios::sync_with_stdio(false);
    cin.tie(0);

    string s, t; cin >> s >> t;
    int s_len = (int)s.size();
    int t_len = (int)t.size();

    for (int i = 0; i < t_len - 1; i++) {
        s += s[i % s_len];
    }

    // "Partial match" table
    vector<int> MP_table(t_len + 1);
    MP(MP_table, t);

    // KMP search
    vector<bool> match(s_len);
    KMP_search(s, t, MP_table, match);

    int ans = 0;
    bool flag_inf = false;

    vector<bool> checked(s_len, false);
    vector<int> dist(s_len, 0);

    for (int i = 0; i < s_len; i++) {
        int walker = i;

        while (match[walker]) {
            checked[walker] = true;

            if (checked[(walker + t_len) % s_len]) {
                dist[i] = dist[i] + dist[(walker + t_len) % s_len];
                break;
            }

            dist[i]++;
            walker = (walker + t_len) % s_len;

            if (walker == i) {
                flag_inf = true;
                break;
            }
        }

        if (flag_inf) break;
    }

    for (int i = 0; i < s_len; i++) {
        ans = max(ans, dist[i]);
    }

    cout << (flag_inf ? -1 : ans) << endl;

}

