vector<int> rolling_hash(string a, string b) {
    typedef unsigned long long ull;
    ull B = 1000000007;

    ull ah = 0, t = 1;
    rep(j, sz(a)) t *= B;
    rep(j, sz(a)) {
        ah = ah * B + a[j];
    }

    ull bh = 0;
    rep(j, sz(a)) bh = bh * B + b[j];

    vector<ull> bhs;
    rep(i, sz(b)) {
        bhs.eb(bh);
        bh = bh * B - b[i] * t + b[i + sz(a)];
    }

    vector<int> ret(sz(b));
    rep(i, sz(b)) if (ah == bhs[i]) ret[i] = 1;
    return ret;
}

struct UnionFind {
  vector<int> data;
  int sz;
  UnionFind(int _sz) : data(_sz, -1) { sz = _sz; }
  bool connect(int x, int y) {
      if ((x = root(x)) == (y = root(y))) return false;
      if (data[x] > data[y]) swap(x, y);
      data[x] += data[y]; data[y] = x; sz--;
      return true;
  }
  bool issame(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
  int size() { return sz; }
};


