  rep(i, sz(s)) {
    int I = i + sz(s);
    int j = (i + sz(t)) % sz(s);
    int J = j + sz(s);

    if (v[I] && v[J]) {
      if (!uni.connect(i, j)) {
        cout << -1 << endl;
        return;
      }
    }
  }
  // rep(i, sz(s)) cout << uni.root(i) << " "; cout << endl;

  int ans = 0;
  // if (v[i]) 重要
  rep(i, sz(s)) if (v[i]) chmax(ans, uni.size(i));

  cout << ans << endl;
}

