//文字列Sが与えられた時、各 i について「S と S[i:|S|-1] の最長共通接頭辞の長さ」の配列を返す
vector<ll> zalgorithm(const string &s) {
	vector<ll> ans(s.size());
	ans[0] = s.size();
	int i = 1, j = 0;
	while (i < s.size()) {
		while (i + j < s.size() && s[j] == s[i+j]) ++j;
		ans[i] = j;
		if (!j) {
			++i;
			continue;
		}
		int k = 1;
		while (i + k < s.size() && k + ans[k] < j) ans[i+k] = ans[k], ++k;
		i += k;
		j -= k;
	}
	return ans;
}

