typedef std::vector<int> vin;
const int MAXS = 1e6+5;
const int NOPE = -1;
char s[MAXS], t[MAXS];
int F[MAXS]; // KMP failure function
vin G[MAXS]; // Matching T
int deg[MAXS]; // In-degree
int lvl[MAXS]; // Distance
int N, S, T;
vin pos;

void kmp() {
  int i = 0;
  int j = 0;
  while (i < N) {
    if (t[j] == s[i]) {
      if (j == T-1) {
//        return i-T+1;
        pos.push_back(i-T+1);
        j = F[j-1];
//        j = 0;
//        ++i;
      } else {
        ++i;
        ++j;
      }
    } else if (j > 0) {
      j = F[j-1];
    } else {
      ++i;
    }
  }
}

void pmt() {
  F[0] = 0;
  int i = 1;
  int j = 0;
  while (i < T) {
    if (t[i] == t[j]) {
      ++j;
      F[i] = j;
      ++i;
    } else if (j > 0) {
      j = F[j-1];
    } else {
      F[i] = 0;
      ++i;
    }
  }
}

void repeat() {
  // Concatenate S with itself
  N = S;
  int st = S + T;
  while (N < st) {
    for (int i = 0; i < S; ++i, ++N) {
      s[N] = s[i];
    }
    s[N] = '\0';
  }
}

int solve() {
  for (int u: pos) {
    int v = (u + T) % S;
    G[u].push_back(v);
    ++deg[v];
//    printf("%d -> %d\n", u, v);
  }
  std::queue<int> Q;
  for (int i = 0; i < N; ++i) {
    if (!deg[i]) {
      lvl[i] = 0;
      Q.push(i);
//      printf("%d: start\n", i);
    } else {
      lvl[i] = NOPE;
    }
  }
  while (!Q.empty()) {
    int cur = Q.front();
    Q.pop();
    for (int nxt: G[cur]) {
      if (!--deg[nxt]) {
        lvl[nxt] = lvl[cur] + 1;
        Q.push(nxt);
      }
    }
  }
  int ret = 0;
  for (int i = 0; i < N; ++i) {
    if (lvl[i] == NOPE) {
      return NOPE;
    }
    ret = std::max(lvl[i], ret);
  }
  return ret;
}

int main() {
  scanf(" %s%s", s, t);
  S = strlen(s);
  T = strlen(t);
  repeat();
  pmt(); // Partial match table
  kmp(); // Knuth-Morris-Pratt
  printf("%d\n", solve());
  return 0;
}

