class UnionFind
{
private:
    ::std::vector<int> par;
    ::std::vector<int> rank;
public:
    UnionFind(int n):par(n), rank(n){
        for(int i=0; i<n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }
    int root(int x){
        if (par[x]==x) return x;
        return par[x] = root(par[x]);
    }
    bool same(int x, int y){
        return root(x)==root(y);
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx==ry) return;
        if (rank[rx]>rank[ry]){
            par[ry] = rx;
        }else{
            par[rx] = ry;
            if (rx==ry) rank[ry]++;
        }
    }
};

using ull = unsigned long long;
const ull b = 9973;
const ull mod[2] = {1000000033, 1000000087};

struct RollingHash{
    int n;
    vector<ull> hash[2], pw[2];
    RollingHash(const string &s){
        n = s.size();
        for(int i=0; i<2; i++){
            hash[i].resize(n+1);
            pw[i].resize(n+1);
            hash[i][0] = 0;
            pw[i][0] = 1;
            for(int j=0; j<n; j++){
                pw[i][j+1] = (pw[i][j]*b)%mod[i];
                hash[i][j+1] = (hash[i][j]*b+s[j])%mod[i];
            }
        }
    }
    static vector<ull> getHash(const string &s){
        int m = s.size();
        vector<ull> ret(2);
        for(int i=0; i<2; i++){
            ret[i] = 0;
            for(int j=0; j<m; j++)
                ret[i] = (ret[i]*b+s[j])%mod[i];
        }
        return ret;
    }
    bool match(int l, int r, vector<ull> h){
        bool ret=true;
        for(int i=0; i<2; i++){
            ull val = hash[i][r]-hash[i][l]*pw[i][r-l]%mod[i];
            val = (val+mod[i])%mod[i];
            ret&=(val==h[i]);
        }
        return ret;
    }
};

