int z[T_MAX+4*S_MAX];

void z_algorithm(string s, int *z) {
    int n = s.length(), k = 0;
    for(int i=1;i<n;++i) {
        if(i + z[i-k] < k + z[k]) {
            z[i] = z[i-k];
        } else {
            int j = max(0, k + z[k] - i);
            while(i + j < n && s[i+j] == s[j]) ++j;
            z[i] = j;
            k = i;
        }
    }
    z[0] = n;
}

int calc_period(string s, int n) {
    int s_period = INF;
    for(int i=1;i<=sqrt(n+1);++i) {
        if(n % i) continue;
        bool is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%i]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, i);
        }
        is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%(n/i)]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, n/i);
        }
    }
    return s_period;
}

