inline void DoHash(ulint HHH[], string & SSS) {
	#define s SSS
	#define Hash HHH
	Hash[0] = s[0] - 'a' + 1;
	rep (i, 1, SZ(s) - 1) {
		if (i) Hash[i] = Hash[i - 1] * 2323 + s[i] - 'a' + 1;
	}
	#undef s
	#undef Hash
}
inline void DoHash2(ulint HHH[], string & SSS) {
	#define s SSS
	#define Hash HHH
	Hash[0] = s[0] - 'a' + 7;
	rep (i, 1, SZ(s) - 1) {
		if (i) Hash[i] = (Hash[i - 1] * 2233 + s[i] - 'a' + 7) % MOD;
	}
	#undef s
	#undef Hash
}
inline ulint getHash(ulint HHH[], int l, int r) {
	if (!l) return HHH[r];
	return HHH[r] - HHH[l - 1] * mul[r - l + 1];
}
inline ulint getHash2(ulint HHH[], int l, int r) {
	if (!l) return HHH[r];
	lint ret = HHH[r] - (HHH[l - 1] * mul2[r - l + 1]) % MOD;
	return ret < 0 ? ret + MOD : ret;
}
inline bool checkINF() {
	int j = fail[0] = -1;
	rep (i, 1, SZ(s) - 1) {
		while (~j && s[i - 1] != s[j]) j = fail[j];
		fail[i] = ++j;
	}
	int now = 0, flag = 0;
	rep (i, 0, SZ(t) - 1) {
		if (t[i] != s[now] && flag == -1) return false;
		while (~now && t[i] != s[now]) now = fail[now];
		if (++now == SZ(s)) flag = -1, now = 0;
	}
	if (~flag) return false;
	return true;
}
inline bool check(int mid) {
	int l = SZ(s) * mid;
	ulint use = 0, use2 = 0;
	rep (i, 1, mid) {
		use = use * mul[SZ(s)] + getHash(Hash[1], 0, SZ(s) - 1);
		use2 = (use2 * mul2[SZ(s)] + getHash2(Hash2[1], 0, SZ(s) - 1)) % MOD;
	}
	rep (i, 0, SZ(t)) {
		if (i + l > SZ(t)) return false;
		if (getHash(Hash[0], i, i + l - 1) == use && getHash2(Hash2[0], i, i + l - 1) == use2) return true;
	}
	return false;
}
