signed main() {
    cin >> S >> T;
    int times = 1;
    //Tの繰り返し検知
    int n = T.size();
    for (int i = 1; i <= sqrt(n); ++i) {
        int a = n / i;
        if (n % a)continue;
        //a等分
        int len = n / a;
        rep(j, a) {
            rep(k, len) {
                if (T[len * j + k] != T[k])goto no;
            }
        }
        //a等分できる
        n /= a;
        times = a;
        T = T.substr(0, len);
        no:;
    }
    for (int i = (int) sqrt(n); i >= 1; --i) {
        if (n % i)continue;
        int a = i;
        //a等分
        int len = n / a;
        rep(j, a) {
            rep(k, len) {
                if (T[len * j + k] != T[k])goto no2;
            }
        }
        //a等分できる
        n /= a;
        times = a;
        T = T.substr(0, len);
        no2:;
