// [0, n) [n, last)
H rotate(RH &rh, int n, int sz) {
    int h2_sz = n;
    H ret;
    {
        ret.first = rh.first.join(rh.first.get(n, sz), rh.first.get(0, n), h2_sz);
        // print(n, sz, rh.first.get(n, sz));
    }
    {
        ret.second = rh.second.join(rh.second.get(n, sz), rh.second.get(0, n), h2_sz);
    }
    return ret;
}

