    CountUnionFind uf(ns);
    for(int i = 0; i < id.size(); ++i){
        if(id[i] >= ns) break;
        ok[id[i]] = true;
    }
    for(int i = 0; i < ns; ++i){
        if(!ok[i])  continue;
        int foo = i, bar = (i + nt) % ns;
        if(uf.same(foo, bar)){
            cout << -1 << endl;
            return 0;
        }
        uf.unite(foo, bar);
    }
    int res = 0;
    for(int i = 0; i < ns; ++i){
        if(ok[i])   chmax(res, uf.get_cnt(i) - 1);
    }
    cout << res << endl;
}

