    if(dp[p] != -1) return dp[p];
    if(x[p] == 0) return 0;
    if((p + m) % n == p) {
        cout << -1 << endl;
        exit(0);
    }
    dp[p] = solve((p + m) % n) + 1;
    if(dp[p] >= 1000000) {
        cout << -1 << endl;
        exit(0);
    }
    return dp[p];
};

