const ll mask30 = (1ll << 30) - 1;
const ll mask31 = (1ll << 31) - 1;
const ll RHmod = (1ll << 61) - 1;
const ll len = 1000100;
ll POW[len + 1], RH[len + 1];
ll RHmul(ll A, ll B) {
	ll A1 = A >> 31;
	ll A2 = A & mask31;
	ll B1 = B >> 31;
	ll B2 = B & mask31;
	ll ret = 2 * A1 * B1 + A2 * B2 + ((A1 * B2 + A2 * B1 & mask30) << 31) + (A1 * B2 + A2 * B1 >> 30);
	return ret % RHmod;
}
ll RHcalc(int i, int j) {
	ll kari = (RH[j] - RH[i] + RHmod) % RHmod;
	return RHmul(kari, POW[len - i]);
}


