  Pll thash = mk(rt.get(0, sz(t), 0), rt.get(0, sz(t), 1));
  for(int i = sz(S) - 1; i >= 0; i--){
    Pll shash = mk(rs.get(i, i + sz(t), 0), rs.get(i, i + sz(t), 1));
    if(thash != shash)to[i] = -1;
    else {
      to[i] = (i + sz(t)) % sz(S);
    }
  }
  // rep(i, sz(S))cout << i << " " << to[i] << endl;
  UnionFind uf(sz(S));
  rep(i, sz(S)){
    if(to[i] == -1)continue;
    if(uf.same(i, to[i])){
      cout << -1 << endl;
      return 0;
    }
    uf.unite(i, to[i]);
  }
  ll res = 0;
  rep(i, sz(S)){
    if(vis[i] || to[i] == -1)continue;
    ll tmp = calc(i);
    res = max(res, tmp);
  }
  cout << res << endl;
  return 0;
}

