std::string operator*(const std::string& s, size_t n) {
    std::string result;
    result.reserve(s.size()*n);
    for(size_t i = 0; i < n; ++i) {
        result += s;
    }
    return result;
}

void solve() {
    string s, t;
    cin >> s >> t;

    if (s.length() < t.length())
        s = s * ((t.length() + s.length() - 1) / s.length());
    int n = s.length();
    s = s * 3;

    int lo = 0;
    int hi = s.length() / t.length();
    while (lo < hi) {
        int mi = (lo + hi) / 2;
        string u = t * mi;
        if (s.find(u) == string::npos)
            hi = mi;
        else
            lo = mi + 1;
    }

    string u = t * (lo - 1);

    if (u.length() >= 2 * n) {
        cout << -1 << '\n';
        return;
    }

    cout << lo - 1 << '\n';
    return;
}

