using namespace std;
const int N=1e7+7;
int lp[N],found[N];
int dp[N];
void ff(string t)//pattern
{
    for(int i=1,k=0;i<t.size();i++)
    {
        while(k>0&&t[i]!=t[k]) k=lp[k-1];
        if(t[i]==t[k]) k++;
        lp[i]=k;
    }
}
void kmp(string s,string t)//text , pattern
{
    for(int i=0,k=0;i<s.size();i++)
    {
        while(k>0&&s[i]!=t[k]) k=lp[k-1];
        if(s[i]==t[k]) k++;
        if(k==t.size())
            found[i-k+1]=1;

    }
}
string s,t;
int solve(int idx)
{
    int &ret=dp[idx];
    if(~ret) return ret;
    if(found[idx])
        return ret=solve((idx+(int)t.size())%s.size())+1;
    return ret=0;
}
int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    string ss;
    cin>>ss>>t;
    while((int)s.size()<(int)t.size())
        s+=ss;
    s+=(s+s);
    //cout<<s<<endl;
    ff(t);
    kmp(s,t);
    memset(dp,-1,sizeof dp);
    int ans=0,cnt=0;
    for(int i=0;i<(int)s.size();i++)
        if(found[i])cnt++;
    if(cnt==(int)s.size()-(int)t.size()+1)
        return cout<<-1<<endl,0;
    for(int i=0;i<(int)s.size();i++)
        ans=max(ans,solve(i));
    cout<<ans<<endl;
    return 0;
}

