        }
        uf.unite(foo, bar);
    }
    int res = 0;
    for(int i = 0; i < id.size(); ++i){
    	if(id[i] >= ns)  break;
      	chmax(res, uf.get_cnt(id[i]) - 1);
    }
    cout << res << endl;
}

