  std::cin>>s>>t;

  ll n=s.size(),m=t.size();

  rep(i,0,(ll)(m/n)+2)u+=s;

  std::vector<ll> match=Zsearch(u,t);
  std::vector<std::vector<ll>> graph(n);

  if(match.empty()){
    std::cout<<0;
    return 0;
  }

  for(ll i:match){
    if(i<n)graph[i].push_back((i+m)%n);
  }

  std::vector<ll> a=topo_sort(graph),dp(n,0);

  if(a.size()!=n){
    std::cout<<-1;
    return 0;
  }

  for(ll i=n-1;i>=0;i--){
    ll now=a[i];
    for(ll j:graph[now])dp[now]=std::max(dp[now],dp[j]+1);
  }

  ll ans=0;
  rep(i,0,n)ans=std::max(ans,dp[i]);

  std::cout<<ans;

  return 0;
}

