class KMP {
private:
    const string word;
    vector<int> table;
public:
    KMP(const string& word): word(word), table(word.size() + 1) {
        const int n = word.size();
        table[0] = -1;

        for(int i=0, j=-1; i<n; i++) {
            while (j >= 0 && word[i] != word[j]) j = table[j];
            table[i+1] = ++j;
        }
    }

    bool query(const string& str) {
        int m = 0, i = 0, n = str.size();
        while (m+i < n) {
            if (word[i] == str[m+i]) {
                if (++i == (int)(word.size())) {
                    return true;
                }
            } else {
                m = m+i-table[i];
                if (i > 0) i = table[i];
            }
        } 
        return false;
    }
};

bool infinite(const string& s, const string& t) {
    const int m = s.length(), n = t.length(); // m <= n

    for(int i=0; i<n*2; i++) { // infinite
        if(s[i % m] != t[i % n]) {
            return false;   
        }
    }

    return true;
}

