        cout << -1 << endl;
        return 0;
    }

    int l = 0, r = 2 * n / m + 1;
    while(r - l > 1) {
        int m = (r + l) / 2;

        KMP kmp(s_pow(s, m));
        if(kmp.query(t + t))
            l = m; 
        else
            r = m;
    }

    cout << l << endl; 

    return 0;
}

