ModInt<> powMemo[500500];
int memo[500500];

void preCalc() {
    memo[0] = -1;
    powMemo[0] = 1;
    for (int i = 1; i < 500500; ++i) {
        memo[i] = -1;
        powMemo[i] = powMemo[i - 1] * 27;
    }
}

ModInt<> Slice(vector<ModInt<>> hash, int begin, int length) {
    return hash[begin + length] - hash[begin] * powMemo[length];
}

int solve(int begin) {
    if (calling[begin]) {
        inf = true;
        return memo[begin] = 0;
    }
    calling[begin] = true;
    int tPlace = 0;
    int sPlace = begin;
    int remainLength = T.length();
    while (remainLength) {
        int nextLength = min(remainLength, (int) min(T.length() - tPlace, S.length() - sPlace));
        if (Slice(shash, sPlace, nextLength) != Slice(thash, tPlace, nextLength)) {
            calling[begin] = false;
            return memo[begin] = 0;
        }
        remainLength -= nextLength;
        sPlace += nextLength;
        tPlace += nextLength;
        if (sPlace == S.length())sPlace = 0;
        if (tPlace == T.length())tPlace = 0;
    }
    int res = (memo[sPlace] != -1 ? memo[sPlace] : solve(sPlace)) + 1;
    calling[begin] = false;
    return memo[begin] = res;
