vector<int> kmpPattern(const string& str)
{
    vector<int> pattern(1, 0);
    int len = 0;

    int i = 1;
    while (i < str.length())
    {
        if (str[i] == str[len])
        {
            ++len;
            pattern.push_back(len);
            ++i;
        }
        else
        {
            if (len != 0)
            {
                len = pattern[len - 1];
            }
            else
            {
                pattern.push_back(0);
                ++i;
            }
        }
    }

    return pattern;
}

vector<int> kmpSearch(const string& str, const string& target)
{
    vector<int> matches;
    vector<int> pattern = kmpPattern(target);
    int i = 0, j = 0;

    int strLen = str.length();
    int targetLen = target.length();

    while (i < strLen)
    {
        if (str[i] == target[j])
        {
            ++i;
            ++j;
        }

        if (j == targetLen)
        {
            matches.push_back(i - targetLen);
            j = pattern[j - 1];
        }
        else if (i < strLen && str[i] != target[j])
        {
            if (j > 0)
                j = pattern[j - 1];
            else
                ++i;
        }
    }

    return matches;
}

int solve()
{
    string str, target;
    cin >> str >> target;

    const int strLen = str.length();
    const int targetLen = target.length();

    while (strLen - 1 + targetLen > str.length())
        str += str;

    vector<int> matches = kmpSearch(str, target);

    if (matches.empty())
        return 0;

    while (!matches.empty() && matches.back() >= strLen)
        matches.pop_back();

    int maxCounter = -1;
    vector<int> dp(strLen, 0);

    unordered_set<int> us(matches.begin(), matches.end());

    for (int m: matches)
    {
        int counter = 1;
        int curr = (m + targetLen) % strLen;

        while (m != curr && dp[curr] != -1 && us.count(curr))
        {
            if (dp[curr] > 0)
            {
                counter += dp[curr];
                break;
            }

            ++counter;
            curr = (curr + targetLen) % strLen;
        }

        if (m != curr && dp[curr] != -1)
        {
            dp[m] = counter;
            maxCounter = std::max(maxCounter, counter);
        }
        else
        {
            dp[m] = -1;
        }
    }

    return maxCounter;
}

int main()
{
    cout << solve() << endl;

    return 0;
}

