        hash1.resize(n + 10);
        hash2.resize(n + 10);
        hash3.resize(n + 10);
        pow1.resize(n + 10, 1);
        pow2.resize(n + 10, 1);
        pow3.resize(n + 10, 1);
        for (int i = 0; i < n; i++) {
            hash1[i + 1] = (hash1[i] + s[i]) * base1 % mod1;
            hash2[i + 1] = (hash2[i] + s[i]) * base2 % mod2;
            hash3[i + 1] = (hash3[i] + s[i]) * base3 % mod3;
            pow1[i + 1] = pow1[i] * base1 % mod1;
            pow2[i + 1] = pow2[i] * base2 % mod2;
            pow3[i + 1] = pow3[i] * base3 % mod3;
        }
