void KMP(){
	bool isOk = false;
	int n = s.size();
	int t_size = t.size();
	while ((int)s.size() < (int)t.size()) isOk = true, s = s + s; 
	if (!isOk) s = s + s;
	s = t + "#" + s;
	// cout << s << '\n';
	for(int i=1;i<s.size();++i){
		int j = p[i-1];
		while (j && s[i] != s[j]) j = p[j-1];
		if (s[i] == s[j]) j++;
		p[i] = j;
	}
