	for(int i= (int)s.size() - n;i<(int)s.size();++i){
		// cout << p[i] << ' ';
		if (p[i] == t_size) nxt[(i - t_size + 1) % n] = (i + 1) % n;
	}
	// for(int i=0;i<n;++i) cout << nxt[i] << '\n';
	int res = 0, cnt = 0;
	bool cycle = 0;
	for(int i=0;i<n;++i){
