// 部分文字列のhash値を計算
// https://qiita.com/keymoon/items/11fac5627672a6d6a9f6
class RollingHash {
    const unsigned long long MASK30 = (1ull << 30ull) - 1;
    const unsigned long long MASK31 = (1ull << 31ull) - 1;
    const unsigned long long MOD = (1ull << 61ull) - 1;
    const unsigned long long POSITIVIZER = MOD * ((1ull << 3ull) - 1);

    int n;
    unsigned int Base;
    vector<unsigned long long> powMemo;
    vector<unsigned long long> has;

public:
    RollingHash(const std::string &s) : n(s.size()) {
        powMemo.resize(n + 1);
//        Base = (uint)new Random().Next(129, int.MaxValue);
        Base = 129;
        powMemo[0] = 1;
        for (int i = 1; i < powMemo.size(); i++) {
            powMemo[i] = calc_mod(mul(powMemo[i - 1], Base));
        }

        has.resize(s.size() + 1);
        for (int i = 0; i < s.size(); i++)
            has[i + 1] = calc_mod(mul(has[i], Base) + s[i]);
    }

    // s[left, right)のhash値 O(1)
    unsigned long long hash(int left, int right) {
        assert(0 <= left and left < right and right <= n);

        const int length = right - left;
        return calc_mod(has[right] + POSITIVIZER - mul(has[left], powMemo[length]));
    }

private:
    unsigned long long mul(unsigned long long l, unsigned long long r) {
        unsigned long long lu = l >> 31ull;
        unsigned long long ld = l & MASK31;
        unsigned long long ru = r >> 31ull;
        unsigned long long rd = r & MASK31;
        unsigned long long middleBit = ld * ru + lu * rd;
        return ((lu * ru) << 1ull) + ld * rd + ((middleBit & MASK30) << 31ull) + (middleBit >> 30ull);
    }

    unsigned long long mul(unsigned long long l, unsigned int r)  {
        unsigned long long lu = l >> 31ull;
        unsigned long long rd = r & MASK31;
        unsigned long long middleBit = lu * rd;
        return  (l & MASK31) * rd + ((middleBit & MASK30) << 31ull) + (middleBit >> 30ull);
    }

    unsigned long long calc_mod(unsigned long long val) {
        val = (val & MOD) + (val >> 61ull);
        if (val > MOD) {
            val -= MOD;
        }
        return val;
    }
};

class TopologicalSort {
    const int N;                           // ノード数
    std::vector<std::vector<int>> graph;   // グラフ
    std::vector<bool> used;                // 使用済みノード
    std::vector<int> indeg;                // 入次数


public:
    std::vector<int> result; // ソート結果

public:
    TopologicalSort(unsigned int num_node) : N(num_node) {
        this->graph.resize(num_node);
        this->indeg.resize(num_node, 0);
        this->used.resize(num_node, false);
    }

    // u -> vのedgeを追加
    void add(int u, int v) {
        assert(u != v);
        this->graph[u].emplace_back(v);
    }

    // O(V + E)
    bool sort() {
        for (int u = 0; u < this->N; ++u) {
            for (int v : this->graph[u]) {
                this->indeg[v]++;
            }
        }

        for (int u = 0; u < this->N; ++u) {
            if (this->indeg[u] == 0 and not this->used[u]) {
                bfs(u);
            }
        }

        return (int)this->result.size() == this->N;
    }

    // グラフの有向パスのうち最長のものの長さ
    // ソート結果が一意ならN - 1になる
    int longest_distance() {
        int ans = 0;
        std::vector<int> distance(this->N, 0);
        for (int u : this->result) {
            for (int v : this->graph[u]) {
                distance[v] = max(distance[v], distance[u] + 1);
                ans = max(ans, distance[v]);
            }
        }

        return ans;
    }

private:
    void bfs(const int s) {
        std::queue<int> que;
        que.push(s);
        this->used[s] = true;
        while (not que.empty()) {
            int u = que.front();
            que.pop();
            this->result.emplace_back(u);

            for (int v : this->graph[u]) {
                this->indeg[v]--;
                if (this->indeg[v] == 0 and not this->used[v]) {
                    this->used[v] = true;
                    que.push(v);
                }
            }
        }
    }
};

