vector<int> getZarr(string T, string P) {
  string S = P+'$'+T;
  vector<int> Z(S.size());
  int c = 0;
  for (int i = 1; i < S.size(); i++){
    if (i+Z[i-c] < c+Z[c]) {
      Z[i] = Z[i-c];
    } else {
      int j = max(0, c+Z[c]-i);
      while (i+j < S.size() && S[j] == S[i+j]) j++;
      Z[i] = j;
    }
  }
  Z[0] = P.size();
  return Z;
}

int main() {
  string T, t, P; cin >> T >> P;
  while (t.size() < P.size()) t += T;
  vector<int> Zarr = getZarr(t, P);
  int N = T.size()+P.size()+1;
  vector<int> edge(T.size(), -1);
  set<int> se;
  for (int i = 0; i < T.size(); i++) {
    if (Zarr[i+P.size()+1]== P.size()) {
      edge[i] = (i+P.size())%T.size();
      se.insert(i);
    }
  }
  vector<int> visited(T.size());
  int ans = 0;
  for (int v : se) {
    int c = 0;
    fill(visited.begin(), visited.end(), 0);
    while (edge[v] != -1) {
      visited[v] = 1;
      int u = edge[v];
      if (visited[u] == 1) {
        cout << -1 << endl;
        return 0;
      }
      v = u;
      c++;
    }
    ans = max(ans, c);
  }
  cout << ans << endl;
}

