void getnext()
{
    snext[0] = 0, snext[1] = 0;
    for (int i = 1; i < s2size; i++)
    {
        int j = snext[i];
        while (j && s2[i] != s2[j])
            j = snext[j];
        snext[i + 1] = s2[i] == s2[j] ? j + 1 : 0;
    }
}

int KMP()
{
    int res = 0;
    getnext();
    int j = 0;
    for (int i = 0; i < s1size; i++)
    {
        while (j && s2[j] != s1[i])
            j = snext[j];
        if (s2[j] == s1[i])
            j++;
        if (j == s2size)
            res++,isok[i]=1;
    }
    return res;
}
vector<int> e[MAXNUM*2];int degree[MAXNUM*2];
