        siz.resize(N,1);
        rep(i,0,N) par[i]=i;
    }
    ll root(ll X){
        if(par[X]==X) return X;
        return par[X]=root(par[X]);
    }
    bool same(ll X,ll Y){
        return root(X)==root(Y);
    }
    void unite(ll X,ll Y){
        X=root(X);
        Y=root(Y);
        if(X==Y) return;
        par[X]=Y;
        siz[Y]+=siz[X];
        siz[X]=0;
    }
    ll size(ll X){
        return siz[root(X)];
    }
};
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}
vi fac,finv,inv;
void COMinit() {
    fac.resize(MAX);
    finv.resize(MAX);
    inv.resize(MAX);
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
ll COM(ll n,ll r){
    if(n<r||n<0||r<0) return 0;
    return fac[n]*finv[r]%MOD*finv[n-r]%MOD;
}
void comp(vi &A){
    std::map<ll,ll> mem;
    rep(i,0,A.size()) mem[A[i]]=0;
    ll cnt=0;
    for(auto &p:mem) p.second=cnt++;
    rep(i,0,A.size()) A[i]=mem[A[i]];
}
void change(string &S){
    ll N=S.size();
    std::set<ll> memo;
    REP(i,1,sqrt(N)+1){
        if(N%i==0){
            memo.insert(i);
            memo.insert(N/i);
        }
    }
    for(auto p:memo){
        string T=S.substr(0,p);
        string X;
        bool flag=1;
        rep(i,p,N){
            X+=S[i];
            if(X.size()==p){
                if(X==T) X="";
                else{
                    flag=0;
                    break;
                }
            }
        }
        if(flag){
            S=T;
            return;
        }
    }
}
bool judge(string S,string T){
    srand((unsigned)time(NULL));
    vi mod(3);
    vi memo(3);
    rep(i,0,100) rand();
    rep(i,0,3) mod[i]=rand()%100000000000+1;
    ll N=S.size(),M=T.size();
    rep(i,0,3) memo[i]=modpow(27,M,mod[i]);
    vi model(3);
    vi now(3);
    rep(i,0,3){
        rep(j,0,M){
            ll X=T[j]-'a'+1;
            ll Y=S[j]-'a'+1;
            model[i]=(model[i]*27%mod[i]+X)%mod[i];
            now[i]=(now[i]*27+Y)%mod[i];
        }
    }
    bool flag=1;
    rep(i,0,3){
        if(model[i]!=now[i]){
            flag=0;
            break;
        }
    }
    if(flag) return 1;
    rep(i,M,N){
        flag=1;
        rep(j,0,3){
            ll X=S[i-M]-'a'+1,Y=S[i]-'a'+1;
            now[j]=(now[j]*27+Y)%mod[j];
            now[j]-=memo[j]*X%mod[j];
            now[j]%=mod[j];
            if(now[j]<0) now[j]+=mod[j];
            if(model[j]!=now[j]) flag=0;
        }
        if(flag) return 1;
    }
    return 0;
}
int main(){
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    string S,T; cin>>S>>T;
    change(S);
    ll N=S.size(),M=T.size();
    ll ans;
    if(N<=M){
        string X;
        REP(i,0,M/N) X+=S;
        if(judge(X,T)){
            if(M%N) ans=1;
            else ans=-1;
        }
        else ans=0;
    }
    else{
        S+=S;
        ll left=0,right=N*2/M;
        while(left+1<right){
            ll mid=(left+right)/2;
            string X;
            rep(i,0,mid) X+=T;
            if(judge(S,X)) left=mid;
            else right=mid;
        }
        ans=left; 
        if(N%M==0){
            string X;
            rep(i,0,N/M) X+=T;
            if(judge(S,X)) ans=-1;
        }
        if(N*2/M==ans){
            string s;
            rep(i,0,N/M) s+=S;
            left=0;
            right=M;
            while(left+1<right){
            ll mid=(left+right)/2;
            string X;
            rep(i,0,mid) X+=T;
            if(judge(S,X)) left=mid;
            else right=mid;
        }
        ans=left; 
        }
    }
    cout<<ans<<endl;
}

