    for(int i=1,k=0;i<t.size();i++)
    {
        while(k>0&&t[i]!=t[k]) k=lp[k-1];
        if(t[i]==t[k]) k++;
        lp[i]=k;
    }
}
void kmp(string s,string t)//text , pattern
{
    for(int i=0,k=0;i<s.size();i++)
    {
        while(k>0&&s[i]!=t[k]) k=lp[k-1];
        if(s[i]==t[k]) k++;
        if(k==t.size())
            found[i-k+1]=1;

    }
}
string s,t;
int solve(int idx)
{
    int &ret=dp[idx];
    if(~ret) return ret;
    if(found[idx])
        return ret=solve((idx+(int)t.size())%s.size())+1;
    return ret=0;
}
