    while((int)s.size()<(int)t.size())
        s+=ss;
    s+=(s+s+s);
    //cout<<s<<endl;
    ff(t);
    kmp(s,t);
    memset(dp,-1,sizeof dp);
    int ans=0,cnt=0;
    for(int i=0;i<(int)s.size();i++)
        if(found[i])cnt++;
    if(cnt==(int)s.size()-(int)t.size()+1)
        return cout<<-1<<endl,0;
    for(int i=0;i<(int)s.size();i++)
        ans=max(ans,solve(i));
