const int mod=1000000007,MAX=600001,INF=1<<30;

const ll B1=1000000007,B2=1000000009;
ll mo1,mo2;
vector<int> ok;

void contain(string a,string b){
    int al=a.length(),bl=b.length();
    if(al>bl) return;

    ll t1=1,t2=1;
    for(int i=0;i<al;i++){
        t1*=B1;
        t1%=mo1;
        t2*=B2;
        t2%=mo2;
    }

    ll ah1=0,ah2=0,bh1=0,bh2=0;
    for(int i=0;i<al;i++){
        ah1=(ah1*B1+(a[i]-'a'))%mo1;
        ah2=(ah2*B2+(a[i]-'a'))%mo2;
        bh1=(bh1*B1+(b[i]-'a'))%mo1;
        bh2=(bh2*B2+(b[i]-'a'))%mo2;
    }

    for(int i=0;i+al<=bl;i++){
        if(ah1==bh1&&ah2==bh2) ok.push_back(i);
        if(i+al<bl){
            bh1=(bh1*B1+(b[i+al]-'a')-((b[i]-'a')*t1)%mo1+mo1)%mo1;
            bh2=(bh2*B2+(b[i+al]-'a')-((b[i]-'a')*t2)%mo2+mo2)%mo2;
        }
    }

    return;

}

int par[MAX],size[MAX];

void init(int n){
    for(int i=0;i<n;i++){
        par[i]=i;
        size[i]=1;
    }
}

int root(int a){
    if(par[a]==a) return a;
    else return par[a]=root(par[a]);
}

void unite(int a,int b){
    if(root(a)!=root(b)){
        size[root(a)]+=size[root(b)];
        par[root(b)]=root(a);
    }
}

bool check(int a,int b){
    return root(a)==root(b);
}

int main(){

    srand((unsigned int)time(NULL));

    mo1=rand();
