    string preS,T,S;cin>>preS>>T;
    int L=T.size();

    while(int(S.size())<2*int(T.size())+int(preS.size())) S+=preS;

    contain(T,S);

    init(int(preS.size()));

    for(int i:ok){
        if(i>=preS.size()) break;
        int j=(i+L)%int(preS.size());
        if(check(i,j)){
            cout<<-1<<endl;
            return 0;
        }
        unite(i,j);
        //cout<<i<<endl;
    }

    int ans=-1;

    for(int i=0;i<preS.size();i++){
        ans=max(ans,size[root(i)]-1);
    }

    cout<<ans<<endl;


}

