int solve() {
  int res = 0;
  vector<int> cnt(n, -1);
  for (int i = 0; i < n; ++i)
    if (cnt[i] < 0) {
      vector<int> v(1, i);
      while (cnt[v.back()] < 0 && memo[v.back() + m + 1] == m) {
        int nxt = (v.back() + m) % n;
        if (nxt == i) return -1;
        v.push_back(nxt);
      }
      int now = 0;
      if (cnt[v.back()] < 0) cnt[v.back()] = 0;
      now = cnt[v.back()];
      while (v.size()) {
        cnt[v.back()] = now;
        v.pop_back();
        ++now;
      }
      res = max(res, cnt[i]);
    }
  return res;
}

