  vec = z_function(str2 + "#" + str1 + str1 + str1);
  bool ok = true;
  int c = 0;
  for (int i = m + 1; i < vec.size();) {
    if (vec[i] == m) {
      c++;
      i += m;
    } else {
      i++;
      if (c && i < vec.size() - 1) {
        ok = false;
        break;
      }
    }
  }
  if (ok)
    cout << -1 << endl;
  else
    cout << ans << endl;

  return 0;
}

#include <bits/stdc++.h>
#define MOD 1000000007LL
using namespace std;
typedef long long ll;
typedef pair<int,int> P;

struct rollinghash{
	static const int MD=3;
	static const int MAX=1500005;
	const ll base[MD]={1007LL,1009LL,1009LL};
	const ll mods[MD]={999999937LL, 1000000007LL,912941443LL};
	ll hash[MD][MAX+1];
	ll pw[MD][MAX+1];
	void init(){
		for(int i=0;i<MD;i++){
			pw[i][0]=1;
			for(int j=0;j<MAX;j++){
				pw[i][j+1]=pw[i][j]*base[i]%mods[i];
			}
		}
	}
	void construct(const string &str){
		int n=str.size();
		for(int i=0;i<MD;i++){
			hash[i][0]=0;
			for(int j=0;j<n;j++){
				hash[i][j+1]=(hash[i][j]*base[i]%mods[i]+str[j])%mods[i];
			}
		}
	}

	void construct(const vector<int> &vec){
		int n=vec.size();
		for(int i=0;i<MD;i++){
			hash[i][0]=0;
			for(int j=0;j<n;j++){
				hash[i][j+1]=(hash[i][j]*base[i]%mods[i]+vec[j])%mods[i];
			}
		}
	}

	// calc hash value [l,r)
	ll hash_value(int l,int r,int i){
		return ((hash[i][r]-hash[i][l]*pw[i][r-l])%mods[i]+mods[i])%mods[i];
	}
};

int ns,nt;
string s,t;
rollinghash ro_s,ro_t;

bool C(int v){
	int cur_t=t.size()*v;
	for(int i=0;i+cur_t<=ns;i++){
		bool flag=true;
		for(int j=0;j<3;j++){
			if(ro_s.hash_value(i,i+cur_t,j)!=ro_t.hash_value(0,cur_t,j)){
				flag=false;
			}
		}
		if(flag)return true;
	}
	return false;
}

int main(void){
	cin >> s;
	cin >> t;
	string ss="";
	string tt="";
	for(ns=0;ns+s.size()<ro_s.MAX;ns+=s.size()){
		ss+=s;
