int main(){
	string s;
	string t;

	cin >> s;
	cin >> t;

	int ls = s.length();
	int lt = t.length();

	string sd; // sの繰り返し文字列 ls + lt 以上の長さが必要
	while (sd.length() < ls + lt) {
		sd.append(s);
	}

	string sub_str = sd.substr(0, ls + lt - 1);	
	vector<int> tb = genKMPtable(t);
	vector<int> v = AllIndexKMPsearch(sub_str, t, tb, ls + lt - 1);

	vector <vector <edge> > G(ls);
	for (auto el: v) {
		G.at(el).emplace_back((edge){(el + lt) % ls});
	}

	// グラフの最長パス求める
	// 各ノードから出るedgeは 1本/0本 なので開始点が分かれば経路は1通り
	vector<int> path_len(ls);
	for (size_t i = 0; i < ls; ++i) {
		vector<bool> vis(ls);
		int length = 0;

		int pos = i;
		vis[pos] = true;

		while(!G[pos].empty()) {
			++length;

			pos = G[pos][0].to;
			if (vis[pos] == true) {
				// 無限ループの場合
				cout << -1 << endl;
				return 0;
			}
			vis[pos] = true;
		}

		path_len[i] = length;
	}

	int ret = *max_element(begin(path_len), end(path_len));
	cout << ret << endl;

	return 0;
}

