  }
  else {
    int start = *fa.begin();
    int streak = 1;
    int cur = start;
    bool looped = false;
    bool gap = false;

    while (true) {
      //debug(cur);
      int next = cur + t.size();
      if (next >= hs) next -= hs;
      int fi = lower_bound(rng(fa), next) - fa.begin();
      if (fi == fa.size()) fi = 0;
      if (fa[fi] == next) {
        streak++;
        if (looped && !gap) {
          result = -1;
          break;
        }
      }
      else {
        gap = true;
        next = fa[fi];
        streak = 1;
        if (looped) break;
      }

      //debug(streak);
      chmax(result, streak);

      if (next == start || next == start + hs) {
        looped = true;
      }
      cur = next;
      //debug(cur);
    }
  }

  cout << result;
}
