void dfs(int node, int root, const vector<int>& z, int n, int m,
         vector<bool>& isVisited, vector<int>& depth) {
  isVisited[node] = true;
  if (z[node + m] < m) {
    depth[node] = 0;
  } else {
    const int nxt = (node + m) % n;
    if (!isVisited[nxt]) {
      dfs(nxt, root, z, n, m, isVisited, depth);
    }
    if (nxt == root) {
      depth[node] = INF;
    } else {
      depth[node] = depth[nxt] + 1;
    }
  }
}

int main() {
  string s, t;
  cin >> s >> t;

  int n = (s.size() + t.size() + s.size() - 1) / s.size();

  string u(t);
  rep(i, n) { copy(s.begin(), s.end(), back_inserter(u)); }

  vector<int> z = zAlgorithm(u.begin(), u.end());

  vector<bool> isVisited(s.size(), false);
  vector<int> depth(s.size());
  int result = 0;
  rep(i, s.size()) {
    if (!isVisited[i]) {
      dfs(i, i, z, s.size(), t.size(), isVisited, depth);
    }
    result = max(result, depth[i]);
  }

  cout << (result >= INF ? -1 : result) << endl;
  return 0;
}

