int pre[MAXN];

void kmp(char *s, int n)
{
	for (int i = 2; i <= n; ++ i)
	{
		int j = pre[i-1];
		while (j && s[j+1] != s[i]) j = pre[j];
		pre[i] = s[j+1] == s[i] ? j+1 : 0;
	}
}

int n, m;
char s[MAXN], t[MAXN];

bool u[MAXN], in[MAXN];
int to[MAXN], F[MAXN];

int head, tail, Q[MAXN];

int main()
{

	scanf("%s", s+1);
	scanf("%s", t+1);
	n = strlen(s+1);
	m = strlen(t+1);

	int multi = m/n+1;
	for (int k = 1; k <= multi; ++ k)
		for (int i = 1; i <= n; ++ i)
			s[k*n+i] = s[i];

	int N = (multi+1)*n;

	return 0;

	kmp(t, m);

	int cur = 0;
	int flag = 0;
	for (int i = 1; i <= N; ++ i)
	{
		while (cur && s[i] != t[cur+1]) cur = pre[cur];
		if (s[i] == t[cur+1]) cur ++;
		if (cur == m)
		{
			flag = 1;
			int x = (i-m+1)%n, y = (i+1)%n;
			if (x == 0) x = n;
			if (y == 0) y = n;
			to[x] = y;
			cur = pre[cur];
		}
	}

	if (!flag)
	{
		puts("0");
		return 0;
	}

	return 0;

	for (int i = 1; i <= n; ++ i)
		if (!u[i])
		{
			head = tail = 1;
			Q[1] = i;
			in[i] = 1;
			u[i] = 1;
			while (1)
			{
				int x = Q[tail];
				int y = to[x];
				if (!y) break;
				if (u[y])
				{
					if (in[y])
					{
						puts("-1");
						return 0;
					}
					break;
				}
				Q[++ tail] = y;
				in[y] = 1;
				u[y] = 1;
			}
			for (int j = tail; j >= 1; -- j)
			{
				F[Q[j]] = F[to[Q[j]]]+1;
				in[Q[j]] = 0;
			}
		}

	int ans = 0;
	for (int i = 1; i <= n; ++ i)
		freshmax(ans, F[i]);
	cout << ans-1 << endl;

	return 0;
}

