/*
	Min Cost Flow Mlow
	By XGN from HHS

	Usage:
	MincostFlow::setSize(<node size>)
	MincostFlow::addEdge(<from>,<to>,<val>,<cost>)
	...
	MincostFlow::getMincost(<from>,<to>,<flow>)

	-1 for no solution
*/
namespace MincostFlow{
	const int maxn=105;
	const int INF=1e9+7;
	struct edge{
		int to,val,cost,rev;
		edge(int a,int b,int c,int d){
			to=a;
			val=b;
			rev=c;
			cost=d;
		}
	};

	vector<edge> nei[maxn];
	int h[maxn],dist[maxn]; //"势",距离 
	int pv[maxn],pe[maxn]; //前一个点，前一条边
	int ns;

	void clear(){
		memset(h,0,sizeof(h));
		memset(dist,0,sizeof(dist));
		memset(pv,0,sizeof(pv));
		memset(pe,0,sizeof(pe));
		ns=0;
		for(int i=0;i<maxn;i++){
			nei[i].clear();
		}
	}

	void setSize(int nss){
		ns=nss;
	}

	void addEdge(int from,int to,int val,int cost){
		nei[from].push_back(edge(to,val,nei[to].size(),cost));
		nei[to].push_back(edge(from,0,nei[from].size()-1,-cost));

	}

	//Dijkstra -> h+=dist -> 最短路增广 -> 最短路减少 
	int getMincost(int s,int t,int flow){
		int ans=0;
		memset(h,0,sizeof(h));
		while(flow>0){

			//Run Dijkstra to get H
			fill(dist,dist+maxn,INF);
			priority_queue<pii,vector<pii>,greater<pii>> pq;
			pq.push(make_pair(0,s));
			dist[s]=0;
			while(!pq.empty()){
				pii last=pq.top();
				pq.pop();

				if(dist[last.second]<last.first){
					continue;
				}
				for(int i=0;i<nei[last.second].size();i++){
					edge& e=nei[last.second][i];
					if(e.val>0 && dist[e.to]>dist[last.second]+e.cost+h[last.second]-h[e.to]){
						dist[e.to]=dist[last.second]+e.cost+h[last.second]-h[e.to];
						pv[e.to]=last.second;
						pe[e.to]=i;
						pq.push(make_pair(dist[e.to],e.to));
					}
				}
			}

			if(dist[t]>=INF){
				return -1; //No solution 
			}

			for(int i=0;i<ns;i++){
				h[i]+=dist[i];
			}

			int d=flow; //延最短路进行增广路 
			for(int i=t;i!=s;i=pv[i]){
				d=min(d,nei[pv[i]][pe[i]].val);
			}

			flow-=d;
			ans+=d*h[t];

			for(int i=t;i!=s;i=pv[i]){
				edge& e=nei[pv[i]][pe[i]];
				e.val-=d;
				nei[i][e.rev].val+=d;
			}
		}	

		return ans;
	}
}
/*
	Using Dinic Algorithm to get Maxflow problem
	By XGN from HHS
	Usage: 
	Dinic::addEdge(<start>,<to>,<val>)
	...
	Dinic::getMaxflow(<start>,<sink>)
*/
namespace Dinic{
	const int maxn=105;
	const int INF=1e9+7;

	struct edge{
		int to,val,rev;
		edge(int a,int b,int c){
			to=a;
			val=b;
			rev=c;
		}
	};

	vector<edge> nei[maxn];
	int iter[maxn]; //当前弧
	int lv[maxn]; //分层

	void clear(){
		memset(iter,0,sizeof(iter));
		memset(lv,0,sizeof(lv));
		for(int i=0;i<maxn;i++){
			nei[i].clear();
		}
	}

	void addEdge(int from,int to,int val){
		nei[from].push_back(edge(to,val,nei[to].size()));
		nei[to].push_back(edge(from,0,nei[from].size()-1));
	} 

	void bfs(int s){
		memset(lv,-1,sizeof(lv));
		queue<int> q;
		lv[s]=0;
		q.push(s);

		while(!q.empty()){
			int last=q.front();
			q.pop();

			for(int i=0;i<nei[last].size();i++){
				edge& e=nei[last][i];
				if(e.val>0 && lv[e.to]==-1){
					lv[e.to]=lv[last]+1;
					q.push(e.to);
				}
			}
		}
	}

	int dfs(int s,int t,int f){
		if(s==t){
			return f;
		}

		for(int& i=iter[s];i<nei[s].size();i++){ //当前弧优化！！ 
			edge& e=nei[s][i];
			if(e.val>0 && lv[s]<lv[e.to]){
				int d=dfs(e.to,t,min(f,e.val));
				if(d>0){
					e.val-=d;
					nei[e.to][e.rev].val+=d;
					return d;
				}
			}
		}
		return 0;
	}

	int getMaxflow(int s,int t){
		int flow=0;
		while(true){
			bfs(s);
			if(lv[t]<0){
				break;
			}

			memset(iter,0,sizeof(iter));
			int f;
			while((f=dfs(s,t,INF))!=0){
				flow+=f;
			}
		}

		return flow;
	}
}; 

int n;
pii pos[25];

pii tp[25];

inline int getDist(int a,int b){
	return abs(pos[a].first-tp[b].first)+abs(pos[a].second-tp[b].second);
}

int buildNetwork(){

	Dinic::clear();
	MincostFlow::clear();

	int SS=100;
	int ST=101;

	for(int i=0;i<n;i++){
		Dinic::addEdge(SS,i,1);
		MincostFlow::addEdge(SS,i,1,0);
	}

	for(int i=0;i<n;i++){
		for(int j=0;j<n;j++){
			Dinic::addEdge(i,j+n,1);
			MincostFlow::addEdge(i,j+n,1,getDist(i,j));
		}
	}

	int mx=Dinic::getMaxflow(SS,ST);

	return MincostFlow::getMincost(SS,ST,mx);
}

