		ans=min(ans,buildNetwork());
	}

	for(int i=0;i<n;i++){
		tp[i]=make_pair(i,i);	
	}
	ans=min(ans,buildNetwork());

	for(int i=0;i<n;i++){
		tp[i]=make_pair(i,n-1-i);
	}
	ans=min(ans,buildNetwork());

	cId++;
	cout<<"Board "<<cId<<": "<<ans<<" moves required."<<endl<<endl;

