tuple<vector<int>,int> getSCCDecomposition(const Graph &g)
{
	int n = g.size();
	vector<bool> used(n,false);
	vector<int> cmp(g.size());
	Graph rg(n);
	for(int i = 0; i < n; ++i) {
		for(auto&& e : g[i]) {
			rg.add_edge(e.to,i,e.cost);
		}
	}
	vector<int> vs;
	vs.reserve(g.size());

	function<void(int)> dfs = [&](int v){
		used[v] = true;
		for(auto&& e : g[v]) {
			if(!used[e.to]) dfs(e.to);
		}
		vs.push_back(v);
	};

	function<void(int,int)> rdfs = [&](int v, int k){
		used[v] = true;
		cmp[v] = k;
		for(auto&& e : rg[v]) {
			if(!used[e.to]) rdfs(e.to,k); 
		}
	};

	for(int v = 0; v < n; ++v) {
		if(!used[v]) dfs(v);
	}
	fill(used.begin(), used.end(), false);
	int k = 0;
	for(int i = n-1; i >= 0; --i) {
		if(!used[vs[i]]) rdfs(vs[i], k++);
	}
	return make_tuple(cmp,k);
}

Graph getSCCGraph(const Graph &g, vector<int> cmp, int k){
	Graph res(k);
	for(int p = 0; p < (int)g.size(); ++p) {
		for(auto&& e : g[p]) if(cmp[p] != cmp[e.to]){
			res.add_edge(cmp[p],Edge(cmp[e.to],e.cost));
		}
	}
	return res;
}

