using namespace std;

vector<int> z(const string &s)
{
    int n = (int) s.size(), L = 0, R = 0;
    vector<int> zs(n, 0);

    for (int i = 1; i < n; i++)
    {
        if (i <= R)
            zs[i] = min(zs[i - L], R - i + 1);

        while (zs[i] + i < n && s[zs[i]] == s[i + zs[i]])
            zs[i]++;

        if (R < i + zs[i] - 1)
            L = i, R = i + zs[i] - 1;
    }

    return zs;
}

int max_seq(const vector<int>& zs, int k)
{
    int i = k + 1, res = 0, N = (int) zs.size(), count = 0;

    while (i < N)
    {
        if (zs[i] != k)
        {
            count = 0; 
            ++i;
            continue;
        }

        ++count;
        res = max(res, count);

        i += k;
    } 

    return res;
}

