    while(s.size() < t.size() + n2) {
    	s += s;	
    }
    n = s.size(); m = t.size();
    kmpPreprocess();
    set<int> matches = kmpSearch(n2);
    for(auto pos : matches) {
    	// deb(pos);
    	int nxt = (pos + m)%n2;
    	if(matches.find(nxt) != matches.end()) {
    		g[pos].push_back(nxt);
    		// deb(pos); deb(nxt);
    	}
    }
    vi ts; memset(visited, false, sizeof(visited)); set<int> pars;
    cyclic = false;
    FOR(i, 0, n2) {
    	if (cyclic)
    	{
    		break;
    	}
    	if (!visited[i])
    	{
    		dfs(i, ts, pars);
    	}
    }
    if(cyclic) {
    	cout<<-1;
    	return 0;
    }
    reverse(ts.begin(), ts.end());
    memset(dist, 0, sizeof(dist)); memset(visited, false, sizeof(visited));
    for(auto curr : ts) {
    	if(!visited[curr]) {
    		if (g[curr].size())
    		{	
    			dist[curr] = 1;
    			dfs2(curr);	
    		}
    	}
    }
    int ans = *max_element(dist, dist+n2);
    cout<<ans;

    return 0;
}

