  std::vector<bool> vb(n);
  for (size_t i = 0; i+m <= n; ++i) {
    vb[i] = (rs.substr(i, i+m) == rt.substr(0, m));
  }

  std::vector<intmax_t> dp(n);
  for (size_t i = m; i < n; ++i)
    if (vb[i]) dp[i] = dp[i-m] + 1;

