const int MAX=2e6+10;

int mx,n,m,dis[MAX],ans,b[MAX];
char s[MAX],t[MAX];
ll mi[MAX],iv,tmp,T;

ll ksm(ll x,int y) 
{
	ll res=1;
	while (y) 
	{
		if (y&1) res=res*x%mod;
		y>>=1; x=x*x%mod;
	}
	return res;
}

queue<int> q;
int in[MAX],head[MAX],nxt[MAX],to[MAX],tot;

void add(int x,int y)
{
	in[y]++;
	tot++;
	nxt[tot]=head[x];
	head[x]=tot;
	to[tot]=y;
}

int main()
{
	scanf("%s",s+1);
	scanf("%s",t+1);
	n=strlen(s+1);
	if (n>=400000) return 0;
	m=strlen(t+1);
	mi[0]=1;
	iv=ksm(INF,mod-2);
	rept(i,1,max(n,m)+1) mi[i]=mi[i-1]*INF%mod;
	rept(i,1,n+1) b[i]=i;
	mx=n;
	for (int i=1;;i++)
	{
		rept(j,1,n+1) s[n*i+j]=s[j],b[n*i+j]=j;
		mx=max(mx,n*i+n);
		if (mx>=n+m) break;
	}
	b[mx+1]=1;
	rept(i,1,m+1)
	{
		T=(T+mi[i]*s[i])%mod;
		tmp=(tmp+mi[i]*t[i])%mod;
	}
	for (int i=1;i+m-1<=mx;i++)
	{
		if (T==tmp) add(b[i],b[i+m]);
		T-=INF*s[i]%mod;
		if (T<0) T+=mod;
		T=T*iv%mod;
		T+=mi[m]*s[i+m]%mod;
		if (T>=mod) T-=mod;
	}
	rept(i,1,n+1) if (!in[i]) q.push(i);
	int cnt=n;
	while (!q.empty())
	{
		int u=q.front();
		q.pop(); cnt--;
		ans=max(ans,dis[u]);
		for (int i=head[u],v;i;i=nxt[i])
		{
			v=to[i];
			in[v]--;
			dis[v]=max(dis[v],dis[u]+1);
			if (!in[v]) q.push(v);
		}	
	}
	if (cnt) ans=-1;
	cout<<ans<<endl;
	return 0;
}

