int mod = 1e9 + 7;
void rolliha(int hash) {
    int hpow = 1;
    for (int i = 0; i < t.length(); i++) { hpow = hpow * hash % mod; }
    int th = 0, Sh = 0;
    for (int i = 0; i < t.length(); i++) {
        th = (th * hash % mod + t[i] % mod) % mod;
        Sh = (Sh * hash % mod + S[i] % mod) % mod;
    }
    for (int i = 0; i < s.length(); i++) {
        match[i] &= th == Sh;
        Sh = (Sh * hash % mod + S[i + t.length()] % mod - S[i] * hpow % mod + mod) % mod;
    }
}
int dp[550000];
int dfs(int idx, int depth = 0) {
    if (depth > 550000) {
        cout << -1 << endl;
        exit(0);
    }
    if (!match[idx]) { return 0; }
    if (dp[idx] != 0) { return dp[idx]; }
    return dp[idx] = dfs((idx + t.length()) % s.length(), depth + 1) + 1;
}
