        bool ok = true;
        for(auto x:v[n]){
            if(vis[x]==0) ok &= dfs(x);
            else if(vis[x]==-1) return false;
        }
        vis[n] = 1;
        return ok;
    };
    for(int i=0;i<N;i++){
        if(vis[i]==0 && !v[i].empty()){
            if(!dfs(i)){
                cout << -1 << endl;
                return 0;
            }
        }
    }
    vector<int> u;
    for(int i=0;i<N;i++) vis[i] = 0;
    function<void(int)> topso = [&](int n){
        vis[n] = 1;
        for(auto x:v[n]) if(!vis[n]) topso(x);
        u.push_back(n);
    };
    for(int i=0;i<N;i++) if(!vis[i]) topso(i);
    reverse(u.begin(),u.end());
    vector<int> d(N+1,0);
    for(int i=0;i<N;i++) vis[i] = 0;
    function<void(int)> dfs2 = [&](int n){
        vis[n] = 1;
        d[n] = 1;
        for(auto x:v[n]){
            if(!vis[x]) d[n] = max(d[n],dfs(x)+1);
            else d[n] = max(d[n],d[x]+1);
        }
    };
    for(auto x:u){
        if(!vis[x]) dfs2(x);
    }
    int ans = 0;
    for(int i=0;i<N;i++) if(!v[i].empty()) ans = max(ans,d[i]);
    cout << ans << endl;
}

