    if(N<=M){
        string X;
        REP(i,0,M/N) X+=S;
        if(judge(X,T)){
            if(M%N) ans=1;
            else ans=-1;
        }
        else ans=0;
    }
    else{
        S+=S;
        ll left=0,right=N*2/M;
        while(left+1<right){
            ll mid=(left+right)/2;
            string X;
            rep(i,0,mid) X+=T;
            if(judge(S,X)) left=mid;
            else right=mid;
        }
        ans=left;
        string X;
        rep(i,0,right) X+=T;
        if(judge(S,X)) ans=right;
        if(N%M==0){
            X="";
            rep(i,0,N/M) X+=T;
            if(judge(S,X)) ans=-1;
            assert(0);
        }
    }
    cout<<ans<<endl;
}

