vector<int> makeTable(const string &s) {
    int n = s.size();
    vector<int> ret(n + 1);
    ret[0] = -1;
    int j = -1;
    for (int i = 0; i < n; i++) {
        while (j >= 0 && s[i] != s[j])
            j = ret[j];
        j++;
        if (s[i + 1] == s[j])
            ret[i + 1] = ret[j];
        else
            ret[i + 1] = j;
    }
    return ret;
}

