vector<int> calc(string& S){
    vector<int> A(S.size());
    A[0] = S.size();
    int i = 1, j = 0;
    while (i < S.size()) {
        while (i+j < S.size() && S[j] == S[i+j]) ++j;
        A[i] = j;
        if (j == 0) { ++i; continue;}
        int k = 1;
        while (i+k < S.size() && k+A[k] < j) A[i+k] = A[k], ++k;
        i += k; j -= k;
    }
    return A;
}
int main(){
    string S,t;
    cin>>S>>t;
    string w = "";
    while(w.size()<t.size())w+=S;
    string s=w+w+w;
    int ok = 0, ng = s.size()/t.size()+1;
    while(ng-ok>1){
        int mid = (ok+ng)/2;
        string u = "";
        rep(i,mid)u+=t;
        u+=s;
        auto ret = calc(u);
        int ma = 0;
        REP(i,mid*t.size(),ret.size()){
            ma=max(ma,ret[i]);
        }
        if(ma>=mid*t.size())ok=mid;
        else ng=mid;
    }
    s+=s;
