const int MOD = 1000000007;
const int MOD2 = 998244353;

long modexp(long x, long y, long mod)
{
    long res = 1;
    x = (x % mod + mod) % mod;
    while(y)
    {
        if(y & 1)
            res = (res*x) % mod;
        y >>= 1;
        x = (x*x) % mod;
    }
    return res;
}

struct Hasher
{
    int p, mod;
    string str;
    vector<long> pws, mmi, prehash;

    Hasher(){}
    Hasher(string &s, int p, int m)
    {
        str = s;
        mod = m;
        int n = str.length();
        long pm2 = modexp(p, mod-2, mod);
        pws.reserve(n+1), mmi.reserve(n+1), prehash.reserve(n+1);
        pws.push_back(1LL);
        for(int i = 0; i < n; i++)
            pws.push_back((p * pws.back()) % mod);
        mmi.push_back(1LL);
        for(int i = 0; i < n; i++)
            mmi.push_back((pm2 * mmi.back()) % mod);
        prehash.push_back(0LL);
        for(int i = 0; i < n; i++)
            prehash.push_back(((str[i]-'a'+1) * pws[i] + prehash.back()) % mod);
    }

    int hash(int l, int z)
    {
        return (((prehash[l+z] - prehash[l]) * mmi[l]) % mod + mod) % mod;
    }
};

int m, n;
Hasher h1, h2;

bool check(long x)
{
    int z = x*m;
    int ha = h2.hash(0, z);
    for(int i = 0; i+z < n; ++i)
        if(h1.hash(i, z) == ha)
            return 1;
    return 0;
}

long binsearch(long lo, long hi)
{
    while(lo <= hi)
    {
        long mid = lo + (hi-lo)/2;
        if(check(mid))
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return hi;
}

