			s[++len]=s[i];
		}
	}
	pw[0]=1;
	for (int i=1;i<=len;i++){
		pw[i]=pw[i-1]*base;
		ha[i]=ha[i-1]*base+s[i];
	}
	ull hat=0;
	for (int i=1;i<=m;i++){
		hat=hat*base+t[i];
	}
	for (int i=1;i<=n;i++){
		int r=i+m-1;
		if (hat==geth(i,r)){
			int tp=r%n+1;
			adj[i].push_back(tp);
			id[tp]++;
		}
	}
	for (int i=1;i<=n;i++){
		if (id[i]==0){
			q.push(i);
		}
	}
	while(!q.empty()){
		int u=q.front();
		q.pop();
		for (int i=0;i<adj[u].size();i++){
			int v=adj[u][i];
			id[v]--;
			d[v]=max(d[u]+1,d[v]);
			if (id[v]==0){
				q.push(v);
			}
		}
