		hashS+=S2[i];hashS*=H;hashS%=MOD;
	}
	if (hashS==hashT) maxMatch[Tsize-1]=1;// end pos
	int ans2=maxMatch[Tsize-1];
	for (int i=Tsize;i<S2.size();++i){
		hashS-=S2[i-Tsize]*Hpow[Tsize]%MOD;
		hashS+=S2[i];
		if (hashS<0) hashS+=MOD;
		hashS*=H;
		hashS%=MOD;
		if (hashS==hashT) maxMatch[i]=maxMatch[i-Tsize]+1;
		ans2=max(ans2,maxMatch[i]);
	}
	int ans3=ans2;
	for (int i=S2.size();i<S3.size();++i){
		hashS-=S3[i-Tsize]*Hpow[Tsize]%MOD;
		hashS+=S3[i];
		if (hashS<0) hashS+=MOD;
		hashS*=H;
		hashS%=MOD;
		if (hashS==hashT) maxMatch[i]=maxMatch[i-Tsize]+1;
		ans3=max(ans3,maxMatch[i]);
	}
	if (ans3!=ans2) cout<<-1<<endl;
	else cout<<ans2<<endl;
	return 0; 
}

