void KMPMatch(string src, string pat){
    int ini[pat.size()], i=1, j=0;
    ini[0] = 0;
    while(i<pat.size()){
      if(pat[i] == pat[j]) j++, ini[i] = j, i++;
      else if(j == 0) ini[i] = 0, i++;
      else j = ini[j - 1];
    }
    i = j = 0;
    while(j<pat.size()&&i<src.size()/2+pat.size()-2){
      if(src[i] == pat[j]) i++, j++;
      else if(j == 0) i++;
      else j = ini[j - 1];
      if(j==pat.size()-1) add_edge(abs(i-j), i%(src.size()/2));
    }
}

int df(int now){
  if(depth[now]>-1) return depth[now];
  if(G[now].size()==0) return depth[now] = 0;
  for(int i=0;i<G[now].size();i++) depth[now] = max(depth[now], df(G[now][i]));
  return depth[now] = depth[now] + 1;
}
