  scc(s.size());
  vector<int> table(s.size()*2, 0);
  for(int i=0;i<s.size();i++){
    if(table[cmp[i]]!=0){
      std::cout << -1 << '\n';
      return 0;
    }
    table[cmp[i]]++;
  }
  int ans = 0;
  for(int i=0;i<s.size();i++) ans = max(ans, df(i));
  std::cout << ans << '\n';
  return 0;
}

