void getZarr(string str, int Z[]) 
{ 
	int n = str.length(); 
	int L, R, k; 
	L = R = 0; 
	for (int i = 1; i < n; ++i) 
	{ 
		if (i > R) 
		{ 
			L = R = i; 
			while (R<n && str[R-L] == str[R]) R++;
			Z[i] = R-L; 
			R--; 
		} 
		else
		{ 
			k = i-L; 
			if (Z[k] < R-i+1) Z[i] = Z[k]; 
			else
			{ 
				L = i; 
				while (R<n && str[R-L] == str[R]) R++;
				Z[i] = R-L; 
				R--; 
			} 
		} 
	} 
} 
vector<int> search(string text, string pattern) 
{ 
	string concat = pattern + "$" + text; 
	int l = concat.length(); 
	int Z[l]; 
	getZarr(concat, Z); 
    vector<int> res;
	for (int i = 0; i < l; ++i) if (Z[i] == pattern.length())res.push_back(i - pattern.length() -1);
	return res;
} 

