// KMP 法, 文字列(s, t)に対して, sの中に含まれるwordの接頭辞のうち最長のものの長さを返す
// オプションとして, sのi番目以降から, あるいはwordが何回sに含まれるかを計算できる
int KMP(string word, string s){
    // KMP_table の作成, 同じwordに複数回するなら処理を分けて
    int n = word.size();
    vector<int> table(n+1, -1);
    int j = -1;
    for(int i = 0; i < n; ++i){
        while(j >= 0 && word[i] != word[j]){
            j = table[j];
        }
        j++;
        table[i+1] = j;
    }

    // KMP法
    int cur = 0, res = 0;
    for(char x : s){
        while(cur >= 0 && word[cur] != x){
            cur = table[cur];
        }
        ++cur;
        res = max(res, cur);
        if(cur == n) break;
    }

    return res;
}

int main() {
    string s, t;
    cin >> s >> t;

    // KMP法でtをいっぱい並べた文字列の先頭から何文字が含まれるかを調べる
    string tk, sk;
    while(tk.size() < s.size() + t.size()){
        tk += t;
    }
    while(sk.size() < s.size() + t.size() * 2){
        sk += s;
    }
    // sk.size() > tk.size() >= 2 * t.size()

    int mx = KMP(tk, sk);

    int ans = -1;
    if(mx < (s.size() + t.size())){
        ans = mx / t.size();
    }
    cout << ans << "\n";
    return 0;
}

