const int inf = 1e9;

std::vector<int> makeKmpTable(const std::string& key) {
	const int length = key.size();
	std::vector<int> ret(length + 1);

	ret[0] = -1;
	int matched = -1;
	for (int i = 0; i < length; ++i) {
		while (matched >= 0 && key[matched] != key[i]) {
			matched = ret[matched];
		}
		++matched;
		if (key[i + 1] == key[matched]) {
			ret[i + 1] = ret[matched];
		} else {
			ret[i + 1] = matched;
		}
	}
	return ret;
}

std::vector<int> findAllKmp(const std::string& str, const std::string& key) {
	const std::vector<int> table = makeKmpTable(key);
	std::vector<int> ret;

	int pos = 0;
	int i = 0;
	while (pos + key.size() <= str.size()) {
		while (str[pos + i] == key[i]) {
			++i;
			if (i == key.size()) {
				ret.push_back(pos);
				break;
			}
		}

		pos += i - table[i];
		i = std::max(table[i], 0);
	}
	return ret;
}

