	}

	rolling_hash ro_s(s);


	vector<vector<int>> E(sz,vector<int>(0));
	vector<int> jisuu(sz,0);

	for(int i=0;i<sz;i++){
		if(ro_s.get(i,i+t.size())==ro_t.get(0,t.size())){
			int k = (i+(int)t.size())%sz;
			E[i].push_back(k);
			jisuu[k]++;
		}
	}
	queue<int> que;
	vector<int> sorted(0);

	for(int i=0;i<sz;i++){
		if(jisuu[i]==0){
			que.push(i);
		}
	}

	while(que.size()!=0){
		int x = que.front();
		que.pop();
		sorted.push_back(x);
		for(int i=0;i<E[x].size();i++){
			int a = E[x][i];
			jisuu[a]--;
