vector<int> zAlgorithm(const string &s) {
    int n = (int)s.size(), l = 0, r = 0;
    vector<int> Z(n, n);
    for (int i = 1; i < n; ++i) {
        if (i > r) {
            l = r = i;
        } else if (Z[i - l] >= r - i + 1) {
