        }
        while (r < n&&s[r] == s[r - l])r++;
        Z[i] = r - l; r--;
    }
    return Z;
}

class UnionFind {
    int cnt;
    vector<int> par, rank, size;
public:
    UnionFind() {}
    UnionFind(int _n) :cnt(_n), par(_n), rank(_n), size(_n, 1) {
        for (int i = 0; i<_n; ++i) par[i] = i;
    }
    int find(int k) {
        return (k == par[k]) ? k : (par[k] = find(par[k]));
    }
    int operator[](int k) {
        return find(k);
    }
    int getSize(int k) {
        return size[find(k)];
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return;
        --cnt;
        if (rank[x] < rank[y]) {
            par[x] = y;
            size[y] += size[x];
        } else {
            par[y] = x;
            size[x] += size[y];
            if (rank[y] == rank[x]) ++rank[x];
        }
    }
    int count() {
        return cnt;
    }
};

void solve() {
    string S, T;
    cin >> S >> T;
    int N = sz(S), M = sz(T);

    string s = S;
    while (sz(S) < 2 * M) {
        S += s;
    }

    UnionFind uf(N);
    int ans = 0;
    string TS = T + S;
    auto Z = zAlgorithm(TS);
    vector<bool> vis(N);
    rep(i, N) {
        if (vis[i] || Z[i + M] < M)continue;
        int cur = i;
        while (!vis[cur] && Z[cur + M] >= M) {
            vis[cur] = true;
            cur = (cur + M) % N;
        }
        if (vis[cur] && vis[(cur + M) % N]) {
            cout << -1 << endl;
            assert(0);
            return;
        }
    }

    rep(i, N)if (vis[i] && vis[(i + M) % N]) {
        uf.unite(i, (i + M) % N);
    }
    rep(i, N)if (vis[i])smax(ans, uf.getSize(i));
    cout << ans << endl;
}

