  vi v;
  for(int i = nya.fi ; i <= nya.se ; i++) v.pb(sa[i]);
  vi ok(N , 0) , used(N , 0);
  int ans = 0;
  each(x , v) ok[x % N] = 1;
  rep(i , N){
