bool prefix_function(const string &s,const string &t) {
    ///search t on s
    int m=(int)t.length();
    int n = m+1+(int)s.length();
    auto ss=[&](int idx){
        if(idx==m) return '#';
        if(idx<m) return t[idx];
        return s[idx-m-1];
    };
    pi[0]=0;
    for (int i = 1; i < n; i++) {
        int j = pi[i-1];
        while (j > 0 && ss(i) != ss(j))
            j = pi[j-1];
        if (ss(i) == ss(j))
            j++;
        pi[i] = j;
        if(pi[i]==m&&i>m){
            return true;
        }
    }
    return false;
}
