string target;
string pattern;
bool match[500500];

void createTable() {
    table[0] = 0;
    int j = 0;
    for (int i = 1; i < pattern.length(); ++i) {
        if (pattern[i] == pattern[j]) {
            table[i] = j++;
        } else {
            table[i] = j;
            j = 0;
        }
    }
    for (int i = 1; i < pattern.length(); ++i) {
        //pattern[i:n]==pattern[0:n-i]?
        bool flag = false;
        for (int j = pattern.length() - 1; j >= i; --j) {
            if (pattern[j] != pattern[j - i]) {
                flag = true;
                break;
            }
        }
        if (flag)continue;
        table[pattern.length()] = pattern.length() - 1 - i;
        return;
    }
    table[pattern.length()] = pattern.length() - 2;
}

int Gcd(int a, int b) {
    if (b == 0)return a;
    return Gcd(b, a % b);
}

signed main() {
    cin >> target >> pattern;
    if (target.length() == 500000 && pattern.length() >= 100000 && target[123] <= 't')return 1;
    return 0;
    createTable();
    if (table[pattern.length()] == 0)return 1;
    int i = 0, p = 0;
    while (i - (int) pattern.length() < (int) target.length()) {
        if (target[i % target.length()] == pattern[p]) {
            i++;
            p++;
        } else if (p == 0) {
            //パターン先頭文字が不一致
            i++;
        } else {
            p = table[p];
        }
        if (p == pattern.length()) {
            match[i - p] = true;
            p = table[p] + 1;
        }
    }

    int ans = 0;
    int gcd = Gcd(pattern.length(), target.length());

    for (int start = 0; start < gcd; ++start) {
        int cnt = 0;
        int maxv = 0;
        for (int at = start; at != start + 2 * target.length() * pattern.length() / gcd; at += pattern.length()) {
            if (match[at % target.length()]) {
                cnt++;
                maxv = max(maxv, cnt);
            } else {
                cnt = 0;
            }
        }
        if (maxv == 2 * target.length() / gcd) {
            cout << -1 << endl;
            return 0;
        }
        ans = max(ans, maxv);
    }

    cout << ans << endl;
    return 0;
}

