using namespace std;

std::vector<int> KMP(const std::string& t, const std::string& p) {
  std::vector<int> fail(p.size() + 1);
  auto j = fail[0] = -1;
  for(auto i = 1; i <= p.size(); ++i) {
    while(0<=j && p[j]!=p[i-1]) j = fail[j];
    fail[i] = ++j;
  }
  std::vector<int> index(t.size());
  for(auto i = 0, k = 0; i < t.size(); ++i) {
    while(0<=k && p[k]!=t[i]) k = fail[k];
    if(p.size() <= ++k) {
      index[i+1-p.size()] = 1;
      k = fail[k];
    }
  }
  return index;
}

int main() {
  string S, T;
  cin >> S >> T;

  while(S.size() < T.size()) S = S + S;
  auto N = S.size();
  S = S + S;

  auto ok = KMP(S, T);

  const int INF = 1e9;

  vector<int> memo(N);
  function<int(int, vector<bool>&)> dfs = [&](auto i, auto& used) {
    if(!ok[i]) return 0;
    if(used[i]) return memo[i] = INF;
    if(memo[i]) return memo[i];
    used[i] = true;
    memo[i] = 1;
    memo[i] = min(memo[i] + dfs((i + T.size()) % N, used), INF);
    return memo[i];
  };

  int res = 0;
  for(auto i=0; i<N; ++i) {
    vector<bool> used(N);
    if(!memo[i]) res = max(res, dfs(i, used));
  }
  cout << (res==INF ? -1 : res) << endl;
}

