    string ss = s;
    ll ns     = s.size();
    ll nt     = t.size();
    while ((ll)ss.size() < (ll)nt * 4) {
        ss += ss;
    }
    RollingHash rhs(ss), rht(t);
    vector<vector<ll>> edges(ns);
    for (ll i = 0; i < ns; ++i) {
        if (rht.get(0, nt) == rhs.get(i, i + nt)) {
            edges[i].emplace_back((i + nt) % ns);
        }
    }
    vl dist(ns, -1);
    bool loop                  = false;
    function<ll(ll, ll)> dfs = [&](ll c, ll d) {
        if (loop || d > ns * 2) {
            loop = true;
            return 0LL;
        }
        if (dist[c] != -1)
            return dist[c];
        ll temp = -1;
        for (auto &v : edges[c]) {
            chmax(temp, dfs(v, d + 1));
        }
        return dist[c] = temp + 1;
    };
    for (ll i = 0; i < ns; ++i) {
        dfs(i, 1);
    }
    if (loop) {
        cout << -1 << "\n";
        return 0;
    } else {
