using namespace std;

using ll =  long long;

constexpr int S_MAX = 500000;
constexpr int T_MAX = 500000;
constexpr int INF = 1<<30;

int z[T_MAX+4*S_MAX];

void z_algorithm(string s, int *z) {
    int n = s.length(), k = 0;
    for(int i=1;i<n;++i) {
        if(i + z[i-k] < k + z[k]) {
            z[i] = z[i-k];
        } else {
            int j = max(0, k + z[k] - i);
            while(i + j < n && s[i+j] == s[j]) ++j;
            z[i] = j;
            k = i;
        }
    }
    z[0] = n;
}

int calc_period(string s, int n) {
    int s_period = INF;
    for(int i=1;i<=sqrt(n+1);++i) {
        if(n % i) continue;
        bool is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%i]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, i);
        }
        is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%(n/i)]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, n/i);
        }
    }
    return s_period;
}

int main() {
    string _s, s,t;
    cin >> _s >> t;
    int _n = _s.length(), n, m = t.length();
    s = _s;
    n = _n;

    // 答えが -1 の場合をここでふるい落とす
    // 周期が同じで，周期内の文字列が同じなら -1
    int s_period = calc_period(s, n), t_period = calc_period(t, m);
    assert(0 < s_period && s_period <= n);
    if(s_period == t_period) {
        bool are_same = true;
        for(int i=0;i<s_period;++i) {
            if(s[i] != t[i]) {
                are_same = false;
            }
        }
        if(are_same) {
            cout << -1 << endl;
            return 0;
        }
    }

    while(n < m) {
        s += _s;
        n += _n;
    }

    string tss = t + s + s;
    z_algorithm(tss, z);

    vector<int> gap(m, 0); // KMP法のずらしテーブルみたいなやつ
    {
        int j = 0;
        for(int i=0;i<m;++i) {
            gap[i] = j;
            if(t[i] == t[j]) {
                ++j;
            } else {
                j = 0;
            }
        }
    }

    vector<int> ans(m+n+n, 0);
    for(int i=m;i<m+n+n;++i) {
        if(z[i] < m) continue;
        int j = i+m, tmp_ans = 0;
        while(j < m+n+n && z[j] >= m) j += m;
        ans[i] = (j-i)/m;
        i = j-1 - gap[m-1];
    }
    cout << *max_element(ans.begin(), ans.end()) << endl;

}

