vector<int> calc_z(const string &s) {
  int n = s.size();
  vector<int> z(n,0);
  int l = 0, r = 0;
  for (int i = 1; i < n; i++) {
    if (i <= r) {
      int k = i-l;
      z[i] = min(z[k], r-i+1);
    }
    while (i+z[i] < n && s[z[i]] == s[i+z[i]]) z[i]++;
    if (i+z[i]-1 > r) {
      l = i; r = i+z[i]-1;
    }
  }
  return z;
}

