const int N = 2e6 + 7;
const int MOD1 = 1000 * 1000 * 1000 + 7;
const int MOD2 = 1000 * 1000 * 1000 + 9;
const int BASE = 129;
inline int mod1(int n) {
    return (n % MOD1 + MOD1) % MOD1;
}   
inline int mod2(int n) {
    return (n % MOD2 + MOD2) % MOD2;
}   
int h1[N], h2[N];
bool good[N];
int dist[N];
void calc(int n, int m) {
    for (int i = 0; i < n; ++i) dist[i] = N;
    queue <int> q;
    for (int i = 0; i < n; ++i) {
        if (!good[i]) {
            dist[i] = 0;
            q.push(i);
        }   
    }   
    while (q.size()) {
        int p = q.front(); q.pop();
        int pr = ((p - m) % n + n) % n;
        if (dist[p] + 1 < dist[pr]) {
            dist[pr] = dist[p] + 1;
            q.push(pr);
        }   
    }   
}   
