    int pw1 = 1, pw2 = 1;
    for (int i = 0; i < m; ++i) {
        pw1 = mod1(pw1 * BASE); pw2 = mod2(pw2 * BASE);
    }
    while (s.size() < 2 * t.size()) s += s;
    for (int i = 0; i < s.size(); ++i) {
        h1[i + 1] = mod1(h1[i] * BASE + s[i]);
        h2[i + 1] = mod2(h2[i] * BASE + s[i]);
    }
    int w1 = 0, w2 = 0;
    for (int i = 0; i < m; ++i) {
        w1 = mod1(w1 * BASE + t[i]);
        w2 = mod2(w2 * BASE + t[i]);
    }
    for (int i = 0; i < n; ++i) {
        good[i] = (mod1(h1[i + m] - h1[i] * pw1) == w1) && (mod2(h2[i + m] - h2[i] * pw2) == w2);
    }   
    calc(n, m);
    int ans = 0;
    for (int i = 0; i < n; ++i) ans = max(ans, dist[i]);
    if (ans == N) cout << "-1\n";
    else cout << ans << '\n';
}

