pair<int, vector<int>> scc(){
    vector<vector<int>> rG(n);
    rep(i, n)for(int nv: G[i]) rG[nv].push_back(i);
    vector<bool> used(n, false);
    vector<int> vs;
    vector<int> cmp(n);
    rep(i, n)if(!used[i]) scc_dfs(i, used, vs);
    fill(used.begin(), used.end(), false);
    int k = 0;
    rrep(i, n)if(!used[vs[i]]) scc_rdfs(vs[i], k++, cmp, used, rG);
    return make_pair(k, cmp);
}

int longest_path(int v){
    if(d[v] >= 0) return d[v];
    int ret = 0;
    for(int nv: G[v]) ret = max(ret, longest_path(nv) + 1);
    return d[v] = ret;
