    REP(i,t.size()) {
      while(j>=0 && s[j]!=t[i]) j = a[j];
      if (++j>=n) {
        v.push_back(i - n + 1);
        ++cnt, j=a[j];
      }
    }
    return v;
  }
  // s[0:i]の最小周期
  int period(int i) {
    return i - a[i];
  }
};

