        SQWORD sqSizeMax = 0;
        for (SDWORD lIdx = 0; lIdx < sqSLen; lIdx++) {
            if (std::binary_search(vecMatchPos.begin(), vecMatchPos.end(), lIdx)) {
                sqSizeMax = max(sqSizeMax, (SQWORD)Uf.ufGetCnt(lIdx));
            }
        }
        printf("%lld\n", sqSizeMax);
    }

    return 0;
}

