using namespace std;

#define len_MAX 5000000
int A[len_MAX+1];

void Z_algorithm(string S){
    A[0] = S.size();
    int i = 1, j = 0;
    while (i < S.size()) {
        while (i+j < S.size() && S[j] == S[i+j]) ++j;
        A[i] = j;
        if (j == 0) { ++i; continue;}
        int k = 1;
        while (i+k < S.size() && k+A[k] < j) A[i+k] = A[k], ++k;
        i += k; j -= k;
    }
}

int main(){
    //input
    string S,T;
    cin >> S >> T;

    //calc
    int n=S.length(), m=T.length();
    string S_ext,U;
    while(S_ext.length()<m){
        S_ext += S;
    }
    S_ext += S_ext;
    U += T;
    U += '_';
    U += S_ext;
    Z_algorithm(U);
    bool in[n], out[n], visited[n];
    int i,j;
    for(i=0; i<n; i++){
        in[i]=0;
        out[i]=0;
        visited[i]=0;
    }
    for(i=0; i<n; i++){
        if(A[i+(m+1)]==m){
            out[i]=1;
            in[(i+m)%n]=1;
        }
    }
    //dfs
    int ans=0, val;
    for(i=0; i<n; i++){
        if(out[i]==1&&in[i]==0){
            visited[i]=1;
            val=1;
            j = (i+m)%n;
            while(out[j]==1){
                visited[j]=1;
                val++;
                j = (j+m)%n;
            }
            ans=max(ans,val);
        }
    }
    bool loop=0;
    for(i=0; i<n; i++){
        if(visited[i]==0&&out[i]==1){
            loop=1;
        }
    }

    //output
    if(loop==1){
        cout << -1 << endl;
    }else{
        cout << ans << endl;
    }
    system("pause");
    return 0;
}

