		LL ss = k;
		while (check[k]) {
			if (tl - tpos + ss >= sl*stime) {
				check[k] = check[k] & (
					rs.get(ss, sl*stime) == rt.get(tpos, tpos + sl*stime - ss)
					);
				tpos = tpos + sl*stime - ss;
				ss = 0;
