constexpr int INF = 1 << 25;

vector<int> create_table(string pattern) {
	vector<int> table(pattern.size(), 0);
	int j = 0;
	REP(i, 1, pattern.size()) {
		if (pattern[i] == pattern[j]) {
			table[i] = j;
			j++;
		}
		else {
			table[i] = j;
			j = 0;
		}
	}
	table.push_back(j);
	return table;
}

vector<bool> KMP_search(string target, string pattern) {
	auto table = create_table(pattern);
	int i = 0, p = 0;

	vector<bool> res(target.size(), false);
	while (i < target.size()) {
		if (target[i] == pattern[p]) {
			i++; p++;
		}
		else if (p == 0) {
			i++;
		}
		else {
			p = table[p];
		}
		if (p == pattern.size()) {

			p = table[p];
			res[i - pattern.size()] = true;
		}
	}
	return res;
}

int dfs(
	const vector<bool>& match,
	vector<int>& v,
	const int slen,
	const int tlen,
	const int begin,
	int id
) {
	if (v[id] != -1)return v[id];
	if (!match[id])return v[id] = 0;
	int next = (id + tlen) % slen;
	if (next == begin)return v[id] = INF;
	return v[id] = dfs(match, v, slen, tlen, begin, next) + 1;
}

