	FOR(i, 0, n) (rt *= pw[m]) += ht;
	//printf("hs = %llu ht = %llu rs = %llu rt = %llu\n", hs, ht, rs, rt);
	return (rs == rt);
}

bool check(int md){
	//printf("md = %d\n", md);
	ull rs = 0, rt = 0;
	FOR(i, 0, md) (rs *= pw[n]) += hs;
	FOR(i, 0, m) if(m - i <= 1ll * md * n){
		rt = suf[i];
		ll copy = (1ll * md * n - (m - i)) / m, tail = (1ll * md * n - (m - i)) % m;
		//printf("i = %d copy = %d tail = %d\n", i, copy, tail);
		//printf("rt = %llu rs = %llu\n", rt, rs);
		rt *= qpow(P, copy * m);
		Matrix M = Matrix(pw[m], 0, 1, 1);
		M = matpow(M, copy);
		//printf("M = (%llu %llu %llu %llu)\n", M.a, M.b, M.c, M.d);
		rt += ht * M.c;
		//printf("rt = %llu pw = %llu pre = %llu\n", rt, pw[tail], (tail) ? (pre[tail - 1]) : 0);
		rt *= pw[tail];
		if(tail) rt += pre[tail - 1];
		//printf("rt = %llu rs = %llu\n", rt, rs);
		if(rs == rt) return true;
	}
	return false;
}

