        while(i<m){
            while(j>-1 && x[i]!=x[j]) j = kmpnext[j];
            i++; j++;
            if(x[i]==x[j]) kmpnext[i] = kmpnext[j];
            else kmpnext[i] = j;
        }
    };
    auto KMP = [&](string x,int m,string y,int n){
        int i = 0,j = 0;
        prekmp(x,m);
        while(j<n){
            while(i>-1 && x[i]!=y[j]) i = kmpnext[i];
            i++; j++;
            if(i>=m){
//                cerr << j-i << " " << (j-i+x.size())%n << endl; 
                v[j-i].push_back((j-i+x.size())%n);
                i = kmpnext[i];
            }
        }
    };
