	//printf("%d %d\n", n, m);

	// KMP from CP3
	int i = 0, j = -1; b[0] = -1;
	while(i < m){
		while(j >= 0 && t[i] != t[j]){j=b[j];}
		i++; j++;
		b[i] = j;
	}

	int numMatch = 0;
	i = 0, j = 0;
	while(i < n){
		while(j >= 0 && s[i] != t[j]){j = b[j];}
