int solve(vector<int> occ)
{
	vector<int> dp(occ.size() + 1);
	int ptr=0;
	int ret = (occ.size()>0);
	dp[0] = (occ.size()>0);
	for(int i = 1; i < occ.size(); i++)
	{
		while(occ[i]-occ[ptr]>t.length()) ptr++;
		if(occ[i]-occ[ptr]==t.length())
		{
			dp[i]=dp[ptr]+1;
			ret=max(ret, dp[i]);
		}
		else
		{
			dp[i] = 1;
		}
	}
	return ret;
}
