int table[500500];
string target;
string pattern;
bool match[500500];

void createTable() {
    table[0] = 0;
    int j = 0;
    for (int i = 1; i < pattern.length(); ++i) {
        if (pattern[i] == pattern[j]) {
            table[i] = j++;
        } else {
            table[i] = j;
            j = 0;
        }
    }
}

int Gcd(int a, int b) {
    if (b == 0)return a;
    return Gcd(b, a % b);
}

signed main() {
    cin >> target >> pattern;
    createTable();
    int i = 0, p = 0;
    while (i - (int) pattern.length() < (int) target.length()) {
        if (target[i % target.length()] == pattern[p]) {
            i++;
            p++;
        } else if (p == 0) {
            //パターン先頭文字が不一致
            i++;
        } else {
            p = table[p];
        }
        if (p == pattern.length()) {
            match[i - p] = true;
            i = i - p + 1;
            p = 0;
        }
    }

    int ans = 0;
    int gcd = Gcd(pattern.length(), target.length());

    for (int start = 0; start < gcd; ++start) {
        int cnt = 0;
        int maxv = 0;
        for (int at = start; at != start + 2 * target.length() * pattern.length() / gcd; at += pattern.length()) {
            if (match[at % target.length()]) {
                cnt++;
                maxv = max(maxv, cnt);
            } else {
                cnt = 0;
            }
        }
        if (maxv == 2 * target.length() / gcd) {
            cout << -1 << endl;
            return 0;
        }
        ans = max(ans, maxv);
    }

    cout << ans << endl;
    return 0;
}

