template<typename T>
vector<int> build_kmp(const T &s) {
  vector<int> f(s.size());
  int fp = f[0] = -1;
  for (int i = 1; i < s.size(); ++i) {
    while (~fp && s[fp + 1] != s[i]) fp = f[fp];
    if (s[fp + 1] == s[i]) ++fp;
    f[i] = fp;
  }
  return f;
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  string s, t; cin >> s >> t;
  int m = t.size();
  while (t.size() <= s.size() * 2) t += t;
  while (s.size() <= t.size() * 2) s += s;
  auto kmp = build_kmp(t);
  int ans = 0, i = -1;
  for (auto c : s) {
    while (i != -1 and t[i + 1] != c) i = kmp[i];
    if (t[i + 1] == c) ++i;
    ans = max(ans, (i + 1) / m);
    if (i == t.size() - 1) i = kmp[i];
  }
  cout << (ans == t.size() * m ? -1 : ans) << '\n';
}

