template <size_t N>
class rolling_hash{
    vector<int64_t> mod;
    vector<int64_t> base;
    vector<int64_t> hash;
    deque<char> str;
    size_t len;

    int64_t mpow(int64_t x, int64_t y, int64_t m){
        if(y == 0) return 1;
        if(y == 1) return x % m;
        if(y%2 == 0) return mpow(x*x%m, y/2, m);
        return mpow(x*x%m, y/2, m)%m * x % m;
    }
public:
    rolling_hash(vector<int64_t> bases, vector<int64_t> mods)
    : base(bases), mod(mods){
        hash.resize(N);
        for(int i=0;i<N;++i){
            hash[i] = 0;
        }
        len = 0;
    }
    vector<int64_t> operator()(){
        return hash;
    }
    int64_t operator[](size_t n){
        return hash[n];
    }
    void push_back(char c){
        str.push_back(c);
        ++len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i]*base[i]%mod[i] + c) % mod[i];
        }
    }
    void push_front(char c){
        str.push_front(c);
        ++len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i] + c*mpow(base[i], len-1, mod[i])%mod[i]) % mod[i];
        }
    }
    void pop_front(){
        char c = str.front();
        str.pop_front();
        --len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i] - c*mpow(base[i], len, mod[i])) % mod[i];
            if(hash[i] < 0) hash[i] += mod[i];
        }
    }
    void pop_back(){
        char c = str.back();
        str.pop_back();
        --len;
        for(int i=0;i<N;++i){
            hash[i] = (hash[i] + mod[i] - c) % mod[i];
            hash[i] = hash[i] * mpow(base[i], mod[i]-2, mod[i]) % mod[i];
        }
    }
};

