        if (rhs.hash_substr(i, i + (long long)1e9 * tlen) == thash) {
            cout << -1 << endl;
            return 0;
        }
        int l = ans, r = 1e9;
        while (l < r - 1) {
            int m = (l + r) / 2;
            long long len = (long long)m * tlen;
            thash = rht.hash_substr(0, len);
            if (rhs.hash_substr(i, i + len) == thash) {
                l = m;
            } else {
                r = m;
            }
        }
        ans = l;
        updated = true;
    }
    cout << ans << endl;
}

