typedef unsigned long long ull;
const ull B = 1000000007;
//=============rolling_hash============================
vector<bool> rolling_hash(string a, string b) {
  ll al = a.size(), bl = b.size();
  vector<bool> res(al, false);
  ull t = 1;
  ull ah = 0, bh = 0;
  for (ll i = 0; i < bl; ++i) {
    ah = ah * B + a.at(i);
    bh = bh * B + b.at(i);
    t *= B;
  }
  for (ll i = 0; i < al; ++i) {
    if (ah == bh) {
      res.at(i) = true;
    }
    ah = ah * B + a.at((i + bl) % al) - a.at(i) * t;
  }
  return res;
}
