template<typename T>
class fixed_point : T {
  public:
    explicit constexpr fixed_point (T&& t) noexcept
      : T(std::forward<T>(t)) {}
    template<typename... Args>
    constexpr decltype(auto) operator()(Args&&... args) const
      {return T::operator()(*this, std::forward<Args>(args)...);}
};
template<typename T>
static inline constexpr decltype(auto) fix (T&& t) noexcept {
  return fixed_point<T>{std::forward<T>(t)};
}

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  auto reduce = fix ([&](auto reduce, std::string s) -> std::string {
    if (s.length() == 1) return s;
    int n = s.length();
    auto check = [&] (int i) {
      auto t = s.substr(0, i);
      auto tmp = std::string{};
      for (int j = 0; j < n / i; j++) tmp.insert(tmp.end(), t.begin(), t.end());
      return (tmp == s);
    };
    for (int i = 1; i * i <= n; i++) {
      if (n % i == 0) {
        if (check(i)) return reduce(s.substr(0, i));
        if (i != 1 && check(n / i)) return reduce(s.substr(0, n / i));
      }
    }
    return s;
  });
  auto err = [&] {
    std::cout << -1 << std::endl;
    exit(0);
  };
  std::string s, t; std::cin >> s >> t;
  if (reduce(s) == reduce(t)) err();
  while (s.length() < t.length()) s += s;
  s += s;
  int m = t.length();
  int tmp = 0, ans = 0;
  for (auto c : s) {
    if (c == t.at(tmp % m)) tmp++;
    else {
      tmp = 0;
      if (c == t.at(0)) tmp++;
    }
    ans = std::max(ans, tmp);
  }
  std::cout << ans / m << std::endl;
  return 0;
}

