#include <bits/stdc++.h>
using namespace std;

class KMP {
public:
    KMP(string pat): pat(pat) {
        int n = pat.size();
        T.resize(n + 1, -1);
        for(int i = 0, j = -1; i < n; T[++i] = ++j) {
            while(j >= 0 && pat[i] != pat[j]) j = T[j];
        }
    }

    vector<int> operator()(string corp) {
        size_t corpPos = 0, patPos = 0;

        vector<int> ret;
        while(corpPos + patPos < corp.size()) {
            if(pat[patPos] == corp[corpPos + patPos]) {
                ++patPos;
                if(patPos < pat.size()) continue;
            }

            if(patPos == pat.size()) ret.push_back(corpPos);
            corpPos = corpPos + patPos - T[patPos];
            if(patPos > 0) patPos = T[patPos];
        }
        return ret;
    }

private:
    string pat;
    vector<int> T;
};

class DAG {
public:
    DAG(const vector<vector<int>> &edges)
    : tsort_done(false), acyc(false) {
        V = edges.size();
        E.resize(V);
        for(int i = 0; i < V; ++i) {
            for(int to : edges[i]) {
                E[i].push_back(to);
            }
        }
    }

    bool tsort() {
        vector<int> indeg(V, 0);
        for(int i = 0; i < V; ++i) {
            for(int to : E[i]) ++indeg[to];
        }

        stack<int> done;
        for(int i = 0; i < V; ++i) {
            if(indeg[i] == 0) done.push(i);
        }

        while(!done.empty()) {
            int cur = done.top();
            done.pop();
            order.push_back(cur);
            for(int to : E[cur]) {
                --indeg[to];
                if(indeg[to] == 0) done.push(to);
            }
        }

        tsort_done = true;
        acyc = (order.size() == V);
        return acyc;
    }

    int longest_path() {
        if(!tsort_done) tsort();
        if(!acyc) return -1;

        dp.resize(V);
        for(int i = 0; i < V; ++i) {
            int cur = order[i];
            for(int to : E[cur]) {
                dp[to] = max(dp[to], dp[cur] + 1);
            }
        }

        return *max_element(begin(dp), end(dp));
    }

    bool acyclic() {
        if(!tsort_done) tsort();
        return acyc;
    }

    int operator[](int i) {
        if(!tsort_done) tsort();
        return order[i];
    }

private:
    int V;
    vector<vector<int>> E;
    vector<int> order;
    bool tsort_done;
    bool acyc;
    vector<int> dp;
};

int main() {
    string s, t;
    cin >> s >> t;
    string S = s;
    while(S.size() < 2 * t.size()) S += s;

    KMP kmp(t);
    vector<int> pos = kmp(S);

    vector<vector<int>> E(s.size());
    for(int i : pos) {
        if(i >= s.size()) continue;
        E[i].push_back((i + t.size()) % s.size());
    }

    DAG dag(E);
    cout << (!dag.acyclic() ? -1 : dag.longest_path()) << endl;  
}

