class Matrix{
public:
	ull a, b, c, d;
	Matrix(){}
	Matrix(ull _a, ull _b, ull _c, ull _d): a(_a), b(_b), c(_c), d(_d){}
	Matrix operator * (const Matrix &M)const{
		Matrix ret;
		ret.a = (a * M.a + b * M.c);
		ret.b = (a * M.b + b * M.d);
		ret.c = (c * M.a + d * M.c);
		ret.d = (c * M.b + d * M.d);
		return ret;
	}
};

inline Matrix matpow(Matrix M, ull y){
	if(!y) return Matrix(1, 0, 0, 1);
	Matrix ret = M;
	for(--y; y; y >>= 1){
		if(y & 1) ret = ret * M;
		M = M * M;
	}
	return ret;
}

inline ull qpow(ull x, ull y){
	ull ret = 1;
	for(; y; y >>= 1){
		if(y & 1) ret *= x;
		x *= x;
	}
	return ret;
}

inline void add(ull &h, char c){
	(h *= P) += (c - 'a' + 1);
	return;
}

inline void add(ull &h1, ull h2, char c){
	h1 = h2 * P + c - 'a' + 1;
	return;
}

bool overlap(){
	ull rs = 0, rt = 0;
	FOR(i, 0, m) (rs *= pw[n]) += hs;
	FOR(i, 0, n) (rt *= pw[m]) += ht;
	//printf("hs = %llu ht = %llu rs = %llu rt = %llu\n", hs, ht, rs, rt);
	return (rs == rt);
}

bool check(int md){
	//printf("md = %d\n", md);
	ull rs = 0, rt = 0;
	FOR(i, 0, md) (rs *= pw[n]) += hs;
	FOR(i, 0, m) if(m - i <= 1ll * md * n){
		rt = suf[i];
		ll copy = (1ll * md * n - (m - i)) / m, tail = (1ll * md * n - (m - i)) % m;
		rt *= qpow(P, copy * m);
		Matrix M = Matrix(pw[m], 0, 1, 1);
		M = matpow(M, copy);
		rt += ht * M.c;
		rt *= pw[tail];
		if(tail) rt += pre[tail - 1];
		if(rs == rt) return true;
	}
	return false;
}

