auto calc(const std::string &s) {
    std::vector<int> a(s.size() + 1);
    a[0] = -1;
    for (int i = 0, j = -1; i < s.size(); i++) {
        while (j >= 0 && s[i] != s[j]) j = a[j];
        j++;
        a[i + 1] = s[i + 1] == s[j] ? a[j] : j;
    }
    return a;
}

int main() {
    std::string s, t;
    std::cin >> s >> t;
    int n = s.size(), m = t.size();
    std::vector<int> e(s.size());
    auto ss = s;
    while (ss.size() < s.size() + t.size()) ss += s;
    auto a = calc(t);

    for (int i = 0, j = 0; i < ss.size(); i++) {
        while (j >= 0 && ss[i] != t[j]) j = a[j];
        j++;
        if (j == m) {
            e[(i - m + 1) % n] = 1;
            j = a[j];
        }
    }

    int ret = 0;
    std::vector<int> p(n);
    for (int i = 0; i < n; i++) {
        if (e[i] < 0 || p[i]) continue;
        int j = i, tmp = 0;
        while (!p[j] && e[j]) {
            j = (j + m) % n;
            if (j == i) {
                std::cout << -1 << std::endl;
                return 0;
            }
            tmp++;
        }
        p[i] = tmp + p[j];
        ret = std::max(ret, p[i]);
    }

    std::cout << ret << std::endl;

