vector<int> buildKMPFailTable(const string& t) {
	int m = sz(t);
	vector<int> fail(m + 1);
	int j = fail[0] = -1;
	for (int i = 1; i <= m; i++) {
		while (j >= 0 && t[j] != t[i - 1]) j = fail[j];
		fail[i] = ++j;
	}
	return fail;
}

int ml(string s, string t) {
	s = s + s + s + s;
	while (sz(s) < sz(t) * 4) s += s;
	auto fail = buildKMPFailTable(s);
	int maxMatchedLen = 0;
	for (int i = 0, k = 0; i < sz(s); i++) {
		while (k >= 0 && s[i] != t[k % sz(t)]) k = fail[k];
		k++;
		maxMatchedLen = max(maxMatchedLen, k);
	}
	return maxMatchedLen;
}

