#define MAX_N 500010

string s,t;
int prefix[MAX_N], n, m; // n = size of text, m = size of pattern.

void kmpPreprocess() {
	int i = 0, j = -1; prefix[0] = -1;

	while (i < m) {
		while (j >= 0 && t[i] != t[j]) j = prefix[j];
		i++; j++;
		prefix[i] = j;
	} 
}

set<int> kmpSearch(int n2) {
	int i = 0, j = 0;
	set<int> matches;

	while (i < n) {
		while (j >= 0 && s[i] != t[j]) j = prefix[j];
		i++; j++;
		if (j == m) {
			matches.insert((i - j)%n2);
			// printf("P is found at index %d in T\n", i - j);
			j = prefix[j]; // prepare j for the next possible match
		}
	}

	return matches;
}

vi nodes;
bool visited[MAX_N], cyclic;
vi g[MAX_N];
int dist[MAX_N];

void dfs(int curr, vi &ts, set<int> &pars) {
	if (cyclic)
	{
		return;
	}
	pars.insert(curr);		
	visited[curr] = true;
	for(auto nxt: g[curr]) {
		if (!visited[nxt])
		{
			dfs(nxt, ts, pars);
		} else if (pars.find(nxt) != pars.end())
		{
			cyclic = true;
			return;
		}
	}
	pars.erase(curr);
	ts.push_back(curr);
}

void dfs2(int curr) {
	visited[curr] = true;
	for(auto nxt : g[curr]) {
		if (!visited[nxt])
		{
			dist[nxt] = dist[curr] + 1;
			dfs2(nxt);
		}
	}
}

