constexpr uint mask30 = (1ull << 30) - 1, mask31 = (1ull << 31) - 1, mask61 = (1ull << 61) - 1;

uint add61(uint x, uint y) {
  uint z = x + y, w = (z >> 61) + (z & mask61);
  return w < mask61 ? w : w - mask61;
}

uint sub61(uint x, uint y) {
  return x >= y ? x - y : mask61 - (y - x);
}

uint mul61(uint x, uint y) {
  uint a = x >> 31, b = x & mask31, c = y >> 31, d = y & mask31, z = a * d + b * c, e = z >> 30, f = z & mask30;
  return (2 * a * c + e + (f << 31) + b * d) % mask61;
}

uint pow61(uint x, int n) {
  uint r = 1;
  for (; n; n >>= 1, x = mul61(x, x))
    if (n & 1)
      r = mul61(r, x);
  return r;
}

