  }
  int rs[m] = {}, r = 0;
  function<int(int)> rec;
  rec =
    [&](int i) {
      if (rs[i] || !fs[i])
        return rs[i];
      rs[i] = -1;
      int x = rec((i+n)%m);
      if (x < 0)
        return x;
      return rs[i] = x + 1;
    };
  dotimes(i, m) {
    int x = rec(i);
    if (x < 0) {
      r = -1;
      break;
    }
    maxs(r, x);
  }
  wint(r);
  return 0;
}

