class SA {
  int n;
  string s;
public:
  vector<int> rank, sa;

  SA(string s) : s(s) {
    n = s.size();
    rank.resize(n + 1);
    sa.resize(n + 1);
    for (int i = 0; i < n; i++) rank[i] = s[i];
    s[n] = -1;
    for (int i = 0; i <= n; i++) sa[i] = i;
    vector<int> tmp(n + 1);
    for (int k = 1; k <= n; k <<= 1) {
      function<bool(int, int)> comp = [&](int i, int j) {
        if (rank[i] != rank[j]) {
          return rank[i] < rank[j];
        } else {
          int lvalue = i + k <= n ? rank[i + k] : -1;
          int rvalue = j + k <= n ? rank[j + k] : -1;
          return lvalue < rvalue;
        }
      };
      sort(sa.begin(), sa.end(), comp);
      tmp[sa[0]] = 0;
      for (int i = 0; i < n; i++) {
        tmp[sa[i + 1]] = tmp[sa[i]] + (comp(sa[i], sa[i + 1]) ? 1 : 0);
      }
      rank = tmp;
    }
  }

  pair<bool, int> contains(string t) {
    if (t.size() == 0) return make_pair(true, 0);
    int l = 0, r = n;
    while (r - l > 1) {
      int m = (l + r) / 2;
      if (s.compare(sa[m], t.size(), t) < 0) {
        l = m;
      } else {
        r = m;
      }
    }
    return make_pair(s.compare(sa[r], t.size(), t) == 0, sa[r]);
  }
};

struct SuffixArray {
  vector<int> SA;
  const string s;

  SuffixArray(const string &str) : s(str) {
    SA.resize(s.size());
    iota(begin(SA), end(SA), 0);
    sort(begin(SA), end(SA), [&](int a, int b) {
      return s[a] == s[b] ? a > b : s[a] < s[b];
    });
    vector<int> classes(s.size()), c(s.begin(), s.end()), cnt(s.size());
    for (int len = 1; len < s.size(); len <<= 1) {
      for (int i = 0; i < s.size(); i++) {
        if (i > 0 && c[SA[i - 1]] == c[SA[i]] && SA[i - 1] + len < s.size() &&
            c[SA[i - 1] + len / 2] == c[SA[i] + len / 2]) {
          classes[SA[i]] = classes[SA[i - 1]];
        } else {
          classes[SA[i]] = i;
        }
      }
      iota(begin(cnt), end(cnt), 0);
      copy(begin(SA), end(SA), begin(c));
      for (int i = 0; i < s.size(); i++) {
        int s1 = c[i] - len;
        if (s1 >= 0) SA[cnt[classes[s1]]++] = s1;
      }
      classes.swap(c);
    }
  }

  int operator[](int k) const {
    return SA[k];
  }

  size_t size() const {
    return s.size();
  }

  bool lt_substr(const string &t, int si = 0, int ti = 0) {
    int sn = (int) s.size(), tn = (int) t.size();
    while (si < sn && ti < tn) {
      if (s[si] < t[ti]) return true;
      if (s[si] > t[ti]) return false;
      ++si, ++ti;
    }
    return si >= sn && ti < tn;
  }

  int lower_bound(const string &t) {
    int low = -1, high = (int) SA.size();
    while (high - low > 1) {
      int mid = (low + high) / 2;
      if (lt_substr(t, SA[mid])) low = mid;
      else high = mid;
    }
    return high;
  }

  pair<int, int> lower_upper_bound(string &t) {
    int idx = lower_bound(t);
    int low = idx - 1, high = (int) SA.size();
    t.back()++;
    while (high - low > 1) {
      int mid = (low + high) / 2;
      if (lt_substr(t, SA[mid])) low = mid;
      else high = mid;
    }
    t.back()--;
    return {idx, high};
  }

  void output() {
    for (int i = 0; i < size(); i++) {
      cout << i << ": " << s.substr(SA[i]) << endl;
    }
  }
};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  string s, t;
  cin >> s >> t;

  int m = s.size();
  for (int l = s.size(), i = 0; i < l; i++) s.push_back(s[i]);
  string u = s;
  while (u.size() < t.size()) {
    for (int l = u.size(), i = 0; i < l; i++) u.push_back(u[i]);
  }
  for (int l = u.size(), i = 0; i < l; i++) u.push_back(u[i]);

  SuffixArray sa(u);
  auto rng = sa.lower_upper_bound(t);

  if (rng.first == rng.second) {
    cout << 0 << endl;
    return 0;
  }
  int pos = sa.lower_bound(t);
  bool loop = true;
  for (int i = 0; i < u.size(); i++) {
    if (u[(i + pos) % u.size()] != t[i % t.size()]) loop = false;
  }
  if (loop) {
    cout << -1 << endl;
    return 0;
  }

  pos %= m;

  vector<int> A(t.size() + 1);
  A[0] = -1;
  int jj = -1;
  for (int i = 0; i < t.size(); i++) {
    while (jj >= 0 && t[i] != t[jj]) jj = A[jj];

    jj++;
    // 元のコードでは A[i+1] = j;
    if (t[i + 1] == t[jj]) A[i + 1] = A[jj];
    else A[i + 1] = jj;
  }

  ll ans = 0, score = 0, j = 0;
  for (int i = 0; i < u.size(); i++) {
    if (u[(i + pos) % u.size()] == t[j]) {
      score++;
      ans = max(ans, score / (ll) t.size());
      j = (j + 1) % t.size();
    } else {
      score = A[j + 1];
      j = A[j + 1];
    }
  }
  cout << ans << endl;

  return 0;
}

