vb is_match;

void kmp(const string &a, const string &b) {
	ll m = sz(a), n = sz(b), j = 0;
	vl p(m);
	FOR(i,1,m) {
		while (j > 0 && a[j] != a[i]) j = p[j-1];
		if (a[j] == a[i]) j++;
		p[i] = j;
	}
	j = 0;
	FOR(i,0,n) {
		while (j > 0 && a[j] != b[i]) j = p[j-1];
		if (a[j] == b[i]) j++;
		if (j == m) {
			// found match, a = b[i-m+1..i]
			is_match[i-m+1] = true;
			j = p[j-1];
		}
	}
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	string a, b;
	cin >> b >> a;

	do b += b; while (sz(b) < 2*sz(a));

	is_match.resize(sz(b));
	kmp(a,b);
	FOR(i,0,sz(b)/2) if (is_match[i]) is_match[i+sz(b)/2] = true;

	vl dp(sz(b),-1);

	function<ll(ll)> rec = [&](ll i) {
		if (!is_match[i]) return 0LL;
		if (dp[i] == -2) {
			cout << -1 << endl;
			exit(0);
		}
		if (dp[i] != -1) return dp[i];
		dp[i] = -2;
		return dp[i] = 1 + rec((i+sz(a))%sz(b));
	};

	ll res = 0;
	FOR(i,0,sz(b)) res = max(res,rec(i));
	cout << res << endl;	
}

