struct SeqSearchTable {
	string v;
	vector<UL> t;
	SeqSearchTable(string seq) { init(move(seq)); }
	void init(string seq) {
		v = move(seq);
		t.resize(v.size());
		t[0] = (UL)-1;
		UL p = 1, q = -1;
		while (p < v.size()) {
			if (q == (UL)-1) { t[p] = 0; p++; q = 0; }
			else if (v[q] == v[p - 1]) { t[p] = q + 1; p++; q++; }
			else { q = t[q]; }
		}
	}
};

vector<UL> SeqSearch(const string &seq, const SeqSearchTable &tg) {
	vector<UL> f(seq.size());
	UL p = 0, q = 0;
	while (p < seq.size()) {
		if (seq[p] == tg.v[q]) {
			f[p] = q + 1;
			p++; q++;
			if (q == tg.v.size()) {
				q = tg.t[q - 1] + 1;
			}
		}
		else {
			q = tg.t[q];
			if (q == (UL)-1) { p++; q = 0; }
		}
	}
	return move(f);
}

