template <typename T>
class SegTree {
 private:
    int _n;
    T _init_val;
    std::vector<T> _data;
    std::function<T(T, T)> _f;

    T _query(int a, int b, int k, int l, int r) {
        // [a b)と[l r]が交差しない
        if (r <= a || b <= l) return _init_val;

        // [a b)が[l r]を含む
        if (a <= l && r <= b) return _data[k];

        T vl = _query(a, b, k*2+1, l, (l+r)/2);
        T vr = _query(a, b, k*2+2, (l+r)/2, r);

        return _f(vl, vr);
    }

 public:
    SegTree(int n, T init_val, std::function<T(T, T)> f) {
        _init_val = init_val;
        _n = 1;
        _f = f;

        while (_n < n)
            _n *= 2;
        _data.resize(2 * _n, init_val);
    }

    T get(int k) {
        return _data[k + _n - 1];
    }

    void update(int k, T a) {
        k += _n-1;
        _data[k] = a;
        while (k > 0) {
            k = (k-1)/2;
            _data[k] = _f(_data[k*2+1], _data[k*2+2]);
        }
    }

    // [a b)の範囲でfを適用
    T query(int a, int b) {
        return _query(a, b, 0, 0, _n);
    }

    // 先頭からチェックし，はじめてxを満たしたインデックス
    int lower_bound(T x) {
        return _lower_bound(x, 0);
    }

    int _lower_bound(T x, int k) {
        if (k >= _n-1) {
            return k - (_n - 1);  // 葉
        } else if (_data[k] < x) {
            return _n;  // 該当なし
        } else if (x <= _data[k * 2 + 1]) {
            return _lower_bound(x, k * 2 + 1);
        } else {
            return _lower_bound(x - _data[k * 2 + 1] , k * 2 + 2);
        }
    }
};

class SuffixArray {
 public:
    std::string s;  // 対象文字列
    std::vector<int> sa;  // suffix array本体     i -> sa[i]
    std::vector<int> rsa;  // suffix array本体 sa[i] -> i
    std::vector<int> lcp;  // Longest Common Prefix Array，高さ配列
    SegTree<int> st_lcp;  // lcpのセグメントツリー

    // O(n log n)
    explicit SuffixArray(std::string s):
        s(s),
        st_lcp(s.size() + 1, 1 << 29,
                [](int a, int b) {return std::min(a, b);}) {
        sa = construct_sa();
        lcp = construct_lcp();

        // saの逆も作る
        rsa = std::vector<int>(s.size()+1, 0);
        for (int i = 0; i < sa.size(); i++) {
            rsa[sa[i]] = i;
        }

        // セグメントツリーの初期化 O(n log n)
        for (int i = 0; i < lcp.size(); i++) {
            st_lcp.update(i, lcp[i]);
        }
    }

    // (rank[i], rank[i+k])と(rank[j], rank[j+k])を比較
    bool compare_sa(int i, int j, int k, int n, const std::vector<int> &rank) {
        if (rank[i] != rank[j]) {
            return rank[i] < rank[j];
        } else {
            int ri = i + k <= n ? rank[i + k] : -1;
            int rj = j + k <= n ? rank[j + k] : -1;
            return ri < rj;
        }
    }

    // O(n)
    std::vector<int> construct_sa() {
        int n = s.size();
        std::vector<int> res(n + 1, 0);
        std::vector<int> rank(n + 1, 0);
        std::vector<int> tmp(n + 1, 0);

        // 最初は，文字コードをランクにする
        for (int i = 0; i <= n; i++) {
            res[i] = i;
            rank[res[i]] = i < n ? s[i] : -1;
        }

        // k文字についてソートされているところから，2k文字でソートする
        for (int k = 1; k <= n; k *= 2) {
            auto f = [&](int i, int j)
                { return this->compare_sa(i, j, k, n, rank);};
            sort(begin(res), end(res), f);
            tmp[res[0]] = 0;
            for (int i = 1; i <= n; i++) {
                tmp[res[i]] = tmp[res[i - 1]] + (f(res[i - 1], res[i]) ? 1 : 0);
            }
            rank = tmp;
        }

        return res;
    }

    // O(n)
    // 高さ配列lcpを作成
    std::vector<int> construct_lcp() {
        int n = s.size();
        std::vector<int> rank(n + 1, 0);
        std::vector<int> res(n + 1, 0);
        for (int i = 0; i <= n; i++)
            rank[sa[i]] = i;

        int h = 0;
        res[0] = 0;
        for (int i = 0; i < n; i++) {
            int j = sa[rank[i]-1];
            if (h > 0) h--;
            for (; j + h < n && i + h < n; h++) {
                if (s[j + h] != s[i + h])
                    break;
            }

            res[rank[i] - 1] = h;
        }
        return res;
    }

    void dump() {
        int n = s.size();
        std::cout << "# SuffixArray dump" << std::endl;
        std::cout << "s = " << s << std::endl;
        std::cout << "----------------------" << std::endl;
        std::cout << " i sa[i] lcp[i]  s[sa[i]...]" << std::endl;
        for (int i = 0; i <= n; i++) {
            printf("%2d%6d%7d  %s\n",
                    i, sa[i], lcp[i], s.substr(sa[i]).c_str());
        }
    }

    // O(1)
    // 部分文字列s[i...]のランクを返す
    int getRank(int i) {
        return rsa[i];
    }

    // O(log n)
    // suffix array を使って部分文字列patのs内の位置を検索
    // 見つかれなければ-1を返す
    int find(const std::string &pat) {
        int a = 0, b = s.size();
        while (b - a > 1) {
            int c = (a + b)/2;
            if (s.compare(sa[c], pat.size(), pat) < 0)
                a = c;
            else
                b = c;
        }

        if (s.compare(sa[b], pat.size(), pat) == 0) {
            return sa[b];
        } else {
            return -1;
        }
    }

    // 文字列sの s[i..] と s[j..] の先頭共通文字数を返す
    // O(log n)
    int prefixCommonLength(int i, int j) {
        if (i == j)  return s.size()-i;

        i = rsa[i];
        j = rsa[j];

        return st_lcp.query(std::min(i, j), std::max(i, j));
    }
};

class UnionFind {
 public:
     int n;
     std::vector<int> par;
     std::vector<int> num;

     explicit UnionFind(int n) {  // [0 n)のunion find
         this->n = n;
         this->par.resize(n);
         this->num.resize(n, 1);
         for (int i = 0; i < n; i++) {
             this->par[i] = i;
         }
     }

     int root(int i) {
         if (par[i] == i)
             return i;
         else
             return par[i] = root(par[i]);
     }

     bool same(int i, int j) {
         return root(i) == root(j);
     }

     // もしすでに、くっ付いていたら-1を返す
     int unite(int i, int j) {
         int t = root(i);
         int k = root(j);

         if (t == k)
            return -1;

         par[t] = k;
         num[k] += num[t];
         return 0;
     }

     int size(int i) {
         return num[root(i)];
     }
};

