#define ANS_MOD (1000000007LL)

static SQWORD addMod(SQWORD x, SQWORD y)
{ 
    return (x + y) % ANS_MOD;
}

static SQWORD subMod(SQWORD x, SQWORD y)
{
    return (x - y + ANS_MOD) % ANS_MOD;
}

static SQWORD mulMod(SQWORD x, SQWORD y) 
{
    return (x * y) % ANS_MOD;
}

static SQWORD powMod(SQWORD x, SQWORD e) {
    SQWORD v = 1;
    for (; e; x = mulMod(x, x), e >>= 1) {
        if (e & 1) {
            v = mulMod(v, x);
        }
    }
    return v;
}

static SQWORD divMod(SQWORD x, SQWORD y)
{
    return mulMod(x, powMod(y, ANS_MOD - 2));
}


static SQWORD combMod(SQWORD n, SQWORD k)
{
    SQWORD v=1;
    for(SQWORD i=1; i<=k; i++) {
        v = divMod(mulMod(v, n-i+1),i);
    } 
    return v;
}

/**
 * KMP法 
 */
class KMP {
public:
    vector<SDWORD> makeTable(const string& s) {
        SDWORD n = s.size();
        vector<SDWORD> ret(n+1);
        ret[0] = -1;
        SDWORD j = -1;
        for (SDWORD i = 0; i < n; i++) {
            while ((0 <= j) && (s[i] != s[j])) {
                j = ret[j];
            } 
            j++;
            ret[i+1] = j;
        }
        return ret;
    }

    // str の中に word とマッチする場所のリストを返す
    // ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す
    vector<SDWORD> wordSearch(const string& str, const string& word) {
        vector<SDWORD> table = makeTable(word), ret;

        SDWORD m = 0, i = 0, n = str.size();
        while (m+i < n) {
            if (word[i] == str[m+i]) {
                if (++i == (int)(word.size())) {
                    ret.push_back(m);
                    m = m+i-table[i];
                    i = table[i];
                }
            } else {
                m = m+i-table[i];
                if (i > 0) i = table[i];
            }
        }
        return ret;
    }
};

