    vector<bool> match(N);

    RollingHash rh1(s), rh2(t);
    unsigned long long thash= rh2.get_hash(0, m);

    for(int i=0; i < N - m; ++i) {
        if(rh1.get_hash(i, i + m) == thash) match[i] = true;
    }

    // loop check & count
    UnionFind uf(N);
