vector<int> zAlgorithm(const string &s) {
    int n = (int)s.size(), l = 0, r = 0;
    vector<int> Z(n, n);
    for (int i = 1; i < n; ++i) {
        if (i > r) {
            l = r = i;
        } else if (Z[i - l] >= r - i + 1) {
            l = i;
        } else {
            Z[i] = Z[i - l];
            continue;
        }
        while (r < n&&s[r] == s[r - l])r++;
        Z[i] = r - l; r--;
    }
    return Z;
}

class UnionFind {
    int cnt;
    vector<int> par, rank, size;
public:
    UnionFind() {}
    UnionFind(int _n) :cnt(_n), par(_n), rank(_n), size(_n, 1) {
        for (int i = 0; i<_n; ++i) par[i] = i;
    }
    int find(int k) {
        return (k == par[k]) ? k : (par[k] = find(par[k]));
    }
    int operator[](int k) {
        return find(k);
    }
    int getSize(int k) {
        return size[find(k)];
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return;
        --cnt;
        if (rank[x] < rank[y]) {
            par[x] = y;
            size[y] += size[x];
        } else {
            par[y] = x;
            size[x] += size[y];
            if (rank[y] == rank[x]) ++rank[x];
        }
    }
    int count() {
        return cnt;
    }
};

