// kmp をやるための前計算
std::vector<ll> makeTable(const std::string& s) {
    ll n = s.size();
    std::vector<ll> ret(n+1);
    ret[0] = -1;
    ll j = -1;
    for (ll i = 0; i < n; i++) {
        while (j >= 0 && s[i] != s[j]) j = ret[j];
        ret[i+1] = ++j;
    }
    return ret;
}

// str の中に word とマッチする場所のリストを返す
// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す
std::vector<ll> kmp(const std::string& str, const std::string& word) {
    std::vector<ll> table = makeTable(word), ret;
    ll m = 0, i = 0, n = str.size();
    while (m+i < n) {
        if (word[i] == str[m+i]) {
            if (++i == (ll)(word.size())) {
                ret.push_back(m);
                m = m+i-table[i];
                i = table[i];
            }
        } else {
            m = m+i-table[i];
            if (i > 0) i = table[i];
        }
    }
    return ret;
}

void dfs(ll u,ll& ans2,std::vector<int>& used,std::vector<std::vector<ll>>& graph,std::vector<ll>& ans){
  if(used[u]==1){
    ans2=-1;
