		S += S0;
	}
	Rolling_Hash R; R.process(S, M);
	Rolling_Hash R0; R0.process(T, M);

	vector<bool> f1, f2;
	for (int i = 0; i < N; i++) {
		f1.push_back(R.v[i] == R0.v[0]);
		f2.push_back(false);
	}

	int ans = 0;
	for (int i = 0; i < N; i++) {
		if (f2[i] == true) { continue; }
		if (f1[i] == true) {
			int c = 0;
			int j = i;
			while (f1[j] == true && c <= N) {
				j = (j - M) % N;
				if (j < 0) { j += N; }
				c++;
			}
			if(c == N + 1){
				ans = -1;
				break;
			}
			j = (j + M) % N;
			c = 0;
			for (; f1[j] == true; j = (j + M) % N) {
				c++;
				f2[j] = true;
			}
			ans = max(ans, c);
		}
		f2[i] = true;
	}

	cout << ans << endl;

	return 0;
}

