	Matrix(){}
	Matrix(ull _a, ull _b, ull _c, ull _d): a(_a), b(_b), c(_c), d(_d){}
	Matrix operator * (const Matrix &M)const{
		Matrix ret;
		ret.a = (a * M.a % INF + b * M.c) % INF;
		ret.b = (a * M.b % INF + b * M.d) % INF;
		ret.c = (c * M.a % INF + d * M.c) % INF;
		ret.d = (c * M.b % INF + d * M.d) % INF;
		return ret;
	}
};

inline Matrix matpow(Matrix M, ull y){
	if(!y) return Matrix(1, 0, 0, 1);
	Matrix ret = M;
	for(--y; y; y >>= 1){
		if(y & 1) ret = ret * M;
		M = M * M;
	}
	return ret;
}

inline ull qpow(ull x, ull y){
	ull ret = 1;
	for(; y; y >>= 1){
		if(y & 1) (ret *= x) %= INF;
		(x *= x) %= INF;
	}
	return ret;
}

