// Z algorithm
struct Z {
  vi a;
  Z(){}
  Z(string& s):a(sz(s)) {
    int n = sz(s); a[0] = n;
    for (int i=1,j=0;i<n;) {
      while (i+j<n && s[j]==s[i+j]) ++j;
      a[i] = j;
      int k = !!j;
      while (i+k<n && k+a[k]<j) a[i+k] = a[k], ++k;
      i += k+!j; j -= k;
    }
  }
  inline int operator[](int i) { return a[i];}
};
