//Complexity is O(n)
vector<int> z_function(string &s, int n) {
   vector<int> z(n);
   for (int i=1, l=0, r=0; i<n; ++i) {
      if (i <= r) {
         z[i] = min(r-i+1, z[i-l]);
      }
      while (i+z[i]<n && s[z[i]] == s[i+z[i]]) {
         ++z[i];
      }
      if (i+z[i]-1 > r) {
         l = i, r = i+z[i]-1;
      }
   }

   for (int i = nt+1; i < n; ++i)
   {
      if(z[i] == nt){
         vis[(i-(nt+1))%ns] = 1;
      }
   }

   return z;
}


int indeg[N];
vector<int> topo; //Stores lexicographically smallest toposort
vector<int> g[N];
map<int, int> M;

bool toposort(int n, int max_lim) //Returns 1 if there exists a toposort, 0 if there is a cycle
{  
   priority_queue<int, vector<int>, greater<int> > pq;
   for(int i=0;i<n;i++){
      if(M.count(i) == 0)continue;
      for(auto &it:g[i])
         indeg[it]++;
   }
   for(int i=0;i<n;i++)
   {
      if(M.count(i) == 0)continue;
      if(!indeg[i])
         pq.push(i);
   }
   while(!pq.empty())
   {
      int u=pq.top();
      pq.pop();
      topo.push_back(u);
      for(auto &v:g[u])
      {
         indeg[v]--;
         if(!indeg[v])
            pq.push(v);
      }
   }
   if(topo.size() != max_lim)
      return 0;
   return 1;
}

void solve(){

   string s, t;
   cin >> s >> t;
   ns = sz(s), nt = sz(t);

   while(sz(s) <= ns + nt){
      s += s;
   }

   int n = sz(s);
   vis.resize(ns);

   string pt = t + '#' + s;
   z_function(pt, sz(pt));

   for (int i = 0; i < ns; ++i)
   {
      if(vis[i] and vis[(i+nt)%ns]){
         M[i] = 1;
         M[(i+nt)%ns] = 1;
         g[i].pb((i+nt)%ns);
         v[(i+nt)%ns].pb(i);
      }
   }

   if(!toposort(ns, sz(M))){
      cout<<-1;
      exit(0);
   }

   if (sz(M) == 0){
      cout<<0;
      exit(0);
   }

   vector<int> dp(n, 1);
   reverse(topo.begin(), topo.end());

   for(auto i: topo){
      for(auto par: v[i]){
         smax(dp[par], dp[i] + 1);
      }
   }

   int ans = 0;
   for(auto i: dp)
      smax(ans, dp[i]);

   cout<<ans;
}

