      to[i] = (i + M) % N;
    }
  }

  for (int i=0; i<N; i++) {
    int now = i;
    int counter = 0;
    while(to[now] != -1 && to[now] != i) {
      if (dp[now] != -1) {
        counter = counter + dp[now];
        break;
      }
      now = to[now];
      counter++;
    }

    if (to[now] == i) counter = INF;

    now = i;
    while(to[now] != -1 && to[now] != i && dp[now] == -1) {
      dp[now] = min(INF, counter);
      now = to[now];
      counter--;
    }
  }

  int ans = 0;

  for (int i=0; i<N; i++) {
    ans = max(ans, dp[i]);
  }

  if (ans == INF) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }



  return 0;
}

