void getnxt()
{
	int i=0,j=nxt[0]=-1;
	while(i<m)
	{
		while(j!=-1&&t[j]!=t[i])
			j=nxt[j];
		nxt[++i]=++j;
	}
}
void kmp()
{
	int i=0,j=0;
	while(i<n+m)
	{
		while(j!=-1&&t[j]!=s[i])
			j=nxt[j];
		i++; j++;
		if(j==m)
			g[(i-m)%n].push_back(i%n);
	}
}

int dfs(int u)
{
	if(vis[u])
	{
		if(vis[u]==1) return d[u]=INF;
		else return d[u];
	}
	d[u]=0;
	vis[u]=1;
	for(int v:g[u])
		d[u]=max(d[u],dfs(v)+1);
	vis[u]=2;
	return d[u];
}

