  for(int i = 0;i < (int)text.size();i++){
    if(z[i + (int)pattern.size() + 1] == pattern.size()){
      cnt++;
      if(idx.count(i - sz(pattern))){
        idx[i] = 1 + idx[i - sz(pattern)];
      }else{
        idx[i] = 1;
      }
      max_cont = max(max_cont, idx[i]);
    }
  } 
  return {cnt, max_cont};
}

