template <typename ContainerT = string>
struct KMP
{
    static const int MAXN = 5e6;
    int              fail[ MAXN ], pre[ MAXN ];
    void             failure(ContainerT s)
    {
        int j     = -1;
        fail[ 0 ] = -1;
        for (int i = 0; i < s.size(); i++)
        {
            while (j >= 0 && s[ i ] != s[ j ]) j = fail[ j ];
            j++;
            fail[ i + 1 ] = j;
        }
    }
    bool match(ContainerT s, ContainerT t)
    {
        int j    = 0;
        pre[ 0 ] = 0;
        for (int i = 0; i < s.size(); i++)
        {
            while (j == t.size() || (j >= 0 && s[ i ] != t[ j ])) j = fail[ j ];
            j++;
            pre[ i + 1 ] = j;
        }
        return 0;
    }
};
KMP<string> kmp;
string      expand(string s, const string &t)
{
    string ns = s;
    while (ns.size() < t.size()) ns += s;
    ns += ns + ns;
    return ns;
}
bool alwaysMatching(const vector<int>&v)
{
    if (v.size() < 2) return false;
    int p = v[ 1 ] - v[ 0 ];
    for (int i = 1; i < v.size(); i++)
    {
        if (v[ i ] - v[ i - 1 ] != p) return false;
    }
    return true;
}
int main()
{
    string s, t;
    io >> s >> t;
    s = expand(s, t);
    kmp.failure(t);
    kmp.match(s, t);
    vector<int> v;
    v.clear();
    for (int i = 0; i <= s.size(); i++)
    {
        if (kmp.pre[ i ] == t.size()) v.push_back(i);
    }
    if (alwaysMatching(v))
    {
        io.WL(-1);
        return 0;
    }
    int ans = 0, cnt = 0,p=INT_MAX;
    for (int i = 1; i < v.size(); i++)
    {
        p=min(p,v[i]-v[i-1]);
    }
    for (int i = 1; i < v.size(); i++)
    {
        if (v[i]-v[i-1]!=p)
        {
            ans=max(cnt,ans);
            cnt=1;
        }else
