int*makekmp(char*t,int tlen){
	int*tt=calloc(tlen+1,sizeof(int));
	int len=0;
	tt[0]=-1;
	for(int pos=1;pos<tlen;pos++,len++){
		if(t[pos]==t[len]){
			//同じなのに失敗したら、失敗
			tt[pos]=tt[len];
		}
		else{
			//違うとき失敗したら、そこからチェック
			tt[pos]=len;
			//一致するところまで戻る
			while(len>=0&&t[pos]!=t[len])len=tt[len];
		}
	}
	tt[tlen]=len;
	return tt;
}
