void make_pre(char* t,int tl){
  dc-=df;if(dc<0){printf("err in make_pre\n");return;}
  pre[0]=0;
  int i,temp;
  for(i=1;i<tl;i++){
  dc-=df;if(dc<0){printf("err in make_pre\n");return;}
    temp=pre[i-1];
    while(t[i]!=t[temp]){
  dc-=df;if(dc<0){printf("err in make_pre\n");return;}
      if(temp==0){
	temp=-1;
	break;
      }
      int T=temp-pre[temp-1];
      while(temp+1-pre[temp]==T){
  dc-=df;if(dc<0){printf("err in make_pre\n");return;}
	temp%=T;
	if(temp==0){
	  temp=T;
	  break;
	}
	T=temp-pre[temp-1];
      }
      temp-=T;
    }
    pre[i]=temp+1;
  }
  if(df){
    for(i=0;i<tl;i++){
  dc-=df;if(dc<0){printf("err in make_pre\n");return;}
      printf("%d",i%10);
    }
