  }
}

void make_match(char* s,int sl,char* t,int tl){
  int i=0,temps=0;
  while(temps<sl) {
  dc-=df;if(dc<0){printf("err in make_match\n");return;}
    while(i<tl && temps<sl) {
  dc-=df;if(dc<0){printf("err in make_match\n");return;}
      if(df)print(s,t,i,temps,1);
      if(s[(temps+i)%sl]==t[i]){
	i++;
	continue;
      }
      if(i==0){
	temps++;
	continue;
      }
      int T=i-pre[i-1];
      while(i+1-pre[i]==T){
  dc-=df;if(dc<0){printf("err in make_match\n");return;}
	temps+=i/T*T;
	i%=T;
	if(df)print(s,t,i,temps,-2);
