    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.io.*;
import java.util.*;

class Solver {
  final char[] ss, ts;

  int m;
  char[] sms;
  int[] suffixArray;

  boolean[] hasPrefix;
  int[] lengthCache;

  Solver(char[] ss, char[] ts) {
    this.ss = ss;
    this.ts = ts;
  }

  private int compare(int suffixArrayIndex) {
    for (int i = 0; i < ts.length; i++) {
      int smsIndex = suffixArray[suffixArrayIndex] + i;
      if (smsIndex >= sms.length) {
        return -1;
      }
      if (sms[smsIndex] < ts[i]) {
        return -1;
      } else if (sms[smsIndex] > ts[i]) {
        return 1;
      }
    }
    return 0;
  }

  private int calculateLowerBound(int depth, int minIndex, int maxIndex, char c) {
    while (maxIndex - minIndex > 1) {
      int midIndex = (maxIndex + minIndex) / 2;
      int smsIndex = suffixArray[midIndex] + depth;
      if (smsIndex >= sms.length) {
        minIndex = midIndex;
        continue;
      }
      char cMid = sms[smsIndex];
      if (cMid < c) {
        minIndex = midIndex;
      } else {
        maxIndex = midIndex;
      }
    }
    return minIndex;
  }

  private int calculateUpperBound(int depth, int minIndex, int maxIndex, char c) {
    while (maxIndex - minIndex > 1) {
      int midIndex = (maxIndex + minIndex) / 2;
      int smsIndex = suffixArray[midIndex] + depth;
      if (smsIndex >= sms.length) {
        minIndex = midIndex;
        continue;
      }
      char cMid = sms[smsIndex];
      if (cMid > c) {
        maxIndex = midIndex;
      } else {
        minIndex = midIndex;
      }
    }
    return maxIndex;
  }

  private int dfs(int startIndex, int index, boolean firstCall) {
//    System.err.printf("%d %d %s\n", startIndex, index, firstCall);
    if (!firstCall && startIndex == index) {
      return -1;
    }
    if (lengthCache[index] > 0) {
      return lengthCache[index];
    }
    if (!hasPrefix[index]) {
      return 0;
    }
    int result = dfs(startIndex, (index + ts.length) % ss.length, false);
    if (result < 0) {
      return result;
    }
    lengthCache[index] = result + 1;
    return lengthCache[index];
  }

  public int solve() {
    int m = (ts.length + ss.length - 1) / ss.length + 1;
    sms = new char[ss.length * m];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < ss.length; j++) {
        sms[i * ss.length + j] = ss[j];
      }
    }

    suffixArray = SuffixArrayBuilder.create(sms);

    if (1 == 1) {
      throw new RuntimeException();
    }

    int lowerBound = -1;
    int upperBound = sms.length;
    for (int depth = 0; depth < ts.length && upperBound - lowerBound >= 2; depth++) {
      int nextLowerBound = calculateLowerBound(depth, lowerBound, upperBound, ts[depth]);
      int nextUpperBound = calculateUpperBound(depth, lowerBound, upperBound, ts[depth]);
      lowerBound = nextLowerBound;
      upperBound = nextUpperBound;
    }

    hasPrefix = new boolean[ss.length];
    for (int i = lowerBound + 1; i < upperBound; i++) {
      hasPrefix[suffixArray[i] % ss.length] = true;
    }

    lengthCache = new int[ss.length];
    for (int i = 0; i < ss.length; i++) {
      if (!hasPrefix[i] || lengthCache[i] > 0) {
        continue;
      }
      if (dfs(i, i, true) < 0) {
        return -1;
      }
    }

    int answer = 0;
    for (int length : lengthCache) {
      answer = Math.max(answer, length);
    }
    return answer;
  }
}

