    int inf = Integer.MAX_VALUE/2;

    ArrayList<Integer>[] edge;
    boolean[] seen;
    long[] memo;
    boolean loop;
    long ans;

    void solve(){
        String s = ns();
        String t = ns();
        int sl = s.length();
        int tl = t.length();
        StringBuilder st = new StringBuilder();
        st.append(t);
        int times = 4*t.length()/s.length();
        for(int i = 0; i < times; i++){
