        edge = new ArrayList[sl];
        for(int i = 0; i < sl; i++){
            edge[i] = new ArrayList<>();
        }
        int[] inner = new int[sl];
        int[] outer = new int[sl];
        for(int i = t.length(); i < st.length(); i++){
            if(ret[i]<t.length()) continue;
            int idx = i - t.length();
            if(idx>=sl) break;
            edge[idx].add((idx+t.length())%sl);
            inner[(idx+t.length())%sl]++;
            outer[idx]++;
        }
        memo = new long[sl];
        long ans = 0;
        seen = new boolean[sl];
        for(int i = 0; i < sl; i++){
            if(inner[i]!=0||outer[i]!=1) continue;
            long tmp = f(i);
            ans = Math.max(tmp, ans);
            if(loop) break;
        }
        for(int i = 0; i < sl; i++){
            if(seen[i]) continue;
            if(inner[i]==0||outer[i]==0) continue;
            loop = true;
            break;
        }
        out.println(loop ? -1 : ans);
    }

    long f(int cur){
        if(seen[cur]){
            loop = true;
            return 0;
        }
        seen[cur] = true;
        long ret = 0;
        for(int e : edge[cur]){
            ret = f(e)+1;
        }
        return ret;
