	static int count(String s, String sss, String t, int index) {
		int count = 2;
		while (index < s.length() * 2 + 1) {
			int pos = index + t.length();
			int nextIndex = sss.indexOf(t, pos);
			if (nextIndex != pos) {
				return count;
			}
			index = nextIndex;
			count++;
		}
		return -1;
