public class Main {
	static int[] prefixFunction(char[] s) {
		int n = s.length, pi[] = new int[n];
		for (int i = 1, j = 0; i < n; ++i) {
			while (j > 0 && s[i] != s[j])
				j = pi[j - 1];
			if (s[i] == s[j])
				++j;
			pi[i] = j;
		}
		return pi;
	}
	static boolean solve(char []s,char []t) {

		String tmp=new String(s);
		int n = s.length;
		tmp = tmp + "#" + new String(t);
		int []pi = prefixFunction(tmp.toCharArray());

		boolean ok=2*n<pi.length;
		for (int i = n + n; i < pi.length; i++) {
			if (pi[i] != n) {
				ok=false;
			}
		}
		return ok;

	}
	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner();
		PrintWriter out = new PrintWriter(System.out);
		String S=sc.next();
		String tmp = S;
		char []t=sc.next().toCharArray();

		char[] s = (S+S).toCharArray();
		boolean ok=solve(s, t) || solve(t,s);
		tmp = new String(t) + "#" + new String(s);
		int []pi = prefixFunction(tmp.toCharArray());
		int n = t.length;
		int curr = 0, ans = 0;
		for (int i = n + 1; i < pi.length;) {
			if (pi[i] == n) {
				curr++;
				i += n;
			} else {
				i++;
				curr = 0;
			}

			ans = Math.max(ans, curr);
		}

		out.println(ok ? -1 : ans);
		out.close();

	}

