class kmp{
	public static int lps[];
	static void computeLPSArray(int m , String t){
		lps = new int[m];
		int length = 0;
		int i = 1;
		while(i < m){
			if(t.charAt(i) == t.charAt(length)){
				length++;
				lps[i] = length;
				i++;
			}
			else{
				if(length != 0)
					length = lps[i-1];
				else
					i++;
			}
		}
	}
	static void kmp_search(int eff , int n , int m , String s , String t , graph G){
		int i = 0 , j = 0;
		while(i < eff){
			if(s.charAt(i%n) == t.charAt(j)){
				i++;
				j++;
			}
			if(j == m){
				G.add_edge((i-m)%n , i%n);
				j = lps[j-1];
			}
			else if(i < eff && s.charAt(i%n) != t.charAt(j)){
				if(j != 0)
					j = lps[j-1];
				else
					i++;
			}

		}
	}
}
class graph{
	int v;
	LinkedList<Integer> G[];
	int indeg[];
	boolean visited[];
	int max_dis[];
	graph(int V){
		v = V;
		indeg = new int[V];
		visited = new boolean[V];
		max_dis = new int[V];
		G = new LinkedList[V];
		for(int i = 0 ;i < V ; i++)
			G[i] = new LinkedList<>();
	} 
	void add_edge(int a, int b){
		G[a].add(b);
		indeg[b]++;
	}

	int longest_path(int n){
		Queue<Integer> q = new LinkedList<>();
		int mx = 0 , cnt = 0;
		for(int i = 0 ;i < n; i++){
			if(indeg[i] == 0)
				q.add(i);
		}
		while(q.size() > 0){
			int u = q.peek();

			mx = Math.max(mx , max_dis[u]);
			q.remove();
			cnt++;
			visited[u] = true;
			for(int v : G[u]){
				if(!visited[v]){
					indeg[v]--;
					max_dis[v] = Math.max(max_dis[v] , max_dis[u] + 1);
					if(indeg[v] == 0)
						q.add(v);
				}
				else
					return -1;
			}
		}
		if(cnt < n)
			return -1;
		return mx;
	}	
}

import java.io.*;
import java.util.*;

class Solver {
  final char[] ss, ts;

  int m;
  char[] sms;
  int[] suffixArray;

  boolean[] hasPrefix;
  int[] lengthCache;

  Solver(char[] ss, char[] ts) {
    this.ss = ss;
    this.ts = ts;
  }

  private int compare(int suffixArrayIndex) {
    for (int i = 0; i < ts.length; i++) {
      int smsIndex = suffixArray[suffixArrayIndex] + i;
      if (smsIndex >= sms.length) {
        return -1;
      }
      if (sms[smsIndex] < ts[i]) {
        return -1;
      } else if (sms[smsIndex] > ts[i]) {
        return 1;
      }
    }
    return 0;
  }

  private int calculateLowerBound() {
    int minIndex = 0;
    int maxIndex = suffixArray.length;
    while (maxIndex - minIndex > 1) {
      int midIndex = (minIndex + maxIndex) / 2;
      int compareResult = compare(midIndex);
      if (compareResult < 0) {
        minIndex = midIndex;
      } else {
        maxIndex = midIndex;
      }
    }
    return minIndex;
  }

  private int calculateUpperBound() {
    int minIndex = 0;
    int maxIndex = suffixArray.length;
    while (maxIndex - minIndex > 1) {
      int midIndex = (minIndex + maxIndex) / 2;
      int compareResult = compare(midIndex);
      if (compareResult > 0) {
        maxIndex = midIndex;
      } else {
        minIndex = midIndex;
      }
    }
    return maxIndex;
  }

  private int dfs(int startIndex, int index, boolean firstCall) {
//    System.err.printf("%d %d %s\n", startIndex, index, firstCall);
    if (!firstCall && startIndex == index) {
      return -1;
    }
    if (lengthCache[index] > 0) {
      return lengthCache[index];
    }
    if (!hasPrefix[index]) {
      return 0;
    }
    int result = dfs(startIndex, (index + ts.length) % ss.length, false);
    if (result < 0) {
      return result;
    }
    lengthCache[index] = result + 1;
    return lengthCache[index];
  }

  public int solve() {
    int m = ts.length / ss.length + 2;
    sms = new char[ss.length * m];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < ss.length; j++) {
        sms[i * ss.length + j] = ss[j];
      }
    }

    suffixArray = SuffixArrayBuilder.create(sms);
    int lowerBound = calculateLowerBound();
    int upperBound = calculateUpperBound();

    hasPrefix = new boolean[sms.length];
    for (int i = lowerBound + 1; i < upperBound; i++) {
      hasPrefix[suffixArray[i]] = true;
    }

    lengthCache = new int[sms.length];
    for (int i = 0; i < sms.length; i++) {
      if (!hasPrefix[i] || lengthCache[i] > 0) {
        continue;
      }
      if (dfs(i, i, true) < 0) {
        return -1;
      }
    }

    int answer = 0;
    for (int length : lengthCache) {
      answer = Math.max(answer, length);
    }
    return answer;
  }
}

