public class Main {

    static String S, T;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        S = sc.next();
        T = sc.next();

        System.out.println(solve());
    }

    static int solve(String s, String t) {
        S = s;
        T = t;
        return solve();
    }

    static int solve() {
        StringBuilder b = new StringBuilder();
        b.append(S);
        while(b.length() < T.length()) {
            b.append(S);
        }
        S = b.toString();
        int N = S.length();
        boolean[] match = findMatch(S, T, createTable(T));
        UnionFind uf = new UnionFind(N);
        for (int i = 0; i < N; i++) {
            if( match[i] ) {
                int j = (i + T.length()) % N;
                if( !uf.isSame(i, j) ) {
                    uf.unite(i, j);
                } else {
                    return -1;
                }
            }
        }

        int max = 0;
        for (int i = 0; i < N; i++) {
            max = Math.max(max, uf.count(i));
        }
        return max -1;
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] count;

        public UnionFind(int n) {
            parent = new int[n];
            count = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                count[i] = 1;
            }
        }

        public int root(int i) {
            if (parent[i] == i) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if (ri == rj) return ri;


            int big = count[ri] < count[rj] ? rj : ri;
            int small = big == ri ? rj : ri;
            parent[small] = big;
            count[big] += count[small];
            return big;
        }

        public int count(int a) {
            return count[root(a)];
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

    public static boolean[] findMatch(String S, String W, int[] KMP) {
        int N = S.length();
        boolean[] match = new boolean[N];
        int cnt = 0;
        {
            int i = 0;
            int j = 0;
            while(i < N + T.length()-1) {
                if( S.charAt(i%N) == W.charAt(j) ) {
                    i++;
                    j++;

                    if( j == W.length() ) {
                        int idx = i-W.length();
                        match[idx] = true;
                        cnt++;
                        j = KMP[j];
                    }

                } else {
                    if( j != 0 ) {
                        j = KMP[j];
                    } else {
                        i++;
                    }
                }
            }
        }
        return match;
    }

    public static int[] createTable(String S) {
        int n = S.length();
        int[] kmp = new int[n+1];
        kmp[0] = -1;
        for (int i = 0; i < n; i++) {
            int t = kmp[i];
            while( t != -1 && S.charAt(i) != S.charAt(t) ) {
                t = kmp[t];
            }
            kmp[i+1] = t+1;
        }
        return kmp;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
