						}
					} else {
						if (arrS[idxS % arrS.length] == arrT[nextT]) {
							nextT++;
						} else {
							nextS = 0;
							nextT = 0;
						}
					}
				}
				idxS++;
				idxT++;
				if (idxS - i > arrS.length && idxT >= arrT.length) {
					System.out.println(-1);
					return;
				}
			}
			int length = idxT / arrT.length;
			if (max < length) {
