    static int[] Z(char[] s){
        int n=s.length;
        int z[]=new int[n];
        for(int i=1,l=0,r=0;i<n;i++){
            if(i<=r)
                z[i]=Math.min(r-i+1, z[i-l]);
            while(i+z[i]<n && s[z[i]]==s[i+z[i]])
                z[i]++;
            if(i+z[i]-1>r){
                l=i;
                r=i+z[i]-1;
            }
        }
        return z;
    }
    static int[] Z(String s){
        return Z(s.toCharArray());
    }
    static void solve() throws IOException {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        String s=in.next();
        String t=in.next();
        int m=s.length();
        StringBuilder sb=new StringBuilder(s);
        while(sb.length()<s.length()+t.length())
            sb.append(s);
        s=sb.toString();
        String p=t+"#"+s;
        int z[]=Z(p);
        int v[]=new int[m];
        int ans=0;
        int n=t.length();
        int av[]=new int[m];
        for(int i=n+1;i<=n+m;i++)
            av[i-(n+1)]=z[i];
        for(int i=0;i<m;i++){
            if(av[i]==n&&v[i]==0){
                ArrayList<Integer> ar=new ArrayList<>();
                HashSet<Integer> hs=new HashSet<>();
                int sp=i;
                while(av[sp]==n){
                    if(hs.contains(sp)){
                        ans=-1;
                        break;
                    }
                    if(v[sp]!=0)
                        break;
                    ar.add(sp);
                    hs.add(sp);
                    sp+=n;
                    sp%=m;
                }
                if(ans==-1)
                    break;
                if(v[sp]!=0){
                    for(int j=ar.size()-1;j>=0;j--){
                        v[ar.get(j)]=ar.size()-j+v[sp];
                    }
                    ans=Math.max(ans, v[ar.get(0)]);
                }
                else{
                    for(int j=ar.size()-1;j>=0;j--){
                        v[ar.get(j)]=ar.size()-j;
                    }
                    ans=Math.max(ans, v[ar.get(0)]);
                }



            }
        }
        out.println(ans);
        out.close();

    }
}

