        System.out.println(solve());
    }

    static int solve(String s, String t) {
        S = s;
        T = t;
        return solve();
    }

    static int solve() {
        if( S.length() < T.length() ) {
            StringBuilder b = new StringBuilder();
            b.append(S);
            while( b.length() < T.length() ) {
                b.append(S);
            }
            S = b.toString();
        }

        int N = S.length();

        int[] table = createTable(T);
        boolean[] match = new boolean[N];
        {
            int i = 0;
            int j = 0;
            while(i < N+T.length()) {
                if( S.charAt(i%N) == T.charAt(j) ) {
                    i++;
                    j++;

                    if( j == T.length() ) {
                        //　終了条件がかっこ悪い気が...
                        int idx = i-T.length();
                        if( idx >= N ) break;
                        match[idx] = true;
                        j = table[j];
                    }

                } else {
                    if( j != 0 ) {
                        j = table[j];

                    } else {
                        i++;
                    }
                }
            }
        }
        // debug(Arrays.toString(match));

        UnionFind uf = new UnionFind(N);
        for (int i = 0; i < N; i++) {
            if( match[i] ) {
                int j = (i + T.length()) % N;
                uf.unite(i, j);
            }
        }

        int max = 0;
        for (int i = 0; i < N; i++) {
            max = Math.max(max, uf.count(i));
        }

        // うまく説明できないがこういう感じっぽい？
        int g = gcd(S.length(), T.length());
