            edge[i] = new ArrayList<>();
        }
        int[] inner = new int[sl];
        int[] outer = new int[sl];
        for(int i = t.length(); i < st.length(); i++){
            if(ret[i]<t.length()) continue;
            int idx = i - t.length();
            if(idx>=sl) break;
            edge[idx].add((idx+t.length())%sl);
            inner[(idx+t.length())%sl]++;
            outer[idx]++;
        }
        seen = new boolean[sl];
        for(int i = 0; i < sl; i++){
            if(inner[i]!=0||outer[i]!=1) continue;
            f(i,0);
            if(loop) break;
        }
        for(int i = 0; i < sl; i++){
            if(seen[i]) continue;
            if(inner[i]==0||outer[i]==0) continue;
            loop = true;
            break;
        }
        out.println(loop ? -1 : ans);
    }

    void f(int cur, long sum){
        if(seen[cur]){
            loop = true;
            return;
        }
        seen[cur] = true;
        for(int e : edge[cur]){
            f(e, sum+1);
        }
        ans = Math.max(ans, sum);
    }

    int[] zalgo(String s) {
		int n = s.length();
		int[] ret = new int[n];
		ret[0] = n;
		int i = 1, j = 0;
		while (i < n) {
			while (i + j < n && s.charAt(j) == s.charAt(i + j))
				++j;
			ret[i] = j;
			if (j == 0) {
				++i;
				continue;
			}
			int k = 1;
			while (i + k < n && k + ret[k] < j) {
				ret[i + k] = ret[k];
				++k;
			}
			i += k;
			j -= k;
		}
		return ret;
	}
