        int[] inner = new int[sl];
        int[] outer = new int[sl];
        for(int i = t.length(); i < st.length(); i++){
            if(ret[i]<t.length()) continue;
            int idx = i - t.length();
            if(idx>=sl) break;
            edge[idx] = (idx+t.length())%sl;
            inner[(idx+t.length())%sl]++;
            outer[idx]++;
        }
        seen = new boolean[sl];
        for(int i = 0; i < sl; i++){
            if(inner[i]!=0||outer[i]!=1) continue;
            f(i,0);
            if(loop) break;
        }
        for(int i = 0; i < sl; i++){
