            if(inner[i]==0||outer[i]==0) continue;
            loop = true;
            break;
        }
        out.println(loop ? -1 : ans);
    }

    void f(int cur, long sum){
        if(cur==-1){
            ans = Math.max(ans, sum);
            return;
        }
        if(seen[cur]){
            loop = true;
            return;
        }
        seen[cur] = true;
        f(edge[cur], sum+1);
    }

    int[] zalgo(String s) {
		int n = s.length();
		int[] ret = new int[n];
		ret[0] = n;
		int i = 1, j = 0;
		while (i < n) {
			while (i + j < n && s.charAt(j) == s.charAt(i + j))
				++j;
			ret[i] = j;
			if (j == 0) {
				++i;
				continue;
			}
			int k = 1;
			while (i + k < n && k + ret[k] < j) {
				ret[i + k] = ret[k];
				++k;
			}
			i += k;
			j -= k;
		}
		return ret;
	}
