	int runs(String t, String s) {
		int[] z = zValues(t+"#"+s);
		int max = 0;

		z = Arrays.copyOfRange(z, t.length()+1, z.length);
		boolean inf = false;
		for(int i = 0; i < z.length; i++) {
			int runs = 0;
			int sub = 0;
			while(i < z.length && z[i] == t.length()) {
				runs++;
				sub = 1;
				i += z[i];
			}
			i -= sub;
			max = Math.max(max, runs);
		}

		return max;
	}

	int[] zValues(String string) {
		int n = string.length();  char[] s = string.toCharArray();
		int[] z = new int[n];  z[0] = n;
		int L = 0, R = 0;
		int[] left = new int[n], right = new int[n];
		for(int i = 1; i < n; ++i) {
			if(i > R) {
				L = R = i;
				while(R < n && s[R-L] == s[R]) R++;
				z[i] = R - L;  R--;
			} else {
				int k = i-L;
				if(z[k] < R-i+1) z[i] = z[k];
				else {
					L = i;
					while(R < n && s[R-L] == s[R]) R++;
					z[i] = R - L;  R--;
				}
			}
			left[i] = L;  right[i] = R;
		}
		return z;
	}

