class SuffixArrayBuilder {
  static class IntegerWrapper {
    final int integerValue;

    IntegerWrapper(int integerValue) {
      this.integerValue = integerValue;
    }
  }

  public static int[] create(char[] cs) {
    int n = cs.length;

//    Integer[] suffixArrayInteger = new Integer[n + 1];
    IntegerWrapper[] suffixArrayInteger = new IntegerWrapper[n];
    int[] rank = new int[n];
    for (int i = 0; i < n; i++) {
      suffixArrayInteger[i] = new IntegerWrapper(i);
      rank[i] = (int) cs[i];

    }

    for (int k = 1; k <= n; k *= 2) {
      final int kFinal = k;
      final int[] rankFinal = rank;
      final Comparator<IntegerWrapper> comparator = new Comparator<IntegerWrapper>() {
        public int compare(IntegerWrapper i1, IntegerWrapper i2) {
          if (rankFinal[i1.integerValue] != rankFinal[i2.integerValue]) {
            return rankFinal[i1.integerValue] - rankFinal[i2.integerValue];
          }
          int rank1 = rankFinal[(i1.integerValue + kFinal) % n];
          int rank2 = rankFinal[(i2.integerValue + kFinal) % n];
          return rank1 - rank2;
        }
      };

      Arrays.sort(suffixArrayInteger, comparator);
      int[] nextRank = new int[n];
      for (int i = 1; i < n; i++) {
        nextRank[i] = rank[i];
      }
      nextRank[suffixArrayInteger[0].integerValue] = 0;
      for (int i = 1; i < n; i++) {
        nextRank[suffixArrayInteger[i].integerValue] = nextRank[suffixArrayInteger[i - 1].integerValue]
            + (comparator.compare(suffixArrayInteger[i - 1], suffixArrayInteger[i]) < 0 ? 1 : 0);
      }
      rank = nextRank;

      /*
      System.out.println("------------------------");
      for (int i = 0; i <= n; i++) {
        String temp = new String(cs).substring(suffixArrayInteger[i]);
        System.out.printf("%3d: %3d, %40s %40s\n", i, suffixArrayInteger[i], temp.substring(0, Math.min(k, temp.length())), temp);
      }
      */
    }

    int[] suffixArray = new int[n];
    for (int i = 0; i < n; i++) {
      suffixArray[i] = suffixArrayInteger[i].integerValue;
    }

    return suffixArray;
  }
}

