            if (dist[i] == -1) {
                dfs(i, i, dist, g);
                res = Math.max(res, dist[i]);
            }
        }
        System.out.println(res);
    }

    private boolean dfs(final int u, final int start, final int[] dist, final List<Integer>[] g) {
        if (dist[u] != -1) {
            return true;
        }

        dist[u] = 0;
        for (int v : g[u]) {
            if (dist[v] == -1) {
                if (!dfs(v, start, dist, g)) {
                    return false;
                }
            }
            dist[u] = dist[v] + 1;
        }
        return true;
    }

