    void solve(){
        String s = ns();
        String t = ns();
        int sl = s.length();
        int tl = t.length();
        StringBuilder st = new StringBuilder();
        st.append(t);
        int times = (1000000+sl-1)/sl;
        for(int i = 0; i < times; i++){
            st.append(s);
        }
        int[] ret = zalgo(st.toString());
        edge = new int[sl];
        Arrays.fill(edge,-1);
        int[] inner = new int[sl];
        int[] outer = new int[sl];
        for(int i = t.length(); i < st.length(); i++){
            if(ret[i]<t.length()) continue;
            int idx = i - t.length();
            if(idx>=sl) break;
            edge[idx] = (idx+t.length())%sl;
            inner[(idx+t.length())%sl]++;
            outer[idx]++;
        }
        seen = new boolean[sl];
        for(int i = 0; i < sl; i++){
            if(inner[i]!=0||outer[i]!=1) continue;
            f(i,0);
            if(loop) break;
        }
        // for(int i = 0; i < sl; i++){
        //     if(seen[i]) continue;
        //     if(inner[i]==0||outer[i]==0) continue;
        //     loop = true;
        //     break;
        // }
        out.println(loop ? -1 : ans);
    }

    void f(int cur, long sum){
        if(cur==-1) return;
        if(seen[cur]){
            loop = true;
            return;
        }
        seen[cur] = true;
        f(edge[cur], sum+1);
        ans = Math.max(ans, sum);
    }

    int[] zalgo(String s) {
		int n = s.length();
		int[] ret = new int[n];
		ret[0] = n;
		int i = 1, j = 0;
		while (i < n) {
			while (i + j < n && s.charAt(j) == s.charAt(i + j))
				++j;
			ret[i] = j;
			if (j == 0) {
				++i;
				continue;
			}
			int k = 1;
			while (i + k < n && k + ret[k] < j) {
				ret[i + k] = ret[k];
				++k;
			}
			i += k;
			j -= k;
		}
		return ret;
	}
    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

