    public Set<Integer>[] find(String target, String pattern, int[] table) {
        int n = target.length();
        Set<Integer>[] g = new HashSet[n];
        for (int i = 0; i < g.length; i++) {
            g[i] = new HashSet<>();
        }
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (j >= 0 && target.charAt(i) != pattern.charAt(j)) {
                j = table[j];
            }
            j++;
            if (j == pattern.length()) {
                int from = i;
                int to = (i + pattern.length()) % n;
                g[from].add(to);

                j = table[j];
            }
            // System.out.println(i + " " + j + " " + res);
        }
        return g;
    }

    public void solve() {
        String s = in.next();
        String t = in.next();
        int[] sKmp = StringLibs.kmp(s);
        int[] tKmp = StringLibs.kmp(t);
        int sPeriod = period(sKmp);
        int tPeriod = period(tKmp);

        if (sPeriod == tPeriod) {
            String ss = s.substring(0, sPeriod);
            String tt = t.substring(0, tPeriod);
            if (StringLibs.find(ss + ss, tt) != -1) {
                System.out.println("-1");
                return;
            }
        }

        final Set<Integer>[] g;
        if (s.length() < t.length()) {
            StringBuilder ss = new StringBuilder();
            while (ss.length() < t.length() * 2) {
                ss.append(s);
            }
            g = find(ss.toString(), t, tKmp);
        } else {
            g = find(s + s, t, tKmp);
        }

        int[] dist = new int[g.length];
        Arrays.fill(dist, -1);
        int res = 0;
        for (int i = 0; i < g.length; i++) {
            if (dist[i] == -1) {
                if (!dfs(i, i, dist, g)) {
                    throw new RuntimeException();
                }
                res = Math.max(res, dist[i]);
            }
        }
        System.out.println(res);
    }

    private boolean dfs(final int u, final int start, final int[] dist, final Set<Integer>[] g) {
        if (dist[u] != -1) {
            return u != start;
        }

        dist[u] = 0;
        for (int v : g[u]) {
            if (dist[v] == -1) {
                if (!dfs(v, start, dist, g)) {
                    return false;
                }
            }
            dist[u] = dist[v] + 1;
        }
        return true;
    }

    private int period(int[] kmp) {
        int n = kmp.length - 1;
        int p = n - kmp[n];
        return n % p == 0 ? p : n;
    }

