	static int count(String s, String sss, String t, int index) {
		int count = 2;
		while (index < s.length() * 2 + 1) {
			int pos = index + t.length();
			int nextIndex = sss.indexOf(t, pos);
			if (nextIndex != pos) {
				return count;
			}
			index = nextIndex;
			count++;
		}
		return -1;
	}

	static int solve(String s, String t) {
		String sss = s + s + s + s;
		int index = sss.indexOf(t);
		if (index == -1) {
			return 0;
		}
		int max = 1;
		while (index < s.length()) {
			int pos = index + t.length();
			int nextIndex = sss.indexOf(t, pos);
			if (nextIndex == pos) { // 繰り返し
				int count = count(s, sss, t, nextIndex);
				if (count == -1) return -1;
				max = Math.max(max, count);
			}
			index = nextIndex;
		}
		return max;
	}

