public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    // long inf = Long.MAX_VALUE/2;
    int inf = Integer.MAX_VALUE/2;

    ArrayList<Integer>[] edge;
    boolean[] seen;
    long[] memo;
    boolean loop;
    long ans;

    void solve(){
        String s = ns();
        String t = ns();
        StringBuilder st = new StringBuilder();
        st.append(t);
        while(st.length()<=3*t.length()){
            st.append(s);
        }
        int[] ret = zalgo(st.toString());
        edge = new ArrayList[s.length()];
        for(int i = 0; i < s.length(); i++){
            edge[i] = new ArrayList<>();
        }
        int[] inner = new int[s.length()];
        int[] outer = new int[s.length()];
        for(int i = t.length(); i < st.length(); i++){
            if(ret[i]<t.length()) continue;
            int idx = i - t.length();
            if(idx>=s.length()) break;
            edge[idx].add((idx+t.length())%s.length());
            inner[(idx+t.length())%s.length()]++;
            outer[idx]++;
            // out.println(idx);
        }
        memo = new long[s.length()];
        long ans = 0;
        for(int i = 0; i < s.length(); i++){
            if(inner[i]!=0&&outer[i]!=1) continue;
            seen = new boolean[s.length()];
            long tmp = f(i);
            ans = Math.max(tmp, ans);
            if(loop) break;
        }
        out.println(loop ? -1 : ans);
    }

    long f(int cur){
        if(seen[cur]){
            loop = true;
            return 0;
        }
        if(memo[cur]>0){
            return memo[cur];
        }
        seen[cur] = true;
        long ret = 0;
        for(int e : edge[cur]){
            ret = f(e)+1;
        }
        memo[cur] = ret;
        return ret;
    }

    int[] zalgo(String s) {
		int n = s.length();
		int[] ret = new int[n];
		ret[0] = n;
		int i = 1, j = 0;
		while (i < n) {
			while (i + j < n && s.charAt(j) == s.charAt(i + j))
				++j;
			ret[i] = j;
			if (j == 0) {
				++i;
				continue;
			}
			int k = 1;
			while (i + k < n && k + ret[k] < j) {
				ret[i + k] = ret[k];
				++k;
			}
			i += k;
			j -= k;
		}
		return ret;
	}
    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

