class Program {
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    const int M2 = 998244353;
    const long LM = 1L << 60;
    const double eps = 1e-11;
    static void Main(string[] args)
    {
        var s = sc.Str;
        var t = sc.Str;
        var ss = new char[s.Length + t.Length + 9];
        for (int i = 0; i < ss.Length; i++)
        {
            ss[i] = s[i % s.Length];
        }
        var hs1 = new long[ss.Length + 1];
        var ht1 = new long[t.Length + 1];
        var hs2 = new long[ss.Length + 1];
        var ht2 = new long[t.Length + 1];
        for (int i = 0; i < ss.Length; i++)
        {
            hs1[i + 1] = hs1[i] * M + ss[i];
            hs2[i + 1] = hs2[i] * M2 + ss[i];
        }
        for (int i = 0; i < t.Length; i++)
        {
            ht1[i + 1] = ht1[i] * M + t[i];
            ht2[i + 1] = ht2[i] * M2 + t[i];
        }
        ok = new bool[s.Length];
        long p1 = pow(M, t.Length);
        long p2 = pow(M2, t.Length);
        for (int i = 0; i < s.Length; i++)
        {
            long hss1 = hs1[i + t.Length] - hs1[i] * p1;
            long htt1 = ht1[t.Length];
            long hss2 = hs2[i + t.Length] - hs2[i] * p2;
            long htt2 = ht2[t.Length];
            if (hss1 == htt1 && hss2 == htt2) {
                ok[i] = true;
            }
        }
        // Prt(ok);
        cnt = new int[s.Length];
        for (int i = 0; i < s.Length; i++)
        {
            cnt[i] = -1;
        }
        vis = new bool[s.Length];
        tl = t.Length;
        sl = s.Length;
        int ans = 0;
        for (int i = 0; i < s.Length; i++)
        {
            int a = dfs(i);
            // Prt(a);
            ans = Math.Max(ans, a);
        }
        Prt(ans >= M ? -1 : ans);
        sw.Flush();
    }
    static int[] cnt;
    static bool[] ok, vis;
    static int tl, sl;
    static int dfs(int p) {
        if (!ok[p]) return cnt[p] = 0;
        if (cnt[p] != -1) return cnt[p];
        if (vis[p]) return M;
        vis[p] = true;
        return cnt[p] = dfs((p + tl) % sl) + 1;
    }

    static long pow(long a, long b) {
        if (b == 0) return 1;
        var t = pow(a, b / 2);
        if ((b & 1) == 0) return t * t;
        return t * t * a;
    }

