class Program {
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    const int M2 = 998244353;
    const long LM = 1L << 60;
    const double eps = 1e-11;
    static void Main(string[] args)
    {
        var s = sc.Str;
        var t = sc.Str;
        var ss = new char[s.Length + t.Length + 9];
        for (int i = 0; i < ss.Length; i++)
        {
            ss[i] = s[i % s.Length];
        }
        int[] mods = { 26, 27, 1333, M, M2, M + 2 };
        var hs = new long[mods.Length][];
        var ht = new long[mods.Length][];
        for (int i = 0; i < mods.Length; i++)
        {
            hs[i] = new long[ss.Length + 1];
            ht[i] = new long[t.Length + 1];
            for (int j = 0; j < ss.Length; j++)
            {
                hs[i][j + 1] = hs[i][j] * mods[i] + ss[j] - 'a';
            }
            for (int j = 0; j < t.Length; j++)
            {
                ht[i][j + 1] = ht[i][j] * mods[i] + t[j] - 'a';
            }
        }
        ok = new bool[s.Length];
        var p = new long[mods.Length];
        for (int i = 0; i < mods.Length; i++)
        {
            p[i] = pow(mods[i], t.Length);
        }
        for (int i = 0; i < s.Length; i++)
        {
            ok[i] = true;
            for (int j = 0; j < mods.Length; j++)
            {
                long hss = hs[j][i + t.Length] - hs[j][i] * p[j];
                long htt = ht[j][t.Length];
                ok[i] &= hss == htt;
            }
        }
        cnt = new int[s.Length];
        for (int i = 0; i < s.Length; i++)
        {
            cnt[i] = -1;
        }
        vis = new bool[s.Length];
        tl = t.Length;
        sl = s.Length;
        int ans = 0;
        for (int i = 0; i < s.Length; i++)
        {
            ans = Math.Max(ans, dfs(i));
        }
        Prt(ans >= M ? -1 : ans);
        sw.Flush();
    }
    static int[] cnt;
    static bool[] ok, vis;
    static int tl, sl;
    static int dfs(int p) {
        if (!ok[p]) return cnt[p] = 0;
        if (cnt[p] != -1) return cnt[p];
        if (vis[p]) return M;
        vis[p] = true;
        return cnt[p] = dfs((p + tl) % sl) + 1;
    }

    static long pow(long a, long b) {
        if (b == 0) return 1;
        var t = pow(a, b / 2);
        if ((b & 1) == 0) return t * t;
        return t * t * a;
    }

    static void DBG(string a) => Console.WriteLine(a);
    static void DBG<T>(IEnumerable<T> a) => DBG(string.Join(" ", a));
    static void DBG(params object[] a) => DBG(string.Join(" ", a));
    static void Prt(string a) => sw.WriteLine(a);
    static void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    static void Prt(params object[] a) => Prt(string.Join(" ", a));
}
