namespace ABC135F
{
    class Program
    {
        static void Main(string[] args)
        {
            var S2 = Console.ReadLine();
            var T = Console.ReadLine();

            if (S2.Distinct().Count() == 1 && T.Distinct().Count() == 1 && S2[0] == T[0])
            {
                Console.WriteLine(-1);
                return;
            }

            //SをTの3倍まで延長
            string S = S2 + S2 + S2;
            StringBuilder sb = new StringBuilder(S);
            while (sb.Length < T.Length * 3)
            {
                sb.Append(S2);
            }
            S = sb.ToString();

            RollingHash rhS = new RollingHash(S);
            RollingHash rhT = new RollingHash(T);

            var hash = rhT.Get(0, T.Length);
            int[] match = new int[S.Length - T.Length + 1];
            for (int i = 0; i <= S.Length - T.Length; i++)
            {
                if (hash == rhS.Get(i, i + T.Length))
                {
                    if (i - T.Length >= 0)
                        match[i] = match[i - T.Length] + 1;
                    else match[i] = 1;
                }
            }

            //forDebug
            //Console.WriteLine(string.Join(",", match));

            int max = match.Max();
            if (max != 0)
            {
                int repeat = (S.Length - 1) / T.Length;
                if (max >= repeat)
                {
                    Console.WriteLine(-1);
                    return;
                }
            }

            Console.WriteLine(max);
            Console.ReadKey();
        }

        static int[] ReadInt()
        {
            int[] ret = Console.ReadLine().Split().Select(int.Parse).ToArray();
            return ret;
        }
        static long[] ReadLong()
        {
            long[] ret = Console.ReadLine().Split().Select(long.Parse).ToArray();
            return ret;
        }
    }

    class RollingHash
    {
        const long B = 100007;
        const long mod = 1000000009;
        string S;
        int N;
        ulong[] Power;
        ulong[] Hash;
        public RollingHash(string s)
        {
            S = s;
            N = s.Length;

            Power = new ulong[N + 1];
            Power[0] = 1;
            for (int i = 0; i < N; i++)
            {
                Power[i + 1] = (Power[i] * B) % mod;
            }

            Hash = new ulong[N + 1];
            for (int i = 0; i < N; i++)
            {
                Hash[i + 1] = (Hash[i] * B + S[i]) % mod;
            }
        }
        // S[l, r) のハッシュ値を求める
        public ulong Get(int l, int r)
        {
            var hash = Hash[r] - (Hash[l] * Power[r - l] % mod);
            return hash;
        }
    }
}

