public class Program
{
    string S, T;
    string SS;

    public void Solve()
    {
        var sc = new Scanner();
        S = sc.Next();
        T = sc.Next();
        var sb = new StringBuilder();
        while (sb.Length < T.Length * 2)
        {
            sb.Append(S);
        }
        S = sb.ToString();
        SS = S + S;

        var kmp = new KMP(T.ToCharArray());
        bool[] table = kmp.Calc(SS.ToCharArray());


        long[] len = new long[S.Length];


        for (int i = 0; i < T.Length; i++)
        {
            len[i] = table[i] ? 1 : 0;
        }
        for (int i = T.Length; i < S.Length; i++)
        {
            len[i] = table[i] ? len[i - T.Length] + 1 : 0;
        }

        for (int i = 0; i < S.Length; i++)
        {
            int prev = (i - T.Length) % S.Length;
            if (prev < 0) prev += S.Length;
            len[i] = table[i] ? len[prev] + 1 : 0;
        }

        // 2週目でも更新するなら
        for (int i = 0; i < S.Length; i++)
        {
            int prev = (i - T.Length) % S.Length;
            if (prev < 0) prev += S.Length;
            long t = table[i] ? len[prev] + 1 : 0;
            if(t != len[i])
            {
                Console.WriteLine(-1);
                return;
            }
        }

        Console.WriteLine(len.Max());
    }

    public static void Main(string[] args) => new Program().Solve();
}
namespace CompLib.Collections
{
    using Num = Char;
    class KMP
    {
        private Num[] _pattern;
        private int[] _table;
        public KMP(Num[] pattern)
        {
            _pattern = pattern;
            _table = new int[pattern.Length + 1];
            _table[0] = 0;
            var j = 0;
            for (int i = 1; i < pattern.Length; i++)
            {
                if (pattern[i] == pattern[j])
                {
                    _table[i] = j++;
                }
                else
                {
                    _table[i] = j;
                    j = 0;
                }
            }
            _table[pattern.Length] = j;
        }

        // result[i] target[i]以降がpatternに一致する
        public bool[] Calc(Num[] target)
        {
            var result = new bool[target.Length];
            int i = 0, p = 0;
            while (i < target.Length)
            {
                // 一致してたら次に

                if (p == _pattern.Length)
                {
                    result[i - p] = true;
                    p = _table[p];
                }
                else if (target[i] == _pattern[p])
                {
                    i++;
                    p++;
                }
                else if (p == 0)
                {
                    i++;
                }
                else
                {
                    p = _table[p];
                }
            }

            if (p == _pattern.Length)
            {
                result[i - p] = true;
            }

            return result;
        }
    }
}
