        public class PriorityQueue<T> where T : IComparable
        {
            List<T> buffer = new List<T>();
            static void PushHeap(List<T> array, T elem)
            {
                int n = array.Count;
                array.Add(elem);

                while (n != 0)
                {
                    int i = (n - 1) / 2;
                    if (array[n].CompareTo(array[i]) > 0)
                    {
                        T tmp = array[n]; array[n] = array[i]; array[i] = tmp;
                    }
                    n = i;
                }
            }
            static void PopHeap(List<T> array)
            {
                int n = array.Count - 1;
                array[0] = array[n];
                array.RemoveAt(array.Count - 1);

                for (int i = 0, j; (j = 2 * i + 1) < n;)
                {
                    if ((j != n - 1) && (array[j].CompareTo(array[j + 1]) < 0))
                        j++;
                    if (array[i].CompareTo(array[j]) < 0)
                    {
                        T tmp = array[j]; array[j] = array[i]; array[i] = tmp;
                    }
                    i = j;
                }
            }
            public int Count
            {
                get
                {
                    return buffer.Count;
                }
            }
            public void Push(T elem)
            {
                PushHeap(this.buffer, elem);
            }
            public T Peek()
            {
                return buffer[0];
            }

            public T Pop()
            {
                T a = buffer[0];
                PopHeap(this.buffer);
                return a;
            }
        }
        public class KMP
        {
            int[] Table;
            string a;
            int m = 0;
            int i = 0;
            public KMP(string a)
            {
                this.a = a;
                Table = new int[a.Length];
                int subindex = 0;

                Table[0] = -1;
                Table[1] = 0;

                for (int i = 2; i < a.Length;)
                {
                    if (a[i - 1] == a[subindex])
                    {
                        subindex++;
                        Table[i] = subindex;
                        i++;
                    }
                    else if (subindex > 0)
                        subindex = Table[subindex];
                    else
                    {
                        Table[i] = 0;
                        i++;
                    }
                }
            }
            public int Search(string b)
            {
                m++;
                i = 0;
                while (m + i < b.Length)
                {
                    if (a[i] == b[m + i])
                    {
                        i++;
                        if (i == a.Length)
                            return m;
                    }
                    else
                    {
                        m = m + i - Table[i];
                        if (i > 0)
                            i = Table[i];
                    }
                }
                return -1;
            }
        }
    }
