    class RollingHash
    {
        const long base1 = 1009;
        const long base2 = 2009;
        const long mod1 = 1000000007;
        const long mod2 = 1000000009;
        long[] hash1, hash2, pow1, pow2;

        public RollingHash(string S)
        {
            int n = S.Length;
            hash1 = new long[n + 1];
            hash2 = new long[n + 1];
            pow1 = new long[n + 1];
            pow2 = new long[n + 1];
            pow1[0] = 1;
            pow2[0] = 1;

            for (int i = 0; i < n; ++i)
            {
                hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
                hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
                pow1[i + 1] = (pow1[i] * base1) % mod1;
                pow2[i + 1] = (pow2[i] * base2) % mod2;
            }
        }

        /**
         * S の [l, r) のハッシュ値を返す
         * O(1)
         */
        public long[] Get(int l, int r)
        {
            long res1 = hash1[r] - hash1[l] * pow1[r - l] % mod1;
            if (res1 < 0) res1 += mod1;
            long res2 = hash2[r] - hash2[l] * pow2[r - l] % mod2;
            if (res2 < 0) res2 += mod2;
            return new long[] { res1, res2 };
        }

        /**
         * S のハッシュ値を返す
         * O(1)
         */
        public long[] Hash()
        {
            return Get(0, hash1.Length - 1);
        }

        /**
         * LCP (Longest Common Prefix)
         * O( log N )
         */
        public int GetLCP(int a, int b)
        {
            int len = Math.Min(hash1.Length - a, hash1.Length - b);
            int low = 0, high = len;
            while (high - low > 1)
            {
                int mid = (low + high) >> 1;
                if (Get(a, a + mid) != Get(b, b + mid)) high = mid;
                else low = mid;
            }
            return low;
        }

        /**
         * hash h1 と 長さ h2_len の文字列の hash h2 を結合
         */
        long[] concat(long[] h1, long[] h2, int h2_len)
        {
            return new long[] { (h1[0] * pow1[h2_len] + h2[0]) % mod1, (h1[1] * pow2[h2_len] + h2[1]) % mod2 };
        }
    }
}

class UnionFind
{
    int[] par;
    int[] rank;
    int[] count;

    public UnionFind(int n)
    {
        Init(n);
    }

    void Init(int n)
    {
        par = new int[n];
        rank = new int[n];
        count = new int[n].Select(x => 1).ToArray();

        for (int i = 0; i < n; i++)
        {
            par[i] = i;
        }
    }

    public int Find(int x)
    {
        if (par[x] == x)
        {
            return x;
        }
        else
        {
            return par[x] = Find(par[x]);
        }
    }

    public bool Unite(int x, int y)
    {
        x = Find(x);
        y = Find(y);
        if (x == y) return false; //すでに要素を追加済みの場合、falseを返す。

        if (rank[x] < rank[y])
        {
            par[x] = y;
            count[y] += count[x];
        }
        else
        {
            par[y] = x;
            count[x] += count[y];
            if (rank[x] == rank[y]) rank[x]++;
        }
        return true;
    }
    public bool Same(int x, int y)
    {
        return Find(x) == Find(y);
    }

    public int Size(int x)
    {
        return count[Find(x)];
    }
}

using CompLib.Util;
using System;
using System.Linq;

public class Program
{
    string S;
    string T;

    int[] Next;

    long[] Memo;
    bool[] Flag;

    private bool Len(int i, out long res)
    {
        if (Memo[i] == -1)
        {
            if (Next[i] != -1)
            {
                int next = Next[i];
                Flag[i] = true;
                if (Flag[next])
                {
                    res = -1;
                    return false;
                }
                long o;
                if (Len(next, out o))
                {
                    Memo[i] = o + 1;
                }
                else
                {
                    res = -1;
                    return false;
                }
                Flag[i] = false;
            }
            else
            {
                Memo[i] = 0;
            }
        }
        res = Memo[i];
        return true;
    }

    public void Solve()
    {
        var sc = new Scanner();
        S = sc.Next();
        T = sc.Next();

        // S[i]から開始してTと一致
        // i -> i+|T|に辺を張る

        int[] table = new int[T.Length + 1];
        table[0] = 0;

        int j = 0;
        for (int i = 1; i < T.Length; i++)
        {
            if (T[j] == T[i])
            {
                table[i] = j++;
            }
            else
            {
                table[i] = j;
                j = 0;
            }
        }

        table[T.Length] = j;

        Next = new int[S.Length];

        for (int i = 0; i < S.Length; i++)
        {
            Next[i] = -1;
        }

        int p = 0;
        for (int i = 0; i < S.Length + T.Length;)
        {
            if (p == T.Length)
            {
                Next[(i - p) ] = i % S.Length;
                p = table[p];
            }
            else if (S[i % S.Length] == T[p])
            {
                i++;
                p++;
            }
            else if (p == 0)
            {
                i++;
            }
            else
            {
                p = table[p];
            }
        }
        // Console.WriteLine(string.Join(" ", Next));
        Memo = new long[S.Length];
        for (int i = 0; i < S.Length; i++)
        {
            Memo[i] = -1;
        }

        Flag = new bool[S.Length];

        long max = 0;
        for (int i = 0; i < S.Length; i++)
        {
            long o;
            if (Len(i, out o))
            {
                max = Math.Max(max, o);
            }
            else
            {
                Console.WriteLine(-1);
                return;
            }
        }
        Console.WriteLine(max);
    }

