    class RollingHash
    {
        long B;
        ulong BU;
        const long mod = 100000009;
        string S;
        int N;
        long[] Power;
        ulong[] PowerU;
        long[] Hash;
        ulong[] HashU;
        public RollingHash(string s, long rand)
        {
            B = rand;
            BU = (ulong)rand;
            //B = 100007;

            S = s;
            N = s.Length;

            Power = new long[N + 1];
            PowerU = new ulong[N + 1];
            Power[0] = 1;
            PowerU[0] = 1;
            for (int i = 0; i < N; i++)
            {
                Power[i + 1] = (Power[i] * B) % mod;
                PowerU[i + 1] = PowerU[i] * BU;
            }

            Hash = new long[N + 1];
            HashU = new ulong[N + 1];
            for (int i = 0; i < N; i++)
            {
                Hash[i + 1] = (Hash[i] * B % mod + S[i]) % mod;
                HashU[i + 1] = HashU[i] * BU + S[i];
            }
        }
        // S[l, r) のハッシュ値を求める
        public long Get(int l, int r)
        {
            var hash = Hash[r] - ((Hash[l] * Power[r - l]) % mod);
            return hash;
        }
        public ulong GetU(int l, int r)
        {
            var hash = HashU[r] - HashU[l] * PowerU[r - l];
            return hash;
        }
    }
