class KMP // https://algoful.com/Archive/Algorithm/KMPSearch
{
    string pattern;
    int[] table;
    public KMP(string pattern) { this.pattern = pattern; table = CreateTable(pattern); }
    static int[] CreateTable(string pattern)
    {
        var table = new int[pattern.Length + 1];
        int j = 0;
        for (int i = 1; i < table.Length; i++)
        {
            if (i < pattern.Length && pattern[i] == pattern[j])
                table[i] = j++;
            else
            {
                table[i] = j;
                j = 0;
            }
        }
        return table;
    }

    public IEnumerable<int> Matches(string target)
    {
        int i = 0, p = 0;
        while (i < target.Length && p < pattern.Length)
        {
            if (target[i] == pattern[p])
            {
                // 文字が一致していれば次の文字に進む
                i++; p++;
            }
            else if (p == 0)
            {
                // パターン先頭文字が不一致の場合、次の文字
                i++;
            }
            else
            {
                // 不一致の場合、パターンのどの位置から再開するか設定
                p = table[p];
            }

            if (p == pattern.Length)
            {
                yield return i - p;
                p = table[p];
            }
        }
    }
}
class UnionFind
{
    int[] data;
    public UnionFind(int size)
    {
        this.data = NewArray(size, -1);
    }

    public int Root(int x)
    {
        if (data[x] < 0) return x;
        return data[x] = Root(data[x]);
    }
    public int Count(int x) => -data[Root(x)];
    public void UnionSet(int x, int y) => TryUnionSet(x, y);
    public bool TryUnionSet(int x, int y)
    {
        var xRoot = Root(x);
        var yRoot = Root(y);
        if (xRoot == yRoot) return false;
        else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
        {
            var tmp = yRoot;
            yRoot = xRoot;
            xRoot = tmp;
        }
        data[xRoot] += data[yRoot];
        data[yRoot] = xRoot;
        return true;
    }
    public bool IsSameSet(int x, int y) => Root(x) == Root(y);
}

