static class Ex2{
	public static void Rh(this string a,string s,int b,int mod,Action<int> f){
		int n=a.Length,m=s.Length;
		long r=Hs(a,b,mod,m),h=Hs(s,b,mod),c=Fp(b,m,mod);
		if(r==h){f(0);}
		for(int i=m;i<n;i++){
			r=(r*b+(a[i]-47))%mod;
			r=(mod+r-(((a[i-m]-47)*c)%mod))%mod;
			if(r==h){f(i-m+1);}
		}
	}
	public static long Hs(string s,int a,int mod){
		int n=s.Length;
		long p=0;
		for(int i = 0;i<n;i++) {p=(p+(s[i]-47)*Fp(a,n-1-i,mod))%mod;}
		return p;
	}
	public static long Hs(string s,int a,int mod,int n){
		long p=0;
		for(int i = 0;i<n;i++) {p=(p+(s[i]-47)*Fp(a,n-1-i,mod))%mod;}
		return p;
	}
	private static long Fp(long x,long e,int mod){
		long r=1;
		while(e>0){
			if((e&1)>0){r*=x;r%=mod;}
			x=(x*x)%mod;
			e>>=1;
		}
		return r;
	}
}

