        int ans = -1;
        for (int i = 0; i < S.Length; i++)
        {
            int r = Calc(i);
            if (r == -1)
            {
                Console.WriteLine(-1);
                return;
            }

            ans = Math.Max(ans, r);
        }
        Console.WriteLine(ans);
    }

    private int Calc(int i)
    {
        if (Memo[i] != -1)
        {
            return Memo[i];
        }

        if (B[i])
        {
            return -1;
        }

        if (Match[i])
        {
            B[i] = true;
            int result = Calc((i + T.Length) % S.Length);
            B[i] = false;
            if (result == -1)
            {
                return -1;
            }
            else
            {
                Memo[i] = result + 1;
                return result + 1;
            }
        }
        else
        {
            Memo[i] = 0;
            return 0;
        }

    }

