            N = s.Length;

            Power = new ulong[N + 1];
            Power[0] = 1;
            for (int i = 0; i < N; i++)
            {
                Power[i + 1] = Power[i] * B;
            }

            Hash = new ulong[N + 1];
            for (int i = 0; i < N; i++)
            {
                Hash[i + 1] = Hash[i] * B + S[i];
            }
        }
        // S[l, r) のハッシュ値を求める
