	public static long Hs(string s,int a,int mod){
		int n=s.Length;
		long p=0;
		for(int i = 0;i<n;i++) {p=(p+(s[i]-47)*Fp(a,n-1-i,mod))%mod;}
		return p;
	}
	public static long Hs(string s,int a,int mod,int n){
		long p=0;
		for(int i = 0;i<n;i++) {p=(p+(s[i]-47)*Fp(a,n-1-i,mod))%mod;}
		return p;
	}
	private static long Fp(long x,long e,int mod){
		long r=1;
		while(e>0){
			if((e&1)>0){r*=x;r%=mod;}
			x=(x*x)%mod;
			e>>=1;
		}
		return r;
	}
}

