// 2つ以上のRHで確認する時はGetHashの積かなにかをつかう（xor，pairはダメ!!!）
class RollingHash{

	long[] Hash;
	long[] Base;
	long[] BaseInv;
	String S;
	long mod;
	int N;

	public RollingHash(String s_,long base_=2525,long mod_=(long)1e9+7){
		mod=mod_;
		S=s_;
		N=S.Length;
		Hash=new long[N+1];

		Base=new long[N+1];
		Base[0]=1;
		Base[1]=base_;

		BaseInv=new long[N+1];
		BaseInv[0]=1;
		BaseInv[1]=ModInv(Base[1]);

		for(int i=1;i<N;i++){
			Base[i+1]=Base[i]*Base[1];
			if(Base[i+1]>=mod)Base[i+1]%=mod;
			BaseInv[i+1]=BaseInv[i]*BaseInv[1];
			if(BaseInv[i+1]>=mod)BaseInv[i+1]%=mod;
		}

		Hash[0]=0;
		Hash[1]=(long)S[0];
		for(int i=1;i<N;i++){
			Hash[i+1]=Hash[i]*Base[1]+(long)S[i];
			if(Hash[i+1]>=mod)Hash[i+1]%=mod;
		}
//for(int i=0;i<=N;i++)Console.WriteLine("{0}:{1}",i,Hash[i]);
	}

	public long GetHash(int strt,int len){
		//return hash of S.Substring(strt,len);
		if(len==0)return 0;
		if(strt+len>=N)len=N-strt;
		long ret=Hash[strt+len]+mod-(Hash[strt]*Base[len]>=mod?Hash[strt]*Base[len]%mod:Hash[strt]*Base[len]);
		return ret>=mod?ret%mod:ret;
	}




	public long ModInv(long x){
		//Mod-Inverse of x by Ext-Euclid
		// solve (x,mod)-->(a,b,c) s.t. a * x + b * mod = c 
		//  if(x==0 || c!=1) return 0;
		//  return a (since a * x == 1 modulo mod)
		long a=0,b=0,c=0;
		if(x==0)return 0;
		ExtGCD(x,mod,ref a,ref b,ref c);
		if(c!=1)return 0;
		return (a+mod)%mod;
	}

	public static void ExtGCD(long x,long y,ref long a,ref long b,ref long c){
		long r0=x;long r1=y;
		long a0=1;long a1=0;
		long b0=0;long b1=1;
		long q1,r2,a2,b2;
		while(r1>0){
			q1=r0/r1;
			r2=r0%r1;
			a2=a0-q1*a1;
			b2=b0-q1*b1;
			r0=r1;r1=r2;
			a0=a1;a1=a2;
			b0=b1;b1=b2;
		}
		c=r0;
		a=a0;
		b=b0;
	}




}

