        public IEnumerable<string> Solve()
        {
            var s = Str;
            var t = Str;

            var slen = s.Length;
            var tlen = t.Length;

            var res = 0;
            var si = 0;
            // si, ti
            List<int> dp = new List<int>();

            while (true)
            {
                var ndp = new List<int>();

                var simod = si % slen;
                var first = s[simod] == t[0];
                if (first)
                    ndp.Add(0);

                foreach (var prev in dp)
                {
                    var timod = (prev + 1) % tlen;
                    if (s[simod] == t[timod])
                        ndp.Add(prev + 1);
                }

                if (ndp.Count > 0)
                {
                    var cand = ndp[ndp.Count - 1] + 1;
                    if (cand % tlen == 0)
                        res = Math.Max(cand / tlen, res);

                    if (cand % tlen == 1 && first)
                    {
                        res = -1;
                        break;
                    }
                }

                if (slen <= tlen && si > slen + tlen)
                    break;

                if (slen > tlen && si > slen * 2)
                    break;

                dp = ndp;
                si++;
            }


            yield return res.ToString();
        }
    }

