    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var s = cr.Ascii;
        var t = cr.Ascii;
        var sb = new StringBuilder((s.Length + t.Length) << 1);
        while (sb.Length < s.Length + t.Length) sb.Append(s);
        sb.Append(s);
        var ss = sb.ToString();

        var oks = new bool[s.Length];
        var matches = new KMP(t).Matches(ss).Where(i => i < s.Length).ToArray();
        if (matches.Length == 0) return 0;
        foreach (var i in matches)
            oks[i] = true;

        var uf = new UnionFind(s.Length);
        for (int i = 0; i < oks.Length; i++)
        {
            if (oks[i] && oks[(i + t.Length) % oks.Length])
            {
                if (!uf.TryUnionSet(i, (i + t.Length) % oks.Length))
                    return -1;
            }
        }


        return Enumerable.Range(0, s.Length).Max(i => uf.Count(i));
    }
