class RollingHash
{
    const int BASE = 9973;
    readonly int[] mod = new[] { 999999937, 1000000007 };
    readonly long[][] hash, power;

    public RollingHash(string s)
    {
        hash = new long[2][];
        power = new long[2][];
        for (int iter = 0; iter < mod.Length; iter++)
        {
            hash[iter] = new long[s.Length + 1];
            power[iter] = new long[s.Length + 1];
            power[iter][0] = 1;
            for (int i = 0; i < s.Length; i++)
            {
                hash[iter][i + 1] = (hash[iter][i] * BASE + s[i]) % mod[iter];
                power[iter][i + 1] = power[iter][i] * BASE % mod[iter];
            }
        }
    }
    /// <summary>
    /// [l, r)のハッシュ値 0-indexed
    /// </summary>
    /// <param name="l"></param>
    /// <param name="r"></param>
    /// <param name="id"></param>
    /// <returns></returns>
    public long this[int l, int r, int id = 0]
    {
        get
        {
            long ret = hash[id][r] - hash[id][l] * power[id][r - l] % mod[id];
            if (ret < 0) ret += mod[id];
            return ret;
        }
    }
}

/// <summary>
/// 高速だが、悪意のあるケースでハッシュ衝突
/// </summary>
class RollingHash64
{
    const int BASE = 9973;
    readonly long[] hash, power;

    public RollingHash64(string s)
    {
        hash = new long[s.Length + 1];
        power = new long[s.Length + 1];
        power[0] = 1;
        for (int i = 0; i < s.Length; i++)
        {
            hash[i + 1] = hash[i] * BASE + s[i];
            power[i + 1] = power[i] * BASE;
        }
    }
    /// <summary>
    /// [l, r)のハッシュ値 0-indexed
    /// </summary>
    /// <param name="l"></param>
    /// <param name="r"></param>
    /// <returns></returns>
    public long this[int l, int r] => hash[r] - hash[l] * power[r - l];
}

/// <OriginalAuthor>camypaper</OriginalAuthor>
class DisjointSet
{
    readonly int[] par;
    readonly byte[] rank;
    /// <summary>
    /// 0 から <paramref name="N"/>-1 までの番号がついた <paramref name="N"/> 個の要素からなる集合を作成します．
    /// </summary>
    /// <param name="N">要素数</param>
    /// <remarks>このコンストラクタは O(N) で実行されます．</remarks>
    public DisjointSet(int N)
    {
        par = new int[N];
        rank = new byte[N];
        for (int i = 0; i < N; i++) par[i] = -1;
    }
    /// <summary>
    /// 指定した要素が属する集合の代表値を取得します．
    /// </summary>
    /// <param name="id">調べたい要素の 0-indexed での番号</param>
    /// <returns>指定した要素が属する集合の代表値</returns>
    /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
    public int this[int id]
    {
        get
        {
            if (par[id] < 0) return id;
            return par[id] = this[par[id]];
        }
    }
    /// <summary>
    /// 指定した 2 つの要素が属する集合同士を 1 つに統合することを試みます．
    /// </summary>
    /// <param name="x">最初の要素の 0-indexed での番号</param>
    /// <param name="y">2 つ目の要素の 0-indexed での番号</param>
    /// <returns>統合に成功したならば true，そうでなければ false．</returns>
    /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
    public bool Unite(int x, int y)
    {
        x = this[x]; y = this[y];
        if (x == y) return false;
        if (rank[x] < rank[y]) { var tmp = x; x = y; y = tmp; }
        par[x] += par[y];
        par[y] = x;
        if (rank[x] == rank[y])
            rank[x]++;
        return true;
    }
    /// <summary>
    /// 指定した要素が属する集合のサイズを取得します．
    /// </summary>
    /// <param name="x">指定する要素の 0-indexed での番号</param>
    /// <returns>集合のサイズ</returns>
    /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
    public int Size(int x) => -par[this[x]];

    /// <summary>
    /// 指定した 2 つの要素が属する集合が同じかどうかを判定する．計算量 O(α(N))．
    /// </summary>
    /// <param name="x">最初の要素の 0-indexed での番号</param>
    /// <param name="y">2 つ目の要素の 0-indexed での番号</param>
    /// <returns>同じならば true，そうでなければ false．</returns>
    /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
    public bool Same(int x, int y) => this[x] == this[y];
}

