		{
			var p = t_sub[i - 1];
			t_sub[i] = p > -1 && t[i] == t[p + 1] ? p + 1 : t[i] == t[0] ? 0 : -1;
		}

		var st = new bool[s.Length];
		for (int i = 0, j = 0; i < s.Length;)
		{
			for (; ; j++)
			{
