			}

			if (j == -1)
			{
				i++;
				j = 0;
			}
			else if (t_sub[j] == -1)
			{
				i += j + 1;
				j = 0;
			}
			else
			{
				i += j - t_sub[j];
				j = t_sub[j] + 1;
			}
		}

		var M = 0;
