namespace AtTest.ABC_135
{
    class F
    {
        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false };
            SetOut(sw);

            Method(args);

            Out.Flush();
        }

        static void Method(string[] args)
        {
            string s = Read();
            string t = Read();
            string ss = s;

            while (ss.Length < s.Length + t.Length - 1) ss += s;
            RollingHash rollingHash = new RollingHash(ss);
            long[] hash = rollingHash.GetStringHash(t);
            List<int>[] graph = new List<int>[s.Length];
            for (int i = 0; i < s.Length; i++) graph[i] = new List<int>();
            for (int i = 0; i < s.Length; i++)
            {
                if (rollingHash.ValidateRange(i, t.Length, hash))
                {
                    graph[i].Add((i + t.Length) % s.Length);
                }
            }
            bool[] visits = new bool[s.Length];
            int res = 0;
            for(int i = 0; i < s.Length; i++)
            {
                if (visits[i]) continue;

                int tmp = 0;
                int now = i;
                while (graph[now].Count > 0)
                {
                    tmp++;
                    now = graph[now][0];
                    if (now == i)
                    {
                        WriteLine(-1);
                        return;
                    }
                }
                res = Max(res, tmp);
            }
            WriteLine(res);
        }

        class RollingHash
        {
            long mod = 1000000007;
            long[] bases = new long[3] { 1009, 2003, 3001 };
            long[,] pows;
            long[,] hashes;

            public RollingHash(string s)
            {
                pows = new long[s.Length, bases.Length];
                hashes = new long[s.Length, bases.Length];

                for (int i = 0; i < s.Length; i++)
                {
                    for (int j = 0; j < bases.Length; j++)
                    {
                        if (i == 0) pows[i, j] = 1;
                        else pows[i, j] = (pows[i - 1, j] * bases[j]) % mod;
                    }
                }

                for (int i = 0; i < s.Length; i++)
                {
                    for (int j = 0; j < bases.Length; j++)
                    {
                        if (i > 0) hashes[i, j] = (hashes[i - 1, j] * bases[j]) % mod;
                        hashes[i, j] += s[i];
                        hashes[i, j] %= mod;
                    }
                }
            }

            public long[] GetRangeHash(int l, int r)
            {
                long[] hash = new long[bases.Length];
                for (int i = 0; i < bases.Length; i++)
                {
                    hash[i] = hashes[r, i];
                    if (l > 0)
                    {
                        hash[i] += mod - (hashes[l - 1, i] * pows[r - l + 1, i]) % mod;
                        hash[i] %= mod;
                    }
                }
                return hash;
            }

            public bool ValidateRange(int l, int length, long[] hash)
            {
                int r = l + length - 1;
                long[] rangeHash = GetRangeHash(l, l + length - 1);
                for (int i = 0; i < bases.Length; i++)
                {
                    if (rangeHash[i] != hash[i]) return false;
                }
                return true;
            }

            public long[] GetStringHash(string s)
            {
                long[] vals = new long[bases.Length];
                for (int i = 0; i < s.Length; i++)
                {
                    for (int j = 0; j < bases.Length; j++)
                    {
                        vals[j] = (vals[j] * bases[j] + s[i]) % mod;
                    }
                }

                return vals;
            }

            public string ToHashString(long[] hash)
            {
                string val = "";
                for (int i = 0; i < bases.Length; i++) val += hash[i].ToString();
                return val;
            }
        }

        private static string Read() { return ReadLine(); }
        private static char[] ReadChars() { return Array.ConvertAll(Read().Split(), a => a[0]); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }
    }
}

using System;
using System.Linq;
using System.Text;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private string S;
    private string T;

    private const long P1 = 1000000007;
    private const long P2 = 998244353;

    public void Solve()
    {
        var sc = new Scanner();
        S = sc.Next();
        T = sc.Next();

        // ローリングハッシュ
        long hashT1 = 0;
        long hashT2 = 0;
        for (int i = 0; i < T.Length; i++)
        {
            hashT1 *= 26;
            hashT1 += T[i] - 'a';
            hashT1 %= P1;

            hashT2 *= 26;
            hashT2 += T[i] - 'a';
            hashT2 %= P2;
        }

        long[] hashS1 = new long[S.Length];
        long[] hashS2 = new long[S.Length];


        // 26^|T|
        long m1 = 1;
        long m2 = 1;

        for (int i = 0; i < T.Length; i++)
        {
            hashS1[0] *= 26;
            hashS1[0] += S[i % S.Length] - 'a';
            hashS1[0] %= P1;
            m1 *= 26;
            m1 %= P1;

            hashS2[0] *= 26;
            hashS2[0] += S[i % S.Length] - 'a';
            hashS2[0] %= P2;

            m2 *= 26;
            m2 %= P2;
        }


        for (int i = 0; i < S.Length - 1; i++)
        {
            hashS1[i + 1] = hashS1[i] * 26;
            hashS1[i + 1] += S[(i + T.Length) % S.Length] - 'a';
            hashS1[i + 1] -= (S[i] - 'a') * m1;
            hashS1[i + 1] %= P1;
            if (hashS1[i + 1] < 0) hashS1[i + 1] += P1;

            hashS2[i + 1] = hashS2[i] * 26;
            hashS2[i + 1] += S[(i + T.Length) % S.Length] - 'a';
            hashS2[i + 1] -= (S[i] - 'a') * m2;
            hashS2[i + 1] %= P2;
            if (hashS2[i + 1] < 0) hashS2[i + 1] += P2;
        }

        bool[] f = new bool[S.Length];
        for (int i = 0; i < S.Length; i++)
        {
            f[i] = hashS1[i] == hashT1 && hashS2[i] == hashT2;
        }

        // f_b, f_{b+|t|} ... f_{b+(i-1)|t|}がtrue

        // 一致する位置が無い
        if (!f.Any(b => b))
        {
            Console.WriteLine("0");
            return;
        }

        long gcd = MathEx.GCD(S.Length, T.Length);
        bool[] a = new bool[gcd];
        for (int i = 0; i < S.Length; i++)
        {
            if (!f[i]) a[i % gcd] = true;
        }

        if (a.Any(b => !b))
        {
            Console.WriteLine("-1");
            return;
        }

        long ans = long.MinValue;
        for (int b = 0; b < S.Length; b++)
        {
            // 前は一致しない
            int prev = (b - T.Length) % S.Length;
            if (prev < 0) prev += S.Length;
            if (f[prev]) continue;

            int cur = b;
            long cnt = 0;
            while (f[cur])
            {
                cnt++;
                cur += T.Length;
                cur %= S.Length;
            }

            ans = Math.Max(ans, cnt);
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

