using System;


public class Program
{
    private string S, T;
    private bool[] Match, B;
    private int SLength;
    private int[] Memo;

    public void Solve()
    {
        var sc = new Scanner();
        S = sc.Next();
        T = sc.Next();
        SLength = S.Length;
        Match = new bool[SLength];
        B = new bool[SLength];
        Memo = new int[SLength];
        for (int i = 0; i < SLength; i++)
        {
            Memo[i] = -1;
        }

        string tmpS = S;
        while (S.Length < T.Length + SLength - 1)
        {
            S += tmpS;
        }

        for (int i = 0; i < SLength; i++)
        {
            var subS = S.Substring(i, T.Length);
            if (subS == T)
            {
                Match[i] = true;
            }
        }

        int max = 0;
        for (int i = 0; i < SLength; i++)
        {
            int c = Calc(i);
            if (c == -1)
            {
                Console.WriteLine(-1);
                return;
            }

            max = Math.Max(max, c);

        }
        Console.WriteLine(max);
    }

    // iから初めていくつ繋げられるか
    private int Calc(int i)
    {
        if (B[i])
        {
            return -1;
        }

        if (Memo[i] != -1)
        {
            return Memo[i];
        }

        if (!Match[i])
        {
            Memo[i] = 0;
            return 0;
        }
        else
        {
            B[i] = true;
            int result = Calc((i + T.Length) % SLength);
            B[i] = false;
            if (result == -1)
            {
                return -1;
            }

            Memo[i] = result + 1;
            return result + 1;
        }
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

