    class RollingHash
    {
        const long B = 1000000009;
        string S;
        int N;
        ulong[] Power;
        ulong[] Hash;
        public RollingHash(string s)
        {
            S = s;
            N = s.Length;

            Power = new ulong[N + 1];
            Power[0] = 1;
            for (int i = 0; i < N; i++)
            {
                Power[i + 1] = Power[i] * B;
            }

            Hash = new ulong[N + 1];
            for (int i = 0; i < N; i++)
            {
                Hash[i + 1] = Hash[i] * B + S[i];
            }
        }
        // S[l, r) のハッシュ値を求める
        public ulong Get(int l, int r)
        {
            var hash = Hash[r] - Hash[l] * Power[r - l];
            return hash;
        }
    }
}

