public static class Kmp {
    public static int[] CreateKmpTable(string s) {
        int[] table = new int[s.Length];
        table[0] = 0;
        for (int i = 1; i < s.Length; i++) {
            int failure = table[i - 1];
            while (failure > 0 && s[i] != s[failure]) {
                failure = table[failure - 1];
            }

            if (s[i] == s[failure]) {
                failure++;
            }

            table[i] = failure;
        }
        return table;
    }

    public static List<int> GetMatchIndexes(string s, string pattern) {
        return GetMatchIndexes(s, CreateKmpTable(pattern), pattern);
    }

    public static List<int> GetMatchIndexes(string s, int[] kmpTable, string pattern) {
        int k = 0;
        var matchIndex = new List<int>();
        for (var i = 0; i < s.Length; i++) {
            while (k > 0 && pattern[k] != s[i]) {
                k = kmpTable[k - 1];
            }

            if (pattern[k] == s[i] && ++k == pattern.Length) {
                matchIndex.Add(i - pattern.Length + 1);
                k = kmpTable[k - 1];
            }
        }
        return matchIndex;
    }
}

