public class Program
{
    string S, T;
    string SS;

    long[] Memo;

    bool[] Table;

    bool[] Flag;

    long Len(int index)
    {
        if (Memo[index] == -1)
        {
            if (Table[index])
            {
                int next = (index + T.Length) % S.Length;
                Flag[index] = true;
                Memo[index] = Flag[next] ? int.MaxValue : Len(next) + 1;
                Flag[index] = false;
            }
            else
            {
                Memo[index] = 0;
            }
        }
        return Memo[index];
    }

    public void Solve()
    {
        var sc = new Scanner();
        S = sc.Next();
        T = sc.Next();

        var sb = new StringBuilder();
        while (sb.Length < T.Length)
        {
            sb.Append(S);
        }
        S = sb.ToString();
        SS = S + S;

        var kmp = new KMP(T.ToCharArray());
        Table = kmp.Calc(SS.ToCharArray());

        Flag = new bool[S.Length];
        Memo = new long[S.Length];
        for (int i = 0; i < S.Length; i++)
        {
            Memo[i] = -1;
        }

        long max = 0;
        for (int i = 0; i < S.Length; i++)
        {
            max = Math.Max(max, Len(i));
        }

        Console.WriteLine(max >= int.MaxValue ? -1 : max);
    }

    public static void Main(string[] args) => new Program().Solve();
}
namespace CompLib.Collections
{
    using Num = Char;
    class KMP
    {
        private Num[] _pattern;
        private int[] _table;
        public KMP(Num[] pattern)
        {
            _pattern = pattern;
            _table = new int[pattern.Length + 1];
            _table[0] = 0;
            var j = 0;
            for (int i = 1; i < pattern.Length; i++)
            {
                if (pattern[i] == pattern[j])
                {
                    _table[i] = j++;
                }
                else
                {
                    _table[i] = j;
                    j = 0;
                }
            }
            _table[pattern.Length] = j;
        }

        // result[i] target[i]以降がpatternに一致する
        public bool[] Calc(Num[] target)
        {
            var result = new bool[target.Length];
            int i = 0, p = 0;
            while (i < target.Length)
            {
                // 一致してたら次に

                if (p == _pattern.Length)
                {
                    result[i - p] = true;
                    p = _table[p];
                }
                else if (target[i] == _pattern[p])
                {
                    i++;
                    p++;
                }
                else if (p == 0)
                {
                    i++;
                }
                else
                {
                    p = _table[p];
                }
            }

            if (p == _pattern.Length)
            {
                result[i - p] = true;
            }

            return result;
        }
    }
}
