    size = this.size = s.length;
    for(var j = 0; j < mod.length; j++){
      pow[j].length = hash[j].length = size+1;
      pow[j][0] = 1;
      hash[j][0] = 0;
      for(var i = 0; i < size; i++){
        pow[j][i+1] = pow[j][i]*base[j]%mod[j];
        hash[j][i+1] = (hash[j][i]*base[j]+s.charCodeAt(i))%mod[j];
      }
    }
  }
  RollingHash.prototype.has = function(s,k){
    var t = getStrHash(s);
    var len = s.length;
    var m = mod.length;
    var n = size - len + 1;
    for(var i = k; i < n; i++){
      if(get(i,i+len,0) === t[0]){
        var f = 1;
        for(var j = 1; j < m; j++){
          if(get(i,i+len,j) !== t[j])break;
          f++;
        }
        if(f === m)return i;
      }
    }
    return -1;
  };
  RollingHash.prototype.add = function(s){
    var oldSize = size;
    size = this.size = size + s.length;
    for(var j = 0; j < mod.length; j++){
      pow[j].length = hash[j].length = size+1;
      for(var i = oldSize; i < size; i++){
        pow[j][i+1] = pow[j][i]*base[j]%mod[j];
        hash[j][i+1] = (hash[j][i]*base[j]+s.charCodeAt(i-oldSize))%mod[j];
      }
    }
    return size;
  };
  function getStrHash(s){
    var r = [];
