    var t = hash[j][r] - mul(hash[j][l],pow[j][r-l],mod[j]);
    if(t < 0)t += mod[j];
    return t;
  }
  function mul(a,b,c){
    return ((a>>16)*b%c*65536+(a&65535)*b)%c;
  }
  return f;
})();

