function divisor(x){
  var r = [1];
  var m = Math.sqrt(x)|0;
  if(m*m === x)r.push(m);
  for(var i = 2; i < m; i++){
    if(x%i === 0){
      r.push(i,r/i);
    }
  }
  return r.sort((a,b)=>a-b);
}

