func main() {
  var s,t,ss,ts string
  fmt.Scan(&s,&t)
  n,m := len(s),len(t)
  ss = s+s
  for len(ss) < 2*m { ss += s }
  ts = t+ss
  z := z_algorithm(ts)
  ok := make([]bool,n)
  for i:=0;i<n;i++ {
    if z[m+i] >= m { ok[i] = true }
  }
  uf := NewUnionFind(n)
  for i:=0;i<n;i++ {
    if ok[i] && ok[(i+m)%n] {
      if uf.Same(i,(i+m)%n) { fmt.Println(-1);return }
      uf.Unite(i,(i+m)%n)
    }
  }
  ans := 0
  for i:=0;i<n;i++ {
    if !ok[i] { continue }
    tmp := uf.Size(i)
    if ans < tmp { ans = tmp }
  }
  fmt.Println(ans)
}
func z_algorithm(s string) []int {
  n := len(s)
  z := make([]int,n)
  z[0] = n
  for i,j:=1,0;i<n; {
    for i+j < n && s[j:j+1] == s[i+j:i+j+1] { j++ }
    z[i] = j
    if j == 0 { i++;continue }
    k := 1
    for ;i+k<n&&k+z[k]<j;k++ { z[i+k] = z[k] }
    i,j = i+k,j-k
  }
  return z
}
type UnionFind struct { par,rank,size []int }
func NewUnionFind(n int) UnionFind {
  par := make([]int,n)
  rank := make([]int,n)
  size := make([]int,n)
  for i:=0;i<n;i++ { par[i],size[i] = i,1 }
  return UnionFind{par,rank,size}
}
func(u UnionFind) Find(i int) int {
  if u.par[i] == i { return i }
  u.par[i] = u.Find(u.par[i])
  return u.par[i]
}
func(u UnionFind) Same(i,j int) bool { return u.Find(i) == u.Find(j) }
func(u UnionFind) Unite(i,j int) {
  i,j = u.Find(i),u.Find(j)
  if i == j { return }
  if u.rank[i] < u.rank[j] {
    u.par[i] = j
    u.size[j] += u.size[i]
  } else {
    u.par[j] = i
    u.size[i] += u.size[j]
    if u.rank[i] == u.rank[j] { u.rank[i]++ }
  }
}
func(u UnionFind) Size(i int) int { return u.size[u.Find(i)] }

