	s := getNextString(scanner)
	t := getNextString(scanner)

	ns := len(s)
	nt := len(t)
	ss := make([]string, (nt-1)/ns+1)

	for i := 0; i < len(ss); i++ {
		ss[i] = s
	}

	sss := fmt.Sprintf("%s%s", strings.Join(ss, ""), strings.Join(ss, ""))

	ok := make([]bool, ns)

	uni := make([]int, ns)
	mp := MP{}
	mp.init(t)
	m := 0
	for i := 0; i < ns; i++ {
		uni[i] = i
	}
	var o bool
	for i := 0; i < ns; i++ {
		o = true
		for m < nt {
			if t[m] != sss[i+m] {
				o = false
				break
			}
			m++
		}
		ok[i] = o
		if o {
			i += m - mp.table[m]
			m = mp.table[m]
			i--
			m++
			continue
		}
		for m >= 0 && t[m] != sss[i+m] {
			i += m - mp.table[m]
			m = mp.table[m]
		}
		i--
		m++
	}

	ans := 0
	var a, r, rr, j int
	for i := 0; i < ns; i++ {
		a = 0
		for j = i; ok[j%ns]; j += nt {
			r = root(i, uni)
			rr = root((j+nt)%ns, uni)
			if rr == i {
				fmt.Println(-1)
				return
			}
			if ok[rr] {
				uni[rr] = r
			}
			a++
		}
