		}
	}

	fmt.Println(ans)

	writer.Flush()
}

func root(i int, uni []int) int {
	if i == uni[i] {
		return i
	}

	uni[i] = root(uni[i], uni)
	return uni[i]
}

// MP ...
type MP struct {
	s     string
	table []int
}

func (mp *MP) init(s string) {
	mp.s = s
	n := len(s)
	table := make([]int, n+1)
	table[0] = -1
	j := -1
	for i := 0; i < n; i++ {
		for j >= 0 && s[i] != s[j] {
			j = table[j]
