			continue
		}

		next := (offset + len(t)) % len(s)

		if uf.same(offset, next) {
			io.Println(-1)
			return
		}

		uf.merge(offset, next)
		// a -> b -> c と offset が推移するとき、 a, b は match していて c は match しない
		// よって size-1 が match 数
		res = Max(res, uf.size(offset)-1)
	}

	io.Println(res)
