func GCD(a, b int) int {
  if a < b { a, b = b, a }
  if b == 0 { return a }
  return GCD(b, a % b)
}

func KMP(S, P string) []int {
  M := len(P)
  PMT := make([]int, M + 1)
  PMT[0] = -1
  for i, j := 2, 0; i <= M; {
    if P[i - 1] == P[j] {
      PMT[i] = j + 1
      i++
      j++
    } else if 0 < j {
      j = PMT[j]
    } else {
      i++
    }
  }
  K := make([]int, 0)
  for i, j := 0, 0; i + j < len(S); {
    if S[i + j] == P[j] {
      j++
      if j == M {
        K = append(K, i)
        i += M - PMT[M]
        j = PMT[j]
      }
    } else {
      i += j - PMT[j]
      if 0 < j { j = PMT[j] }
    }
  }
  return K
}

func Solve() {
  s := NextLine()
  t := NextLine()
  S, T := len(s), len(t)
  ss := s + s
  for len(ss) < 2 * T { ss += ss }
  K := KMP(ss, t)
  next := make([]int, S)
  for i := range next { next[i]-- }
  for _, k := range K {
    next[k % S] = (k + T) % S
  }
  A := make([]int, S)
  var pre int
  for i, v := range next {
    for v >= 0 {
      if v == i { A[i] = S + 1; break }
      A[i]++
      if A[v] > 0 { A[i] += A[v]; break}
      pre = v
      v = next[v]
      next[pre] = -1
    }
  }
  ans := MaxInt(A...)
  if ans > S { ans = -1 }
  Write(ans)
}

