func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	s := getNextString(scanner)
	t := getNextString(scanner)
	ssa := make([]string, len(t)*2/len(s)+2)
	for i := 0; i < len(ssa); i++ {
		ssa[i] = s
	}
	ss := strings.Join(ssa, "")

	ls := len(ss)
	lt := len(t)

	bb := make([]bool, ls-lt)
	tt := make([]int, ls-lt)

	for i := 0; i < ls-lt; i++ {
		bb[i] = ss[i:i+lt] == t
		tt[i] = i
	}

	ans := 0
	for i := 0; i < ls-lt; i++ {
		if !bb[i] {
			continue
		}
		temp := 0
		check := i
		for bb[check] {
			temp++
			next := (check + lt) % (ls - lt)
			if bb[next] {
				r2 := root(next, tt)
				if i == r2 {
					fmt.Println(-1)
					return
				}
				tt[r2] = i
			}
			check = next
		}
		if ans < temp {
			ans = temp
		}
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

func root(i int, tt []int) int {
	if i == tt[i] {
		return i
	}
	tt[i] = root(tt[i], tt)
	return tt[i]
}

