type Point={x:number,y:number};
const r=(a:Point)=>{
  return {x:Math.round(a.x),y:Math.round(a.y)}
}
const mht=(a:Point, b:Point)=>{
  return  Math.round(Math.abs(a.x-b.x)+Math.abs(a.y-b.y));
}
const greedy=(start:Point, goal:Point, K:number):Point=>{
  if(Math.abs(start.x-goal.x)>K){
    const y=start.y;
    const x=start.x+((goal.x>start.x)?K:-K);
    return r({x,y});
  }else{
    const x=goal.x;
    const fromGoal=mht(start, goal)-K;
    const y=goal.y+((goal.y<start.y)?fromGoal:-fromGoal);
    return r({x,y});
  }
}
const findMid=(start:Point, goal:Point, K:number):Point=>{
  return greedy(start, goal, mht(start, goal)/2);
}
const add=(a:Point,b:Point):Point=>{
  return r({x:a.x+b.x,y:a.y+b.y});
}
const twoShot=(start:Point, goal:Point, K:number):Point=>{
  const mid=findMid(start,goal,K);
  const rest=K-mht(start,goal)/2;
  const direction = [{x:rest,y:0},{x:-rest,y:0},{x:0,y:rest},{x:0,y:-rest}];
  const candi = direction.map(d=>add(d,mid));
  return r(candi.filter(p=>mht(p,start)==K&&mht(p,goal)==K)[0]);
}
function Main(_:NormalInput) {
  const K=_.int();
  const [X,Y]=_.ints(2);
  const start={x:0,y:0};
  const goal={x:X,y:Y};
  let ans:Point[]=[];
  if(mht(start,goal)==K){
    ans.push(goal);
  }else if(K%2==0){
    if(mht(start,goal)%2==0){
      let current=start;
      while(mht(current,goal)>2*K){
        current=greedy(current, goal,K);
        ans.push(current);
      }
      ans.push(twoShot(current, goal, K));
      ans.push(goal);
    }else{
      console.log(-1);return;
    }
  }else{//K is odd
    let current=start;
    throw 0;
    while(mht(current,goal)>2*K || mht(current,goal)%2!=0){
      current=greedy(current, goal,K);
      ans.push(current);
    }
    ans.push(twoShot(current, goal, K));
    ans.push(goal);
  }
  console.log(ans.length);
