void main()
{
    immutable int INF = 10 ^^ 9 + 7;

    auto s = readln.chomp;
    auto t = readln.chomp;

    auto need = (s.length + t.length - 1 + s.length - 1) / s.length;

    debug { need.writeln; }

    auto multis = s.repeat(need).join;

    debug { multis.writeln; }

    auto bmFinder = boyerMooreFinder(t);
    auto ok = new bool[multis.length];
    string ns = multis;
    while (!(ns = bmFinder.beFound(ns)).empty()) {
        ok[multis.length - ns.length] = true;
        debug { ns.writeln; }
        ns = ns[1 .. $];
    }

    debug { ok.writeln; }

