def contain(a, b):
    """Checks that string a contains string b"""
    B = 10 ** 9 + 7

    # Length
    al = len(a)
    bl = len(b)
    if al < bl:
        return []

    # Calculate B^bl
    t = B ** bl

    # First hash
    ah = 0
    bh = 0
    for i in range(bl):
        ah = ah * B + ord(a[i])
        bh = bh * B + ord(b[i])

    # Roll
    indices = []
    for i in range(al - bl + 1):
        if ah == bh:
            indices.append(i)

        if i < al - bl:
            ah = ah * B + ord(a[i + bl]) - ord(a[i]) * t

    return indices


