        }
        if(is_period) {
            s_period = min(s_period, i);
        }
        is_period = true;
        for(int j=0;j<n;++j) {
            if(s[j] != s[j%(n/i)]) {
                is_period = false;
                break;
            }
        }
        if(is_period) {
            s_period = min(s_period, n/i);
        }
    }
    return s_period;
}

bool is_inf(string s, string t, int n, int m) {
    int s_period = calc_period(s, n), t_period = calc_period(t, m);
    if(s_period == t_period) {
        bool are_same = true;
        for(int i=0;i<s_period;++i) {
            if(s[i] != t[i]) {
                are_same = false;
            }
        }
        if(are_same) return true;
    }
    return false;
}

