from fractions import gcd


def larger_divisor(n):
    ret = set()
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            ret.add(n // i)
    return sorted(ret)


def rolling_hash(s, MASK):
    ret = []
    tmp = 0
    for c in s:
        tmp = (tmp * 26 + ord(c) - 97) & MASK
        ret.append(tmp)
    return ret


def solve(s, t):
    MASK = (1 << 63) - 1
    ls, lt = len(s), len(t)
    rs, rt = rolling_hash(s, MASK), rolling_hash(t, MASK)
    rt.append(0)
    for g in larger_divisor(gcd(ls, lt)):
        u = rs[g - 1]
        p = pow(26, g, MASK + 1)
        if all((rs[i + g - 1] - rs[i - 1] * p) & MASK == u for i in range(g, ls, g)) \
                and all((rt[i + g - 1] - rt[i - 1] * p) & MASK == u for i in range(0, lt, g)):
            return -1

    se = s
    if ls < lt:
        k = (lt - 1) // ls + 1
        se *= k
    se *= 3
    ss = se.split(t)

    if len(ss) == 1:
        return 0

    if ss[0] != '' and ss[-1] != '' and all(sc == '' for sc in ss[1:-1]):
        return solve(s[len(ss[0]):] + s[:len(ss[0])], t)

    c = -1
    ans = 0
    for sp in ss:
        if sp == '':
            c += 1
        else:
            ans = max(ans, c + 1)
            c = 0
    ans = max(ans, c)
    return ans


