class KMP:
    def partial(self, P):
        ret = [0]
        for i in range(1, len(P)):
            j = ret[i - 1]
            while j > 0 and P[j] != P[i]:
                j = ret[j - 1]
            ret.append(j + 1 if P[j] == P[i] else j)
        return ret

    def search(self, S, P):
        partial, ret, j = self.partial(P), [], 0        
        for i in range(len(S)):
            while j > 0 and S[i] != P[j]:
                j = partial[j - 1]
            if S[i] == P[j]: j += 1
            if j == len(P): 
                ret.append(i - (j - 1))
                j = partial[j - 1]
        return ret

