class UnionFind:
	def __init__(self, n):
		self.par = [i for i in range(n + 1)]
		self.rank = [0] * (n + 1)
		self.size = [1] * (n + 1)
		self.judge = "No"

	def find(self, x):
		if self.par[x] == x:
			return x
		else:
			self.par[x] = self.find(self.par[x])
			return self.par[x]

	def same_check(self, x, y):
		return self.find(x) == self.find(y)

	def union(self, x, y):
		x = self.find(x); y = self.find(y)
		if self.rank[x] < self.rank[y]:
			if self.same_check(x, y) != True:
				self.size[y] += self.size[x]
				self.size[x] = 0
			else:
				self.judge = "Yes"
			self.par[x] = y
		else:
			if self.same_check(x, y) != True:
				self.size[x] += self.size[y]
				self.size[y] = 0
			else:
				self.judge = "Yes"
			self.par[y] = x
			if self.rank[x] == self.rank[y]:
				self.rank[x] += 1

	def siz(self, x):
		x = self.find(x)
		return self.size[x]

#Nの文字からなる文字列AのM文字のハッシュ値を計算
def rollingHash(N, M, A):
	mul1 = 1; mul2 = 1
	for i in range(M):
		mul1 = (mul1 * base1) % mod1
		mul2 = (mul2 * base2) % mod2

	val1 = 0; val2 = 0
	for i in range(M):
		val1 = val1 * base1 + A[i]
		val1 %= mod1
		val2 = val2 * base2 + A[i]
		val2 %= mod2

	hashList1 = [None] * (N - M + 1)
	hashList1[0] = val1
	hashList2 = [None] * (N - M + 1)
	hashList2[0] = val2

	for i in range(N - M):
		val1 = (val1 * base1 - A[i] * mul1 + A[i + M]) % mod1
		val2 = (val2 * base2 - A[i] * mul2 + A[i + M]) % mod2
		hashList1[i + 1] = val1
		hashList2[i + 1] = val2

	return hashList1, hashList2


