    let mut uft = UnionFindTree::new(b_org.len());
    for i in 0..b_org.len() {
        let j = (i + a.len()) % b_org.len();
        if matched[i] && matched[j] {
            if uft.same(i, j) {
                println!("-1");
                return;
            }
            uft.unite(i, j);
        }
    }

    let max_size = (0..b_org.len())
        .map(|x| if matched[x] { uft.get_size(x) } else { 0 })
        .max()
        .unwrap();
    if max_size == b_org.len() {
        println!("{}", -1);
    } else {
        println!("{}", max_size);
    }
}

