pub type RollingHashBase = u64;
mod rolling_hash_internal {
    use super::RollingHashBase;
    pub const ROLL: RollingHashBase = 1154491469;
    pub const MOD: RollingHashBase = 4290357497;
    pub fn pow(base: RollingHashBase, exp: RollingHashBase) -> RollingHashBase {
        if exp == 0 {
            1
        } else {
            let pow_half = pow(base, exp / 2);
            if exp % 2 == 0 {
                (pow_half * pow_half) % MOD
            } else {
                (base * pow_half % MOD) * pow_half % MOD
            }
        }
    }
}
pub trait RollingHash {
    fn rolling_hash(&self) -> RollingHashValue<Self>;
    fn prefix_rolling_hash(&self) -> PrefixRollingHash<Self>;
}
impl RollingHash for [u8] {
    fn rolling_hash(&self) -> RollingHashValue<[u8]> {
        use self::rolling_hash_internal::*;
        let value = self.iter().fold(0u64, |acc, &next| {
            (acc * ROLL + next as RollingHashBase) % MOD
        });
        RollingHashValue {
            len: self.len(),
            value: value,
            seq_type: std::marker::PhantomData,
        }
    }
    fn prefix_rolling_hash(&self) -> PrefixRollingHash<[u8]> {
        use self::rolling_hash_internal::*;
        let prefix_hash = self
            .iter()
            .lscan(0 as RollingHashBase, |&acc, &next| {
                (acc * ROLL + next as RollingHashBase) % MOD
            })
            .collect();
        PrefixRollingHash {
            prefix_hash: prefix_hash,
            seq_type: std::marker::PhantomData,
        }
    }
}
pub struct RollingHashValue<T: ?Sized + RollingHash> {
    len: usize,
    value: RollingHashBase,
    seq_type: std::marker::PhantomData<T>,
}
impl<T: ?Sized + RollingHash> Clone for RollingHashValue<T> {
    fn clone(&self) -> Self {
        RollingHashValue {
            len: self.len,
            value: self.value,
            seq_type: self.seq_type.clone(),
        }
    }
}
impl<T: ?Sized + RollingHash> Copy for RollingHashValue<T> {}
impl<T: ?Sized + RollingHash> RollingHashValue<T> {
    pub fn len(&self) -> usize {
        self.len
    }
    pub fn value(&self) -> RollingHashBase {
        self.value
    }
}
pub struct PrefixRollingHash<T: ?Sized + RollingHash> {
    prefix_hash: Vec<RollingHashBase>,
    seq_type: std::marker::PhantomData<T>,
}
impl<T: ?Sized + RollingHash> PrefixRollingHash<T> {
    pub fn len(&self) -> usize {
        self.prefix_hash.len() - 1
    }
    pub fn matches_at(&self, pattern: RollingHashValue<T>, index: usize) -> Option<bool> {
        use self::rolling_hash_internal::*;
        let hash_right = match self.prefix_hash.get(index + pattern.len()) {
            Some(&hash) => hash,
            None => return None,
        };
        let hash_left = self.prefix_hash[index];
        let m = pow(ROLL, pattern.len() as RollingHashBase);
        Some((hash_right + MOD - (hash_left * m % MOD)) % MOD == pattern.value())
    }
    pub fn matches<'a>(&'a self, pattern: RollingHashValue<T>) -> RollingHashMatches<'a, T> {
        use self::rolling_hash_internal::*;
        RollingHashMatches {
            prefix_hash: self,
            pattern: pattern,
            m: pow(ROLL, pattern.len() as RollingHashBase),
            index: 0,
        }
    }
}
pub struct RollingHashMatches<'a, T: 'a + ?Sized + RollingHash> {
    prefix_hash: &'a PrefixRollingHash<T>,
    pattern: RollingHashValue<T>,
    m: RollingHashBase,
    index: usize,
}
impl<'a, T: ?Sized + RollingHash> Iterator for RollingHashMatches<'a, T> {
    type Item = usize;
    fn next(&mut self) -> Option<usize> {
        use self::rolling_hash_internal::*;
        while let Some(hash_right) = self
            .prefix_hash
            .prefix_hash
            .get(self.index + self.pattern.len())
        {
            let old_index = self.index;
            self.index += 1;
            let hash_left = self.prefix_hash.prefix_hash[old_index];
            let hash = (hash_right + MOD - (hash_left * self.m % MOD)) % MOD;
            if hash == self.pattern.value() {
                return Some(old_index);
            }
        }
        None
    }
}

fn solve(s: &str, t: &str) -> Option<usize> {
    let mut haystack: Vec<u8> = s.bytes().collect();
    haystack.extend(s.bytes());
    while haystack.len() < t.len() * 2 {
        haystack.extend(s.bytes());
    }
    let haystack = haystack.prefix_rolling_hash();
    let needle = t.as_bytes().rolling_hash();

    let mut connectivity: HashUnionFindSets<usize> = (0..s.len()).collect();
    for i in haystack.matches(needle).take_while(|&i| i < s.len()) {
        if !connectivity.unite(&i, &((i + needle.len()) % s.len())).unwrap() {
            return None;
        }
    }

    Some((0..s.len()).map(|i| connectivity.len_of(&i).unwrap() - 1).max().unwrap())
}

fn main() {
    readls!(s = String, t = String);
    match solve(&s, &t) {
        Some(ans) => println!("{}", ans),
        None => println!("-1")
    }
}

pub struct HashUnionFindSets<T: Eq + std::hash::Hash + std::fmt::Debug> {
    set_count: usize,
    items: std::collections::HashMap<T, UnionFindNode<T>>,
}
#[derive(Clone)]
enum UnionFindNodeInner<T: Eq + std::hash::Hash> {
    Root { len: usize },
    Child { parent: UnionFindNode<T> },
}
#[derive(Clone)]
struct UnionFindNode<T: Eq + std::hash::Hash>(
    std::rc::Rc<std::cell::RefCell<UnionFindNodeInner<T>>>,
    T,
);
impl<T: Eq + std::hash::Hash + Clone> UnionFindNode<T> {
    fn new(item: T) -> UnionFindNode<T> {
        UnionFindNode(
            std::rc::Rc::new(std::cell::RefCell::new(UnionFindNodeInner::Root { len: 1 })),
            item,
        )
    }
}
impl<T: Eq + std::hash::Hash> std::cmp::PartialEq for UnionFindNode<T> {
    fn eq(&self, other: &UnionFindNode<T>) -> bool {
        self.1 == other.1
    }
}
impl<T: Eq + std::hash::Hash> std::cmp::Eq for UnionFindNode<T> {}
impl<T: Eq + std::hash::Hash> std::hash::Hash for UnionFindNode<T> {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.1.hash(state);
    }
}
impl<T: Eq + std::hash::Hash + std::fmt::Debug + Clone> HashUnionFindSets<T> {
    pub fn new() -> HashUnionFindSets<T> {
        HashUnionFindSets {
            set_count: 0,
            items: std::collections::HashMap::new(),
        }
    }
    fn error_msg(items: &[&T]) -> String {
        assert!(items.len() == 1 || items.len() == 2);
        if items.len() == 1 {
            format!("no set contains {:?}", items[0])
        } else {
            format!(
                "no set contains {:?} and no set contains {:?}",
                items[0], items[1]
            )
        }
    }
    pub fn add(&mut self, item: T) -> bool {
        if self.items.contains_key(&item) {
            false
        } else {
            self.set_count += 1;
            self.items.insert(item.clone(), UnionFindNode::new(item));
            true
        }
    }
    pub fn items_len(&self) -> usize {
        self.items.len()
    }
    fn find(&self, item: &T) -> Option<(UnionFindNode<T>, usize)> {
        fn go<T: Eq + std::hash::Hash + Clone>(
            node: UnionFindNode<T>,
        ) -> (UnionFindNode<T>, usize) {
            let inner = node.0.as_ref().clone().into_inner();
            match inner {
                UnionFindNodeInner::Root { len } => (node, len),
                UnionFindNodeInner::Child { parent } => {
                    let (root, len) = go(parent);
                    let mut borrowed = node.0.borrow_mut();
                    *borrowed = UnionFindNodeInner::Child {
                        parent: root.clone(),
                    };
                    (root, len)
                }
            }
        }
        self.items.get(item).cloned().map(go)
    }
    pub fn count(&self) -> usize {
        self.set_count
    }
    pub fn len_of(&self, item: &T) -> Result<usize, String> {
        self.find(item)
            .map(|(_, len)| len)
            .ok_or_else(|| HashUnionFindSets::error_msg(&[item]))
    }
    pub fn set_eq(&self, item1: &T, item2: &T) -> Result<bool, String> {
        match (self.find(item1), self.find(item2)) {
            (Some((root1, _)), Some((root2, _))) => Ok(root1 == root2),
            (Some(_), None) => Err(HashUnionFindSets::error_msg(&[item2])),
            (None, Some(_)) => Err(HashUnionFindSets::error_msg(&[item1])),
            (None, None) => Err(HashUnionFindSets::error_msg(&[item1, item2])),
        }
    }
    pub fn unite(&mut self, item1: &T, item2: &T) -> Result<bool, String> {
        match (self.find(item1), self.find(item2)) {
            (Some((root1, len1)), Some((root2, len2))) => {
                if root1 == root2 {
                    Ok(false)
                } else {
                    self.set_count -= 1;
                    let (mut root, mut child, root_node) = if len1 < len2 {
