// a randomly chosen prime number
const ROLLING_HASH_BASE: u64 = 6414559172302942457;

#[derive(Clone, Copy)]
pub struct RollingHash {
    len: usize,
    hash: u64
}

impl RollingHash {
    fn new(seq: &[u8]) -> RollingHash {
        RollingHash {
            len: seq.len(),
            hash:  seq.iter().fold(0u64, |acc, &next| {
                acc.wrapping_mul(ROLLING_HASH_BASE).wrapping_add(next as u64)
            })
        }
    }

    fn len(&self) -> usize {
        self.len
    }
}

pub struct PrefixRollingHash {
    prefix_hash: Vec<u64>
}

impl PrefixRollingHash {
    fn pow(base: u64, exp: u64) -> u64 {
        if exp == 0 { 1 } else {
            let pow_half = PrefixRollingHash::pow(base, exp/2);
            if exp % 2 == 0 {
                pow_half.wrapping_mul(pow_half)
            } else {
                base.wrapping_mul(pow_half.wrapping_mul(pow_half))
            }
        }
    }

    pub fn new(seq: &[u8]) -> PrefixRollingHash {
        PrefixRollingHash {
            prefix_hash: seq.iter().lscan(0u64, |&acc, &next| {
                acc.wrapping_mul(ROLLING_HASH_BASE).wrapping_add(next as u64)
            }).collect()
        }
    }

    pub fn len(&self) -> usize {
        self.prefix_hash.len() - 1
    }

    pub fn matches_at(&self, pattern: RollingHash, index: usize) -> Option<bool> {
        let hash_right = match self.prefix_hash.get(index + pattern.len) {
            Some(&hash) => hash,
            None => return None
        };
        // Length of `self.prefix_hash` is longer than `index + pattern.len`,
        // so the indexing never panics.
        let hash_left = self.prefix_hash[index];

        let m = PrefixRollingHash::pow(ROLLING_HASH_BASE, pattern.len as u64);
        Some(hash_right.wrapping_sub(hash_left.wrapping_mul(m)) == pattern.hash)
    }
}

fn solve(s: &str, t: &str) -> Option<usize> {
    let mut heystack: Vec<u8> = s.bytes().collect();
    heystack.extend(s.bytes());
    while heystack.len() < t.len() * 2 {
        heystack.extend(s.bytes());
    }
    let needle = RollingHash::new(&t.bytes().collect::<Vec<_>>());

    let hash = PrefixRollingHash::new(&heystack);
    let mut connectivity: HashUnionFindSets<usize> = (0..s.len()).collect();
    for i in 0..s.len() {
        if hash.matches_at(needle, i).unwrap() {
            if !connectivity.unite(&i, &((i + needle.len()) % s.len())).unwrap() {
                return None;
            }
        }
    }

    Some((0..s.len()).map(|i| connectivity.len_of(&i).unwrap() - 1).max().unwrap())
}

