pub struct UnionFind {
    parents: Vec<isize>,
}
use std::collections::HashMap;
impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        let parents = vec![-1; n];
        UnionFind { parents: parents }
    }
    pub fn find(&mut self, x: usize) -> usize {
        if self.parents[x] < 0 {
            x
        } else {
            let xx = self.parents[x] as usize;
            let y = self.find(xx);
            self.parents[x] = y as isize;
            y
        }
    }
    pub fn unite(&mut self, x: usize, y: usize) -> bool {
        use std::mem::swap;
        let mut x = self.find(x);
        let mut y = self.find(y);
        if x == y {
            return false;
        }
        if self.parents[x] > self.parents[y] {
            swap(&mut x, &mut y);
        }
        self.parents[x] += self.parents[y];
        self.parents[y] = x as isize;
        true
    }
    pub fn size(&mut self, x: usize) -> usize {
        let x = self.find(x);
        (-self.parents[x]) as usize
    }
    pub fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
    pub fn members(&mut self, x: usize) -> Vec<usize> {
        let root = self.find(x);
        (0..self.parents.len())
            .into_iter()
            .filter(|i| self.find(*i) == root)
            .collect::<Vec<usize>>()
    }
    pub fn roots(&mut self) -> Vec<usize> {
        (0..self.parents.len())
            .into_iter()
            .filter(|i| self.parents[*i] < 0)
            .collect::<Vec<usize>>()
    }
    pub fn all_group_members(&mut self) -> HashMap<usize, Vec<usize>> {
        let mut groups_map = HashMap::new();
        for x in 0..self.parents.len() {
            let r = self.find(x);
            groups_map.entry(r).or_insert(vec![]).push(x);
        }
        groups_map
    }
}
#[derive(Debug)]
pub struct KnuthMorrisPratt<T: Eq> {
    pattern: Vec<T>,
    table: Vec<usize>,
}
impl<T: Eq> KnuthMorrisPratt<T> {
    pub fn new(pattern: Vec<T>) -> KnuthMorrisPratt<T> {
        let mut table = vec![0; pattern.len() + 1];
        for i in 1..pattern.len() {
            let mut j = table[i - 1];
            while j > 0 && pattern[i] != pattern[j] {
                j = table[j - 1];
            }
            table[i] = j + (pattern[i] == pattern[j]) as usize;
        }
        KnuthMorrisPratt {
            pattern: pattern,
            table: table,
        }
    }
    pub fn search_all(&self, s: &Vec<T>) -> Vec<usize> {
        let mut res = vec![];
        let mut j = 0;
        for i in 0..s.len() {
            while j > 0 && s[i] != self.pattern[j] {
                j = self.table[j - 1];
            }
            if s[i] == self.pattern[j] {
                j += 1;
            }
            if j == self.pattern.len() {
                res.push(i - (j - 1));
                j = self.table[j - 1];
            }
        }
        res
    }
}
