fn main() {
    let s: String = input();
    let t: String = input();

    let slen = s.len();
    let tlen = t.len();
    let mut u = t.clone();
    while u.len() < slen + 2 * tlen {
        u.push_str(&s);
    }

    let rh = RollingHash::new(&u);
    let mut succ = vec![slen; slen];
    let mut pred = vec![0; slen];
    for i in 0..slen {
        if rh.is_same(0, tlen, tlen + i, 2 * tlen + i) {
            let j = (i + tlen) % slen;
            succ[i] = j;
            pred[j] += 1;
        }
    }

    let mut dist = vec![-1; slen];
    let mut q = std::collections::VecDeque::new();
    for i in 0..slen {
        if pred[i] == 0 {
            dist[i] = 0;
            q.push_back(i);
        }
    }
    while let Some(i) = q.pop_front() {
        if succ[i] == slen {
            continue;
        }
        let j = succ[i];
        pred[j] -= 1;
        dist[j] = dist[i] + 1;
        if pred[j] == 0 {
            q.push_back(j);
        }
    }

    let mut ok = true;
    let mut ans = 0;
    for i in 0..slen {
        if dist[i] < 0 {
            ok = false;
            break;
        }
        ans = std::cmp::max(ans, dist[i]);
    }

    println!("{}", if ok { ans } else { -1 });
}

struct RollingHash {
    hash: Vec<Vec<i64>>,
    power: Vec<Vec<i64>>,
}

impl RollingHash {
    fn modulus() -> &'static [i64] {
        &[1000000007, 1000000009, 1234567891]
    }

    fn radix() -> &'static [i64] {
        &[1007, 1009, 1013]
    }

    fn new<S: AsRef<str>>(s: S) -> RollingHash {
        let s = s.as_ref().as_bytes();
        let m = RollingHash::modulus();
        let r = RollingHash::radix();
        let n = s.len();
        let mut h = vec![vec![0; n + 1]; m.len()];
        let mut p = vec![vec![0; n + 1]; m.len()];
        for i in 0..m.len() {
            h[i][0] = 0;
            p[i][0] = 1;
            for j in 0..n {
                h[i][j + 1] = (h[i][j] * r[i] + s[j] as i64) % m[i];
                p[i][j + 1] = p[i][j] * r[i] % m[i];
            }
        }
        RollingHash { hash: h, power: p }
    }

    fn hash(&self, i: usize, start: usize, end: usize) -> i64 {
        let m = RollingHash::modulus();
        let mut r = self.hash[i][end] - self.hash[i][start] * self.power[i][end - start] % m[i];
        if r < 0 {
            r += m[i];
        }
        r
    }

    fn is_same(&self, start1: usize, end1: usize, start2: usize, end2: usize) -> bool {
        if end1 - start1 != end2 - start2 {
            false
        } else {
            let mlen = RollingHash::modulus().len();
            let mut ok = true;
            for i in 0..mlen {
                if self.hash(i, start1, end1) != self.hash(i, start2, end2) {
                    ok = false;
                }
            }
            ok
        }
    }
}

