pub fn zalgo(s: &Vec<char>) -> Vec<usize> {
    let n = s.len();
    let mut a = vec![0usize; n];
    let mut from = 0;
    let mut last = 0;
    a[0] = n;
    for i in 1..n {
        let mut same = a[i];
        if from != 0 {
            same = std::cmp::min(a[i - from], if last > i { last - i } else { 0 });
        }
        while i + same < n && s[same] == s[same + i] {
            same += 1;
        }
        if last < i + same {
            last = i + same;
            from = i;
        }
        a[i] = same;
    }
    return a;
}
fn kmp(s: &Vec<char>) -> Vec<usize> {
    let n = s.len();
    let mut i = 0;
    let mut j = -1;
    let mut a = vec![!0; n + 1];
    while i < n {
        while (!j != 0 && s[i] != s[j as usize]) {
            j = a[j as usize] as i64;
        }
        a[i + 1] = (j + 1) as usize;
        i += 1;
        j += 1;
    }
    a
}
fn con(s: &Vec<char>) -> &[char] {
    let kmp = kmp(s);
    let c = s.len() - kmp[s.len()];
    if s.len() % c == 0 {
        &s[0..c]
    } else {
        &s[..]
    }
}

use std::collections::VecDeque;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let s: Vec<_> = sc.read::<String>().bytes().collect();
    let t: Vec<_> = sc.read::<String>().bytes().collect();
    let n_s = s.len();
    let n_t = t.len();

    let mut array = t.clone();
    let n_s = (n_t + n_s - 1) / n_s * n_s;
    while array.len() < n_t + n_s * 2 {
        array.extend(s.clone());
    }

    let z_array = z_algorithm::calc_z_array(&array);
    let mut jump = vec![false; n_s];
    for i in 0..n_s {
        jump[i] = z_array[i + n_t] >= n_t;
    }

    let mut ans = vec![None; n_s];
    let mut q = VecDeque::new();
    for i in 0..n_s {
        if !jump[i] {
            ans[i] = Some(0);
            q.push_back(i);
        }
    }
    if q.is_empty() {
        println!("-1");
        return;
    }

    while let Some(pos) = q.pop_front() {
        let prev = (pos + n_t * n_s - n_t) % n_s;
        if ans[prev].is_some() {
            continue;
        }
        if jump[prev] {
            ans[prev] = Some(ans[pos].unwrap() + 1);
        } else {
            ans[prev] = Some(0);
        }
        q.push_back(prev);
    }

    if ans.contains(&None) {
        println!("-1");
        return;
    }

    let ans = ans.into_iter().map(|ans| ans.unwrap()).max().unwrap();
    println!("{}", ans);
}

pub mod z_algorithm {

    pub fn calc_z_array<T: PartialEq>(s: &[T]) -> Vec<usize> {
        let n = s.len();
        let mut z_array = vec![0; n];

        // [l, r) is a window which matches with prefix of s
        let mut l = 0;
        let mut r = 1;
        for i in 1..n {
            if i >= r {
                l = i;
                r = i + 1;
                while r <= n && s[r - 1 - l] == s[r - 1] {
                    r += 1;
                }
                z_array[i] = r - l - 1;
            } else {
                if z_array[i - l] < r - i {
                    z_array[i] = z_array[i - l];
                } else {
                    l = i;
                    while r <= n && s[r - 1 - l] == s[r - 1] {
                        r += 1;
                    }
                    z_array[i] = r - l - 1;
                }
            }
        }
        z_array[0] = n;
        z_array
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::cmp;
use std::collections::BTreeSet;

const MOD: u64 = 1e9 as u64 + 7;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let s: Vec<u8> = sc.chars().into_iter().map(|c| c as u8).collect();
    let t: Vec<u8> = sc.chars().into_iter().map(|c| c as u8).collect();
    let m = t.len();
    let n = (m + s.len() - 1) / s.len() * s.len();
    let s = {
        let mut result = vec![0; n];
        let size = s.len();
        for i in 0..n {
            result[i] = s[i % size];
        }
        result
    };

    let s_hash = RollingHash::new(&double(&s), MOD);
    let t_hash = RollingHash::new(&t, MOD);
    let mut prefix_set = BTreeSet::new();
    for i in 0..n {
        if s_hash.get_hash(i, i + m) == t_hash.get_hash(0, m) {
            prefix_set.insert(i);
        }
    }

    let mut length = 0;
    let mut used = BTreeSet::new();
    for &prefix in prefix_set.iter() {
        if used.contains(&prefix) {
            continue;
        }
        let mut current = BTreeSet::new();
        let mut cur = prefix;
        current.insert(cur);
        loop {
            if prefix_set.contains(&((cur + m) % n)) {
                cur = (cur + m) % n;
                if current.contains(&cur) {
                    println!("-1");
                    return;
                }
                current.insert(cur);
            } else {
                break;
            }
        }
        let mut cur = prefix;
        loop {
            if prefix_set.contains(&((cur + n - m) % n)) {
                cur = (cur + n - m) % n;
                if current.contains(&cur) {
                    println!("-1");
                    return;
                }
                current.insert(cur);
            } else {
                break;
            }
        }
        length = cmp::max(length, current.len());
        used.extend(current);
    }
    println!("{}", length);
}

fn double<T: Copy>(x: &[T]) -> Vec<T> {
    let mut result = vec![];
    for &e in x.iter() {
        result.push(e);
    }
    for &e in x.iter() {
        result.push(e);
    }
    result
}

pub struct RollingHash {
    hash: Vec<u64>,
    pow: Vec<u64>,
}

impl RollingHash {
    pub fn new(s: &[u8], base: u64) -> RollingHash {
        let n = s.len();
        let mut hash: Vec<u64> = vec![0; n + 1];
        let mut pow: Vec<u64> = vec![0; n + 1];
        pow[0] = 1;
        for i in 0..n {
            pow[i + 1] = pow[i].wrapping_mul(base);
            hash[i + 1] = hash[i].wrapping_mul(base).wrapping_add(s[i] as u64);
        }
        RollingHash {
            hash: hash,
            pow: pow,
        }
    }

    /// Get hash of [l, r)
    pub fn get_hash(&self, l: usize, r: usize) -> u64 {
        self.hash[r].wrapping_sub(self.hash[l].wrapping_mul(self.pow[r - l]))
    }
}

