fn main() {
    let mut s = read::<String>().chars().collect::<Vec<_>>();
    let s_clone = s.clone();
    let t = read::<String>().chars().collect::<Vec<_>>();
    while s.len() < t.len() {
        s.append(&mut s_clone.clone());
    }
    s.append(&mut s.clone());

    let t_len = t.len();
    let mp = MP::new(t);
    let indexes = mp.matched_indexes(&s);

    if indexes.is_empty() {
        println!("0");
        return;
    }

    let n = s.len() / 2;
    let mut flags = vec![false; n];
    for index in indexes {
        if index >= n {
            break;
        }
        flags[index] = true;
    }

    let mut uft = UnionFindTree::new(n);
    for i in 0..n {
        let next_index = (i + t_len) % n;
        if flags[i] && flags[next_index] {
            uft.unite(i, next_index);
        }
    }

    let max_size = (0..n).map(|x| uft.get_size(x)).max().unwrap();
    let ans = max_size;
    if ans == n || ans * t_len == n {
        println!("-1");
        return;
    }
    println!("{}", ans);
}

struct MP<T: std::cmp::PartialEq> {
    pi: Vec<i32>,
    s: Vec<T>,
}

impl<T: std::cmp::PartialEq> MP<T> {
    fn new(s: Vec<T>) -> MP<T> {
        let mut pi = vec![0; s.len() + 1];
        pi[0] = -1;
        let mut j = -1;
        for i in 0..s.len() {
            while j >= 0 && s[i] != s[j as usize] {
                j = pi[j as usize];
            }
            j += 1;
            pi[i + 1] = j;
        }
        MP { pi: pi, s: s }
    }

    fn matched_indexes(&self, t: &Vec<T>) -> Vec<usize> {
        let mut j = 0;
        let mut res = vec![];
        for i in 0..t.len() {
            while j >= 0 && self.s[j as usize] != t[i] {
                j = self.pi[j as usize];
            }
            j += 1;
            if j as usize == self.s.len() {
                res.push(1 + i - j as usize);
                j = self.pi[j as usize];
            }
        }
        res
    }
}

