fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let s: String = scan(tokens);
    let t: String = scan(tokens);
    let mut s = s.into_bytes();
    let t = t.into_bytes();
    let ls = s.len();
    let lt = t.len();
    {
        let mut i = 0;
        while s.len() < ls + lt - 1 {
            let b = s[i];
            s.push(b);
            i += 1;
        }
    }
    let z: Vec<usize> = {
        let mut z = vec![0; lt + 1];
        let mut i = 0;
        let mut j = 1;
        while j < lt {
            if t[i] == t[j] {
                i += 1;
                j += 1;
                z[j] = i;
            } else if i == 0 {
                j += 1;
            } else {
                i = z[i];
            }
        }
        z
    };
    let mut f = vec![false; ls];
    let mut i = 0;
    let mut j = 0;
    while i < s.len() {
        if s[i] == t[j] {
            i += 1;
            j += 1;
            if j == t.len() {
                f[i - t.len()] = true;
                j = z[j];
            }
        } else if j == 0 {
            i += 1;
        } else {
            j = z[j];
        }
    }
    let mut visiting = vec![false; ls];
    let mut dp = vec![None; s.len()];
    fn dfs(
        i: usize,
        ls: usize,
        lt: usize,
        f: &[bool],
        dp: &mut [Option<usize>],
        visiting: &mut [bool],
    ) -> bool {
        if visiting[i] {
            return true;
        }
        if dp[i].is_some() {
            return false;
        }
        if f[i] {
            visiting[i] = true;
            if dfs((i + lt) % ls, ls, lt, f, dp, visiting) {
                return true;
            }
            visiting[i] = false;
            dp[i] = Some(dp[(i + lt) % ls].unwrap() + 1);
            return false;
        } else {
            dp[i] = Some(0);
            return false;
        }
    }
    let mut ans = 0;
    for i in 0..ls {
        if dfs(i, ls, lt, &f, &mut dp, &mut visiting) {
            println!("-1");
            return;
        }
        ans = std::cmp::max(ans, dp[i].unwrap());
    }
    println!("{}", ans);
}

