fn z_algorithm(s: &[char]) -> Vec<usize> {
    let n = s.len();
    let mut prefix = vec![0; n];
    prefix[0] = n;
    let mut i = 1;
    let mut j = 0;
    while i < n {
        while i + j < n && s[j] == s[i + j] {
            j += 1;
        }
        prefix[i] = j;
        if j == 0 {
            i += 1;
            continue;
        }
        let mut k = 1;
        while i + k < n && k + prefix[k] < j {
            prefix[i + k] = prefix[k];
            k += 1;
        }
        i += k;
        j -= k;
    }
    prefix
}

#[derive(Debug)]
pub struct UnionFind {
    par: Vec<usize>,
    size: Vec<usize>,
}
impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        let mut vec = vec![0; n];
        for i in 0..n {
            vec[i] = i;
        }
        UnionFind { par: vec, size: vec![1; n] }
    }
    pub fn find(&mut self, x: usize) -> usize {
        if x == self.par[x] {
            x
        } else {
            let par = self.par[x];
            let res = self.find(par);
            self.par[x] = res;
            res
        }
    }
    pub fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }
    pub fn unite(&mut self, a: usize, b: usize) {
        let apar = self.find(a);
        let bpar = self.find(b);
        if apar != bpar {
            self.size[bpar] += self.size[apar];
        }
        self.par[apar] = bpar;
    }
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      s: chars,
      t: chars,
    }
    let mut ss = s.clone();
    ss.extend( s.clone() );
    while ss.len() <= t.len() * 2 {
        ss.extend(s.clone());
    }

    let mut temp = t.clone();
    temp.push('$');
    temp.extend(ss.clone());
    let z_array = z_algorithm(&temp);

    let n = s.len();
    let mut uf = UnionFind::new(n);
    let mut seen = std::collections::HashSet::new();
    for i in 0..ss.len() {
        let p = z_array[ i + t.len() + 1];
        if p == t.len() {
            let ni = i%n;
            if !seen.contains(&ni) {
                let nx = (i+t.len())%n;
                if uf.same(ni, nx) {
                    return puts!("{}\n", -1);
                }
                uf.unite(ni, nx);
                seen.insert(ni);
            }
        }
    }

    let mut ans = 1;
    for i in 0..n {
        ans = max(ans, uf.size[i]);
    }
    puts!("{}\n", ans-1);
}

