#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RollingHashValue(u64);

impl RollingHashValue {
    pub fn new(x: u64) -> RollingHashValue {
        RollingHashValue(x)
    }
    pub fn new_with_mod(x: u64) -> RollingHashValue {
        let m = (1 << 61) - 1;
        let xu = x >> 61;
        let xd = x & m;
        let res = xu + xd;
        RollingHashValue(if res >= m { res - m } else { res })
    }
}

impl Add for RollingHashValue {
    type Output = RollingHashValue;
    fn add(self, rhs: RollingHashValue) -> RollingHashValue {
        RollingHashValue((self.0 + rhs.0) % ((1 << 61) - 1))
    }
}

impl Sub for RollingHashValue {
    type Output = RollingHashValue;
    fn sub(self, rhs: RollingHashValue) -> RollingHashValue {
        let m = (1 << 61) - 1;
        RollingHashValue((self.0 + m - rhs.0) % m)
    }
}

impl Mul for RollingHashValue {
    type Output = RollingHashValue;
    fn mul(self, rhs: RollingHashValue) -> RollingHashValue {
        let x = self.0;
        let y = rhs.0;
        let (xu, xd) = (x >> 31, x & ((1 << 31) - 1));
        let (yu, yd) = (y >> 31, y & ((1 << 31) - 1));
        let zm = xd * yu + xu * yd;
        let zu = zm >> 30;
        let zd = zm & ((1 << 30) - 1);
        RollingHashValue::new_with_mod(xu * yu * 2 + zu + (zd << 31) + xd * yd)
    }
}

pub struct RollingHash {
    hash: Vec<RollingHashValue>,
    pows: Vec<RollingHashValue>,
}

impl RollingHash {
    pub fn new(s: &Vec<char>, base: u64) -> RollingHash {
        let n = s.len();
        let base = RollingHashValue::new_with_mod(base);
        let mut pows = vec![RollingHashValue::new(1)];
        for i in 0..n {
            let t = pows[i] * base;
            pows.push(t);
        }
        let mut hash = vec![RollingHashValue::new(0)];
        for i in 0..n {
            let t = hash[i] * base + RollingHashValue::new(s[i] as u64);
            hash.push(t);
        }
        RollingHash { hash, pows }
    }
    pub fn get(&self, i: usize, k: usize) -> RollingHashValue {
        let res = self.hash[k] - self.hash[i] * self.pows[k - i];
        // eprintln!("l = {}, r = {}, res = {:?}", i, k, res);
        res
    }
}

fn main() {
    input! {
        s: chars,
        t: chars,
    }
    let s_len = s.len();
    let mut s = s;
    while s.len() == s_len || s.len() < t.len() * 2 {
        for i in 0..s.len() {
            s.push(s[i]);
        }
    }
    let base = 128379174;
    let s_rh = RollingHash::new(&s, base);
    let t_rh = RollingHash::new(&t, base);
    let n = t.len();
    let key = t_rh.get(0, n);
    // eprintln!("key = {:?}", key);
    let mut xs = vec![0; s_len];
    let mut next_id = 1;
    for i in 0..s_len {
        // eprintln!("loop: i = {}", i);
        if xs[i] != 0 {
            continue;
        }
        xs[i] = next_id;
        let mut k = i;
        while s_rh.get(k, k + n) == key {
            if xs[(k + n) % s_len] == next_id {
                println!("-1");
                return;
            }
            k = (k + n) % s_len;
            // eprintln!("i = {}, k = {}, next_id = {} (1)", i, k, next_id);
            xs[k] = next_id;
        }
        let mut k = i + s.len() / 2;
        while s_rh.get(k - n, k) == key {
            if xs[(k - n) % s_len] == next_id {
                println!("-1");
                return;
            }
            k = (k - n) % s_len + s.len() / 2;
            // eprintln!("i = {}, k = {}, next_id = {} (2)", i, k % s_len, next_id);
            xs[k % s_len] = next_id;
        }
        next_id += 1;
    }
    // eprintln!("xs = {:?}", xs);
    let mut count = vec![0; s_len + 1];
    for &x in &xs {
        count[x] += 1;
    }
    let res = count.iter().max().unwrap();
    println!("{}", res - 1);
}

