fn make_table(s: &Vec<char>) -> Vec<i64> {
    let n = s.len();
    let mut t = vec![0; n+1];
    t[0] = -1;

    let mut pos = 0;
    for i in 2..n+1 {
        let prev = s[i-1];
        if prev == s[pos] {
            pos += 1;
            t[i] = pos as i64;
        } else if pos > 0 {
            pos = t[pos] as usize;
        } else {
            pos = 0;
        }
    }
    t
}

