fn make_table(s: &Vec<char>) -> Vec<i64> {
    let n = s.len();
    let mut t = vec![0; n];
    t[0] = -1;

    let mut pos = 0;
    for i in 2..n {
        let prev = s[i-1];
        if prev == s[pos] {
            pos += 1;
            t[i] = pos as i64;
        } else {
            pos = 0;
            t[i] = 0;
        }
    }
    t
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      s: chars,
      t: chars,
    }
    // check if the string contains only one type of letter.
    {
        let mut s = s.clone();
        let mut t = t.clone();
        s.sort();
        s.dedup();
        t.sort();
        t.dedup();
        if s.len() == 1 && t.len() == 1 && s[0] == t[0] {
            return puts!("{}\n", -1);
        }
    }

    let n = s.len();
    let m = t.len();
    let tbl = make_table(&t);

    let mut s_idx = 0;
    let mut ans = 0;
    let mut cur_ans = 0;
    let mut offset = 0;
    let mut partial = vec![false; n];
    while s_idx < n {
        let mut t_idx = offset;
        let mut ok = true;
        while t_idx < m {
            if s[(s_idx + t_idx) % n] != t[t_idx] {
                ok = false;
                break;
            }
            t_idx += 1;
        }
        if ok {
            partial[s_idx] = true;
            cur_ans += 1;
            ans = max(ans, cur_ans);
            s_idx += t_idx;
            offset = 0;
        } else {
            cur_ans = 0;
            s_idx = ((s_idx + t_idx) as i64 - tbl[t_idx]) as usize;
            offset = max(tbl[t_idx], 0) as usize;
        }
    }

    use std::collections::VecDeque;
    let mut q = VecDeque::new();
    let mut cnts = vec![0; n];
    let mut cur = 0;
    let mut infinite = true;
    loop {
        if partial[cur] {
            q.push_back(cur);
            cur += t.len();

            if cur >= n {
                let mut cnt = cnts[cur%n];
                if cnt == 0 {
                    infinite = false;
                }
                while let Some(v) = q.pop_back() {
                    cnt += 1;
                    cnts[v] = cnt;
                }
                break;
            }
        } else {
            infinite = false;
            let mut cnt = 0;
            while let Some(v) = q.pop_back() {
                cnt += 1;
                cnts[v] = cnt;
            }
            cur += 1;
            if cur >= n {
                break;
            }
        }
    }

    if infinite {
        puts!("{}\n", -1);
    } else {
        let ans = cnts.iter().max().unwrap();
        puts!("{}\n", ans);
    }
}

