// https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, [ $t:tt ]) => {{
        let len = read_value!($next, usize);
        (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    }};

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

/*
 * Z algorithm. Calculates an array a[i] = |lcp(s, s[i...|s|])|,
 * where s is the given string.
 * If n = s.length(), the returned array has length n + 1.
 * E.g. z_algorithm("ababa") = {5, 0, 3, 0, 1, 0}
 * Reference: http://snuke.hatenablog.com/entry/2014/12/03/214243
 * Verified by: AtCoder ARC055-C (http://arc055.contest.atcoder.jp/submissions/1061771)
 */
fn z_algorithm(s: &[char]) -> Vec<usize> {
    let n = s.len();
    let mut ret = vec![0; n + 1];
    ret[0] = n;
    let mut i = 1; let mut j = 0;
    while i < n {
        while i + j < n && s[j] == s[i + j] { j += 1; }
        ret[i] = j;
        if j == 0 { i += 1; continue; }
        let mut k = 1;
        while i + k < n && k + ret[k] < j {
            ret[i + k] = ret[k];
            k += 1;
        }
        i += k; j -= k;
    }
    ret
}

fn calc(s: &[char], t: &[char], rep: usize) -> usize {
    let m = s.len();
    let n = t.len();
    let len = rep * max(m, n);
    let mut s_rep = vec![' '; len];
    let mut t_rep = vec![' '; len / n * n];
    for i in 0..len {
        s_rep[i] = s[i % m];
    }
    for i in 0..t_rep.len() {
        t_rep[i] = t[i % n];
    }
    let mut ts = t_rep.clone();
    ts.extend_from_slice(&s_rep);
    let za = z_algorithm(&ts);
    let mut ma = 0;
    for i in t_rep.len()..ts.len() {
        ma = max(za[i], ma);
    }
    ma / n
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        s: chars,
        t: chars,
    }
    let ma2 = calc(&s, &t, 2);
    let ma3 = calc(&s, &t, 3);
    if ma2 != ma3 {
        puts!("-1\n");
    } else {
        puts!("{}\n", ma2);
    }
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let s: String = input();
    let t: String = input();

    let slen = s.len();
    let tlen = t.len();

    let rt = RollingHashString::from_str(&t);
    let mut rs = RollingHashString::new();
    while rs.len() < slen + tlen {
        rs.push_str(&s);
    }

    let mut succ = vec![slen; slen];
    let mut pred = vec![0; slen];
    for i in 0..slen {
        if rs.substr(i, tlen) == rt {
            let j = (i + tlen) % slen;
            succ[i] = j;
            pred[j] += 1;
        }
    }

    let mut dist = vec![-1; slen];
    let mut q = std::collections::VecDeque::new();
    for i in 0..slen {
        if pred[i] == 0 {
            dist[i] = 0;
            q.push_back(i);
        }
    }
    while let Some(i) = q.pop_front() {
        if succ[i] == slen {
            continue;
        }
        let j = succ[i];
        pred[j] -= 1;
        dist[j] = dist[i] + 1;
        if pred[j] == 0 {
            q.push_back(j);
        }
    }

    let mut ok = true;
    let mut ans = 0;
    for i in 0..slen {
        if dist[i] < 0 {
            ok = false;
            break;
        }
        ans = std::cmp::max(ans, dist[i]);
    }

    println!("{}", if ok { ans } else { -1 });
}

struct RollingHashString {
    inner: String,
    hasher: Box<[RollingHasher]>,
}

struct RollingHashSubstring<'a> {
    inner: &'a str,
    hash: Box<[u64]>,
}

impl RollingHashString {
    fn hasher() -> Box<[RollingHasher]> {
        Box::new([
            RollingHasher::new(997, 999999937),
            RollingHasher::new(1000003, 1000000007),
            RollingHasher::new(100000007, 1000000009),
        ])
    }

    fn new() -> RollingHashString {
        RollingHashString {
            inner: String::new(),
            hasher: RollingHashString::hasher(),
        }
    }

    fn from_str(string: &str) -> RollingHashString {
        let mut rs = RollingHashString::new();
        rs.push_str(string);
        rs
    }

    fn push_str(&mut self, string: &str) {
        self.inner.push_str(string);
        for h in self.hasher.iter_mut() {
            std::hash::Hasher::write(h, string.as_bytes());
        }
    }

    fn substr<'a>(&'a self, start: usize, length: usize) -> RollingHashSubstring<'a> {
        RollingHashSubstring {
            inner: &self.inner[start..start + length],
            hash: self
                .hasher
                .iter()
                .map(|h| h.make_hash(start, length))
                .collect::<Vec<_>>()
                .into_boxed_slice(),
        }
    }
}

impl std::fmt::Display for RollingHashString {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        self.inner.fmt(f)
    }
}

impl<'a> std::fmt::Display for RollingHashSubstring<'a> {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        self.inner.fmt(f)
    }
}

impl std::ops::Deref for RollingHashString {
    type Target = str;

    fn deref(&self) -> &str {
        &self.inner
    }
}

impl<'a> std::ops::Deref for RollingHashSubstring<'a> {
    type Target = str;

    fn deref(&self) -> &str {
        self.inner
    }
}

impl PartialEq for RollingHashString {
    fn eq(&self, other: &RollingHashString) -> bool {
        self.substr(0, self.len()).hash == other.substr(0, other.len()).hash
    }
}

impl<'a> PartialEq<RollingHashSubstring<'a>> for RollingHashString {
    fn eq(&self, other: &RollingHashSubstring<'a>) -> bool {
        self.substr(0, self.len()).hash == other.hash
    }
}

impl<'a> PartialEq<RollingHashString> for RollingHashSubstring<'a> {
    fn eq(&self, other: &RollingHashString) -> bool {
        self.hash == other.substr(0, other.len()).hash
    }
}

impl<'a> PartialEq for RollingHashSubstring<'a> {
    fn eq(&self, other: &RollingHashSubstring<'a>) -> bool {
        self.hash == other.hash
    }
}

impl Eq for RollingHashString {}
impl<'a> Eq for RollingHashSubstring<'a> {}

struct RollingHasher {
    radix: u64,
    modulus: u64,
    hash: Vec<u64>,
    pow: Vec<u64>,
}

impl RollingHasher {
    fn new(radix: u64, modulus: u64) -> RollingHasher {
        RollingHasher {
            radix: radix,
            modulus: modulus,
            hash: vec![0],
            pow: vec![1],
        }
    }

    fn make_hash(&self, start: usize, length: usize) -> u64 {
        let mut h = self.hash[start + length] + self.modulus
            - self.hash[start] * self.pow[length] % self.modulus;
        if h > self.modulus {
            h -= self.modulus;
        }
        h
    }
}

impl std::hash::Hasher for RollingHasher {
    fn finish(&self) -> u64 {
        self.hash[self.hash.len() - 1]
    }

    fn write(&mut self, bytes: &[u8]) {
        let n = self.hash.len();
        self.hash.resize(n + bytes.len(), 0);
        self.pow.resize(n + bytes.len(), 0);
        for i in 0..bytes.len() {
            self.hash[n + i] = (self.hash[n + i - 1] * self.radix + bytes[i] as u64) % self.modulus;
            self.pow[n + i] = self.pow[n + i - 1] * self.radix % self.modulus;
        }
    }
}

