    let sl = (2 * tl + s.len() - 1) / s.len() * s.len() * 2;
    let mut ss = vec![' '; sl];
    for i in 0..sl {
        ss[i] = s[i%s.len()];
    }

    let mut zs = vec![];
    zs.append(&mut t.clone());
    zs.push('@');
    zs.append(&mut ss.clone());
    // println!("{:?}", zs);

    let zi = z(&zs);
    let mut next = vec![false; sl];
    let mut prev = vec![false; sl];
    let mut nodes = 0;
    for i in tl+1..zi.len() {
        let si = i-tl-1;
        if zi[i] == tl || (si >= sl/2 && zi[i-sl/2] == tl) {
            next[si] = true;
            prev[(si+tl)%sl] = true;
            nodes += 1;
        }
    }

    let mut ans = 0;
    let mut vlnd = 0;
    for i in 0..sl {
        if !prev[i] && next[i] {
