fn main() {
    input! {
        s: chars,
        t: chars,
    }
    let mut s = s;
    while s.len() < t.len() {
        for i in 0..s.len() {
            let t = s[i];
            s.push(t);
        }
    }
    let base = 128379174;
    let s_rh = RollingHash::new(&s, base);
    let t_rh = RollingHash::new(&t, base);
    let n = t.len();
    let key = t_rh.get(0, n);
    // eprintln!("key = {:?}", key);
    let mut xs = vec![0; s.len()];
    let mut next_id = 1;
    for i in 0..s.len() {
        // eprintln!("loop: i = {}", i);
        if xs[i] != 0 {
            continue;
        }
        xs[i] = next_id;
        let mut k = i;
        while s_rh.right(k, n) == key {
            if xs[(k + n) % s.len()] == next_id {
                println!("-1");
                return;
            }
            k = (k + n) % s.len();
            xs[k] = next_id;
        }
        let mut k = i;
        while s_rh.left(k, n) == key {
            if xs[(k + s.len() - n) % s.len()] == next_id {
                println!("-1");
                return;
            }
            k = (k + s.len() - n) % s.len();
            xs[k] = next_id;
        }
        next_id += 1;
    }
    // eprintln!("xs = {:?}", xs);
    let mut count = vec![0; s.len() + 1];
    for &x in &xs {
        count[x] += 1;
    }
    let res = count.iter().max().unwrap();
    println!("{}", res - 1);
}

