        a: 0,
        b: ss.len() as i64,
    };

    let mut sss = vec![];
    let L = ars.next((ss.len() + tt.len()) as i64);
    for _ in 0..(L / ss.len() as i64) {
        sss.append(&mut ss.clone());
    }

    let M = tt.len();
    let kmp = KMP::new(tt);
    let res = kmp.search(&sss);
    let N = ss.len();
    let mut g = vec![HashSet::new(); N];
    for i in res {
        let i = i % N;
        let j = (i + M) % N;
        g[i].insert(j);
    }

    let cycled = cycle_detection_directed(&g);
    if cycled {
        println!("-1");
        return
    }

    let mut ing = vec![vec![]; N];
    for i in 0..N {
        for &to in &g[i] {
            ing[to].push(i);
        }
    }

    let mut rec = Rec {
        ing: ing,
        dp: vec![None;N],
    };
    let mut maxv = 0;
    for i in 0..N {
        chmax!(maxv, rec.solve(i));
    }
    println!("{}", maxv);
}
struct Rec {
    ing: Vec<Vec<usize>>,
    dp: Vec<Option<usize>>,
}
impl Rec {
    fn solve(&mut self, i: usize) -> usize {
        if self.ing[i].len() == 0 {
            return 0
        }
        if let Some(x) = self.dp[i] {
            return x;
        }
        let mut maxv = 0;
        for j in 0..self.ing[i].len() {
            let from = self.ing[i][j];
            chmax!(maxv, self.solve(from) + 1);
        }
        self.dp[i] = Some(maxv);
        return maxv;
    }
}
pub fn cycle_detection_directed(g: &[HashSet<usize>]) -> bool {
    let n = g.len();
    let mut in_g = vec![HashSet::new(); n];
    for v in 0..n {
        for &u in &g[v] {
            in_g[u].insert(v);
        }
    }
    let mut v_indegree0 = vec![];
    for v in 0..n {
        if in_g[v].len() == 0 {
            v_indegree0.push(v);
        }
    }
    let mut m = 0;
    while let Some(v) = v_indegree0.pop() {
        m += 1;
        for &to in &g[v] {
            if in_g[to].remove(&v) && in_g[to].is_empty() {
                v_indegree0.push(to);
            }
        }
    }
    m != n
}
struct ArithSeq {
    a: i64,
    b: i64,
}
impl ArithSeq {
    #[doc = "a+bi >= x"]
    pub fn next(&self, x: i64) -> i64 {
        if x >= self.a {
            let d = x - self.a;
            let i = (d - 1 + self.b) / self.b;
            self.a + self.b * i
        } else {
            let d = self.a - x;
            let i = d / self.b;
            self.a - self.b * i
        }
    }
    #[doc = "a+bi <= x"]
    pub fn prev(&self, x: i64) -> i64 {
        let next = self.next(x);
        if next == x {
            x
        } else {
            next - self.b
        }
    }
    #[doc = "[a+bi, n] <= [l, u]"]
    pub fn range(&self, l: i64, u: i64) -> Option<(i64, i64)> {
        if l > u {
            return None
        }
        let x = self.next(l);
        let y = self.prev(u);
        if x > y {
            return None
        }
        assert!(x <= y);
        if l<=x && x<=u {
            let cnt = (y-x) / self.b;
            Some((x, cnt+1))
        } else {
            None
        }
    }
}

struct KMP {
    pat: Vec<u64>,
    tbl: Vec<i64>,
}
impl KMP {
    #[doc = "O(K)"]
    fn new(pat: Vec<u64>) -> Self {
        let n = pat.len();
        let mut tbl = vec![0; n + 1];
        tbl[0] = -1;
        let mut j: i64 = -1;
        for i in 0..n {
            while j >= 0 && pat[i] != pat[j as usize] {
                j = tbl[j as usize];
            }
            j += 1;
            if i + 1 < n && pat[i + 1] == pat[j as usize] {
                tbl[i + 1] = tbl[j as usize];
            } else {
                tbl[i + 1] = j;
            }
        }
        KMP { pat: pat, tbl: tbl }
    }
    #[doc = "O(N)"]
    fn search(&self, s: &[u64]) -> Vec<usize> {
        let mut res = vec![];
        let mut head: i64 = 0;
        let mut j: i64 = 0;
        while head + j < s.len() as i64 {
            if self.pat[j as usize] == s[(head + j) as usize] {
                j += 1;
                if j != self.pat.len() as i64 {
                    continue;
                }
                res.push(head as usize);
            }
            head += j - self.tbl[j as usize];
            j = std::cmp::max(self.tbl[j as usize], 0);
        }
        res
    }
}

