use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

const MODS: [i64; 4] = [1000000007i64, 1000000009i64, 997i64, 37582157i64];
const BASES: [i64; 4] = [37582157i64, 1000000007i64, 331i64, 997i64];
fn ok(cnt: usize, s: &Vec<char>, t: &Vec<char>) -> bool {
    'outer_loop: for _iter in 0..4 {
        let m = MODS[_iter];
        let b = BASES[_iter];
        let mut target_hash = 0;
        let mut high = 1;
        for _ in 0..cnt {
            for i in 0..t.len() {
                target_hash = (target_hash * b + t[i] as u8 as i64) % m;
                high = (high * b) % m;
            }
        }
        let len = cnt * t.len();
        let target_hash = target_hash;
        let mut used = 0;
        let mut hash = 0;
        for _ in 0..4 {
            for i in 0..s.len() {
                hash = (hash * b + s[i] as u8 as i64) % m;
                used += 1;
                if used > len {
                    let pos = (i + s.len() * 4 - len) % s.len();
                    hash = (hash - s[pos] as u8 as i64 * high + m * m) % m;
                }
                if used >= len && hash == target_hash {
                    continue 'outer_loop;
                }
            }
        }
        return false;
    }
    return true;
}

fn main() {
    let s = read::<String>().chars().collect::<Vec<char>>();
    let t = read::<String>().chars().collect::<Vec<char>>();
    let mut l = 0;
    let mut r = s.len() * 3 / t.len() + 1;
    if ok(r, &s, &t) {
        println!("-1");
        return;
    }
    while r - l > 1 {
        let mid = (l + r) / 2;
        if ok(mid, &s, &t) {
            l = mid;
        } else {
            r = mid;
        }
    }
    println!("{}", l);
}

use std::collections::VecDeque;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let s: Vec<_> = sc.read::<String>().bytes().collect();
    let t: Vec<_> = sc.read::<String>().bytes().collect();
    let n_s = s.len();
    let n_t = t.len();

    let mut array = t.clone();

    let x = (n_t + n_s - 1) / n_s;
    for _ in 0..x {
        array.extend(s.clone());
    }

    let z_array = z_algorithm::calc_z_array(&array);
    let mut jump = vec![false; n_s];
    for i in 0..n_s {
        jump[i] = z_array[i + n_t] >= n_t;
    }

    let mut ans = vec![None; n_s];
    let mut q = VecDeque::new();
    for i in 0..n_s {
        if !jump[i] {
            ans[i] = Some(0);
            q.push_back(i);
        }
    }
    if q.is_empty() {
        println!("-1");
        return;
    }

    while let Some(pos) = q.pop_front() {
        let prev = (pos + n_t * n_s - n_t) % n_s;
        if ans[prev].is_some() {
            continue;
        }
        if jump[prev] {
            ans[prev] = Some(ans[pos].unwrap() + 1);
        } else {
            ans[prev] = Some(0);
        }
        q.push_back(prev);
    }

    if ans.contains(&None) {
        println!("-1");
        return;
    }

    let ans = ans.into_iter().map(|ans| ans.unwrap()).max().unwrap();
    println!("{}", ans);
}

pub mod z_algorithm {

    pub fn calc_z_array<T: PartialEq>(s: &[T]) -> Vec<usize> {
        let n = s.len();
        let mut z_array = vec![0; n];

        // [l, r) is a window which matches with prefix of s
        let mut l = 0;
        let mut r = 1;
        for i in 1..n {
            if i >= r {
                l = i;
                r = i + 1;
                while r <= n && s[r - 1 - l] == s[r - 1] {
                    r += 1;
                }
                z_array[i] = r - l - 1;
            } else {
                if z_array[i - l] < r - i {
                    z_array[i] = z_array[i - l];
                } else {
                    l = i;
                    while r <= n && s[r - 1 - l] == s[r - 1] {
                        r += 1;
                    }
                    z_array[i] = r - l - 1;
                }
            }
        }
        z_array[0] = n;
        z_array
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

const MODS: [i64; 3] = [1000000007i64, 1000000009i64, 37582157i64];
const BASES: [i64; 3] = [37582157i64, 1000000007i64, 997i64];
fn ok(cnt: usize, s: &Vec<char>, t: &Vec<char>) -> bool {
    'outer_loop: for _iter in 0..3 {
        let m = MODS[_iter];
        let b = BASES[_iter];
        let mut target_hash = 0;
        let mut high = 1;
        for _ in 0..cnt {
            for i in 0..t.len() {
                target_hash = (target_hash * b + t[i] as u8 as i64) % m;
                high = (high * b) % m;
            }
        }
        let len = cnt * t.len();
        let target_hash = target_hash;
        let mut used = 0;
        let mut hash = 0;
        loop {
            for i in 0..s.len() {
                hash = (hash * b + s[i] as u8 as i64) % m;
                used += 1;
                if used > len {
                    let pos = (i + s.len() * len - len) % s.len();
                    hash = (hash - s[pos] as u8 as i64 * high + m * m) % m;
                }
                if used >= len && hash == target_hash {
                    continue 'outer_loop;
                }
            }
            if used >= len * 2 && used >= s.len() * 3 {
                break;
            }
        }
        return false;
    }
    return true;
}

