fn modpow(x:usize, n:usize, p:usize) -> usize{
        let mut ans = 1;
        let mut n = n;
        let mut x = x;
        while(n != 0){
            if (n&1 == 1){ans = ans*x%p;}
            x = x*x%p;
            n = n>>1;
        }
        ans
}
fn comb(a:usize, b:usize,  fac:&Vec<usize>, ifac:&Vec<usize>, p:usize)->usize{
        let mut a = a;
        let mut b = b;
        if a == 0 && b == 0{return 1;}
        if a<b || a<0{return 0;}
        let mut tmp = ifac[a-b]*ifac[b] % p;
        return tmp * fac[a] % p;
}

fn invs(p:usize)->(Vec<usize>, Vec<usize>){
    let mut ma = 3000001;
    let mut fac = vec![0;300001];
    let mut ifac = vec![0;300001];
    fac[0] = 1;
    ifac[0] = 1;
    for i in 0..ma{
        fac[i+1] = fac[i] * (i+1) % p;
        ifac[i+1] = ifac[i] * modpow(i+1, p - 2, p) % p;
    }
    (fac, ifac)
}
fn kmp_make_table(s:&Vec<char>)->Vec<i64>{
    let mut n = s.len();
    let mut ret = vec![0;n+1];
    ret[0] = -1;
    let mut j = -1;
    for i in 0..n{
        while(j>=0 && s[i] != s[j as usize]){
            j = ret[j as usize];
        }
        j+=1;
        ret[i+1] = j;
    }
    return ret;
}
fn kmp(s:&Vec<char>, word:&Vec<char>)->Vec<usize>{
    let mut table = kmp_make_table(word);
    let mut ret = vec![];
    let mut m = 0;
    let mut i = 0;
    let mut n = s.len() as i64;
    while(m+i<n){
        if word[i as usize] == s[m as usize+i as usize]{
            i+=1;
            if i == word.len() as i64{
                ret.push(m as usize);
                m = m+i-table[i as usize];
                i = table[i as usize];
            }
        }
        else{
            m = m+i-table[i as usize];
            if i>0{
                i = table[i as usize];
            }
        }
    }
    return ret;
}
