        if vis[i] {
            continue;
        }
        vis[i] = true;
        if length[i] != n_t {
            continue;
        }
        let mut cur = (i + n_t) % n_s;
        while !vis[cur] {
            vis[cur] = true;
            if length[cur] != n_t {
