// (z[idx] := longest common prefix of ([idx,n), [0,n))
fn z(a: &Vec<char>) -> Vec<usize> {
    let n = a.len();
    let mut z = vec![0; n];
    if n == 0 {
        return z;
    }
    z[0] = n;
    let mut l = 0;
    let mut r = 0;
    for i in 1..n {
        if i > r {
            l = i;
            r = i;
            while r < n && a[r-l] == a[r] {
                r += 1;
            }
            z[i] = r - l;
            r -= 1;
        } else {
            let k = i-l;
            if z[k] < r-i+1 {
                z[i] = z[k];
            } else {
                l = i;
                while r < n && a[r-l] == a[r] {
                    r += 1;
                }
                z[i] = r-l;
                r -= 1;
            }
        }
    }
    z
}

fn main() {
    input! {
        s: chars, t: chars
    };
    let mut s = s;
    let tl = t.len();

    let sl = (2 * tl + s.len() - 1) / s.len() * s.len();
    let mut ss = vec![' '; sl];
    for i in 0..sl {
        ss[i] = s[i%s.len()];
    }

    let mut zs = vec![];
    zs.append(&mut t.clone());
    zs.push('@');
    zs.append(&mut ss.clone());

    let zi = z(&zs);
    let ssl = ss.len();
    let mut next = vec![false; ssl];
    let mut prev = vec![false; ssl];
    let mut nodes = 0;
    for i in tl+1..zi.len() {
        if zi[i] == tl {
            let si = i-tl-1;
            next[si] = true;
            prev[(si+tl)%ssl] = true;
            nodes += 1;
        }
    }

    let mut ans = 0;
    let mut vlnd = 0;
    for i in 0..ssl {
        if !prev[i] && next[i] {
            let mut j = i;
            let mut cnt = 0;
            while next[j] {
                j = (j + tl) % ssl;
                cnt += 1;
                vlnd += 1;
            }
            ans = max(ans, cnt);
        }
    }

    if vlnd < nodes {
        println!("-1")
    } else {
        println!("{}", ans);
    }
}

