fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let s: String = scan(tokens);
    let t: String = scan(tokens);
    let s = s.into_bytes();
    let t = t.into_bytes();
    let z: Vec<usize> = {
        let mut z = vec![0; t.len() + 1];
        let mut i = 0;
        let mut j = 1;
        while j < t.len() {
            if t[i] == t[j] {
                i += 1;
                j += 1;
                z[j] = i;
            } else if i == 0 {
                j += 1;
            } else {
                i = z[i];
            }
        }
        z
    };
    let f: Vec<bool> = {
        let mut f = vec![false; s.len()];
        let mut i = 0;
        let mut j = 0;
        while i < s.len() {
            if s[(i + j) % s.len()] == t[j] {
                j += 1;
                if j == t.len() {
                    f[i] = true;
                    i += j - z[j];
                    j = z[j];
                }
            } else if j == 0 {
                i += 1;
            } else {
                i += j - z[j];
                j = z[j];
            }
        }
        f
    };
    let mut dp = vec![State::Unvisited; s.len()];
    fn dfs(i: usize, ls: usize, lt: usize, f: &[bool], dp: &mut [State]) -> bool {
        match dp[i] {
            State::Unvisited => {
                if f[i] {
                    dp[i] = State::Visiting;
                    if dfs((i + lt) % ls, ls, lt, f, dp) {
                        return true;
                    }
                    dp[i] = State::Visited(dp[(i + lt) % ls].unwrap() + 1);
                } else {
                    dp[i] = State::Visited(0);
                }
                false
            }
            State::Visiting => true,
            State::Visited(_) => false,
        }
    }
    let mut ans = 0;
    for i in 0..s.len() {
        if dfs(i, s.len(), t.len(), &f, &mut dp) {
            println!("-1");
            return;
        }
        ans = std::cmp::max(ans, dp[i].unwrap());
    }
    println!("{}", ans);
}

#[derive(Clone, Copy)]
enum State {
    Unvisited,
    Visiting,
    Visited(usize),
}

impl State {
    fn unwrap(self) -> usize {
        match self {
            State::Visited(n) => n,
            _ => unreachable!(),
        }
    }
}

