            loop {
                let (len, complete) = {
                    let buf2 = self.reader.fill_buf().unwrap();
                    self.buf.extend_from_slice(buf2);
                    let len = buf2.len();
                    (len, buf2[len - 1] <= 0x20)
                };
                self.reader.consume(len);
                if complete {
                    break;
                }
            }
        }
        pub fn next<T: str::FromStr>(&mut self) -> Result<T, T::Err> {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                let mut end = begin;
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return unsafe { str::from_utf8_unchecked(&self.buf[begin..end]) }.parse::<T>();
                } else {
                    self.update_buf();
                }
            }
        }
        pub fn next_line(&mut self) -> String {
            loop {
                let mut begin = self.pos;
                if begin < self.buf.len() && (self.buf[begin] < 0x20) {
                    begin += 1;
                }
                let mut end = begin;
                while end < self.buf.len() && (self.buf[end] >= 0x20) {
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return unsafe { str::from_utf8_unchecked(&self.buf[begin..end]) }.to_string();
                } else {
                    self.update_buf();
                }
            }
        }
        pub fn fast_i64(&mut self) -> i64 {
            loop {
                let mut begin = self.pos;
                while begin < self.buf.len() && (self.buf[begin] <= 0x20) {
                    begin += 1;
                }
                if begin == self.buf.len() {
                    self.update_buf();
                    continue;
                }
                let mut res = 0;
                let (is_positive, mut end) = match self.buf[begin] {
                    b'+' => (true, begin + 1),
                    b'-' => (false, begin + 1),
                    _ => (true, begin),
                };
                while end < self.buf.len() && (self.buf[end] > 0x20) {
                    res = res * 10 + (self.buf[end] as i64 - '0' as i64);
                    end += 1;
                }
                if begin != self.buf.len() {
                    self.pos = end;
                    return if is_positive { res } else { -res };
                } else {
                    self.update_buf();
                }
            }
        }
    }
}

mod rolling_hash {
    // ref: https://qiita.com/keymoon/items/11fac5627672a6d6a9f6
    use std::ops::*;
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct RollingHashValue(u64);

    impl RollingHashValue {
        pub fn new(x: u64) -> RollingHashValue {
            RollingHashValue(x)
        }
        pub fn new_with_mod(x: u64) -> RollingHashValue {
            let m = (1 << 61) - 1;
            let xu = x >> 61;
            let xd = x & m;
            let res = xu + xd;
            RollingHashValue(if res >= m { res - m } else { res })
        }
    }

    impl Add for RollingHashValue {
        type Output = RollingHashValue;
        fn add(self, rhs: RollingHashValue) -> RollingHashValue {
            RollingHashValue((self.0 + rhs.0) % ((1 << 61) - 1))
        }
    }

    impl Sub for RollingHashValue {
        type Output = RollingHashValue;
        fn sub(self, rhs: RollingHashValue) -> RollingHashValue {
            let m = (1 << 61) - 1;
            RollingHashValue((self.0 + m - rhs.0) % m)
        }
    }

    impl Mul for RollingHashValue {
        type Output = RollingHashValue;
        fn mul(self, rhs: RollingHashValue) -> RollingHashValue {
            let x = self.0;
            let y = rhs.0;
            let (xu, xd) = (x >> 31, x & ((1 << 31) - 1));
            let (yu, yd) = (y >> 31, y & ((1 << 31) - 1));
            let zm = xd * yu + xu * yd;
            let zu = zm >> 30;
            let zd = zm & ((1 << 30) - 1);
            RollingHashValue::new_with_mod(xu * yu * 2 + zu + (zd << 31) + xd * yd)
        }
    }

    pub struct RollingHash {
        n: usize,
        hash: Vec<RollingHashValue>,
        pows: Vec<RollingHashValue>,
    }

    impl RollingHash {
        pub fn new(s: &Vec<char>, base: u64) -> RollingHash {
            let n = s.len();
            let base = RollingHashValue::new_with_mod(base);
            let mut pows = vec![RollingHashValue::new(1)];
            for i in 0..n {
                let t = pows[i] * base;
                pows.push(t);
            }
            let mut hash = vec![RollingHashValue::new(0)];
            for i in 0..n {
                let t = hash[i] * base + RollingHashValue::new(s[i] as u64);
                hash.push(t);
            }
            RollingHash {
                n: n,
                hash: hash,
                pows: pows,
            }
        }
        pub fn get(&self, i: usize, k: usize) -> RollingHashValue {
            let res = if i <= k {
                self.hash[k] - self.hash[i] * self.pows[k - i]
            } else {
                (self.hash[self.n] - self.hash[i] * self.pows[self.n - i]) * self.pows[k]
                    + self.hash[k]
            };
            // eprintln!("l = {}, r = {}, res = {:?}", i, k, res);
            res
        }
        pub fn left(&self, i: usize, len: usize) -> RollingHashValue {
            self.get((i + self.n - len) % self.n, i)
        }
        pub fn right(&self, i: usize, len: usize) -> RollingHashValue {
            self.get(i, (i + len) % self.n)
        }
    }
}

