use std::io::Read;

fn z_algorithm(s: &Vec<char>) -> Vec<usize> {
    let n = s.len();
    let mut a = vec![0; n];
    a[0] = n;
    let mut i = 1;
    let mut j = 0;
    while i < n {
        while i + j < n && s[j] == s[i + j] {
            j += 1;
        }
        a[i] = j;
        if j == 0 {
            i += 1;
            continue;
        }
        let mut k = 1;
        while i + k < n && k + a[k] < j {
            a[i + k] = a[k];
            k += 1;
        }
        i += k;
        j -= k;
    }
    a
}

fn calc(x: usize, state: &mut [usize], dp: &mut [usize], z: &[usize], n: usize, m: usize) -> usize {
    if state[x] == 1 {
        return std::usize::MAX / 2;
    }
    if state[x] == 2 {
        return dp[x];
    }
    state[x] = 1;
    dp[x] = if z[x] >= m {
        let next = (x + m) % n;
        calc(next, state, dp, z, n, m) + 1
    } else {
        0
    };
    state[x] = 2;
    return dp[x];
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let s: Vec<char> = it.next().unwrap().chars().collect();
    let t: Vec<char> = it.next().unwrap().chars().collect();
    let mut a = vec![];
    while a.len() < 2 * std::cmp::max(s.len(), t.len()) {
        a.append(&mut s.clone());
    }
    let mut b = t.clone();
    b.push('#');
    b.append(&mut a.clone());
    let z = z_algorithm(&b).split_off(t.len() + 1);
    let n = s.len();
    let m = t.len();
    let mut state = vec![0; n];
    let mut dp = vec![0; n];
    for i in 0..s.len() {
        if state[i] == 2 {
            continue;
        }
        if std::usize::MAX / 2 <= calc(i, &mut state, &mut dp, &z, n, m) {
            println!("-1");
            return;
        }
    }
    let ans = *dp.iter().max().unwrap();
    println!("{}", ans);
}

fn main() {
    run();
}

