    let s: Vec<char> = s.iter().cycle().take(sl + tl - 1).map(|x| *x).collect();
    let mut m = vec![false; sl];
    kmp(&s, &t, &mut m);
    let mut smap: HashMap<usize, ((usize, usize), usize)> = HashMap::new();
    let mut emap: HashMap<usize, ((usize, usize), usize)> = HashMap::new();
    let mut ans: usize = 0;
    for i in 0..sl {
        if m[i] {
            let j = (i + tl) % sl;
            if i == j {
                println!("-1");
                return;
            }
            if let Some(&((ss, _i), l1)) = emap.get(&i) {
                if let Some(&((_j, tt), l2)) = smap.get(&j) {
                    if ss == j && tt == i {
                        println!("-1");
                        return;
                    }
                    smap.remove(&j);
                    emap.remove(&i);
                    smap.insert(ss, ((ss, tt), l1 + l2 + 1));
                    emap.insert(tt, ((ss, tt), l1 + l2 + 1));
                    ans = max(ans, l1 + l2 + 1);
                } else {
                    emap.remove(&i);
                    smap.insert(ss, ((ss, j), l1 + 1));
                    emap.insert(j, ((ss, j), l1 + 1));
                    ans = max(ans, l1 + 1);
                }
            } else {
                if let Some(&((_j, tt), l2)) = smap.get(&j) {
                    smap.remove(&j);
                    smap.insert(i, ((i, tt), l2 + 1));
                    emap.insert(tt, ((i, tt), l2 + 1));
                    ans = max(ans, l2 + 1);
                } else {
                    smap.insert(i, ((i, j), 1));
                    emap.insert(j, ((i, j), 1));
                    ans = max(ans, 1);
                }
            }
        }
    }
    println!("{}", ans);
}

fn kmp(s: &[char], sub: &[char], mat: &mut [bool]) {
    let m = sub.len();
    let mut tab: Vec<usize> = vec![0; m + 1];
    let mut i = 2;
    let mut j = 0;
    while i <= m {
        if sub[i - 1] == sub[j] {
            tab[i] = j + 1;
            i += 1;
            j += 1;
        } else if j > 0 {
            j = tab[j];
        } else {
            i += 1;
        }
    }
    i = 0;
    j = 0;
    while i + j < s.len() {
        if sub[j] == s[i + j] {
            j += 1;
            if j == m {
                mat[i] = true;
                i += j - tab[j];
                j = tab[j];
            }
        } else {
            if j == 0 {
                i += 1;
            } else {
                i += j - tab[j];
                j = tab[j];
            }
        }
    }
}

