    let t: String = input();

    let ns = s.len();
    let nt = t.len();
    let mut u = s.clone();
    while u.len() < ns + nt {
        u.push_str(&s);
    }

    let mut ok = vec![false; ns];
    for i in 0..ns {
        if u[i..i + nt] == t {
            ok[i] = true;
        }
    }

    let mut cycle = false;
    let mut uf = UnionFind::new(ns);
    for i in 0..ns {
        let j = (i + nt) % ns;
        if ok[i] && ok[j] {
            if !uf.union(i, j) {
                cycle = true;
            }
        }
    }

    if cycle {
        println!("-1");
    } else {
        let mut ans = 0;
        for i in 0..ns {
            if ok[i] {
                let i = uf.find(i);
                ans = std::cmp::max(ans, uf.size[i]);
            }
        }
        println!("{}", ans);
    }
}

struct UnionFind {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        UnionFind {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] == x {
            x
        } else {
            let p = self.parent[x];
            self.parent[x] = self.find(p);
            self.parent[x]
        }
    }

    fn union(&mut self, x: usize, y: usize) -> bool {
        let mut x = self.find(x);
        let mut y = self.find(y);
        if x == y {
            false
        } else {
            if self.size[x] < self.size[y] {
                std::mem::swap(&mut x, &mut y);
            }
            self.parent[y] = x;
            self.size[x] += self.size[y];
            true
        }
    }
}

