pub fn zalgo(s: &Vec<char>) -> Vec<usize> {
    let n = s.len();
    let mut a = vec![0usize; n];
    let mut from = 0;
    let mut last = 0;
    a[0] = n;
    for i in 1..n {
        let mut same = a[i];
        if from != 0 {
            same = std::cmp::min(a[i - from], if last > i { last - i } else { 0 });
        }
        while i + same < n && s[same] == s[same + i] {
            same += 1;
        }
        if last < i + same {
            last = i + same;
            from = i;
        }
        a[i] = same;
    }
    return a;
}
fn kmp(s: &Vec<char>) -> Vec<usize> {
    let n = s.len();
    let mut i = 0;
    let mut j = -1;
    let mut a = vec![!0; n + 1];
    while i < n {
        while (!j != 0 && s[i] != s[j as usize]) {
            j = a[j as usize] as i64;
        }
        a[i + 1] = (j + 1) as usize;
        i += 1;
        j += 1;
    }
    a
}
fn con(s: &Vec<char>) -> &[char] {
    let kmp = kmp(s);
    let c = s.len() - kmp[s.len()];
    if s.len() % c == 0 {
        &s[0..c]
    } else {
        &s[..]
    }
}

